}

/** LSP convention: 0-based line, UTF-16 code-unit character. */
export interface Position {
  line: number;
  character: number;
}

export interface Range {
  start: Position;
  end: Position;
}

/** Where the `@@ telelean` block lives. */
export interface SourceLocation {
  file: string;
  range: Range;
  markupVersion: number;
}

export interface LeanBinding {
  binding: 'none' | 'adjacent' | 'pinned';
  /** Lean name `n` of the statement (`abbrev n : Prop := ...`). */
  statement?: string;
  /** Lean name `n.holds` (an axiom for an assumption, a theorem once proved). */
  justification?: string;
  /** M0 addition: source text of the bound declarations, shown in the expanded card. */
  code?: string;
}

export type Cert = 'none' | 'ok' | 'refuted';

export type StatusFlag =
  | 'self-evident'
  | 'unselected-used'
  | 'claimed'
  | 'stale'
  | 'broken'
  | 'depends-on-removed'
  | 'no-rationale'
  | 'signoff-stale'
  | 'definitional-choice'
  | 'existence-commitment';

export type ProofStatus =
  | { kind: 'none' }
  | { kind: 'assumed' }
  | { kind: 'pending-promotion' }
  | { kind: 'conditional'; on: string[] }
  | { kind: 'proved'; footprint: string[] };

