import path from 'node:path';

export interface SandboxProfile {
  /** The real `$HOME`. It is covered by an empty tmpfs inside the sandbox; `HOME` still points at it. */
  readonly home: string;
  /** `~/.elan` (holds the toolchain). Bound read-only. */
  readonly elanHome: string;
  /** The toolchain's `bin/`, put first on `PATH` so nothing resolves through the elan proxies. */
  readonly toolchainBin: string;
  /** The shadow project. Sources read-only; only `<shadow>/.lake` is writable. Also the working directory. */
  readonly shadowDir: string;
  /** The real project's `.lake/packages`, bound read-only at `<shadow>/.lake/packages` (absent: nothing bound). */
  readonly packagesDir?: string | undefined;
  /** Extra paths bound read-only at the same path (e.g. the extractor's directory, a frozen export). */
  readonly roBinds?: readonly string[] | undefined;
  /** Extra paths bound writable at the same path (e.g. the extractor's one-time compile directory). */
  readonly rwBinds?: readonly string[] | undefined;
  /** Paths covered by an empty tmpfs after the shadow is bound (e.g. a real workspace's `.git`). */
  readonly maskPaths?: readonly string[] | undefined;
  /**
   * Create `/root`, `/run/user` and `/var`, which `lake comparator`'s own nested bwrap needs as mount
   * points. Without them every comparator verdict would fail to start (verifier FV-2). Default true;
   * turning it off exists only so a test can show that failure is reported as "could not start".
   */
  readonly allowNestedSandbox?: boolean | undefined;
  /** Environment inside the sandbox, on top of `HOME` and `PATH` (which cannot be overridden). */
  readonly env?: Readonly<Record<string, string>> | undefined;
  /** File descriptor bwrap reports its JSON status on (`child-pid`, `exit-code`). */
  readonly jsonStatusFd?: number | undefined;
}

/** `PATH` inside the sandbox: the toolchain first, then the system. */
export function sandboxPath(toolchainBin: string): string {
  return `${toolchainBin}:/usr/bin:/bin`;
}

const ENV_NAME = /^[A-Za-z_][A-Za-z0-9_]*$/;

function assertAbsolute(what: string, p: string): void {
  if (!path.isAbsolute(p)) throw new TypeError(`${what} must be an absolute path, got ${JSON.stringify(p)}`);
  if (p.includes('\0')) throw new TypeError(`${what} contains a NUL byte`);
}

/**
 * Builds the bwrap arguments (without the `bwrap` executable itself) that run `argv` under the profile.
 *
 * Order matters: bwrap applies mounts in order, so the tmpfs covers come before the binds that punch
 * through them (`~/.elan` lives under the masked `$HOME`; the shadow may live under `/tmp` or `$HOME`).
 */
export function buildBwrapArgs(profile: SandboxProfile, argv: readonly string[]): string[] {
  if (argv.length === 0) throw new TypeError('argv must not be empty');
  assertAbsolute('home', profile.home);
  assertAbsolute('elanHome', profile.elanHome);
  assertAbsolute('toolchainBin', profile.toolchainBin);
  assertAbsolute('shadowDir', profile.shadowDir);
  if (profile.packagesDir !== undefined) assertAbsolute('packagesDir', profile.packagesDir);
  for (const p of profile.roBinds ?? []) assertAbsolute('roBinds entry', p);
  for (const p of profile.rwBinds ?? []) assertAbsolute('rwBinds entry', p);
  for (const p of profile.maskPaths ?? []) assertAbsolute('maskPaths entry', p);

  const shadow = path.resolve(profile.shadowDir);
  const dotLake = path.join(shadow, '.lake');
  const args: string[] = [
    // System, read-only. Merged-/usr layout: /lib, /lib64 and /bin are symlinks into /usr.
    '--ro-bind', '/usr', '/usr',
    '--ro-bind', '/etc', '/etc',
    '--symlink', 'usr/lib', '/lib',
    '--symlink', 'usr/lib64', '/lib64',
    '--symlink', 'usr/bin', '/bin',
    '--proc', '/proc',
    '--dev', '/dev',
    // Fresh, empty filesystems: no host /tmp, no host /run (D-Bus, keyring, Wayland), no host $HOME.
    '--tmpfs', '/tmp',
    '--tmpfs', '/run',
    '--tmpfs', profile.home,
  ];
  if (profile.allowNestedSandbox ?? true) {
    args.push('--dir', '/root', '--dir', '/run/user', '--dir', '/var');
  }
  args.push('--ro-bind', profile.elanHome, profile.elanHome);
  for (const p of profile.roBinds ?? []) args.push('--ro-bind', p, p);
  args.push('--ro-bind', shadow, shadow, '--bind', dotLake, dotLake);
  if (profile.packagesDir !== undefined) {
    args.push('--ro-bind', profile.packagesDir, path.join(dotLake, 'packages'));
  }
  for (const p of profile.rwBinds ?? []) args.push('--bind', p, p);
  for (const p of profile.maskPaths ?? []) args.push('--tmpfs', p);
  args.push(
    '--chdir', shadow,
    '--unshare-all', // user, ipc, pid, net (loopback only), uts, cgroup
    '--die-with-parent',
    '--new-session',
    '--clearenv',
    '--setenv', 'HOME', profile.home,
    '--setenv', 'PATH', sandboxPath(profile.toolchainBin),
  );
  for (const [name, value] of Object.entries(profile.env ?? {})) {
    if (!ENV_NAME.test(name)) throw new TypeError(`invalid environment variable name ${JSON.stringify(name)}`);
    if (name === 'HOME' || name === 'PATH') throw new TypeError(`${name} is fixed by the sandbox profile`);
    args.push('--setenv', name, value);
  }
  if (profile.jsonStatusFd !== undefined) args.push('--json-status-fd', String(profile.jsonStatusFd));
  args.push('--', ...argv);
  return args;
}
/**
 * Gate step G4: `lake comparator` against a frozen challenge, under runLean (03 §8.5, 02 D-26).
 *
 * Freeze (after phase A is signed off):
 *   a copy of the exact snapshot + a generated challenge module declaring `theorem n.holds : n := sorry`
 *   per target (the statement abbrevs are left untouched), built and exported with the toolchain's
 *   `leanexport` into `frozen.ndjson`, all inside the sandbox. The snapshot itself is never written to.
 * Judge (when the agent claims it is finished):
 *   `lake compa

    '-- The frozen statements are left untouched; each target theorem is stated here with `sorry`.',
    ...imports.map((m) => `import ${m}`),
    '',
    ...targets.map((t) => `theorem ${formatDeclName(t.theorem)} : ${formatDeclName(t.statement)} := sorry`),
    '',
  ];
  return lines.join('\n');
}

/** What a frozen challenge pins down; everything comparator needs besides the solution. */
export interface Freeze {
  /** Host path of the NDJSON export of the challenge. */
  readonly exportPath: string;
  readonly challengeModule: string;
  readonly theoremNames: readonly string[];
  readonly permittedAxioms: readonly string[];
  readonly definitionNames: readonly string[];
}

type RunPassthrough = Omit<Partial<RunLeanOptions>, 'shadowDir' | 'argv' | 'stdin' | 'stdoutFile'>;

export interface FreezeOptions {
  /**
   * The approved (phase-A) snapshot. Only read: it is copied into `freezeDir` (with its `.lake/build`,
   * so building the challenge is incremental), and the challenge module goes into the copy.
   */
  readonly snapshotDir: string;
  /**
   * A fresh directory (absent or empty) for that copy. Keeping it apart from the agent's shadow means the
   * generated `sorry` never shows up in the agent's files, its proposal diff or G3's no-sorry scan. The
   * caller may delete it once the export is written.
   */
  readonly freezeDir: string;
  /** Modules the challenge imports, e.g. `['Model']`. */
  readonly imports: readonly string[];
  /** Must belong to one of the project's libraries, e.g. `Model.TeleleanChallenge`. */
  readonly challengeModule: string;
  readonly targets: readonly ChallengeTarget[];
  readonly permittedAxioms: readonly string[];
  readonly definitionNames?: readonly string[];
  /** Host path the export is written to. */
  readonly exportPath: string;
  readonly run?: RunPassthrough;
}

export type FreezeResult =
  | { readonly ok: true; readonly freeze: Freeze; readonly build: RunLeanResult; readonly export: RunLeanResult }
  | {
      readonly ok: false;
      readonly stage: 'build' | 'export';
      readonly detail: string;
      readonly build: RunLeanResult;
      readonly export?: RunLeanResult;
    };

function tail(text: string, n = 12): string {
  return text.trim().split('\n').slice(-n).join('\n');
}

/**
 * Copies the snapshot into `freezeDir`, writes the challenge module into the copy, builds it and exports
 * it, all under runLean. Throws (`ShadowError`, `TypeError`) if the snapshot cannot be copied as a model
 * project or the names are unusable; build and export failures are returned.
 */
export async function freezeChallenge(options: FreezeOptions): Promise<FreezeResult> {
  assertModuleName(options.challengeModule);
  for (const t of options.targets) {
    assertDeclName(t.theorem);
    assertDeclName(t.statement);
  }
  for (const a of options.permittedAxioms) assertDeclName(a);
  for (const d of options.definitionNames ?? []) assertDeclName(d);

  const copy = await createShadow(options.snapshotDir, options.freezeDir);
  const challengeFile = path.join(copy.dir, modulePath(options.challengeModule));
  const existing = await readFile(challengeFile, 'utf8').catch(() => undefined);
  if (existing !== undefined && !existing.startsWith(CHALLENGE_MARKER)) {
    throw new Error(`${modulePath(options.challengeModule)} exists in the snapshot and was not generated by telelean; refusing to overwrite it`);
  }
  await mkdir(path.dirname(challengeFile), { recursive: true });
  await writeFile(challengeFile, generateChallengeModule(options.imports, options.targets), 'utf8');

  const toolchain = options.run?.toolchain ?? resolveToolchain();
  const lake = toolchainExe(toolchain, 'lake');
  const build = await runLean({ ...options.run, toolchain, shadowDir: copy.dir, argv: [lake, 'build', options.challengeModule] });
  if (build.status !== 'ok') {
    return { ok: false, stage: 'build', detail: `${build.status}: ${build.detail ?? tail(build.stdout + build.stderr)}`, build };
  }

  const theoremNames = options.targets.map((t) => t.theorem);
  const definitionNames = options.definitionNames ?? [];
  const exportTargets = comparatorExportTargets({ theoremNames, permittedAxioms: options.permittedAxioms, definitionNames });
  await mkdir(path.dirname(options.exportPath), { recursive: true });
  const exported = await runLean({
    ...options.run,
    toolchain,
    shadowDir: copy.dir,
    argv: [lake, 'env', 'leanexport', options.challengeModule, '--', ...exportTargets],
    env: { ...options.run?.env, LEAN_ABORT_ON_PANIC: '1' },
    stdoutFile: options.exportPath,
  });
  const size = await stat(options.exportPath).then((s) => s.size, () => 0);
  if (exported.status !== 'ok' || size === 0) {
    return {
      ok: false,
      stage: 'export',
      detail: `${exported.status}${size === 0 ? ' (empty export)' : ''}: ${exported.detail ?? tail(exported.stderr)}`,
      build,
      export: exported,
    };
  }
  return {
    ok: true,
    freeze: {
      exportPath: options.exportPath,
      challengeModule: options.challengeModule,
      theoremNames,
      permittedAxioms: [...options.permittedAxioms],
      definitionNames: [...definitionNames],
    },
    build,
    export: exported,
  };
}

