function nextMessage(
  api: TeleleanApi,
  predicate: (message: WebviewToHostMessage) => boolean,
  timeoutMs: number,
  label: string,
): Promise<WebviewToHostMessage> {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => {
      subscription.dispose();
      reject(new Error(`timed out after ${timeoutMs} ms waiting for the webview to post ${label}`));
    }, timeoutMs);
    const subscription = api.onDidReceiveBoardMessage((message) => {
      if (!predicate(message)) return;
      clearTimeout(timer);
      subscription.dispose();
      resolve(message);
    });
  });
}

