type Layer = 'under' | 'over';

/** Arrowheads, one per line style. Filled through CSS classes (inline style attributes are blocked by the CSP). */
function EdgeDefs({ layer }: { layer: Layer }) {
  return (
    <defs>
      {(['declared', 'verified', 'focus'] as const).map((variant) => (
        <marker
