/**
 * Stub marker for frozen M1 contracts whose implementation belongs to a work package (docs/m1-plan.md section 9).
 * A builder replaces the stub body; nothing else may depend on the error. Tests of one package that need another
 * package's implementation can skip themselves with `isImplemented(() => fn(...))` until integration.
 */
export class NotImplementedError extends Error {
  constructor(readonly what: string) {
    super(`not implemented yet: ${what}`);
    this.name = 'NotImplementedError';
  }
}

export function notImplemented(what: string): never {
  throw new NotImplementedError(what);
}

/** True unless calling `probe` throws NotImplementedError (other errors count as implemented). */
export function isImplemented(probe: () => unknown): boolean {
  try {
    probe();
    return true;
  } catch (error) {
    return !(error instanceof NotImplementedError);
  }
}

/**
 * Lean facts: what the semantic layer (runner, WP-semantic) learned from one sandboxed `lake build` plus the
 * telelean-generated check file, keyed by Lean names and file positions. Pure data, no markup knowledge: core
 * (WP-model) merges it with the parsed blocks (docs/m1-plan.md section 4).
 *
 * FROZEN CONTRACT (M1). Additive optional fields only; record them in the plan's change log.
 *
 * Positions follow the LSP convention (0-based line, UTF-16 character), as the `.ilean` files store them.
 * Paths are POSIX, relative to the model root.
 */
import type { Range } from './model.js';

export const LEAN_FACTS_FORMAT = 'telelean-lean-facts' as const;
export const LEAN_FACTS_VERSION = 1 as const;

/** The axioms `#print axioms` treats as a clean proof (same list as runner/lean/comparator.ts STANDARD_AXIOMS). */
export const STANDARD_AXIOM_NAMES: readonly string[] = ['propext', 'Classical.choice', 'Quot.sound'];
/** The axiom behind `sorry`. */
export const SORRY_AXIOM = 'sorryAx';
/** D-2(b): the justification of statement `n` is `n.holds`. */
export const HOLDS_SUFFIX = '.holds';

export type FactsStatus =
  /** Build and check succeeded; every module is fresh. */
  | 'ok'
  /** The build had errors: facts cover the modules that built (see `modules[].state`). */
  | 'build-errors'
  /** The build succeeded but the check file reported errors for some declarations (see `decls[].error`). */
  | 'check-errors'
  /** The sandbox could not start (no bwrap/systemd user manager, cap not enforced, ...). No facts. */
  | 'could-not-start'
  | 'timeout'
  | 'oom'
  | 'cancelled'
  /** Not started: MemAvailable was below the threshold. No facts. */
  | 'low-memory'
  /** Not started: `lean-toolchain` is not the pinned toolchain (D-7). No facts. */
  | 'unsupported-toolchain';

export interface LeanMessageFact {
  severity: 'error' | 'warning' | 'information';
  /** Model file the message is about, when Lean names one. */
  file?: string;
  module?: string;
  /** 0-based line / UTF-16 character (converted from Lean's 1-based line, 0-based column). */
  range?: Range;
  text: string;
}

export interface BuildFacts {
  status: 'ok' | 'failed' | 'oom' | 'timeout' | 'cancelled' | 'could-not-start' | 'skipped';
  durationMs: number;
  peakMemoryBytes?: number;
  /** Lean messages from the build (errors, warnings such as "declaration uses `sorry`", infos). */
  messages: LeanMessageFact[];
  /** Modules Lake reported as failed. */
  failedModules: string[];
  detail?: string;
}

export interface CheckRunFacts {
  status: 'ok' | 'failed' | 'oom' | 'timeout' | 'cancelled' | 'could-not-start' | 'skipped';
  durationMs: number;
  peakMemoryBytes?: number;
  /** Number of declarations probed. */
  probed: number;
  detail?: string;
}

export interface ModuleFacts {
  /** e.g. `Model.Spyro.Main`. */
  name: string;
  /** e.g. `Model/Spyro/Main.lean`. */
  file: string;
  /** sha256 (hex) of the source the build saw, hashed before the build started. */
  sourceSha256: string;
  /**
   * `fresh`: built in this refresh (or up to date) and checked. `failed`: Lake reported it failed (Lake deletes
   * its .olean/.ilean). `dependency-failed`: an import failed, so it was not built. `not-built`: not imported by
   * the library root, so `lake build` never compiles it. `stale`: its source changed while the refresh ran.
   */
  state: 'fresh' | 'failed' | 'dependency-failed' | 'not-built' | 'stale';
  /** Project-internal imports, from the source header. */
  imports: string[];
}

export type LeanDeclKind = 'axiom' | 'theorem' | 'def' | 'opaque' | 'instance' | 'structure' | 'inductive' | 'class' | 'other';

/** An identifier occurrence inside a declaration that Lean resolved to a constant (`.ilean` `usages`). */
export interface DeclRef {
  /** Fully-qualified constant name. */
  name: string;
  /** Module that defines the constant. */
  module: string;
  /** Absolute range of the occurrence in the declaration's file. */
  range: Range;
}

export interface DeclFacts {
  /** Fully-qualified name, e.g. `Spyro.cynder_dark_past.holds`. */
  name: string;
  module: string;
  file: string;
  /** Full range from the `.ilean` `decls` table (starts at the docstring when there is one). */
  range: Range;
  /** The name's range. */
  selectionRange: Range;
  /** From the `#print` header (`@[reducible] def` counts as `def` with attribute `reducible`). */
  kind?: LeanDeclKind;
  /** Attributes shown by `#print`, e.g. `reducible`, `instance_reducible`. */
  attributes?: string[];
  /** `#check @name` with `pp.fullNames`: the declaration's type, e.g. `Spyro.Character → Prop`. */
  type?: string;
  /** `#print` value for definitions (e.g. a statement abbrev's proposition), `pp.fullNames`; absent for axioms, opaque, theorems. */
  value?: string;
  /** `#print axioms` with `pp.fullNames`, in Lean's order. Absent if the probe failed. */
  axioms?: string[];
  /** `axioms` contains `sorryAx`. */
  usesSorry?: boolean;
  /** A probe failed (e.g. the name did not resolve); the text is Lean's message. */
  error?: string;
  /** The docstring text (between `/--` and `-/`, trimmed), read from the source at `range`. */
  docstring?: string;
  /** Usages inside this declaration (`.ilean` usages whose parent declaration is this one), in source order. */
  refs: DeclRef[];
  /** For auxiliary names that `.ilean` attributes to another declaration (e.g. structure fields): that declaration. */
  parent?: string;
}

export interface LeanFacts {
  format: typeof LEAN_FACTS_FORMAT;
  version: typeof LEAN_FACTS_VERSION;
  /** The toolchain the project pins and the facts come from, e.g. `leanprover/lean4:v4.35.0`. */
  toolchain: string;
  /** Library whose modules were checked, e.g. `Model`. */
  library: string;
  startedAt: string;
  finishedAt: string;
  status: FactsStatus;
  detail?: string;
  build: BuildFacts;
  check: CheckRunFacts;
  modules: ModuleFacts[];
  /** Declarations of the fresh modules, in module then source order. */
  decls: DeclFacts[];
}

/** `n.holds` for statement `n`. */
export function holdsName(statement: string): string {
  return `${statement}${HOLDS_SUFFIX}`;
}

/** The statement name of a `.holds` name, or undefined. */
export function statementOfHolds(name: string): string | undefined {
  return name.endsWith(HOLDS_SUFFIX) && name.length > HOLDS_SUFFIX.length ? name.slice(0, -HOLDS_SUFFIX.length) : undefined;
}

/**
 * Path conventions of a model folder (03 section 4 scaffold, D-10 subjects, D-12 sidecars), as pure string helpers.
 * Every path is POSIX and relative to the model root (the folder that holds `.telelean/` and the lakefile).
 *
 * FROZEN CONTRACT (M1, docs/m1-plan.md section 7). Implemented here by the architect; owned by WP-model afterwards.
 *
 *   lakefile.toml · lean-toolchain · lake-manifest.json · .gitignore
 *   Model.lean                         library root: imports every subject root (maintained by telelean)
 *   Model/<S>.lean                     subject root: imports the subject's modules
 *   Model/<S>/{Vocabulary,Inbox,Main}.lean        `namespace <S>`
 *   .telelean/config.json              opt-in marker + project settings
 *   .telelean/graph.json               export for scripts (gitignored)
 *   .telelean/subjects/<S>/layout.json column order (committed)
 *   .telelean/subjects/<S>/attic/<id>.lean        archived proofs (committed)
 */

export const TELELEAN_DIR = '.telelean';
export const CONFIG_PATH = '.telelean/config.json';
export const GRAPH_JSON_PATH = '.telelean/graph.json';
export const DEFAULT_LIBRARY = 'Model';
export const PINNED_TOOLCHAIN_NAME = 'leanprover/lean4:v4.35.0';

/** The modules of a scaffolded subject, in import order. */
export const SUBJECT_MODULES = ['Vocabulary', 'Inbox', 'Main'] as const;
export type SubjectModule = (typeof SUBJECT_MODULES)[number];

/** A subject name is a Lean identifier usable as a module component and a namespace (capitalised by convention). */
export const SUBJECT_NAME_PATTERN = /^[A-Z][A-Za-z0-9_]{0,63}$/;

export function isSubjectName(name: string): boolean {
  return SUBJECT_NAME_PATTERN.test(name);
}

/** `.telelean/config.json`. */
export interface ProjectConfig {
  format: 'telelean-config';
  version: 1;
  /** The Lake library that holds the subjects (default `Model`). */
  library: string;
}

export function defaultProjectConfig(): ProjectConfig {
  return { format: 'telelean-config', version: 1, library: DEFAULT_LIBRARY };
}

/** Parses `.telelean/config.json` leniently: unknown keys are ignored, a bad library name falls back to the default. */
export function parseProjectConfig(json: string): ProjectConfig {
  try {
    const raw = JSON.parse(json) as Record<string, unknown>;
    const library = typeof raw['library'] === 'string' && /^[A-Za-z_][A-Za-z0-9_]*$/.test(raw['library']) ? raw['library'] : DEFAULT_LIBRARY;
    return { format: 'telelean-config', version: 1, library };
  } catch {
    return defaultProjectConfig();
  }
}

export function serializeProjectConfig(config: ProjectConfig): string {
  return `${JSON.stringify({ format: config.format, version: config.version, library: config.library }, null, 2)}\n`;
}

export function libraryRootFile(library: string = DEFAULT_LIBRARY): string {
  return `${library}.lean`;
}

export function subjectDir(subject: string, library: string = DEFAULT_LIBRARY): string {
  return `${library}/${subject}`;
}

export function subjectRootFile(subject: string, library: string = DEFAULT_LIBRARY): string {
  return `${library}/${subject}.lean`;
}

export function subjectModulePath(subject: string, module: SubjectModule, library: string = DEFAULT_LIBRARY): string {
  return `${library}/${subject}/${module}.lean`;
}

/** New code-less nodes go to the subject's Inbox (D-11). */
export function inboxPath(subject: string, library: string = DEFAULT_LIBRARY): string {
  return subjectModulePath(subject, 'Inbox', library);
}

export function subjectSidecarDir(subject: string): string {
  return `${TELELEAN_DIR}/subjects/${subject}`;
}

export function layoutPath(subject: string): string {
  return `${subjectSidecarDir(subject)}/layout.json`;
}

export function atticPath(subject: string, nodeId: string): string {
  return `${subjectSidecarDir(subject)}/attic/${nodeId}.lean`;
}

/** `Model/Spyro/Main.lean` -> `Model.Spyro.Main`; undefined for non-Lean paths. */
export function moduleOfPath(path: string): string | undefined {
  if (!path.endsWith('.lean') || path.startsWith('/') || path.split('/').some((s) => s === '' || s === '.' || s === '..')) return undefined;
  return path.slice(0, -'.lean'.length).split('/').join('.');
}

/** `Model.Spyro.Main` -> `Model/Spyro/Main.lean`. */
export function pathOfModule(module: string): string {
  return `${module.split('.').join('/')}.lean`;
}

/**
 * The subject a model file belongs to: `Model/<S>.lean` and `Model/<S>/**.lean` belong to `<S>`; anything else
 * (the library root, files outside the library) belongs to no subject.
 */
export function subjectOfPath(path: string, library: string = DEFAULT_LIBRARY): string | undefined {
  const parts = path.split('/');
  if (parts[0] !== library || parts.length < 2) return undefined;
  if (parts.length === 2) {
    const file = parts[1] ?? '';
    return file.endsWith('.lean') ? file.slice(0, -'.lean'.length) || undefined : undefined;
  }
  return parts[1] || undefined;
}

/**
 * The files a subject's history snapshots cover (D-33, docs/m1-plan.md section 8): its subject root, its module
 * directory, and its sidecar directory. Returned as prefixes; a path is in scope if it equals a file entry or starts
 * with a directory entry (those end with `/`).
 */
export function subjectSnapshotScope(subject: string, library: string = DEFAULT_LIBRARY): string[] {
  return [subjectRootFile(subject, library), `${subjectDir(subject, library)}/`, `${subjectSidecarDir(subject)}/`];
}

/** Project-level files covered by the `_project` history chain. */
export function projectSnapshotScope(library: string = DEFAULT_LIBRARY): string[] {
  return [libraryRootFile(library), 'lakefile.toml', 'lean-toolchain', 'lake-manifest.json', '.gitignore', CONFIG_PATH];
}

export function inScope(path: string, scope: readonly string[]): boolean {
  return scope.some((entry) => (entry.endsWith('/') ? path.startsWith(entry) : path === entry));
}

/**
 * `.telelean/subjects/<S>/layout.json`: the column order of one subject's board (D-12; layout only, never semantics).
 * A card's column is its node's `type:`; the layout only orders cards inside a column.
 *
 * FROZEN CONTRACT (M1, docs/m1-plan.md section 7). Implemented by the architect; owned by WP-model afterwards.
 */
import type { NodeType } from './model.js';
import { isNodeType, NODE_TYPES } from './model.js';

export interface Layout {
  format: 'telelean-layout';
  version: 1;
  /** Card order per column (ids). Ids that no longer exist, or sit in the wrong column, are ignored. */
  columns: Record<NodeType, string[]>;
  /** UI state that is worth keeping with the model. */
  collapsed?: { vocabulary?: boolean };
}

export function emptyLayout(): Layout {
  return { format: 'telelean-layout', version: 1, columns: { ASSUMPTION: [], DERIVATION: [], GOAL: [] } };
}

/** Parses layout.json leniently: anything malformed yields the empty layout (layout is never worth an error). */
export function parseLayout(json: string | null | undefined): Layout {
  if (!json) return emptyLayout();
  try {
    const raw = JSON.parse(json) as { columns?: Record<string, unknown>; collapsed?: { vocabulary?: unknown } };
    const layout = emptyLayout();
    for (const [kind, ids] of Object.entries(raw.columns ?? {})) {
      if (!isNodeType(kind) || !Array.isArray(ids)) continue;
      const seen = new Set<string>();
      for (const id of ids) {
        if (typeof id === 'string' && !seen.has(id)) {
          seen.add(id);
          layout.columns[kind].push(id);
        }
      }
    }
    if (typeof raw.collapsed?.vocabulary === 'boolean') layout.collapsed = { vocabulary: raw.collapsed.vocabulary };
    return layout;
  } catch {
    return emptyLayout();
  }
}

/** Stable serialisation (2-space indent, trailing newline), so unchanged layouts produce identical files. */
export function serializeLayout(layout: Layout): string {
  const out: Record<string, unknown> = {
    format: 'telelean-layout',
    version: 1,
    columns: { ASSUMPTION: layout.columns.ASSUMPTION, DERIVATION: layout.columns.DERIVATION, GOAL: layout.columns.GOAL },
  };
  if (layout.collapsed) out['collapsed'] = layout.collapsed;
  return `${JSON.stringify(out, null, 2)}\n`;
}

/**
 * Column order for `nodes` (given in file order): ids listed in the layout's column come first, in layout order;
 * the remaining nodes of that type follow in input order.
 */
export function orderByLayout(nodes: ReadonlyArray<{ id: string; type: NodeType }>, layout?: Layout): Record<NodeType, string[]> {
  const order: Record<NodeType, string[]> = { ASSUMPTION: [], DERIVATION: [], GOAL: [] };
  const typeOf = new Map(nodes.map((n) => [n.id, n.type]));
  const placed = new Set<string>();
  for (const kind of NODE_TYPES) {
    for (const id of layout?.columns[kind] ?? []) {
      if (typeOf.get(id) === kind && !placed.has(id)) {
        order[kind].push(id);
        placed.add(id);
      }
    }
  }
  for (const node of nodes) {
    if (!placed.has(node.id)) {
      order[node.type].push(node.id);
      placed.add(node.id);
    }
  }
  return order;
}

/**
 * The layout after moving `id` into `column` above `beforeId` (null = end), starting from the order the board
 * currently shows (`current`, e.g. from `orderByLayout`). The result lists every id of `current`, so the board's
 * order is pinned once the user has arranged it.
 */
export function moveInLayout(
  layout: Layout,
  current: Readonly<Record<NodeType, readonly string[]>>,
  id: string,
  column: NodeType,
  beforeId: string | null,
): Layout {
  const columns: Record<NodeType, string[]> = { ASSUMPTION: [], DERIVATION: [], GOAL: [] };
  for (const kind of NODE_TYPES) columns[kind] = current[kind].filter((x) => x !== id);
  const target = columns[column];
  const index = beforeId === null ? -1 : target.indexOf(beforeId);
  if (index >= 0) target.splice(index, 0, id);
  else target.push(id);
  return { ...layout, columns };
}

/** The layout without the given ids (after deletes). */
export function withoutIds(layout: Layout, ids: Iterable<string>): Layout {
  const drop = new Set(ids);
  const columns: Record<NodeType, string[]> = { ASSUMPTION: [], DERIVATION: [], GOAL: [] };
  for (const kind of NODE_TYPES) columns[kind] = layout.columns[kind].filter((id) => !drop.has(id));
  return { ...layout, columns };
}

/** The layout with `id` appended to `column` (after adds), unless it is already listed there. */
export function appendToLayout(layout: Layout, id: string, column: NodeType): Layout {
  if (layout.columns[column].includes(id)) return layout;
  const base = withoutIds(layout, [id]);
  return { ...base, columns: { ...base.columns, [column]: [...base.columns[column], id] } };
}

/**
 * Board actions and their results: what a user gesture asks for (BoardAction), what core plans for it (EditPlan),
 * what the runner applies and records (FileChange), and the history/undo records the board lists.
 *
 * FROZEN CONTRACT (M1, docs/m1-plan.md sections 5 and 8). Additive optional fields only.
 *
 *   webview message --(extension)--> BoardAction --(core planAction)--> EditPlan
 *     --(runner materialises sidecars)--> FileChange[] --(extension EditApplier: WorkspaceEdit + save)--> disk
 *     --(runner)--> history snapshot (git private ref) + undo entry + re-parse + Lean refresh
 */
import type { Evidential, NodeType, Stance } from './model.js';
import type { Layout } from './layout.js';

// ---------------------------------------------------------------------------------------------
// Actions

/** Fields the board can edit in place (D-17 "edit text/rationale"; D-14 chips). */
export type EditableField = 'naturalName' | 'rationale' | 'stance' | 'source';

/** What to do with Lean dependents when a kind change removes `n.holds` (D-11 A->G, D->G). */
export type DependentsChoice = 'rewrite' | 'mark-broken';

export type BoardAction =
  /** D-16: a comment-only node with the user's verbatim words, written to the subject's Inbox. */
  | {
      kind: 'add-node';
      subject: string;
      type: NodeType;
      naturalName: string;
      rationale?: string;
      stance?: Stance;
      source?: Evidential;
      /** Id the webview proposed (used when valid and unused across the workspace). */
      preferredId?: string;
    }
  /** `value: null` removes the field (not allowed for naturalName). */
  | { kind: 'edit-node'; id: string; field: EditableField; value: string | null }
  /** D-18 delete: the block, and unless `keepLean` also its bound declarations (theorem proofs are archived). */
  | { kind: 'delete-node'; id: string; keepLean: boolean }
  /** D-11 kind change (the card moves to `to`, above `beforeId`). */
  | {
      kind: 'change-kind';
      id: string;
      to: NodeType;
      beforeId: string | null;
      /** Required when the change removes a `.holds` that others use (KindChangeImpact.needsConfirmation). */
      dependents?: DependentsChoice;
      /** G->A: "you supply the reason" (optional, never blocking: D-14). */
      rationale?: string;
    }
  /** D-17 drag within a column: layout only. */
  | { kind: 'reorder'; id: string; column: NodeType; beforeId: string | null }
  /** M1 "These suffice": declare `premises` as the target's joint support (replaces `premises:`, D-13). */
  | { kind: 'set-premises'; target: string; premises: string[] }
  /** D-10: a new subject (module subtree + namespace), with the scaffold files. */
  | { kind: 'create-subject'; name: string };

export type BoardActionKind = BoardAction['kind'];

/** Every kind of history entry (board actions plus housekeeping). */
export type HistoryActionKind =
  | BoardActionKind
  /** The first snapshot of a subject (when its history starts). */
  | 'initial'
  /** Hand edits found on disk before telelean's next write. */
  | 'manual'
  | 'undo'
  | 'redo'
  | 'revert'
  /** "telelean: Initialize Model Here". */
  | 'initialize';

// ---------------------------------------------------------------------------------------------
// Plans and file changes

/** A whole-file change. `before: null` = the file is created; `after: null` = the file is deleted. */
export interface FileChange {
  /** POSIX path relative to the model root. */
  path: string;
  before: string | null;
  after: string | null;
}

/** A declaration removed from a model file and kept in the subject's attic (D-11 D->A, D-18 delete). */
export interface ArchiveEntry {
  subject: string;
  nodeId: string;
  /** Fully-qualified name of the archived declaration. */
  declName: string;
  /** Its source text, verbatim. */
  text: string;
  /** e.g. `Derivation -> Assumption`, `deleted`. */
  reason: string;
}

/**
 * What core plans for one action, from the parsed files alone (pure). The runner turns `layout` and `archive` into
 * sidecar FileChanges (layout.json, attic files) before applying.
 */
export interface EditPlan {
  action: HistoryActionKind;
  /** One line for the history dropdown and the Undo toast, e.g. `Delete: Cynder would not be a good addition…`. */
  label: string;
  /** The subject the action belongs to ('' for project-level changes). */
  subject: string;
  /** Node ids the action is about. */
  nodes: string[];
  /** Model (Lean) file changes. */
  changes: FileChange[];
  /** The subject's new layout, when the column order changes. */
  layout?: { subject: string; layout: Layout };
  /** Declarations to append to attic files. */
  archive?: ArchiveEntry[];
  /** Only the layout changes: undoable, but not snapshotted on its own (docs/m1-plan.md section 8). */
  layoutOnly?: boolean;
  /** The id of a node the action created (add-node). */
  nodeId?: string;
}

export type ActionErrorCode =
  /** The node, subject or history entry does not exist (any more). */
  | 'not-found'
  /** The request is invalid (e.g. empty sentence, premise cycle, subject name taken). */
  | 'invalid'
  /** The change removes a `.holds` that others use and no DependentsChoice was given (show the confirm dialog). */
  | 'needs-confirmation'
  /** The Lean facts needed for a mechanical rewrite are stale or missing: refresh first. */
  | 'facts-stale'
  /** A file changed since the plan was made, or since the action being undone. */
  | 'conflict'
  /** The block or declaration cannot be edited safely (duplicate id, parse error in the block, ...). */
  | 'unsafe'
  /** Available from M2 on (e.g. "Self-evident?" with zero premises). */
  | 'not-yet'
  /** History is unavailable (no git repository, git missing). */
  | 'no-history'
  | 'internal';

/** A user-facing refusal. `message` is shown on the board as is. */
export class ActionError extends Error {
  constructor(
    readonly code: ActionErrorCode,
    message: string,
    /** For `needs-confirmation`: the dependents to list. */
    readonly dependents: readonly string[] = [],
  ) {
    super(message);
    this.name = 'ActionError';
  }
}

/** The result of performing an action, undo, redo or revert (runner -> extension -> webview `actionResult`). */
export type ActionOutcome =
  | { ok: true; label: string; undoable: boolean; nodeId?: string }
  | { ok: false; code: ActionErrorCode; error: string; dependents?: string[] };

// ---------------------------------------------------------------------------------------------
// History (D-33) and undo

export interface HistoryEntry {
  /** Commit id (hex) of the snapshot. */
  id: string;
  /** ISO time of the snapshot. */
  time: string;
  action: HistoryActionKind;
  /** e.g. `Delete: Cynder would not be a good addition…`. */
  label: string;
  subject: string;
  nodes: string[];
}

/** Disk used by telelean's history (D-33 counter): objects reachable from telelean's refs and from no branch or tag. */
export interface StorageUsage {
  subjectBytes: number;
  totalBytes: number;
  perSubject: Record<string, number>;
}

export type HistoryAvailability =
  | { state: 'ready' }
  /** The model folder is not inside a git repository; Initialize/the board can offer `git init`. */
  | { state: 'no-repo' }
  | { state: 'git-missing' }
  /** Switched off by the `telelean.git.snapshotRefs` setting. */
  | { state: 'disabled' }
  | { state: 'error'; detail: string };

export interface HistoryListing {
  subject: string;
  /** Newest first. */
  entries: HistoryEntry[];
  storage: StorageUsage;
  /** More entries exist beyond `entries`. */
  more: boolean;
}

/** Files of a history entry compared with its parent or with the current state, for the read-only preview. */
export interface HistoryDiff {
  entry: HistoryEntry;
  compare: 'parent' | 'current';
  files: FileChange[];
}

// ---------------------------------------------------------------------------------------------
// Board-level state the host sends besides the graph

export interface WorkspaceState {
  /** Display name of the model root (its folder name). */
  rootName: string;
  subjects: Array<{ name: string; nodeCount: number }>;
  /** The subject the board shows. */
  subject: string;
  /** Label of the action Undo would revert / Redo would re-apply, or null. */
  undo: string | null;
  redo: string | null;
  history: HistoryAvailability;
}

/**
 * Markup language v1 and Lean source text (03 section 3; 02 D-8, D-9): the types shared by the lexer, parser,
 * binder, serializer and the text-edit primitives (WP-markup), and consumed by the graph builder and the edit
 * planner (WP-model) and the runner workspace (WP-workspace).
 *
 * FROZEN CONTRACT (M1, docs/m1-plan.md section 5.2). WP-markup owns this file but may only add OPTIONAL fields or new
 * exports (record them in the plan's change log); renames/removals go through the integrator.
 *
 * Offsets (`Span`) are UTF-16 code-unit indices into `ParsedFile.text` (JavaScript string indices), end exclusive.
 * Ranges follow the LSP convention (0-based line, UTF-16 character). Paths are POSIX, relative to the model root.
 */
import type { Evidential, NodeType, Range, Severity, Stance } from '../model.js';

export interface Span {
  readonly start: number;
  readonly end: number;
}

// ---------------------------------------------------------------------------------------------
// Lexer (Lean 4.35 comment/string rules: nested `/- -/`, `--` line comments, strings, chars, raw strings, «»)

export type CommentKind =
  /** `-- ...` */
  | 'line'
  /** `/- ... -/` (the only kind that can hold a telelean block) */
  | 'block'
  /** `/-- ... -/` docstring */
  | 'doc'
  /** `/-! ... -/` module docstring */
  | 'moddoc';

export interface LeanComment {
  kind: CommentKind;
  /** From the opener to just after the closer (or EOF when unterminated). */
  span: Span;
  /** The text between opener and closer. */
  body: Span;
  unterminated: boolean;
}

export type TokenKind = 'ident' | 'string' | 'char' | 'number' | 'symbol';

/** A code token outside comments (identifiers are dotted, with «escaped» parts; symbols are single characters). */
export interface LeanToken {
  kind: TokenKind;
  span: Span;
  text: string;
}

export interface LexResult {
  comments: LeanComment[];
  tokens: LeanToken[];
}

// ---------------------------------------------------------------------------------------------
// Blocks

export const MARKUP_VERSION = 1;
/** Markup versions this build interprets (a newer block is kept and shown, with TL008). */
export const SUPPORTED_MARKUP_VERSIONS: readonly number[] = [1];

/** Field keys with a meaning in v1 (03 section 3.2). `kind` is accepted as an alias of `type` and normalised. */
export type KnownFieldKey =
  | 'id'
  | 'type'
  | 'natural_name'
  | 'rationale'
  | 'stance'
  | 'source'
  | 'asserted'
  | 'premises'
  | 'lean'
  | 'supersedes'
  | 'refines'
  | 'tags'
  | 'origin'
  | 'session'
  | 'worded_by';

/** Canonical order in which the serializer writes known fields. */
export const FIELD_ORDER: readonly KnownFieldKey[] = [
  'id',
  'type',
  'natural_name',
  'rationale',
  'stance',
  'source',
  'premises',
  'asserted',
  'lean',
  'supersedes',
  'refines',
  'tags',
  'origin',
  'session',
  'worded_by',
];

/** The interpreted values of the known fields of one block. */
export interface BlockFields {
  type?: NodeType;
  naturalName?: string;
  rationale?: string;
  stance?: Stance;
  source?: Evidential;
  /** ISO date `YYYY-MM-DD`. */
  asserted?: string;
  premises?: string[];
  /** Pinned binding: fully-qualified names as written (the first is the statement). */
  lean?: string[];
  supersedes?: string;
  refines?: string;
  tags?: string[];
  origin?: 'user' | 'agent';
  session?: string;
  wordedBy?: 'user' | 'agent';
}

/** One `key: value` line of a block, as written. */
export interface FieldLine {
  /** Normalised key (`kind` -> `type`); dotted extension keys verbatim. */
  key: string;
  /** The key as written. */
  writtenKey: string;
  /** The whole line, from its first character up to (not including) its line break. */
  span: Span;
  /** The raw value text (after `:` and surrounding spaces). */
  valueSpan: Span;
  raw: string;
}

export interface BlockBinding {
  /** `pinned`: a `lean:` field; `adjacent`: the next declaration (no blank line in between); `none`: code-less. */
  mode: 'none' | 'adjacent' | 'pinned';
  /** Fully-qualified name of the statement declaration (the first `lean:` name, or the adjacent declaration's name). */
  statement?: string;
  /** All pinned names, fully qualified (a multi-name `lean:` field). */
  pinned?: string[];
  /** Index into `ParsedFile.decls` of the adjacent declaration. */
  adjacentDecl?: number;
  /** Index into `ParsedFile.decls` of a declaration that follows after a blank line (TL013 hint). */
  gapDecl?: number;
}

export interface MarkupBlock {
  /** The node id: as written, or derived from `natural_name` when absent (`idWritten: false`, TL112). */
  id: string;
  idWritten: boolean;
  version: number;
  fields: BlockFields;
  /** Dotted extension keys and unknown keys, verbatim values, in order of appearance (round-tripped untouched). */
  extensions: Record<string, string[]>;
  /** Markdown notes after `---`, dedented, with the `-\/` and `/\-` escapes kept. */
  body?: string;
  /** The whole `/- ... -/` comment. */
  span: Span;
  range: Range;
  markerSpan: Span;
  lines: FieldLine[];
  /** From the `---` line to the end of the body. */
  bodySpan?: Span;
  binding: BlockBinding;
}

// ---------------------------------------------------------------------------------------------
// Declarations (syntactic; the semantic layer confirms them)

export type DeclKeyword =
  | 'axiom'
  | 'theorem'
  | 'lemma'
  | 'def'
  | 'abbrev'
  | 'opaque'
  | 'instance'
  | 'example'
  | 'inductive'
  | 'coinductive'
  | 'structure'
  | 'class'
  | 'class inductive'
  | 'class abbrev'
  | 'mutual';

/** A top-level declaration found by the header parser (docstring, `@[...]`, modifiers, keyword, name). */
export interface DeclInfo {
  keyword: DeclKeyword;
  /** The name as written (may be relative to the namespace); absent for anonymous instances, `example`, `mutual`. */
  name?: string;
  /** Resolved against the enclosing namespaces (`_root_.` honoured). */
  fullName?: string;
  /** Enclosing namespace components at the declaration, outermost first. */
  namespace: string[];
  /** `private`, `noncomputable`, ... in order. */
  modifiers: string[];
  /** Raw text of the `@[...]` attribute lists, if any. */
  attributes?: string[];
  /** Docstring text (inside `/-- -/`, trimmed). */
  docstring?: string;
  docSpan?: Span;
  /**
   * From the start of the docstring/attributes/modifiers to the end of the declaration's last non-blank line
   * (the declaration ends where the next top-level command, block or `end`/`namespace`/`section` starts).
   */
  span: Span;
  range: Range;
  keywordSpan: Span;
  nameSpan?: Span;
  /** Offset of the top-level `:=` (or `where`/`|`) that ends the signature; absent for axioms and bodiless opaques. */
  valueStart?: number;
}

export interface MarkupDiagnostic {
  /** TL001-TL099 (docs/m1-plan.md section 6.5). */
  code: string;
  severity: Severity;
  message: string;
  span: Span;
  range: Range;
  nodeId?: string;
}

/** One model file, parsed. Cheap enough to redo on every keystroke (research: ~145 ms for 27k lines in CPython). */
export interface ParsedFile {
  path: string;
  text: string;
  eol: '\n' | '\r\n';
  blocks: MarkupBlock[];
  decls: DeclInfo[];
  /** Module names imported by the header. */
  imports: string[];
  diagnostics: MarkupDiagnostic[];
}

/** Offset <-> position conversion for one text. */
export interface LineIndex {
  positionAt(offset: number): { line: number; character: number };
  offsetAt(position: { line: number; character: number }): number;
  readonly lineCount: number;
}

// ---------------------------------------------------------------------------------------------
// Writing

/** The fields of a block telelean writes (add-node; M2 proposals). */
export interface NewBlock {
  id: string;
  type: NodeType;
  naturalName: string;
  rationale?: string;
  stance?: Stance;
  source?: Evidential;
  premises?: string[];
  asserted?: string;
  lean?: string[];
  /** Extra `key: value` pairs written after the known fields (e.g. `origin`, dotted extensions). */
  extra?: Array<[string, string]>;
  /** Markdown notes after `---` (escaped by the serializer). */
  body?: string;
}

/** Replace `text[span.start, span.end)` by `newText`. Edits passed together must not overlap. */
export interface TextEdit {
  span: Span;
  newText: string;
}

export type InsertWhere =
  /** Before the `end <namespace>` that closes the file's last `namespace <namespace>`, else at end of file. */
  | { kind: 'end-of-namespace'; namespace: string }
  | { kind: 'end-of-file' }
  /** After the block with this id, and after the declarations bound to it. */
  | { kind: 'after-block'; blockId: string };

/**
 * A Lean text operation (planned by WP-model from the graph and the facts, applied by WP-markup to one file).
 * Names are fully qualified; `Span`s refer to the current text of the file the op is applied to.
 */
export type LeanOp =
  /** G->A, D->A (unproved): insert `axiom <short>.holds : <short>` on the line after the statement declaration. */
  | { op: 'add-holds-axiom'; statement: string }
  /** D->A: replace `theorem S.holds ... := proof` by `axiom S.holds : S`, archiving the theorem's text. */
  | { op: 'holds-theorem-to-axiom'; statement: string }
  /** A->G, D->G: delete `S.holds` (archived when it is a theorem). */
  | { op: 'remove-holds'; statement: string; archive: boolean }
  /** Delete any declaration (with its docstring), e.g. the statement abbrev on delete. */
  | { op: 'remove-decl'; name: string; archive: boolean }
  /**
   * D-11 rewrite of a dependent: add the binder `(hypName : hypType)` before the declaration's `:` and replace each
   * span (an occurrence of the removed `.holds`, from the facts' refs) by `hypName`.
   */
  | { op: 'add-hypothesis'; decl: string; hypName: string; hypType: string; replace: readonly Span[] }
  /** D-11 cascade: wrap each span (an occurrence of a dependent that gained a hypothesis) as `(<occurrence> <hypName>)`. */
  | { op: 'apply-hypothesis'; decl: string; hypName: string; replace: readonly Span[] }
  /** D-9 docstring mirror: set the declaration's docstring to `/-- text -/` (inserted when absent). */
  | { op: 'set-docstring'; decl: string; text: string };

/** A declaration's text removed by a LeanOp, for the attic. */
export interface ArchivedDecl {
  name: string;
  text: string;
}

export interface LeanOpsResult {
  edits: TextEdit[];
  archived: ArchivedDecl[];
  /** Ops that could not be applied (e.g. the declaration was not found), as user-facing sentences. Non-empty = do not apply. */
  problems: string[];
}

