/**
 * The semantic layer (WP-semantic): how telelean learns what Lean thinks of a model project in M1
 * (03 section 5 "M1 facts"; docs/m1-plan.md section 4).
 *
 *   1. memory guard: MemAvailable >= threshold, else status `low-memory` (the board shows "paused: low memory");
 *   2. toolchain check: `lean-toolchain` must be the pinned `leanprover/lean4:v4.35.0` (D-7), else `unsupported-toolchain`;
 *   3. hash every module source (sha256), then `lake build` IN PLACE under runLean (sources read-only, `.lake/`
 *      writable, `.git` masked when present); parse Lake's log for messages and failed modules;
 *   4. read each fresh module's `.ilean` (version 5: `decls` ranges and `references` with parent declarations);
 *   5. one generated check file on stdin (`lake env lean --stdin --json`) importing the fresh modules, with
 *      `set_option pp.fullNames true` and `pp.proofs false`, and per declaration `#check @N`, `#print N` and
 *      `#print axioms N`; messages are attributed by line;
 *   6. re-hash the sources: modules whose source changed meanwhile are `stale`.
 *
 * FROZEN CONTRACT (M1). WP-semantic owns this file; additive optional fields only.
 */
import type { LeanFacts } from '@telelean/core';

import type { HostTools } from '../lean/systemd.js';
import type { LeanToolchain } from '../lean/toolchain.js';

/** Refreshes pause below this much MemAvailable (setting `telelean.memory.minAvailableGiB`, default 2). */
export const DEFAULT_MIN_AVAILABLE_BYTES = 2 * 1024 ** 3;
export const DEFAULT_REFRESH_MEMORY_MAX = '4G';
export const DEFAULT_BUILD_TIMEOUT_MS = 120_000;
export const DEFAULT_CHECK_TIMEOUT_MS = 120_000;

export interface RefreshRequest {
  /** Absolute path of the model root (the Lake project that holds `.telelean/`). */
  root: string;
  /** The Lake library holding the subjects (default `Model`). */
  library?: string;
  /** runLean scope group, for cancelRun (`[A-Za-z0-9_]{1,64}`). */
  runId?: string;
  signal?: AbortSignal;
  /** runLean `MemoryMax=` for the build and the check (default `4G`). */
  memoryMax?: string;
  /** Memory guard threshold (default DEFAULT_MIN_AVAILABLE_BYTES). */
  minAvailableBytes?: number;
  buildTimeoutMs?: number;
  checkTimeoutMs?: number;
  toolchain?: LeanToolchain;
  /** Test hooks. */
  host?: Partial<HostTools>;
  readMemAvailable?: () => number | undefined;
  now?: () => Date;
  /** Called when the build and the check start (the board shows "checking…"). */
  onPhase?: (phase: 'build' | 'check') => void;
}

/** Re-exported for convenience: what a refresh returns. */
export type { LeanFacts };

/**
 * WP-semantic public functions (docs/m1-plan.md sections 4 and 9). Stubs until WP-semantic implements them; the
 * signatures and documented behaviour are FROZEN. Internal helpers (check-file generator, `.ilean` reader, Lake log
 * parser) are WP-semantic's to design and may be exported from here too.
 */
import { readFileSync } from 'node:fs';

import { notImplemented, type LeanFacts } from '@telelean/core';

import type { RefreshRequest } from './types.js';

export * from './types.js';

/**
 * Builds the project in place under runLean and checks it (see ./types.ts for the six steps). Never throws for
 * Lean or sandbox failures: they become `status` values with a `detail`. Throws TypeError for invalid arguments.
 * Does not serialise itself: callers wrap it in `runExclusive`.
 */
export async function refreshLeanFacts(request: RefreshRequest): Promise<LeanFacts> {
  void request;
  return notImplemented('semantic.refreshLeanFacts (WP-semantic)');
}

/** MemAvailable from /proc/meminfo in bytes, or undefined when it cannot be read. */
export function readMemAvailableBytes(): number | undefined {
  try {
    const match = /^MemAvailable:\s+(\d+)\s+kB$/m.exec(readFileSync('/proc/meminfo', 'utf8'));
    return match ? Number(match[1]) * 1024 : undefined;
  } catch {
    return undefined;
  }
}

let tail: Promise<unknown> = Promise.resolve();

/**
 * Runs Lean jobs one at a time in this process (03 principle 5: one Lean job at a time; M2's shadow builds will
 * queue here too). A job's failure does not block the queue.
 */
export function runExclusive<T>(job: () => Promise<T>): Promise<T> {
  const run = tail.then(job, job);
  tail = run.catch(() => undefined);
  return run;
}

/**
 * The model workspace (WP-workspace): everything the extension host needs for one opted-in model root, without
 * importing vscode (03 section 6 "WorkspaceIndex"; docs/m1-plan.md sections 3, 7 and 8).
 *
 *   load()            scan `<library>.lean`, `<library>/**.lean`, `.telelean/` sidecars; parse with core
 *   graph(subject)    core.subjectGraph(project model built from the parsed files + the latest Lean facts)
 *   invalidate(paths) re-read changed files (open buffers first, via TextSource) and rebuild
 *   requestRefresh()  debounced, coalesced, one-at-a-time Lean refresh (semantic.refreshLeanFacts in runExclusive);
 *                     afterwards rewrites `.telelean/graph.json`
 *   perform(action)   core.planAction -> materialise sidecars (layout.json, attic) -> snapshot hand edits ("manual")
 *                     -> EditApplier.apply (the extension: WorkspaceEdit + save) -> snapshot the result -> push the
 *                     undo entry -> re-parse -> requestRefresh
 *   undo/redo         reverse/forward patches of the recorded whole-file changes (fuzzy, all-or-nothing)
 *   history           D-33: per-subject private git refs, revert (itself undoable and snapshotted), storage counter
 *
 * FROZEN CONTRACT (M1). WP-workspace owns this file; additive optional members only.
 */
import type {
  ActionOutcome,
  BoardAction,
  FileChange,
  HistoryAvailability,
  HistoryDiff,
  HistoryListing,
  LeanFacts,
  ProjectConfig,
  SemanticSummary,
  SubjectInfo,
  TlGraph,
  WorkspaceState,
} from '@telelean/core';

import type { RefreshRequest } from '../semantic/types.js';

export interface Disposable {
  dispose(): void;
}

export type WorkspaceLog = (level: 'info' | 'warn' | 'error', message: string) => void;

/** Where the workspace reads model files from. The extension prefers open (possibly unsaved) editor buffers. */
export interface TextSource {
  /** The current text of a file (POSIX path relative to the root), or null when it does not exist. */
  read(path: string): Promise<string | null>;
}

/** How the workspace writes. The extension applies a WorkspaceEdit and saves; tests write to disk. */
export interface EditApplier {
  /**
   * Applies whole-file changes (create / replace / delete) and saves them, so they are on disk when it resolves.
   * Rejects when any change could not be applied; it should then leave nothing half-applied.
   */
  apply(changes: readonly FileChange[], label: string): Promise<void>;
}

export interface SemanticSettings {
  /** Lean checking on/off (off = syntactic mode). Default true. */
  enabled: boolean;
  /** runLean `MemoryMax=` (setting `telelean.memory.capGiB`, default 4 -> `4G`). */
  memoryMax: string;
  /** Memory guard (setting `telelean.memory.minAvailableGiB`, default 2). */
  minAvailableBytes: number;
  /** Debounce for requestRefresh, default 750 ms. */
  debounceMs: number;
}

export interface GitSettings {
  /** D-33 snapshots on/off (setting `telelean.git.snapshotRefs`, default true). */
  enabled: boolean;
  /** git executable (default `git` on PATH). */
  gitPath: string;
  /** Author/committer of snapshot commits (default `telelean <telelean@localhost>`). */
  author: { name: string; email: string };
}

export interface ModelWorkspaceOptions {
  /** Absolute path of the model root (holds `.telelean/config.json`). */
  root: string;
  text: TextSource;
  applier: EditApplier;
  semantic?: Partial<SemanticSettings>;
  git?: Partial<GitSettings>;
  log?: WorkspaceLog;
  now?: () => Date;
  /** Version string written into graph.json's generator. */
  generatorVersion?: string;
  /** Test hook: replaces semantic.refreshLeanFacts. */
  refreshFacts?: (request: RefreshRequest) => Promise<LeanFacts>;
}

export interface WorkspaceChange {
  /** Subjects whose graph may have changed. */
  subjects: string[];
