 32	/** Verified dependencies: one solid `verified` edge per node in a proved node's footprint. */
 33	export function verifiedEdges(nodes: readonly TlNode[]): TlEdge[] {
 34	  const ids = new Set(nodes.map((n) => n.id));
 35	  const edges: TlEdge[] = [];
 36	  for (const node of nodes) {
 37	    if (node.status.proof.kind !== 'proved') continue;
 38	    for (const dep of node.status.proof.footprint) {
 39	      if (dep.startsWith(PRESUPPOSITION_PREFIX) || !ids.has(dep)) continue;
 40	      edges.push({
 41	        id: edgeId('verified', dep, node.id),
 42	        type: 'verified',
 43	        source: dep,
 44	        target: node.id,
 45	        origin: 'lean',
 46	        where: 'proof',
 47	      });
 48	    }
 49	  }
 50	  return edges;
 51	}
