106	    ids.add(node.id);
107	  }
108	  for (const node of graph.nodes) {
109	    for (const premise of node.premises) {
110	      if (premise === node.id) problems.push({ code: 'self-premise', message: `"${node.id}" lists itself as a premise` });
111	      else if (!ids.has(premise)) {
