  const edges: TlEdge[] = [];
  for (const node of nodes) {
    if (node.status.proof.kind !== 'proved') continue;
    for (const dep of node.status.proof.footprint) {
      if (dep.startsWith(PRESUPPOSITION_PREFIX) || !ids.has(dep)) continue;
      edges.push({
        id: edgeId('verified', dep, node.id),
        type: 'verified',
        source: dep,
        target: node.id,
        origin: 'lean',
        where: 'proof',
      });
    }
  }
  return edges;
}

