{
  "name": "telelean",
  "displayName": "telelean",
  "description": "Your mental model as a board of ASSUMPTION / DERIVATION / GOAL cards, backed by Lean 4 (personal prototype)",
  "version": "0.1.0",
  "publisher": "telelean",
  "private": true,
  "license": "UNLICENSED",
  "engines": {
    "vscode": "^1.140.0"
  },
  "categories": [
    "Visualization",
    "Other"
  ],
  "main": "./dist/extension.js",
  "activationEvents": [
    "workspaceContains:**/.telelean/config.json",
    "onWebviewPanel:telelean.board"
  ],
  "capabilities": {
    "untrustedWorkspaces": {
      "supported": false,
      "description": "telelean builds and checks the model folder with Lean, which can run code while it compiles."
    },
    "virtualWorkspaces": false
  },
  "contributes": {
    "commands": [
      {
        "command": "telelean.openBoard",
        "title": "Open Board",
        "category": "telelean"
      },
      {
        "command": "telelean.initializeModel",
        "title": "Initialize Model Here",
        "category": "telelean"
      },
      {
        "command": "telelean.refresh",
        "title": "Refresh Lean Check",
        "category": "telelean",
        "icon": "$(refresh)"
      }
    ],
    "menus": {
      "explorer/context": [
        {
          "command": "telelean.initializeModel",
          "when": "explorerResourceIsFolder",
          "group": "telelean@1"
        }
      ]
    },
    "configuration": {
      "title": "telelean",
      "properties": {
        "telelean.memory.capGiB": {
          "type": "number",
          "default": 4,
          "minimum": 1,
          "maximum": 64,
          "scope": "machine-overridable",
          "markdownDescription": "Memory cap in GiB for each sandboxed Lean build and check (systemd `MemoryMax`, no swap). Applies to boards opened after the change."
        },
        "telelean.memory.minAvailableGiB": {
          "type": "number",
          "default": 2,
          "minimum": 0,
          "maximum": 64,
          "scope": "machine-overridable",
          "markdownDescription": "Lean refreshes pause (\"paused: low memory\") while the system's available memory (`MemAvailable`) is below this many GiB. Applies to boards opened after the change."
        },
        "telelean.refresh.enabled": {
          "type": "boolean",
          "default": true,
          "scope": "resource",
          "markdownDescription": "Check the model with Lean (`lake build` plus a generated check file) while its board is open. Off: the board runs in syntactic mode. Applies to boards opened after the change."
        },
        "telelean.refresh.debounceMs": {
          "type": "integer",
          "default": 750,
          "minimum": 0,
          "maximum": 60000,
          "scope": "resource",
          "markdownDescription": "How long telelean waits after a save (or its own edit) before it re-checks the model with Lean, in milliseconds. Applies to boards opened after the change."
        },
        "telelean.git.snapshotRefs": {
          "type": "boolean",
          "default": true,
          "scope": "resource",
          "markdownDescription": "Record every change telelean makes as a private git ref (`refs/telelean/…`) in the model folder's own repository: the board's History dropdown, Revert and the storage counter. Never touches your branches, staging area or hooks. Applies to boards opened after the change."
        },
        "telelean.git.path": {
          "type": "string",
          "default": "git",
          "scope": "machine",
          "markdownDescription": "The `git` executable telelean uses for history snapshots (default: `git` on the PATH). Applies to boards opened after the change."
        }
      }
    },
    "colors": [
      {
        "id": "telelean.kindAssumption",
        "description": "Colour of ASSUMPTION cards and of the Assumptions column on the telelean board.",
        "defaults": { "dark": "#B180D7", "light": "#652D90", "highContrast": "#D2A8FF", "highContrastLight": "#5A1E8C" }
      },
      {
        "id": "telelean.kindDerivation",
        "description": "Colour of DERIVATION cards and of the Derivations column on the telelean board.",
        "defaults": { "dark": "#89D185", "light": "#388A34", "highContrast": "#8FE38A", "highContrastLight": "#1F6B1C" }
      },
      {
        "id": "telelean.kindGoal",
        "description": "Colour of GOAL cards and of the Goals column on the telelean board.",
        "defaults": { "dark": "#D18616", "light": "#A85F00", "highContrast": "#FFA94D", "highContrastLight": "#8F4A00" }
      },
      {
        "id": "telelean.formalizedAura",
        "description": "The aura around cards that are formalised in Lean.",
        "defaults": { "dark": "#3794FF", "light": "#1A85FF", "highContrast": "#6FC3FF", "highContrastLight": "#0F4A85" }
      },
      {
        "id": "telelean.vocabulary",
        "description": "Colour of the Vocabulary group and its items (types, predicates, constants) on the telelean board.",
        "defaults": { "dark": "#4EC9B0", "light": "#16825D", "highContrast": "#5EE3C6", "highContrastLight": "#0B5E43" }
      },
      {
        "id": "telelean.highlight",
        "description": "Highlight of the item an identifier in a card's Lean code refers to (click an identifier to highlight it).",
        "defaults": { "dark": "#E5C07B", "light": "#9A6700", "highContrast": "#FFE066", "highContrastLight": "#7A5200" }
      }
    ]
  },
  "scripts": {
    "build": "node scripts/build.mjs",
    "build:all": "npm --prefix ../webview run build && node scripts/build.mjs",
    "typecheck": "tsc -p tsconfig.json",
    "test:unit": "vitest run",
    "test:smoke": "node scripts/smoke.mjs",
    "test": "npm run typecheck && npm run build:all && npm run test:unit && npm run test:smoke"
  }
}

{
  // Type-check only: esbuild bundles src/ to dist/extension.js (CommonJS, `vscode` external).
  // `@telelean/core` and `@telelean/runner` resolve to their sources (no build step, no workspace link). The extension
  // imports only the runner's `semantic` and `workspace` subpaths (never the package root): `llm/` uses
  // `import.meta.url`, which means nothing in a CommonJS bundle (docs/m1-plan.md R8).
  "extends": "../../tsconfig.base.json",
  "compilerOptions": {
    "module": "Preserve",
    "moduleResolution": "Bundler",
    "lib": ["ES2023"],
    "types": ["node", "vscode", "mocha"],
    "noEmit": true,
    "paths": {
      "@telelean/core": ["../core/src/index.ts"],
      "@telelean/runner": ["../runner/src/index.ts"],
      "@telelean/runner/*": ["../runner/src/*"]
    }
  },
  "include": ["src", "test", "vitest.config.mts"]
}

import { fileURLToPath } from 'node:url';
import { defineConfig } from 'vitest/config';

const source = (path: string) => fileURLToPath(new URL(path, import.meta.url));

// Unit tests for host code that does not import `vscode` (src/logic, src/board/html.ts, the bundle check). Everything
// that needs VS Code runs in test/suite via @vscode/test-cli (npm run test:smoke). Core and runner resolve to their
// sources, as in tsconfig.json.
export default defineConfig({
  resolve: {
    alias: [
      { find: /^@telelean\/core$/, replacement: source('../core/src/index.ts') },
      { find: /^@telelean\/runner$/, replacement: source('../runner/src/index.ts') },
      { find: /^@telelean\/runner\/(.*)$/, replacement: `${source('../runner/src/')}$1` },
    ],
  },
  test: {
    include: ['test/unit/**/*.test.ts'],
    fileParallelism: false,
  },
});

/**
 * The `telelean.*` settings (package.json `contributes.configuration`) as the runner's workspace options.
 * Pure: the caller passes a getter (VS Code's `WorkspaceConfiguration.get` in the extension, a record in tests).
 */
import type { GitSettings, SemanticSettings } from '@telelean/runner/workspace/index.js';

/** Setting keys relative to the `telelean` section, with their package.json defaults. */
export const SETTING_DEFAULTS = {
  'memory.capGiB': 4,
  'memory.minAvailableGiB': 2,
  'refresh.enabled': true,
  'refresh.debounceMs': 750,
  'git.snapshotRefs': true,
  'git.path': 'git',
} as const;

export type SettingKey = keyof typeof SETTING_DEFAULTS;

/** Reads one setting; returns `fallback` when it is unset. */
export type SettingGetter = <K extends SettingKey>(key: K, fallback: (typeof SETTING_DEFAULTS)[K]) => unknown;

export interface TeleleanSettings {
  semantic: SemanticSettings;
  git: Pick<GitSettings, 'enabled' | 'gitPath'>;
}

const GIB = 1024 ** 3;

function finiteNumber(value: unknown, fallback: number, min: number, max: number): number {
  return typeof value === 'number' && Number.isFinite(value) ? Math.min(max, Math.max(min, value)) : fallback;
}

/**
 * runLean's `MemoryMax=` value for a cap in GiB: `4G` for whole numbers, otherwise a byte count (systemd accepts
 * both), so `2.5` is not truncated.
 */
export function memoryMaxFor(capGiB: number): string {
  return Number.isInteger(capGiB) ? `${capGiB}G` : String(Math.round(capGiB * GIB));
}

/** Out-of-range or mistyped values fall back to the defaults (or are clamped to the schema's bounds). */
export function readSettings(get: SettingGetter): TeleleanSettings {
  const capGiB = finiteNumber(get('memory.capGiB', SETTING_DEFAULTS['memory.capGiB']), SETTING_DEFAULTS['memory.capGiB'], 1, 64);
  const minAvailableGiB = finiteNumber(
    get('memory.minAvailableGiB', SETTING_DEFAULTS['memory.minAvailableGiB']),
    SETTING_DEFAULTS['memory.minAvailableGiB'],
    0,
    64,
  );
  const enabled = get('refresh.enabled', SETTING_DEFAULTS['refresh.enabled']);
  const debounceMs = finiteNumber(get('refresh.debounceMs', SETTING_DEFAULTS['refresh.debounceMs']), SETTING_DEFAULTS['refresh.debounceMs'], 0, 60_000);
  const snapshots = get('git.snapshotRefs', SETTING_DEFAULTS['git.snapshotRefs']);
  const gitPath = get('git.path', SETTING_DEFAULTS['git.path']);
  return {
    semantic: {
      enabled: typeof enabled === 'boolean' ? enabled : SETTING_DEFAULTS['refresh.enabled'],
      memoryMax: memoryMaxFor(capGiB),
      minAvailableBytes: Math.round(minAvailableGiB * GIB),
      debounceMs: Math.round(debounceMs),
    },
    git: {
      enabled: typeof snapshots === 'boolean' ? snapshots : SETTING_DEFAULTS['git.snapshotRefs'],
      gitPath: typeof gitPath === 'string' && gitPath.trim() !== '' ? gitPath.trim() : SETTING_DEFAULTS['git.path'],
    },
  };
}

/**
 * Paths inside a model root: the checks behind "Open in editor" (the webview's path is untrusted), the TextSource and
 * the EditApplier (the runner's paths are relative POSIX), and which file events matter to a workspace.
 * Pure apart from the optional `realpath` probe.
 */
import { realpath as fsRealpath } from 'node:fs/promises';
import * as path from 'node:path';

/** Thrown when a path would leave the model root (or is not a plain relative POSIX path). */
export class OutsideRootError extends Error {
  constructor(
    readonly file: string,
    reason: string,
  ) {
    super(`refused "${file}": ${reason}`);
    this.name = 'OutsideRootError';
  }
}

/** True when `absPath` lies strictly inside `root` (the root itself is not inside). */
export function isInside(root: string, absPath: string): boolean {
  const rel = path.relative(root, absPath);
  return rel !== '' && rel !== '..' && !rel.startsWith(`..${path.sep}`) && !path.isAbsolute(rel);
}

/** `absPath` relative to `root` as a POSIX path, or undefined when it is not inside the root. */
export function relativeModelPath(root: string, absPath: string): string | undefined {
  if (!isInside(root, absPath)) return undefined;
  return path.relative(root, absPath).split(path.sep).join('/');
}

/**
 * The absolute path of a model file given as a POSIX path relative to the root. Refuses absolute paths, backslashes,
 * NUL, and empty, `.` or `..` segments (the protocol already refuses them; the host checks again), and anything that
 * would resolve outside the root.
 */
export function resolveInsideRoot(root: string, file: string): string {
  if (file.length === 0) throw new OutsideRootError(file, 'empty path');
  if (file.startsWith('/') || /[\\\0]/.test(file)) throw new OutsideRootError(file, 'not a relative POSIX path');
  const segments = file.split('/');
  if (segments.some((s) => s === '' || s === '.' || s === '..')) throw new OutsideRootError(file, 'empty, "." or ".." segment');
  const absPath = path.join(root, ...segments);
  if (!isInside(root, absPath)) throw new OutsideRootError(file, 'outside the model root');
  return absPath;
}

/**
 * Like `resolveInsideRoot`, and when the file exists also checks its real path (symbolic links resolved) against the
 * root's real path, so a link inside the model folder cannot open a file elsewhere.
 */
export async function resolveModelFile(root: string, file: string, realpath: (p: string) => Promise<string> = fsRealpath): Promise<string> {
  const absPath = resolveInsideRoot(root, file);
  let real: string;
  try {
    real = await realpath(absPath);
  } catch {
    return absPath; // does not exist (yet): nothing to follow
  }
  const realRoot = await realpath(root).catch(() => root);
  if (!isInside(realRoot, real)) throw new OutsideRootError(file, 'links outside the model root');
  return absPath;
}

/** The innermost root that contains `absPath`, if any. */
export function rootOfPath(roots: Iterable<string>, absPath: string): string | undefined {
  let best: string | undefined;
  for (const root of roots) {
    if (isInside(root, absPath) && (best === undefined || root.length > best.length)) best = root;
  }
  return best;
}

/** What a changed file means for a model workspace. */
export interface ModelPathEvent {
  /** POSIX path relative to the root. */
  path: string;
  /** `model`: a Lean file; `sidecar`: under `.telelean/`; `project`: lakefile.toml, lean-toolchain, lake-manifest.json. */
  kind: 'model' | 'sidecar' | 'project';
  /** A Lean refresh is due even without a save (the project's build setup changed). */
  refresh: boolean;
}

/** Directories inside a root whose files never concern the board. */
const IGNORED_DIRS = new Set(['.lake', '.git', 'node_modules']);
/** Gitignored telelean outputs: writing them must not trigger anything (graph.json is rewritten after each refresh). */
const IGNORED_SIDECARS = ['.telelean/graph.json', '.telelean/frozen/', '.telelean/sessions/'];
const PROJECT_FILES = new Set(['lakefile.toml', 'lean-toolchain', 'lake-manifest.json']);

/**
 * Classifies a file event under `root`: undefined for files outside the root and for files that never concern the
 * board (`.lake/`, `.git/`, `.telelean/graph.json`, non-Lean files, ...).
 */
export function classifyModelPath(root: string, absPath: string): ModelPathEvent | undefined {
  const rel = relativeModelPath(root, absPath);
  if (rel === undefined) return undefined;
  const segments = rel.split('/');
  if (segments.some((s) => IGNORED_DIRS.has(s))) return undefined;
  if (rel.startsWith('.telelean/')) {
    if (IGNORED_SIDECARS.some((ignored) => (ignored.endsWith('/') ? rel.startsWith(ignored) : rel === ignored))) return undefined;
    return { path: rel, kind: 'sidecar', refresh: false };
  }
  if (PROJECT_FILES.has(rel)) return { path: rel, kind: 'project', refresh: true };
  if (rel.endsWith('.lean')) return { path: rel, kind: 'model', refresh: false };
  return undefined;
}

/**
 * The runner's TextSource for one model root: what the user sees. An open editor buffer (possibly unsaved) wins over
 * the file on disk, so the board, history snapshots and the EditApplier's `before` check all agree with the editor.
 */
import { readFile } from 'node:fs/promises';

import type { TextSource } from '@telelean/runner/workspace/index.js';

import { resolveInsideRoot } from './modelPaths';

export interface TextSourcePorts {
  /** The text of the open document for this absolute path, or undefined when no document is open for it. */
  openText(absPath: string): string | undefined;
  /** The file's text on disk, or null when it does not exist. */
  readFile(absPath: string): Promise<string | null>;
}

export function createTextSource(root: string, ports: TextSourcePorts): TextSource {
  return {
    async read(file: string): Promise<string | null> {
      const absPath = resolveInsideRoot(root, file);
      const open = ports.openText(absPath);
      if (open !== undefined) return open;
      return ports.readFile(absPath);
    },
  };
}

/**
 * Reads a file as UTF-8 the way VS Code shows it: a leading byte-order mark is dropped (VS Code's document text never
 * contains it). Missing files (or a missing parent directory) give null.
 */
export async function readTextFile(absPath: string): Promise<string | null> {
  try {
    const text = await readFile(absPath, 'utf8');
    return text.charCodeAt(0) === 0xfeff ? text.slice(1) : text;
  } catch (error) {
    const code = (error as NodeJS.ErrnoException).code;
    if (code === 'ENOENT' || code === 'ENOTDIR') return null;
    throw error;
  }
}

