/**
 * The EditApplier behind every board write (docs/m1-plan.md section 2, "board to files"), without the vscode API:
 *
 *   1. check that each file's current text (open buffer first, via the TextSource) still equals the change's
 *      `before` (`null`: the file must not exist); otherwise refuse with ActionError `conflict`, applying nothing;
 *   2. turn the whole-file changes into one batch of operations: minimal line-based text edits for files that are
 *      changed (so open editors keep their cursors, folds and undo history outside the edited lines), create and
 *      delete for files that appear or disappear;
 *   3. apply the batch (the extension: one `vscode.WorkspaceEdit`) and refuse when VS Code refuses it;
 *   4. save every file that was edited in place, so the change is on disk when `apply` resolves (D-17 "edits are
 *      saved immediately"; this also saves unsaved typing in those files, risk R4).
 */
import { ActionError, type FileChange, type Position, type Range } from '@telelean/core';
import type { EditApplier, TextSource } from '@telelean/runner/workspace/index.js';
import { diffLines } from 'diff';

import { OutsideRootError, resolveInsideRoot } from './modelPaths';

/** Replace `before.slice(start, end)` with `text` (offsets into the text the edits were computed from). */
export interface TextReplacement {
  start: number;
  end: number;
  text: string;
}

/** Beyond this, a whole-file replacement is cheaper than searching for a minimal diff. */
const DIFF_TIMEOUT_MS = 2000;

/**
 * Line-granular edits that turn `before` into `after`: one replacement per changed run of lines, non-overlapping
 * and in order (what VS Code expects of the edits for one document). Empty when the texts are equal.
 */
export function minimalTextEdits(before: string, after: string): TextReplacement[] {
  if (before === after) return [];
  const parts = diffLines(before, after, { timeout: DIFF_TIMEOUT_MS });
  if (!parts) return [{ start: 0, end: before.length, text: after }];
  const edits: TextReplacement[] = [];
  let offset = 0;
  let open: TextReplacement | undefined; // the replacement being built at the current offset
  for (const part of parts) {
    if (part.added) {
      if (open && open.end === offset) open.text += part.value;
      else edits.push((open = { start: offset, end: offset, text: part.value }));
    } else if (part.removed) {
      if (open && open.end === offset) open.end += part.value.length;
      else edits.push((open = { start: offset, end: offset + part.value.length, text: '' }));
      offset += part.value.length;
    } else {
      offset += part.value.length;
      open = undefined;
    }
  }
  return edits;
}

/** Applies replacements computed by `minimalTextEdits` (used by tests and to double-check a plan). */
export function applyTextReplacements(text: string, edits: readonly TextReplacement[]): string {
  let out = '';
  let cursor = 0;
  for (const edit of edits) {
    if (edit.start < cursor || edit.end < edit.start || edit.end > text.length) throw new RangeError('overlapping or out-of-range replacement');
    out += text.slice(cursor, edit.start) + edit.text;
    cursor = edit.end;
  }
  return out + text.slice(cursor);
}

/** Offsets where lines start; `\r\n`, `\n` and a lone `\r` each end a line (as in VS Code's text model). */
export function lineStarts(text: string): number[] {
  const starts = [0];
  for (let i = 0; i < text.length; i++) {
    const c = text.charCodeAt(i);
    if (c === 13) {
      if (text.charCodeAt(i + 1) === 10) i++;
      starts.push(i + 1);
    } else if (c === 10) {
      starts.push(i + 1);
    }
  }
  return starts;
}

/** The LSP position (0-based line, UTF-16 character) of an offset, given `lineStarts` of the same text. */
export function positionAt(starts: readonly number[], offset: number): Position {
  let low = 0;
  let high = starts.length - 1;
  while (low < high) {
    const mid = (low + high + 1) >> 1;
    if ((starts[mid] ?? 0) <= offset) low = mid;
    else high = mid - 1;
  }
  return { line: low, character: offset - (starts[low] ?? 0) };
}

/** One step of the batch for one file. Paths: `path` relative POSIX (for messages), `absPath` for the editor. */
export type FileOperation =
  | { kind: 'create'; path: string; absPath: string; text: string }
  | { kind: 'delete'; path: string; absPath: string }
  | { kind: 'edit'; path: string; absPath: string; edits: Array<{ range: Range; text: string }> };

/** The batch for `changes` (already checked); no-op changes produce nothing. */
export function planFileOperations(root: string, changes: readonly FileChange[]): FileOperation[] {
  const operations: FileOperation[] = [];
  for (const change of changes) {
    const absPath = resolveInsideRoot(root, change.path);
    if (change.before === change.after) continue;
    if (change.before === null && change.after !== null) {
      operations.push({ kind: 'create', path: change.path, absPath, text: change.after });
    } else if (change.before !== null && change.after === null) {
      operations.push({ kind: 'delete', path: change.path, absPath });
    } else if (change.before !== null && change.after !== null) {
      const starts = lineStarts(change.before);
      const edits = minimalTextEdits(change.before, change.after).map((edit) => ({
        range: { start: positionAt(starts, edit.start), end: positionAt(starts, edit.end) },
        text: edit.text,
      }));
      operations.push({ kind: 'edit', path: change.path, absPath, edits });
    }
  }
  return operations;
}

/** What the EditApplier needs from the editor (VS Code in the extension, fakes in unit tests). */
export interface WorkspaceEditPort {
  /** Applies the batch as one edit; resolves false when the editor refused it (nothing should then be applied). */
  apply(operations: readonly FileOperation[], label: string): Promise<boolean>;
  /** Saves the document of a file edited in place (a no-op when it is not dirty); false when it could not be saved. */
  save(absPath: string): Promise<boolean>;
}

export interface CheckedEditApplierOptions {
  root: string;
  text: TextSource;
  port: WorkspaceEditPort;
  log?: (level: 'info' | 'warn' | 'error', message: string) => void;
  /**
   * Told about each file just before the batch is applied (`text` = its content afterwards, null = deleted), so the
   * extension's watchers can recognise the echo of telelean's own write.
   */
  onWillWrite?: (writes: ReadonlyArray<{ absPath: string; text: string | null }>) => void;
}

export class CheckedEditApplier implements EditApplier {
  constructor(private readonly options: CheckedEditApplierOptions) {}

  async apply(changes: readonly FileChange[], label: string): Promise<void> {
    const { root, text, port, log, onWillWrite } = this.options;
    const seen = new Set<string>();
    for (const change of changes) {
      try {
        resolveInsideRoot(root, change.path);
      } catch (error) {
        if (error instanceof OutsideRootError) throw new ActionError('internal', `telelean refused to write ${error.message}`);
        throw error;
      }
      if (seen.has(change.path)) throw new ActionError('internal', `"${label}" changes ${change.path} twice`);
      seen.add(change.path);
    }

    const conflicts: string[] = [];
    for (const change of changes) {
      const current = await text.read(change.path);
      if (current !== change.before) conflicts.push(change.path);
    }
    if (conflicts.length > 0) {
      throw new ActionError('conflict', `${conflicts.join(', ')} changed since telelean planned "${label}"; nothing was applied.`);
    }

    const operations = planFileOperations(root, changes);
    if (operations.length === 0) return;
    onWillWrite?.(
      changes.filter((c) => c.before !== c.after).map((c) => ({ absPath: resolveInsideRoot(root, c.path), text: c.after })),
    );
    if (!(await port.apply(operations, label))) {
      throw new ActionError('conflict', `VS Code could not apply "${label}" (a file probably changed at the same moment); nothing was applied.`);
    }
    const unsaved: string[] = [];
    for (const operation of operations) {
      if (operation.kind === 'edit' && !(await port.save(operation.absPath))) unsaved.push(operation.path);
    }
    if (unsaved.length > 0) {
      throw new ActionError('internal', `"${label}" was applied, but ${unsaved.join(', ')} could not be saved: save it yourself, then Undo if needed.`);
    }
    log?.('info', `applied "${label}": ${operations.map((o) => `${o.kind} ${o.path}`).join(', ')}`);
  }
}

/**
 * Protocol messages (already validated by core's `parseWebviewToHost`) to the runner's BoardActions
 * (docs/m1-plan.md section 5.5). The board's current subject fills in what the message does not say.
 */
import type { BoardAction, WebviewToHostMessage } from '@telelean/core';

/** The webview messages that become a BoardAction (`ModelWorkspace.perform`). */
export const ACTION_MESSAGE_TYPES = ['addNode', 'kindChange', 'theseSuffice', 'editNode', 'deleteNode', 'reorder', 'createSubject'] as const;
export type ActionMessageType = (typeof ACTION_MESSAGE_TYPES)[number];
export type ActionMessage = Extract<WebviewToHostMessage, { type: ActionMessageType }>;

export function isActionMessage(message: WebviewToHostMessage): message is ActionMessage {
  return (ACTION_MESSAGE_TYPES as readonly string[]).includes(message.type);
}

/**
 * The BoardAction for an action message, or undefined when there is none: "These suffice" with no premises
 * ("Self-evident?") asks for a proof from nothing, which needs Claude (M2); the host answers it `not-yet`.
 * `addNode.clientId` is the webview's provisional id and never becomes the node's id (the host derives ids, 6.2).
 */
export function toBoardAction(message: ActionMessage, subject: string): BoardAction | undefined {
  switch (message.type) {
    case 'addNode': {
      const { type, naturalName, rationale, stance, source } = message.payload;
      return {
        kind: 'add-node',
        subject,
        type,
        naturalName,
        ...(rationale !== undefined ? { rationale } : {}),
        ...(stance !== undefined ? { stance } : {}),
        ...(source !== undefined ? { source } : {}),
      };
    }
    case 'kindChange': {
      const { id, to, beforeId, dependents, rationale } = message.payload;
      return {
        kind: 'change-kind',
        id,
        to,
        beforeId,
        ...(dependents !== undefined ? { dependents } : {}),
        ...(rationale !== undefined ? { rationale } : {}),
      };
    }
    case 'theseSuffice': {
      const { premises, target } = message.payload;
      if (premises.length === 0) return undefined;
      return { kind: 'set-premises', target, premises: [...premises] };
    }
    case 'editNode': {
      const { id, field, value } = message.payload;
      return { kind: 'edit-node', id, field, value };
    }
    case 'deleteNode': {
      const { id, keepLean } = message.payload;
      return { kind: 'delete-node', id, keepLean };
    }
    case 'reorder': {
      const { id, column, beforeId } = message.payload;
      return { kind: 'reorder', id, column, beforeId };
    }
    case 'createSubject':
      return { kind: 'create-subject', name: message.payload.name };
  }
}

/** The request id a message carries, if its type has one. */
export function requestIdOf(message: WebviewToHostMessage): string | undefined {
  const payload = message.payload as { requestId?: unknown };
  return typeof payload.requestId === 'string' ? payload.requestId : undefined;
}

/** Shown when "These suffice" is pressed with no premises. */
export const SELF_EVIDENT_NOT_YET = '"Self-evident?" (a proof from no premises) asks Claude for a proof, which arrives in M2. Select the premises that suffice to declare them.';

/**
 * One board's conversation with its model workspace (docs/m1-plan.md sections 3 and 5.5), without the vscode API:
 * validated webview messages in, BoardActions / undo / history calls to the runner's ModelWorkspace, and
 * `workspace` / `graph` / `history` / `actionResult` / `notice` messages back to the webview.
 *
 *   ready, onDidChange, subject switches  -> publish: `workspace` state, then the subject's `graph`
 *   action messages                       -> ws.perform(BoardAction) -> actionResult (requestId) + notice (Undo toast)
 *   undo / redo                           -> ws.undo / ws.redo for the board's subject, reported like an action
 *   history*                              -> listHistory / historyDiff (read-only diff editor) / revert / prune
 *   initGit                               -> a modal question in the host, then ws.initGit
 *   copyText / openInEditor / refresh     -> clipboard / editor (path re-checked inside the root) / ws.refreshNow
 *
 * Mutating messages run one at a time in arrival order; read-only ones (history listing and preview, copy, open,
 * refresh) do not wait behind them. When the board's subject disappears (undo of create-subject, a revert), the board
 * switches to the first remaining subject.
 */
import {
  ActionError,
  hostMessage,
  LIMITS,
  NotImplementedError,
  type ActionOutcome,
  type HistoryAvailability,
  type HistoryDiff,
  type HistoryListing,
  type HostToWebviewMessage,
  type NoticeLevel,
  type Range,
  type SubjectInfo,
  type WebviewToHostMessage,
  type WorkspaceState,
} from '@telelean/core';
import type { ModelWorkspace, WorkspaceChange } from '@telelean/runner/workspace/index.js';

import { isActionMessage, requestIdOf, SELF_EVIDENT_NOT_YET, toBoardAction, type ActionMessage } from './actionMapping';

export type LogLevel = 'info' | 'warn' | 'error';

/** Modal questions the host may ask (ids let tests answer them). */
export type ConfirmId = 'initGit';

/** What a session needs from the editor (VS Code in the extension, fakes in unit tests). */
export interface BoardSessionPorts {
  /** Posts to the webview; false when it was not delivered (e.g. the webview is still loading). */
  post(message: HostToWebviewMessage): Promise<boolean>;
  writeClipboard(text: string): Promise<void>;
  /** The absolute path of a model file named by the webview; throws when it is not inside the model root. */
  resolveFile(file: string): Promise<string>;
  openFile(absPath: string, range: Range | undefined): Promise<void>;
  /** Opens the read-only multi-file diff of a history entry. */
  showHistoryDiff(diff: HistoryDiff): Promise<void>;
  /** A modal question; true when the user chose `yes`. */
  confirm(id: ConfirmId, message: string, detail: string, yes: string): Promise<boolean>;
  /** The board now shows `subject` (remembered so a restored board shows it again). */
  subjectChanged(subject: string): void;
  log(level: LogLevel, message: string): void;
}

export interface BoardSessionOptions {
  root: string;
  /** Folder name of the root (the board's title and the `initGit` question). */
  rootName: string;
  workspace: ModelWorkspace;
  /** The subject to show first when it exists (restored or remembered); otherwise the first subject. */
  subject?: string;
  ports: BoardSessionPorts;
}

type OutcomeKind = 'action' | 'undo' | 'redo' | 'revert';

const INIT_GIT_DETAIL =
  "telelean records each change as a private ref (refs/telelean/…) in this folder's own repository. It never touches your branches, staging area or hooks, and never pushes.";

function errorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

/** The outcome for an exception from the runner (refusals normally arrive as `ok: false` outcomes instead). */
export function outcomeFromError(error: unknown): ActionOutcome {
  if (error instanceof ActionError) {
    return { ok: false, code: error.code, error: error.message, ...(error.dependents.length > 0 ? { dependents: [...error.dependents] } : {}) };
  }
  if (error instanceof NotImplementedError) return { ok: false, code: 'internal', error: `Not available in this build yet (${error.what}).` };
  return { ok: false, code: 'internal', error: errorMessage(error) };
}

export function emptyHistoryListing(subject: string): HistoryListing {
  return { subject, entries: [], storage: { subjectBytes: 0, totalBytes: 0, perSubject: {} }, more: false };
}

export function describeAvailability(availability: HistoryAvailability): string {
  switch (availability.state) {
    case 'ready':
      return 'History is on.';
    case 'no-repo':
      return 'The model folder is not inside a git repository.';
    case 'git-missing':
      return 'git was not found (setting telelean.git.path).';
    case 'disabled':
      return 'History snapshots are switched off (setting telelean.git.snapshotRefs).';
    case 'error':
      return `History error: ${availability.detail}`;
  }
}

const isNoHistory = (error: unknown) => error instanceof ActionError ? error.code === 'no-history' : (error as { code?: unknown } | null)?.code === 'no-history';

export class BoardSession {
  private current: string;
  private queue: Promise<void> = Promise.resolve();
  private publishing: Promise<void> | undefined;
  private publishAgain = false;
  private notices = 0;
  private disposed = false;

  constructor(private readonly options: BoardSessionOptions) {
    this.current = this.pickSubject(options.subject);
  }

  get root(): string {
    return this.options.root;
  }

  /** The subject the board shows ('' when the model has no subject yet). */
  get subject(): string {
    return this.current;
  }

  get workspace(): ModelWorkspace {
    return this.options.workspace;
  }

  /** Handles one validated message; resolves when its effects (posts included) are done. Never rejects. */
  async handle(message: WebviewToHostMessage): Promise<void> {
    try {
      switch (message.type) {
        case 'ready':
          return await this.requestPublish();
        case 'select':
        case 'diagnostic':
          return; // logged by the panel
        case 'copyText':
          return await this.copy(message.payload.text);
        case 'openInEditor':
          return await this.open(message.payload.file, message.payload.range);
        case 'refresh':
          return await this.refresh();
        case 'historyList':
          return await this.listHistory(message.payload.subject, message.payload.limit);
        case 'historyPreview':
          return await this.preview(message.payload.subject, message.payload.entryId, message.payload.compare);
        default:
          return await this.enqueue(() => this.handleInOrder(message));
      }
    } catch (error) {
      this.options.ports.log('error', `handling ${message.type} failed: ${errorMessage(error)}`);
      await this.notice('error', `telelean: ${errorMessage(error)}`, false);
    }
  }

  /** The workspace changed (typing, saves, refreshes, actions): republish (and switch away from a vanished subject). */
  onWorkspaceChange(change: WorkspaceChange): Promise<void> {
    void change;
    return this.requestPublish();
  }

  /**
   * Posts `workspace` then `graph` for the current subject. Calls during a publish coalesce into one more publish,
   * so a burst of changes costs at most two.
   */
  requestPublish(): Promise<void> {
    if (this.publishing) {
      this.publishAgain = true;
      return this.publishing;
    }
    const run = async () => {
      do {
        this.publishAgain = false;
        await this.publish();
      } while (this.publishAgain && !this.disposed);
    };
    this.publishing = run().finally(() => {
      this.publishing = undefined;
    });
    return this.publishing;
  }

  dispose(): void {
    this.disposed = true;
  }

  // ---------------------------------------------------------------------------------------------

  private enqueue(job: () => Promise<void>): Promise<void> {
    const run = this.queue.then(job);
    this.queue = run.catch(() => undefined);
    return run;
  }

  private async handleInOrder(message: WebviewToHostMessage): Promise<void> {
    if (isActionMessage(message)) return this.performMessage(message);
    const ws = this.options.workspace;
    switch (message.type) {
      case 'undo':
        return this.finish(await this.run(() => ws.undo(this.current)), message.payload.requestId, 'undo');
      case 'redo':
        return this.finish(await this.run(() => ws.redo(this.current)), message.payload.requestId, 'redo');
      case 'selectSubject':
        return this.selectSubject(message.payload.subject);
      case 'historyRevert': {
        const { subject, entryId, requestId } = message.payload;
        return this.finish(await this.run(() => ws.revert(subject, entryId)), requestId, 'revert');
      }
      case 'historyPrune':
        return this.prune(message.payload.subject, message.payload.keepLast, message.payload.requestId);
      case 'initGit':
        return this.initGit(message.payload.requestId);
      default:
        this.options.ports.log('warn', `unhandled message ${message.type}`);
    }
  }

  private async performMessage(message: ActionMessage): Promise<void> {
    const requestId = requestIdOf(message);
    const action = toBoardAction(message, this.current);
    if (!action) return this.finish({ ok: false, code: 'not-yet', error: SELF_EVIDENT_NOT_YET }, requestId, 'action');
    if (action.kind === 'add-node' && !this.current) {
      return this.finish({ ok: false, code: 'invalid', error: 'This model has no subject yet: create one first ("New subject…").' }, requestId, 'action');
    }
    const outcome = await this.run(() => this.options.workspace.perform(action));
    if (action.kind === 'create-subject' && outcome.ok && this.hasSubject(action.name)) this.switchTo(action.name);
    return this.finish(outcome, requestId, 'action');
  }

  private async run(job: () => Promise<ActionOutcome>): Promise<ActionOutcome> {
    try {
      return await job();
    } catch (error) {
      return outcomeFromError(error);
    }
  }

  /**
   * Reports an outcome: `actionResult` when the webview asked with a request id; an info notice with the label on
   * success (with Undo unless it was itself an undo/redo, where Undo would undo the previous action instead);
   * a warning notice on failure, except `needs-confirmation` answered through `actionResult` (the webview asks).
   */
  private async finish(outcome: ActionOutcome, requestId: string | undefined, kind: OutcomeKind): Promise<void> {
    if (requestId) await this.post(hostMessage('actionResult', { requestId, outcome }));
    if (outcome.ok) {
      await this.notice('info', outcome.label, outcome.undoable && kind !== 'undo' && kind !== 'redo');
    } else if (!(outcome.code === 'needs-confirmation' && requestId)) {
      await this.notice(outcome.code === 'internal' ? 'error' : 'warning', outcome.error, false);
    }
    await this.requestPublish();
  }

  private async selectSubject(subject: string): Promise<void> {
    if (!this.hasSubject(subject)) {
      await this.notice('warning', `There is no subject "${subject}" (any more).`, false);
    } else {
      this.switchTo(subject);
    }
    await this.requestPublish();
  }

  private async listHistory(subject: string, limit: number | undefined): Promise<void> {
    let listing: HistoryListing;
    try {
      listing = await this.options.workspace.listHistory(subject, limit);
    } catch (error) {
      if (!isNoHistory(error)) await this.notice('warning', `History: ${errorMessage(error)}`, false);
      listing = emptyHistoryListing(subject);
    }
    await this.post(hostMessage('history', { listing }));
  }

  private async preview(subject: string, entryId: string, compare: 'parent' | 'current'): Promise<void> {
    try {
      const diff = await this.options.workspace.historyDiff(subject, entryId, compare);
      if (diff.files.length === 0) {
        await this.notice('info', compare === 'current' ? 'No differences: the files match this entry.' : 'This entry changed no files.', false);
        return;
      }
      await this.options.ports.showHistoryDiff(diff);
    } catch (error) {
      await this.notice('warning', `Could not preview this history entry: ${errorMessage(error)}`, false);
    }
  }

  private async prune(subject: string, keepLast: number, requestId: string | undefined): Promise<void> {
    let outcome: ActionOutcome;
    try {
      const listing = await this.options.workspace.prune(subject, keepLast);
      await this.post(hostMessage('history', { listing }));
      outcome = { ok: true, label: `History of ${subject}: kept the last ${keepLast} ${keepLast === 1 ? 'entry' : 'entries'}`, undoable: false };
    } catch (error) {
      outcome = outcomeFromError(error);
    }
    return this.finish(outcome, requestId, 'action');
  }

  private async initGit(requestId: string | undefined): Promise<void> {
    const yes = await this.options.ports.confirm(
      'initGit',
      `Initialize a git repository in "${this.options.rootName}" for telelean's history?`,
      INIT_GIT_DETAIL,
      'Initialize git',
    );
    if (!yes) {
      if (requestId) {
        await this.post(hostMessage('actionResult', { requestId, outcome: { ok: false, code: 'no-history', error: 'Not initialized: history stays off.' } }));
      }
      return;
    }
    let outcome: ActionOutcome;
    try {
      const availability = await this.options.workspace.initGit();
      outcome =
        availability.state === 'ready'
          ? { ok: true, label: `Initialized a git repository in "${this.options.rootName}" for telelean's history`, undoable: false }
          : { ok: false, code: 'no-history', error: describeAvailability(availability) };
    } catch (error) {
      outcome = outcomeFromError(error);
    }
    return this.finish(outcome, requestId, 'action');
  }

  private async copy(text: string): Promise<void> {
    try {
      await this.options.ports.writeClipboard(text);
      await this.notice('info', 'Copied', false);
    } catch (error) {
      await this.notice('error', `Could not copy: ${errorMessage(error)}`, false);
    }
  }

  private async open(file: string, range: Range | undefined): Promise<void> {
    let absPath: string;
    try {
      absPath = await this.options.ports.resolveFile(file);
    } catch (error) {
      this.options.ports.log('warn', `openInEditor ${errorMessage(error)}`);
      await this.notice('warning', `Not opened: ${errorMessage(error)}`, false);
      return;
    }
    try {
      await this.options.ports.openFile(absPath, range);
    } catch (error) {
      await this.notice('warning', `Could not open ${file}: ${errorMessage(error)}`, false);
    }
  }

  private async refresh(): Promise<void> {
    try {
      await this.options.workspace.refreshNow();
    } catch (error) {
      await this.notice('warning', `Lean refresh failed: ${errorMessage(error)}`, false);
    }
    await this.requestPublish();
  }

  // ---------------------------------------------------------------------------------------------

  private async publish(): Promise<void> {
    if (this.disposed) return;
    const vanished = this.ensureSubject();
    if (vanished) {
      await this.notice(
        'info',
        this.current ? `Subject "${vanished}" no longer exists; showing "${this.current}".` : `Subject "${vanished}" no longer exists.`,
        false,
      );
    }
    await this.post(hostMessage('workspace', { state: await this.workspaceState() }));
    if (!this.current) return;
    try {
      await this.post(hostMessage('graph', { graph: this.options.workspace.graph(this.current) }));
    } catch (error) {
      this.options.ports.log('error', `graph(${this.current}) failed: ${errorMessage(error)}`);
    }
  }

  /** Switches away from a subject that no longer exists; returns its name when it did. */
  private ensureSubject(): string | undefined {
    if (this.current && this.hasSubject(this.current)) return undefined;
    const previous = this.current;
    const next = this.pickSubject(undefined);
    if (next === previous) return undefined;
    this.current = next;
    if (next) this.options.ports.subjectChanged(next);
    return previous || undefined;
  }

  private switchTo(subject: string): void {
    if (subject === this.current) return;
    this.current = subject;
    this.options.ports.subjectChanged(subject);
  }

  private subjects(): SubjectInfo[] {
    try {
      return this.options.workspace.subjects();
    } catch (error) {
      this.options.ports.log('error', `subjects() failed: ${errorMessage(error)}`);
      return [];
    }
  }

  private hasSubject(subject: string): boolean {
    return this.subjects().some((s) => s.name === subject);
  }

  private pickSubject(preferred: string | undefined): string {
    const subjects = this.subjects();
    if (preferred && subjects.some((s) => s.name === preferred)) return preferred;
    return subjects[0]?.name ?? '';
  }

  private async workspaceState(): Promise<WorkspaceState> {
    try {
      return await this.options.workspace.workspaceState(this.current);
    } catch (error) {
      this.options.ports.log('warn', `workspaceState(${this.current}) failed: ${errorMessage(error)}`);
      return {
        rootName: this.options.rootName,
        subjects: this.subjects().map((s) => ({ name: s.name, nodeCount: s.nodeCount })),
        subject: this.current,
        undo: null,
        redo: null,
        history: { state: 'error', detail: errorMessage(error) },
      };
    }
  }

  private notice(level: NoticeLevel, text: string, undoable: boolean): Promise<boolean> {
    const id = `n${Date.now().toString(36)}-${++this.notices}`;
    const clipped = text.length > LIMITS.textLength ? `${text.slice(0, LIMITS.textLength - 1)}…` : text;
    return this.post(hostMessage('notice', { id, level, text: clipped, undoable }));
  }

  private async post(message: HostToWebviewMessage): Promise<boolean> {
    if (this.disposed) return false;
    try {
      return await this.options.ports.post(message);
    } catch (error) {
      this.options.ports.log('warn', `posting ${message.type} failed: ${errorMessage(error)}`);
      return false;
    }
  }
}

/**
 * Which model root and subject a board shows after a window reload (D-22: the board is an editor tab that restores).
 *
 * VS Code hands the WebviewPanelSerializer the panel (with its title) and whatever state the webview saved with
 * `setState`. The host cannot write that state itself, so it keeps its own record per window (the extension's
 * workspaceState): one entry per board with its title, root and subject, updated whenever the subject changes.
 * Restoring matches, in order: a root (and subject) the webview saved, if any; the recorded entry with the panel's
 * title; the only root whose folder name the title names; the only model root of the window.
 */
import * as path from 'node:path';

/** What the host records for a board (and what a webview may save in its state). */
export interface BoardRecord {
  root: string;
  subject?: string;
  title: string;
}

export const BOARD_TITLE_PREFIX = 'telelean: ';

/** "telelean: <folder>", with the parent folder added when two model roots share a folder name. */
export function boardTitle(root: string, otherRoots: readonly string[] = []): string {
  const name = path.basename(root);
  const clash = otherRoots.some((other) => other !== root && path.basename(other) === name);
  return clash ? `${BOARD_TITLE_PREFIX}${name} (${path.basename(path.dirname(root))})` : `${BOARD_TITLE_PREFIX}${name}`;
}

function stringField(value: unknown, key: string): string | undefined {
  if (typeof value !== 'object' || value === null) return undefined;
  const field = (value as Record<string, unknown>)[key];
  return typeof field === 'string' && field.length > 0 ? field : undefined;
}

export interface RestoreInput {
  /** The webview's saved state (opaque; `root`/`subject` are used when present, also under a `telelean` key). */
  state: unknown;
  /** The restored panel's title. */
  title: string;
  /** Model roots known now (absolute paths). */
  roots: readonly string[];
  /** The host's records, newest first. */
  records: readonly BoardRecord[];
}

export interface RestoreTarget {
  root: string;
  subject?: string;
}

export function restoreTarget({ state, title, roots, records }: RestoreInput): RestoreTarget | undefined {
  const nested = typeof state === 'object' && state !== null ? (state as Record<string, unknown>)['telelean'] : undefined;
  for (const source of [state, nested]) {
    const root = stringField(source, 'root');
    if (root && (roots.includes(root) || records.some((r) => r.root === root))) {
      const subject = stringField(source, 'subject') ?? records.find((r) => r.root === root)?.subject;
      return subject ? { root, subject } : { root };
    }
  }
  const record = records.find((r) => r.title === title);
  if (record) return record.subject ? { root: record.root, subject: record.subject } : { root: record.root };
  if (title.startsWith(BOARD_TITLE_PREFIX)) {
    const named = roots.filter((root) => boardTitle(root, roots) === title || path.basename(root) === title.slice(BOARD_TITLE_PREFIX.length));
    if (named.length === 1 && named[0]) return withSubject(named[0], records);
  }
  if (roots.length === 1 && roots[0]) return withSubject(roots[0], records);
  return undefined;
}

function withSubject(root: string, records: readonly BoardRecord[]): RestoreTarget {
  const subject = records.find((r) => r.root === root)?.subject;
  return subject ? { root, subject } : { root };
}

/** The records after a board for `record.root` showed `record.subject` (newest first, one per root, at most 50). */
export function updateRecords(records: readonly BoardRecord[], record: BoardRecord): BoardRecord[] {
  return [record, ...records.filter((r) => r.root !== record.root)].slice(0, 50);
}

/** Reads records saved by an older or newer extension leniently. */
export function parseRecords(value: unknown): BoardRecord[] {
  if (!Array.isArray(value)) return [];
  const out: BoardRecord[] = [];
  for (const entry of value) {
    const root = stringField(entry, 'root');
    const title = stringField(entry, 'title');
    if (!root || !title) continue;
    const subject = stringField(entry, 'subject');
    out.push(subject ? { root, title, subject } : { root, title });
  }
  return out;
}

/**
 * "telelean: Initialize Model Here" (D-28, docs/m1-plan.md sections 3 and 7.2), without the vscode API:
 *
 *   1. inspect the folder (runner `inspectFolder`): empty, already a model, a dependency-free Lake project, or
 *      unsupported (with the reason, e.g. Lake dependencies such as Mathlib, which M1 refuses);
 *   2. empty folder: ask the first subject's name (validated; suggested from the folder name);
 *      Lake project: confirm adding `.telelean/` and `.gitignore` lines;
 *   3. plan the files (runner `planInitialize`) and write them through the EditApplier;
 *   4. when the folder is not inside a git repository, offer `git init` for telelean's history (modal);
 *   5. open the board.
 */
import * as path from 'node:path';

import { isSubjectName, SUBJECT_NAME_PATTERN, type FileChange, type HistoryAvailability } from '@telelean/core';
import type { FolderInspection, InitializeOptions } from '@telelean/runner/workspace/index.js';

/**
 * The suggested first subject for a folder: its name as a capitalised identifier (`mental_model` -> `MentalModel`,
 * `spyro notes` -> `SpyroNotes`); characters outside `[A-Za-z0-9]` separate words and are dropped; `Subject` when
 * nothing usable is left (or the result would start with a digit).
 */
export function defaultSubjectName(folderName: string): string {
  const words = folderName.split(/[^A-Za-z0-9]+/).filter((w) => w.length > 0);
  const candidate = words.map((w) => w.charAt(0).toUpperCase() + w.slice(1)).join('').slice(0, 64);
  return isSubjectName(candidate) ? candidate : 'Subject';
}

/** Why `value` is not a usable subject name (for the input box), or undefined when it is. */
export function subjectNameProblem(value: string): string | undefined {
  if (value.length === 0) return 'Type a name, e.g. Spyro.';
  if (SUBJECT_NAME_PATTERN.test(value)) return undefined;
  if (!/^[A-Z]/.test(value)) return 'Start with a capital letter (it becomes a Lean namespace and module name).';
  if (value.length > 64) return 'Use at most 64 characters.';
  return 'Use only letters, digits and "_" (it becomes a Lean namespace and module name).';
}

export interface InitializePorts {
  inspect(folder: string): Promise<FolderInspection>;
  /** Asks for the first subject (input box validated with `subjectNameProblem`); undefined = cancelled. */
  askSubject(folder: string, suggested: string): Promise<string | undefined>;
  /** Confirms adding telelean to an existing Lake project. */
  confirmLakeProject(folder: string, library: string, subjects: readonly string[]): Promise<boolean>;
  plan(options: InitializeOptions): FileChange[];
  /** Writes the planned files (EditApplier for that folder). */
  apply(folder: string, changes: readonly FileChange[]): Promise<void>;
  /** History availability of the new model root (`no-repo` when it is not inside a git repository). */
  historyStatus(folder: string): Promise<HistoryAvailability>;
  /** The modal "Initialize a git repository here for telelean's history?" offer. */
  offerGitInit(folder: string): Promise<boolean>;
  initGit(folder: string): Promise<HistoryAvailability>;
  openBoard(folder: string): Promise<void>;
  show(level: 'info' | 'warn' | 'error', message: string): void;
}

export type GitOutcome = 'initialized' | 'declined' | 'ready' | 'unavailable';

export type InitializeResult =
  | { status: 'initialized'; root: string; files: string[]; git: GitOutcome; gitDetail?: string; opened: boolean }
  | { status: 'already-model'; root: string; opened: boolean }
  | { status: 'unsupported'; root: string; reason: string }
  | { status: 'cancelled'; root: string }
  | { status: 'failed'; root: string; error: string };

const message = (error: unknown) => (error instanceof Error ? error.message : String(error));

export async function runInitialize(folder: string, ports: InitializePorts, options: { openBoard?: boolean } = {}): Promise<InitializeResult> {
  const openBoard = options.openBoard ?? true;
  const name = path.basename(folder);
  let inspection: FolderInspection;
  try {
    inspection = await ports.inspect(folder);
  } catch (error) {
    ports.show('error', `telelean could not inspect "${name}": ${message(error)}`);
    return { status: 'failed', root: folder, error: message(error) };
  }

  let subject: string;
  switch (inspection.kind) {
    case 'model':
      ports.show('info', `"${name}" is already a telelean model.`);
      if (openBoard) await ports.openBoard(folder);
      return { status: 'already-model', root: folder, opened: openBoard };
    case 'unsupported':
      ports.show('error', `telelean cannot initialize "${name}": ${inspection.reason}`);
      return { status: 'unsupported', root: folder, reason: inspection.reason };
    case 'empty': {
      const typed = await ports.askSubject(folder, defaultSubjectName(name));
      if (typed === undefined) return { status: 'cancelled', root: folder };
      if (subjectNameProblem(typed)) {
        const problem = `"${typed}" is not a subject name: ${subjectNameProblem(typed)}`;
        ports.show('error', problem);
        return { status: 'failed', root: folder, error: problem };
      }
      subject = typed;
      break;
    }
    case 'lake-project':
      if (!(await ports.confirmLakeProject(folder, inspection.library, inspection.subjects))) return { status: 'cancelled', root: folder };
      subject = inspection.subjects[0] ?? defaultSubjectName(name);
      break;
  }

  let changes: FileChange[];
  try {
    changes = ports.plan({ subject, inspection });
    await ports.apply(folder, changes);
  } catch (error) {
    ports.show('error', `telelean could not initialize "${name}": ${message(error)}`);
    return { status: 'failed', root: folder, error: message(error) };
  }

  let git: GitOutcome = 'unavailable';
  let gitDetail: string | undefined;
  try {
    const status = await ports.historyStatus(folder);
    if (status.state === 'ready') {
      git = 'ready';
    } else if (status.state === 'no-repo') {
      if (await ports.offerGitInit(folder)) {
        const after = await ports.initGit(folder);
        git = after.state === 'ready' ? 'initialized' : 'unavailable';
        if (after.state !== 'ready') gitDetail = after.state === 'error' ? after.detail : after.state;
      } else {
        git = 'declined';
      }
    } else {
      gitDetail = status.state === 'error' ? status.detail : status.state;
    }
  } catch (error) {
    gitDetail = message(error);
  }
  if (git === 'unavailable' && gitDetail) ports.show('warn', `telelean history is unavailable for "${name}": ${gitDetail}`);

  const files = changes.map((c) => c.path);
  ports.show('info', `Initialized the telelean model in "${name}" (${files.length} ${files.length === 1 ? 'file' : 'files'}).`);
  if (openBoard) await ports.openBoard(folder);
  return { status: 'initialized', root: folder, files, git, ...(gitDetail ? { gitDetail } : {}), opened: openBoard };
}

/**
 * Helpers for the extension's file watchers (docs/m1-plan.md section 2, "refresh triggers"): typing is batched per
 * model root (one `invalidate` after ~200 ms of quiet), and the echoes of telelean's own writes (the change, save and
 * file-system events its EditApplier causes) are recognised, since the workspace already knows those texts.
 */

/** Collects paths and calls `flush` once, `delayMs` after the last `add` (a trailing debounce). */
export class PathBatcher {
  private readonly pending = new Set<string>();
  private timer: ReturnType<typeof setTimeout> | undefined;

  constructor(
    private readonly delayMs: number,
    private readonly onFlush: (paths: string[]) => void,
  ) {}

  add(paths: Iterable<string>): void {
    for (const path of paths) this.pending.add(path);
    if (this.pending.size === 0) return;
    if (this.timer !== undefined) clearTimeout(this.timer);
    this.timer = setTimeout(() => this.flush(), this.delayMs);
  }

  /** Delivers what is pending now (e.g. before a save is handled, so the order of events is kept). */
  flush(): void {
    if (this.timer !== undefined) clearTimeout(this.timer);
    this.timer = undefined;
    if (this.pending.size === 0) return;
    const paths = [...this.pending].sort();
    this.pending.clear();
    this.onFlush(paths);
  }

  /** Drops `paths` from the pending set (they are being handled another way). */
  drop(paths: Iterable<string>): void {
    for (const path of paths) this.pending.delete(path);
  }

  get size(): number {
    return this.pending.size;
  }

  dispose(): void {
    if (this.timer !== undefined) clearTimeout(this.timer);
    this.timer = undefined;
    this.pending.clear();
  }
}

/**
 * The files telelean just wrote, with their new text (null = deleted), for a few seconds. An event whose text equals
 * the recorded one is an echo of telelean's own write. The first event with any other text (the user typed) forgets
 * the record, so a later return to the same text is not mistaken for an echo.
 */
export class SelfWrites {
  private readonly entries = new Map<string, { text: string | null; until: number }>();

  constructor(
    private readonly ttlMs = 5000,
    private readonly now: () => number = Date.now,
  ) {}

  record(writes: ReadonlyArray<{ absPath: string; text: string | null }>): void {
    const until = this.now() + this.ttlMs;
    for (const write of writes) this.entries.set(write.absPath, { text: write.text, until });
  }

  isEcho(absPath: string, text: string | null): boolean {
    const entry = this.entries.get(absPath);
    if (!entry) return false;
    if (entry.until < this.now() || entry.text !== text) {
      this.entries.delete(absPath);
      return false;
    }
    return true;
  }

  /** Whether a write to `absPath` is recorded and fresh (for events that carry no text). */
  has(absPath: string): boolean {
    const entry = this.entries.get(absPath);
    if (entry && entry.until < this.now()) this.entries.delete(absPath);
    return this.entries.has(absPath);
  }
}

/**
 * The read-only preview of a history entry (D-33, docs/m1-plan.md section 8 "Preview"): the runner's HistoryDiff
 * becomes VS Code's multi-file diff (`vscode.changes`) over documents served by a `telelean-history:` content
 * provider. This module holds the vscode-free part: titles, the documents' identities and a bounded store.
 */
import type { HistoryDiff } from '@telelean/core';

export const HISTORY_SCHEME = 'telelean-history';

/** One side of one file in a preview: `key` identifies the document (its URI query), `path` names the file. */
export interface PreviewDocument {
  key: string;
  path: string;
  text: string;
}

/** One row of the multi-file diff: absent sides are a created (no left) or deleted (no right) file. */
export interface PreviewRow {
  path: string;
  left?: PreviewDocument;
  right?: PreviewDocument;
}

function pad(n: number): string {
  return String(n).padStart(2, '0');
}

/** `2026-11-01 14:05` in local time (the ISO text itself when it does not parse). */
export function formatEntryTime(iso: string): string {
  const date = new Date(iso);
  if (Number.isNaN(date.getTime())) return iso;
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())} ${pad(date.getHours())}:${pad(date.getMinutes())}`;
}

export function previewTitle(diff: HistoryDiff): string {
  const against = diff.compare === 'parent' ? 'the state before it' : 'the files now';
  return `telelean history: ${diff.entry.label} (${formatEntryTime(diff.entry.time)}) vs ${against}`;
}

/**
 * The rows of a preview. `compare: 'parent'` shows what the entry changed (parent on the left, entry on the right);
 * `compare: 'current'` shows how the files now differ from the entry (entry on the left, current on the right): the
 * runner's FileChange `before`/`after` already follow that order.
 */
export function previewRows(diff: HistoryDiff, previewId: string): PreviewRow[] {
  return diff.files.map((file) => {
    const side = (name: 'before' | 'after', text: string | null): PreviewDocument | undefined =>
      text === null ? undefined : { key: `preview=${previewId}&side=${name}&entry=${diff.entry.id}`, path: file.path, text };
    const left = side('before', file.before);
    const right = side('after', file.after);
    return { path: file.path, ...(left ? { left } : {}), ...(right ? { right } : {}) };
  });
}

/** Documents of the last few previews (older ones are dropped; reopening shows a placeholder). */
export class PreviewStore {
  private readonly previews: Array<{ id: string; keys: string[] }> = [];
  private readonly texts = new Map<string, string>();

  constructor(private readonly keepPreviews = 10) {}

  add(id: string, rows: readonly PreviewRow[]): void {
    const keys: string[] = [];
    for (const row of rows) {
      for (const doc of [row.left, row.right]) {
        if (!doc) continue;
        this.texts.set(this.documentKey(doc.path, doc.key), doc.text);
        keys.push(this.documentKey(doc.path, doc.key));
      }
    }
    this.previews.push({ id, keys });
    while (this.previews.length > this.keepPreviews) {
      for (const key of this.previews.shift()?.keys ?? []) this.texts.delete(key);
    }
  }

  /** The text of a preview document by its URI path (`/<file>`) and query. */
  get(uriPath: string, query: string): string | undefined {
    return this.texts.get(this.documentKey(uriPath.replace(/^\/+/, ''), query));
  }

  private documentKey(path: string, query: string): string {
    return `${query}\u0000${path}`;
  }
}

export const EXPIRED_PREVIEW_TEXT =
  '// This telelean history preview is no longer available (it was opened in an earlier session, or many previews ago).\n// Open it again from the board: History ▸ Preview.\n';

/**
 * Choosing a model root for "Open Board" (D-28: multi-root workspaces get one board per opted-in root, and Open
 * Board asks which one).
 */
import * as path from 'node:path';

export type RootChoice =
  /** No model root: offer Initialize. */
  | { kind: 'none' }
  /** Exactly one: open it. */
  | { kind: 'single'; root: string }
  /** Several: ask (quick pick). */
  | { kind: 'ask'; roots: string[] };

export function chooseRoot(roots: readonly string[]): RootChoice {
  const unique = [...new Set(roots)].sort();
  if (unique.length === 0) return { kind: 'none' };
  if (unique.length === 1 && unique[0]) return { kind: 'single', root: unique[0] };
  return { kind: 'ask', roots: unique };
}

/** The root named by `wanted` (an absolute path, or a folder name that only one root has). */
export function matchRoot(roots: readonly string[], wanted: string): string | undefined {
  if (roots.includes(wanted)) return wanted;
  const resolved = path.resolve(wanted);
  if (roots.includes(resolved)) return resolved;
  const byName = roots.filter((root) => path.basename(root) === wanted);
  return byName.length === 1 ? byName[0] : undefined;
}

/** Quick-pick items for several roots: the folder name, and where it is relative to its workspace folder. */
export function rootPickItems(roots: readonly string[], workspaceFolders: readonly string[]): Array<{ label: string; description: string; root: string }> {
  return roots.map((root) => {
    const folder = workspaceFolders.find((f) => root === f || root.startsWith(`${f}${path.sep}`));
    const where = folder ? path.relative(path.dirname(folder), root) : root;
    return { label: path.basename(root), description: where.split(path.sep).join('/'), root };
  });
}

/** Workspace folders are searched for model roots up to this depth (keeps the scan cheap in large folders). */
export const ROOT_SEARCH_DEPTH = 6;

