/**
 * VS Code adapters for the runner's TextSource and EditApplier (the logic lives in ../logic/textSource.ts and
 * ../logic/editApplier.ts): open documents are read through `workspace.textDocuments`, writes go through one
 * `WorkspaceEdit` and `TextDocument.save`.
 */
import * as vscode from 'vscode';

import type { TextSource } from '@telelean/runner/workspace/index.js';

import { CheckedEditApplier, type FileOperation, type WorkspaceEditPort } from '../logic/editApplier';
import { createTextSource, readTextFile } from '../logic/textSource';

/** The open (possibly unsaved) document for an absolute file path, if VS Code has one. */
export function openDocument(absPath: string): vscode.TextDocument | undefined {
  return vscode.workspace.textDocuments.find((doc) => doc.uri.scheme === 'file' && doc.uri.fsPath === absPath && !doc.isClosed);
}

/** Reads model files the way the user sees them: an open editor buffer wins over the file on disk. */
export function vscodeTextSource(root: string): TextSource {
  return createTextSource(root, {
    openText: (absPath) => openDocument(absPath)?.getText(),
    readFile: readTextFile,
  });
}

/** Applies a batch as one `WorkspaceEdit` (text edits for changed files, create/delete for the others). */
export class VscodeWorkspaceEditPort implements WorkspaceEditPort {
  async apply(operations: readonly FileOperation[], label: string): Promise<boolean> {
    const edit = new vscode.WorkspaceEdit();
    for (const operation of operations) {
      const uri = vscode.Uri.file(operation.absPath);
      switch (operation.kind) {
        case 'create':
          edit.createFile(uri, { overwrite: false, contents: new TextEncoder().encode(operation.text) });
          break;
        case 'delete':
          edit.deleteFile(uri, { ignoreIfNotExists: false });
          break;
        case 'edit':
          for (const { range, text } of operation.edits) {
            edit.replace(uri, new vscode.Range(range.start.line, range.start.character, range.end.line, range.end.character), text);
          }
          break;
      }
    }
    void label;
    return vscode.workspace.applyEdit(edit, { isRefactoring: false });
  }

  async save(absPath: string): Promise<boolean> {
    const doc = openDocument(absPath) ?? (await vscode.workspace.openTextDocument(vscode.Uri.file(absPath)));
    if (!doc.isDirty) return true;
    return doc.save();
  }
}

/** The EditApplier for one model root (Initialize uses it before the root has a workspace). */
export function vscodeEditApplier(
  root: string,
  log: (level: 'info' | 'warn' | 'error', message: string) => void,
  onWillWrite?: (writes: ReadonlyArray<{ absPath: string; text: string | null }>) => void,
): CheckedEditApplier {
  return new CheckedEditApplier({
    root,
    text: vscodeTextSource(root),
    port: new VscodeWorkspaceEditPort(),
    log,
    ...(onWillWrite ? { onWillWrite } : {}),
  });
}

/**
 * The runner functions the extension calls (WP-workspace), gathered in one replaceable record: the in-VS-Code smoke
 * test swaps in a fake ModelWorkspace (extension mode Test only), so the panels, serializer, EditApplier, clipboard,
 * editor and diff paths are exercised before the real workspace exists.
 *
 * Only the runner's `workspace` subpath is imported (never the package root): `llm/` must stay out of the bundle.
 */
import {
  createModelWorkspace,
  findModelRoots,
  inspectFolder,
  planInitialize,
} from '@telelean/runner/workspace/index.js';

export interface RunnerFunctions {
  createModelWorkspace: typeof createModelWorkspace;
  findModelRoots: typeof findModelRoots;
  inspectFolder: typeof inspectFolder;
  planInitialize: typeof planInitialize;
}

export const DEFAULT_RUNNER: RunnerFunctions = { createModelWorkspace, findModelRoots, inspectFolder, planInitialize };

/**
 * One ModelWorkspace per model root (docs/m1-plan.md section 3): created lazily when the root's first board opens,
 * kept until the window closes (so in-board Undo survives closing and reopening the board), with the VS Code
 * TextSource/EditApplier and the file watchers that keep it in sync:
 *
 *   typing (onDidChangeTextDocument)        -> batched ~200 ms -> invalidate(paths)            (never builds)
 *   save (onDidSaveTextDocument)            -> invalidate(path) + requestRefresh('save')       (board open only)
 *   files changed outside the editor        -> invalidate(paths) (+ requestRefresh for lakefile.toml,
 *     (**\/*.lean, .telelean/**, lakefile.toml, lean-toolchain, lake-manifest.json)   lean-toolchain, manifest)
 *
 * Events under `.lake/`, for `.telelean/graph.json` (rewritten after every refresh) and the echoes of telelean's own
 * writes are ignored. Lean refreshes are requested only while the root's board is open (D-28).
 */
import * as path from 'node:path';
import * as vscode from 'vscode';

import type { ModelWorkspace, WorkspaceChange } from '@telelean/runner/workspace/index.js';

import { PathBatcher, SelfWrites } from '../logic/changeBatcher';
import { classifyModelPath, rootOfPath } from '../logic/modelPaths';
import type { TeleleanSettings } from '../logic/settings';
import { readTextFile } from '../logic/textSource';
import { openDocument, vscodeEditApplier, vscodeTextSource } from './editor';
import type { RunnerFunctions } from './runner';

export type Log = (level: 'info' | 'warn' | 'error', message: string) => void;

/** Typing is re-parsed after this much quiet (the plan's ~200 ms). */
export const TYPING_DEBOUNCE_MS = 200;
/** File events (git checkouts, external tools) come in bursts. */
const FILE_EVENT_DEBOUNCE_MS = 300;

export interface RegistryDeps {
  runner: () => RunnerFunctions;
  settingsFor: (root: string) => TeleleanSettings;
  generatorVersion: string;
  log: Log;
  /** Whether a board for `root` is open (Lean refreshes run only then). */
  isBoardOpen: (root: string) => boolean;
  /** Forwarded from each workspace's onDidChange. */
  onDidChange: (root: string, change: WorkspaceChange) => void;
}

interface Entry {
  root: string;
  workspace: ModelWorkspace;
  typing: PathBatcher;
  files: PathBatcher;
  /** Paths among `files` whose change should also trigger a Lean refresh. */
  refreshPaths: Set<string>;
  selfWrites: SelfWrites;
  disposables: vscode.Disposable[];
}

export class WorkspaceRegistry implements vscode.Disposable {
  private readonly loading = new Map<string, Promise<Entry>>();
  private readonly entries = new Map<string, Entry>();
  private readonly disposables: vscode.Disposable[] = [];

  constructor(private readonly deps: RegistryDeps) {
    this.disposables.push(
      vscode.workspace.onDidChangeTextDocument((event) => this.onTyping(event)),
      vscode.workspace.onDidSaveTextDocument((doc) => this.onSave(doc)),
    );
  }

  /** The root's workspace, created and loaded on first use. Rejects when it cannot be created or loaded. */
  async get(root: string): Promise<ModelWorkspace> {
    const existing = this.entries.get(root);
    if (existing) return existing.workspace;
    let pending = this.loading.get(root);
    if (!pending) {
      pending = this.create(root).finally(() => this.loading.delete(root));
      this.loading.set(root, pending);
    }
    return (await pending).workspace;
  }

  /** The root's workspace if it is already loaded. */
  peek(root: string): ModelWorkspace | undefined {
    return this.entries.get(root)?.workspace;
  }

  roots(): string[] {
    return [...this.entries.keys()];
  }

  /** Disposes one root's workspace (tests; a root that stopped being a model). */
  forget(root: string): void {
    const entry = this.entries.get(root);
    if (!entry) return;
    this.entries.delete(root);
    this.disposeEntry(entry);
  }

  dispose(): void {
    for (const entry of this.entries.values()) this.disposeEntry(entry);
    this.entries.clear();
    for (const disposable of this.disposables.splice(0)) disposable.dispose();
  }

  // ---------------------------------------------------------------------------------------------

  private async create(root: string): Promise<Entry> {
    const name = path.basename(root);
    const log: Log = (level, message) => this.deps.log(level, `[${name}] ${message}`);
    const selfWrites = new SelfWrites();
    const settings = this.deps.settingsFor(root);
    const workspace = this.deps.runner().createModelWorkspace({
      root,
      text: vscodeTextSource(root),
      applier: vscodeEditApplier(root, log, (writes) => selfWrites.record(writes)),
      semantic: settings.semantic,
      git: settings.git,
      log,
      generatorVersion: this.deps.generatorVersion,
    });
    try {
      await workspace.load();
    } catch (error) {
      workspace.dispose();
      throw error;
    }
    const entry: Entry = {
      root,
      workspace,
      selfWrites,
      refreshPaths: new Set(),
      typing: new PathBatcher(TYPING_DEBOUNCE_MS, (paths) => this.invalidate(entry, paths, false)),
      files: new PathBatcher(FILE_EVENT_DEBOUNCE_MS, (paths) => {
        const refresh = paths.some((p) => entry.refreshPaths.delete(p));
        this.invalidate(entry, paths, refresh);
      }),
      disposables: [],
    };
    const watcher = vscode.workspace.createFileSystemWatcher(
      new vscode.RelativePattern(vscode.Uri.file(root), '{**/*.lean,.telelean/**,lakefile.toml,lean-toolchain,lake-manifest.json}'),
    );
    entry.disposables.push(
      workspace.onDidChange((change) => this.deps.onDidChange(root, change)),
      watcher,
      watcher.onDidCreate((uri) => void this.onFileEvent(entry, uri, 'create')),
      watcher.onDidChange((uri) => void this.onFileEvent(entry, uri, 'change')),
      watcher.onDidDelete((uri) => void this.onFileEvent(entry, uri, 'delete')),
    );
    this.entries.set(root, entry);
    log('info', `model workspace loaded (${workspace.subjects().length} subjects)`);
    return entry;
  }

  private disposeEntry(entry: Entry): void {
    entry.typing.dispose();
    entry.files.dispose();
    for (const disposable of entry.disposables.splice(0)) disposable.dispose();
    entry.workspace.dispose();
  }

  private entryFor(uri: vscode.Uri): { entry: Entry; path: string; refresh: boolean } | undefined {
    if (uri.scheme !== 'file') return undefined;
    const root = rootOfPath(this.entries.keys(), uri.fsPath);
    const entry = root === undefined ? undefined : this.entries.get(root);
    if (!entry) return undefined;
    const event = classifyModelPath(entry.root, uri.fsPath);
    return event ? { entry, path: event.path, refresh: event.refresh } : undefined;
  }

  private onTyping(event: vscode.TextDocumentChangeEvent): void {
    if (event.contentChanges.length === 0) return;
    const hit = this.entryFor(event.document.uri);
    if (!hit || hit.entry.selfWrites.isEcho(event.document.uri.fsPath, event.document.getText())) return;
    hit.entry.typing.add([hit.path]);
  }

  private onSave(doc: vscode.TextDocument): void {
    const hit = this.entryFor(doc.uri);
    if (!hit || hit.entry.selfWrites.isEcho(doc.uri.fsPath, doc.getText())) return;
    hit.entry.typing.drop([hit.path]);
    hit.entry.typing.flush();
    void this.invalidate(hit.entry, [hit.path], true, 'save');
  }

  private async onFileEvent(entry: Entry, uri: vscode.Uri, kind: 'create' | 'change' | 'delete'): Promise<void> {
    const event = classifyModelPath(entry.root, uri.fsPath);
    if (!event) return;
    // Open documents are followed through their change events (VS Code reloads them when the file changes).
    if (kind !== 'delete' && openDocument(uri.fsPath)) return;
    if (entry.selfWrites.has(uri.fsPath)) {
      const text = kind === 'delete' ? null : await readTextFile(uri.fsPath).catch(() => undefined);
      if (text !== undefined && entry.selfWrites.isEcho(uri.fsPath, text)) return;
    }
    if (event.refresh) entry.refreshPaths.add(event.path);
    entry.files.add([event.path]);
  }

  private async invalidate(entry: Entry, paths: string[], refresh: boolean, reason = 'files'): Promise<void> {
    if (!this.entries.has(entry.root)) return;
    try {
      await entry.workspace.invalidate(paths);
    } catch (error) {
      this.deps.log('warn', `[${path.basename(entry.root)}] invalidate failed: ${error instanceof Error ? error.message : String(error)}`);
    }
    if (refresh && this.deps.isBoardOpen(entry.root)) entry.workspace.requestRefresh(reason);
  }
}

/**
 * The board's editor tab (D-22): a WebviewPanel showing one model root's board, or the static sample graph (the M0
 * prototype, kept for tests and as the fallback of a build without model workspaces).
 *
 * The panel validates everything the webview sends with core's `parseWebviewToHost` (the webview renders workspace
 * text, so its messages are untrusted) and hands it to the root's BoardSession. Messages that arrive while the
 * model workspace is still loading are kept and handled, in order, once the session is attached.
 */
import {
  hostMessage,
  largeGraph,
  parseWebviewToHost,
  spyroGraph,
  spyroProvedGraph,
  type HostToWebviewMessage,
  type NoticeLevel,
  type TlGraph,
  type WebviewToHostMessage,
} from '@telelean/core';
import { randomBytes } from 'node:crypto';
import * as vscode from 'vscode';

import type { BoardSession } from '../logic/boardSession';
import { renderBoardHtml } from './html';

/** The static sample graphs (M0); `openBoard({ sample })` shows one. */
export type SampleName = 'spyro' | 'spyro-proved' | 'large';
export const SAMPLE_NAMES: readonly SampleName[] = ['spyro', 'spyro-proved', 'large'];

export function sampleGraph(name: SampleName): TlGraph {
  switch (name) {
    case 'spyro':
      return spyroGraph();
    case 'spyro-proved':
      return spyroProvedGraph();
    case 'large':
      return largeGraph();
  }
}

export interface BoardPanelDeps {
  extensionUri: vscode.Uri;
  log: vscode.LogOutputChannel;
  /** Every validated message (the TeleleanApi events). `root` is undefined for the sample board. */
  onMessage(root: string | undefined, message: WebviewToHostMessage): void;
  /** Every message posted to a webview. */
  onPost(root: string | undefined, message: HostToWebviewMessage, delivered: boolean): void;
}

type Mode =
  | { kind: 'loading'; queued: WebviewToHostMessage[] }
  | { kind: 'session'; session: BoardSession }
  | { kind: 'sample'; graph: TlGraph; notice?: { level: NoticeLevel; text: string } }
  | { kind: 'failed'; text: string };

const SAMPLE_ACTION_NOTICE = 'This is the static sample board: open a model folder\'s board ("telelean: Open Board") to edit.';

export class BoardPanel implements vscode.Disposable {
  static readonly viewType = 'telelean.board';

  private mode: Mode = { kind: 'loading', queued: [] };
  private readonly disposables: vscode.Disposable[] = [];
  private readonly disposeEmitter = new vscode.EventEmitter<void>();
  private disposed = false;
  private notices = 0;
  /** Fired once when the panel closes (or the board is disposed). */
  readonly onDidDispose = this.disposeEmitter.event;

  /** A new editor tab for a board. */
  static createPanel(title: string, extensionUri: vscode.Uri): vscode.WebviewPanel {
    return vscode.window.createWebviewPanel(BoardPanel.viewType, title, vscode.ViewColumn.Active, {
      ...BoardPanel.webviewOptions(extensionUri),
      enableFindWidget: true,
      retainContextWhenHidden: true,
    });
  }

  static webviewOptions(extensionUri: vscode.Uri): vscode.WebviewOptions {
    return {
      enableScripts: true,
      enableCommandUris: false,
      localResourceRoots: [vscode.Uri.joinPath(extensionUri, 'dist', 'webview')],
    };
  }

  /**
   * Wraps a panel (new, or restored by the serializer) and loads the board into it. `root` is the model root, or
   * undefined for the sample board.
   */
  constructor(
    readonly panel: vscode.WebviewPanel,
    private readonly deps: BoardPanelDeps,
    readonly root: string | undefined,
  ) {
    const { webview } = panel;
    const webviewRoot = vscode.Uri.joinPath(deps.extensionUri, 'dist', 'webview');
    webview.options = BoardPanel.webviewOptions(deps.extensionUri);
    webview.html = renderBoardHtml({
      cspSource: webview.cspSource,
      nonce: randomBytes(18).toString('base64'),
      bootUri: webview.asWebviewUri(vscode.Uri.joinPath(webviewRoot, 'boot.js')).toString(),
      scriptUri: webview.asWebviewUri(vscode.Uri.joinPath(webviewRoot, 'webview.js')).toString(),
      styleUri: webview.asWebviewUri(vscode.Uri.joinPath(webviewRoot, 'webview.css')).toString(),
    });
    this.disposables.push(
      webview.onDidReceiveMessage((raw: unknown) => void this.receive(raw)),
      panel.onDidDispose(() => this.dispose()),
    );
    deps.log.info(`board opened: ${root ?? 'sample'} ("${panel.title}")`);
  }

  get session(): BoardSession | undefined {
    return this.mode.kind === 'session' ? this.mode.session : undefined;
  }

  get isSample(): boolean {
    return this.mode.kind === 'sample';
  }

  /** Attaches the model session and replays what the webview sent while the workspace loaded. */
  async attach(session: BoardSession): Promise<void> {
    const queued = this.mode.kind === 'loading' ? this.mode.queued : [];
    this.mode = { kind: 'session', session };
    await session.requestPublish(); // the webview may have said "ready" long ago, or may say it later
    for (const message of queued) if (message.type !== 'ready') await session.handle(message);
  }

  /** Shows a static sample graph (optionally with a notice, e.g. why it is not the model). */
  showSample(graph: TlGraph, notice?: { level: NoticeLevel; text: string }): void {
    this.mode = notice ? { kind: 'sample', graph, notice } : { kind: 'sample', graph };
    void this.postSample();
  }

  /** The board could not load its model: says why on every "ready". */
  fail(text: string): void {
    this.mode = { kind: 'failed', text };
    void this.postNotice('error', text);
  }

  /** Validates and handles one message from the webview (also the test API's simulated messages). */
  async receive(raw: unknown): Promise<void> {
    const parsed = parseWebviewToHost(raw);
    if (!parsed.ok) {
      this.deps.log.warn(`[webview->host] rejected message: ${parsed.error}`);
      return;
    }
    await this.handle(parsed.value);
  }

  async post(message: HostToWebviewMessage): Promise<boolean> {
    if (this.disposed) return false;
    let delivered = false;
    try {
      delivered = await this.panel.webview.postMessage(message);
    } catch {
      delivered = false;
    }
    const what = message.type === 'graph' ? `graph "${message.payload.graph.subject}" v${message.payload.graph.version}` : message.type;
    const line = `[host->webview] ${what}: ${delivered ? 'delivered' : 'not delivered (webview not ready)'}`;
    if (message.type === 'graph' || message.type === 'workspace' || message.type === 'history') this.deps.log.debug(line);
    else this.deps.log.info(`${line} ${JSON.stringify(message.payload).slice(0, 300)}`);
    this.deps.onPost(this.root, message, delivered);
    return delivered;
  }

  reveal(): void {
    this.panel.reveal();
  }

  dispose(): void {
    if (this.disposed) return;
    this.disposed = true;
    this.session?.dispose();
    for (const disposable of this.disposables.splice(0)) disposable.dispose();
    this.panel.dispose();
    this.deps.log.info(`board closed: ${this.root ?? 'sample'}`);
    this.disposeEmitter.fire();
    this.disposeEmitter.dispose();
  }

  // ---------------------------------------------------------------------------------------------

  private async handle(message: WebviewToHostMessage): Promise<void> {
    const line = `[webview->host] ${message.type} ${JSON.stringify(message.payload).slice(0, 500)}`;
    if (message.type === 'diagnostic' && message.payload.level === 'error') this.deps.log.error(line);
    else if (message.type === 'diagnostic' && message.payload.level === 'warn') this.deps.log.warn(line);
    else this.deps.log.info(line);
    this.deps.onMessage(this.root, message);

    switch (this.mode.kind) {
      case 'loading':
        this.mode.queued.push(message);
        return;
      case 'session':
        return this.mode.session.handle(message);
      case 'sample':
        if (message.type === 'ready') return this.postSample();
        if (message.type === 'select' || message.type === 'diagnostic' || message.type === 'copyText') {
          if (message.type === 'copyText') {
            await vscode.env.clipboard.writeText(message.payload.text);
            await this.postNotice('info', 'Copied');
          }
          return;
        }
        await this.postNotice('info', SAMPLE_ACTION_NOTICE);
        return;
      case 'failed':
        if (message.type === 'ready') await this.postNotice('error', this.mode.text);
        return;
    }
  }

  private async postSample(): Promise<void> {
    if (this.mode.kind !== 'sample') return;
    const { graph, notice } = this.mode;
    await this.post(hostMessage('graph', { graph }));
    if (notice) await this.postNotice(notice.level, notice.text);
  }

  private postNotice(level: NoticeLevel, text: string): Promise<boolean> {
    return this.post(hostMessage('notice', { id: `p${Date.now().toString(36)}-${++this.notices}`, level, text, undoable: false }));
  }
}

/**
 * The read-only `telelean-history:` documents behind a history preview, shown with VS Code's multi-file diff editor
 * (`vscode.changes`). Documents of a content provider cannot be edited or saved, so a preview never writes anything.
 */
import * as path from 'node:path';
import * as vscode from 'vscode';

import type { HistoryDiff } from '@telelean/core';

import { EXPIRED_PREVIEW_TEXT, HISTORY_SCHEME, previewRows, previewTitle, PreviewStore, type PreviewDocument } from '../logic/historyPreview';

export class HistoryPreviews implements vscode.TextDocumentContentProvider, vscode.Disposable {
  private readonly store = new PreviewStore();
  private readonly registration: vscode.Disposable;
  private counter = 0;

  constructor() {
    this.registration = vscode.workspace.registerTextDocumentContentProvider(HISTORY_SCHEME, this);
  }

  provideTextDocumentContent(uri: vscode.Uri): string {
    return this.store.get(uri.path, uri.query) ?? EXPIRED_PREVIEW_TEXT;
  }

  /** Opens the diff of one history entry; resolves with the title of the diff editor. */
  async show(diff: HistoryDiff, root: string): Promise<string> {
    const id = `${Date.now().toString(36)}${++this.counter}`;
    const rows = previewRows(diff, id);
    this.store.add(id, rows);
    const uri = (doc: PreviewDocument) => vscode.Uri.from({ scheme: HISTORY_SCHEME, path: `/${doc.path}`, query: doc.key });
    const resources = rows.map((row) => [
      vscode.Uri.file(path.join(root, ...row.path.split('/'))),
      row.left ? uri(row.left) : undefined,
      row.right ? uri(row.right) : undefined,
    ]);
    const title = previewTitle(diff);
    await vscode.commands.executeCommand('vscode.changes', title, resources);
    return title;
  }

  dispose(): void {
    this.registration.dispose();
  }
}

/**
 * What `activate` returns: tests (and later integrations) observe the boards through it. The `testing` member exists
 * only when VS Code runs the extension in Test mode (the @vscode/test-cli smoke test).
 */
import type { HostToWebviewMessage, WebviewToHostMessage } from '@telelean/core';
import type { ModelWorkspace } from '@telelean/runner/workspace/index.js';
import type * as vscode from 'vscode';

import type { BoardRecord } from './logic/restore';
import type { RunnerFunctions } from './vscode/runner';

export interface BoardMessageEvent {
  /** The board's model root; undefined for the sample board. */
  root: string | undefined;
  message: WebviewToHostMessage;
}

export interface BoardPostEvent {
  root: string | undefined;
  message: HostToWebviewMessage;
  /** False when the webview was not ready to receive it. */
  delivered: boolean;
}

export interface BoardInfo {
  root: string | undefined;
  panel: vscode.WebviewPanel;
  /** The subject the board shows (undefined for the sample or while the model loads). */
  subject: string | undefined;
  /** True for the static sample board. */
  sample: boolean;
}

/** Ids of the modal questions tests can answer in advance. */
export type PromptId = 'initGit' | 'initializeGit' | 'initializeLakeProject';

export interface TeleleanTesting {
  /** Replaces runner functions (e.g. with a fake ModelWorkspace); returns a function that restores them. */
  useRunner(overrides: Partial<RunnerFunctions>): () => void;
  /** Answers the given modal questions without showing them (until cleared with `undefined`). */
  answerPrompts(answers: Partial<Record<PromptId, boolean | undefined>>): void;
  /** Closes every board and disposes every model workspace (a clean slate between tests). */
  reset(): Promise<void>;
}

export interface TeleleanApi {
  /** Every validated message any board webview sends (M0). */
  readonly onDidReceiveBoardMessage: vscode.Event<WebviewToHostMessage>;
  /** The same, with the board it came from. */
  readonly onDidReceiveBoardEvent: vscode.Event<BoardMessageEvent>;
  /** Every message the host posts to a board webview. */
  readonly onDidPostToBoard: vscode.Event<BoardPostEvent>;
  /** The most recently opened board panel (model or sample), if it is still open. */
  readonly boardPanel: vscode.WebviewPanel | undefined;
  boards(): BoardInfo[];
  boardFor(root: string): BoardInfo | undefined;
  /** Runs `raw` through the same validation and dispatch as a message from that root's board webview. */
  simulateBoardMessage(root: string, raw: unknown): Promise<void>;
  /** The root's model workspace, once a board has created it (it lives until the window closes). */
  workspaceFor(root: string): ModelWorkspace | undefined;
  /** The serializer's restore path (VS Code calls it after a reload; tests pass a panel they created). */
  restoreBoard(panel: vscode.WebviewPanel, state: unknown): Promise<void>;
  /** What the host remembers for restoring boards (newest first). */
  boardRecords(): BoardRecord[];
  readonly testing?: TeleleanTesting;
}

/** Arguments of `telelean.openBoard` (all optional; the palette passes none). */
export interface OpenBoardArgs {
  /** Open this model root directly (must hold `.telelean/config.json`). */
  root?: string;
  /** Show this subject. */
  subject?: string;
  /** Answer for the root quick pick when there are several roots (an absolute path or a folder name). */
  pick?: string;
  /** Show a static sample graph instead of a model (M0 prototype; tests). */
  sample?: 'spyro' | 'spyro-proved' | 'large';
  /** When there is no model root: answer the "Initialize one?" offer (true runs Initialize, false does nothing). */
  offerInitialize?: boolean;
}

export interface OpenBoardResult {
  root?: string;
  /** True when several roots made the command ask which one. */
  asked: boolean;
  sample?: string;
  error?: string;
}

/** Arguments of `telelean.initializeModel` beyond the explorer's folder (tests answer the prompts with them). */
export interface InitializeArgs {
  folder?: string;
  /** Answer for the first-subject input box (empty folders). */
  subject?: string;
  /** Answer for "Add telelean to this Lake project?". */
  confirm?: boolean;
  /** Answer for the git offer. */
  gitInit?: boolean;
  /** Open the board afterwards (default true). */
  openBoard?: boolean;
}

export interface RefreshResult {
  root?: string;
  state?: string;
  error?: string;
}

/**
 * The extension host's controller (docs/m1-plan.md sections 2, 3 and 9 WP5): model roots, one board per root, the
 * model workspaces behind them, the three commands, the board serializer (D-22) and the test API.
 *
 *   Open Board      model roots per workspace folder (runner findModelRoots); several -> quick pick; none -> offer
 *                   Initialize; one board per root ("telelean: <folder>"), reused when it is already open
 *   Initialize      inspect -> first subject -> planInitialize -> EditApplier -> git offer -> open the board
 *   Refresh         `refreshNow` for the focused (or only) open board
 *   restore         after a reload, the serializer maps the restored panel back to its root and subject
 *
 * A folder without `.telelean/config.json` never gets a workspace, so nothing runs Lean there (D-28 opt-in).
 */
import { access } from 'node:fs/promises';
import * as path from 'node:path';
import * as vscode from 'vscode';

import {
  NotImplementedError,
  parseWebviewToHost,
  spyroGraph,
  webviewMessage,
  type HostToWebviewMessage,
  type NoticeLevel,
  type Range,
  type WebviewToHostMessage,
} from '@telelean/core';
import type { ModelWorkspace, WorkspaceChange } from '@telelean/runner/workspace/index.js';

import type {
  BoardInfo,
  BoardMessageEvent,
  BoardPostEvent,
  InitializeArgs,
  OpenBoardArgs,
  OpenBoardResult,
  PromptId,
  RefreshResult,
  TeleleanApi,
  TeleleanTesting,
} from '../api';
import { BoardPanel, SAMPLE_NAMES, sampleGraph, type SampleName } from '../board/BoardPanel';
import { BoardSession, type BoardSessionPorts, type ConfirmId } from '../logic/boardSession';
import { runInitialize, subjectNameProblem, type InitializePorts, type InitializeResult } from '../logic/initialize';
import { resolveModelFile } from '../logic/modelPaths';
import { boardTitle, parseRecords, restoreTarget, updateRecords, type BoardRecord } from '../logic/restore';
import { chooseRoot, matchRoot, ROOT_SEARCH_DEPTH, rootPickItems } from '../logic/roots';
import { readSettings, type TeleleanSettings } from '../logic/settings';
import { vscodeEditApplier } from './editor';
import { HistoryPreviews } from './historyProvider';
import { WorkspaceRegistry, type Log } from './registry';
import { DEFAULT_RUNNER, type RunnerFunctions } from './runner';

const RECORDS_KEY = 'telelean.boards';
export const SAMPLE_TITLE = 'telelean: sample';
const NOT_IMPLEMENTED_TEXT =
  'This build of telelean cannot read model folders yet (M1 integration pending): showing the static Spyro sample instead.';
const INIT_GIT_DETAIL =
  "telelean records each change as a private ref (refs/telelean/…) in this folder's own repository. It never touches your branches, staging area or hooks, and never pushes.";

const errorText = (error: unknown) => (error instanceof Error ? error.message : String(error));

async function isModelRoot(root: string): Promise<boolean> {
  try {
    await access(path.join(root, '.telelean', 'config.json'));
    return true;
  } catch {
    return false;
  }
}

function toVscodeRange(range: Range): vscode.Range {
  return new vscode.Range(range.start.line, range.start.character, range.end.line, range.end.character);
}

export class TeleleanHost implements vscode.Disposable {
  private runner: RunnerFunctions = DEFAULT_RUNNER;
  private readonly boards = new Map<string, BoardPanel>();
  private readonly orphans = new Set<BoardPanel>();
  private sample: BoardPanel | undefined;
  private lastPanel: BoardPanel | undefined;
  private readonly registry: WorkspaceRegistry;
  private readonly previews = new HistoryPreviews();
  private readonly messages = new vscode.EventEmitter<WebviewToHostMessage>();
  private readonly events = new vscode.EventEmitter<BoardMessageEvent>();
  private readonly posts = new vscode.EventEmitter<BoardPostEvent>();
  private readonly readyBoards = new WeakMap<BoardPanel, Promise<void>>();
  private promptAnswers: Partial<Record<PromptId, boolean>> = {};
  private readonly isTest: boolean;

  constructor(
    private readonly context: vscode.ExtensionContext,
    private readonly log: vscode.LogOutputChannel,
  ) {
    this.isTest = context.extensionMode === vscode.ExtensionMode.Test;
    this.registry = new WorkspaceRegistry({
      runner: () => this.runner,
      settingsFor: (root) => this.settingsFor(root),
      generatorVersion: String((context.extension.packageJSON as { version?: unknown }).version ?? '0.0.0'),
      log: this.logAt,
      isBoardOpen: (root) => this.boards.get(root)?.session !== undefined,
      onDidChange: (root, change) => this.onWorkspaceChange(root, change),
    });
  }

  /** Registers the commands, the serializer and the history document provider. */
  register(): void {
    this.context.subscriptions.push(
      this,
      vscode.commands.registerCommand('telelean.openBoard', (args?: OpenBoardArgs) => this.openBoardCommand(args)),
      vscode.commands.registerCommand('telelean.initializeModel', (arg?: vscode.Uri | InitializeArgs) => this.initializeCommand(arg)),
      vscode.commands.registerCommand('telelean.refresh', () => this.refreshCommand()),
      vscode.window.registerWebviewPanelSerializer(BoardPanel.viewType, {
        deserializeWebviewPanel: (panel, state) => this.restoreBoard(panel, state),
      }),
    );
  }

  // ---------------------------------------------------------------------------------------------
  // Commands

  async openBoardCommand(args?: OpenBoardArgs): Promise<OpenBoardResult> {
    if (args?.sample) {
      const name = SAMPLE_NAMES.includes(args.sample) ? args.sample : 'spyro';
      this.showSample(name);
      return { asked: false, sample: name };
    }
    if (args?.root) {
      const root = path.resolve(args.root);
      if (!(await isModelRoot(root))) {
        const error = `"${root}" is not a telelean model (no .telelean/config.json): run "telelean: Initialize Model Here" first.`;
        void vscode.window.showErrorMessage(error);
        return { asked: false, error };
      }
      await this.openBoard(root, args.subject);
      return { root, asked: false };
    }

    let roots: string[];
    try {
      roots = await this.findRoots();
    } catch (error) {
      if (error instanceof NotImplementedError) {
        this.showSample('spyro', { level: 'warning', text: NOT_IMPLEMENTED_TEXT });
        return { asked: false, sample: 'spyro', error: error.message };
      }
      void vscode.window.showErrorMessage(`telelean could not look for model folders: ${errorText(error)}`);
      return { asked: false, error: errorText(error) };
    }

    const choice = chooseRoot(roots);
    switch (choice.kind) {
      case 'none': {
        const error = 'There is no telelean model in this window.';
        if (args?.offerInitialize === true) {
          await vscode.commands.executeCommand('telelean.initializeModel');
        } else if (args?.offerInitialize === undefined && !this.isTest) {
          const initialize = 'Initialize Model Here…';
          void vscode.window.showInformationMessage(`${error} Initialize one?`, initialize).then((picked) => {
            if (picked === initialize) void vscode.commands.executeCommand('telelean.initializeModel');
          });
        }
        return { asked: false, error };
      }
      case 'single':
        await this.openBoard(choice.root, args?.subject);
        return { root: choice.root, asked: false };
      case 'ask': {
        const root = args?.pick !== undefined ? matchRoot(choice.roots, args.pick) : await this.pickRoot(choice.roots);
        if (!root) return { asked: true, error: args?.pick !== undefined ? `no model root matches "${args.pick}"` : 'cancelled' };
        await this.openBoard(root, args?.subject);
        return { root, asked: true };
      }
    }
  }

  async initializeCommand(arg?: vscode.Uri | InitializeArgs): Promise<InitializeResult | undefined> {
    const args: InitializeArgs = arg instanceof vscode.Uri ? { folder: arg.fsPath } : (arg ?? {});
    const folder = args.folder ? path.resolve(args.folder) : await this.pickFolderToInitialize();
    if (!folder) return undefined;
    const ports: InitializePorts = {
      inspect: (f) => this.runner.inspectFolder(f),
      askSubject: async (f, suggested) => {
        if (args.subject !== undefined) return args.subject;
        if (this.isTest) return undefined;
        return vscode.window.showInputBox({
          title: `telelean: Initialize Model Here (${path.basename(f)})`,
          prompt: 'Name of the first subject: a Lean namespace and module name, e.g. Spyro',
          value: suggested,
          ignoreFocusOut: true,
          validateInput: (value) => subjectNameProblem(value),
        });
      },
      confirmLakeProject: async (f, library, subjects) =>
        args.confirm ??
        this.confirm(
          'initializeLakeProject',
          `Add telelean to the Lake project "${path.basename(f)}"?`,
          `This creates .telelean/config.json (library ${library}) and a layout file for each subject (${subjects.join(', ') || 'none yet'}), and adds telelean's lines to .gitignore. Your Lean files are not changed.`,
          'Add telelean',
        ),
      plan: (options) => this.runner.planInitialize(options),
      apply: (f, changes) => vscodeEditApplier(f, this.logAt).apply(changes, 'Initialize model'),
      historyStatus: async (f) => (await this.registry.get(f)).historyStatus(),
      offerGitInit: async (f) =>
        args.gitInit ?? this.confirm('initializeGit', `Initialize a git repository in "${path.basename(f)}" for telelean's history?`, INIT_GIT_DETAIL, 'Initialize git'),
      initGit: async (f) => (await this.registry.get(f)).initGit(),
      openBoard: async (f) => {
        await this.openBoard(f);
      },
      show: (level, text) => {
        if (level === 'error') void vscode.window.showErrorMessage(text);
        else if (level === 'warn') void vscode.window.showWarningMessage(text);
        else void vscode.window.showInformationMessage(text);
      },
    };
    const result = await runInitialize(folder, ports, { openBoard: args.openBoard ?? true });
    this.log.info(`initialize ${folder}: ${JSON.stringify(result)}`);
    return result;
  }

  async refreshCommand(): Promise<RefreshResult> {
    const open = [...this.boards.values()].filter((board) => board.session);
    let board = open.find((b) => b.panel.active) ?? (open.length === 1 ? open[0] : undefined);
    if (!board && open.length > 1) {
      const picked = await vscode.window.showQuickPick(
        open.map((b) => ({ label: b.panel.title, board: b })),
        { title: 'telelean: Refresh Lean Check', placeHolder: 'Which board?' },
      );
      board = picked?.board;
      if (!board) return { error: 'cancelled' };
    }
    if (!board?.session) {
      const opened = await this.openBoardCommand();
      return opened.root ? { root: opened.root, state: 'opened' } : { error: opened.error ?? 'no board' };
    }
    const { session } = board;
    try {
      const summary = await session.workspace.refreshNow();
      await session.requestPublish();
      return { root: session.root, state: summary.state };
    } catch (error) {
      void vscode.window.showWarningMessage(`telelean: the Lean refresh failed: ${errorText(error)}`);
      return { root: session.root, error: errorText(error) };
    }
  }

  // ---------------------------------------------------------------------------------------------
  // Boards

  /** Opens (or reveals) the board of a model root; `restored` is a panel the serializer hands back after a reload. */
  async openBoard(root: string, subject?: string, restored?: vscode.WebviewPanel): Promise<BoardPanel> {
    const existing = this.boards.get(root);
    if (existing) {
      if (restored && restored !== existing.panel) restored.dispose();
      existing.reveal();
      this.lastPanel = existing;
      await this.readyBoards.get(existing);
      if (subject && existing.session && existing.session.subject !== subject) {
        await existing.session.handle(webviewMessage('selectSubject', { subject }));
      }
      return existing;
    }

    const records = this.records();
    const title = boardTitle(root, [...this.boards.keys(), ...records.map((r) => r.root)]);
    const panel = restored ?? BoardPanel.createPanel(title, this.context.extensionUri);
    if (restored) panel.title = title;
    const board = new BoardPanel(panel, this.panelDeps(), root);
    this.boards.set(root, board);
    this.lastPanel = board;
    board.onDidDispose(() => {
      if (this.boards.get(root) === board) this.boards.delete(root);
    });
    const wanted = subject ?? records.find((r) => r.root === root)?.subject;
    this.saveRecord(wanted ? { root, title, subject: wanted } : { root, title });

    const ready = this.attachSession(board, root, wanted);
    this.readyBoards.set(board, ready);
    await ready;
    return board;
  }

  private async attachSession(board: BoardPanel, root: string, subject: string | undefined): Promise<void> {
    let workspace: ModelWorkspace;
    try {
      workspace = await this.registry.get(root);
    } catch (error) {
      if (error instanceof NotImplementedError) {
        board.showSample(spyroGraph(), { level: 'warning', text: NOT_IMPLEMENTED_TEXT });
      } else {
        const text = `telelean could not load the model in "${path.basename(root)}": ${errorText(error)}`;
        board.fail(text);
        void vscode.window.showErrorMessage(text);
      }
      return;
    }
    if (this.boards.get(root) !== board) return; // closed while the workspace loaded
    const session = new BoardSession({
      root,
      rootName: path.basename(root),
      workspace,
      ...(subject ? { subject } : {}),
      ports: this.sessionPorts(root, board),
    });
    await board.attach(session);
    workspace.requestRefresh('open');
  }

  /** The serializer's path: maps a restored panel back to its model root and subject (D-22). */
  async restoreBoard(panel: vscode.WebviewPanel, state: unknown): Promise<void> {
    if (panel.title === SAMPLE_TITLE) {
      this.showSample('spyro', undefined, panel);
      return;
    }
    let roots: string[] = [];
    try {
      roots = await this.findRoots();
    } catch (error) {
      this.log.warn(`restore: could not list model roots: ${errorText(error)}`);
    }
    const target = restoreTarget({ state, title: panel.title, roots, records: this.records() });
    if (target && (await isModelRoot(target.root))) {
      this.log.info(`restoring board "${panel.title}" -> ${target.root} (${target.subject ?? 'first subject'})`);
      await this.openBoard(target.root, target.subject, panel);
      return;
    }
    const orphan = new BoardPanel(panel, this.panelDeps(), undefined);
    this.orphans.add(orphan);
    orphan.onDidDispose(() => this.orphans.delete(orphan));
    orphan.fail(`telelean could not find the model folder of this board ("${panel.title}"). Close this tab and run "telelean: Open Board".`);
  }

  private showSample(name: SampleName, notice?: { level: NoticeLevel; text: string }, restored?: vscode.WebviewPanel): BoardPanel {
    let board = this.sample;
    if (board && restored && restored !== board.panel) restored.dispose();
    if (!board) {
      const panel = restored ?? BoardPanel.createPanel(SAMPLE_TITLE, this.context.extensionUri);
      board = new BoardPanel(panel, this.panelDeps(), undefined);
      this.sample = board;
      const created = board;
      created.onDidDispose(() => {
        if (this.sample === created) this.sample = undefined;
      });
    } else {
      board.reveal();
    }
    board.showSample(sampleGraph(name), notice);
    this.readyBoards.set(board, Promise.resolve());
    this.lastPanel = board;
    return board;
  }

  private panelDeps() {
    return {
      extensionUri: this.context.extensionUri,
      log: this.log,
      onMessage: (root: string | undefined, message: WebviewToHostMessage) => {
        this.messages.fire(message);
        this.events.fire({ root, message });
      },
      onPost: (root: string | undefined, message: HostToWebviewMessage, delivered: boolean) => this.posts.fire({ root, message, delivered }),
    };
  }

  private sessionPorts(root: string, board: BoardPanel): BoardSessionPorts {
    return {
      post: (message) => board.post(message),
      writeClipboard: async (text) => {
        await vscode.env.clipboard.writeText(text);
      },
      resolveFile: (file) => resolveModelFile(root, file),
      openFile: async (absPath, range) => {
        const doc = await vscode.workspace.openTextDocument(vscode.Uri.file(absPath));
        await vscode.window.showTextDocument(doc, {
          viewColumn: vscode.ViewColumn.Beside,
          preview: false,
          ...(range ? { selection: toVscodeRange(range) } : {}),
        });
      },
      showHistoryDiff: async (diff) => {
        await this.previews.show(diff, root);
      },
      confirm: (id, message, detail, yes) => this.confirm(id, message, detail, yes),
      subjectChanged: (subject) => this.saveRecord({ root, title: board.panel.title, subject }),
      log: (level, message) => this.logAt(level, `[${path.basename(root)}] ${message}`),
    };
  }

  private onWorkspaceChange(root: string, change: WorkspaceChange): void {
    void this.boards.get(root)?.session?.onWorkspaceChange(change);
  }

  // ---------------------------------------------------------------------------------------------
  // Helpers

  /** Model roots in the window's (file) workspace folders. Rejects with NotImplementedError before integration. */
  private async findRoots(): Promise<string[]> {
    const folders = (vscode.workspace.workspaceFolders ?? []).filter((f) => f.uri.scheme === 'file');
    const lists = await Promise.all(folders.map((f) => this.runner.findModelRoots(f.uri.fsPath, { maxDepth: ROOT_SEARCH_DEPTH })));
    return [...new Set(lists.flat())].sort();
  }

  private async pickRoot(roots: string[]): Promise<string | undefined> {
    const folders = (vscode.workspace.workspaceFolders ?? []).map((f) => f.uri.fsPath);
    const picked = await vscode.window.showQuickPick(rootPickItems(roots, folders), {
      title: 'telelean: Open Board',
      placeHolder: 'Which model?',
    });
    return picked?.root;
  }

  private async pickFolderToInitialize(): Promise<string | undefined> {
    const folders = (vscode.workspace.workspaceFolders ?? []).filter((f) => f.uri.scheme === 'file');
    if (folders.length > 0) {
      const items: Array<vscode.QuickPickItem & { folder?: string }> = [
        ...folders.map((f) => ({ label: f.name, description: f.uri.fsPath, folder: f.uri.fsPath })),
        { label: 'Choose another folder…' },
      ];
      const picked = await vscode.window.showQuickPick(items, {
        title: 'telelean: Initialize Model Here',
        placeHolder: 'Which folder should hold the model? (An empty folder, or a Lake project without dependencies.)',
      });
      if (!picked) return undefined;
      if (picked.folder) return picked.folder;
    }
    const uris = await vscode.window.showOpenDialog({
      canSelectFolders: true,
      canSelectFiles: false,
      canSelectMany: false,
      openLabel: 'Initialize Model Here',
      ...(folders[0] ? { defaultUri: folders[0].uri } : {}),
    });
    return uris?.[0]?.fsPath;
  }

  /** A modal yes/no question; tests answer in advance, and in Test mode an unanswered question counts as "no". */
  private async confirm(id: ConfirmId | PromptId, message: string, detail: string, yes: string): Promise<boolean> {
    const preset = this.promptAnswers[id];
    if (preset !== undefined) return preset;
    if (this.isTest) {
      this.log.warn(`prompt "${id}" not answered by the test: treated as "no" (${message})`);
      return false;
    }
    return (await vscode.window.showInformationMessage(message, { modal: true, detail }, yes)) === yes;
  }

  private settingsFor(root: string): TeleleanSettings {
    const config = vscode.workspace.getConfiguration('telelean', vscode.Uri.file(root));
    return readSettings((key, fallback) => config.get(key, fallback));
  }

  private records(): BoardRecord[] {
    return parseRecords(this.context.workspaceState.get<unknown>(RECORDS_KEY));
  }

  private saveRecord(record: BoardRecord): void {
    void this.context.workspaceState.update(RECORDS_KEY, updateRecords(this.records(), record));
  }

  private readonly logAt: Log = (level, message) => {
    if (level === 'error') this.log.error(message);
    else if (level === 'warn') this.log.warn(message);
    else this.log.info(message);
  };

  private info(board: BoardPanel): BoardInfo {
    return { root: board.root, panel: board.panel, subject: board.session?.subject, sample: board.isSample };
  }

  // ---------------------------------------------------------------------------------------------
  // API

  api(): TeleleanApi {
    const host = this;
    const testing: TeleleanTesting = {
      useRunner: (overrides) => {
        const previous = host.runner;
        host.runner = { ...previous, ...overrides };
        return () => {
          host.runner = previous;
        };
      },
      answerPrompts: (answers) => {
        for (const [id, answer] of Object.entries(answers) as Array<[PromptId, boolean | undefined]>) {
          if (answer === undefined) delete host.promptAnswers[id];
          else host.promptAnswers[id] = answer;
        }
      },
      reset: async () => {
        for (const board of [...host.boards.values(), ...host.orphans, ...(host.sample ? [host.sample] : [])]) board.dispose();
        for (const root of host.registry.roots()) host.registry.forget(root);
        host.promptAnswers = {};
        await host.context.workspaceState.update(RECORDS_KEY, undefined);
      },
    };
    return {
      onDidReceiveBoardMessage: this.messages.event,
      onDidReceiveBoardEvent: this.events.event,
      onDidPostToBoard: this.posts.event,
      get boardPanel() {
        const last = host.lastPanel;
        return last && (last === host.sample || [...host.boards.values()].includes(last)) ? last.panel : undefined;
      },
      boards: () => [...this.boards.values(), ...(this.sample ? [this.sample] : [])].map((b) => this.info(b)),
      boardFor: (root) => {
        const board = this.boards.get(root);
        return board ? this.info(board) : undefined;
      },
      simulateBoardMessage: async (root, raw) => {
        const board = this.boards.get(root);
        if (!board) throw new Error(`no board is open for ${root}`);
        const parsed = parseWebviewToHost(raw);
        if (!parsed.ok) throw new Error(`invalid message: ${parsed.error}`);
        await this.readyBoards.get(board);
        await board.receive(raw);
      },
      workspaceFor: (root) => this.registry.peek(root),
      restoreBoard: (panel, state) => this.restoreBoard(panel, state),
      boardRecords: () => this.records(),
      ...(this.isTest ? { testing } : {}),
    };
  }

  dispose(): void {
    for (const board of [...this.boards.values(), ...this.orphans]) board.dispose();
    this.sample?.dispose();
    this.registry.dispose();
    this.previews.dispose();
    this.messages.dispose();
    this.events.dispose();
    this.posts.dispose();
  }
}

/**
 * telelean's VS Code extension (the thin host of docs/m1-plan.md section 2): commands, one board per model root,
 * the model workspaces behind them (runner), and the board serializer. Activation is cheap: nothing reads model
 * files or runs Lean until a board opens (D-28).
 */
import * as vscode from 'vscode';

import type { TeleleanApi } from './api';
import { TeleleanHost } from './vscode/host';

export type { BoardInfo, BoardMessageEvent, BoardPostEvent, InitializeArgs, OpenBoardArgs, OpenBoardResult, RefreshResult, TeleleanApi } from './api';

export function activate(context: vscode.ExtensionContext): TeleleanApi {
  const log = vscode.window.createOutputChannel('telelean', { log: true });
  context.subscriptions.push(log);
  const host = new TeleleanHost(context, log);
  host.register();
  log.info(`telelean activated (VS Code ${vscode.version}, mode ${vscode.ExtensionMode[context.extensionMode]})`);
  return host.api();
}

export function deactivate(): void {}

/**
 * Test doubles for the vscode-free host logic: an in-memory ModelWorkspace and recording BoardSession ports.
 */
import {
  spyroGraph,
  type ActionOutcome,
  type BoardAction,
  type HistoryAvailability,
  type HistoryDiff,
  type HistoryListing,
  type HostToWebviewMessage,
  type Range,
  type SemanticSummary,
  type SubjectInfo,
  type TlGraph,
  type WorkspaceState,
} from '@telelean/core';
import type { Disposable, ModelWorkspace, WorkspaceChange } from '@telelean/runner/workspace/index.js';

import type { BoardSessionPorts, ConfirmId, LogLevel } from '../../src/logic/boardSession';

export class FakeWorkspace implements ModelWorkspace {
  readonly root: string;
  subjectList: SubjectInfo[] = [{ name: 'Spyro', nodeCount: 4, files: ['Model/Spyro/Main.lean'] }];
  performed: BoardAction[] = [];
  undone: string[] = [];
  redone: string[] = [];
  reverted: Array<{ subject: string; entryId: string }> = [];
  pruned: Array<{ subject: string; keepLast: number }> = [];
  refreshRequests: string[] = [];
  refreshNowCalls = 0;
  initGitCalls = 0;
  invalidated: string[][] = [];
  version = 100;
  history: HistoryAvailability = { state: 'ready' };
  /** The outcome `perform` returns (or computes). */
  outcome: ActionOutcome | ((action: BoardAction) => ActionOutcome) = (action) => ({ ok: true, label: `did ${action.kind}`, undoable: true });
  /** Called by `perform` before it returns (e.g. to change the subjects, as create-subject would). */
  onPerform?: (action: BoardAction) => void;
  listHistoryError?: unknown;
  diff?: HistoryDiff;
  private readonly listeners = new Set<(change: WorkspaceChange) => void>();

  constructor(root = '/models/spyro') {
    this.root = root;
  }

  async load(): Promise<void> {}
  subjects(): SubjectInfo[] {
    return this.subjectList;
  }
  graph(subject: string): TlGraph {
    if (!this.subjectList.some((s) => s.name === subject)) throw new Error(`unknown subject ${subject}`);
    return { ...spyroGraph(), subject, version: this.version };
  }
  async workspaceState(subject: string): Promise<WorkspaceState> {
    return {
      rootName: 'spyro',
      subjects: this.subjectList.map((s) => ({ name: s.name, nodeCount: s.nodeCount })),
      subject,
      undo: this.performed.length > 0 ? 'last action' : null,
      redo: null,
      history: this.history,
    };
  }
  semantic(): SemanticSummary {
    return { state: 'unavailable' };
  }
  onDidChange(listener: (change: WorkspaceChange) => void): Disposable {
    this.listeners.add(listener);
    return { dispose: () => this.listeners.delete(listener) };
  }
  fire(change: WorkspaceChange): void {
    for (const listener of this.listeners) listener(change);
  }
  async invalidate(paths: readonly string[]): Promise<void> {
    this.invalidated.push([...paths]);
  }
  requestRefresh(reason: string): void {
    this.refreshRequests.push(reason);
  }
  async refreshNow(): Promise<SemanticSummary> {
    this.refreshNowCalls++;
    return { state: 'fresh' };
  }
  async perform(action: BoardAction): Promise<ActionOutcome> {
    this.performed.push(action);
    this.onPerform?.(action);
    this.version++;
    return typeof this.outcome === 'function' ? this.outcome(action) : this.outcome;
  }
  async undo(subject: string): Promise<ActionOutcome> {
    this.undone.push(subject);
    return { ok: true, label: 'Undo: did something', undoable: true };
  }
  async redo(subject: string): Promise<ActionOutcome> {
    this.redone.push(subject);
    return { ok: true, label: 'Redo: did something', undoable: true };
  }
  async historyStatus(): Promise<HistoryAvailability> {
    return this.history;
  }
  async listHistory(subject: string, limit?: number): Promise<HistoryListing> {
    if (this.listHistoryError) throw this.listHistoryError;
    const entries = [{ id: 'abc1234', time: '2026-11-01T10:00:00.000Z', action: 'initial' as const, label: 'Initial state', subject, nodes: [] }];
    return { subject, entries: entries.slice(0, limit ?? 50), storage: { subjectBytes: 10, totalBytes: 20, perSubject: { [subject]: 10 } }, more: false };
  }
  async historyDiff(subject: string, entryId: string, compare: 'parent' | 'current'): Promise<HistoryDiff> {
    return (
      this.diff ?? {
        entry: { id: entryId, time: '2026-11-01T10:00:00.000Z', action: 'add-node', label: 'Add assumption: x', subject, nodes: [] },
        compare,
        files: [{ path: 'Model/Spyro/Inbox.lean', before: 'a\n', after: 'a\nb\n' }],
      }
    );
  }
  async revert(subject: string, entryId: string): Promise<ActionOutcome> {
    this.reverted.push({ subject, entryId });
    return { ok: true, label: 'Revert to: Initial state (2026-11-01 10:00)', undoable: true };
  }
  async prune(subject: string, keepLast: number): Promise<HistoryListing> {
    this.pruned.push({ subject, keepLast });
    return { subject, entries: [], storage: { subjectBytes: 0, totalBytes: 0, perSubject: {} }, more: false };
  }
  async initGit(): Promise<HistoryAvailability> {
    this.initGitCalls++;
    this.history = { state: 'ready' };
    return this.history;
  }
  dispose(): void {}
}

export class RecordingPorts implements BoardSessionPorts {
  posts: HostToWebviewMessage[] = [];
  clipboard: string[] = [];
  opened: Array<{ absPath: string; range: Range | undefined }> = [];
  diffs: HistoryDiff[] = [];
  confirms: Array<{ id: ConfirmId; message: string }> = [];
  subjects: string[] = [];
  logs: Array<{ level: LogLevel; message: string }> = [];
  confirmAnswer = true;
  /** Absolute paths `resolveFile` accepts (relative file -> absolute); anything else is refused. */
  files = new Map<string, string>([['Model/Spyro/Main.lean', '/models/spyro/Model/Spyro/Main.lean']]);

  async post(message: HostToWebviewMessage): Promise<boolean> {
    this.posts.push(message);
    return true;
  }
  async writeClipboard(text: string): Promise<void> {
    this.clipboard.push(text);
  }
  async resolveFile(file: string): Promise<string> {
    const absPath = this.files.get(file);
    if (!absPath) throw new Error(`refused "${file}": outside the model root`);
    return absPath;
  }
  async openFile(absPath: string, range: Range | undefined): Promise<void> {
    this.opened.push({ absPath, range });
  }
  async showHistoryDiff(diff: HistoryDiff): Promise<void> {
    this.diffs.push(diff);
  }
  async confirm(id: ConfirmId, message: string): Promise<boolean> {
    this.confirms.push({ id, message });
    return this.confirmAnswer;
  }
  subjectChanged(subject: string): void {
    this.subjects.push(subject);
  }
  log(level: LogLevel, message: string): void {
    this.logs.push({ level, message });
  }

  /** Posts of one type, in order. */
  of<T extends HostToWebviewMessage['type']>(type: T): Array<Extract<HostToWebviewMessage, { type: T }>> {
    return this.posts.filter((m): m is Extract<HostToWebviewMessage, { type: T }> => m.type === type);
  }
  clear(): void {
    this.posts = [];
  }
}

import { parseWebviewToHost, type BoardAction, type WebviewToHostMessage } from '@telelean/core';
import { describe, expect, it } from 'vitest';

import { ACTION_MESSAGE_TYPES, isActionMessage, requestIdOf, toBoardAction, type ActionMessage } from '../../src/logic/actionMapping';

/** Builds a message the way the host receives it: through core's validator. */
function message(type: string, payload: Record<string, unknown>): WebviewToHostMessage {
  const parsed = parseWebviewToHost({ v: 1, type, payload });
  if (!parsed.ok) throw new Error(parsed.error);
  return parsed.value;
}

function action(type: string, payload: Record<string, unknown>, subject = 'Spyro'): BoardAction | undefined {
  const m = message(type, payload);
  if (!isActionMessage(m)) throw new Error(`${type} is not an action message`);
  return toBoardAction(m, subject);
}

