// esbuild options shared by scripts/build.mjs and the bundle test (test/unit/bundle.test.ts).
// `@telelean/core` and `@telelean/runner/*` resolve through the tsconfig `paths` entries to the package sources.

/** @param {string} root absolute path of packages/extension */
export function commonOptions(root) {
  /** @type {import('esbuild').BuildOptions} */
  const options = {
    absWorkingDir: root,
    bundle: true,
    platform: 'node',
    format: 'cjs',
    target: 'node22',
    sourcemap: true,
    tsconfig: 'tsconfig.json',
    logLevel: 'info',
  };
  return options;
}

/** src/extension.ts -> dist/extension.js (CommonJS, `vscode` external). */
export function extensionOptions(root) {
  /** @type {import('esbuild').BuildOptions} */
  const options = { ...commonOptions(root), entryPoints: ['src/extension.ts'], outfile: 'dist/extension.js', external: ['vscode'] };
  return options;
}

/** test/suite/*.test.ts -> out/test/suite/*.test.js (loaded by @vscode/test-cli's mocha runner). */
export function suiteOptions(root) {
  /** @type {import('esbuild').BuildOptions} */
  const options = { ...commonOptions(root), entryPoints: ['test/suite/*.test.ts'], outdir: 'out/test/suite', external: ['vscode', 'mocha'] };
  return options;
}

// Bundles the extension host code and the in-VS-Code smoke tests with esbuild.
//   src/extension.ts        -> dist/extension.js         (CommonJS, `vscode` external)
//   test/suite/*.test.ts    -> out/test/suite/*.test.js  (loaded by @vscode/test-cli's mocha runner)
// `@telelean/core` and `@telelean/runner/*` resolve through the tsconfig `paths` entries to the package sources (no
// workspace link needed). Only the runner's `semantic`/`workspace` subpaths are imported, so `llm/` (which uses
// `import.meta.url`) never enters the CommonJS bundle; the build fails if it does.
// The webview bundle (dist/webview/) is built separately by packages/webview (`npm run build:all` does both).
import * as esbuild from 'esbuild';
import { rm } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';

import { extensionOptions, suiteOptions } from './esbuild-options.mjs';

const root = fileURLToPath(new URL('..', import.meta.url));

await rm(`${root}/dist/extension.js`, { force: true });
await rm(`${root}/dist/extension.js.map`, { force: true });
const result = await esbuild.build({ ...extensionOptions(root), metafile: true });
const llm = Object.keys(result.metafile.inputs).filter((input) => input.includes('runner/src/llm/'));
if (llm.length > 0) throw new Error(`the extension bundle must not include the runner's llm/ modules: ${llm.join(', ')}`);

await rm(`${root}/out`, { recursive: true, force: true });
await esbuild.build(suiteOptions(root));

/**
 * The extension bundle (risk R8): it is built from the current sources with the build's own esbuild options, must
 * not contain the runner's llm/ modules (they use `import.meta.url`, meaningless in CommonJS), and must load and
 * activate in plain Node with a stub `vscode` module (so a missing or broken import fails here, before VS Code).
 */
import * as esbuild from 'esbuild';
import { mkdtemp, readFile, rm } from 'node:fs/promises';
import Module, { createRequire } from 'node:module';
import { tmpdir } from 'node:os';
import * as path from 'node:path';
import { fileURLToPath } from 'node:url';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';

// @ts-expect-error -- plain .mjs helper shared with scripts/build.mjs (no type declarations)
import { extensionOptions } from '../../scripts/esbuild-options.mjs';

const root = fileURLToPath(new URL('../..', import.meta.url));
let outDir: string;
let bundle: string;
let warnings: esbuild.Message[];
let inputs: string[];

beforeAll(async () => {
  outDir = await mkdtemp(path.join(process.env.TELELEAN_TEST_TMP ?? tmpdir(), 'tl-bundle-'));
  bundle = path.join(outDir, 'extension.js');
  const result = await esbuild.build({ ...(extensionOptions(root) as esbuild.BuildOptions), outfile: bundle, sourcemap: false, logLevel: 'silent', metafile: true });
  warnings = result.warnings;
  inputs = Object.keys(result.metafile?.inputs ?? {});
}, 60_000);

afterAll(async () => {
  await rm(outDir, { recursive: true, force: true });
});

/** A `vscode` stand-in with just what activation touches; records what the extension registers. */
function vscodeStub() {
  const registered = { commands: [] as string[], serializers: [] as string[], providers: [] as string[] };
  const disposable = { dispose() {} };
  class EventEmitter<T> {
    private readonly listeners = new Set<(value: T) => void>();
    readonly event = (listener: (value: T) => void) => {
      this.listeners.add(listener);
      return { dispose: () => this.listeners.delete(listener) };
    };
    fire(value: T) {
      for (const listener of this.listeners) listener(value);
    }
    dispose() {
      this.listeners.clear();
    }
  }
  const uri = (fsPath: string) => ({ scheme: 'file', fsPath, path: fsPath, toString: () => `file://${fsPath}` });
  const stub = {
    version: '1.140.0-stub',
    ExtensionMode: { Production: 1, Development: 2, Test: 3, 1: 'Production', 2: 'Development', 3: 'Test' },
    EventEmitter,
    Uri: { file: uri, joinPath: (base: { fsPath: string }, ...parts: string[]) => uri(path.join(base.fsPath, ...parts)) },
    window: {
      createOutputChannel: () => ({ info() {}, warn() {}, error() {}, debug() {}, trace() {}, dispose() {} }),
      registerWebviewPanelSerializer: (viewType: string) => (registered.serializers.push(viewType), disposable),
    },
    commands: { registerCommand: (id: string) => (registered.commands.push(id), disposable) },
    workspace: {
      workspaceFolders: undefined,
      registerTextDocumentContentProvider: (scheme: string) => (registered.providers.push(scheme), disposable),
      onDidChangeTextDocument: () => disposable,
      onDidSaveTextDocument: () => disposable,
    },
  };
  return { stub, registered };
}

function loadWithStub(file: string, stub: unknown): { activate: (context: unknown) => Record<string, unknown> } {
  const id = path.join(outDir, '__vscode_stub__.js');
  const loader = Module as unknown as { _resolveFilename: (request: string, ...rest: unknown[]) => string };
  const original = loader._resolveFilename;
  const require = createRequire(import.meta.url);
  loader._resolveFilename = function (this: unknown, request: string, ...rest: unknown[]) {
    return request === 'vscode' ? id : original.call(this, request, ...rest);
  };
  require.cache[id] = { id, filename: id, loaded: true, exports: stub } as unknown as NodeJS.Module;
  try {
    return require(file) as { activate: (context: unknown) => Record<string, unknown> };
  } finally {
    loader._resolveFilename = original;
  }
}

describe('extension bundle (R8)', () => {
  it('bundles the runner workspace/semantic sources but none of the llm/ modules, without import.meta warnings', async () => {
    expect(inputs.some((i) => i.includes('runner/src/workspace/'))).toBe(true);
    expect(inputs.some((i) => i.includes('core/src/'))).toBe(true);
    expect(inputs.filter((i) => i.includes('runner/src/llm/'))).toEqual([]);
    expect(warnings.filter((w) => /import\.meta/.test(w.text))).toEqual([]);
    const text = await readFile(bundle, 'utf8');
    expect(text).not.toMatch(/import\.meta/);
    expect(text).not.toContain('telelean-path-guard');
  });

  it('loads and activates with a stub vscode: registers the 3 commands, the board serializer and the history provider', () => {
    const { stub, registered } = vscodeStub();
    const extension = loadWithStub(bundle, stub);
    const context = {
      subscriptions: [] as Array<{ dispose(): void }>,
      extensionMode: 1,
      extension: { packageJSON: { version: '0.0.1' } },
      extensionUri: stub.Uri.file(root),
      workspaceState: { get: () => undefined, update: async () => undefined },
    };
    const api = extension.activate(context);
    expect(registered.commands.sort()).toEqual(['telelean.initializeModel', 'telelean.openBoard', 'telelean.refresh']);
    expect(registered.serializers).toEqual(['telelean.board']);
    expect(registered.providers).toEqual(['telelean-history']);
    expect(typeof api.simulateBoardMessage).toBe('function');
    expect(typeof api.workspaceFor).toBe('function');
    expect(api.testing).toBeUndefined(); // test hooks exist only in Test mode
    for (const disposable of context.subscriptions) disposable.dispose();
  });
});

// @vscode/test-cli configuration for the in-VS-Code smoke tests (docs/m1-plan.md section 10).
// Run from packages/extension with `npm run test:smoke`: scripts/smoke.mjs prepares an isolated profile under
// $TELELEAN_TEST_TMP/vscode-<pid>/ (home, XDG dirs, user-data, extensions, a workspace with copies of the sample
// model), points TELELEAN_SMOKE_DIR at it, and runs
//   sh -c 'ulimit -c 0; env -u ELECTRON_RUN_AS_NODE xvfb-run -a npx vscode-test'
// The VS Code 1.140.0 test build in ./.vscode-test/ is reused (never re-downloaded or modified). Because
// --user-data-dir and --extensions-dir are passed here, @vscode/test-electron does not add its own
// ./.vscode-test/user-data defaults, and HOME/XDG_* point into the scratch profile, so nothing reaches the user's real
// home folder (~/.config/Code, ~/.copilot, ~/.config/google-chrome, ...).
import { defineConfig } from '@vscode/test-cli';
import { homedir } from 'node:os';
import { join } from 'node:path';

const dir = process.env.TELELEAN_SMOKE_DIR;
if (!dir) {
  throw new Error(
    'TELELEAN_SMOKE_DIR is not set. Run the smoke tests with `npm run test:smoke` (scripts/smoke.mjs prepares the isolated VS Code profile); refusing to start VS Code with a real profile.',
  );
}

// This shell may run inside the user's (snap) VS Code: drop its IPC hooks and Electron/Wayland settings so the
// test instance is a fresh, separate X11 window inside xvfb. DBUS_SESSION_BUS_ADDRESS and XDG_RUNTIME_DIR are kept:
// runLean's `systemd-run --user` needs them.
const inherited = Object.fromEntries(
  Object.keys(process.env)
    .filter((name) => name.startsWith('VSCODE_') || name.startsWith('ELECTRON_'))
    .map((name) => [name, undefined]),
);

export default defineConfig({
  label: 'smoke',
  files: 'out/test/suite/**/*.test.js',
  version: '1.140.0',
  workspaceFolder: join(dir, 'ws'),
  mocha: { ui: 'tdd', timeout: 60_000, color: false },
  launchArgs: [
    `--user-data-dir=${join(dir, 'user-data')}`,
    `--extensions-dir=${join(dir, 'extensions')}`,
    '--disable-extensions',
    '--disable-telemetry',
    '--disable-workspace-trust',
    '--disable-crash-reporter',
    '--disable-gpu',
    '--password-store=basic',
    '--ozone-platform=x11',
  ],
  env: {
    ...inherited,
    WAYLAND_DISPLAY: undefined,
    XDG_SESSION_TYPE: 'x11',
    HOME: join(dir, 'home'),
    XDG_CONFIG_HOME: join(dir, 'xdg-config'),
    XDG_CACHE_HOME: join(dir, 'xdg-cache'),
    XDG_DATA_HOME: join(dir, 'xdg-data'),
    // Lean's toolchains are only read (runLean calls the pinned toolchain's binaries directly).
    ELAN_HOME: process.env.ELAN_HOME ?? join(homedir(), '.elan'),
    GIT_CONFIG_GLOBAL: '/dev/null',
    GIT_CONFIG_NOSYSTEM: '1',
    GIT_CEILING_DIRECTORIES: process.env.TELELEAN_TEST_TMP ?? dir,
    GIT_TERMINAL_PROMPT: '0',
    LEAN_NUM_THREADS: '4',
    TELELEAN_SMOKE_DIR: dir,
    TELELEAN_TEST_TMP: process.env.TELELEAN_TEST_TMP ?? dir,
  },
});

// npm run test:smoke: the in-VS-Code smoke tests in an isolated profile (docs/m1-plan.md section 10).
//
// 1. Makes $TELELEAN_TEST_TMP/vscode-<pid>/{home,xdg-config,xdg-cache,xdg-data,user-data,extensions,ws} (a fresh
//    mkdtemp under the OS temp dir when TELELEAN_TEST_TMP is unset; never anything under the real $HOME).
// 2. Fills ws/ with copies: mental_model (the sample model; until it holds .telelean/config.json, the Spyro fixture
//    plus a generated .telelean/config.json and empty layout, IN THE COPY ONLY), second_model (a second root),
//    plain_folder (Lean files, no .telelean: must never get a workspace) and empty_folder (for Initialize).
//    mental_model/ and test-fixtures/ themselves are only read.
// 3. Writes the instance's user settings: AI features, telemetry, updates, experiments and workspace trust off.
// 4. Records listings of the real ~/.copilot, ~/.config/Code and ~/.config/google-chrome.
// 5. Runs `sh -c 'ulimit -c 0; env -u ELECTRON_RUN_AS_NODE xvfb-run -a npx vscode-test'` (.vscode-test.mjs reads the
//    profile from TELELEAN_SMOKE_DIR).
// 6. Checks: the isolated user-data dir received the instance's files; the real listings did not change; no process
//    of this run is left (killed and reported if one is) and no telelean-* systemd unit of this run is left.
import { spawn, spawnSync } from 'node:child_process';
import { existsSync } from 'node:fs';
import { cp, mkdir, mkdtemp, readdir, readFile, readlink, symlink, writeFile } from 'node:fs/promises';
import { homedir, tmpdir } from 'node:os';
import * as path from 'node:path';
import { fileURLToPath } from 'node:url';

const extensionDir = fileURLToPath(new URL('..', import.meta.url));
const repo = path.resolve(extensionDir, '..', '..');
const realHome = homedir();

const base = process.env.TELELEAN_TEST_TMP ? path.resolve(process.env.TELELEAN_TEST_TMP) : await mkdtemp(path.join(tmpdir(), 'telelean-smoke-'));
if (base === realHome || base.startsWith(`${realHome}${path.sep}`)) {
  if (!base.startsWith(path.join(repo, 'packages', 'extension', 'out'))) {
    console.error(`[smoke] refusing to put the test profile under the real home folder (${base}); set TELELEAN_TEST_TMP to a scratch dir`);
    process.exit(2);
  }
}
