15	/** Declared support: one dashed `premise` edge per entry of `premises:`. */
16	export function declaredEdges(nodes: readonly TlNode[]): TlEdge[] {
17	  const edges: TlEdge[] = [];
18	  for (const node of nodes) {
19	    for (const premise of node.premises) {
20	      edges.push({
21	        id: edgeId('premise', premise, node.id),
22	        type: 'premise',
23	        source: premise,
24	        target: node.id,
25	        origin: 'declared',
26	      });
27	    }
28	  }
29	  return edges;
30	}
