32	/**
33	 * Verified dependencies approximated from footprints: one solid `verified` edge per node in a proved node's
34	 * footprint. Used by the samples and tests (where proofs use assumptions directly). The M1 graph builder
35	 * (`subjectGraph`, docs/m1-plan.md section 6.3) computes verified edges from the `.ilean` references of each proof
36	 * instead, because a footprint only lists axioms: a goal proved through a derivation (a theorem) must get the edge
37	 * from that derivation, which no footprint mentions.
38	 */
39	export function verifiedEdges(nodes: readonly TlNode[]): TlEdge[] {
40	  const ids = new Set(nodes.map((n) => n.id));
41	  const edges: TlEdge[] = [];
42	  for (const node of nodes) {
43	    if (node.status.proof.kind !== 'proved') continue;
44	    for (const dep of node.status.proof.footprint) {
45	      if (dep.startsWith(PRESUPPOSITION_PREFIX) || !ids.has(dep)) continue;
46	      edges.push({
47	        id: edgeId('verified', dep, node.id),
48	        type: 'verified',
49	        source: dep,
50	        target: node.id,
51	        origin: 'lean',
52	        where: 'proof',
53	      });
54	    }
55	  }
56	  return edges;
57	}
