107	export function validateGraph(graph: TlGraph): GraphProblem[] {
108	  const problems: GraphProblem[] = [];
109	  const ids = new Set<string>();
110	  for (const node of graph.nodes) {
111	    if (ids.has(node.id)) problems.push({ code: 'duplicate-id', message: `duplicate node id "${node.id}"` });
112	    ids.add(node.id);
113	  }
114	  for (const node of graph.nodes) {
115	    for (const premise of node.premises) {
116	      if (premise === node.id) problems.push({ code: 'self-premise', message: `"${node.id}" lists itself as a premise` });
117	      else if (!ids.has(premise)) {
118	        problems.push({ code: 'dangling-premise', message: `"${node.id}" lists unknown premise "${premise}"` });
119	      }
120	    }
121	  }
122	  for (const edge of graph.edges) {
123	    if (!ids.has(edge.source) || !ids.has(edge.target)) {
124	      problems.push({ code: 'dangling-edge', message: `edge ${edge.id} references an unknown node` });
125	    }
126	  }
127	  const cycle = findPremiseCycle(graph.nodes);
128	  if (cycle) problems.push({ code: 'premise-cycle', message: `premise cycle: ${cycle.join(' -> ')}` });
129	  return problems;
130	}
