3	 * A card's column is its node's `type:`; the layout only orders cards inside a column.
4	 *
5	 * FROZEN CONTRACT (M1, docs/m1-plan.md section 7). Implemented by the architect; owned by WP-model afterwards.
6	 */
7	import type { NodeType } from './model.js';
8	import { isNodeType, NODE_TYPES } from './model.js';
