10	export interface Layout {
11	  format: 'telelean-layout';
12	  version: 1;
13	  /** Card order per column (ids). Ids that no longer exist, or sit in the wrong column, are ignored. */
14	  columns: Record<NodeType, string[]>;
15	  /** UI state that is worth keeping with the model. */
16	  collapsed?: { vocabulary?: boolean };
17	}
18	
19	export function emptyLayout(): Layout {
20	  return { format: 'telelean-layout', version: 1, columns: { ASSUMPTION: [], DERIVATION: [], GOAL: [] } };
21	}
22	
23	/** Parses layout.json leniently: anything malformed yields the empty layout (layout is never worth an error). */
24	export function parseLayout(json: string | null | undefined): Layout {
25	  if (!json) return emptyLayout();
26	  try {
27	    const raw = JSON.parse(json) as { columns?: Record<string, unknown>; collapsed?: { vocabulary?: unknown } };
28	    const layout = emptyLayout();
29	    for (const [kind, ids] of Object.entries(raw.columns ?? {})) {
30	      if (!isNodeType(kind) || !Array.isArray(ids)) continue;
31	      const seen = new Set<string>();
32	      for (const id of ids) {
33	        if (typeof id === 'string' && !seen.has(id)) {
34	          seen.add(id);
35	          layout.columns[kind].push(id);
36	        }
37	      }
38	    }
39	    if (typeof raw.collapsed?.vocabulary === 'boolean') layout.collapsed = { vocabulary: raw.collapsed.vocabulary };
40	    return layout;
41	  } catch {
42	    return emptyLayout();
43	  }
44	}
