46	/** Stable serialisation (2-space indent, trailing newline), so unchanged layouts produce identical files. */
47	export function serializeLayout(layout: Layout): string {
48	  const out: Record<string, unknown> = {
49	    format: 'telelean-layout',
50	    version: 1,
51	    columns: { ASSUMPTION: layout.columns.ASSUMPTION, DERIVATION: layout.columns.DERIVATION, GOAL: layout.columns.GOAL },
52	  };
53	  if (layout.collapsed) out['collapsed'] = layout.collapsed;
54	  return `${JSON.stringify(out, null, 2)}\n`;
55	}
