57	/**
58	 * Column order for `nodes` (given in file order): ids listed in the layout's column come first, in layout order;
59	 * the remaining nodes of that type follow in input order.
60	 */
61	export function orderByLayout(nodes: ReadonlyArray<{ id: string; type: NodeType }>, layout?: Layout): Record<NodeType, string[]> {
62	  const order: Record<NodeType, string[]> = { ASSUMPTION: [], DERIVATION: [], GOAL: [] };
63	  const typeOf = new Map(nodes.map((n) => [n.id, n.type]));
64	  const placed = new Set<string>();
65	  for (const kind of NODE_TYPES) {
66	    for (const id of layout?.columns[kind] ?? []) {
67	      if (typeOf.get(id) === kind && !placed.has(id)) {
68	        order[kind].push(id);
69	        placed.add(id);
70	      }
71	    }
72	  }
73	  for (const node of nodes) {
74	    if (!placed.has(node.id)) {
75	      order[node.type].push(node.id);
76	      placed.add(node.id);
77	    }
78	  }
79	  return order;
80	}
