82	/**
83	 * The layout after moving `id` into `column` above `beforeId` (null = end), starting from the order the board
84	 * currently shows (`current`, e.g. from `orderByLayout`). The result lists every id of `current`, so the board's
85	 * order is pinned once the user has arranged it.
86	 */
87	export function moveInLayout(
88	  layout: Layout,
89	  current: Readonly<Record<NodeType, readonly string[]>>,
90	  id: string,
91	  column: NodeType,
92	  beforeId: string | null,
93	): Layout {
94	  const columns: Record<NodeType, string[]> = { ASSUMPTION: [], DERIVATION: [], GOAL: [] };
95	  for (const kind of NODE_TYPES) columns[kind] = current[kind].filter((x) => x !== id);
96	  const target = columns[column];
97	  const index = beforeId === null ? -1 : target.indexOf(beforeId);
98	  if (index >= 0) target.splice(index, 0, id);
99	  else target.push(id);
100	  return { ...layout, columns };
101	}
