103	/** The layout without the given ids (after deletes). */
104	export function withoutIds(layout: Layout, ids: Iterable<string>): Layout {
105	  const drop = new Set(ids);
106	  const columns: Record<NodeType, string[]> = { ASSUMPTION: [], DERIVATION: [], GOAL: [] };
107	  for (const kind of NODE_TYPES) columns[kind] = layout.columns[kind].filter((id) => !drop.has(id));
108	  return { ...layout, columns };
109	}
