111	/** The layout with `id` appended to `column` (after adds), unless it is already listed there. */
112	export function appendToLayout(layout: Layout, id: string, column: NodeType): Layout {
113	  if (layout.columns[column].includes(id)) return layout;
114	  const base = withoutIds(layout, [id]);
115	  return { ...base, columns: { ...base.columns, [column]: [...base.columns[column], id] } };
116	}
