/**
 * Small pure text helpers of the model builder and the edit planner (WP-model). They deliberately do not depend on
 * WP-markup's lexer: positions and declaration spans come from the parsed files, and these helpers only convert
 * between offsets and LSP positions, read declaration signatures and scan for namespaces/tokens.
 *
 * Offsets are UTF-16 code-unit indices; positions are LSP (0-based line, UTF-16 character).
 */
import type { Position, Range } from '../model.js';

/** Offset <-> position conversion for one text (`\n` and `\r\n` line breaks). */
export class LineMap {
  private readonly starts: number[] = [0];

  constructor(readonly text: string) {
    for (let i = 0; i < text.length; i++) if (text.charCodeAt(i) === 10) this.starts.push(i + 1);
  }

  get lineCount(): number {
    return this.starts.length;
  }

  positionAt(offset: number): Position {
    const clamped = Math.max(0, Math.min(offset, this.text.length));
    let lo = 0;
    let hi = this.starts.length - 1;
    while (lo < hi) {
      const mid = (lo + hi + 1) >> 1;
      if ((this.starts[mid] ?? 0) <= clamped) lo = mid;
      else hi = mid - 1;
    }
    return { line: lo, character: clamped - (this.starts[lo] ?? 0) };
  }

  offsetAt(position: Position): number {
    if (position.line < 0) return 0;
    if (position.line >= this.starts.length) return this.text.length;
    const start = this.starts[position.line] ?? 0;
    const next = position.line + 1 < this.starts.length ? (this.starts[position.line + 1] ?? this.text.length) - 1 : this.text.length;
    const lineEnd = next > start && this.text.charCodeAt(next - 1) === 13 ? next - 1 : next;
    return Math.min(start + Math.max(0, position.character), lineEnd);
  }

  rangeOf(start: number, end: number): Range {
    return { start: this.positionAt(start), end: this.positionAt(end) };
  }
}

export function comparePositions(a: Position, b: Position): number {
  return a.line - b.line || a.character - b.character;
}

/** `inner` lies within `outer` (inclusive ends: a zero-width message range at a declaration's end still counts). */
export function rangeContains(outer: Range, inner: Position): boolean {
  return comparePositions(outer.start, inner) <= 0 && comparePositions(inner, outer.end) <= 0;
}

/** Every run of whitespace becomes one space (Lean wraps long `#check` types onto indented lines). */
export function normalizeWhitespace(text: string): string {
  return text.replace(/\s+/g, ' ').trim();
}

/**
 * The text with comments (nested `/- -/`, `--`) and string literals blanked out by spaces, so offsets stay valid.
 * Line breaks inside comments are kept.
 */
export function blankComments(text: string): string {
  const out = text.split('');
  const blank = (from: number, to: number) => {
    for (let k = from; k < to; k++) if (out[k] !== '\n' && out[k] !== '\r') out[k] = ' ';
  };
  let i = 0;
  while (i < text.length) {
    const c = text[i];
    const next = text[i + 1];
    if (c === '-' && next === '-') {
      let j = i;
      while (j < text.length && text[j] !== '\n') j++;
      blank(i, j);
      i = j;
    } else if (c === '/' && next === '-') {
      let depth = 1;
      let j = i + 2;
      while (j < text.length && depth > 0) {
        if (text[j] === '/' && text[j + 1] === '-') {
          depth++;
          j += 2;
        } else if (text[j] === '-' && text[j + 1] === '/') {
          depth--;
          j += 2;
        } else j++;
      }
      blank(i, j);
      i = j;
    } else if (c === '"') {
      let j = i + 1;
      while (j < text.length && text[j] !== '"' && text[j] !== '\n') j += text[j] === '\\' ? 2 : 1;
      blank(i, Math.min(j + 1, text.length));
      i = j + 1;
    } else i++;
  }
  return out.join('');
}

const OPENERS = '([{⟨⦃';
const CLOSERS = ')]}⟩⦄';

/**
 * Splits a type at its top-level arrows (`→` or `->`, outside brackets). A type that starts with a binder
 * (`∀`, `∃`, `fun`, `λ`, `Π`, `Σ`) is returned whole: its arrows are not top-level implications.
 */
export function splitTopLevelArrows(type: string): string[] {
  const text = normalizeWhitespace(type);
  if (/^(∀|∃|∃!|fun\b|λ|Π|Σ)/.test(text)) return [text];
  const parts: string[] = [];
  let depth = 0;
  let start = 0;
  for (let i = 0; i < text.length; i++) {
    const c = text[i] ?? '';
    if (OPENERS.includes(c)) depth++;
    else if (CLOSERS.includes(c)) depth = Math.max(0, depth - 1);
    else if (depth === 0 && (c === '→' || (c === '-' && text[i + 1] === '>'))) {
      parts.push(text.slice(start, i).trim());
      start = i + (c === '→' ? 1 : 2);
      if (c !== '→') i++;
    }
  }
  parts.push(text.slice(start).trim());
  return parts;
}

/** The offset of the first top-level `:` (not `:=`) in `text`, outside brackets, or -1. */
export function topLevelColon(text: string): number {
  let depth = 0;
  for (let i = 0; i < text.length; i++) {
    const c = text[i] ?? '';
    if (OPENERS.includes(c)) depth++;
    else if (CLOSERS.includes(c)) depth = Math.max(0, depth - 1);
    else if (depth === 0 && c === ':' && text[i + 1] !== '=' && text[i - 1] !== ':') return i;
  }
  return -1;
}

/** A binder group `(a b : T)`, `{a : T}`, `[C]`, `⦃a : T⦄` of a declaration signature. */
export interface Binder {
  explicit: boolean;
  names: string[];
  type: string;
}

/** Splits `(a b : A) {c : C} [D]` into binder groups; returns undefined when the text is not only binders. */
export function parseBinders(text: string): Binder[] | undefined {
  const binders: Binder[] = [];
  let i = 0;
  const src = text.trim();
  while (i < src.length) {
    while (i < src.length && /\s/.test(src[i] ?? '')) i++;
    if (i >= src.length) break;
    const open = src[i] ?? '';
    const close = open === '(' ? ')' : open === '{' ? '}' : open === '[' ? ']' : open === '⦃' ? '⦄' : '';
    if (!close) return undefined;
    let depth = 0;
    let j = i;
    for (; j < src.length; j++) {
      const c = src[j] ?? '';
      if (OPENERS.includes(c)) depth++;
      else if (CLOSERS.includes(c)) {
        depth--;
        if (depth === 0) break;
      }
    }
    if (j >= src.length) return undefined;
    const inner = src.slice(i + 1, j);
    const colon = topLevelColon(inner);
    if (colon < 0) binders.push({ explicit: open === '(', names: [], type: inner.trim() });
    else {
      const names = inner.slice(0, colon).trim().split(/\s+/).filter(Boolean);
      binders.push({ explicit: open === '(', names, type: inner.slice(colon + 1).trim() });
    }
    i = j + 1;
  }
  return binders;
}

const IDENT = /(?:«[^»]*»|[\p{L}_][\p{L}\p{N}_'!?₀-₉ₐ-ₜ]*)(?:\.(?:«[^»]*»|[\p{L}_][\p{L}\p{N}_'!?₀-₉ₐ-ₜ]*))*/gu;

/** Identifier tokens (dotted names) of a text, with their offsets; comments and strings should be blanked first. */
export function identifierTokens(text: string): Array<{ text: string; start: number }> {
  const out: Array<{ text: string; start: number }> = [];
  for (const match of text.matchAll(IDENT)) {
    const start = match.index ?? 0;
    const before = start > 0 ? text[start - 1] ?? '' : '';
    if (before && /[\p{L}\p{N}_'.]/u.test(before)) continue;
    out.push({ text: match[0], start });
  }
  return out;
}

/** True when `name` occurs as a whole identifier token in `text` (comments and strings ignored). */
export function hasToken(text: string, name: string): boolean {
  return identifierTokens(blankComments(text)).some((t) => t.text === name || t.text.startsWith(`${name}.`));
}

/**
 * The enclosing namespaces (outermost first) at `offset`, from `namespace X` / `section` / `end` commands at column 0
 * before it (comments ignored).
 */
export function namespaceAt(text: string, offset: number): string[] {
  const clean = blankComments(text.slice(0, offset));
  const stack: Array<{ kind: 'namespace' | 'section'; parts: string[] }> = [];
  for (const line of clean.split('\n')) {
    const ns = /^namespace\s+(\S+)/.exec(line);
    if (ns) {
      stack.push({ kind: 'namespace', parts: (ns[1] ?? '').split('.').filter(Boolean) });
      continue;
    }
    if (/^section(\s|$)/.test(line)) {
      stack.push({ kind: 'section', parts: [] });
      continue;
    }
    if (/^end(\s|$)/.test(line)) stack.pop();
  }
  return stack.flatMap((entry) => entry.parts);
}

/** The candidates a name written inside `namespace` may refer to, innermost first (`_root_.` honoured). */
export function resolutionCandidates(name: string, namespace: readonly string[]): string[] {
  if (name.startsWith('_root_.')) return [name.slice('_root_.'.length)];
  const out: string[] = [];
  for (let i = namespace.length; i > 0; i--) out.push(`${namespace.slice(0, i).join('.')}.${name}`);
  out.push(name);
  return out;
}

/** One line for labels and messages: the text cut to `max` characters (code points) with `…`. */
export function cutText(text: string, max = 60): string {
  const chars = Array.from(text.replace(/\s+/g, ' ').trim());
  return chars.length <= max ? chars.join('') : `${chars.slice(0, max - 1).join('')}…`;
}

/** Compares Lean names the way `#print axioms` orders them (`Name.cmp`: fewer components first, then by string). */
export function compareLeanNames(a: string, b: string): number {
  const pa = a.split('.');
  const pb = b.split('.');
  if (pa.length !== pb.length) return pa.length - pb.length;
  for (let i = 0; i < pa.length; i++) {
    const x = pa[i] ?? '';
    const y = pb[i] ?? '';
    if (x !== y) return x < y ? -1 : 1;
  }
  return 0;
}

/**
 * Which Lean facts the board may use (docs/m1-plan.md section 6.3, "Which facts"):
 *
 *  - a FRESH file (its module is `fresh` and its hash equals the facts' `sourceSha256`) uses its facts fully;
 *  - a STALE file (the hash differs, or the module went stale during the refresh) keeps a declaration's previous facts
 *    BY NAME while the declaration's current syntactic keyword agrees with the facts' kind (positions are not used);
 *  - an UNCHECKED file (failed / dependency-failed / not-built module, a file the facts do not know, or no facts at
 *    all) uses no facts: only the syntactic keyword counts.
 */
import type { DeclFacts, LeanDeclKind, LeanFacts, ModuleFacts } from '../facts.js';
import type { DeclInfo, DeclKeyword, ParsedFile } from '../markup/types.js';

export type FileFactsState = 'fresh' | 'stale' | 'unchecked';

export interface FileFactsInfo {
  state: FileFactsState;
  module?: ModuleFacts;
  /** The file's current hash differs from the hash the facts were computed from. */
  hashDiffers: boolean;
}

/** The fact kind a syntactic keyword corresponds to. */
export function keywordKind(keyword: DeclKeyword): LeanDeclKind {
  switch (keyword) {
    case 'axiom':
      return 'axiom';
    case 'theorem':
    case 'lemma':
      return 'theorem';
    case 'def':
    case 'abbrev':
      return 'def';
    case 'opaque':
      return 'opaque';
    case 'instance':
      return 'instance';
    case 'structure':
      return 'structure';
    case 'inductive':
    case 'coinductive':
      return 'inductive';
    case 'class':
    case 'class inductive':
    case 'class abbrev':
      return 'class';
    default:
      return 'other';
  }
}

/** A stale file keeps a declaration's facts while its current keyword still says the same kind of declaration. */
export function kindsAgree(keyword: DeclKeyword, kind: LeanDeclKind | undefined): boolean {
  if (kind === undefined) return true;
  const expected = keywordKind(keyword);
  if (expected === kind) return true;
  // Lean prints instances as theorems/defs and class abbrevs as defs; the semantic layer usually fixes instances up.
  if (keyword === 'instance') return kind === 'theorem' || kind === 'def';
  if (keyword === 'class abbrev') return kind === 'def';
  if (keyword === 'class' || keyword === 'class inductive') return kind === 'structure' || kind === 'inductive';
  return false;
}

export class FactsIndex {
  /** Per model file. */
  readonly files = new Map<string, FileFactsInfo>();
  /** Usable facts by fully-qualified name (fresh files fully, stale files by name). */
  readonly usable = new Map<string, DeclFacts>();
  /** Usable facts by `file` + syntactic declaration index (also covers anonymous instances matched by start line). */
  private readonly bySyntactic = new Map<string, DeclFacts>();
  /** Facts decls of fresh files that no syntactic declaration matched (e.g. constructors), per file. */
  readonly unmatched = new Map<string, DeclFacts[]>();

  constructor(
    files: readonly ParsedFile[],
    fileHashes: Readonly<Record<string, string>>,
    readonly facts: LeanFacts | undefined,
  ) {
    const modulesByFile = new Map<string, ModuleFacts>();
    for (const module of facts?.modules ?? []) if (!modulesByFile.has(module.file)) modulesByFile.set(module.file, module);
    for (const file of files) {
      const module = facts ? modulesByFile.get(file.path) : undefined;
      if (!module) {
        this.files.set(file.path, { state: 'unchecked', hashDiffers: false });
        continue;
      }
      const hashDiffers = fileHashes[file.path] !== module.sourceSha256;
      let state: FileFactsState;
      if (module.state === 'fresh') state = hashDiffers ? 'stale' : 'fresh';
      else if (module.state === 'stale') state = 'stale';
      else state = 'unchecked';
      this.files.set(file.path, { state, module, hashDiffers });
    }

    const factsByFile = new Map<string, DeclFacts[]>();
    for (const decl of facts?.decls ?? []) {
      const list = factsByFile.get(decl.file) ?? [];
      list.push(decl);
      factsByFile.set(decl.file, list);
    }
    for (const file of files) {
      const state = this.files.get(file.path)?.state ?? 'unchecked';
      const list = factsByFile.get(file.path) ?? [];
      if (state === 'unchecked' || list.length === 0) continue;
      const byName = new Map<string, DeclFacts>();
      for (const decl of list) if (!byName.has(decl.name)) byName.set(decl.name, decl);
      const matched = new Set<DeclFacts>();
      file.decls.forEach((decl, index) => {
        let found: DeclFacts | undefined;
        if (decl.fullName) found = byName.get(decl.fullName);
        else if (state === 'fresh' && decl.keyword === 'instance') {
          // Anonymous instances: Lean names them (`instNonemptyCharacter`); match by the declaration's start line.
          found = list.find((f) => !matched.has(f) && f.range.start.line === decl.range.start.line && (f.kind === undefined || kindsAgree('instance', f.kind)));
        }
        if (!found) return;
        if (state === 'stale' && !kindsAgree(decl.keyword, found.kind)) return;
        matched.add(found);
        this.bySyntactic.set(`${file.path}#${index}`, found);
        if (!this.usable.has(found.name)) this.usable.set(found.name, found);
      });
      if (state === 'fresh') {
        const rest: DeclFacts[] = [];
        for (const decl of list) {
          if (matched.has(decl)) continue;
          if (!this.usable.has(decl.name)) this.usable.set(decl.name, decl);
          rest.push(decl);
        }
        if (rest.length > 0) this.unmatched.set(file.path, rest);
      }
    }
  }

  stateOf(path: string): FileFactsState {
    return this.files.get(path)?.state ?? 'unchecked';
  }

  isFresh(path: string): boolean {
    return this.stateOf(path) === 'fresh';
  }

  /** Usable facts for a syntactic declaration of a file. */
  factsFor(file: ParsedFile, decl: DeclInfo): DeclFacts | undefined {
    const index = file.decls.indexOf(decl);
    return index < 0 ? undefined : this.bySyntactic.get(`${file.path}#${index}`);
  }

  /** Files whose facts can be trusted fully (fresh). */
  freshFiles(): Set<string> {
    const out = new Set<string>();
    for (const [path, info] of this.files) if (info.state === 'fresh') out.add(path);
    return out;
  }
}

/**
 * The computed Vocabulary group (D-3, docs/m1-plan.md section 6.4): every declaration of a subject's modules that is
 * bound to no node, classified by the simple shape check, from Lean's facts where usable and from the declaration
 * text otherwise (syntactic mode).
 */
import type { DeclFacts, LeanDeclKind } from '../facts.js';
import type { BoardDiagnostic, VocabFlag, VocabItem, VocabKind } from '../model.js';
import type { DeclInfo, DeclKeyword, ParsedFile } from '../markup/types.js';
import { keywordKind, type FactsIndex } from './factsIndex.js';
import {
  blankComments,
  identifierTokens,
  LineMap,
  normalizeWhitespace,
  parseBinders,
  resolutionCandidates,
  splitTopLevelArrows,
  topLevelColon,
} from './text.js';

/** Display order of the Vocabulary group. */
export const VOCAB_KIND_ORDER: readonly VocabKind[] = ['sort', 'predicate', 'function', 'constant', 'presupposition', 'definition', 'lemma', 'unmarked-axiom', 'other'];

/** What the classifier needs to know about one declaration. */
export interface DeclShape {
  /** Fully-qualified name. */
  name: string;
  kind: LeanDeclKind;
  /** The syntactic keyword, when the declaration is in the current text. */
  keyword?: DeclKeyword;
  /** Fully-qualified type (facts `#check`, or the qualified declaration text). */
  type?: string;
  /** Top-level arrow parts of the type, binders included. */
  parts: string[];
  /** The signature has implicit or instance binders (never a simple vocabulary shape). */
  implicitBinders: boolean;
  /** `#check type_of%` sort (facts) or inferred from the text. */
  typeSort?: string;
  /** Names the declaration refers to (facts refs, or resolved identifiers of the text). */
  mentions: string[];
  docstring?: string;
}

export interface VocabCandidate {
  shape: DeclShape;
  subject: string;
  file: ParsedFile;
  decl?: DeclInfo;
  facts?: DeclFacts;
  stale: boolean;
}

export interface VocabularyResult {
  /** Every subject's items, in subject order then display order. */
  items: VocabItem[];
  /** Fully-qualified name of every declaration that belongs to an item (the item itself and folded auxiliaries) -> item name. */
  itemOfName: Map<string, string>;
  /** Item kind by item name. */
  kindOf: Map<string, VocabKind>;
  /** Declarations that only re-export a presupposition (not listed). */
  hidden: Set<string>;
  /** Items declared with `axiom` (constants/functions declared with axiom assert existence: footprint `axiom:`). */
  declaredWithAxiom: Set<string>;
  diagnostics: BoardDiagnostic[];
}

/** Resolves a name written inside `namespace` against the known declaration names. */
export function resolveName(name: string, namespace: readonly string[], known: (fq: string) => boolean): string | undefined {
  for (const candidate of resolutionCandidates(name, namespace)) if (known(candidate)) return candidate;
  return undefined;
}

/** The signature text of a syntactic declaration: binders and type between the name and the value. */
export function signatureText(file: ParsedFile, decl: DeclInfo): { binders: string; type: string } | undefined {
  const start = decl.nameSpan?.end ?? decl.keywordSpan.end;
  const end = decl.valueStart ?? decl.span.end;
  if (end <= start) return undefined;
  const text = blankComments(file.text.slice(start, end));
  const colon = topLevelColon(text);
  if (colon < 0) return { binders: text.trim(), type: '' };
  return { binders: text.slice(0, colon).trim(), type: text.slice(colon + 1).trim() };
}

/** Replaces identifiers that resolve to known declarations by their fully-qualified names. */
export function qualifyText(text: string, namespace: readonly string[], known: (fq: string) => boolean): string {
  const tokens = identifierTokens(text);
  let out = '';
  let last = 0;
  for (const token of tokens) {
    const resolved = resolveName(token.text, namespace, known);
    out += text.slice(last, token.start) + (resolved ?? token.text);
    last = token.start + token.text.length;
  }
  return normalizeWhitespace(out + text.slice(last));
}

/** The shape of a declaration, from usable facts when present, else from its text. */
export function shapeOf(
  file: ParsedFile,
  decl: DeclInfo | undefined,
  facts: DeclFacts | undefined,
  name: string,
  known: (fq: string) => boolean,
): DeclShape {
  const keyword = decl?.keyword;
  const docstring = facts?.docstring ?? decl?.docstring;
  if (facts && facts.type !== undefined) {
    const type = normalizeWhitespace(facts.type);
    return {
      name,
      kind: keyword === 'instance' ? 'instance' : (facts.kind ?? (keyword ? keywordKind(keyword) : 'other')),
      ...(keyword ? { keyword } : {}),
      type,
      parts: splitTopLevelArrows(type),
      implicitBinders: /^∀\s*[{[⦃]/.test(type),
      ...(facts.typeSort !== undefined ? { typeSort: normalizeWhitespace(facts.typeSort) } : {}),
      mentions: facts.refs.map((r) => r.name),
      ...(docstring !== undefined ? { docstring } : {}),
    };
  }
  const kind: LeanDeclKind = keyword === 'instance' ? 'instance' : (facts?.kind ?? (keyword ? keywordKind(keyword) : 'other'));
  const namespace = decl?.namespace ?? [];
  const signature = decl ? signatureText(file, decl) : undefined;
  let parts: string[] = [];
  let implicitBinders = false;
  let type: string | undefined;
  if (signature) {
    const binders = signature.binders ? parseBinders(signature.binders) : [];
    const typeParts = signature.type ? splitTopLevelArrows(qualifyText(signature.type, namespace, known)) : [];
    if (binders === undefined) {
      implicitBinders = true;
      parts = typeParts;
    } else {
      for (const binder of binders) {
        if (!binder.explicit) implicitBinders = true;
        const binderType = qualifyText(binder.type, namespace, known);
        for (let i = 0; i < Math.max(1, binder.names.length); i++) parts.push(binderType);
      }
      parts.push(...typeParts);
    }
    if (parts.length > 0) type = parts.join(' → ');
  }
  const mentions: string[] = [];
  if (decl) {
    const body = blankComments(file.text.slice(decl.nameSpan?.end ?? decl.keywordSpan.end, decl.span.end));
    for (const token of identifierTokens(body)) {
      const resolved = resolveName(token.text, namespace, known);
      if (resolved && resolved !== name) mentions.push(resolved);
    }
  }
  return {
    name,
    kind,
    ...(keyword ? { keyword } : {}),
    ...(type !== undefined ? { type } : {}),
    parts,
    implicitBinders,
    mentions,
    ...(docstring !== undefined ? { docstring } : {}),
  };
}

const LOGICAL = /(^|[\s(])(∀|∃|¬|∧|∨|↔|=|≠|True|False)($|[\s)])/;

/** Syntactic guess of `typeSort` when Lean's is unavailable. */
function inferTypeSort(shape: DeclShape, sorts: ReadonlySet<string>, propHeads: ReadonlySet<string>): string | undefined {
  const type = shape.type;
  if (type === undefined) return undefined;
  if (type === 'Type') return 'Type 1';
  if (/^(Type|Sort)\b/.test(type)) return undefined;
  const last = shape.parts[shape.parts.length - 1] ?? '';
  if (last === 'Prop') return 'Type';
  if (shape.parts.every((p) => sorts.has(p))) return 'Type';
  if (/^Nonempty\b/.test(type)) return 'Prop';
  if (LOGICAL.test(type)) return 'Prop';
  const head = /^[^\s()]+/.exec(last)?.[0];
  if (head && propHeads.has(head)) return 'Prop';
  return undefined;
}

/** Lean's automatic name of an anonymous instance, e.g. `instNonemptyCharacter` for `Nonempty Character`. */
export function anonymousInstanceName(file: ParsedFile, decl: DeclInfo): string {
  const signature = signatureText(file, decl);
  const words = identifierTokens(signature?.type ?? '').map((t) => {
    const last = t.text.split('.').pop() ?? t.text;
    return last.charAt(0).toUpperCase() + last.slice(1);
  });
  const short = `inst${words.join('')}`;
  return decl.namespace.length > 0 ? `${decl.namespace.join('.')}.${short}` : short;
}

interface Classified {
  kind: VocabKind | 'hidden';
  arity?: number;
  presupposes?: string;
  flags: VocabFlag[];
  problem?: string;
}

function classify(
  candidate: VocabCandidate,
  sorts: ReadonlyMap<string, string | undefined>,
  propHeads: ReadonlySet<string>,
): Classified {
  const shape = candidate.shape;
  const sortNames = new Set(sorts.keys());
  const type = shape.type;
  const last = shape.parts[shape.parts.length - 1] ?? '';
  const args = shape.parts.slice(0, -1);
  const declaredWith = shape.kind === 'axiom' ? 'axiom' : 'opaque';
  const nonSort = args.filter((a) => !sortNames.has(a));

  const symbolShape = (): Classified | undefined => {
    if (last === 'Prop' && !(shape.implicitBinders && shape.parts.length === 1)) {
      const flags: VocabFlag[] = [];
      let problem: string | undefined;
      if (nonSort.length > 0 || shape.implicitBinders) {
        flags.push('shape-violation');
        problem = `${shape.name} is a predicate over ${nonSort.length > 0 ? nonSort.join(', ') : 'implicit arguments'}, which ${nonSort.length === 1 ? 'is not a sort' : 'are not sorts'}: predicates take sorts (\`axiom T : Type\`) as arguments.`;
      }
      return { kind: 'predicate', arity: args.length, flags, ...(problem ? { problem } : {}) };
    }
    if (shape.parts.length > 0 && !shape.implicitBinders && shape.parts.every((p) => sortNames.has(p))) {
      const kind: VocabKind = shape.parts.length === 1 ? 'constant' : 'function';
      if (declaredWith === 'axiom') {
        return {
          kind,
          ...(kind === 'function' ? { arity: args.length } : {}),
          flags: ['shape-violation'],
          problem: `${shape.name} is declared with \`axiom\`, which asserts that such a ${kind === 'constant' ? 'thing' : 'function'} exists without showing it: declare it \`noncomputable opaque\` so its existence presupposition shows.`,
        };
      }
      return { kind, ...(kind === 'function' ? { arity: args.length } : {}), flags: [] };
    }
    return undefined;
  };

  switch (shape.kind) {
    case 'axiom': {
      if (type === 'Type') return { kind: 'sort', flags: [] };
      const nonempty = type ? /^Nonempty\s+(\S+)$/.exec(type) : null;
      if (nonempty && sortNames.has(nonempty[1] ?? '')) return { kind: 'presupposition', presupposes: nonempty[1] ?? '', flags: [] };
      if (shape.typeSort === 'Prop') return { kind: 'unmarked-axiom', flags: ['unmarked-assumption'] };
      const symbol = symbolShape();
      if (symbol) return symbol;
      if (shape.typeSort === undefined && inferTypeSort(shape, sortNames, propHeads) === 'Prop') return { kind: 'unmarked-axiom', flags: ['unmarked-assumption'] };
      return {
        kind: 'other',
        flags: ['shape-violation'],
        problem: `${shape.name} is an axiom of type ${type ?? '(unknown)'}: vocabulary axioms are sorts (\`axiom T : Type\`) or predicates ending in \`Prop\`.`,
      };
    }
    case 'opaque': {
      const symbol = symbolShape();
      if (symbol) return symbol;
      return {
        kind: 'other',
        flags: ['shape-violation'],
        problem: `${shape.name} has type ${type ?? '(unknown)'}: constants and functions range over the subject's sorts (\`axiom T : Type\`).`,
      };
    }
    case 'theorem':
      return { kind: 'lemma', flags: [] };
    case 'instance': {
      const nonempty = type ? /^Nonempty\s+(\S+)$/.exec(type) : null;
      const sort = nonempty?.[1];
      const presupposition = sort !== undefined ? sorts.get(sort) : undefined;
      if (presupposition !== undefined && shape.mentions.includes(presupposition)) return { kind: 'hidden', flags: [] };
      return { kind: 'definition', flags: [] };
    }
    case 'def':
    case 'structure':
    case 'inductive':
    case 'class':
      return { kind: 'definition', flags: [] };
    default:
      return { kind: 'other', flags: [] };
  }
}

/**
 * Classifies the candidates (all subjects at once, so a sort imported from another subject still counts as a sort)
 * and builds the items in display order.
 */
export function buildVocabulary(candidates: readonly VocabCandidate[], subjects: readonly string[]): VocabularyResult {
  const sorts = new Map<string, string | undefined>();
  for (const c of candidates) if (c.shape.kind === 'axiom' && c.shape.type === 'Type') sorts.set(c.shape.name, undefined);
  for (const c of candidates) {
    if (c.shape.kind !== 'axiom') continue;
    const m = c.shape.type ? /^Nonempty\s+(\S+)$/.exec(c.shape.type) : null;
    const sort = m?.[1];
    if (sort !== undefined && sorts.has(sort) && sorts.get(sort) === undefined) sorts.set(sort, c.shape.name);
  }
  // Heads that make an application a proposition (syntactic mode): predicates and Prop-valued definitions.
  const propHeads = new Set<string>();
  for (const c of candidates) {
    const last = c.shape.parts[c.shape.parts.length - 1];
    if (last === 'Prop') propHeads.add(c.shape.name);
  }

  const itemOfName = new Map<string, string>();
  const kindOf = new Map<string, VocabKind>();
  const hidden = new Set<string>();
  const declaredWithAxiom = new Set<string>();
  const diagnostics: BoardDiagnostic[] = [];
  const bySubject = new Map<string, VocabItem[]>();

  for (const c of candidates) {
    const result = classify(c, sorts, propHeads);
    if (result.kind === 'hidden') {
      hidden.add(c.shape.name);
      continue;
    }
    const kind = result.kind;
    const flags: VocabFlag[] = [...result.flags];
    if (c.stale) flags.push('stale');
    const lines = new LineMap(c.file.text);
    const range = c.decl ? c.decl.range : c.facts?.range;
    const code = c.decl
      ? c.file.text.slice(c.decl.span.start, c.decl.span.end)
      : c.facts
        ? c.file.text.slice(lines.offsetAt(c.facts.range.start), lines.offsetAt(c.facts.range.end))
        : undefined;
    const prefix = `${c.subject}.`;
    const gloss = c.shape.docstring?.trim();
    const item: VocabItem = {
      name: c.shape.name,
      shortName: c.shape.name.startsWith(prefix) && c.shape.name.length > prefix.length ? c.shape.name.slice(prefix.length) : c.shape.name,
      subject: c.subject,
      kind,
      ...(c.shape.type !== undefined ? { type: c.shape.type } : {}),
      ...(result.arity !== undefined ? { arity: result.arity } : {}),
      ...(gloss ? { gloss, glossBy: 'user' as const } : {}),
      ...(result.presupposes !== undefined ? { presupposes: result.presupposes } : {}),
      ...(kind === 'sort' && sorts.get(c.shape.name) !== undefined ? { presupposition: sorts.get(c.shape.name) as string } : {}),
      ...(range ? { loc: { file: c.file.path, range } } : {}),
      ...(code !== undefined ? { code } : {}),
      usedBy: [],
      flags,
    };
    itemOfName.set(item.name, item.name);
    kindOf.set(item.name, kind);
    if (c.shape.kind === 'axiom') declaredWithAxiom.add(item.name);
    const list = bySubject.get(c.subject) ?? [];
    list.push(item);
    bySubject.set(c.subject, list);
    if (kind === 'unmarked-axiom') {
      diagnostics.push({
        code: 'TL104',
        severity: 'warning',
        message: `${item.name} is a Prop-valued axiom without a card: a hidden assumption. Give it a block (an Assumption) or remove it.`,
        file: c.file.path,
        ...(range ? { range } : {}),
        vocab: item.name,
      });
    }
    if (result.problem) {
      diagnostics.push({ code: 'TL111', severity: 'warning', message: result.problem, file: c.file.path, ...(range ? { range } : {}), vocab: item.name });
    }
  }

  const items: VocabItem[] = [];
  for (const subject of subjects) {
    const list = bySubject.get(subject) ?? [];
    // Stable sort: display kind first, then the candidates' file/source order.
    const ranked = list.map((item, index) => ({ item, index }));
    ranked.sort((a, b) => VOCAB_KIND_ORDER.indexOf(a.item.kind) - VOCAB_KIND_ORDER.indexOf(b.item.kind) || a.index - b.index);
    items.push(...ranked.map((r) => r.item));
  }
  return { items, itemOfName, kindOf, hidden, declaredWithAxiom, diagnostics };
}

/**
 * Edges of the project (D-13, docs/m1-plan.md section 6.3):
 *
 *  - `premise` (declared, dashed): one per entry of `premises:`;
 *  - `verified` (Lean, solid): FROM REFERENCES, not footprints. direct(v) = the nodes u whose `.holds` the proof of v
 *    uses: start at v's `.holds` `DeclFacts.refs` and follow references through declarations that belong to no node
 *    (untracked lemmas, definitions) until a node's `.holds` is reached; plus one `conditional` edge per node v takes
 *    as a hypothesis (`on`). A footprint lists only axioms, so it would miss every derivation -> goal edge;
 *  - `lean-ref`: v's statement mentions u's statement;
 *  - mismatch flags, only when v is proved or conditional, judged at the assumption level: `declared-unused` (TL109)
 *    when a premise is not in the closure of what the proof uses; `used-undeclared` (TL107) when a used node is not a
 *    premise and the assumptions it stands for are not covered by the premises' assumptions.
 */
import type { DeclFacts } from '../facts.js';
import { holdsName } from '../facts.js';
import { edgeId } from '../graph.js';
import type { BoardDiagnostic, TlEdge, TlNode } from '../model.js';

export interface EdgeInput {
  /** Every node of the project, in file order. */
  nodes: readonly TlNode[];
  ownerOfDecl: ReadonlyMap<string, string>;
  /** Usable facts by name (fresh files fully, stale files by name). */
  declFacts: ReadonlyMap<string, DeclFacts>;
}

export interface EdgeResult {
  edges: TlEdge[];
  /** direct(v): nodes whose `.holds` v's proof uses (only for proved/conditional v). */
  direct: Map<string, string[]>;
  diagnostics: BoardDiagnostic[];
}

function isProvedOrConditional(node: TlNode): boolean {
  return node.status.proof.kind === 'proved' || node.status.proof.kind === 'conditional';
}

function onOf(node: TlNode): string[] {
  return node.status.proof.kind === 'conditional' ? node.status.proof.on : [];
}

/** The nodes whose `.holds` the proof of `node` uses, following untracked declarations. */
export function directUses(node: TlNode, input: Pick<EdgeInput, 'ownerOfDecl' | 'declFacts'>, holdsOwner: ReadonlyMap<string, string>): string[] {
  const statement = node.lean.statement;
  if (!statement) return [];
  const own = holdsName(statement);
  const start = input.declFacts.get(own);
  if (!start) return [];
  const out: string[] = [];
  const visited = new Set<string>([own]);
  const queue = start.refs.map((r) => r.name);
  while (queue.length > 0) {
    const name = queue.shift() as string;
    if (visited.has(name)) continue;
    visited.add(name);
    const user = holdsOwner.get(name);
    if (user !== undefined) {
      if (user !== node.id && !out.includes(user)) out.push(user);
      continue;
    }
    const owner = input.ownerOfDecl.get(name);
    if (owner !== undefined && (owner !== node.id || name === statement)) continue;
    const facts = input.declFacts.get(name);
    if (facts) for (const ref of facts.refs) if (!visited.has(ref.name)) queue.push(ref.name);
  }
  return out;
}

export function computeEdges(input: EdgeInput): EdgeResult {
  const byId = new Map(input.nodes.map((n) => [n.id, n]));
  const statementOwner = new Map<string, string>();
  const holdsOwner = new Map<string, string>();
  for (const node of input.nodes) {
    const statement = node.lean.statement;
    if (!statement || input.ownerOfDecl.get(statement) !== node.id) continue;
    statementOwner.set(statement, node.id);
    holdsOwner.set(holdsName(statement), node.id);
  }

  const direct = new Map<string, string[]>();
  for (const node of input.nodes) if (isProvedOrConditional(node)) direct.set(node.id, directUses(node, input, holdsOwner));

  const premiseEdges: TlEdge[] = [];
  const verifiedEdges: TlEdge[] = [];
  const refEdges: TlEdge[] = [];
  const seen = new Set<string>();
  const push = (list: TlEdge[], edge: TlEdge) => {
    if (seen.has(edge.id)) return;
    seen.add(edge.id);
    list.push(edge);
  };

  for (const node of input.nodes) {
    for (const premise of node.premises) {
      if (premise === node.id || !byId.has(premise)) continue;
      push(premiseEdges, { id: edgeId('premise', premise, node.id), type: 'premise', source: premise, target: node.id, origin: 'declared' });
    }
    const uses = direct.get(node.id) ?? [];
    for (const source of uses) {
      push(verifiedEdges, { id: edgeId('verified', source, node.id), type: 'verified', source, target: node.id, origin: 'lean', where: 'proof' });
    }
    for (const source of onOf(node)) {
      if (!byId.has(source) || source === node.id) continue;
      push(verifiedEdges, { id: edgeId('verified', source, node.id), type: 'verified', source, target: node.id, origin: 'lean', where: 'proof', conditional: true });
    }
    const statement = node.lean.statement;
    const facts = statement ? input.declFacts.get(statement) : undefined;
    if (facts && statement && statementOwner.get(statement) === node.id) {
      for (const ref of facts.refs) {
        const source = statementOwner.get(ref.name);
        if (source === undefined || source === node.id) continue;
        push(refEdges, { id: edgeId('lean-ref', source, node.id), type: 'lean-ref', source, target: node.id, origin: 'lean', where: 'statement' });
      }
    }
  }

  // D-13 mismatches, at the assumption level.
  const closureMemo = new Map<string, Set<string>>();
  const closure = (id: string, stack: Set<string> = new Set()): Set<string> => {
    const memo = closureMemo.get(id);
    if (memo) return memo;
    const out = new Set<string>();
    if (stack.has(id)) return out;
    stack.add(id);
    const node = byId.get(id);
    for (const u of [...(direct.get(id) ?? []), ...(node ? onOf(node) : [])]) {
      if (!byId.has(u)) continue;
      out.add(u);
      for (const w of closure(u, stack)) out.add(w);
    }
    stack.delete(id);
    closureMemo.set(id, out);
    return out;
  };
  const rests = (id: string): string[] => {
    const node = byId.get(id);
    if (!node || !isProvedOrConditional(node)) return [id];
    const proof = node.status.proof;
    const footprint = proof.kind === 'proved' ? proof.footprint : proof.kind === 'conditional' ? (proof.footprint ?? []) : [];
    return [...new Set([...footprint.filter((x) => byId.has(x)), ...onOf(node)])];
  };

  const diagnostics: BoardDiagnostic[] = [];
  const at = (node: TlNode) => (node.loc ? { file: node.loc.file, range: node.loc.range } : {});
  for (const node of input.nodes) {
    if (!isProvedOrConditional(node)) continue;
    const premises = node.premises.filter((p) => byId.has(p) && p !== node.id);
    const used = closure(node.id);
    for (const edge of premiseEdges) {
      if (edge.target !== node.id || used.has(edge.source)) continue;
      edge.mismatch = 'declared-unused';
      diagnostics.push({ code: 'TL109', severity: 'hint', message: `Declared premise "${edge.source}" is not used by the proof.`, nodeId: node.id, ...at(node) });
    }
    const covered = new Set(premises.flatMap((p) => rests(p)));
    for (const edge of verifiedEdges) {
      if (edge.target !== node.id || premises.includes(edge.source)) continue;
      if (rests(edge.source).every((x) => covered.has(x))) continue;
      edge.mismatch = 'used-undeclared';
      diagnostics.push({
        code: 'TL107',
        severity: 'warning',
        message: `The proof uses "${edge.source}", which the declared premises do not cover.`,
        nodeId: node.id,
        ...at(node),
      });
    }
  }

  return { edges: [...premiseEdges, ...verifiedEdges, ...refEdges], direct, diagnostics };
}

/**
 * `buildProjectModel` (docs/m1-plan.md sections 6.1, 6.3-6.5): bind every block to its declarations, merge the usable
 * Lean facts, classify the vocabulary, compute each node's card data and status, the edges and the diagnostics.
 * Pure: no I/O, deterministic for a given input.
 */
import type { DeclFacts } from '../facts.js';
import { holdsName, SORRY_AXIOM, STANDARD_AXIOM_NAMES } from '../facts.js';
import { PRESUPPOSITION_PREFIX } from '../graph.js';
import type {
  BoardDiagnostic,
  DerivedStatus,
  FileRange,
  LeanBinding,
  LeanRef,
  NodeType,
  ProofStatus,
  Range,
  Severity,
  StatusFlag,
  SubjectInfo,
  TlNode,
} from '../model.js';
import type { DeclInfo, MarkupBlock, ParsedFile } from '../markup/types.js';
import { isSubjectName, libraryRootFile, moduleOfPath, pathOfModule, subjectOfPath } from '../paths.js';
import { computeEdges, type EdgeResult } from './edges.js';
import { FactsIndex } from './factsIndex.js';
import type { ModelNode, ProjectInput, ProjectModel } from './types.js';
import { blankComments, cutText, LineMap, normalizeWhitespace, namespaceAt, rangeContains, splitTopLevelArrows } from './text.js';
import { anonymousInstanceName, buildVocabulary, resolveName, shapeOf, signatureText, type VocabCandidate, type VocabularyResult } from './vocabulary.js';

/** Canonical order of status flags (deterministic output). */
const FLAG_ORDER: readonly StatusFlag[] = [
  'no-rationale',
  'claimed',
  'missing-holds',
  'provable-assumption',
  'proved-goal',
  'uses-sorry',
  'holds-mismatch',
  'rests-on-claimed',
  'self-evident',
  'existence-commitment',
  'definitional-choice',
  'unselected-used',
  'broken',
  'depends-on-removed',
  'signoff-stale',
  'stale',
  'not-checked',
];

const SEVERITY_OF_LEAN: Readonly<Record<string, Severity>> = { error: 'error', warning: 'warning', information: 'info' };

interface Located {
  file: ParsedFile;
  decl: DeclInfo;
}

/** A piece of a card's code: a contiguous stretch of one file. */
interface CodePiece {
  file: ParsedFile;
  start: number;
  end: number;
  /** Which declarations' refs belong to it. */
  decls: string[];
}

interface Draft {
  id: string;
  file: ParsedFile;
  block: MarkupBlock;
  subject: string;
  type: NodeType;
  statement?: string;
  statementFound: boolean;
  /** TL113: bound to something that is not a Prop abbrev/def. */
  notProp: boolean;
  statementDecl?: Located;
  holds?: string;
  holdsDecl?: Located;
  holdsExists: boolean;
  statementFacts?: DeclFacts;
  holdsFacts?: DeclFacts;
  extraPinned: string[];
  leanError: boolean;
  diagnostics: BoardDiagnostic[];
  flags: Set<StatusFlag>;
  proof: ProofStatus;
  formal: DerivedStatus['formal'];
  lean: LeanBinding;
}

/** Internal results kept per model, so `subjectGraph` and `toGraphJson` need not recompute them. */
interface ModelInternals {
  edges: EdgeResult;
}

const internals = new WeakMap<ProjectModel, ModelInternals>();

/** The project's edges (computed once per model; recomputed from the model's public data for copies). */
export function edgesOf(model: ProjectModel): EdgeResult {
  const cached = internals.get(model);
  if (cached) return cached.edges;
  const edges = computeEdges({ nodes: [...model.nodes.values()].map((n) => n.node), ownerOfDecl: model.ownerOfDecl, declFacts: model.declFacts });
  internals.set(model, { edges });
  return edges;
}

function byPath(a: { path: string }, b: { path: string }): number {
  return a.path < b.path ? -1 : a.path > b.path ? 1 : 0;
}

function sortFlags(flags: Iterable<StatusFlag>): StatusFlag[] {
  return [...new Set(flags)].sort((a, b) => FLAG_ORDER.indexOf(a) - FLAG_ORDER.indexOf(b));
}

function compareDiagnostics(a: BoardDiagnostic, b: BoardDiagnostic): number {
  const fa = a.file ?? '￿';
  const fb = b.file ?? '￿';
  if (fa !== fb) return fa < fb ? -1 : 1;
  const la = a.range?.start.line ?? -1;
  const lb = b.range?.start.line ?? -1;
  if (la !== lb) return la - lb;
  const ca = a.range?.start.character ?? -1;
  const cb = b.range?.start.character ?? -1;
  if (ca !== cb) return ca - cb;
  if (a.code !== b.code) return a.code < b.code ? -1 : 1;
  return a.message < b.message ? -1 : a.message > b.message ? 1 : 0;
}

function dedupeDiagnostics(list: BoardDiagnostic[]): BoardDiagnostic[] {
  const seen = new Set<string>();
  const out: BoardDiagnostic[] = [];
  for (const d of list) {
    const key = JSON.stringify([d.code, d.file ?? null, d.range?.start ?? null, d.nodeId ?? null, d.vocab ?? null, d.message]);
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(d);
  }
  return out;
}

/** Is the statement a Prop abbrev/def (D-2(b))? From usable facts, else from the declaration text. */
function isPropStatement(draft: Draft): boolean {
  const facts = draft.statementFacts;
  if (facts && facts.type !== undefined) {
    const kindOk = facts.kind === undefined ? ['abbrev', 'def'].includes(draft.statementDecl?.decl.keyword ?? 'def') : facts.kind === 'def';
    return kindOk && normalizeWhitespace(facts.type) === 'Prop';
  }
  const located = draft.statementDecl;
  if (!located) return facts !== undefined && (facts.kind === undefined || facts.kind === 'def');
  if (located.decl.keyword !== 'abbrev' && located.decl.keyword !== 'def') return false;
  const signature = signatureText(located.file, located.decl);
  return signature !== undefined && signature.binders === '' && normalizeWhitespace(signature.type) === 'Prop';
}

/** `n.holds`'s kind as the board treats it: `other` (a def proving the statement, ...) counts like a theorem. */
function holdsKind(draft: Draft): 'axiom' | 'theorem' | 'other' | undefined {
  if (!draft.holdsExists) return undefined;
  const kind = draft.holdsFacts?.kind;
  if (kind === 'axiom') return 'axiom';
  if (kind === 'theorem') return 'theorem';
  if (kind !== undefined) return 'other';
  const keyword = draft.holdsDecl?.decl.keyword;
  if (keyword === 'axiom') return 'axiom';
  if (keyword === 'theorem' || keyword === 'lemma') return 'theorem';
  return keyword === undefined ? undefined : 'other';
}

function codePieces(draft: Draft): CodePiece[] {
  const statement = draft.statementDecl;
  const holds = draft.holdsDecl;
  if (!statement || !draft.statement) return [];
  const stmtPiece: CodePiece = { file: statement.file, start: statement.decl.span.start, end: statement.decl.span.end, decls: [draft.statement] };
  if (!holds || !draft.holds) return [stmtPiece];
  const holdsPiece: CodePiece = { file: holds.file, start: holds.decl.span.start, end: holds.decl.span.end, decls: [draft.holds] };
  if (holds.file.path === statement.file.path && holds.decl.span.start >= statement.decl.span.end) {
    const from = statement.decl.span.end;
    const to = holds.decl.span.start;
    const quiet =
      !holds.file.decls.some((d) => d.span.start >= from && d.span.start < to) &&
      !holds.file.blocks.some((b) => b.span.start >= from && b.span.start < to) &&
      blankComments(holds.file.text.slice(from, to)).trim() === '';
    if (quiet) return [{ file: statement.file, start: statement.decl.span.start, end: holds.decl.span.end, decls: [draft.statement, draft.holds] }];
  }
  return [stmtPiece, holdsPiece];
}

export function buildProject(input: ProjectInput): ProjectModel {
  const library = input.library;
  const files = [...input.files].sort(byPath);
  const fileMap = new Map(files.map((f) => [f.path, f]));
  const factsIndex = new FactsIndex(files, input.fileHashes, input.facts);
  const diagnostics: BoardDiagnostic[] = [];
  const lineMaps = new Map<string, LineMap>();
  const lines = (file: ParsedFile): LineMap => {
    let map = lineMaps.get(file.path);
    if (!map) {
      map = new LineMap(file.text);
      lineMaps.set(file.path, map);
    }
    return map;
  };

  // ---- subjects
  const subjectOfFile = new Map<string, string>();
  for (const file of files) {
    const subject = subjectOfPath(file.path, library);
    if (subject !== undefined && isSubjectName(subject)) subjectOfFile.set(file.path, subject);
  }
  const subjectNames = [...new Set(subjectOfFile.values())].sort();

  // ---- syntactic declarations by name, and every name Lean or the text knows
  const syntactic = new Map<string, Located>();
  for (const file of files) for (const decl of file.decls) if (decl.fullName && !syntactic.has(decl.fullName)) syntactic.set(decl.fullName, { file, decl });
  const known = (name: string) => syntactic.has(name) || factsIndex.usable.has(name);

  // ---- ids (written ids win; derived ids are suffixed on collisions, files in path order)
  const writtenIds = new Set<string>();
  for (const file of files) for (const block of file.blocks) if (block.idWritten && block.id) writtenIds.add(block.id);
  const assigned = new Map<string, { file: string; range: Range }>();
  const blockIds = new Map<MarkupBlock, string>();
  const drafts: Draft[] = [];
  for (const file of files) {
    for (const block of file.blocks) {
      if (!block.id || block.fields.type === undefined || block.fields.naturalName === undefined) continue;
      let id = block.id;
      if (block.idWritten) {
        const first = assigned.get(id);
        if (first) {
          diagnostics.push({
            code: 'TL006',
            severity: 'error',
            message: `Duplicate id "${id}": the block in ${first.file} (line ${first.range.start.line + 1}) keeps it. Give this block another id.`,
            file: file.path,
            range: block.range,
          });
          continue;
        }
      } else if (assigned.has(id) || writtenIds.has(id)) {
        let n = 2;
        while (assigned.has(`${block.id}-${n}`) || writtenIds.has(`${block.id}-${n}`)) n++;
        id = `${block.id}-${n}`;
      }
      assigned.set(id, { file: file.path, range: block.range });
      blockIds.set(block, id);
      const subject = subjectOfFile.get(file.path);
      if (subject === undefined) {
        diagnostics.push({
          code: 'TL120',
          severity: 'warning',
          message: `This block is outside any subject: move it into ${library}/<Subject>/ (a subject is a module subtree with its own namespace).`,
          file: file.path,
          range: block.range,
        });
        continue;
      }
      drafts.push({
        id,
        file,
        block,
        subject,
        type: block.fields.type,
        statementFound: false,
        notProp: false,
        holdsExists: false,
        extraPinned: [],
        leanError: false,
        diagnostics: [],
        flags: new Set(),
        proof: { kind: 'none' },
        formal: 'informal',
        lean: { binding: block.binding.mode },
      });
    }
  }

  // ---- binding
  for (const draft of drafts) {
    const binding = draft.block.binding;
    if (binding.mode === 'none') continue;
    let statement = binding.statement;
    if (binding.mode === 'adjacent') {
      const decl = binding.adjacentDecl !== undefined ? draft.file.decls[binding.adjacentDecl] : undefined;
      if (decl) {
        statement = decl.fullName;
        if (statement) draft.statementDecl = { file: draft.file, decl };
      }
    } else {
      const namespace = namespaceAt(draft.file.text, draft.block.span.start);
      const resolve = (name: string) => (known(name) ? name : (resolveName(name, namespace, known) ?? name));
      if (statement) statement = resolve(statement);
      draft.extraPinned = (binding.pinned ?? []).slice(1).map(resolve);
      if (statement) {
        const located = syntactic.get(statement);
        if (located) draft.statementDecl = located;
      }
    }
    if (!statement) {
      draft.notProp = binding.mode === 'adjacent';
      continue;
    }
    draft.statement = statement;
    draft.statementFound = known(statement);
    draft.holds = holdsName(statement);
    const holdsDecl = syntactic.get(draft.holds);
    if (holdsDecl) draft.holdsDecl = holdsDecl;
    const statementFacts = factsIndex.usable.get(statement);
    if (statementFacts) draft.statementFacts = statementFacts;
    const holdsFacts = factsIndex.usable.get(draft.holds);
    if (holdsFacts) draft.holdsFacts = holdsFacts;
    draft.holdsExists = Boolean(holdsDecl || holdsFacts);
  }

  // ---- ownership (statement and `.holds`), TL017
  const ownerOfDecl = new Map<string, string>();
  for (const draft of drafts) {
    if (!draft.statement || !draft.statementFound) continue;
    const owner = ownerOfDecl.get(draft.statement);
    if (owner !== undefined && owner !== draft.id) {
      draft.diagnostics.push({
        code: 'TL017',
        severity: 'error',
        message: `${draft.statement} is already bound to "${owner}": a declaration can belong to one card only.`,
        file: draft.file.path,
        range: draft.block.range,
        nodeId: draft.id,
      });
      continue;
    }
    ownerOfDecl.set(draft.statement, draft.id);
    if (draft.holds && draft.holdsExists && !ownerOfDecl.has(draft.holds)) ownerOfDecl.set(draft.holds, draft.id);
    for (const name of draft.extraPinned) if (known(name) && !ownerOfDecl.has(name)) ownerOfDecl.set(name, draft.id);
  }

  // ---- vocabulary
  const candidates: VocabCandidate[] = [];
  const folded = new Map<string, string>();
  for (const file of files) {
    const subject = subjectOfFile.get(file.path);
    if (subject === undefined) continue;
    const state = factsIndex.stateOf(file.path);
    const names: string[] = [];
    for (const decl of file.decls) {
      if (decl.keyword === 'example' || decl.keyword === 'mutual') continue;
      const facts = factsIndex.factsFor(file, decl);
      const name = decl.fullName ?? facts?.name ?? (decl.keyword === 'instance' ? anonymousInstanceName(file, decl) : undefined);
      if (!name || names.includes(name) || ownerOfDecl.has(name)) continue;
      names.push(name);
      if (facts?.parent) {
        folded.set(name, facts.parent);
        continue;
      }
      candidates.push({ shape: shapeOf(file, decl, facts, name, known), subject, file, decl, ...(facts ? { facts } : {}), stale: state === 'stale' });
    }
    for (const facts of factsIndex.unmatched.get(file.path) ?? []) {
      if (names.includes(facts.name) || ownerOfDecl.has(facts.name)) continue;
      names.push(facts.name);
      const parent = facts.parent ?? names.find((n) => n !== facts.name && facts.name.startsWith(`${n}.`));
      if (parent !== undefined) {
        folded.set(facts.name, parent);
        continue;
      }
      candidates.push({ shape: shapeOf(file, undefined, facts, facts.name, known), subject, file, facts, stale: false });
    }
  }
  const vocab: VocabularyResult = buildVocabulary(candidates, subjectNames);
  for (let pass = 0; pass < 3; pass++) {
    for (const [name, parent] of folded) {
      const item = vocab.itemOfName.get(parent);
      if (item !== undefined && !vocab.itemOfName.has(name)) vocab.itemOfName.set(name, item);
    }
  }
  const isPresupposition = (name: string) => vocab.kindOf.get(name) === 'presupposition' && vocab.itemOfName.get(name) === name;

  // ---- Lean messages (trusted positions only where the build saw the current text)
  const trustworthy = (path: string) => {
    const info = factsIndex.files.get(path);
    return info !== undefined && info.module !== undefined && !info.hashDiffers;
  };
  const containing = (path: string, range: Range | undefined): { nodeId?: string; vocab?: string } => {
    if (!range || !trustworthy(path)) return {};
    for (const draft of drafts) {
      for (const located of [draft.statementDecl, draft.holdsDecl]) {
        if (located && located.file.path === path && rangeContains(located.decl.range, range.start)) return { nodeId: draft.id };
      }
    }
    for (const item of vocab.items) if (item.loc && item.loc.file === path && rangeContains(item.loc.range, range.start)) return { vocab: item.name };
    return {};
  };
  for (const message of input.facts?.build.messages ?? []) {
    const severity = SEVERITY_OF_LEAN[message.severity] ?? 'info';
    const where = message.file ? containing(message.file, message.range) : {};
    diagnostics.push({
      code: 'LEAN',
      severity,
      message: message.text,
      ...(message.file ? { file: message.file } : {}),
      ...(message.range ? { range: message.range } : {}),
      ...where,
    });
    if (severity === 'error' && where.nodeId !== undefined) {
      const draft = drafts.find((d) => d.id === where.nodeId);
      if (draft) draft.leanError = true;
    }
  }

  // ---- per node: formal, card data, base proof status
  const byId = new Map(drafts.map((d) => [d.id, d]));
  const ownerStatement = (id: string) => byId.get(id)?.statement;
  for (const draft of drafts) {
    const block = draft.block;
    const binding = block.binding.mode;
    const at = { file: draft.file.path, range: block.range, nodeId: draft.id };
    if (draft.type === 'ASSUMPTION' && block.fields.rationale === undefined) {
      draft.flags.add('no-rationale');
      draft.diagnostics.push({ code: 'TL011', severity: 'info', message: 'No rationale yet: why do you hold it?', ...at });
    }
    if (binding === 'none') continue;

    // formal
    if (!draft.statement) {
      draft.formal = 'ill-formed';
      draft.diagnostics.push({ code: 'TL113', severity: 'error', message: 'This card is bound to a declaration without a name: bind it to `abbrev n : Prop := …` (with `axiom n.holds : n`).', ...at });
    } else if (!draft.statementFound) {
      draft.formal = 'ill-formed';
      draft.diagnostics.push({ code: 'TL101', severity: 'error', message: `Lean declaration ${draft.statement} not found.`, ...at });
    } else if (!isPropStatement(draft)) {
      draft.formal = 'ill-formed';
      draft.notProp = true;
      const short = draft.statement.split('.').pop() ?? draft.statement;
      draft.diagnostics.push({
        code: 'TL113',
        severity: 'error',
        message: `${draft.statement} is not a Prop abbrev/def: write \`abbrev ${short} : Prop := …\` and \`axiom ${short}.holds : ${short}\`.`,
        ...at,
      });
    } else draft.formal = draft.leanError ? 'ill-formed' : 'formalized';

    const statement = draft.statement;
    const lean: LeanBinding = { binding, ...(statement ? { statement } : {}) };
    const hk = draft.statementFound && !draft.notProp ? holdsKind(draft) : undefined;
    if (statement && draft.statementFound && draft.holdsExists && draft.holds) lean.justification = draft.holds;
    if (hk) lean.justificationKind = hk;

    // code and codeLoc
    const pieces = draft.statementFound ? codePieces(draft) : [];
    if (pieces.length > 0) {
      lean.code = pieces.map((p) => p.file.text.slice(p.start, p.end)).join('\n\n');
      const first = pieces[0] as CodePiece;
      const last = pieces[pieces.length - 1] as CodePiece;
      const end = last.file.path === first.file.path ? last.end : first.end;
      const loc: FileRange = { file: first.file.path, range: lines(first.file).rangeOf(first.start, end) };
      lean.codeLoc = loc;
    }

    // uses (statement closure) and presupposes
    if (statement && draft.statementFacts) {
      const uses: string[] = [];
      const visited = new Set([statement]);
      const queue = [statement];
      while (queue.length > 0) {
        const name = queue.shift() as string;
        const facts = factsIndex.usable.get(name);
        if (!facts) continue;
        for (const ref of facts.refs) {
          const item = vocab.itemOfName.get(ref.name);
          if (item !== undefined && !uses.includes(item)) uses.push(item);
          const owner = ownerOfDecl.get(ref.name);
          const throughNode = owner !== undefined && ownerStatement(owner) === ref.name;
          const throughDefinition = item === ref.name && vocab.kindOf.get(item) === 'definition';
          if ((throughNode || throughDefinition) && !visited.has(ref.name)) {
            visited.add(ref.name);
            queue.push(ref.name);
          }
        }
      }
      lean.uses = uses;
      if (draft.statementFacts.axioms) lean.presupposes = draft.statementFacts.axioms.filter(isPresupposition);
    }
    if (draft.holdsFacts?.axioms) lean.axioms = [...draft.holdsFacts.axioms];

    // refs: code-relative, fresh files only
    if (pieces.length > 0 && pieces.every((p) => factsIndex.isFresh(p.file.path))) {
      const refs: LeanRef[] = [];
      let lineOffset = 0;
      for (const piece of pieces) {
        const map = lines(piece.file);
        const start = map.positionAt(piece.start);
        const end = map.positionAt(piece.end);
        for (const declName of piece.decls) {
          const facts = factsIndex.usable.get(declName);
          for (const ref of facts?.refs ?? []) {
            const owner = ownerOfDecl.get(ref.name);
            const ownerStmt = owner !== undefined ? ownerStatement(owner) : undefined;
            const nodeRef = ownerStmt !== undefined && (ref.name === ownerStmt || ref.name === holdsName(ownerStmt));
            if (!nodeRef && !vocab.itemOfName.has(ref.name)) continue;
            if (ref.range.start.line < start.line || ref.range.end.line > end.line) continue;
            const shift = (p: { line: number; character: number }) => ({
              line: p.line - start.line + lineOffset,
              character: p.line === start.line ? p.character - start.character : p.character,
            });
            refs.push({ name: ref.name, range: { start: shift(ref.range.start), end: shift(ref.range.end) }, ...(nodeRef && owner !== undefined ? { nodeId: owner } : {}) });
          }
        }
        lineOffset += end.line - start.line + 2;
      }
      lean.refs = refs;
    }
    draft.lean = lean;

    // stale / not-checked
    const declFiles = [draft.statementDecl?.file.path ?? draft.statementFacts?.file, draft.holdsDecl?.file.path ?? draft.holdsFacts?.file].filter(
      (p): p is string => p !== undefined,
    );
    if (declFiles.some((p) => factsIndex.files.get(p)?.hashDiffers || factsIndex.stateOf(p) === 'stale')) draft.flags.add('stale');
    if (draft.statementFound && (draft.statementFacts === undefined || (draft.holdsExists && draft.holdsFacts === undefined))) draft.flags.add('not-checked');

    // proof (docs/m1-plan.md section 6.3 table)
    if (!draft.statementFound || draft.notProp || !statement) continue;
    const short = statement.split('.').pop() ?? statement;
    if (!draft.holdsExists) {
      if (draft.type === 'ASSUMPTION') {
        draft.flags.add('missing-holds');
        draft.diagnostics.push({
          code: 'TL117',
          severity: 'warning',
          message: `This assumption has no \`axiom ${short}.holds : ${short}\`, so proofs cannot use it.`,
          ...at,
        });
      }
      continue;
    }
    const holdsFacts = draft.holdsFacts;
    if (hk === 'axiom') {
      if (draft.type === 'ASSUMPTION') draft.proof = { kind: 'assumed' };
      else if (draft.type === 'DERIVATION') {
        draft.proof = { kind: 'pending-promotion' };
        draft.flags.add('claimed');
      } else {
        draft.proof = { kind: 'assumed' };
        draft.diagnostics.push({ code: 'TL116', severity: 'warning', message: `This goal is asserted as an axiom (${draft.holds}): make it an Assumption?`, ...at });
      }
      if (holdsFacts?.type !== undefined && normalizeWhitespace(holdsFacts.type) !== statement) {
        draft.flags.add('holds-mismatch');
        draft.diagnostics.push({ code: 'TL114', severity: 'error', message: `${draft.holds} does not state ${statement} (its type is ${normalizeWhitespace(holdsFacts.type)}).`, ...at });
      }
      continue;
    }
    // theorem (or another kind, treated like a theorem): needs Lean's facts
    if (!holdsFacts || holdsFacts.type === undefined || holdsFacts.axioms === undefined) {
      draft.flags.add('not-checked');
      continue;
    }
    if (holdsFacts.usesSorry || holdsFacts.axioms.includes(SORRY_AXIOM)) {
      draft.flags.add('uses-sorry');
      draft.diagnostics.push({ code: 'TL115', severity: 'warning', message: 'The proof uses `sorry`.', ...at });
      continue;
    }
    const type = normalizeWhitespace(holdsFacts.type);
    let on: string[] | undefined;
    if (type === statement) on = [];
    else {
      const parts = splitTopLevelArrows(type);
      if (parts.length > 1 && parts[parts.length - 1] === statement) {
        const hyps: string[] = [];
        for (const part of parts.slice(0, -1)) {
          const owner = ownerOfDecl.get(part);
          if (owner === undefined || ownerStatement(owner) !== part) {
            hyps.length = 0;
            break;
          }
          if (!hyps.includes(owner)) hyps.push(owner);
        }
        if (hyps.length > 0) on = hyps;
      }
    }
    if (on === undefined) {
      draft.flags.add('holds-mismatch');
      draft.diagnostics.push({ code: 'TL114', severity: 'error', message: `${draft.holds} does not state ${statement} (its type is ${type}).`, ...at });
      continue;
    }
    // footprint
    const nodesIn: string[] = [];
    const presups: string[] = [];
    const others: string[] = [];
    for (const axiom of holdsFacts.axioms) {
      if (STANDARD_AXIOM_NAMES.includes(axiom)) continue;
      const owner = ownerOfDecl.get(axiom);
      const ownerStmt = owner !== undefined ? ownerStatement(owner) : undefined;
      if (owner !== undefined && ownerStmt !== undefined && axiom === holdsName(ownerStmt)) {
        if (!nodesIn.includes(owner)) nodesIn.push(owner);
        continue;
      }
      if (isPresupposition(axiom)) {
        presups.push(`${PRESUPPOSITION_PREFIX}${axiom}`);
        continue;
      }
      const item = vocab.itemOfName.get(axiom);
      const kind = item !== undefined ? vocab.kindOf.get(item) : undefined;
      const harmless = kind === 'sort' || kind === 'predicate' || ((kind === 'function' || kind === 'constant') && !vocab.declaredWithAxiom.has(item ?? ''));
      if (harmless) continue;
      others.push(`axiom:${axiom}`);
      draft.diagnostics.push({
        code: 'TL103',
        severity: 'warning',
        message: `The proof uses ${axiom}, which is neither an assumption (a card's \`.holds\`) nor vocabulary.`,
        ...at,
        ...(item !== undefined ? { vocab: item } : {}),
      });
    }
    const footprint = [...nodesIn, ...presups, ...others];
    draft.proof = on.length > 0 ? { kind: 'conditional', on, footprint } : { kind: 'proved', footprint };
    if (draft.type === 'ASSUMPTION') {
      draft.flags.add('provable-assumption');
      draft.diagnostics.push({ code: 'TL106', severity: 'info', message: 'This assumption has a proof: make it a Derivation?', ...at });
    } else if (draft.type === 'GOAL') {
      draft.flags.add('proved-goal');
      draft.diagnostics.push({ code: 'TL105', severity: 'info', message: 'This goal is already proved: make it a Derivation?', ...at });
    }
  }

  // ---- flags that depend on other nodes
  for (const draft of drafts) {
    const proof = draft.proof;
    if (proof.kind !== 'proved' && proof.kind !== 'conditional') continue;
    const at = { file: draft.file.path, range: draft.block.range, nodeId: draft.id };
    const footprint = proof.kind === 'proved' ? proof.footprint : (proof.footprint ?? []);
    const footprintNodes = footprint.map((x) => byId.get(x)).filter((d): d is Draft => d !== undefined);
    if (footprintNodes.some((d) => d.proof.kind === 'pending-promotion')) draft.flags.add('rests-on-claimed');
    if (proof.kind === 'proved' && footprintNodes.length === 0) draft.flags.add('self-evident');
    const onNodes = proof.kind === 'conditional' ? proof.on.map((x) => byId.get(x)).filter((d): d is Draft => d !== undefined) : [];
    const covered = new Set([...(draft.lean.presupposes ?? []), ...[...footprintNodes, ...onNodes].flatMap((d) => d.lean.presupposes ?? [])]);
    const uncovered = footprint.filter((x) => x.startsWith(PRESUPPOSITION_PREFIX) && !covered.has(x.slice(PRESUPPOSITION_PREFIX.length)));
    if (uncovered.length > 0) {
      draft.flags.add('existence-commitment');
      const names = uncovered.map((x) => x.slice(PRESUPPOSITION_PREFIX.length));
      draft.diagnostics.push({
        code: 'TL108',
        severity: 'info',
        message: `The proof needs ${names.join(', ')} (existence assumption${names.length === 1 ? '' : 's'}) that no statement it uses mentions.`,
        ...at,
      });
    }
    if (proof.kind === 'conditional') {
      draft.diagnostics.push({ code: 'TL102', severity: 'warning', message: `The proof is conditional on unproved cards: ${proof.on.join(', ')}.`, ...at });
    }
    const goals = footprintNodes.filter((d) => d.type === 'GOAL').map((d) => d.id);
    if (goals.length > 0) {
      draft.diagnostics.push({ code: 'TL102', severity: 'warning', message: `The proof rests on a goal asserted as an axiom: ${goals.join(', ')}.`, ...at });
    }
  }
  for (const draft of drafts) {
    if ((draft.lean.uses ?? []).some((name) => vocab.kindOf.get(name) === 'definition')) draft.flags.add('definitional-choice');
  }

  // ---- premises: TL007 dangling, TL121 other subject, TL015 cycles
  for (const draft of drafts) {
    const at = { file: draft.file.path, range: draft.block.range, nodeId: draft.id };
    for (const premise of draft.block.fields.premises ?? []) {
      const target = byId.get(premise);
      if (!target) draft.diagnostics.push({ code: 'TL007', severity: 'warning', message: `Premise "${premise}" does not exist.`, ...at });
      else if (target.subject !== draft.subject) {
        draft.diagnostics.push({
          code: 'TL121',
          severity: 'warning',
          message: `Premise "${premise}" belongs to subject ${target.subject}: premises stay within one subject.`,
          ...at,
        });
      }
    }
  }
  const inCycle = new Set<string>();
  {
    const state = new Map<string, 'visiting' | 'done'>();
    const stack: string[] = [];
    const visit = (id: string) => {
      state.set(id, 'visiting');
      stack.push(id);
      for (const premise of byId.get(id)?.block.fields.premises ?? []) {
        if (!byId.has(premise)) continue;
        const mark = state.get(premise);
        if (mark === 'visiting') for (const x of stack.slice(stack.indexOf(premise))) inCycle.add(x);
        else if (mark === undefined) visit(premise);
      }
      stack.pop();
      state.set(id, 'done');
    };
    for (const draft of drafts) if (!state.has(draft.id)) visit(draft.id);
  }
  for (const draft of drafts) {
    if (!inCycle.has(draft.id)) continue;
    draft.diagnostics.push({
      code: 'TL015',
      severity: 'warning',
      message: 'This card is part of a premise cycle: a card cannot (indirectly) support itself.',
      file: draft.file.path,
      range: draft.block.range,
      nodeId: draft.id,
    });
  }

  // ---- nodes
  const nodes = new Map<string, ModelNode>();
  for (const draft of drafts) {
    const block = draft.block;
    const fields = block.fields;
    const ext: Record<string, string> = {};
    for (const key of Object.keys(block.extensions).sort()) ext[key] = (block.extensions[key] ?? []).join('\n');
    const wordedBy = fields.wordedBy ?? 'user';
    const node: TlNode = {
      id: draft.id,
      type: draft.type,
      role: 'node',
      subject: draft.subject,
      naturalName: fields.naturalName ?? '',
      ...(fields.rationale !== undefined ? { rationale: fields.rationale } : {}),
      ...(block.body !== undefined ? { body: block.body } : {}),
      ...(fields.asserted !== undefined ? { asserted: fields.asserted } : {}),
      ...(fields.stance !== undefined ? { stance: fields.stance } : {}),
      ...(fields.source !== undefined ? { source: fields.source } : {}),
      premises: [...(fields.premises ?? [])],
      ...(fields.supersedes !== undefined ? { supersedes: fields.supersedes } : {}),
      ...(fields.refines !== undefined ? { refines: fields.refines } : {}),
      provenance: {
        wordedBy,
        endorsed: wordedBy === 'user',
        origin: fields.origin ?? 'user',
        ...(fields.session !== undefined ? { session: fields.session } : {}),
      },
      ext,
      loc: { file: draft.file.path, range: block.range, markupVersion: block.version },
      lean: draft.lean,
      status: {
        formal: draft.formal,
        proof: draft.proof,
        certificates: { consistency: 'none', nonVacuity: 'none' },
        flags: sortFlags(draft.flags),
      },
    };
    nodes.set(draft.id, {
      node,
      file: draft.file.path,
      block,
      ...(draft.statementDecl ? { statementDecl: { file: draft.statementDecl.file.path, decl: draft.statementDecl.decl } } : {}),
      ...(draft.holdsDecl ? { holdsDecl: { file: draft.holdsDecl.file.path, decl: draft.holdsDecl.decl } } : {}),
    });
  }

  // ---- edges and mismatches
  const edges = computeEdges({ nodes: [...nodes.values()].map((n) => n.node), ownerOfDecl, declFacts: factsIndex.usable });

  // ---- vocabulary usedBy and definitional choices
  const itemsByName = new Map(vocab.items.map((item) => [item.name, item]));
  for (const { node } of nodes.values()) {
    for (const name of [...(node.lean.uses ?? []), ...(node.lean.presupposes ?? [])]) {
      const item = itemsByName.get(name);
      if (item && !item.usedBy.includes(node.id)) item.usedBy.push(node.id);
    }
    for (const name of node.lean.uses ?? []) {
      const item = itemsByName.get(name);
      if (item && item.kind === 'definition' && !item.flags.includes('definitional-choice')) item.flags.push('definitional-choice');
    }
  }

  // ---- markup diagnostics (with node ids), TL118, everything else
  const blockAt = (file: ParsedFile, offset: number) => file.blocks.find((b) => offset >= b.span.start && offset < b.span.end);
  for (const file of files) {
    for (const d of file.diagnostics) {
      const block = blockAt(file, d.span.start);
      const resolved = block ? blockIds.get(block) : undefined;
      const nodeId = resolved !== undefined && nodes.has(resolved) ? resolved : d.nodeId !== undefined && nodes.has(d.nodeId) ? d.nodeId : undefined;
      diagnostics.push({ code: d.code, severity: d.severity, message: d.message, file: file.path, range: d.range, ...(nodeId !== undefined ? { nodeId } : {}) });
    }
  }
  const rootPath = libraryRootFile(library);
  const root = fileMap.get(rootPath);
  if (root) {
    const reached = new Set<string>([rootPath]);
    const queue = [root];
    while (queue.length > 0) {
      const file = queue.shift() as ParsedFile;
      for (const module of file.imports) {
        const path = pathOfModule(module);
        const target = fileMap.get(path);
        if (target && !reached.has(path)) {
          reached.add(path);
          queue.push(target);
        }
      }
    }
    for (const file of files) {
      if (reached.has(file.path) || moduleOfPath(file.path) === undefined) continue;
      diagnostics.push({
        code: 'TL118',
        severity: 'warning',
        message: `This file is not imported by ${rootPath}, so Lean never checks it.`,
        file: file.path,
        range: { start: { line: 0, character: 0 }, end: { line: 0, character: 0 } },
      });
    }
  }
  for (const draft of drafts) {
    // Do not repeat TL011 when the markup layer already reported it for this block.
    const markupTl011 = draft.file.diagnostics.some((d) => d.code === 'TL011' && d.span.start >= draft.block.span.start && d.span.start < draft.block.span.end);
    for (const d of draft.diagnostics) if (!(d.code === 'TL011' && markupTl011)) diagnostics.push(d);
  }
  diagnostics.push(...vocab.diagnostics, ...edges.diagnostics);

  // ---- subjects
  const subjects: SubjectInfo[] = subjectNames.map((name) => ({
    name,
    nodeCount: drafts.filter((d) => d.subject === name).length,
    files: files.filter((f) => subjectOfFile.get(f.path) === name).map((f) => f.path),
  }));

  const model: ProjectModel = {
    library,
    subjects,
    nodes,
    files: fileMap,
    ...(input.facts ? { facts: input.facts } : {}),
    freshFiles: factsIndex.freshFiles(),
    vocabulary: vocab.items,
    diagnostics: dedupeDiagnostics(diagnostics).sort(compareDiagnostics),
    declFacts: factsIndex.usable,
    ownerOfDecl,
  };
  internals.set(model, { edges });
  return model;
}

/** One line for the history and toasts (exported for the planner). */
export function sentenceLabel(text: string): string {
  return cutText(text, 60);
}

