/**
 * One subject's board (docs/m1-plan.md sections 5.3 and 6.3): its nodes in column order (layout.json first, then file
 * order), the edges with both ends in the subject, its Vocabulary group and its diagnostics.
 */
import { orderByLayout } from '../layout.js';
import type { BoardDiagnostic, TlGraph, TlNode } from '../model.js';
import { NODE_TYPES } from '../model.js';
import { edgesOf } from './build.js';
import type { ProjectModel, SubjectGraphOptions } from './types.js';

/** Which subject a diagnostic belongs to, or undefined for project-level ones (files outside every subject). */
function subjectOfDiagnostic(model: ProjectModel, d: BoardDiagnostic, fileSubject: ReadonlyMap<string, string>, vocabSubject: ReadonlyMap<string, string>): string | undefined {
  if (d.nodeId !== undefined) {
    const node = model.nodes.get(d.nodeId);
    if (node) return node.node.subject;
  }
  if (d.vocab !== undefined) {
    const subject = vocabSubject.get(d.vocab);
    if (subject !== undefined) return subject;
  }
  if (d.file !== undefined) return fileSubject.get(d.file);
  return undefined;
}

export function buildSubjectGraph(model: ProjectModel, subject: string, options: SubjectGraphOptions): TlGraph {
  const subjectNodes: TlNode[] = [];
  for (const entry of model.nodes.values()) if (entry.node.subject === subject) subjectNodes.push(entry.node);
  const byId = new Map(subjectNodes.map((n) => [n.id, n]));
  const order = orderByLayout(subjectNodes, options.layout);
  const nodes = NODE_TYPES.flatMap((type) => order[type].map((id) => byId.get(id) as TlNode));

  const edges = edgesOf(model).edges.filter((e) => byId.has(e.source) && byId.has(e.target));

  const vocabulary = model.vocabulary.filter((item) => item.subject === subject).map((item) => ({ ...item, usedBy: item.usedBy.filter((id) => byId.has(id)) }));

  const fileSubject = new Map<string, string>();
  for (const info of model.subjects) for (const file of info.files) fileSubject.set(file, info.name);
  const vocabSubject = new Map(model.vocabulary.map((item) => [item.name, item.subject]));
  const diagnostics = model.diagnostics.filter((d) => {
    const owner = subjectOfDiagnostic(model, d, fileSubject, vocabSubject);
    // Project-level problems (e.g. a block outside every subject, TL120) are shown on every board.
    return owner === undefined ? d.file === undefined || !fileSubject.has(d.file) : owner === subject;
  });

  return { version: options.version, subject, nodes, edges, vocabulary, diagnostics, semantic: options.semantic };
}

/**
 * WP-model: building the project model and one subject's board graph (docs/m1-plan.md sections 5.3 and 6).
 * Signatures and documented behaviour are FROZEN; the implementation lives in ./build.ts and ./subjectGraph.ts.
 */
import type { TlGraph } from '../model.js';
import { buildProject } from './build.js';
import { buildSubjectGraph } from './subjectGraph.js';
import type { ProjectInput, ProjectModel, SubjectGraphOptions } from './types.js';

export * from './types.js';

/**
 * Steps 2-5 of 03 section 2: bind blocks to declarations, merge the Lean facts, add vocabulary / presupposition /
 * untracked items, validate (TL1xx), and derive every node's status (D-15) and `lean` card data.
 * Facts are trusted fully only where the file hash matches. For a stale file (docs/m1-plan.md section 6.3) a
 * declaration keeps its previous facts BY NAME while its current syntactic keyword agrees with the facts' kind
 * (flag `stale`; refs dropped, `uses` kept); otherwise it falls back to the syntactic keyword (a theorem then shows
 * no proof, flagged `stale`/`not-checked`: the board never claims "proved" without Lean).
 */
export function buildProjectModel(input: ProjectInput): ProjectModel {
  return buildProject(input);
}

/**
 * One subject's board: its nodes in column order (layout first, then file order), declared + verified edges
 * (with D-13 mismatch flags), its vocabulary group, its diagnostics, and the semantic summary.
 * An unknown subject yields an empty board (its project-level diagnostics only).
 */
export function subjectGraph(model: ProjectModel, subject: string, options: SubjectGraphOptions): TlGraph {
  return buildSubjectGraph(model, subject, options);
}

/**
 * A small stand-in for WP-markup's `parseLeanFile`, good enough for the model builder's tests while WP-markup is a
 * stub (docs/m1-plan.md section 9, R7). It follows the frozen ParsedFile contract (markup/types.ts) and the binding
 * and command-start rules of section 6.1 for the simple Lean the fixtures use: blocks (`/- @@ telelean ... -/`),
 * top-level declarations with docstrings, attributes and modifiers, namespaces, imports. Not a Lean parser.
 * The gated tests run the same scenarios through the real parser once WP-markup is implemented.
 */
import type { BlockBinding, BlockFields, DeclInfo, DeclKeyword, FieldLine, MarkupBlock, ParsedFile, Span } from '../../../src/markup/types.js';
import type { Evidential, NodeType, Range, Stance } from '../../../src/model.js';

const DECL_KEYWORDS = ['axiom', 'theorem', 'lemma', 'def', 'abbrev', 'opaque', 'instance', 'example', 'inductive', 'coinductive', 'structure', 'class', 'mutual'];
const MODIFIERS = ['private', 'public', 'protected', 'noncomputable', 'unsafe', 'partial', 'nonrec', 'scoped', 'local', 'meta'];
const OTHER_COMMANDS = [
  'end',
  'namespace',
  'section',
  'open',
  'export',
  'variable',
  'universe',
  'set_option',
  'attribute',
  'notation',
  'infix',
  'infixl',
  'infixr',
  'prefix',
  'postfix',
  'macro',
  'macro_rules',
  'syntax',
  'elab',
  'deriving',
  'initialize',
  'import',
];
const COMMAND_WORDS = new Set([...DECL_KEYWORDS, ...MODIFIERS, ...OTHER_COMMANDS]);
const IDENT_AT = /^(?:_root_\.)?[\p{L}_«][\p{L}\p{N}_'!?«».]*/u;

interface Comment {
  kind: 'line' | 'block' | 'doc' | 'moddoc';
  start: number;
  end: number;
}

class Lines {
  readonly starts: number[] = [0];
  constructor(readonly text: string) {
    for (let i = 0; i < text.length; i++) if (text[i] === '\n') this.starts.push(i + 1);
  }
  pos(offset: number) {
    let line = 0;
    while (line + 1 < this.starts.length && (this.starts[line + 1] ?? Infinity) <= offset) line++;
    return { line, character: offset - (this.starts[line] ?? 0) };
  }
  range(span: Span): Range {
    return { start: this.pos(span.start), end: this.pos(span.end) };
  }
}

function scanComments(text: string): Comment[] {
  const out: Comment[] = [];
  let i = 0;
  while (i < text.length) {
    if (text.startsWith('--', i)) {
      let j = i;
      while (j < text.length && text[j] !== '\n') j++;
      out.push({ kind: 'line', start: i, end: j });
      i = j;
    } else if (text.startsWith('/-', i)) {
      const kind = text.startsWith('/--', i) && !text.startsWith('/--/', i) ? 'doc' : text.startsWith('/-!', i) ? 'moddoc' : 'block';
      let depth = 1;
      let j = i + 2;
      while (j < text.length && depth > 0) {
        if (text.startsWith('/-', j)) {
          depth++;
          j += 2;
        } else if (text.startsWith('-/', j)) {
          depth--;
          j += 2;
        } else j++;
      }
      out.push({ kind, start: i, end: j });
      i = j;
    } else if (text[i] === '"') {
      let j = i + 1;
      while (j < text.length && text[j] !== '"') j += text[j] === '\\' ? 2 : 1;
      i = j + 1;
    } else i++;
  }
  return out;
}

function slug(text: string): string {
  return (
    text
      .toLowerCase()
      .normalize('NFKD')
      .replace(/[̀-ͯ]/g, '')
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-+|-+$/g, '')
      .split('-')
      .slice(0, 6)
      .join('-') || 'n-000000'
  );
}

function fieldValue(raw: string): string {
  const trimmed = raw.trim();
  if (trimmed.startsWith('"')) {
    try {
      return JSON.parse(trimmed) as string;
    } catch {
      return trimmed;
    }
  }
  return trimmed;
}

function skipWs(text: string, i: number, end: number): number {
  while (i < end && /\s/.test(text[i] ?? '')) i++;
  return i;
}

function wordAt(text: string, i: number): string {
  return /^[A-Za-z_]+/.exec(text.slice(i, i + 40))?.[0] ?? '';
}

export function parseFixture(path: string, text: string): ParsedFile {
  const lines = new Lines(text);
  const comments = scanComments(text);
  const insideComment = (offset: number) => comments.some((c) => c.start < offset && offset < c.end);

  // ---- command starts (column 0; docs/m1-plan.md section 6.1)
  const starts: number[] = [];
  for (const lineStart of lines.starts) {
    if (lineStart >= text.length || insideComment(lineStart)) continue;
    const rest = text.slice(lineStart, lineStart + 40);
    if (rest.startsWith('/-') || rest.startsWith('--') || rest.startsWith('@[') || rest.startsWith('#') || COMMAND_WORDS.has(wordAt(text, lineStart))) {
      starts.push(lineStart);
    }
  }

  // ---- declarations and namespaces
  const decls: DeclInfo[] = [];
  const imports: string[] = [];
  const nsStack: string[][] = [];
  let pending: { start: number; docSpan?: Span; docstring?: string; attributes: string[]; modifiers: string[] } | undefined;
  starts.forEach((segStart, index) => {
    const segEnd = index + 1 < starts.length ? (starts[index + 1] as number) : text.length;
    let p = segStart;
    const comment = comments.find((c) => c.start === p);
    if (comment && comment.kind !== 'doc') {
      pending = undefined;
      return;
    }
    const current = pending ?? { start: segStart, attributes: [], modifiers: [] };
    if (comment && comment.kind === 'doc') {
      current.start = segStart;
      current.docSpan = { start: comment.start, end: comment.end };
      current.docstring = text.slice(comment.start + 3, comment.end - 2).trim();
      p = skipWs(text, comment.end, segEnd);
    }
    while (text.startsWith('@[', p)) {
      let depth = 0;
      let j = p;
      for (; j < segEnd; j++) {
        if (text[j] === '[') depth++;
        else if (text[j] === ']') {
          depth--;
          if (depth === 0) break;
        }
      }
      current.attributes.push(text.slice(p, j + 1));
      p = skipWs(text, j + 1, segEnd);
    }
    for (let word = wordAt(text, p); MODIFIERS.includes(word); word = wordAt(text, p)) {
      current.modifiers.push(word);
      p = skipWs(text, p + word.length, segEnd);
    }
    if (p >= segEnd) {
      pending = current;
      return;
    }
    const word = wordAt(text, p);
    if (!DECL_KEYWORDS.includes(word)) {
      pending = undefined;
      const line = text.slice(p, text.indexOf('\n', p) < 0 ? text.length : text.indexOf('\n', p));
      const ns = /^namespace\s+(\S+)/.exec(line);
      if (ns) nsStack.push((ns[1] ?? '').split('.'));
      else if (/^section\b/.test(line)) nsStack.push([]);
      else if (/^end\b/.test(line)) nsStack.pop();
      else if (/^import\s+(\S+)/.test(line)) imports.push(/^import\s+(\S+)/.exec(line)?.[1] ?? '');
      return;
    }
    let keyword = word as DeclKeyword;
    const keywordStart = p;
    let q = p + word.length;
    if (word === 'class') {
      const next = wordAt(text, skipWs(text, q, segEnd));
      if (next === 'inductive' || next === 'abbrev') {
        keyword = `class ${next}` as DeclKeyword;
        q = skipWs(text, q, segEnd) + next.length;
      }
    }
    const keywordSpan = { start: keywordStart, end: q };
    q = skipWs(text, q, segEnd);
    if (keyword === 'instance' && text.startsWith('(priority', q)) q = skipWs(text, text.indexOf(')', q) + 1, segEnd);
    let name: string | undefined;
    let nameSpan: Span | undefined;
    if (keyword !== 'example' && keyword !== 'mutual') {
      const m = IDENT_AT.exec(text.slice(q, segEnd));
      if (m && !(keyword === 'instance' && /^\s*$/.test(m[0]))) {
        name = m[0];
        nameSpan = { start: q, end: q + m[0].length };
      }
    }
    const namespace = nsStack.flat();
    const fullName = name === undefined ? undefined : name.startsWith('_root_.') ? name.slice(7) : [...namespace, name].join('.');
    const end = segStart + text.slice(segStart, segEnd).trimEnd().length;
    // valueStart: first top-level `:=` / `where` / `|` after the name
    let valueStart: number | undefined;
    let depth = 0;
    for (let k = nameSpan?.end ?? keywordSpan.end; k < end; k++) {
      if (insideComment(k)) continue;
      const c = text[k] ?? '';
      if ('([{⟨'.includes(c)) depth++;
      else if (')]}⟩'.includes(c)) depth--;
      else if (depth === 0 && (text.startsWith(':=', k) || (c === '|' && keyword !== 'theorem') || (text.startsWith('where', k) && /\s/.test(text[k - 1] ?? '')))) {
        valueStart = k;
        break;
      }
    }
    const span = { start: current.start, end };
    decls.push({
      keyword,
      ...(name !== undefined ? { name, fullName } : {}),
      namespace,
      modifiers: current.modifiers,
      ...(current.attributes.length > 0 ? { attributes: current.attributes } : {}),
      ...(current.docstring !== undefined ? { docstring: current.docstring, docSpan: current.docSpan } : {}),
      span,
      range: lines.range(span),
      keywordSpan,
      ...(nameSpan ? { nameSpan } : {}),
      ...(valueStart !== undefined ? { valueStart } : {}),
    } as DeclInfo);
    pending = undefined;
  });

  // ---- blocks
  const blocks: MarkupBlock[] = [];
  const usedIds = new Set<string>();
  for (const comment of comments) {
    if (comment.kind !== 'block') continue;
    const bodyStart = comment.start + 2;
    const bodyEnd = comment.end - 2;
    const body = text.slice(bodyStart, bodyEnd);
    const rawLines = body.split('\n');
    let offset = bodyStart;
    const lineSpans = rawLines.map((l) => {
      const s = { start: offset, end: offset + l.length, text: l };
      offset += l.length + 1;
      return s;
    });
    const markerIndex = lineSpans.findIndex((l) => l.text.trim() !== '');
    const marker = lineSpans[markerIndex];
    const markerMatch = marker ? /^\s*@@\s*telelean(?:\s+v(\d+))?\s*$/.exec(marker.text) : null;
    if (!marker || !markerMatch) continue;
    const fields: BlockFields = {};
    const extensions: Record<string, string[]> = {};
    const fieldLines: FieldLine[] = [];
    let id: string | undefined;
    let bodySpan: Span | undefined;
    let markdown: string | undefined;
    for (let k = markerIndex + 1; k < lineSpans.length; k++) {
      const line = lineSpans[k] as { start: number; end: number; text: string };
      if (line.text.trim() === '---') {
        bodySpan = { start: line.start, end: bodyEnd };
        markdown = lineSpans
          .slice(k + 1)
          .map((l) => l.text)
          .join('\n')
          .trim();
        break;
      }
      const m = /^\s*([a-z_][a-z0-9_]*(?:\.[a-z_][a-z0-9_]*)*)\s*:\s?(.*)$/.exec(line.text);
      if (!m) continue;
      const writtenKey = m[1] ?? '';
      const key = writtenKey === 'kind' ? 'type' : writtenKey;
      const raw = (m[2] ?? '').trim();
      const valueStartIdx = line.start + line.text.length - (m[2] ?? '').length + ((m[2] ?? '').length - (m[2] ?? '').trimStart().length);
      fieldLines.push({ key, writtenKey, span: { start: line.start, end: line.end }, valueSpan: { start: valueStartIdx, end: valueStartIdx + raw.length }, raw });
      const value = fieldValue(raw);
      const list = () => value.split(',').map((x) => x.trim()).filter(Boolean);
      switch (key) {
        case 'id':
          id = value;
          break;
        case 'type':
          fields.type = value.toUpperCase() as NodeType;
          break;
        case 'natural_name':
          fields.naturalName = value;
          break;
        case 'rationale':
          fields.rationale = value;
          break;
        case 'stance':
          fields.stance = value as Stance;
          break;
        case 'source':
          fields.source = value as Evidential;
          break;
        case 'asserted':
          fields.asserted = value;
          break;
        case 'premises':
          fields.premises = list();
          break;
        case 'lean':
          fields.lean = list();
          break;
        case 'supersedes':
          fields.supersedes = value;
          break;
        case 'refines':
          fields.refines = value;
          break;
        case 'tags':
          fields.tags = list();
          break;
        case 'origin':
          fields.origin = value as 'user' | 'agent';
          break;
        case 'session':
          fields.session = value;
          break;
        case 'worded_by':
          fields.wordedBy = value as 'user' | 'agent';
          break;
        default:
          (extensions[key] ??= []).push(raw);
      }
    }
    let idWritten = id !== undefined;
    if (id === undefined) {
      const base = slug(fields.naturalName ?? '');
      id = base;
      for (let n = 2; usedIds.has(id); n++) id = `${base}-${n}`;
      idWritten = false;
    }
    usedIds.add(id);
    const span = { start: comment.start, end: comment.end };
    let binding: BlockBinding = { mode: 'none' };
    if (fields.lean && fields.lean.length > 0) binding = { mode: 'pinned', statement: fields.lean[0], pinned: [...fields.lean] };
    else {
      const index = decls.findIndex((d) => d.span.start >= span.end);
      const decl = decls[index];
      if (decl) {
        const gap = text.slice(span.end, decl.span.start).split('\n');
        const middle = gap.slice(1, -1);
        const otherBlock = comments.some((c) => c.kind === 'block' && c.start >= span.end && c.start < decl.span.start);
        const adjacent = gap.length >= 2 && (gap[0] ?? '').trim() === '' && middle.every((l) => l.trim() !== '') && !otherBlock;
        binding = adjacent ? { mode: 'adjacent', ...(decl.fullName ? { statement: decl.fullName } : {}), adjacentDecl: index } : { mode: 'none', gapDecl: index };
      }
    }
    blocks.push({
      id,
      idWritten,
      version: Number(markerMatch[1] ?? '1'),
      fields,
      extensions,
      ...(markdown !== undefined ? { body: markdown } : {}),
      span,
      range: lines.range(span),
      markerSpan: { start: marker.start, end: marker.end },
      lines: fieldLines,
      ...(bodySpan ? { bodySpan } : {}),
      binding,
    });
  }

  return { path, text, eol: text.includes('\r\n') ? '\r\n' : '\n', blocks, decls, imports, diagnostics: [] };
}

/**
 * A stand-in for WP-semantic's `refreshLeanFacts` on small synthetic fixtures: from parsed files it derives the
 * LeanFacts a real build would report for the simple Lean the tests use (ranges from the declarations, refs from
 * the identifiers that resolve to project declarations, `#check`-style fully-qualified types with binders turned into
 * arrows, `typeSort` for axioms/opaques, and `#print axioms`-style transitive axiom lists in Lean's name order).
 * Anything a test needs beyond that (e.g. the `And.right` ref Lean records for `.2`) goes in `overrides`.
 * The Spyro acceptance tests use the hand-written fixtures/project/*.json instead.
 */
import type { DeclFacts, DeclRef, LeanDeclKind, LeanFacts, LeanMessageFact, ModuleFacts } from '../../../src/facts.js';
import type { DeclInfo, ParsedFile } from '../../../src/markup/types.js';
import { moduleOfPath } from '../../../src/paths.js';
import { keywordKind } from '../../../src/project/factsIndex.js';
import { blankComments, compareLeanNames, identifierTokens, LineMap, normalizeWhitespace, splitTopLevelArrows } from '../../../src/project/text.js';
import { anonymousInstanceName, qualifyText, resolveName, shapeOf } from '../../../src/project/vocabulary.js';

export interface DeclOverride {
  kind?: LeanDeclKind;
  type?: string;
  typeSort?: string;
  axioms?: string[];
  usesSorry?: boolean;
  /** Extra ref names appended (zero-width ranges at the declaration's end), e.g. `And.right`. */
  extraRefs?: string[];
  /** Replace the refs entirely. */
  refs?: DeclRef[];
  value?: string;
  error?: string;
  parent?: string;
  /** Leave the declaration out of the facts. */
  drop?: boolean;
}

export interface FakeFactsOptions {
  library?: string;
  overrides?: Record<string, DeclOverride>;
  /** Module state per file path (default `fresh`; non-fresh modules get no declarations, like a real build). */
  moduleStates?: Record<string, ModuleFacts['state']>;
  messages?: LeanMessageFact[];
  status?: LeanFacts['status'];
}

export const hashOf = (path: string) => `sha-${path}`;

/** The input hashes that make every file fresh against `fakeFacts` (change one to make that file stale). */
export function freshHashes(files: readonly ParsedFile[]): Record<string, string> {
  return Object.fromEntries(files.map((f) => [f.path, hashOf(f.path)]));
}

interface Entry {
  file: ParsedFile;
  decl: DeclInfo;
  name: string;
}

export function fakeFacts(files: readonly ParsedFile[], options: FakeFactsOptions = {}): LeanFacts {
  const library = options.library ?? 'Model';
  const overrides = options.overrides ?? {};
  const entries: Entry[] = [];
  for (const file of files) {
    for (const decl of file.decls) {
      if (decl.keyword === 'example' || decl.keyword === 'mutual') continue;
      const name = decl.fullName ?? (decl.keyword === 'instance' ? anonymousInstanceName(file, decl) : undefined);
      if (name) entries.push({ file, decl, name });
    }
  }
  const names = new Set(entries.map((e) => e.name));
  const known = (n: string) => names.has(n);
  const byName = new Map(entries.map((e) => [e.name, e]));

  const refsOf = new Map<string, DeclRef[]>();
  for (const { file, decl, name } of entries) {
    const lines = new LineMap(file.text);
    const from = decl.nameSpan?.end ?? decl.keywordSpan.end;
    const body = blankComments(file.text.slice(from, decl.span.end));
    const refs: DeclRef[] = [];
    for (const token of identifierTokens(body)) {
      let text = token.text;
      let resolved = resolveName(text, decl.namespace, known);
      while (!resolved && text.includes('.')) {
        text = text.slice(0, text.lastIndexOf('.'));
        resolved = resolveName(text, decl.namespace, known);
      }
      if (!resolved || resolved === name) continue;
      const start = from + token.start;
      const target = byName.get(resolved);
      refs.push({ name: resolved, module: moduleOfPath(target?.file.path ?? '') ?? '', range: lines.rangeOf(start, start + text.length) });
    }
    const o = overrides[name];
    if (o?.extraRefs) {
      const end = lines.positionAt(decl.span.end);
      for (const extra of o.extraRefs) refs.push({ name: extra, module: 'Init.Prelude', range: { start: end, end } });
    }
    refsOf.set(name, o?.refs ?? refs);
  }

  const shapeCache = new Map<string, ReturnType<typeof shapeOf>>();
  const shape = (e: Entry) => {
    let s = shapeCache.get(e.name);
    if (!s) {
      s = shapeOf(e.file, e.decl, undefined, e.name, known);
      shapeCache.set(e.name, s);
    }
    return s;
  };
  const sorts = new Set(entries.filter((e) => e.decl.keyword === 'axiom' && shape(e).type === 'Type').map((e) => e.name));
  const presupOf = new Map<string, string>();
  for (const e of entries) {
    const m = e.decl.keyword === 'axiom' ? /^Nonempty\s+(\S+)$/.exec(shape(e).type ?? '') : null;
    if (m && sorts.has(m[1] ?? '') && !presupOf.has(m[1] ?? '')) presupOf.set(m[1] ?? '', e.name);
  }

  const axiomMemo = new Map<string, string[]>();
  const axiomsOf = (name: string, stack = new Set<string>()): string[] => {
    const memo = axiomMemo.get(name);
    if (memo) return memo;
    const o = overrides[name];
    if (o?.axioms) return o.axioms;
    if (stack.has(name)) return [];
    stack.add(name);
    const e = byName.get(name);
    const out = new Set<string>();
    if (e) {
      if (e.decl.keyword === 'axiom') out.add(name);
      for (const ref of refsOf.get(name) ?? []) for (const a of axiomsOf(ref.name, stack)) out.add(a);
      if (e.decl.keyword === 'opaque') {
        const type = shape(e).type ?? '';
        const presup = presupOf.get(type);
        if (presup) {
          out.add('Classical.choice');
          for (const a of axiomsOf(presup, stack)) out.add(a);
        }
      }
      const text = blankComments(e.file.text.slice(e.decl.span.start, e.decl.span.end));
      if (/(^|[^\w])sorry([^\w]|$)/.test(text)) out.add('sorryAx');
    }
    stack.delete(name);
    const list = [...out].sort(compareLeanNames);
    axiomMemo.set(name, list);
    return list;
  };

  const states = options.moduleStates ?? {};
  const modules: ModuleFacts[] = files.map((file) => ({
    name: moduleOfPath(file.path) ?? file.path,
    file: file.path,
    sourceSha256: hashOf(file.path),
    state: states[file.path] ?? 'fresh',
    imports: file.imports.filter((m) => m === library || m.startsWith(`${library}.`)),
  }));
  const factsOk = (path: string) => (states[path] ?? 'fresh') === 'fresh' || states[path] === 'stale';

  const decls: DeclFacts[] = [];
  for (const e of entries) {
    if (!factsOk(e.file.path)) continue;
    const o = overrides[e.name] ?? {};
    if (o.drop) continue;
    const lines = new LineMap(e.file.text);
    const s = shape(e);
    const kind: LeanDeclKind = o.kind ?? (e.decl.keyword === 'instance' ? 'instance' : keywordKind(e.decl.keyword));
    const type = o.type ?? (s.type !== undefined ? normalizeWhitespace(s.type) : undefined);
    let typeSort = o.typeSort;
    if (typeSort === undefined && (kind === 'axiom' || kind === 'opaque') && type !== undefined) {
      const parts = splitTopLevelArrows(type);
      if (type === 'Type') typeSort = 'Type 1';
      else if (parts[parts.length - 1] === 'Prop' || parts.every((p) => sorts.has(p))) typeSort = 'Type';
      else typeSort = 'Prop';
    }
    let value = o.value;
    if (value === undefined && kind === 'def' && e.decl.valueStart !== undefined) {
      value = qualifyText(blankComments(e.file.text.slice(e.decl.valueStart + 2, e.decl.span.end)), e.decl.namespace, known);
    }
    const axioms = axiomsOf(e.name);
    decls.push({
      name: e.name,
      module: moduleOfPath(e.file.path) ?? '',
      file: e.file.path,
      range: e.decl.range,
      selectionRange: lines.rangeOf(e.decl.nameSpan?.start ?? e.decl.keywordSpan.start, e.decl.nameSpan?.end ?? e.decl.keywordSpan.end),
      kind,
      ...(e.decl.attributes ? { attributes: e.decl.attributes } : {}),
      ...(type !== undefined ? { type } : {}),
      ...(typeSort !== undefined ? { typeSort } : {}),
      ...(value !== undefined ? { value } : {}),
      axioms,
      usesSorry: o.usesSorry ?? axioms.includes('sorryAx'),
      ...(o.error !== undefined ? { error: o.error } : {}),
      ...(e.decl.docstring !== undefined ? { docstring: e.decl.docstring } : {}),
      refs: refsOf.get(e.name) ?? [],
      ...(o.parent !== undefined ? { parent: o.parent } : {}),
    });
  }

  return {
    format: 'telelean-lean-facts',
    version: 1,
    toolchain: 'leanprover/lean4:v4.35.0',
    library,
    startedAt: '2026-11-01T02:00:00.000Z',
    finishedAt: '2026-11-01T02:00:01.200Z',
    status: options.status ?? 'ok',
    build: { status: 'ok', durationMs: 1000, messages: options.messages ?? [], failedModules: Object.entries(states).filter(([, s]) => s === 'failed').map(([p]) => moduleOfPath(p) ?? p) },
    check: { status: 'ok', durationMs: 200, probed: decls.length },
    modules,
    decls,
  };
}

/**
 * AT2.1 (and the Spyro parts of AT2.4): buildProjectModel + subjectGraph on test-fixtures/spyro (and the
 * runner-lean `proved` overlay) with the hand-written facts reproduce the frozen samples spyroGraph() and
 * spyroProvedGraph(). Runs once with the fixture parser (test/project/helpers) and once with WP-markup's
 * parseLeanFile (skipped until WP-markup is implemented).
 */
import { describe, expect, it } from 'vitest';
import rootLean from '../../../../test-fixtures/spyro/Model.lean?raw';
import mainLean from '../../../../test-fixtures/spyro/Model/Spyro/Main.lean?raw';
import vocabLean from '../../../../test-fixtures/spyro/Model/Spyro/Vocabulary.lean?raw';
import provedMainLean from '../../../../test-fixtures/runner-lean/overlays/proved/Model/Spyro/Main.lean?raw';
import factsJson from '../fixtures/project/spyro-facts.json?raw';
import provedFactsJson from '../fixtures/project/spyro-proved-facts.json?raw';
import { isImplemented } from '../../src/notImplemented.js';
import { parseLeanFile } from '../../src/markup/api.js';
import type { ParsedFile } from '../../src/markup/types.js';
import type { LeanFacts } from '../../src/facts.js';
import { buildProjectModel, subjectGraph } from '../../src/project/index.js';
import { proofDependents } from '../../src/kindChange.js';
import { SPYRO_SEMANTIC, spyroGraph, spyroProvedGraph, spyroVocabulary } from '../../src/samples/spyro.js';
import type { TlGraph } from '../../src/model.js';
import { parseFixture } from './helpers/parseFixture.js';

type Parser = (path: string, text: string) => ParsedFile;

const HASHES = { 'Model.lean': 'sha-model-root', 'Model/Spyro/Main.lean': 'sha-main', 'Model/Spyro/Vocabulary.lean': 'sha-vocabulary' };
const PROVED_HASHES = { ...HASHES, 'Model/Spyro/Main.lean': 'sha-main-proved' };

export function spyroFiles(parse: Parser, main = mainLean): ParsedFile[] {
  return [parse('Model.lean', rootLean), parse('Model/Spyro/Main.lean', main), parse('Model/Spyro/Vocabulary.lean', vocabLean)];
}

export function spyroModel(parse: Parser) {
  const facts = JSON.parse(factsJson) as LeanFacts;
  return buildProjectModel({ files: spyroFiles(parse), fileHashes: HASHES, facts, library: 'Model' });
}

export function spyroProvedModel(parse: Parser) {
  const facts = JSON.parse(provedFactsJson) as LeanFacts;
  return buildProjectModel({ files: spyroFiles(parse, provedMainLean), fileHashes: PROVED_HASHES, facts, library: 'Model' });
}

const sortedUsedBy = (graph: TlGraph) => graph.vocabulary.map((v) => ({ ...v, usedBy: [...v.usedBy].sort() }));
const edgeKeys = (graph: TlGraph, type: string) =>
  graph.edges
    .filter((e) => e.type === type)
    .map((e) => e.id)
    .sort();

const PARSERS: Array<[string, Parser, boolean]> = [
  ['fixture parser', parseFixture, true],
  ['WP-markup parseLeanFile', parseLeanFile, isImplemented(() => parseLeanFile('X.lean', ''))],
];

for (const [label, parse, enabled] of PARSERS) {
  describe.skipIf(!enabled)(`AT2.1 Spyro walkthrough (${label})`, () => {
    it('reproduces spyroGraph(): nodes with their card data and statuses, the vocabulary, the 3 declared edges', () => {
      const graph = subjectGraph(spyroModel(parse), 'Spyro', { version: 1, semantic: { ...SPYRO_SEMANTIC } });
      const sample = spyroGraph();
      expect(graph.nodes).toEqual(sample.nodes);
      expect(graph.vocabulary).toEqual(spyroVocabulary());
      expect(graph.vocabulary).toHaveLength(9);
      expect(graph.edges).toEqual(sample.edges);
      expect(graph.edges.every((e) => e.type === 'premise' && !e.mismatch)).toBe(true);
      expect(graph.semantic).toEqual(SPYRO_SEMANTIC);
      expect(graph.subject).toBe('Spyro');
    });

    it('hides the two Nonempty instances and lists only the expected diagnostics', () => {
      const model = spyroModel(parse);
      expect(model.vocabulary.map((v) => v.name)).not.toContain('Spyro.instNonemptyCharacter');
      expect(model.vocabulary.map((v) => v.name)).not.toContain('Spyro.instNonemptyGame');
      expect(model.diagnostics.map((d) => [d.code, d.nodeId])).toEqual([['TL011', 'pg-no-dark-past']]);
      expect(model.subjects).toEqual([{ name: 'Spyro', nodeCount: 4, files: ['Model/Spyro/Main.lean', 'Model/Spyro/Vocabulary.lean'] }]);
      expect([...model.freshFiles].sort()).toEqual(['Model.lean', 'Model/Spyro/Main.lean', 'Model/Spyro/Vocabulary.lean']);
      expect(model.ownerOfDecl.get('Spyro.cynder_dark_past.holds')).toBe('cynder-dark-past');
      expect(model.ownerOfDecl.get('Spyro.cynder_not_good')).toBe('cynder-not-good');
    });

    it('with the proved-overlay facts reproduces spyroProvedGraph(): statuses, footprint, verified edges, refs', () => {
      const graph = subjectGraph(spyroProvedModel(parse), 'Spyro', { version: 2, semantic: { ...SPYRO_SEMANTIC } });
      const sample = spyroProvedGraph();
      expect(graph.nodes).toEqual(sample.nodes);
      const goal = graph.nodes.find((n) => n.id === 'cynder-not-good');
      expect(goal?.status.proof).toEqual({
        kind: 'proved',
