/** Builders for small synthetic projects (subject `S` unless stated), parsed with the fixture parser. */
import type { LeanFacts } from '../../../src/facts.js';
import type { Layout } from '../../../src/layout.js';
import type { ParsedFile } from '../../../src/markup/types.js';
import type { TlGraph, TlNode } from '../../../src/model.js';
import { buildProjectModel, subjectGraph, type ProjectModel } from '../../../src/project/index.js';
import { fakeFacts, freshHashes, type FakeFactsOptions } from './fakeFacts.js';
import { parseFixture } from './parseFixture.js';

/** The vocabulary most synthetic tests share: a sort with its presupposition and instance, two predicates, a constant. */
export const VOCAB_S = `namespace S

/-- things -/
axiom T : Type
/-- there is at least one thing -/
axiom T.exists : Nonempty T
instance : Nonempty T := T.exists
/-- is good -/
axiom Good : T → Prop
/-- is bad -/
axiom Bad : T → Prop
/-- a thing -/
noncomputable opaque t : T

end S
`;

export interface BlockSpec {
  id?: string;
  type: 'ASSUMPTION' | 'DERIVATION' | 'GOAL';
  name: string;
  rationale?: string;
  premises?: string[];
  lean?: string;
}

/** A markup block as telelean writes it (fields in canonical order). */
export function block(spec: BlockSpec): string {
  return [
    '/-',
    '@@ telelean v1',
    ...(spec.id ? [`id: ${spec.id}`] : []),
    `type: ${spec.type}`,
    `natural_name: ${spec.name}`,
    ...(spec.rationale ? [`rationale: ${spec.rationale}`] : []),
    ...(spec.premises ? [`premises: ${spec.premises.join(', ')}`] : []),
    ...(spec.lean ? [`lean: ${spec.lean}`] : []),
    '-/',
  ].join('\n');
}

/** A Main module of subject `S` importing the shared vocabulary. */
export function mainS(body: string, subject = 'S'): string {
  return `import Model.${subject}.Vocabulary\n\nnamespace ${subject}\n\n${body.trim()}\n\nend ${subject}\n`;
}

export interface Built {
  model: ProjectModel;
  files: ParsedFile[];
  facts: LeanFacts | undefined;
  hashes: Record<string, string>;
}

export interface BuildOptions {
  /** `false`: no facts at all (syntactic mode). */
  facts?: FakeFactsOptions | false;
  /** Texts the facts were computed from (default: the current texts). Files whose text differs become stale. */
  factsFrom?: Record<string, string>;
  mutateFacts?: (facts: LeanFacts) => void;
  library?: string;
}

export function build(texts: Record<string, string>, options: BuildOptions = {}): Built {
  const parse = (all: Record<string, string>) => Object.entries(all).map(([path, text]) => parseFixture(path, text));
  const files = parse(texts);
  let facts: LeanFacts | undefined;
  const hashes = freshHashes(files);
  if (options.facts !== false) {
    const source = options.factsFrom ? parse({ ...texts, ...options.factsFrom }) : files;
    facts = fakeFacts(source, { ...(options.facts ?? {}), ...(options.library ? { library: options.library } : {}) });
    options.mutateFacts?.(facts);
    for (const [path, text] of Object.entries(options.factsFrom ?? {})) if (texts[path] !== text) hashes[path] = `sha-edited-${path}`;
  }
  const model = buildProjectModel({ files, fileHashes: hashes, ...(facts ? { facts } : {}), library: options.library ?? 'Model' });
  return { model, files, facts, hashes };
}

export function graphOf(model: ProjectModel, subject = 'S', layout?: Layout): TlGraph {
  return subjectGraph(model, subject, { version: 1, semantic: { state: 'fresh' }, ...(layout ? { layout } : {}) });
}

export function nodeOf(model: ProjectModel, id: string): TlNode {
  const entry = model.nodes.get(id);
  if (!entry) throw new Error(`no node ${id}; nodes: ${[...model.nodes.keys()].join(', ')}`);
  return entry.node;
}

export const codes = (model: ProjectModel, nodeId?: string) => model.diagnostics.filter((d) => nodeId === undefined || d.nodeId === nodeId).map((d) => d.code);

/**
 * AT2.2: node statuses per the table of docs/m1-plan.md section 6.3 (one test per cell), proved vs conditional,
 * holds-mismatch, `other` justifications, footprint mapping, flags and the TL1xx diagnostics that go with them.
 */
import { describe, expect, it } from 'vitest';
import type { NodeType } from '../../src/model.js';
import { block, build, codes, mainS, nodeOf, VOCAB_S } from './helpers/build.js';

const VOCAB = { 'Model/S/Vocabulary.lean': VOCAB_S };

/** `a` (an assumption, `Good t`) plus node `n` of the given type whose statement is `Good t ∧ Good t`, with `holds`. */
function cell(type: NodeType, holds: string) {
  const body = [
    block({ id: 'a', type: 'ASSUMPTION', name: 'A holds', rationale: 'seen it', lean: 'S.a' }),
    'abbrev a : Prop := Good t',
    'axiom a.holds : a',
    '',
    block({ id: 'n', type, name: 'N holds', rationale: 'why not', lean: 'S.n' }),
    'abbrev n : Prop := Good t ∧ Good t',
    holds,
  ].join('\n');
  return build({ ...VOCAB, 'Model/S/Main.lean': mainS(body) }).model;
}

const ABSENT = '';
const AXIOM = 'axiom n.holds : n';
const THEOREM = 'theorem n.holds : n := ⟨a.holds, a.holds⟩';
const SORRY = 'theorem n.holds : n := sorry';

describe('AT2.2 the status table (H = n.holds)', () => {
  it('ASSUMPTION, H absent: none + missing-holds (TL117)', () => {
    const model = cell('ASSUMPTION', ABSENT);
    expect(nodeOf(model, 'n').status).toMatchObject({ formal: 'formalized', proof: { kind: 'none' }, flags: ['missing-holds'] });
    expect(codes(model, 'n')).toEqual(['TL117']);
  });
  it('ASSUMPTION, H axiom: assumed', () => {
    const model = cell('ASSUMPTION', AXIOM);
    expect(nodeOf(model, 'n').status).toMatchObject({ proof: { kind: 'assumed' }, flags: [] });
    expect(nodeOf(model, 'n').lean).toMatchObject({ justification: 'S.n.holds', justificationKind: 'axiom' });
    expect(codes(model, 'n')).toEqual([]);
  });
  it('ASSUMPTION, H theorem: proved + provable-assumption (TL106)', () => {
    const model = cell('ASSUMPTION', THEOREM);
    expect(nodeOf(model, 'n').status).toMatchObject({ proof: { kind: 'proved', footprint: ['a', 'presup:S.T.exists'] }, flags: ['provable-assumption'] });
    expect(codes(model, 'n')).toEqual(['TL106']);
  });
  it('ASSUMPTION, H theorem with sorryAx: none + uses-sorry (TL115)', () => {
    const model = cell('ASSUMPTION', SORRY);
    expect(nodeOf(model, 'n').status).toMatchObject({ proof: { kind: 'none' }, flags: ['uses-sorry'] });
    expect(codes(model, 'n')).toEqual(['TL115']);
  });

  it('DERIVATION, H absent: none', () => {
    const model = cell('DERIVATION', ABSENT);
    expect(nodeOf(model, 'n').status).toMatchObject({ formal: 'formalized', proof: { kind: 'none' }, flags: [] });
    expect(codes(model, 'n')).toEqual([]);
  });
  it('DERIVATION, H axiom: pending-promotion + claimed', () => {
    const model = cell('DERIVATION', AXIOM);
    expect(nodeOf(model, 'n').status).toMatchObject({ proof: { kind: 'pending-promotion' }, flags: ['claimed'] });
  });
  it('DERIVATION, H theorem: proved', () => {
    const model = cell('DERIVATION', THEOREM);
    expect(nodeOf(model, 'n').status).toMatchObject({ proof: { kind: 'proved', footprint: ['a', 'presup:S.T.exists'] }, flags: [] });
    expect(codes(model, 'n')).toEqual([]);
  });
  it('DERIVATION, H theorem with sorryAx: none + uses-sorry (TL115)', () => {
    const model = cell('DERIVATION', SORRY);
    expect(nodeOf(model, 'n').status).toMatchObject({ proof: { kind: 'none' }, flags: ['uses-sorry'] });
    expect(codes(model, 'n')).toEqual(['TL115']);
  });

  it('GOAL, H absent: none', () => {
    const model = cell('GOAL', ABSENT);
    expect(nodeOf(model, 'n').status).toMatchObject({ proof: { kind: 'none' }, flags: [] });
    expect(nodeOf(model, 'n').lean.justification).toBeUndefined();
  });
  it('GOAL, H axiom: assumed + TL116 ("make it an Assumption?")', () => {
    const model = cell('GOAL', AXIOM);
    expect(nodeOf(model, 'n').status).toMatchObject({ proof: { kind: 'assumed' }, flags: [] });
    expect(codes(model, 'n')).toEqual(['TL116']);
  });
  it('GOAL, H theorem: proved + proved-goal (TL105)', () => {
    const model = cell('GOAL', THEOREM);
    expect(nodeOf(model, 'n').status).toMatchObject({ proof: { kind: 'proved' }, flags: ['proved-goal'] });
    expect(codes(model, 'n')).toEqual(['TL105']);
  });
  it('GOAL, H theorem with sorryAx: none + uses-sorry (TL115)', () => {
    const model = cell('GOAL', SORRY);
    expect(nodeOf(model, 'n').status).toMatchObject({ proof: { kind: 'none' }, flags: ['uses-sorry'] });
    expect(codes(model, 'n')).toEqual(['TL115']);
  });
});

describe('AT2.2 proved vs conditional, mismatches, other kinds, footprints, flags', () => {
  it('a theorem taking a node statement as hypothesis is conditional, also when Lean wraps the #check type', () => {
    const body = [
      block({ id: 'a', type: 'ASSUMPTION', name: 'A holds', rationale: 'r', lean: 'S.a' }),
      'abbrev a : Prop := Good t',
      '',
      block({ id: 'd', type: 'DERIVATION', name: 'D holds', lean: 'S.d' }),
      'abbrev d : Prop := Good t',
      'theorem d.holds (h : a) : d := h',
    ].join('\n');
    const plain = build({ ...VOCAB, 'Model/S/Main.lean': mainS(body) }).model;
    expect(nodeOf(plain, 'd').status.proof).toEqual({ kind: 'conditional', on: ['a'], footprint: [] });
    expect(codes(plain, 'd')).toEqual(['TL102']);
    const wrapped = build({ ...VOCAB, 'Model/S/Main.lean': mainS(body) }, { facts: { overrides: { 'S.d.holds': { type: 'S.a →\n  S.d' } } } }).model;
    expect(nodeOf(wrapped, 'd').status.proof).toEqual({ kind: 'conditional', on: ['a'], footprint: [] });
    // The hypothesis gives a conditional verified edge.
    expect(wrapped.ownerOfDecl.get('S.a')).toBe('a');
  });

  it('n.holds stating something else is holds-mismatch (TL114), proof none', () => {
    const model = cell('DERIVATION', 'theorem n.holds : Good t ∧ Good t := ⟨a.holds, a.holds⟩');
    expect(nodeOf(model, 'n').status).toMatchObject({ proof: { kind: 'none' }, flags: ['holds-mismatch'] });
    expect(codes(model, 'n')).toEqual(['TL114']);
  });

  it('a `def` justification counts as `other` and is treated like a theorem', () => {
    const model = cell('DERIVATION', 'def n.holds : n := ⟨a.holds, a.holds⟩');
    expect(nodeOf(model, 'n').lean.justificationKind).toBe('other');
    expect(nodeOf(model, 'n').status.proof).toEqual({ kind: 'proved', footprint: ['a', 'presup:S.T.exists'] });
  });

  it('footprint mapping: node ids, presup: entries, standard axioms and vocabulary dropped, other axioms as axiom: + TL103', () => {
    const body = [
      block({ id: 'a', type: 'ASSUMPTION', name: 'A holds', rationale: 'r', lean: 'S.a' }),
      'abbrev a : Prop := Good t',
      'axiom a.holds : a',
      '',
      'axiom sneaky : Bad t',
      '',
      block({ id: 'n', type: 'DERIVATION', name: 'N holds', lean: 'S.n' }),
      'abbrev n : Prop := Good t ∧ Bad t',
      'theorem n.holds : n := ⟨a.holds, sneaky⟩',
    ].join('\n');
    const model = build({ ...VOCAB, 'Model/S/Main.lean': mainS(body) }).model;
    const n = nodeOf(model, 'n');
    expect(n.lean.axioms).toEqual(['Classical.choice', 'S.Bad', 'S.Good', 'S.T', 'S.sneaky', 'S.T.exists', 'S.a.holds']);
    expect(n.status.proof).toEqual({ kind: 'proved', footprint: ['a', 'presup:S.T.exists', 'axiom:S.sneaky'] });
    expect(model.diagnostics.filter((d) => d.code === 'TL103')).toMatchObject([{ nodeId: 'n', vocab: 'S.sneaky', severity: 'warning' }]);
    expect(model.diagnostics.filter((d) => d.code === 'TL104').map((d) => d.vocab)).toEqual(['S.sneaky']);
  });

  it('rests-on-claimed: a proof using the axiom of a derivation whose promotion is pending', () => {
    const body = [
      block({ id: 'd', type: 'DERIVATION', name: 'D holds', lean: 'S.d' }),
      'abbrev d : Prop := Good t',
      'axiom d.holds : d',
      '',
      block({ id: 'g', type: 'GOAL', name: 'G holds', lean: 'S.g' }),
      'abbrev g : Prop := Good t ∧ Good t',
      'theorem g.holds : g := ⟨d.holds, d.holds⟩',
    ].join('\n');
    const model = build({ ...VOCAB, 'Model/S/Main.lean': mainS(body) }).model;
    expect(nodeOf(model, 'd').status.proof.kind).toBe('pending-promotion');
    expect(nodeOf(model, 'g').status.flags).toEqual(['proved-goal', 'rests-on-claimed']);
  });

  it('self-evident: proved with no node in the footprint', () => {
    const body = [block({ id: 'e', type: 'DERIVATION', name: 'Truth', lean: 'S.e' }), 'abbrev e : Prop := True', 'theorem e.holds : e := trivial'].join('\n');
    const model = build({ ...VOCAB, 'Model/S/Main.lean': mainS(body) }).model;
    expect(nodeOf(model, 'e').status).toMatchObject({ proof: { kind: 'proved', footprint: [] }, flags: ['self-evident'] });
  });

  it('existence-commitment + TL108: the proof needs a presupposition no statement mentions', () => {
    const body = [block({ id: 'e', type: 'DERIVATION', name: 'Something exists', lean: 'S.e' }), 'abbrev e : Prop := ∃ x : T, True', 'theorem e.holds : e := ⟨t, trivial⟩'].join('\n');
    const model = build({ ...VOCAB, 'Model/S/Main.lean': mainS(body) }).model;
    const e = nodeOf(model, 'e');
    expect(e.lean.presupposes).toEqual([]);
    expect(e.status).toMatchObject({ proof: { kind: 'proved', footprint: ['presup:S.T.exists'] }, flags: ['self-evident', 'existence-commitment'] });
    expect(model.diagnostics.find((d) => d.code === 'TL108')).toMatchObject({ nodeId: 'e', severity: 'info' });
  });

  it('TL102 when a proof rests on a goal asserted as an axiom', () => {
    const body = [
      block({ id: 'g0', type: 'GOAL', name: 'G0 holds', lean: 'S.g0' }),
      'abbrev g0 : Prop := Good t',
      'axiom g0.holds : g0',
      '',
      block({ id: 'd', type: 'DERIVATION', name: 'D holds', premises: ['g0'], lean: 'S.d' }),
      'abbrev d : Prop := Good t ∧ Good t',
      'theorem d.holds : d := ⟨g0.holds, g0.holds⟩',
    ].join('\n');
    const model = build({ ...VOCAB, 'Model/S/Main.lean': mainS(body) }).model;
    expect(codes(model, 'g0')).toEqual(['TL116']);
    expect(codes(model, 'd')).toEqual(['TL102']);
    expect(model.diagnostics.find((d) => d.code === 'TL102')?.message).toMatch(/goal asserted as an axiom: g0/);
  });

  it('a block bound to a theorem or to a bare axiom is ill-formed with TL113', () => {
    const body = [
      block({ id: 'th', type: 'DERIVATION', name: 'A lemma' }),
      'theorem th : Good t → Good t := fun h => h',
      '',
      block({ id: 'ax', type: 'ASSUMPTION', name: 'A bare axiom', rationale: 'r' }),
      'axiom ax : Good t',
    ].join('\n');
    for (const facts of [undefined, false] as const) {
      const model = build({ ...VOCAB, 'Model/S/Main.lean': mainS(body) }, facts === false ? { facts: false } : {}).model;
      for (const id of ['th', 'ax']) {
        expect(nodeOf(model, id).status.formal, `${id} (${facts === false ? 'syntactic' : 'facts'})`).toBe('ill-formed');
        expect(nodeOf(model, id).lean.binding).toBe('adjacent');
        expect(codes(model, id)).toContain('TL113');
      }
    }
  });

  it('a Lean error inside one node\'s .holds makes only that node ill-formed', () => {
    const body = [
      block({ id: 'a', type: 'ASSUMPTION', name: 'A holds', rationale: 'r', lean: 'S.a' }),
      'abbrev a : Prop := Good t',
      'axiom a.holds : a',
      '',
      block({ id: 'n', type: 'DERIVATION', name: 'N holds', lean: 'S.n' }),
      'abbrev n : Prop := Good t',
      'theorem n.holds : n := a.hold',
    ].join('\n');
    const main = mainS(body);
    const line = main.split('\n').findIndex((l) => l.startsWith('theorem n.holds'));
    const model = build(
      { ...VOCAB, 'Model/S/Main.lean': main },
      {
        facts: {
          moduleStates: { 'Model/S/Main.lean': 'failed' },
          messages: [
            {
              severity: 'error',
              file: 'Model/S/Main.lean',
              module: 'Model.S.Main',
              range: { start: { line, character: 23 }, end: { line, character: 23 } },
              text: "unknown identifier 'a.hold'",
            },
          ],
        },
      },
    ).model;
    expect(nodeOf(model, 'n').status).toMatchObject({ formal: 'ill-formed', proof: { kind: 'none' } });
    expect(nodeOf(model, 'n').status.flags).toContain('not-checked');
    expect(nodeOf(model, 'a').status.formal).toBe('formalized');
    expect(nodeOf(model, 'a').status.proof.kind).toBe('assumed');
    expect(model.diagnostics.find((d) => d.code === 'LEAN')).toMatchObject({ nodeId: 'n', severity: 'error', message: "unknown identifier 'a.hold'" });
  });

  it('no-rationale is an ASSUMPTION flag (TL011), never a derivation or goal one', () => {
    const body = [block({ id: 'x', type: 'ASSUMPTION', name: 'X' }), '', block({ id: 'y', type: 'GOAL', name: 'Y' })].join('\n');
    const model = build({ ...VOCAB, 'Model/S/Main.lean': mainS(body) }).model;
    expect(nodeOf(model, 'x').status.flags).toEqual(['no-rationale']);
    expect(nodeOf(model, 'y').status.flags).toEqual([]);
    expect(codes(model, 'x')).toEqual(['TL011']);
    expect(nodeOf(model, 'x').status.formal).toBe('informal');
  });
});

/**
 * AT2.3: which facts the board uses (docs/m1-plan.md section 6.3): stale files keep their previous facts by name while
 * the keyword is unchanged; unchecked theorems never show as proved; failed / dependency-failed / not-built modules.
 */
import { describe, expect, it } from 'vitest';
import { buildProjectModel } from '../../src/project/index.js';
import { block, build, mainS, nodeOf, VOCAB_S } from './helpers/build.js';
import { parseFixture } from './helpers/parseFixture.js';
import { SPYRO_PROVED_HASHES, SPYRO_TEXTS, spyroFiles, spyroProvedFacts } from './helpers/spyro.js';

/** The proved overlay, with Main.lean edited after the facts were computed. */
function staleProved(edit: (text: string) => string) {
  const main = edit(SPYRO_TEXTS.provedMain);
  return buildProjectModel({
    files: spyroFiles(parseFixture, main),
    fileHashes: { ...SPYRO_PROVED_HASHES, 'Model/Spyro/Main.lean': 'sha-typed-since' },
    facts: spyroProvedFacts(),
    library: 'Model',
  });
}

describe('AT2.3 stale files keep previous facts by name', () => {
  it('while the keyword is unchanged: same status, flag stale, refs dropped, uses/presupposes/axioms kept', () => {
    const model = staleProved((t) => t.replace('namespace Spyro\n', 'namespace Spyro\n\n-- a note typed since the last check\n'));
    expect(model.freshFiles.has('Model/Spyro/Main.lean')).toBe(false);
    const goal = nodeOf(model, 'cynder-not-good');
    expect(goal.status.proof.kind).toBe('proved');
    expect(goal.status.flags).toEqual(['proved-goal', 'stale']);
    expect(goal.lean.refs).toBeUndefined();
    expect(goal.lean.uses).toEqual(['Spyro.GoodAddition', 'Spyro.cynder', 'Spyro.newSpyro']);
    expect(goal.lean.presupposes).toEqual(['Spyro.Character.exists', 'Spyro.Game.exists']);
    expect(goal.lean.axioms).toHaveLength(11);
    // The code is the current text (one line lower), the facts' positions are not used.
    expect(goal.lean.codeLoc?.range.start.line).toBe(56);
    expect(nodeOf(model, 'cynder-dark-past').status).toMatchObject({ proof: { kind: 'assumed' }, flags: ['stale'] });
    // Edges by name: the verified arrows stay.
    expect([...model.nodes.values()].length).toBe(4);
  });

  it('a theorem whose keyword changed (axiom -> theorem) shows proof none + not-checked + stale, never proved', () => {
    const model = staleProved((t) => t.replace('axiom cynder_dark_past.holds : cynder_dark_past', 'theorem cynder_dark_past.holds : cynder_dark_past := sorry'));
    const node = nodeOf(model, 'cynder-dark-past');
    expect(node.status.proof).toEqual({ kind: 'none' });
    expect(node.status.flags).toEqual(['provable-assumption', 'stale', 'not-checked'].filter((f) => f !== 'provable-assumption'));
    expect(node.lean.justificationKind).toBe('theorem');
  });

  it('a theorem the facts do not know (typed since the check) shows proof none + not-checked + stale', () => {
    const model = staleProved((t) =>
      t.replace(
        'abbrev new_spyro_pg : Prop := IsPG newSpyro\naxiom new_spyro_pg.holds : new_spyro_pg',
        'abbrev new_spyro_pg : Prop := IsPG newSpyro\ntheorem new_spyro_pg.holds : new_spyro_pg := by\n  exact sorry',
      ),
    );
    const node = nodeOf(model, 'new-spyro-pg');
    expect(node.status.proof).toEqual({ kind: 'none' });
    expect(node.status.flags).toContain('not-checked');
    expect(node.status.flags).toContain('stale');
  });

  it('a theorem renamed away from its facts: the new name has none, so it is not proved', () => {
    const model = staleProved((t) => t.replace('theorem cynder_not_good.holds : cynder_not_good :=', 'theorem cynder_not_good.holds : cynder_not_good ∧ True :='));
    // Keyword unchanged: the previous facts still apply by name (the board keeps "proved" while the user types).
    expect(nodeOf(model, 'cynder-not-good').status.proof.kind).toBe('proved');
  });
});

describe('AT2.3 unchecked modules', () => {
  const body = [
    block({ id: 'a', type: 'ASSUMPTION', name: 'A holds', rationale: 'r', lean: 'S.a' }),
    'abbrev a : Prop := Good t',
    'axiom a.holds : a',
    '',
    block({ id: 'n', type: 'DERIVATION', name: 'N holds', premises: ['a'], lean: 'S.n' }),
    'abbrev n : Prop := Good t',
    'theorem n.holds : n := a.holds',
  ].join('\n');
  const texts = { 'Model.lean': 'import Model.S.Main\n', 'Model/S/Vocabulary.lean': VOCAB_S, 'Model/S/Main.lean': mainS(body) };

  for (const state of ['failed', 'dependency-failed', 'not-built'] as const) {
    it(`${state}: nodes get not-checked; an axiom still counts as assumed, a theorem as not proved`, () => {
      const model = build(texts, { facts: { moduleStates: { 'Model/S/Main.lean': state } } }).model;
      expect(nodeOf(model, 'a').status).toMatchObject({ formal: 'formalized', proof: { kind: 'assumed' }, flags: ['not-checked'] });
      expect(nodeOf(model, 'n').status).toMatchObject({ formal: 'formalized', proof: { kind: 'none' }, flags: ['not-checked'] });
      expect(nodeOf(model, 'n').lean.uses).toBeUndefined();
      expect(nodeOf(model, 'n').lean.refs).toBeUndefined();
      expect(nodeOf(model, 'n').lean.code).toBe('abbrev n : Prop := Good t\ntheorem n.holds : n := a.holds');
    });
  }

  it('no facts at all: syntactic mode, nothing proved, vocabulary from the text', () => {
    const model = build(texts, { facts: false }).model;
    expect(model.freshFiles.size).toBe(0);
    expect(nodeOf(model, 'a').status).toMatchObject({ formal: 'formalized', proof: { kind: 'assumed' }, flags: ['not-checked'] });
    expect(nodeOf(model, 'n').status).toMatchObject({ formal: 'formalized', proof: { kind: 'none' }, flags: ['not-checked'] });
    expect(model.vocabulary.map((v) => [v.name, v.kind])).toEqual([
      ['S.T', 'sort'],
      ['S.Good', 'predicate'],
      ['S.Bad', 'predicate'],
      ['S.t', 'constant'],
      ['S.T.exists', 'presupposition'],
    ]);
  });
});

/**
 * AT2.4: a card's `uses` and `refs` come from Lean's references (DeclFacts.refs), never from hard-coded names:
 * changing the refs changes `uses`; the closure runs through other nodes' statements and vocabulary definitions;
 * refs are code-relative, include the card's own statement inside its `.holds`, and drop non-vocabulary names.
 */
import { describe, expect, it } from 'vitest';
import { buildProjectModel } from '../../src/project/index.js';
import { block, build, mainS, nodeOf, VOCAB_S } from './helpers/build.js';
import { parseFixture } from './helpers/parseFixture.js';
import { spyroFacts, spyroInput } from './helpers/spyro.js';

describe('AT2.4 uses and refs come from the facts', () => {
  it('changing the refs in the facts changes uses (and refs)', () => {
    const input = spyroInput(parseFixture);
    const facts = spyroFacts();
    const statement = facts.decls.find((d) => d.name === 'Spyro.cynder_dark_past');
    if (!statement) throw new Error('fixture');
    // Pretend Lean resolved `cynder` to the game constant instead (same range).
    statement.refs = statement.refs.map((r) => (r.name === 'Spyro.cynder' ? { ...r, name: 'Spyro.newSpyro' } : r));
    const before = nodeOf(buildProjectModel(input), 'cynder-dark-past');
    const after = nodeOf(buildProjectModel({ ...input, facts }), 'cynder-dark-past');
    expect(before.lean.uses).toEqual(['Spyro.HasDarkPast', 'Spyro.cynder']);
    expect(after.lean.uses).toEqual(['Spyro.HasDarkPast', 'Spyro.newSpyro']);
    expect(after.lean.refs?.map((r) => r.name)).toEqual(['Spyro.HasDarkPast', 'Spyro.newSpyro', 'Spyro.cynder_dark_past']);
    // Without facts for the statement, `uses` is absent (the webview hides the line).
    const none = nodeOf(buildProjectModel({ ...input, facts: undefined }), 'cynder-dark-past');
    expect(none.lean.uses).toBeUndefined();
    expect(none.lean.refs).toBeUndefined();
  });

  const vocab = VOCAB_S.replace('end S\n', '/-- good pairs -/\ndef GoodPair (x y : T) : Prop := Good x ∧ Good y\n\nend S\n');
  const body = [
    block({ id: 'b', type: 'ASSUMPTION', name: 'It is bad', rationale: 'r', lean: 'S.b' }),
    'abbrev b : Prop := Bad t',
    'axiom b.holds : b',
    '',
    block({ id: 'c', type: 'GOAL', name: 'A good pair, and bad', premises: ['b'], lean: 'S.c' }),
    '/-- A good pair, and bad -/',
    'abbrev c : Prop := GoodPair t t ∧ b',
    'theorem c.holds : c := ⟨sorry, b.holds⟩',
  ].join('\n');

  it('the closure runs breadth-first through other nodes\' statements and vocabulary definitions', () => {
    const model = build({ 'Model/S/Vocabulary.lean': vocab, 'Model/S/Main.lean': mainS(body) }).model;
    const c = nodeOf(model, 'c');
    // c's own refs (GoodPair, t), then GoodPair's body (T from its binders, Good), then b's statement (Bad).
    expect(c.lean.uses).toEqual(['S.GoodPair', 'S.t', 'S.T', 'S.Good', 'S.Bad']);
    expect(c.status.flags).toContain('definitional-choice');
    const goodPair = model.vocabulary.find((v) => v.name === 'S.GoodPair');
    expect(goodPair).toMatchObject({ kind: 'definition', flags: ['definitional-choice'], usedBy: ['c'] });
    expect(model.vocabulary.find((v) => v.name === 'S.Bad')?.usedBy).toEqual(['b', 'c']);
  });

  it('refs are relative to the card code, include the own statement inside .holds, and drop non-vocabulary names', () => {
    const model = build(
      { 'Model/S/Vocabulary.lean': vocab, 'Model/S/Main.lean': mainS(body) },
      { facts: { overrides: { 'S.c.holds': { extraRefs: ['And.right', 'Nat'] } } } },
    ).model;
    const c = nodeOf(model, 'c');
    expect(c.lean.code).toBe('/-- A good pair, and bad -/\nabbrev c : Prop := GoodPair t t ∧ b\ntheorem c.holds : c := ⟨sorry, b.holds⟩');
    expect(c.lean.refs).toEqual([
      { name: 'S.GoodPair', range: { start: { line: 1, character: 19 }, end: { line: 1, character: 27 } } },
      { name: 'S.t', range: { start: { line: 1, character: 28 }, end: { line: 1, character: 29 } } },
      { name: 'S.t', range: { start: { line: 1, character: 30 }, end: { line: 1, character: 31 } } },
      { name: 'S.b', range: { start: { line: 1, character: 34 }, end: { line: 1, character: 35 } }, nodeId: 'b' },
      { name: 'S.c', range: { start: { line: 2, character: 18 }, end: { line: 2, character: 19 } }, nodeId: 'c' },
      { name: 'S.b.holds', range: { start: { line: 2, character: 32 }, end: { line: 2, character: 39 } }, nodeId: 'b' },
    ]);
    const lines = (c.lean.code ?? '').split('\n');
    for (const ref of c.lean.refs ?? []) {
      const text = lines[ref.range.start.line]?.slice(ref.range.start.character, ref.range.end.character) ?? '';
      expect(ref.name.endsWith(text)).toBe(true);
    }
  });

  it('code that is not contiguous is joined by a blank line and refs are mapped per piece', () => {
    const split = [
      block({ id: 'b', type: 'ASSUMPTION', name: 'It is bad', rationale: 'r', lean: 'S.b' }),
      'abbrev b : Prop := Bad t',
      '',
      'abbrev other : Prop := Good t',
      '',
      'axiom b.holds : b',
    ].join('\n');
    const model = build({ 'Model/S/Vocabulary.lean': VOCAB_S, 'Model/S/Main.lean': mainS(split) }).model;
    const b = nodeOf(model, 'b');
    expect(b.lean.code).toBe('abbrev b : Prop := Bad t\n\naxiom b.holds : b');
    expect(b.lean.refs).toEqual([
      { name: 'S.Bad', range: { start: { line: 0, character: 19 }, end: { line: 0, character: 22 } } },
      { name: 'S.t', range: { start: { line: 0, character: 23 }, end: { line: 0, character: 24 } } },
      { name: 'S.b', range: { start: { line: 2, character: 16 }, end: { line: 2, character: 17 } }, nodeId: 'b' },
    ]);
    // An untracked Prop abbrev is a definition (D-4: endorsement needed only when a statement uses it).
    expect(model.vocabulary.find((v) => v.name === 'S.other')).toMatchObject({ kind: 'definition', flags: [] });
  });
});

/**
 * AT2.5: the Vocabulary group (D-3, docs/m1-plan.md section 6.4), with Lean's facts (`typeSort`) and without them
 * (syntactic mode).
 */
import { describe, expect, it } from 'vitest';
import type { VocabItem } from '../../src/model.js';
import { block, build, graphOf, mainS } from './helpers/build.js';

const VOCAB = `namespace S

/-- things -/
axiom T : Type
/-- there is at least one thing -/
axiom T.exists : Nonempty T
instance : Nonempty T := T.exists
/-- is good -/
axiom Good : T → Prop
/-- likes -/
axiom Likes : T → T → Prop
/-- it rains -/
axiom Rains : Prop
/-- a thing -/
noncomputable opaque t : T
/-- the best friend of -/
noncomputable opaque friend : T → T
/-- an asserted thing -/
axiom c : T
/-- a hidden assumption -/
axiom hidden : Good t
/-- a big universe -/
axiom U : Type 1
/-- whether a number is small -/
axiom Small : Nat → Prop
/-- good pairs -/
def GoodPair (x y : T) : Prop := Good x ∧ Good y
/-- a record -/
structure Rec where
  past : T
/-- a lemma -/
theorem good_good : ∀ x : T, Good x → Good x := fun _ h => h

end S
`;

const MAIN = mainS(
  [
    block({ id: 'p', type: 'GOAL', name: 'The thing makes a good pair with itself', lean: 'S.p' }),
    'abbrev p : Prop := GoodPair t t',
    '',
    block({ id: 'r', type: 'ASSUMPTION', name: 'The friend likes it', rationale: 'seen', lean: 'S.r' }),
    'abbrev r : Prop := Likes (friend t) t',
    'axiom r.holds : r',
  ].join('\n'),
);

const summary = (items: VocabItem[]) => items.map((v) => [v.shortName, v.kind, v.arity ?? null, v.flags]);

const EXPECTED = [
  ['T', 'sort', null, []],
  ['Good', 'predicate', 1, []],
  ['Likes', 'predicate', 2, []],
  ['Rains', 'predicate', 0, []],
  ['Small', 'predicate', 1, ['shape-violation']],
  ['friend', 'function', 1, []],
  ['t', 'constant', null, []],
  ['c', 'constant', null, ['shape-violation']],
  ['T.exists', 'presupposition', null, []],
  ['GoodPair', 'definition', null, ['definitional-choice']],
  ['Rec', 'definition', null, []],
  ['good_good', 'lemma', null, []],
  ['hidden', 'unmarked-axiom', null, ['unmarked-assumption']],
  ['U', 'other', null, ['shape-violation']],
];

describe('AT2.5 vocabulary classification', () => {
  const withFacts = build(
    { 'Model/S/Vocabulary.lean': VOCAB, 'Model/S/Main.lean': MAIN },
    {
      mutateFacts: (facts) => {
        // Lean's .ilean attributes the structure field to its structure (DeclFacts.parent).
        const rec = facts.decls.find((d) => d.name === 'S.Rec');
        if (!rec) throw new Error('fixture');
        facts.decls.push({ ...rec, name: 'S.Rec.past', kind: 'def', type: 'S.Rec → S.T', parent: 'S.Rec', refs: [], axioms: ['S.T'] });
      },
    },
  ).model;

  it('with facts: kinds, arities, flags, display order (sort, predicate, function, constant, presupposition, definition, lemma, unmarked-axiom, other)', () => {
    expect(summary(withFacts.vocabulary)).toEqual(EXPECTED);
  });

  it('attaches the presupposition to its sort and hides the anonymous Nonempty instance (matched by its start line)', () => {
    const t = withFacts.vocabulary.find((v) => v.name === 'S.T');
    const exists = withFacts.vocabulary.find((v) => v.name === 'S.T.exists');
    expect(t).toMatchObject({ presupposition: 'S.T.exists', type: 'Type', gloss: 'things', glossBy: 'user' });
    expect(exists).toMatchObject({ presupposes: 'S.T', type: 'Nonempty S.T' });
    expect(withFacts.vocabulary.map((v) => v.name)).not.toContain('S.instNonemptyT');
    expect(withFacts.declFacts.get('S.instNonemptyT')?.kind).toBe('instance');
  });

  it('folds a structure field into its structure', () => {
    expect(withFacts.vocabulary.map((v) => v.name)).not.toContain('S.Rec.past');
    expect(withFacts.vocabulary.find((v) => v.name === 'S.Rec')?.code).toBe('/-- a record -/\nstructure Rec where\n  past : T');
  });

  it('flags hidden assumptions (TL104) and shape violations (TL111) with the item name', () => {
    expect(withFacts.diagnostics.filter((d) => d.code === 'TL104').map((d) => d.vocab)).toEqual(['S.hidden']);
    expect(withFacts.diagnostics.filter((d) => d.code === 'TL111').map((d) => d.vocab)).toEqual(['S.c', 'S.U', 'S.Small']);
    const c = withFacts.diagnostics.find((d) => d.vocab === 'S.c');
    expect(c?.message).toMatch(/noncomputable opaque/);
    expect(c?.range).toEqual(withFacts.vocabulary.find((v) => v.name === 'S.c')?.loc?.range);
  });

  it('usedBy lists the nodes whose uses or presuppositions contain the item; definitions in a statement closure are definitional choices', () => {
    const usedBy = Object.fromEntries(withFacts.vocabulary.map((v) => [v.shortName, v.usedBy]));
    expect(usedBy).toMatchObject({ GoodPair: ['p'], Good: ['p'], T: ['p'], t: ['p', 'r'], Likes: ['r'], friend: ['r'], 'T.exists': ['p', 'r'], c: [], hidden: [] });
    const graph = graphOf(withFacts);
    expect(graph.nodes.find((n) => n.id === 'p')?.status.flags).toContain('definitional-choice');
    expect(graph.nodes.find((n) => n.id === 'r')?.status.flags).not.toContain('definitional-choice');
  });

  it('without facts the same rules run on the declaration text', () => {
    const syntactic = build({ 'Model/S/Vocabulary.lean': VOCAB, 'Model/S/Main.lean': MAIN }, { facts: false }).model;
    // No usedBy without facts (uses are Lean's), hence no definitional-choice; otherwise the same classification.
    expect(summary(syntactic.vocabulary)).toEqual(EXPECTED.map(([n, k, a, f]) => [n, k, a, (f as string[]).filter((x) => x !== 'definitional-choice')]));
    expect(syntactic.vocabulary.find((v) => v.name === 'S.Likes')?.type).toBe('S.T → S.T → Prop');
    expect(syntactic.vocabulary.find((v) => v.name === 'S.T.exists')).toMatchObject({ presupposes: 'S.T', type: 'Nonempty S.T' });
    expect(syntactic.vocabulary.map((v) => v.name)).not.toContain('S.instNonemptyT');
  });

  it('a predicate over a non-sort is a shape violation; an `axiom P0 : Prop` is a predicate of arity 0', () => {
    const small = withFacts.vocabulary.find((v) => v.name === 'S.Small');
    expect(small).toMatchObject({ kind: 'predicate', arity: 1, flags: ['shape-violation'] });
    expect(withFacts.vocabulary.find((v) => v.name === 'S.Rains')).toMatchObject({ kind: 'predicate', arity: 0, type: 'Prop' });
  });
});

/**
 * AT2.9 (two subjects: separate graphs, workspace-wide ids, TL006/TL120/TL121) and AT2.12 (diagnostics: LEAN
 * messages by containment with Lean's severity, markup diagnostics with node ids, per-subject filtering).
 */
import { describe, expect, it } from 'vitest';
import { emptyLayout, moveInLayout, orderByLayout } from '../../src/layout.js';
import type { LeanMessageFact } from '../../src/facts.js';
import { buildProjectModel, subjectGraph } from '../../src/project/index.js';
import { SPYRO_SEMANTIC, spyroGraph } from '../../src/samples/spyro.js';
import { fakeFacts, freshHashes } from './helpers/fakeFacts.js';
import { parseFixture } from './helpers/parseFixture.js';
import { SPYRO_TEXTS } from './helpers/spyro.js';

const ZELDA_VOCAB = `namespace Zelda

/-- heroes -/
axiom Hero : Type
/-- there is at least one hero -/
axiom Hero.exists : Nonempty Hero
instance : Nonempty Hero := Hero.exists
/-- is brave -/
axiom Brave : Hero → Prop
/-- Link -/
noncomputable opaque link : Hero

end Zelda
`;

const ZELDA_MAIN = `import Model.Zelda.Vocabulary

namespace Zelda

/-
@@ telelean v1
id: link-brave
type: ASSUMPTION
natural_name: Link is brave
rationale: he fights Ganon
lean: Zelda.link_brave
-/
abbrev link_brave : Prop := Brave link
theorem link_brave.holds : link_brave := sorry

/-
@@ telelean v1
type: GOAL
natural_name: Cynder dark past
premises: cynder-dark-past
-/

/-
@@ telelean v1
id: new-spyro-pg
type: ASSUMPTION
natural_name: Same id as a Spyro card
rationale: copied
-/

end Zelda
`;

const ROOT = `import Model.Spyro.Main
import Model.Zelda.Main

/-
@@ telelean v1
id: stray
type: GOAL
natural_name: A card in the library root
-/
`;

function twoSubjects(messages: LeanMessageFact[] = []) {
  const files = [
    parseFixture('Model.lean', ROOT),
    parseFixture('Model/Spyro/Main.lean', SPYRO_TEXTS.main),
    parseFixture('Model/Spyro/Vocabulary.lean', SPYRO_TEXTS.vocabulary),
    parseFixture('Model/Zelda/Main.lean', ZELDA_MAIN),
    parseFixture('Model/Zelda/Vocabulary.lean', ZELDA_VOCAB),
  ];
  const facts = fakeFacts(files, { messages });
  return buildProjectModel({ files, fileHashes: freshHashes(files), facts, library: 'Model' });
}

describe('AT2.9 two subjects', () => {
  const model = twoSubjects();

  it('lists both subjects with their files and node counts', () => {
    expect(model.subjects).toEqual([
      { name: 'Spyro', nodeCount: 4, files: ['Model/Spyro/Main.lean', 'Model/Spyro/Vocabulary.lean'] },
      { name: 'Zelda', nodeCount: 2, files: ['Model/Zelda/Main.lean', 'Model/Zelda/Vocabulary.lean'] },
    ]);
  });

  it('cuts separate subject graphs (nodes, vocabulary, edges)', () => {
    const spyro = subjectGraph(model, 'Spyro', { version: 3, semantic: SPYRO_SEMANTIC });
    const zelda = subjectGraph(model, 'Zelda', { version: 4, semantic: SPYRO_SEMANTIC });
    expect(spyro.nodes.map((n) => n.id)).toEqual(spyroGraph().nodes.map((n) => n.id));
    expect(zelda.nodes.map((n) => n.id)).toEqual(['link-brave', 'cynder-dark-past-2']);
    expect(spyro.vocabulary.every((v) => v.subject === 'Spyro')).toBe(true);
    expect(zelda.vocabulary.map((v) => v.name)).toEqual(['Zelda.Hero', 'Zelda.Brave', 'Zelda.link', 'Zelda.Hero.exists']);
    expect(zelda.vocabulary.find((v) => v.name === 'Zelda.Hero')?.shortName).toBe('Hero');
    // The cross-subject premise is reported, but no edge leaves the subject.
    expect(zelda.edges).toEqual([]);
    expect(spyro.edges).toHaveLength(3);
    expect(subjectGraph(model, 'Nope', { version: 5, semantic: SPYRO_SEMANTIC }).nodes).toEqual([]);
  });

  it('a duplicate written id is TL006 (the first file in path order keeps it); a derived-id collision is suffixed silently', () => {
    const dup = model.diagnostics.filter((d) => d.code === 'TL006');
    expect(dup).toMatchObject([{ file: 'Model/Zelda/Main.lean', severity: 'error' }]);
    expect(model.nodes.get('new-spyro-pg')?.file).toBe('Model/Spyro/Main.lean');
    expect(model.nodes.get('cynder-dark-past-2')?.node.naturalName).toBe('Cynder dark past');
    expect(model.nodes.get('cynder-dark-past')?.file).toBe('Model/Spyro/Main.lean');
    expect(model.diagnostics.filter((d) => d.code === 'TL006')).toHaveLength(1);
  });

  it('a premise in another subject is TL121; a block outside every subject is TL120', () => {
    expect(model.diagnostics.find((d) => d.code === 'TL121')).toMatchObject({ nodeId: 'cynder-dark-past-2', file: 'Model/Zelda/Main.lean' });
    expect(model.diagnostics.find((d) => d.code === 'TL120')).toMatchObject({ file: 'Model.lean', severity: 'warning' });
    expect(model.nodes.has('stray')).toBe(false);
  });

  it('orders a subject\'s nodes by its layout first, then file order', () => {
    const current = orderByLayout(subjectGraph(model, 'Spyro', { version: 1, semantic: SPYRO_SEMANTIC }).nodes);
    const layout = moveInLayout(emptyLayout(), current, 'new-spyro-pg', 'ASSUMPTION', 'pg-no-dark-past');
    const graph = subjectGraph(model, 'Spyro', { version: 1, semantic: SPYRO_SEMANTIC, layout });
    expect(graph.nodes.map((n) => n.id)).toEqual(['new-spyro-pg', 'pg-no-dark-past', 'cynder-dark-past', 'cynder-not-good']);
  });
});

describe('AT2.12 diagnostics', () => {
  it('LEAN messages get their node by containment and their severity from Lean; vocabulary messages name the item', () => {
    const zeldaMainLines = ZELDA_MAIN.split('\n');
    const sorryLine = zeldaMainLines.findIndex((l) => l.startsWith('theorem link_brave.holds'));
    const vocabLine = SPYRO_TEXTS.vocabulary.split('\n').findIndex((l) => l.startsWith('axiom HasDarkPast'));
    const model = twoSubjects([
      { severity: 'warning', file: 'Model/Zelda/Main.lean', module: 'Model.Zelda.Main', range: { start: { line: sorryLine, character: 8 }, end: { line: sorryLine, character: 8 } }, text: "declaration uses 'sorry'" },
      { severity: 'information', file: 'Model/Spyro/Vocabulary.lean', module: 'Model.Spyro.Vocabulary', range: { start: { line: vocabLine, character: 6 }, end: { line: vocabLine, character: 6 } }, text: 'a note\n  with a continuation line' },
    ]);
    const lean = model.diagnostics.filter((d) => d.code === 'LEAN');
    expect(lean).toEqual([
      { code: 'LEAN', severity: 'info', message: 'a note\n  with a continuation line', file: 'Model/Spyro/Vocabulary.lean', range: { start: { line: vocabLine, character: 6 }, end: { line: vocabLine, character: 6 } }, vocab: 'Spyro.HasDarkPast' },
      { code: 'LEAN', severity: 'warning', message: "declaration uses 'sorry'", file: 'Model/Zelda/Main.lean', range: { start: { line: sorryLine, character: 8 }, end: { line: sorryLine, character: 8 } }, nodeId: 'link-brave' },
    ]);
    // A warning does not make the node ill-formed (an error would).
    expect(model.nodes.get('link-brave')?.node.status.formal).toBe('formalized');
    expect(model.nodes.get('link-brave')?.node.status.flags).toContain('uses-sorry');
  });

  it('markup diagnostics carry the (workspace-resolved) node id', () => {
    const files = [parseFixture('Model/Zelda/Main.lean', ZELDA_MAIN), parseFixture('Model/Zelda/Vocabulary.lean', ZELDA_VOCAB), parseFixture('Model/Spyro/Main.lean', SPYRO_TEXTS.main), parseFixture('Model/Spyro/Vocabulary.lean', SPYRO_TEXTS.vocabulary)];
    const zelda = files[0];
    if (!zelda) throw new Error('fixture');
    const derived = zelda.blocks[1];
    if (!derived) throw new Error('fixture');
    zelda.diagnostics.push({ code: 'TL112', severity: 'info', message: 'block without id', span: derived.markerSpan, range: derived.range, nodeId: derived.id });
    const model = buildProjectModel({ files, fileHashes: freshHashes(files), facts: fakeFacts(files), library: 'Model' });
    expect(model.diagnostics.find((d) => d.code === 'TL112')).toMatchObject({ nodeId: 'cynder-dark-past-2', file: 'Model/Zelda/Main.lean', severity: 'info' });
  });

  it('a subject graph carries its own diagnostics (and project-level ones), never another subject\'s', () => {
    const model = twoSubjects();
    const spyro = subjectGraph(model, 'Spyro', { version: 1, semantic: SPYRO_SEMANTIC });
    const zelda = subjectGraph(model, 'Zelda', { version: 1, semantic: SPYRO_SEMANTIC });
    expect(spyro.diagnostics.map((d) => d.code).sort()).toEqual(['TL011', 'TL120']);
    expect(zelda.diagnostics.map((d) => d.code).sort()).toEqual(['TL006', 'TL115', 'TL120', 'TL121']);
    expect(spyro.diagnostics.every((d) => d.file !== 'Model/Zelda/Main.lean')).toBe(true);
  });
});

/**
 * AT2.11: verified edges come from Lean's references, not from footprints. A goal proved through a derivation
 * (`g2.holds := d0.holds.2`, whose `#print axioms` lists only d0's assumptions) gets the edge d0 -> g2; a proof through
 * an untracked lemma gets the edge from the node the lemma uses; D-13 mismatches are judged at the assumption level.
 */
import { describe, expect, it } from 'vitest';
import { kindChangeImpact, proofDependents } from '../../src/kindChange.js';
import { block, build, graphOf, mainS, nodeOf, VOCAB_S } from './helpers/build.js';

function derived(premisesOfG2: string[], extra = '') {
  const body = [
    block({ id: 'a1', type: 'ASSUMPTION', name: 'It is good', rationale: 'r', lean: 'S.a1' }),
    'abbrev a1 : Prop := Good t',
    'axiom a1.holds : a1',
    '',
    block({ id: 'a2', type: 'ASSUMPTION', name: 'It is bad', rationale: 'r', lean: 'S.a2' }),
    'abbrev a2 : Prop := Bad t',
    'axiom a2.holds : a2',
    '',
    block({ id: 'd0', type: 'DERIVATION', name: 'It is good and bad', premises: ['a1', 'a2'], lean: 'S.d0' }),
    'abbrev d0 : Prop := Good t ∧ Bad t',
    'theorem d0.holds : d0 := ⟨a1.holds, a2.holds⟩',
    '',
    block({ id: 'g2', type: 'GOAL', name: 'It is bad, again', premises: premisesOfG2, lean: 'S.g2' }),
    'abbrev g2 : Prop := Bad t',
    'theorem g2.holds : g2 := d0.holds.2',
    extra,
  ].join('\n');
  return build({ 'Model/S/Vocabulary.lean': VOCAB_S, 'Model/S/Main.lean': mainS(body) }, { facts: { overrides: { 'S.g2.holds': { extraRefs: ['And.right'] } } } });
}

describe('AT2.11 proofs through derivations and untracked lemmas', () => {
  it('g2.holds := d0.holds.2 gives the verified edge d0 -> g2, not the assumption edges, while the footprint lists the assumptions', () => {
    const { model, facts } = derived(['d0']);
    const g2Facts = facts?.decls.find((d) => d.name === 'S.g2.holds');
    expect(g2Facts?.refs.map((r) => r.name)).toEqual(['S.g2', 'S.d0.holds', 'And.right']);
    expect(g2Facts?.axioms).toEqual(['Classical.choice', 'S.Bad', 'S.Good', 'S.T', 'S.T.exists', 'S.a1.holds', 'S.a2.holds']);
    const g2 = nodeOf(model, 'g2');
    expect(g2.status.proof).toEqual({ kind: 'proved', footprint: ['a1', 'a2', 'presup:S.T.exists'] });
    const graph = graphOf(model);
    expect(graph.edges.filter((e) => e.type === 'verified').map((e) => e.id)).toEqual(['verified:a1->d0', 'verified:a2->d0', 'verified:d0->g2']);
    expect(graph.edges.some((e) => e.mismatch)).toBe(false);
    expect(model.diagnostics.filter((d) => d.code === 'TL107' || d.code === 'TL109')).toEqual([]);
  });

  it('proofDependents(d0) = [g2], so D -> G on d0 needs a confirmation', () => {
    const graph = graphOf(derived(['d0']).model);
    expect(proofDependents(graph, 'd0')).toEqual(['g2']);
    expect(proofDependents(graph, 'a1')).toEqual(['d0', 'g2']);
    expect(kindChangeImpact(graph, 'd0', 'GOAL')).toMatchObject({ needsConfirmation: true, dependents: ['g2'], leanChange: 'remove-holds' });
  });

  it('a proof through an untracked lemma gives the edge from the node the lemma uses', () => {
    const extra = [
      '',
      'theorem helper : Good t := a1.holds',
      '',
      block({ id: 'g4', type: 'GOAL', name: 'It is good, again', premises: ['a1'], lean: 'S.g4' }),
      'abbrev g4 : Prop := Good t',
      'theorem g4.holds : g4 := helper',
    ].join('\n');
    const { model } = derived(['d0'], extra);
    const graph = graphOf(model);
    expect(graph.edges.filter((e) => e.target === 'g4')).toEqual([
      { id: 'premise:a1->g4', type: 'premise', source: 'a1', target: 'g4', origin: 'declared' },
      { id: 'verified:a1->g4', type: 'verified', source: 'a1', target: 'g4', origin: 'lean', where: 'proof' },
    ]);
    expect(model.vocabulary.find((v) => v.name === 'S.helper')?.kind).toBe('lemma');
  });

  it('mismatches: premises [d0] with a proof via d0: none; premises [a1] with a proof using a2: used-undeclared (TL107) and declared-unused (TL109)', () => {
    const viaD0 = graphOf(derived(['d0']).model);
    expect(viaD0.edges.filter((e) => e.target === 'g2' && e.mismatch)).toEqual([]);

    // Through the derivation of the declared premises: d0 stands for {a1, a2}; declaring a1 and a2 covers it.
    const viaAssumptions = graphOf(derived(['a1', 'a2']).model);
    expect(viaAssumptions.edges.filter((e) => e.target === 'g2' && e.mismatch)).toEqual([]);

    const extra = [
      '',
      block({ id: 'g3', type: 'GOAL', name: 'Bad, from the wrong premise', premises: ['a1'], lean: 'S.g3' }),
      'abbrev g3 : Prop := Bad t',
      'theorem g3.holds : g3 := a2.holds',
    ].join('\n');
    const { model } = derived(['d0'], extra);
    const graph = graphOf(model);
    expect(graph.edges.find((e) => e.id === 'verified:a2->g3')?.mismatch).toBe('used-undeclared');
    expect(graph.edges.find((e) => e.id === 'premise:a1->g3')?.mismatch).toBe('declared-unused');
    expect(model.diagnostics.filter((d) => d.nodeId === 'g3').map((d) => [d.code, d.severity])).toEqual([
      ['TL105', 'info'],
      ['TL107', 'warning'],
      ['TL109', 'hint'],
    ]);
  });

  it('an unproved goal\'s declared premises are never declared-unused', () => {
    const extra = ['', block({ id: 'g5', type: 'GOAL', name: 'Unproved', premises: ['a1', 'a2'], lean: 'S.g5' }), 'abbrev g5 : Prop := Good t ∧ Bad t'].join('\n');
    const graph = graphOf(derived(['d0'], extra).model);
    expect(graph.edges.filter((e) => e.target === 'g5')).toEqual([
      { id: 'premise:a1->g5', type: 'premise', source: 'a1', target: 'g5', origin: 'declared' },
      { id: 'premise:a2->g5', type: 'premise', source: 'a2', target: 'g5', origin: 'declared' },
    ]);
  });

  it('lean-ref edges: a statement mentioning another node\'s statement', () => {
    const extra = ['', block({ id: 'g6', type: 'GOAL', name: 'Both', premises: ['d0'], lean: 'S.g6' }), 'abbrev g6 : Prop := d0 ∧ a1'].join('\n');
    const graph = graphOf(derived(['d0'], extra).model);
    expect(graph.edges.filter((e) => e.type === 'lean-ref')).toEqual([
      { id: 'lean-ref:d0->g6', type: 'lean-ref', source: 'd0', target: 'g6', origin: 'lean', where: 'statement' },
      { id: 'lean-ref:a1->g6', type: 'lean-ref', source: 'a1', target: 'g6', origin: 'lean', where: 'statement' },
    ]);
    // ... and its uses come through those statements (breadth-first).
    expect(graph.nodes.find((n) => n.id === 'g6')?.lean.uses).toEqual(['S.Good', 'S.t', 'S.Bad']);
  });
});

