    flags: [...item.flags],
  };
}

function edgeJson(edge: TlEdge): GraphJsonEdge {
  return {
    type: edge.type,
    source: edge.source,
    target: edge.target,
    origin: edge.origin,
    where: edge.where ?? null,
    conditional: edge.conditional === true,
    mismatch: edge.mismatch ?? null,
