/**
 * An editing session over the model's files (pure): it applies WP-markup's text primitives one step at a time,
 * re-parsing a file before the next step, and yields whole-file FileChanges at the end. Blocks of the original parse
 * are found again after earlier edits by mapping their start offset through the applied edits, so a plan may edit
 * several blocks (or a block and the declarations next to it) without the edits overlapping.
 *
 * Lean operations whose spans come from the facts (D-11 rewrite) must run before any other edit of their file: the
 * planners always apply Lean operations first.
 */
import { ActionError, type FileChange } from '../actions.js';
import type { ArchivedDecl, InsertWhere, KnownFieldKey, LeanOp, MarkupBlock, ParsedFile, TextEdit } from '../markup/types.js';
import { applyLeanOps, applyTextEdits, insertBlockEdits, parseLeanFile, removeBlockEdits, setBlockField } from '../markup/api.js';
import type { ProjectModel } from '../project/types.js';

interface FileState {
  before: string | null;
  text: string | null;
  parsed?: ParsedFile;
  /** Edit batches applied since the model's parse (offset mapping); undefined once the file was (re)created. */
  batches: TextEdit[][] | undefined;
}

/** `import <module>` added after the last import line of `text` (or first, when there is none); undefined if present. */
export function importEdit(text: string, module: string, eol: '\n' | '\r\n'): TextEdit | undefined {
  const linePattern = /^import\s+(\S+)\s*$/;
  let offset = 0;
  let lastImportEnd = -1;
  for (const raw of text.split('\n')) {
    const line = raw.endsWith('\r') ? raw.slice(0, -1) : raw;
    const match = linePattern.exec(line);
    if (match) {
      if (match[1] === module) return undefined;
      lastImportEnd = offset + line.length;
    } else if (line.trim() !== '' && !line.trimStart().startsWith('--')) {
      break;
    }
    offset += raw.length + 1;
  }
  if (lastImportEnd >= 0) return { span: { start: lastImportEnd, end: lastImportEnd }, newText: `${eol}import ${module}` };
  return { span: { start: 0, end: 0 }, newText: `import ${module}${eol}` };
}

export class EditSession {
  private readonly states = new Map<string, FileState>();

  constructor(private readonly model: ProjectModel) {}

  private state(path: string): FileState {
    let state = this.states.get(path);
    if (!state) {
      const file = this.model.files.get(path);
      state = file ? { before: file.text, text: file.text, parsed: file, batches: [] } : { before: null, text: null, batches: undefined };
      this.states.set(path, state);
    }
    return state;
  }

  exists(path: string): boolean {
    return this.state(path).text !== null;
  }

  text(path: string): string | null {
    return this.state(path).text;
  }

  parsed(path: string): ParsedFile {
    const state = this.state(path);
    if (state.text === null) throw new ActionError('internal', `${path} does not exist.`);
    if (!state.parsed) state.parsed = parseLeanFile(path, state.text);
    return state.parsed;
  }

  /** Creates a file that does not exist yet. */
  create(path: string, text: string): void {
    const state = this.state(path);
    if (state.text !== null) throw new ActionError('invalid', `${path} exists already.`);
    state.text = text;
    delete state.parsed;
    state.batches = undefined;
  }

  apply(path: string, edits: readonly TextEdit[]): void {
    if (edits.length === 0) return;
    const state = this.state(path);
    if (state.text === null) throw new ActionError('internal', `${path} does not exist.`);
    state.text = applyTextEdits(state.text, edits);
    delete state.parsed;
    state.batches?.push([...edits]);
  }

  /** Where an offset of the model's parse of `path` is now; undefined when an edit replaced it. */
  mapOffset(path: string, offset: number): number | undefined {
    const state = this.state(path);
    if (!state.batches) return undefined;
    let current = offset;
    for (const batch of state.batches) {
      let delta = 0;
      for (const edit of batch) {
        if (edit.span.end <= current) delta += edit.newText.length - (edit.span.end - edit.span.start);
        else if (edit.span.start <= current) return undefined;
      }
      current += delta;
    }
    return current;
  }

  /** The current parse of a block of the model. */
  block(path: string, original: MarkupBlock): MarkupBlock {
    const offset = this.mapOffset(path, original.span.start);
    const found = offset === undefined ? undefined : this.parsed(path).blocks.find((b) => b.span.start === offset);
    if (!found) throw new ActionError('unsafe', `The card's block in ${path} could not be found again after the other edits of this action.`);
    return found;
  }

  /** setBlockField on a block of the model; `nodeId` is the workspace id (written back when the block's id is derived). */
  setField(path: string, original: MarkupBlock, nodeId: string, key: KnownFieldKey, value: string | readonly string[] | null): void {
    const current = this.block(path, original);
    this.apply(path, setBlockField(this.parsed(path), { ...current, id: nodeId }, key, value));
  }

  removeBlock(path: string, original: MarkupBlock): void {
    const current = this.block(path, original);
    this.apply(path, removeBlockEdits(this.parsed(path), current));
  }

  insertBlock(path: string, blockText: string, where: InsertWhere): void {
    this.apply(path, insertBlockEdits(this.parsed(path), blockText, where));
  }

  /** Applies Lean operations to one file (all or nothing); refuses with `unsafe` when WP-markup reports problems. */
  leanOps(path: string, ops: readonly LeanOp[]): ArchivedDecl[] {
    if (ops.length === 0) return [];
    const result = applyLeanOps(this.parsed(path), ops);
    if (result.problems.length > 0) throw new ActionError('unsafe', result.problems.join(' '));
    this.apply(path, result.edits);
    return result.archived;
  }

  /** Adds `import <module>` to `path` (creating the file with just that line when it does not exist). */
  addImport(path: string, module: string): void {
    if (!this.exists(path)) {
      this.create(path, `import ${module}\n`);
      return;
    }
    const text = this.text(path) ?? '';
    const edit = importEdit(text, module, text.includes('\r\n') ? '\r\n' : '\n');
    if (edit) this.apply(path, [edit]);
  }

  /** The whole-file changes so far (files whose text changed), by path. */
  changes(): FileChange[] {
    const out: FileChange[] = [];
    for (const [path, state] of this.states) if (state.text !== state.before) out.push({ path, before: state.before, after: state.text });
    return out.sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : 0));
  }
}

/**
 * Who uses a declaration (D-11 kind changes, D-18 deletes): from Lean's references (`DeclFacts.refs`, transitively),
 * plus, while some file is not freshly checked, a syntactic scan for the name in the declarations' text (so a use
 * typed since the last check still counts as a dependent and nothing that others use is removed silently).
 */
import type { DeclInfo, ParsedFile } from '../markup/types.js';
import type { ProjectModel } from '../project/types.js';
import { blankComments, identifierTokens } from '../project/text.js';
import { resolveName } from '../project/vocabulary.js';

/** Declarations whose facts refs name one of `targets`, closed under "uses a member" (BFS order). */
export function factUsers(model: ProjectModel, targets: readonly string[], exclude: ReadonlySet<string>): string[] {
  const users = new Map<string, string[]>();
  for (const [name, facts] of model.declFacts) {
    for (const ref of facts.refs) {
      const list = users.get(ref.name) ?? [];
      if (!list.includes(name)) list.push(name);
      users.set(ref.name, list);
    }
  }
  const out: string[] = [];
  const seen = new Set<string>([...targets, ...exclude]);
  const queue = [...targets];
  while (queue.length > 0) {
    const name = queue.shift() as string;
    for (const user of users.get(name) ?? []) {
      if (seen.has(user)) continue;
      seen.add(user);
      out.push(user);
      queue.push(user);
    }
  }
  return out;
}

/** The text of a declaration after its name (signature and value), comments and strings blanked. */
function declBody(file: ParsedFile, decl: DeclInfo): string {
  return blankComments(file.text.slice(decl.nameSpan?.end ?? decl.keywordSpan.end, decl.span.end));
}

/** Declarations whose text mentions one of `targets` (resolved in their namespace), transitively. */
export function textUsers(model: ProjectModel, targets: readonly string[], exclude: ReadonlySet<string>): string[] {
  const decls: Array<{ name: string; file: ParsedFile; decl: DeclInfo }> = [];
  for (const file of model.files.values()) for (const decl of file.decls) if (decl.fullName) decls.push({ name: decl.fullName, file, decl });
  const out: string[] = [];
  const found = new Set<string>(targets);
  let grew = true;
  while (grew) {
    grew = false;
    for (const { name, file, decl } of decls) {
      if (found.has(name) || exclude.has(name)) continue;
      const mentions = identifierTokens(declBody(file, decl)).some((t) => {
        let text = t.text;
        for (;;) {
          if (resolveName(text, decl.namespace, (n) => found.has(n))) return true;
          const dot = text.lastIndexOf('.');
          if (dot < 0) return false;
          text = text.slice(0, dot);
        }
      });
      if (mentions) {
        found.add(name);
        out.push(name);
        grew = true;
      }
    }
  }
  return out;
}

/** True when every model file is freshly checked (the facts see every use). */
export function allFresh(model: ProjectModel): boolean {
  return model.facts !== undefined && [...model.files.keys()].every((p) => model.freshFiles.has(p));
}

/** Users of `targets` (facts first, then text-only finds while the facts are not fresh everywhere). */
export function usersOf(model: ProjectModel, targets: readonly string[], exclude: ReadonlySet<string>): { all: string[]; fromFacts: string[] } {
  const fromFacts = factUsers(model, targets, exclude);
  if (allFresh(model)) return { all: fromFacts, fromFacts };
  const all = [...fromFacts];
  for (const name of textUsers(model, [...targets, ...fromFacts], exclude)) if (!all.includes(name)) all.push(name);
  return { all, fromFacts };
}

/** Where a declaration is (syntactic first, else its facts). */
export function locateDecl(model: ProjectModel, name: string): { file: string; decl?: DeclInfo } | undefined {
  for (const file of model.files.values()) {
    const decl = file.decls.find((d) => d.fullName === name);
    if (decl) return { file: file.path, decl };
  }
  const facts = model.declFacts.get(name);
  return facts ? { file: facts.file } : undefined;
}

/**
 * D-11 kind changes with the Lean facts (docs/m1-plan.md section 6.2). S = the statement, H = `S.holds`,
 * hk = H's kind (`other` counts as `theorem`):
 *
 * | from->to  | code-less | hk absent           | hk axiom                         | hk theorem                         |
 * |-----------|-----------|---------------------|----------------------------------|------------------------------------|
 * | G->D      | type      | type                | type (pending promotion)         | type ("already proved")            |
 * | G->A, D->A| type      | type+add-holds-axiom| type                             | type+holds-theorem-to-axiom        |
 * | A->D      | type      | type                | type (pending promotion)         | type                               |
 * | A->G, D->G| type      | type                | no deps: type+remove-holds; deps: needs a DependentsChoice (same, archived) |
 *
 * `mark-broken` removes H and lists what will no longer compile; `rewrite` (fresh facts only) gives every user a
 * hypothesis `(h_S : S)` as its first binder and passes it on (`(c h_S)`) to the other rewritten users.
 */
import { ActionError } from '../actions.js';
import { holdsName } from '../facts.js';
import { kindChangeImpact, proofDependents } from '../kindChange.js';
import type { LeanOp, Span } from '../markup/types.js';
import { relativeName } from '../markup/api.js';
import type { NodeType, SemanticSummary } from '../model.js';
import { subjectGraph } from '../project/index.js';
import type { ProjectModel } from '../project/types.js';
import { hasToken, LineMap } from '../project/text.js';
import { allFresh, locateDecl, usersOf } from './dependents.js';
import type { KindChangePlan, KindChangeRequest } from './types.js';

const NOUN: Readonly<Record<NodeType, string>> = { ASSUMPTION: 'Assumption', DERIVATION: 'Derivation', GOAL: 'Goal' };

/** The semantic state the planner previews kind changes with (the facts as the model knows them). */
export function modelSemantic(model: ProjectModel): SemanticSummary {
  if (!model.facts) return { state: 'unavailable' };
  return { state: allFresh(model) ? 'fresh' : 'stale' };
}

function plural(n: number, word: string): string {
  return `${n} ${word}${n === 1 ? '' : 's'}`;
}

/** Statement not found (TL101) or not a Prop abbrev/def (TL113): kind changes then touch only `type:`. */
function bindingBroken(model: ProjectModel, id: string): boolean {
  return model.diagnostics.some((d) => d.nodeId === id && (d.code === 'TL101' || d.code === 'TL113'));
}

export function planKind(model: ProjectModel, request: KindChangeRequest): KindChangePlan {
  const entry = model.nodes.get(request.id);
  if (!entry) throw new ActionError('not-found', `No card "${request.id}".`);
  const node = entry.node;
  const from = node.type;
  const to = request.to;
  if (from === to) throw new ActionError('invalid', 'Moving a card within its own column only re-orders it.');
  const graph = subjectGraph(model, node.subject, { version: 0, semantic: modelSemantic(model) });
  const impact = kindChangeImpact(graph, node.id, to);

  const plan: KindChangePlan = { id: node.id, from, to, impact, fieldChanges: [{ key: 'type', value: to }], leanOps: [], broken: [] };
  const statement = node.lean.statement;
  if (!statement || !entry.statementDecl || node.status.formal === 'informal' || bindingBroken(model, node.id)) return plan;

  const holds = holdsName(statement);
  const hk = node.lean.justificationKind;
  const statementFile = entry.statementDecl.file;
  const holdsFile = entry.holdsDecl?.file ?? model.declFacts.get(holds)?.file ?? statementFile;
  const ops = new Map<string, LeanOp[]>();
  const add = (file: string, op: LeanOp) => ops.set(file, [...(ops.get(file) ?? []), op]);
  const finish = () => {
    plan.leanOps = [...ops.keys()].sort().map((file) => ({ file, ops: ops.get(file) ?? [] }));
    return plan;
  };

  if (to === 'DERIVATION') return finish();
  if (to === 'ASSUMPTION') {
    if (hk === undefined) add(statementFile, { op: 'add-holds-axiom', statement });
    else if (hk !== 'axiom') add(holdsFile, { op: 'holds-theorem-to-axiom', statement });
    return finish();
  }

  // to === 'GOAL': a goal is not taken as given, so H must go.
  if (hk === undefined) return finish();
  const archive = hk !== 'axiom';
  const users = usersOf(model, [holds], new Set([statement, holds]));
  const dependents: string[] = [];
  for (const id of proofDependents(graph, node.id)) if (!dependents.includes(id)) dependents.push(id);
  for (const name of users.all) {
    const owner = model.ownerOfDecl.get(name);
    if (owner !== undefined && owner !== node.id) {
      if (!dependents.includes(owner)) dependents.push(owner);
    }
  }
  for (const name of users.all) if (model.ownerOfDecl.get(name) === undefined && !dependents.includes(name)) dependents.push(name);
  for (const d of dependents) if (!plan.impact.dependents.includes(d)) plan.impact.dependents.push(d);
  if (dependents.length > 0) plan.impact.needsConfirmation = true;

  if (users.all.length === 0) {
    add(holdsFile, { op: 'remove-holds', statement, archive });
    return finish();
  }
  const short = statement.split('.').pop() ?? statement;
  if (!request.dependents) {
    throw new ActionError(
      'needs-confirmation',
      `Making it a Goal removes ${short}.holds, which ${plural(dependents.length, 'dependent')} use${dependents.length === 1 ? 's' : ''}: rewrite them to take it as a hypothesis, or keep them and let them show as broken.`,
      dependents,
    );
  }
  if (request.dependents === 'mark-broken') {
    add(holdsFile, { op: 'remove-holds', statement, archive });
    plan.broken = [...users.all];
    return finish();
  }

  // rewrite: needs exact reference spans, so every touched file must be freshly checked.
  const closure = users.fromFacts;
  const touched = new Set<string>([holdsFile]);
  for (const name of users.all) {
    const where = locateDecl(model, name);
    touched.add(where?.file ?? '');
  }
  const staleFiles = [...touched].filter((file) => !model.freshFiles.has(file));
  if (staleFiles.length > 0 || users.all.length !== closure.length) {
    throw new ActionError('facts-stale', `Refresh Lean first: ${staleFiles.length > 0 ? staleFiles.join(', ') : 'some files'} changed since the last check, so the dependents cannot be rewritten exactly.`);
  }
  const notTheorems = closure.filter((name) => model.declFacts.get(name)?.kind !== 'theorem');
  if (notTheorems.length > 0) {
    throw new ActionError(
      'unsafe',
      `${notTheorems.join(', ')} ${notTheorems.length === 1 ? 'is' : 'are'} not a theorem and cannot take a hypothesis without changing ${notTheorems.length === 1 ? 'its' : 'their'} type: choose "mark broken" instead.`,
      notTheorems,
    );
  }
  if (hk === 'axiom') {
    const invisible: string[] = [];
    for (const facts of model.declFacts.values()) {
      if (facts.name === holds || closure.includes(facts.name) || !(facts.axioms ?? []).includes(holds)) continue;
      invisible.push(facts.name);
    }
    if (invisible.length > 0) {
      throw new ActionError(
        'unsafe',
        `${invisible.join(', ')} ${invisible.length === 1 ? 'depends' : 'depend'} on ${short}.holds in a way Lean's references do not show (e.g. through notation): choose "mark broken" instead.`,
        invisible,
      );
    }
  }

  // The rewritten users, in file then source order.
  const members = closure
    .map((name) => {
      const facts = model.declFacts.get(name);
      const file = facts ? model.files.get(facts.file) : undefined;
      const decl = file?.decls.find((d) => d.fullName === name);
      if (!facts || !file || !decl) throw new ActionError('unsafe', `${name} could not be found in the files: refresh Lean first.`);
      return { name, facts, file, decl };
    })
    .sort((a, b) => (a.file.path < b.file.path ? -1 : a.file.path > b.file.path ? 1 : a.decl.span.start - b.decl.span.start));
  const base = `h_${short}`;
  let hypName = base;
  for (let n = 2; members.some((m) => hasToken(m.file.text.slice(m.decl.span.start, m.decl.span.end), hypName)); n++) hypName = `${base}_${n}`;
  const lineMaps = new Map<string, LineMap>();
  const lines = (path: string, text: string) => {
    let map = lineMaps.get(path);
    if (!map) lineMaps.set(path, (map = new LineMap(text)));
    return map;
  };
  for (const member of members) {
    const map = lines(member.file.path, member.file.text);
    const spansOf = (target: string): Span[] =>
      member.facts.refs.filter((r) => r.name === target).map((r) => ({ start: map.offsetAt(r.range.start), end: map.offsetAt(r.range.end) }));
    add(member.file.path, { op: 'add-hypothesis', decl: member.name, hypName, hypType: relativeName(statement, member.decl.namespace), replace: spansOf(holds) });
    for (const other of members) {
      if (other.name === member.name) continue;
      const spans = spansOf(other.name);
      if (spans.length > 0) add(member.file.path, { op: 'apply-hypothesis', decl: member.name, hypName, replace: spans });
    }
  }
  add(holdsFile, { op: 'remove-holds', statement, archive });
  return finish();
}

export { NOUN };

