52	/** Ids of nodes reachable from `id` along verified (proof) edges: everything whose proof rests on `id`. */
53	export function proofDependents(graph: Pick<TlGraph, 'edges'>, id: string): string[] {
54	  const out: string[] = [];
55	  const seen = new Set([id]);
56	  const queue = [id];
57	  while (queue.length > 0) {
58	    const current = queue.shift() as string;
59	    for (const edge of graph.edges) {
60	      if (edge.type !== 'verified' || edge.source !== current || seen.has(edge.target)) continue;
61	      seen.add(edge.target);
62	      out.push(edge.target);
63	      queue.push(edge.target);
64	    }
65	  }
66	  return out;
67	}
