describe('board store', () => {
  it('splits the graph into columns', () => {
    const { state } = setup();
    expect(state().order).toEqual({
      ASSUMPTION: ['pg-no-dark-past', 'cynder-dark-past', 'new-spyro-pg'],
      DERIVATION: [],
      GOAL: ['cynder-not-good'],
    });
  });

  it('click selects one card, Ctrl/Cmd-click toggles, and every change posts select', () => {
    const { state, sent } = setup();
    state().clickCard('cynder-dark-past', false);
    state().clickCard('new-spyro-pg', true);
    state().clickCard('cynder-not-good', true);
    state().clickCard('new-spyro-pg', true);
    expect(state().selected).toEqual(['cynder-dark-past', 'cynder-not-good']);
    expect(sent.map((m) => m.type)).toEqual(['select', 'select', 'select', 'select']);
    state().clickCard('cynder-dark-past', false);
    expect(state().selected).toEqual(['cynder-dark-past']);
  });

  it('the tray puts the single goal in the target slot and theseSuffice posts premises and target', () => {
    const { state, sent } = setup();
    for (const id of ['cynder-dark-past', 'new-spyro-pg', 'cynder-not-good']) state().clickCard(id, true);
    expect(trayModel(state())).toEqual({ premises: ['cynder-dark-past', 'new-spyro-pg'], target: 'cynder-not-good', blocked: null });
    expect(state().theseSuffice()).toBe(true);
    expect(sent.at(-1)).toEqual({ v: 1, type: 'theseSuffice', payload: { premises: ['cynder-dark-past', 'new-spyro-pg'], target: 'cynder-not-good' } });
  });

  it('theseSuffice refuses without a target', () => {
    const { state, sent } = setup();
    state().clickCard('cynder-dark-past', false);
    expect(trayModel(state()).blocked).toMatch(/goal/);
    expect(state().theseSuffice()).toBe(false);
    expect(sent.some((m) => m.type === 'theseSuffice')).toBe(false);
  });

  it('dropCard moves the card, changes its kind and posts kindChange; reordering within a column posts nothing', () => {
    const { state, sent } = setup();
    state().dropCard('pg-no-dark-past', 'GOAL', 'cynder-not-good');
    expect(state().order.GOAL).toEqual(['pg-no-dark-past', 'cynder-not-good']);
    expect(state().nodes['pg-no-dark-past']?.type).toBe('GOAL');
    expect(sent.at(-1)).toEqual({ v: 1, type: 'kindChange', payload: { id: 'pg-no-dark-past', from: 'ASSUMPTION', to: 'GOAL', beforeId: 'cynder-not-good' } });
    const count = sent.length;
    state().dropCard('new-spyro-pg', 'ASSUMPTION', 'cynder-dark-past');
    expect(state().order.ASSUMPTION).toEqual(['new-spyro-pg', 'cynder-dark-past']);
    expect(sent.length).toBe(count);
  });

  it('addNode appends a comment-only card and posts addNode', () => {
    const { state, sent } = setup();
    const id = state().addNode('DERIVATION', '  Cynder   cannot appear in a PG game ');
    expect(id).toBe('cynder-cannot-appear-in-a-pg');
    expect(state().order.DERIVATION).toEqual([id]);
    expect(state().nodes[id ?? '']?.status.formal).toBe('informal');
    expect(sent.at(-1)).toEqual({ v: 1, type: 'addNode', payload: { clientId: id, type: 'DERIVATION', naturalName: 'Cynder cannot appear in a PG game' } });
    expect(state().addNode('GOAL', '   ')).toBeNull();
  });

  it('a new graph keeps the selection of nodes that still exist', () => {
    const { state, sent } = setup();
    state().clickCard('cynder-dark-past', false);
    state().addNode('GOAL', 'Temporary');
    state().clickCard('temporary', true);
    state().applyGraph(spyroGraph(2));
    expect(state().selected).toEqual(['cynder-dark-past']);
    expect(sent.at(-1)).toEqual({ v: 1, type: 'select', payload: { ids: ['cynder-dark-past'] } });
  });
});

