export function sampleGraph(name: SampleName): TlGraph {
  switch (name) {
    case 'spyro':
      return spyroGraph();
    case 'spyro-proved':
      return spyroProvedGraph();
    case 'large':
      return largeGraph();
  }
}

export interface BoardDeps {
  extensionUri: vscode.Uri;
  log: vscode.LogOutputChannel;
  /** Fired for every validated webview message. */
  messages: vscode.EventEmitter<WebviewToHostMessage>;
}

/** The board's WebviewPanel: one per window, revealed again when the command runs twice. */
export class BoardPanel implements vscode.Disposable {
  static readonly viewType = 'telelean.board';
  static current: BoardPanel | undefined;

  private readonly disposables: vscode.Disposable[] = [];
  private disposed = false;

  static show(deps: BoardDeps, graph: TlGraph): BoardPanel {
    const existing = BoardPanel.current;
    if (existing) {
      existing.panel.reveal();
      existing.setGraph(graph);
      return existing;
    }
    const webviewRoot = vscode.Uri.joinPath(deps.extensionUri, 'dist', 'webview');
    const panel = vscode.window.createWebviewPanel(BoardPanel.viewType, 'telelean', vscode.ViewColumn.Active, {
      enableScripts: true,
      enableCommandUris: false,
      enableFindWidget: true,
      retainContextWhenHidden: true,
      localResourceRoots: [webviewRoot],
    });
    BoardPanel.current = new BoardPanel(panel, deps, webviewRoot, graph);
    return BoardPanel.current;
  }

  private constructor(
    readonly panel: vscode.WebviewPanel,
    private readonly deps: BoardDeps,
    webviewRoot: vscode.Uri,
    private graph: TlGraph,
  ) {
    const { webview } = panel;
    webview.html = renderBoardHtml({
      cspSource: webview.cspSource,
      nonce: randomBytes(18).toString('base64'),
      bootUri: webview.asWebviewUri(vscode.Uri.joinPath(webviewRoot, 'boot.js')).toString(),
      scriptUri: webview.asWebviewUri(vscode.Uri.joinPath(webviewRoot, 'webview.js')).toString(),
      styleUri: webview.asWebviewUri(vscode.Uri.joinPath(webviewRoot, 'webview.css')).toString(),
    });
    this.disposables.push(
      webview.onDidReceiveMessage((raw: unknown) => this.receive(raw)),
      panel.onDidDispose(() => this.dispose()),
    );
    deps.log.info(`board opened (graph "${graph.subject}" v${graph.version}, ${graph.nodes.length} nodes)`);
  }

  setGraph(graph: TlGraph): void {
    this.graph = graph;
    void this.postGraph();
  }

  private receive(raw: unknown): void {
    // The webview renders workspace text and (later) LLM output: treat what it sends as untrusted.
    const parsed = parseWebviewToHost(raw);
    if (!parsed.ok) {
      this.deps.log.warn(`[webview->host] rejected message: ${parsed.error}`);
      return;
    }
    const message = parsed.value;
    const line = `[webview->host] ${message.type} ${JSON.stringify(message.payload)}`;
    if (message.type === 'diagnostic' && message.payload.level === 'error') this.deps.log.error(line);
    else if (message.type === 'diagnostic' && message.payload.level === 'warn') this.deps.log.warn(line);
    else this.deps.log.info(line);

