import { createContext, useContext, type ReactNode } from 'react';
import { useStore } from 'zustand';
import type { BoardActions, BoardState, BoardStore } from './store';

const BoardStoreContext = createContext<BoardStore | null>(null);

export function BoardStoreProvider({ store, children }: { store: BoardStore; children: ReactNode }) {
  return <BoardStoreContext.Provider value={store}>{children}</BoardStoreContext.Provider>;
}

export function useBoardStore(): BoardStore {
  const store = useContext(BoardStoreContext);
  if (!store) throw new Error('useBoardStore must be used inside <BoardStoreProvider>');
  return store;
}

/** Subscribes to a slice. The selector must return a stable value (a primitive or an existing object). */
export function useBoard<T>(selector: (state: BoardState) => T): T {
  return useStore(useBoardStore(), selector);
}

/** The actions never change identity, so components can use them without re-rendering. */
export function useBoardActions(): BoardActions {
  return useBoardStore().getState();
}

/**
 * Keeps a press inside a card's text or controls from dragging the card (the user's turn-9 request 1; risk R5 in
 * docs/m1-plan.md section 12).
 *
 * CSS cannot do this in Chrome: when a press inside a `draggable="true"` element moves, Chromium looks for the drag
 * source by walking up from the pressed node to the nearest draggable ancestor, skipping descendants marked
 * `draggable="false"` or `-webkit-user-drag: none`, so the card is dragged and no text gets selected. That search
 * happens when the pointer starts moving, after `pointerdown`. So on `pointerdown` inside a no-drag zone the card's
 * own `draggable` attribute is switched off, and switched back on at `pointerup` / `pointercancel` / window blur.
 * pragmatic-drag-and-drop sets the attribute once when the card registers and never reads it back, so the toggle is
 * safe; `blocked()` additionally feeds its `canDrag`, in case a drag starts anyway.
 */

/** Where a press must select text or operate a control instead of dragging the card. */
export const NO_DRAG_SELECTOR = '.tl-lean, input, textarea, select, button, a[href], [contenteditable], [data-nodrag]';

export interface CardDragGuard {
  /** A press that started in a no-drag zone is still down. */
  blocked(): boolean;
  dispose(): void;
}

export function guardCardDrag(card: HTMLElement): CardDragGuard {
  let blocked = false;
  let unlisten: (() => void) | null = null;

  const release = () => {
    if (!blocked) return;
    blocked = false;
    card.setAttribute('draggable', 'true');
    unlisten?.();
    unlisten = null;
  };

  const onPointerDown = (event: PointerEvent) => {
    const target = event.target;
    if (!(target instanceof Element)) return;
    const zone = target.closest(NO_DRAG_SELECTOR);
    if (!zone || zone === card || !card.contains(zone)) return;
    release(); // a second press before the first one was released (should not happen; be safe)
    blocked = true;
    card.setAttribute('draggable', 'false');
    const view = card.ownerDocument.defaultView ?? window;
    view.addEventListener('pointerup', release, true);
    view.addEventListener('pointercancel', release, true);
    view.addEventListener('blur', release);
    unlisten = () => {
      view.removeEventListener('pointerup', release, true);
      view.removeEventListener('pointercancel', release, true);
      view.removeEventListener('blur', release);
    };
  };

  card.addEventListener('pointerdown', onPointerDown, true);
  return {
    blocked: () => blocked,
    dispose: () => {
      card.removeEventListener('pointerdown', onPointerDown, true);
      unlisten?.();
      unlisten = null;
      blocked = false;
    },
  };
}

/**
 * Scrolling helpers that move only the column an element is in (`scrollIntoView` could also scroll the page or the
 * other columns, which would break the board's independent scrolling).
 */

/** Scrolls `element`'s column list so the element is fully visible (with a small margin), if it is not already. */
export function revealInColumn(element: HTMLElement, margin = 8): void {
  const list = element.closest<HTMLElement>('.tl-col__list');
  if (!list) return;
  const box = element.getBoundingClientRect();
  const view = list.getBoundingClientRect();
  const top = box.top - view.top - list.clientTop + list.scrollTop;
  const bottom = top + box.height;
  const height = list.clientHeight;
  if (box.height + 2 * margin >= height) list.scrollTop = Math.max(0, top - margin);
  else if (top - margin < list.scrollTop) list.scrollTop = Math.max(0, top - margin);
  else if (bottom + margin > list.scrollTop + height) list.scrollTop = bottom + margin - height;
}

/** Reveals the card with this id, after React has rendered it. */
export function revealCardSoon(id: string): void {
  requestAnimationFrame(() => {
    const card = document.querySelector<HTMLElement>(`[data-node-id="${CSS.escape(id)}"]`);
    if (card) revealInColumn(card);
  });
}

/**
 * Dropdowns and tooltips, rendered into document.body so a column's scroll box never clips them and the edge
 * engine's observers on the columns never see them. Positioned with the CSSOM (`style.setProperty`), which the
 * board's CSP allows; style attributes are not used.
 */
import { useLayoutEffect, useRef, type ReactNode } from 'react';
import { createPortal } from 'react-dom';

export interface PopoverProps {
  /** The element the popover hangs from; nothing renders without one. */
  anchor: HTMLElement | null;
  open: boolean;
  /** Called on Escape, a press outside, a scroll outside, or a resize (not for tooltips). */
  onClose?: () => void;
  /** Tooltips ignore the pointer and close only when their owner says so. */
  tooltip?: boolean;
  /** Which edge of the anchor the popover aligns with. */
  align?: 'start' | 'end';
  className?: string;
  role?: string;
  label?: string;
  testId?: string;
  children: ReactNode;
}

const GAP = 4;
const MARGIN = 8;

/** Places `element` below `anchor` (above when there is no room), inside the viewport. */
function place(element: HTMLElement, anchor: HTMLElement, align: 'start' | 'end'): void {
  const a = anchor.getBoundingClientRect();
  const width = element.offsetWidth;
  const height = element.offsetHeight;
  const vw = document.documentElement.clientWidth;
  const vh = document.documentElement.clientHeight;
  let left = align === 'end' ? a.right - width : a.left;
  left = Math.max(MARGIN, Math.min(left, vw - width - MARGIN));
  const below = a.bottom + GAP;
  const above = a.top - GAP - height;
  const top = below + height <= vh - MARGIN || above < MARGIN ? below : above;
  element.style.setProperty('left', `${Math.round(left)}px`);
  element.style.setProperty('top', `${Math.round(Math.max(MARGIN, top))}px`);
  element.style.setProperty('max-height', `${Math.max(80, Math.round(vh - Math.max(MARGIN, top) - MARGIN))}px`);
}

export function Popover({ anchor, open, onClose, tooltip = false, align = 'start', className, role, label, testId, children }: PopoverProps) {
  const ref = useRef<HTMLDivElement>(null);
  const closeRef = useRef(onClose);
  closeRef.current = onClose;

  useLayoutEffect(() => {
    const element = ref.current;
    if (!open || !element || !anchor) return;
    place(element, anchor, align);
    if (tooltip) return;
    const close = () => closeRef.current?.();
    const inside = (target: EventTarget | null) => target instanceof Node && (element.contains(target) || anchor.contains(target));
    const onPointerDown = (event: PointerEvent) => {
      if (!inside(event.target)) close();
    };
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key !== 'Escape') return;
      event.stopPropagation();
      close();
      if (element.contains(document.activeElement)) anchor.focus();
    };
    const onScroll = (event: Event) => {
      if (!inside(event.target)) close();
    };
    document.addEventListener('pointerdown', onPointerDown, true);
    document.addEventListener('keydown', onKeyDown, true);
    document.addEventListener('scroll', onScroll, true);
    window.addEventListener('resize', close);
    return () => {
      document.removeEventListener('pointerdown', onPointerDown, true);
      document.removeEventListener('keydown', onKeyDown, true);
      document.removeEventListener('scroll', onScroll, true);
      window.removeEventListener('resize', close);
    };
  });

  if (!open || !anchor) return null;
  return createPortal(
    <div
      ref={ref}
      className={`tl-popover${tooltip ? ' tl-popover--tooltip' : ''}${className ? ` ${className}` : ''}`}
      role={role ?? (tooltip ? 'tooltip' : 'dialog')}
      aria-label={label}
      data-testid={testId}
    >
      {children}
    </div>,
    document.body,
  );
}

/**
 * A modal dialog on the native <dialog> element (focus is trapped and restored by the browser; Escape cancels).
 * Mounted only while open: showModal() on mount, close() before unmount.
 */
import { useLayoutEffect, useRef, type ReactNode } from 'react';

export interface ModalProps {
  /** Id of the dialog's heading. */
  labelledBy: string;
  testId: string;
  /** Escape, or the parent's Cancel button. */
  onCancel: () => void;
  className?: string;
  children: ReactNode;
}

export function Modal({ labelledBy, testId, onCancel, className, children }: ModalProps) {
  const ref = useRef<HTMLDialogElement>(null);
  useLayoutEffect(() => {
    const dialog = ref.current;
    if (!dialog) return;
    if (!dialog.open) dialog.showModal();
    return () => {
      if (dialog.open) dialog.close();
    };
  }, []);
  return (
    <dialog
      ref={ref}
      className={`tl-dialog${className ? ` ${className}` : ''}`}
      aria-labelledby={labelledBy}
      data-testid={testId}
      onCancel={(event) => {
        event.preventDefault(); // React decides when the dialog goes away
        onCancel();
      }}
    >
      {children}
    </dialog>
  );
}

/**
 * Text inputs for the user's one-line wording (D-16: verbatim, one line): pasted line breaks become spaces instead
 * of being deleted (which an <input> does by default, gluing words together).
 */
import { useLayoutEffect, useRef, useState, type ClipboardEvent, type InputHTMLAttributes, type KeyboardEvent } from 'react';
import { pastedLine } from '../model/format';

/** onPaste handler: inserts the clipboard text with its line breaks turned into spaces. */
export function pasteOneLine(event: ClipboardEvent<HTMLInputElement>, setValue: (value: string) => void): void {
  const text = event.clipboardData.getData('text/plain');
  if (!/[\r\n]/.test(text)) return; // nothing to fix: let the browser paste
  event.preventDefault();
  const input = event.currentTarget;
  const start = input.selectionStart ?? input.value.length;
  const end = input.selectionEnd ?? start;
  const insert = pastedLine(text);
  setValue(input.value.slice(0, start) + insert + input.value.slice(end));
  const caret = start + insert.length;
  requestAnimationFrame(() => input.setSelectionRange(caret, caret));
}

export interface InlineEditProps extends Omit<InputHTMLAttributes<HTMLInputElement>, 'value' | 'onChange' | 'defaultValue'> {
  initial: string;
  /** Enter, or leaving the field. */
  onCommit: (value: string) => void;
  /** Escape. */
  onCancel: () => void;
}

/** An in-place editor: focused and selected on mount; Enter or blur saves, Escape cancels (each fires once). */
export function InlineEdit({ initial, onCommit, onCancel, className, ...rest }: InlineEditProps) {
  const [value, setValue] = useState(initial);
  const ref = useRef<HTMLInputElement>(null);
  const settled = useRef(false);
  useLayoutEffect(() => {
    ref.current?.focus();
    ref.current?.select();
  }, []);
  const commit = () => {
    if (settled.current) return;
    settled.current = true;
    onCommit(value);
  };
  const cancel = () => {
    if (settled.current) return;
    settled.current = true;
    onCancel();
  };
  const onKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter') {
      event.preventDefault();
      commit();
    } else if (event.key === 'Escape') {
      event.preventDefault();
      event.stopPropagation();
      cancel();
    }
  };
  return (
    <input
      {...rest}
      ref={ref}
      type="text"
      className={`tl-edit${className ? ` ${className}` : ''}`}
      value={value}
      onChange={(event) => setValue(event.target.value)}
      onPaste={(event) => pasteOneLine(event, setValue)}
      onKeyDown={onKeyDown}
      onBlur={commit}
      onClick={(event) => event.stopPropagation()}
    />
  );
}

import { draggable, dropTargetForElements } from '@atlaskit/pragmatic-drag-and-drop/adapter/element-adapter';
import { combine } from '@atlaskit/pragmatic-drag-and-drop/utils/combine';
import { attachClosestEdge } from '@atlaskit/pragmatic-drag-and-drop-hitbox/closest-edge/attach-closest-edge';
import { extractClosestEdge } from '@atlaskit/pragmatic-drag-and-drop-hitbox/closest-edge/extract-closest-edge';
import type { Edge } from '@atlaskit/pragmatic-drag-and-drop-hitbox/types';
import { memo, useEffect, useLayoutEffect, useMemo, useRef, useState, type KeyboardEvent, type MouseEvent } from 'react';
import { InlineEdit } from '../common/OneLineInput';
import { KIND_GLYPH, KIND_NOUN } from '../labels';
import { attentionDiagnostics, cardChips, type Chip } from '../model/cardData';
import { useBoard, useBoardActions } from '../state/context';
import { flashTarget } from '../state/store';
import { CardDetails } from './CardDetails';
import { cardDragData, cardTargetData, isCardDragData } from './dnd';
import { guardCardDrag } from './dragGuard';
import { revealInColumn } from './reveal';
import { UsesLine } from './UsesLine';

function ChipView({ chip, onAction }: { chip: Chip; onAction: (action: NonNullable<Chip['action']>) => void }) {
  const className = `tl-chip tl-chip--${chip.tone}${chip.tone === 'attention' ? ' tl-chip--attention' : ''}${chip.action ? ' tl-chip--action' : ''}`;
  if (chip.action) {
    const action = chip.action;
    return (
      <button
        type="button"
        className={className}
        data-chip={chip.key}
        data-dim={chip.dim || undefined}
        title={chip.title}
        onClick={(event) => {
          event.stopPropagation();
          onAction(action);
        }}
      >
        {chip.label}
      </button>
    );
  }
  return (
    <span className={className} data-chip={chip.key} data-dim={chip.dim || undefined} title={chip.title}>
      {chip.label}
    </span>
  );
}

export const NodeCard = memo(function NodeCard({ id }: { id: string }) {
  const node = useBoard((s) => s.nodes[id]);
  const nodes = useBoard((s) => s.nodes);
  const diagnostics = useBoard((s) => s.diagnostics);
  const selected = useBoard((s) => s.selected.includes(id));
  const expanded = useBoard((s) => s.expanded[id] === true);
  const dragging = useBoard((s) => s.drag?.id === id);
  const provisional = useBoard((s) => s.provisional[id] === true);
  const flashed = useBoard((s) => (s.flash?.target === flashTarget.node(id) ? s.flash.token : 0));
  const editing = useBoard((s) => (s.editing?.id === id ? s.editing.field : null));
  const actions = useBoardActions();
  const ref = useRef<HTMLDivElement>(null);
  const [dropEdge, setDropEdge] = useState<Edge | null>(null);

  useEffect(() => {
    const element = ref.current;
    if (!element) return;
    const guard = guardCardDrag(element);
    return combine(
      () => guard.dispose(),
      draggable({
        element,
        getInitialData: () => cardDragData(id),
        // A press in the code, a field or a button never drags the card (request 1); neither does a card the host
        // has not confirmed yet.
        canDrag: () => !guard.blocked() && !actions.isProvisional(id),
      }),
      dropTargetForElements({
        element,
        // The card itself is a target too, so dropping it where it was is recognised as "no move".
        canDrop: ({ source }) => isCardDragData(source.data),
        getData: ({ input, element: el }) => attachClosestEdge(cardTargetData(id), { input, element: el, allowedEdges: ['top', 'bottom'] }),
        onDrag: ({ self, source }) => {
          const edge = isCardDragData(source.data) && source.data.id !== id ? extractClosestEdge(self.data) : null;
          setDropEdge((current) => (current === edge ? current : edge));
        },
        onDragLeave: () => setDropEdge(null),
        onDrop: () => setDropEdge(null),
      }),
    );
  }, [id, actions]);

  useLayoutEffect(() => {
    if (flashed && ref.current) revealInColumn(ref.current);
  }, [flashed]);

  const chips = useMemo(() => (node ? cardChips(node, nodes) : []), [node, nodes]);
  const attention = useMemo(() => attentionDiagnostics(diagnostics, id), [diagnostics, id]);

  if (!node) return null;
  const agentWorded = node.provenance.wordedBy === 'agent';

  const onChipAction = (action: NonNullable<Chip['action']>) => {
    if (action === 'make-derivation') actions.requestKindChange(id, 'DERIVATION', null);
    else actions.startEdit(id, 'rationale');
  };
  const onClick = (event: MouseEvent) => actions.clickCard(id, event.ctrlKey || event.metaKey);
  const onKeyDown = (event: KeyboardEvent) => {
    if (event.target !== event.currentTarget) return;
    if (event.key === 'Enter') {
      event.preventDefault();
      actions.toggleExpanded(id);
    } else if (event.key === ' ') {
      event.preventDefault();
      actions.clickCard(id, true);
    } else if (event.key === 'F2') {
      event.preventDefault();
      actions.startEdit(id, 'naturalName');
    } else if (event.key === 'Delete') {
      event.preventDefault();
      actions.openDelete(id);
    }
  };
  const problems = attention.length;

  return (
    <div
      ref={ref}
      className="tl-card"
      role="listitem"
      tabIndex={0}
      data-node-id={id}
      data-kind={node.type}
      data-formal={node.status.formal}
      data-selected={selected || undefined}
      data-dragging={dragging || undefined}
      data-drop-edge={dropEdge ?? undefined}
      data-provisional={provisional || undefined}
      data-highlight={flashed ? 'true' : undefined}
      aria-label={`${KIND_NOUN[node.type]}: ${node.naturalName}${selected ? ' (selected)' : ''}`}
      onClick={onClick}
      onKeyDown={onKeyDown}
      onMouseEnter={() => actions.setHover(id)}
      onMouseLeave={() => actions.setHover(null)}
    >
      <div className="tl-card__row">
        {editing === 'naturalName' ? (
          <InlineEdit
            initial={node.naturalName}
            aria-label="Edit the sentence"
            onCommit={(value) => {
              actions.stopEdit();
              actions.editNode(id, 'naturalName', value);
            }}
            onCancel={() => actions.stopEdit()}
          />
        ) : (
          <span className={agentWorded ? 'tl-card__text tl-card__text--agent' : 'tl-card__text'}>
            {node.naturalName}
            {agentWorded ? <span className="tl-card__agent-marker"> (Claude's wording)</span> : null}
          </span>
        )}
        {selected ? <span className="codicon codicon-check tl-card__check" title="Selected" aria-hidden="true" /> : null}
        <span className="tl-glyph" data-kind={node.type} title={KIND_NOUN[node.type]}>
          {KIND_GLYPH[node.type]}
        </span>
        <button
          type="button"
          className="tl-card__chevron"
          aria-expanded={expanded}
          aria-label={expanded ? 'Hide details' : 'Show Lean code and details'}
          onClick={(event) => {
            event.stopPropagation();
            actions.toggleExpanded(id);
          }}
        >
          <span className={`codicon codicon-chevron-${expanded ? 'down' : 'right'}`} aria-hidden="true" />
        </button>
      </div>
      {editing === 'rationale' ? (
        <div className="tl-card__because tl-card__because--editing">
          <span>because:</span>
          <InlineEdit
            initial={node.rationale ?? ''}
            aria-label="Edit the reason"
            placeholder="Leave empty to remove the reason"
            onCommit={(value) => {
              actions.stopEdit();
              actions.editNode(id, 'rationale', value);
            }}
            onCancel={() => actions.stopEdit()}
          />
        </div>
      ) : node.rationale ? (
        <div className="tl-card__because">because: {node.rationale}</div>
      ) : null}
      <div className="tl-card__meta">
        {chips.map((chip) => (
          <ChipView key={chip.key} chip={chip} onAction={onChipAction} />
        ))}
        {problems > 0 ? (
          <button
            type="button"
            className="tl-attention"
            data-testid="attention"
            title={attention.map((d) => `${d.code}: ${d.message}`).join('\n')}
            aria-label={`${problems} problem${problems === 1 ? '' : 's'} need${problems === 1 ? 's' : ''} attention`}
            onClick={(event) => {
              event.stopPropagation();
              actions.setExpanded(id, true);
            }}
          >
            <span className="codicon codicon-warning" aria-hidden="true" />
            {problems}
          </button>
        ) : null}
        {provisional ? (
          <span className="tl-chip tl-chip--subtle" data-chip="provisional" title="Waiting for the extension to write this card">
            saving…
          </span>
        ) : null}
      </div>
      {node.lean.uses ? <UsesLine node={node} /> : null}
      {expanded ? <CardDetails node={node} /> : null}
    </div>
  );
});

input.old_string:
  pushToast(level: NoticeLevel, text: string, undoable?: boolean): void;
  dismissToast(key: number): void;
}

input.new_string:
  pushToast(level: NoticeLevel, text: string, undoable?: boolean): void;
  dismissToast(key: number): void;
  /** Whether a card is an add the host has not confirmed yet (read at drag start, not subscribed). */
  isProvisional(id: string): boolean;
}

input.old_string:
  dismissToast(key) {
    const toasts = get().toasts;
    if (toasts.some((t) => t.key === key)) set({ toasts: toasts.filter((t) => t.key !== key) });
  },
};

input.new_string:
  dismissToast(key) {
    const toasts = get().toasts;
    if (toasts.some((t) => t.key === key)) set({ toasts: toasts.filter((t) => t.key !== key) });
  },

  isProvisional(id) {
    return get().provisional[id] === true;
  },
};

input.content:
/**
 * The "uses:" line of a formalised card (the user's turn-9 request 2): the vocabulary its Lean statement uses,
 * computed from Lean (`lean.uses`), truncated inline after two names ("HasDarkPast, cynder, …"), with a "▾ N"
 * dropdown that lists every item with its kind and gloss. Choosing one highlights it in the Vocabulary group.
 */
import type { TlNode } from '@telelean/core';
import { useState } from 'react';
import { Popover } from '../common/Popover';
import { VOCAB_KIND_NOUN } from '../labels';
import { displayName, usesInline } from '../model/cardData';
import { useBoard, useBoardActions } from '../state/context';

export function UsesLine({ node }: { node: TlNode }) {
  const subject = useBoard((s) => s.subject);
  const vocab = useBoard((s) => s.vocab);
  const actions = useBoardActions();
  const [anchor, setAnchor] = useState<HTMLElement | null>(null);
  const uses = node.lean.uses ?? [];
  if (uses.length === 0) return null;
  const close = () => setAnchor(null);

  return (
    <div className="tl-uses" data-testid="uses">
      <span className="tl-uses__text" title={uses.map((name) => displayName(name, subject, vocab)).join(', ')}>
        {`uses: ${usesInline(uses, subject, vocab)}`}
      </span>
      <button
        type="button"
        className="tl-uses__toggle"
        aria-haspopup="menu"
        aria-expanded={anchor !== null}
        aria-label={`All ${uses.length} vocabulary items this card uses`}
        onClick={(event) => {
          event.stopPropagation();
          setAnchor(anchor ? null : event.currentTarget);
        }}
      >
        {`▾ ${uses.length}`}
      </button>
      <Popover anchor={anchor} open={anchor !== null} onClose={close} role="menu" label="Vocabulary this card uses" testId="uses-menu" className="tl-menu">
        {uses.map((name) => {
          const item = vocab.get(name);
          return (
            <button
              key={name}
              type="button"
              role="menuitem"
              className="tl-menu__item tl-uses__entry"
              data-vocab={name}
              disabled={!item}
              title={item ? `Show ${item.shortName} in the Vocabulary group` : `${name} is not in this subject's vocabulary`}
              onClick={() => {
                close();
                actions.highlightVocab(name);
              }}
            >
              <span className="tl-uses__name">{displayName(name, subject, vocab)}</span>
              <span className="tl-uses__kind">{item ? VOCAB_KIND_NOUN[item.kind] : 'elsewhere'}</span>
              {item?.gloss ? (
                <span className={item.glossBy === 'agent' ? 'tl-uses__gloss tl-gloss--agent' : 'tl-uses__gloss'}>{item.gloss}</span>
              ) : null}
            </button>
          );
        })}
      </Popover>
    </div>
  );
}

/**
 * A card's Lean code, expanded (the user's turn-9 requests 1, 3 and 4):
 *  - a press-and-drag selects text and never drags the card (the card's drag guard handles `.tl-lean`; see
 *    dragGuard.ts), and clicks in the code never change the board's selection;
 *  - identifiers Lean resolved (`lean.refs`) are spans: hovering shows the vocabulary item's gloss or the node's
 *    sentence; a plain click highlights the item in the Vocabulary group or reveals that node's card;
 *    Ctrl/Cmd+click is reserved (go to definition / editing later) and does nothing yet;
 *  - "Copy" posts exactly `lean.code` to the host's clipboard; "Open in editor" opens where the code starts.
 */
import type { LeanRef, TlNode } from '@telelean/core';
import { Fragment, useEffect, useMemo, useState, type MouseEvent } from 'react';
import { Popover } from '../common/Popover';
import { VOCAB_KIND_NOUN } from '../labels';
import { codeSegments, displayName } from '../model/cardData';
import { useBoard, useBoardActions } from '../state/context';

interface Tip {
  anchor: HTMLElement;
  ref: LeanRef;
}

function refOf(target: EventTarget | null, refs: readonly LeanRef[]): { span: HTMLElement; ref: LeanRef } | null {
  if (!(target instanceof Element)) return null;
  const span = target.closest<HTMLElement>('.tl-ref');
  const index = Number(span?.dataset.refIndex);
  const ref = Number.isInteger(index) ? refs[index] : undefined;
  return span && ref ? { span, ref } : null;
}

/** What hovering an identifier says: the node's sentence, or the vocabulary item's gloss with its kind and type. */
function RefTip({ leanRef }: { leanRef: LeanRef }) {
  const node = useBoard((s) => (leanRef.nodeId ? s.nodes[leanRef.nodeId] : undefined));
  const item = useBoard((s) => s.vocab.get(leanRef.name));
  const subject = useBoard((s) => s.subject);
  const vocab = useBoard((s) => s.vocab);
  if (node) {
    return (
      <>
        <span className="tl-tip__main">{node.naturalName}</span>
        <span className="tl-tip__meta">{leanRef.name}</span>
      </>
    );
  }
  if (item) {
    return (
      <>
        <span className={item.glossBy === 'agent' ? 'tl-tip__main tl-gloss--agent' : 'tl-tip__main'}>{item.gloss ?? item.shortName}</span>
        <span className="tl-tip__meta">
          {VOCAB_KIND_NOUN[item.kind]} · <code>{displayName(item.name, subject, vocab)}{item.type ? ` : ${item.type}` : ''}</code>
        </span>
      </>
    );
  }
  return <code className="tl-tip__main">{leanRef.name}</code>;
}

export function LeanCode({ node }: { node: TlNode }) {
  const actions = useBoardActions();
  const code = node.lean.code ?? '';
  const refs = useMemo(() => node.lean.refs ?? [], [node.lean.refs]);
  const lines = useMemo(() => codeSegments(code, refs), [code, refs]);
  const [tip, setTip] = useState<Tip | null>(null);
  const [copied, setCopied] = useState(false);
  const location = node.lean.codeLoc ?? (node.loc ? { file: node.loc.file, range: node.loc.range } : undefined);

  useEffect(() => {
    if (!copied) return;
    const timer = setTimeout(() => setCopied(false), 1500);
    return () => clearTimeout(timer);
  }, [copied]);

  const onClick = (event: MouseEvent<HTMLPreElement>) => {
    // Never a card click: no selection change, no expand/collapse.
    event.stopPropagation();
    const selection = window.getSelection();
    if (selection && !selection.isCollapsed && event.currentTarget.contains(selection.anchorNode)) return; // ends a text selection
    if (event.ctrlKey || event.metaKey) return; // reserved (go to definition, editing: later milestones)
    const hit = refOf(event.target, refs);
    if (!hit) return;
    if (hit.ref.nodeId) actions.revealNode(hit.ref.nodeId);
    else actions.highlightVocab(hit.ref.name);
  };

  const onMouseOver = (event: MouseEvent<HTMLPreElement>) => {
    const hit = refOf(event.target, refs);
    if (!hit) return;
    setTip((current) => (current?.anchor === hit.span ? current : { anchor: hit.span, ref: hit.ref }));
  };

  const onMouseOut = (event: MouseEvent<HTMLPreElement>) => {
    const from = refOf(event.target, refs);
    if (!from) return;
    const to = event.relatedTarget instanceof Node ? event.relatedTarget : null;
    if (to && from.span.contains(to)) return;
    setTip((current) => (current?.anchor === from.span ? null : current));
  };

  return (
    <div className="tl-leanbox">
      <div className="tl-leanbox__bar">
        <span className="tl-leanbox__title">Lean</span>
        <button
          type="button"
          className="tl-icon-button"
          aria-label="Copy the Lean code"
          title="Copy the Lean code to the clipboard"
          onClick={(event) => {
            event.stopPropagation();
            if (actions.copyText(code)) setCopied(true);
          }}
        >
          <span className={`codicon codicon-${copied ? 'check' : 'copy'}`} aria-hidden="true" />
          <span aria-live="polite">{copied ? 'Copied' : 'Copy'}</span>
        </button>
        {location ? (
          <button
            type="button"
            className="tl-icon-button"
            title={`Open ${location.file} at line ${location.range.start.line + 1}`}
            onClick={(event) => {
              event.stopPropagation();
              actions.openInEditor(location.file, location.range);
            }}
          >
            <span className="codicon codicon-go-to-file" aria-hidden="true" />
            Open in editor
          </button>
        ) : null}
      </div>
      <pre className="tl-lean" data-testid="lean-code" draggable={false} onClick={onClick} onMouseOver={onMouseOver} onMouseOut={onMouseOut}>
        <code>
          {lines.map((segments, line) => (
            <Fragment key={line}>
              {line > 0 ? '\n' : null}
              {segments.map((segment, i) =>
                segment.ref ? (
                  <span
                    key={i}
                    className="tl-ref"
                    data-ref={segment.ref.name}
                    data-ref-node={segment.ref.nodeId}
                    data-ref-index={refs.indexOf(segment.ref)}
                  >
                    {segment.text}
                  </span>
                ) : (
                  <Fragment key={i}>{segment.text}</Fragment>
                ),
              )}
            </Fragment>
          ))}
        </code>
      </pre>
      <Popover anchor={tip?.anchor ?? null} open={tip !== null} tooltip testId="ref-tooltip" className="tl-tip">
        {tip ? <RefTip leanRef={tip.ref} /> : null}
      </Popover>
    </div>
  );
}

/**
 * The expanded part of a card (03 section 7 "Expanded"): the Lean code, the node's problems, its footprint and
 * presuppositions, "Depends on / Used by" (also the keyboard and screen-reader route through the graph), the
 * stance and source chips, and the keyboard equivalents of the gestures (Make <kind>, Edit, Delete).
 *
 * Presses here never drag the card and clicks never change the selection: the card face is the handle.
 */
import { EVIDENTIALS, NODE_TYPES, STANCES, type BoardDiagnostic, type TlNode } from '@telelean/core';
import { useMemo, type MouseEvent } from 'react';
import { KIND_GLYPH, KIND_NOUN, SOURCE_LABEL, STANCE_LABEL } from '../labels';
import { dependsOn, footprintEntries, presuppositionLabel, RELATION_TEXT, usedBy, type Relation } from '../model/cardData';
import { useBoard, useBoardActions } from '../state/context';
import { impactOf } from '../state/store';
import { LeanCode } from './LeanCode';

const stop = (event: MouseEvent) => event.stopPropagation();

function NodeButton({ id }: { id: string }) {
  const node = useBoard((s) => s.nodes[id]);
  const actions = useBoardActions();
  if (!node) return <code>{id}</code>;
  return (
    <button type="button" className="tl-rel" data-rel-id={id} title="Show this card" onClick={() => actions.revealNode(id)}>
      <span className="tl-glyph" data-kind={node.type} aria-hidden="true">
        {KIND_GLYPH[node.type]}
      </span>
      <span className="tl-rel__text">{node.naturalName}</span>
    </button>
  );
}

function Relations({ title, testId, relations, empty }: { title: string; testId: string; relations: Relation[]; empty: string }) {
  return (
    <section className="tl-details__section" data-testid={testId}>
      <h4 className="tl-details__heading">{title}</h4>
      {relations.length === 0 ? (
        <p className="tl-details__none">{empty}</p>
      ) : (
        <ul className="tl-details__list">
          {relations.map((relation) => (
            <li key={relation.id} className="tl-details__rel">
              <NodeButton id={relation.id} />
              <span className="tl-rel__why">{relation.reasons.map((r) => RELATION_TEXT[r]).join(', ')}</span>
            </li>
          ))}
        </ul>
      )}
    </section>
  );
}

function Problems({ diagnostics }: { diagnostics: readonly BoardDiagnostic[] }) {
  const actions = useBoardActions();
  if (diagnostics.length === 0) return null;
  return (
    <section className="tl-details__section" data-testid="card-problems">
      <h4 className="tl-details__heading">Problems</h4>
      <ul className="tl-details__list">
        {diagnostics.map((d, i) => (
          <li key={i} className="tl-problem" data-severity={d.severity}>
            <span className={`codicon codicon-${d.severity === 'error' ? 'error' : d.severity === 'warning' ? 'warning' : 'info'}`} aria-hidden="true" />
            <span className="tl-problem__text">
              <code>{d.code}</code> {d.message}
            </span>
            {d.file ? (
              <button type="button" className="tl-icon-button" onClick={() => actions.openInEditor(d.file ?? '', d.range)}>
                Open
              </button>
            ) : null}
          </li>
        ))}
      </ul>
    </section>
  );
}

function Proof({ node }: { node: TlNode }) {
  const nodes = useBoard((s) => s.nodes);
  const vocab = useBoard((s) => s.vocab);
  const subject = useBoard((s) => s.subject);
  const actions = useBoardActions();
  const proof = node.status.proof;
  const footprint = proof.kind === 'proved' ? proof.footprint : proof.kind === 'conditional' ? (proof.footprint ?? []) : null;
  const entries = footprint ? footprintEntries(footprint, nodes, subject, vocab) : [];
  const presupposes = node.lean.presupposes ?? [];
  const axioms = node.lean.axioms ?? [];
  if (!footprint && proof.kind !== 'conditional' && presupposes.length === 0 && axioms.length === 0) return null;
  return (
    <section className="tl-details__section" data-testid="footprint">
      {proof.kind === 'conditional' ? (
        <>
          <h4 className="tl-details__heading">Taken as hypotheses (unproved)</h4>
          <ul className="tl-details__list">
            {proof.on.map((id) => (
              <li key={id}>
                <NodeButton id={id} />
              </li>
            ))}
          </ul>
        </>
      ) : null}
      {footprint ? (
        <>
          <h4 className="tl-details__heading">Rests on</h4>
          {entries.length === 0 ? <p className="tl-details__none">No assumptions at all.</p> : null}
          <ul className="tl-details__list">
            {entries.map((entry, i) => (
              <li key={i}>
                {entry.kind === 'node' ? (
                  <NodeButton id={entry.id} />
                ) : entry.kind === 'presupposition' ? (
                  <button type="button" className="tl-presup" data-presup={entry.name} title={entry.name} onClick={() => actions.highlightVocab(entry.name)}>
                    {entry.label}
                  </button>
                ) : entry.kind === 'axiom' ? (
                  <span className="tl-chip tl-chip--attention" title="An axiom that is neither one of your assumptions nor vocabulary (TL103)">
                    axiom <code>{entry.name}</code>
                  </span>
                ) : (
                  <code>{entry.name}</code>
                )}
              </li>
            ))}
          </ul>
        </>
      ) : null}
      {presupposes.length > 0 ? (
        <div data-testid="presuppositions">
          <h4 className="tl-details__heading">Presupposes</h4>
          <div className="tl-details__chips">
            {presupposes.map((name) => (
              <button key={name} type="button" className="tl-presup" data-presup={name} title={name} onClick={() => actions.highlightVocab(name)}>
                {presuppositionLabel(name, subject, vocab)}
              </button>
            ))}
          </div>
        </div>
      ) : null}
      {axioms.length > 0 ? (
        <details className="tl-details__axioms">
          <summary>Lean's axiom list ({axioms.length})</summary>
          <code>{axioms.join(', ')}</code>
        </details>
      ) : null}
    </section>
  );
}

function Choices({ node }: { node: TlNode }) {
  const actions = useBoardActions();
  const showStance = node.type === 'ASSUMPTION' || node.stance !== undefined;
  const showSource = node.type !== 'GOAL' || node.source !== undefined;
  if (!showStance && !showSource) return null;
  return (
    <section className="tl-details__section">
      {showStance ? (
        <div className="tl-details__chips" role="group" aria-label="Stance" data-testid="stance-chips">
          {STANCES.map((stance) => (
            <button
              key={stance}
              type="button"
              className="tl-choice"
              aria-pressed={node.stance === stance}
              onClick={() => actions.editNode(node.id, 'stance', node.stance === stance ? null : stance)}
            >
              {STANCE_LABEL[stance]}
            </button>
          ))}
        </div>
      ) : null}
      {showSource ? (
        <div className="tl-details__chips" role="group" aria-label="Source" data-testid="source-chips">
          <span className="tl-details__label">source:</span>
          {EVIDENTIALS.map((source) => (
            <button
              key={source}
              type="button"
              className="tl-choice"
              aria-pressed={node.source === source}
              onClick={() => actions.editNode(node.id, 'source', node.source === source ? null : source)}
            >
              {SOURCE_LABEL[source]}
            </button>
          ))}
        </div>
      ) : null}
    </section>
  );
}

function Actions({ node }: { node: TlNode }) {
  const actions = useBoardActions();
  const state = useBoard((s) => s);
  const provisional = state.provisional[node.id] === true;
  return (
    <div className="tl-details__actions">
      {NODE_TYPES.filter((kind) => kind !== node.type).map((kind) => {
        const impact = impactOf(state, node.id, kind);
        return (
          <button
            key={kind}
            type="button"
            className="tl-button tl-button--secondary tl-button--small"
            disabled={provisional}
            title={impact ? `${impact.summary}. ${impact.detail}` : undefined}
            onClick={() => actions.requestKindChange(node.id, kind, null)}
          >
            Make {KIND_NOUN[kind]}
          </button>
        );
      })}
      <span className="tl-details__spacer" />
      <button type="button" className="tl-button tl-button--secondary tl-button--small" disabled={provisional} onClick={() => actions.startEdit(node.id, 'naturalName')}>
        Edit
      </button>
      <button type="button" className="tl-button tl-button--secondary tl-button--small" disabled={provisional} onClick={() => actions.startEdit(node.id, 'rationale')}>
        {node.rationale ? 'Edit why' : 'Add why'}
      </button>
      <button type="button" className="tl-button tl-button--secondary tl-button--small tl-button--danger" disabled={provisional} onClick={() => actions.openDelete(node.id)}>
        Delete
      </button>
    </div>
  );
}

export function CardDetails({ node }: { node: TlNode }) {
  const edges = useBoard((s) => s.edges);
  const nodes = useBoard((s) => s.nodes);
  const order = useBoard((s) => s.order);
  const diagnostics = useBoard((s) => s.diagnostics);
  const actions = useBoardActions();
  const ctx = useMemo(() => ({ edges, nodes, order }), [edges, nodes, order]);
  const depends = useMemo(() => dependsOn(node.id, ctx), [node.id, ctx]);
  const users = useMemo(() => usedBy(node.id, ctx), [node.id, ctx]);
  const problems = useMemo(() => diagnostics.filter((d) => d.nodeId === node.id), [diagnostics, node.id]);
  const location = node.loc;

  return (
    <div className="tl-details" data-nodrag onClick={stop}>
      {node.lean.code ? (
        <LeanCode node={node} />
      ) : (
        <div className="tl-leanbox tl-leanbox--empty">
          <p className="tl-lean--empty" data-testid="lean-code">
            No Lean code yet: this node is a comment-only <code>@@ telelean</code> block.
          </p>
          {location ? (
            <button type="button" className="tl-icon-button" onClick={() => actions.openInEditor(location.file, location.range)}>
              <span className="codicon codicon-go-to-file" aria-hidden="true" />
              Open in editor
            </button>
          ) : null}
        </div>
      )}
      <Problems diagnostics={problems} />
      <Proof node={node} />
      <div className="tl-details__relations">
        <Relations title="Depends on" testId="depends-on" relations={depends} empty="Nothing: no declared premises and no proof." />
        <Relations title="Used by" testId="used-by" relations={users} empty="Nothing uses it yet." />
      </div>
      <Choices node={node} />
      <Actions node={node} />
    </div>
  );
}

