/**
 * The computed Vocabulary group at the top of the Assumptions column (D-3): box-shaped items grouped by kind, the
 * presuppositions as chips ("assumes characters exist"), hidden assumptions flagged. Collapsible; the state lives
 * in the webview state (per board), never in a model file. Items can be highlighted (scrolled into view within the
 * column and flashed) from a card's "uses:" dropdown or an identifier in its Lean code.
 */
import type { VocabItem } from '@telelean/core';
import { memo, useLayoutEffect, useMemo, useRef, useState } from 'react';
import { KIND_GLYPH, VOCAB_SECTIONS } from '../labels';
import { presuppositionLabel } from '../model/cardData';
import { useBoard, useBoardActions } from '../state/context';
import { flashTarget } from '../state/store';
import { revealInColumn } from './reveal';

const FLAG_TEXT: Readonly<Record<VocabItem['flags'][number], { label: string; title: string; warn: boolean }>> = {
  'unmarked-assumption': { label: 'hidden assumption', title: 'A Prop-valued axiom with no card: Lean takes it as given (TL104)', warn: true },
  'shape-violation': { label: 'shape', title: 'Breaks the simple vocabulary rule (TL111)', warn: true },
  'definitional-choice': { label: 'definition on a statement path', title: 'A definition your statements rely on (D-4: needs your endorsement)', warn: false },
  stale: { label: 'checking…', title: 'Its file changed since Lean last checked it', warn: false },
  new: { label: 'new', title: 'Added by a proposal', warn: false },
};

/** The `data-highlight` flash token for an item (0 when not flashed); scrolls the item into view when flashed. */
function useFlash(name: string, element: React.RefObject<HTMLElement | null>): number {
  const flashed = useBoard((s) => (s.flash?.target === flashTarget.vocab(name) ? s.flash.token : 0));
  useLayoutEffect(() => {
    if (flashed && element.current) revealInColumn(element.current);
  }, [flashed, element]);
  return flashed;
}

function UsedBy({ ids }: { ids: readonly string[] }) {
  const nodes = useBoard((s) => s.nodes);
  const actions = useBoardActions();
  const present = ids.filter((id) => nodes[id]);
  if (present.length === 0) return <p className="tl-details__none">No card uses it yet.</p>;
  return (
    <ul className="tl-details__list">
      {present.map((id) => {
        const node = nodes[id];
        return node ? (
          <li key={id}>
            <button type="button" className="tl-rel" data-rel-id={id} onClick={() => actions.revealNode(id)}>
              <span className="tl-glyph" data-kind={node.type} aria-hidden="true">
                {KIND_GLYPH[node.type]}
              </span>
              <span className="tl-rel__text">{node.naturalName}</span>
            </button>
          </li>
        ) : null;
      })}
    </ul>
  );
}

const VocabBox = memo(function VocabBox({ item }: { item: VocabItem }) {
  const ref = useRef<HTMLDivElement>(null);
  const flashed = useFlash(item.name, ref);
  const actions = useBoardActions();
  const [open, setOpen] = useState(false);
  const warn = item.kind === 'unmarked-axiom' || item.flags.some((f) => FLAG_TEXT[f].warn);
  return (
    <div
      ref={ref}
      className="tl-vocab__item"
      data-vocab={item.name}
      data-kind-vocab={item.kind}
      data-warn={warn || undefined}
      data-highlight={flashed ? 'true' : undefined}
    >
      <div className="tl-vocab__head">
        <span className="tl-vocab__name">{item.shortName}</span>
        {item.type ? <code className="tl-vocab__type">{item.type}</code> : null}
        <button
          type="button"
          className="tl-card__chevron"
          aria-expanded={open}
          aria-label={open ? `Hide ${item.shortName}'s code` : `Show ${item.shortName}'s code and who uses it`}
          onClick={() => setOpen(!open)}
        >
          <span className={`codicon codicon-chevron-${open ? 'down' : 'right'}`} aria-hidden="true" />
        </button>
      </div>
      {item.gloss ? (
        <div className={item.glossBy === 'agent' ? 'tl-vocab__gloss tl-gloss--agent' : 'tl-vocab__gloss'}>
          {item.gloss}
          {item.glossBy === 'agent' ? <span className="tl-card__agent-marker"> (Claude's wording)</span> : null}
        </div>
      ) : null}
      {item.flags.length > 0 ? (
        <div className="tl-card__meta">
          {item.flags.map((flag) => (
            <span key={flag} className={`tl-chip${FLAG_TEXT[flag].warn ? ' tl-chip--attention' : ''}`} title={FLAG_TEXT[flag].title}>
              {FLAG_TEXT[flag].label}
            </span>
          ))}
        </div>
      ) : null}
      {open ? (
        <div className="tl-vocab__more">
          {item.code ? <pre className="tl-lean">{item.code}</pre> : null}
          <h4 className="tl-details__heading">Used by</h4>
          <UsedBy ids={item.usedBy} />
          {item.loc ? (
            <button type="button" className="tl-icon-button" onClick={() => item.loc && actions.openInEditor(item.loc.file, item.loc.range)}>
              <span className="codicon codicon-go-to-file" aria-hidden="true" />
              Open in editor
            </button>
          ) : null}
        </div>
      ) : null}
    </div>
  );
});

const PresuppositionChip = memo(function PresuppositionChip({ item }: { item: VocabItem }) {
  const ref = useRef<HTMLSpanElement>(null);
  const flashed = useFlash(item.name, ref);
  const subject = useBoard((s) => s.subject);
  const vocab = useBoard((s) => s.vocab);
  return (
    <span
      ref={ref}
      className="tl-presup tl-vocab__presup"
      data-vocab={item.name}
      data-highlight={flashed ? 'true' : undefined}
      title={`${item.shortName} : ${item.type ?? ''}${item.gloss ? ` (${item.gloss})` : ''}`}
    >
      {presuppositionLabel(item.name, subject, vocab)}
    </span>
  );
});

export function VocabularyGroup() {
  const items = useBoard((s) => s.vocabulary);
  const collapsed = useBoard((s) => s.vocabCollapsed);
  const actions = useBoardActions();
  const sections = useMemo(
    () => VOCAB_SECTIONS.map((section) => ({ ...section, items: items.filter((item) => item.kind === section.kind) })).filter((s) => s.items.length > 0),
    [items],
  );
  if (items.length === 0) return null;
  const hidden = items.filter((item) => item.kind === 'unmarked-axiom').length;

  return (
    <section className="tl-vocab" data-testid="vocabulary" data-collapsed={collapsed || undefined} aria-label="Vocabulary">
      <button type="button" className="tl-vocab__toggle" aria-expanded={!collapsed} onClick={() => actions.toggleVocabulary()}>
        <span className={`codicon codicon-chevron-${collapsed ? 'right' : 'down'}`} aria-hidden="true" />
        <span className="tl-vocab__title">Vocabulary</span>
        <span className="tl-col__count">{items.length}</span>
        {hidden > 0 ? (
          <span className="tl-chip tl-chip--attention" title="Prop-valued axioms with no card (TL104)">
            {hidden} hidden assumption{hidden === 1 ? '' : 's'}
          </span>
        ) : null}
      </button>
      {collapsed
        ? null
        : sections.map((section) => (
            <div key={section.kind} className="tl-vocab__section" data-section={section.kind}>
              <h3 className="tl-vocab__heading">{section.title}</h3>
              {section.kind === 'presupposition' ? (
                <div className="tl-vocab__chips">
                  {section.items.map((item) => (
                    <PresuppositionChip key={item.name} item={item} />
                  ))}
                </div>
              ) : (
                <div className="tl-vocab__items">
                  {section.items.map((item) => (
                    <VocabBox key={item.name} item={item} />
                  ))}
                </div>
              )}
            </div>
          ))}
    </section>
  );
}

import { dropTargetForElements } from '@atlaskit/pragmatic-drag-and-drop/adapter/element-adapter';
import { combine } from '@atlaskit/pragmatic-drag-and-drop/utils/combine';
import { autoScrollForElements } from '@atlaskit/pragmatic-drag-and-drop-auto-scroll/element';
import type { NodeType } from '@telelean/core';
import { useCallback, useEffect, useRef } from 'react';
import { COLUMN_TITLE, KIND_GLYPH, KIND_NOUN } from '../labels';
import { useBoard } from '../state/context';
import { impactOf } from '../state/store';
import { columnTargetData, isCardDragData } from './dnd';
import { NodeCard } from './NodeCard';
import { VocabularyGroup } from './VocabularyGroup';

/** Elements the board's edge engine needs from a column: the scrolling list and the two "n linked" slots. */
export interface ColumnRefs {
  list: (element: HTMLDivElement | null) => void;
  /** In the header, above the list: the engine puts "▲ n linked" here. */
  up: (element: HTMLSpanElement | null) => void;
  /** In the footer, below the list: the engine puts "▼ n linked" here. */
  down: (element: HTMLSpanElement | null) => void;
}

/**
 * The labelled drop zone of a column during a drag to another column (D-17): what the drop would do, from
 * kindChangeImpact (D-11), e.g. "Make Derivation: promotion pending until proved". It lets the pointer through, so
 * the drop still lands on the card or list underneath.
 */
function DropZone({ kind, active }: { kind: NodeType; active: boolean }) {
  const summary = useBoard((s) => (s.drag ? (impactOf(s, s.drag.id, kind)?.summary ?? null) : null));
  const detail = useBoard((s) => (s.drag ? (impactOf(s, s.drag.id, kind)?.detail ?? null) : null));
  const confirm = useBoard((s) => (s.drag ? impactOf(s, s.drag.id, kind)?.needsConfirmation === true : false));
  if (!summary) return null;
  return (
    <div className="tl-dropzone" data-testid="dropzone" data-kind={kind} data-active={active || undefined} data-confirm={confirm || undefined} aria-hidden="true">
      <span className="tl-dropzone__summary">{summary}</span>
      {detail ? <span className="tl-dropzone__detail">{detail.replace(/`/g, '')}</span> : null}
    </div>
  );
}

export function Column({ kind, refs }: { kind: NodeType; refs: ColumnRefs }) {
  const ids = useBoard((s) => s.order[kind]);
  const dragFrom = useBoard((s) => s.drag?.from ?? null);
  const active = useBoard((s) => s.dropKind === kind);
  const hasVocabulary = useBoard((s) => kind === 'ASSUMPTION' && s.vocabulary.length > 0);
  const list = useRef<HTMLDivElement | null>(null);

  useEffect(() => {
    const element = list.current;
    if (!element) return;
    return combine(
      dropTargetForElements({ element, getData: () => columnTargetData(kind), canDrop: ({ source }) => isCardDragData(source.data) }),
      autoScrollForElements({ element, getAllowedAxis: () => 'vertical' }),
    );
  }, [kind]);

  const setList = useCallback(
    (element: HTMLDivElement | null) => {
      list.current = element;
      refs.list(element);
    },
    [refs],
  );

  // During a drag: the column under the pointer is "active"; other columns are labelled drop zones (D-17).
  const drop = dragFrom === null ? undefined : active ? 'active' : dragFrom === kind ? 'source' : 'candidate';
  const changesKind = drop !== undefined && dragFrom !== kind;
  const empty = ids.length === 0;

  return (
    <section className="tl-col" data-kind={kind} data-drop={drop} aria-labelledby={`tl-col-title-${kind}`}>
      <header className="tl-col__header">
        <span className="tl-glyph" data-kind={kind} aria-hidden="true">
          {KIND_GLYPH[kind]}
        </span>
        <h2 className="tl-col__title" id={`tl-col-title-${kind}`}>
          {COLUMN_TITLE[kind]}
        </h2>
        <span className="tl-col__count">{ids.length}</span>
        {changesKind ? <span className="tl-col__drop-label">Drop to make {KIND_NOUN[kind]}</span> : null}
        {/* Filled by the edge engine; React never renders children here. */}
        <span ref={refs.up} className="tl-col__badge-slot" data-dir="up" />
      </header>
      <div
        ref={setList}
        className="tl-col__list"
        data-kind={kind}
        data-empty={(empty && !hasVocabulary) || undefined}
        role="list"
        aria-label={COLUMN_TITLE[kind]}
      >
        {kind === 'ASSUMPTION' ? <VocabularyGroup /> : null}
        {ids.map((id) => (
          <NodeCard key={id} id={id} />
        ))}
        {/* Opaque, so arrows that skip this column pass underneath it, as they do under cards. */}
        {empty ? <p className="tl-col__empty">No {COLUMN_TITLE[kind].toLowerCase()} yet</p> : null}
      </div>
      {changesKind ? <DropZone kind={kind} active={active} /> : null}
      <footer className="tl-col__footer">
        <span ref={refs.down} className="tl-col__badge-slot" data-dir="down" />
      </footer>
    </section>
  );
}

