/**
 * Where a drop lands: the column, and the card it goes above (null = end of the column).
 * Dropping on the lower half of a card inserts after it; dropping a card on itself leaves it where it is.
 */
export function dropPlacement(
  targets: readonly DropTargetRecord[],
  order: Readonly<Record<NodeType, readonly string[]>>,
  draggedId: string,
): { kind: NodeType; beforeId: string | null } | null {
  const kind = columnOf(targets);
  if (!kind) return null;
  const cardTarget = targets.find((t) => isCardTargetData(t.data));
  if (!cardTarget || !isCardTargetData(cardTarget.data)) return { kind, beforeId: null };
  const overId = cardTarget.data.id;
  if (overId === draggedId) {
    const column = order[kind];
    const index = column.indexOf(draggedId);
    return { kind, beforeId: index >= 0 ? (column[index + 1] ?? null) : null };
  }

input.content:
import { monitorForElements } from '@atlaskit/pragmatic-drag-and-drop/adapter/element-adapter';
import { NODE_TYPES, type NodeType } from '@telelean/core';
import { useEffect, useLayoutEffect, useMemo, useRef } from 'react';
import { useBoard, useBoardStore } from '../state/context';
import type { BoardState, BoardStore } from '../state/store';
import { Column, type ColumnRefs } from './Column';
import { setCurrentEngine } from './diagnostics';
import { columnOf, dropPlacement, isCardDragData } from './dnd';
import { EdgeEngine, MARKER_VARIANTS } from './EdgeEngine';
import { hasFocusEdges, toDisplayEdges } from './edges';
import type { BadgeDir } from './geometry';

/** The DOM elements of one column that the edge engine works with. */
interface ColumnElements {
  list?: HTMLDivElement;
  up?: HTMLElement;
  down?: HTMLElement;
}

type Layer = 'under' | 'over';

/**
 * Arrowheads, one per variant (MARKER_VARIANTS): filled triangles for declared / verified / focus / mismatch /
 * reference, a hollow one for conditional edges (taken as a hypothesis). Filled through CSS classes (inline style
 * attributes are blocked by the CSP).
 */
function EdgeDefs({ layer }: { layer: Layer }) {
  return (
    <defs>
      {MARKER_VARIANTS.map((variant) => (
        <marker
          key={variant}
          id={`tl-arrow-${layer}-${variant}`}
          className={`tl-marker tl-marker--${variant}`}
          viewBox="0 0 10 10"
          refX="9"
          refY="5"
          markerUnits="userSpaceOnUse"
          markerWidth={variant === 'reference' ? 7 : 9}
          markerHeight={variant === 'reference' ? 7 : 9}
          orient="auto-start-reverse"
        >
          {variant.startsWith('conditional') ? <path d="M1,1.5 L9,5 L1,8.5 z" /> : <path d="M0,1 L10,5 L0,9 z" />}
        </marker>
      ))}
      <clipPath id={`tl-clip-${layer}`}>
        <rect data-clip={layer} x="0" y="0" width="0" height="0" />
      </clipPath>
    </defs>
  );
}

const focusOf = (s: BoardState): ReadonlySet<string> => new Set(s.hover ? [...s.selected, s.hover] : s.selected);

/** Board-level drag monitor: highlights the column under the pointer and applies the drop. */
function useBoardDnd(store: BoardStore) {
  useEffect(
    () =>
      monitorForElements({
        canMonitor: ({ source }) => isCardDragData(source.data),
        onDragStart: ({ source }) => {
          if (isCardDragData(source.data)) store.getState().startDrag(source.data.id);
        },
        onDropTargetChange: ({ location }) => store.getState().setDropKind(columnOf(location.current.dropTargets)),
        onDrop: ({ source, location }) => {
          const state = store.getState();
          state.endDrag();
          if (!isCardDragData(source.data)) return;
          // Dropping outside every column cancels (D-17).
          const placement = dropPlacement(location.current.dropTargets, state.order, source.data.id);
          if (placement) state.dropCard(source.data.id, placement.kind, placement.beforeId);
        },
      }),
    [store],
  );
}

/** All three columns' elements, or null while any of them is not mounted. */
function complete(columns: Partial<Record<NodeType, ColumnElements>>) {
  const lists = {} as Record<NodeType, HTMLDivElement>;
  const badgeSlots = {} as Record<NodeType, Record<BadgeDir, HTMLElement>>;
  for (const kind of NODE_TYPES) {
    const { list, up, down } = columns[kind] ?? {};
    if (!list || !up || !down) return null;
    lists[kind] = list;
    badgeSlots[kind] = { up, down };
  }
  return { lists, badgeSlots };
}

export function Board() {
  const store = useBoardStore();
  const hasGraph = useBoard((s) => s.version !== null);
  const graphSeq = useBoard((s) => s.seq);
  const dragging = useBoard((s) => s.drag !== null);
  const boardRef = useRef<HTMLDivElement>(null);
  const columns = useRef<Partial<Record<NodeType, ColumnElements>>>({});
  const underRef = useRef<SVGGElement>(null);
  const overRef = useRef<SVGGElement>(null);

  const columnRefs = useMemo(() => {
    const refs = {} as Record<NodeType, ColumnRefs>;
    for (const kind of NODE_TYPES) {
      const slot = <K extends keyof ColumnElements>(key: K) => (element: ColumnElements[K] | null) => {
        const entry = (columns.current[kind] ??= {});
        if (element) entry[key] = element;
        else delete entry[key];
      };
      refs[kind] = { list: slot('list'), up: slot('up'), down: slot('down') };
    }
    return refs;
  }, []);

  useLayoutEffect(() => {
    const board = boardRef.current;
    const under = underRef.current;
    const over = overRef.current;
    const parts = complete(columns.current);
    if (!board || !under || !over || !parts) return;
    const clipRects = [...board.querySelectorAll<SVGRectElement>('rect[data-clip]')];
    const engine = new EdgeEngine({ board, lists: parts.lists, layers: { under, over }, clipRects, badgeSlots: parts.badgeSlots });
    const initial = store.getState();
    engine.setEdges(toDisplayEdges(initial.edges, focusOf(initial)));
    engine.setFocus(focusOf(initial));
    const unsubscribe = store.subscribe((state, previous) => {
      const focusChanged = state.selected !== previous.selected || state.hover !== previous.hover;
      // lean-ref arrows are drawn only while one of their ends has focus, so a focus change can change the set.
      if (state.edges !== previous.edges || (focusChanged && hasFocusEdges(state.edges))) engine.setEdges(toDisplayEdges(state.edges, focusOf(state)));
      if (focusChanged) engine.setFocus(focusOf(state));
    });
    setCurrentEngine(engine);
    return () => {
      setCurrentEngine(null);
      unsubscribe();
      engine.dispose();
    };
  }, [store]);

  useBoardDnd(store);

  return (
    <div className="tl-board" ref={boardRef} data-dragging={dragging || undefined} data-graph-seq={graphSeq}>
      <svg className="tl-edges tl-edges--under" aria-hidden="true">
        <EdgeDefs layer="under" />
        <g ref={underRef} clipPath="url(#tl-clip-under)" />
      </svg>
      <div className="tl-columns">
        {NODE_TYPES.map((kind) => (
          <Column key={kind} kind={kind} refs={columnRefs[kind]} />
        ))}
      </div>
      <svg className="tl-edges tl-edges--over" aria-hidden="true">
        <EdgeDefs layer="over" />
        <g ref={overRef} clipPath="url(#tl-clip-over)" />
      </svg>
      {hasGraph ? null : <p className="tl-board__waiting">Waiting for the extension to send the graph…</p>}
    </div>
  );
}

/**
 * "subject: [Spyro ▾]" (D-10, docs/m1-plan.md 7.3): the model's subjects with their card counts, and "New
 * subject…" with an inline name field (a capitalised Lean identifier, not taken). Choosing a subject posts
 * `selectSubject`; creating one posts `createSubject` (the host then switches the board to it).
 */
import { isSubjectName, type ActionOutcome } from '@telelean/core';
import { useState, type FormEvent } from 'react';
import { Popover } from '../common/Popover';
import { useBoard, useBoardActions } from '../state/context';

export function subjectNameProblem(name: string, taken: readonly string[]): string | null {
  if (name === '') return null;
  if (!isSubjectName(name)) return 'Use a capitalised Lean identifier: a capital letter, then letters, digits or _ (e.g. Spyro).';
  if (taken.includes(name)) return `There is already a subject called ${name}.`;
  return null;
}

export function SubjectPicker() {
  const subject = useBoard((s) => s.subject);
  const workspace = useBoard((s) => s.workspace);
  const actions = useBoardActions();
  const [anchor, setAnchor] = useState<HTMLElement | null>(null);
  const [creating, setCreating] = useState(false);
  const [name, setName] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  if (!workspace) {
    // An older host (or the static sample) sends no workspace state: just name the subject.
    return (
      <span className="tl-toolbar__subject" data-testid="subject">
        {subject || 'no subject'}
      </span>
    );
  }

  const taken = workspace.subjects.map((s) => s.name);
  const problem = subjectNameProblem(name, taken);
  const close = () => {
    setAnchor(null);
    setCreating(false);
    setName('');
    setError(null);
  };
  const submit = (event: FormEvent) => {
    event.preventDefault();
    if (!name || problem || busy) return;
    setBusy(true);
    actions.createSubject(name, (outcome: ActionOutcome) => {
      setBusy(false);
      if (outcome.ok) close();
      else setError(outcome.error);
    });
  };

  return (
    <>
      <span className="tl-toolbar__label">subject:</span>
      <button
        type="button"
        className="tl-menu-button"
        data-testid="subject-picker"
        aria-haspopup="menu"
        aria-expanded={anchor !== null}
        onClick={(event) => (anchor ? close() : setAnchor(event.currentTarget))}
      >
        <span data-testid="subject">{subject || workspace.subject}</span>
        <span className="codicon codicon-chevron-down" aria-hidden="true" />
      </button>
      <Popover anchor={anchor} open={anchor !== null} onClose={close} label="Subjects" testId="subject-menu" className="tl-menu">
        <div role="menu" aria-label="Subjects">
          {workspace.subjects.map((entry) => (
            <button
              key={entry.name}
              type="button"
              role="menuitemradio"
              aria-checked={entry.name === subject}
              className="tl-menu__item"
              data-subject={entry.name}
              onClick={() => {
                close();
                actions.selectSubject(entry.name);
              }}
            >
              <span className={`codicon codicon-${entry.name === subject ? 'check' : 'blank'}`} aria-hidden="true" />
              <span className="tl-menu__text">{entry.name}</span>
              <span className="tl-menu__hint">
                {entry.nodeCount} card{entry.nodeCount === 1 ? '' : 's'}
              </span>
            </button>
          ))}
        </div>
        <div className="tl-menu__separator" />
        {creating ? (
          <form className="tl-menu__form" onSubmit={submit}>
            <input
              className="tl-input"
              aria-label="New subject name"
              placeholder="Name, e.g. Bayonetta"
              value={name}
              autoFocus
              maxLength={64}
              onChange={(event) => {
                setName(event.target.value.trim());
                setError(null);
              }}
            />
            <button type="submit" className="tl-button tl-button--small" disabled={!name || problem !== null || busy}>
              Create
            </button>
            {problem || error ? (
              <p className="tl-menu__error" role="alert">
                {problem ?? error}
              </p>
            ) : null}
          </form>
        ) : (
          <button type="button" className="tl-menu__item" onClick={() => setCreating(true)}>
            <span className="codicon codicon-add" aria-hidden="true" />
            <span className="tl-menu__text">New subject…</span>
          </button>
        )}
      </Popover>
    </>
  );
}

/**
 * The history dropdown (D-33, A3): each telelean change to this subject as "time · action · label", a read-only
 * Preview (a diff against its parent, opened by the host) and "Revert to this" (confirmed; the revert itself is
 * undoable), the storage counter (disk, not RAM) and "Keep last N". Without a repository it offers "Initialize
 * git"; other unavailable states explain themselves.
 */
import type { HistoryAvailability } from '@telelean/core';
import { useState } from 'react';
import { Popover } from '../common/Popover';
import { HISTORY_ACTION_LABEL } from '../labels';
import { formatBytes, formatTime } from '../model/format';
import { useBoard, useBoardActions } from '../state/context';

const PAGE = 50;

function Unavailable({ availability }: { availability: Exclude<HistoryAvailability, { state: 'ready' }> }) {
  const actions = useBoardActions();
  switch (availability.state) {
    case 'no-repo':
      return (
        <div className="tl-history__message" data-testid="history-unavailable" data-state="no-repo">
          <p>History needs a git repository in this model folder. telelean keeps its snapshots under private refs (refs/telelean/…) and never touches your branches.</p>
          <button type="button" className="tl-button tl-button--small" onClick={() => actions.initGit()}>
            Initialize git
          </button>
        </div>
      );
    case 'git-missing':
      return (
        <p className="tl-history__message" data-testid="history-unavailable" data-state="git-missing">
          git is not installed, so there is no history. Board actions and Undo still work.
        </p>
      );
    case 'disabled':
      return (
        <p className="tl-history__message" data-testid="history-unavailable" data-state="disabled">
          History is switched off (setting telelean.git.snapshotRefs). Board actions and Undo still work.
        </p>
      );
    case 'error':
      return (
        <p className="tl-history__message" data-testid="history-unavailable" data-state="error">
          History is unavailable: {availability.detail}
        </p>
      );
  }
}

export function HistoryMenu() {
  const workspace = useBoard((s) => s.workspace);
  const subject = useBoard((s) => s.subject);
  const listing = useBoard((s) => s.history);
  const loading = useBoard((s) => s.historyLoading);
  const actions = useBoardActions();
  const [anchor, setAnchor] = useState<HTMLElement | null>(null);
  const [limit, setLimit] = useState(PAGE);
  const [keep, setKeep] = useState('');

  const availability: HistoryAvailability = workspace?.history ?? { state: 'ready' };
  const open = (element: HTMLElement) => {
    setAnchor(element);
    setLimit(PAGE);
    if (availability.state === 'ready') actions.requestHistory(PAGE);
  };
  const shown = listing && listing.subject === subject ? listing : null;
  const keepLast = Number(keep);
  const keepValid = Number.isInteger(keepLast) && keepLast >= 1 && keepLast <= 100_000;

  return (
    <>
      <button
        type="button"
        className="tl-menu-button"
        data-testid="history-button"
        aria-haspopup="dialog"
        aria-expanded={anchor !== null}
        title="History of this subject: preview or revert to an earlier state"
        onClick={(event) => (anchor ? setAnchor(null) : open(event.currentTarget))}
      >
        <span className="codicon codicon-history" aria-hidden="true" />
        History
        <span className="codicon codicon-chevron-down" aria-hidden="true" />
      </button>
      <Popover anchor={anchor} open={anchor !== null} onClose={() => setAnchor(null)} label="History" testId="history-menu" className="tl-menu tl-history">
        {availability.state !== 'ready' ? (
          <Unavailable availability={availability} />
        ) : (
          <>
            <div className="tl-history__storage" data-testid="history-storage" title="Disk used by telelean's snapshots (not memory)">
              {shown
                ? `This subject: ${formatBytes(shown.storage.subjectBytes)} · All subjects: ${formatBytes(shown.storage.totalBytes)}`
                : loading
                  ? 'Loading…'
                  : 'No history yet.'}
            </div>
            {shown && shown.entries.length === 0 ? <p className="tl-history__message">No snapshots of {subject} yet.</p> : null}
            {shown && shown.entries.length > 0 ? (
              <ol className="tl-history__entries">
                {shown.entries.map((entry, index) => (
                  <li key={entry.id} className="tl-history__entry" data-testid="history-entry" data-entry-id={entry.id}>
                    <span className="tl-history__line" title={`${entry.time} · ${entry.label}`}>
                      {`${formatTime(entry.time)} · ${HISTORY_ACTION_LABEL[entry.action] ?? entry.action} · ${entry.label}`}
                    </span>
                    <span className="tl-history__buttons">
                      <button type="button" className="tl-icon-button" title="Show what this change did (read-only diff)" onClick={() => actions.previewHistory(entry.id, 'parent')}>
                        Preview
                      </button>
                      <button
                        type="button"
                        className="tl-icon-button"
                        disabled={index === 0}
                        title={index === 0 ? 'This is the current state' : 'Make this subject look like this again (undoable)'}
                        onClick={() => {
                          setAnchor(null);
                          actions.openRevert(entry);
                        }}
                      >
                        Revert to this
                      </button>
                    </span>
                  </li>
                ))}
              </ol>
            ) : null}
            {shown?.more ? (
              <button
                type="button"
                className="tl-menu__item"
                onClick={() => {
                  const next = limit + PAGE;
                  setLimit(next);
                  actions.requestHistory(next);
                }}
              >
                Show older entries
              </button>
            ) : null}
            <form
              className="tl-history__prune"
              onSubmit={(event) => {
                event.preventDefault();
                if (!keepValid) return;
                actions.pruneHistory(keepLast);
                setKeep('');
              }}
            >
              <label className="tl-history__prune-label">
                Keep the last
                <input
                  className="tl-input tl-input--number"
                  type="number"
                  min={1}
                  max={100000}
                  aria-label="Keep the last N entries"
                  value={keep}
                  placeholder="N"
                  onChange={(event) => setKeep(event.target.value)}
                />
                entries
              </label>
              <button type="submit" className="tl-button tl-button--secondary tl-button--small" disabled={!keepValid}>
                Keep last
              </button>
            </form>
          </>
        )}
      </Popover>
    </>
  );
}

/**
 * The Lean side of the header: the badge (one per SemanticSummary state; a click asks for a refresh), the problems
 * list (every board diagnostic; file items open in the editor, node items reveal their card), and the banner for
 * syntactic mode (D-7) and switched-off checking.
 */
import type { BoardDiagnostic } from '@telelean/core';
import { useState } from 'react';
import { Popover } from '../common/Popover';
import { semanticBadge } from '../labels';
import { useBoard, useBoardActions } from '../state/context';

const BADGE_ICON = { ok: 'pass', busy: 'sync', warn: 'warning', error: 'error', off: 'circle-slash' } as const;

export function LeanBadge() {
  const semantic = useBoard((s) => s.semantic);
  const actions = useBoardActions();
  const badge = semanticBadge(semantic);
  return (
    <button
      type="button"
      className="tl-lean-badge"
      data-testid="lean-badge"
      data-state={semantic.state}
      data-tone={badge.tone}
      title={badge.title}
      onClick={() => actions.refresh()}
    >
      <span className={`codicon codicon-${BADGE_ICON[badge.tone]}`} aria-hidden="true" />
      {badge.text}
    </button>
  );
}

const SEVERITY_ICON: Readonly<Record<BoardDiagnostic['severity'], string>> = { error: 'error', warning: 'warning', info: 'info', hint: 'lightbulb' };

export function ProblemsMenu() {
  const diagnostics = useBoard((s) => s.diagnostics);
  const nodes = useBoard((s) => s.nodes);
  const actions = useBoardActions();
  const [anchor, setAnchor] = useState<HTMLElement | null>(null);
  const serious = diagnostics.filter((d) => d.severity === 'error' || d.severity === 'warning').length;
  if (diagnostics.length === 0) return null;
  return (
    <>
      <button
        type="button"
        className="tl-menu-button"
        data-testid="problems-button"
        data-serious={serious > 0 || undefined}
        aria-haspopup="dialog"
        aria-expanded={anchor !== null}
        onClick={(event) => setAnchor(anchor ? null : event.currentTarget)}
      >
        <span className={`codicon codicon-${serious > 0 ? 'warning' : 'info'}`} aria-hidden="true" />
        Problems {diagnostics.length}
      </button>
      <Popover anchor={anchor} open={anchor !== null} onClose={() => setAnchor(null)} label="Problems" testId="problems-menu" className="tl-menu tl-problems" align="end">
        <ul className="tl-problems__list">
          {diagnostics.map((d, i) => {
            const node = d.nodeId ? nodes[d.nodeId] : undefined;
            const where = d.file ? `${d.file}${d.range ? `:${d.range.start.line + 1}` : ''}` : null;
            return (
              <li key={i} className="tl-problem" data-testid="problem" data-severity={d.severity}>
                <span className={`codicon codicon-${SEVERITY_ICON[d.severity]}`} aria-hidden="true" />
                <span className="tl-problem__text">
                  <code>{d.code}</code> {d.message}
                  {node ? <span className="tl-problem__node"> ({node.naturalName})</span> : null}
                </span>
                {node ? (
                  <button
                    type="button"
                    className="tl-icon-button"
                    onClick={() => {
                      setAnchor(null);
                      actions.revealNode(node.id);
                    }}
                  >
                    Show card
                  </button>
                ) : null}
                {where && d.file ? (
                  <button
                    type="button"
                    className="tl-icon-button"
                    data-testid="problem-open"
                    title={`Open ${where}`}
                    onClick={() => {
                      setAnchor(null);
                      actions.openInEditor(d.file ?? '', d.range);
                    }}
                  >
                    {where}
                  </button>
                ) : null}
              </li>
            );
          })}
        </ul>
      </Popover>
    </>
  );
}

/** Syntactic mode (D-7) and switched-off checking get a line under the header; other states fit the badge. */
export function LeanBanner() {
  const semantic = useBoard((s) => s.semantic);
  if (semantic.state === 'unsupported-toolchain') {
    return (
      <div className="tl-banner" data-testid="lean-banner" data-state={semantic.state} role="status">
        <span className="codicon codicon-info" aria-hidden="true" />
        <span>
          <strong>Syntactic mode.</strong> This project uses {semantic.toolchain ?? 'another Lean toolchain'}; telelean checks only with
          leanprover/lean4:v4.35.0, so the cards show what the files say, unchecked by Lean.
          {semantic.detail ? ` ${semantic.detail}` : ''}
        </span>
      </div>
    );
  }
  if (semantic.state === 'disabled') {
    return (
      <div className="tl-banner" data-testid="lean-banner" data-state={semantic.state} role="status">
        <span className="codicon codicon-circle-slash" aria-hidden="true" />
        <span>
          <strong>Lean checking is off.</strong> {semantic.detail ?? 'The cards show what the files say, unchecked by Lean.'}
        </span>
      </div>
    );
  }
  return null;
}

import { useBoard, useBoardActions } from '../state/context';
import { HistoryMenu } from './HistoryMenu';
import { LeanBadge, ProblemsMenu } from './LeanStatus';
import { SubjectPicker } from './SubjectPicker';

/** The legend (D-15): line pattern is epistemic status; colour and markers add the rest, never colour alone. */
export function Legend() {
  const line = (variant: 'declared' | 'verified' | 'conditional' | 'mismatch') => (
    <svg width="30" height="10" aria-hidden="true">
      <line className={`tl-legend__line tl-legend__line--${variant}`} x1="1" y1="5" x2="22" y2="5" />
      {variant === 'conditional' ? (
        <path className="tl-legend__head tl-legend__head--hollow" d="M21,1.5 L28,5 L21,8.5 z" />
      ) : (
        <path className={`tl-legend__head tl-legend__head--${variant}`} d="M20,1 L29,5 L20,9 z" />
      )}
    </svg>
  );
  return (
    <span className="tl-legend" aria-label="Legend">
      <span className="tl-legend__item" data-legend="declared" title="You declared this support (These suffice)">
        {line('declared')}
        declared
      </span>
      <span className="tl-legend__item" data-legend="verified" title="Lean checked that the proof uses it">
        {line('verified')}
        verified by Lean
      </span>
      <span className="tl-legend__item" data-legend="conditional" title="The proof takes it as a hypothesis: proved only if it holds">
        {line('conditional')}
        conditional
      </span>
      <span className="tl-legend__item" data-legend="mismatch" title="Declared but unused by the proof, or used but not declared">
        {line('mismatch')}
        mismatch
      </span>
      <span className="tl-legend__item" data-legend="aura" title="The card has a Lean statement">
        <span className="tl-legend__aura" aria-hidden="true" />
        formalised
      </span>
    </span>
  );
}

function UndoRedo() {
  const workspace = useBoard((s) => s.workspace);
  const actions = useBoardActions();
  const undo = workspace?.undo ?? null;
  const redo = workspace?.redo ?? null;
  return (
    <span className="tl-toolbar__group">
      <button type="button" className="tl-icon-button tl-icon-button--toolbar" aria-label="Undo" title={undo ? `Undo: ${undo} (Ctrl+Z)` : 'Nothing to undo'} disabled={!undo} onClick={() => actions.undo()}>
        <span className="codicon codicon-discard" aria-hidden="true" />
      </button>
      <button
        type="button"
        className="tl-icon-button tl-icon-button--toolbar"
        aria-label="Redo"
        title={redo ? `Redo: ${redo} (Ctrl+Shift+Z)` : 'Nothing to redo'}
        disabled={!redo}
        onClick={() => actions.redo()}
      >
        <span className="codicon codicon-redo" aria-hidden="true" />
      </button>
    </span>
  );
}

export function Header() {
  const rootName = useBoard((s) => s.workspace?.rootName ?? null);
  return (
    <header className="tl-toolbar">
      <span className="tl-toolbar__title">telelean</span>
      {rootName ? <span className="tl-toolbar__root" title="Model folder">{rootName}</span> : null}
      <SubjectPicker />
      <HistoryMenu />
      <UndoRedo />
      <LeanBadge />
      <ProblemsMenu />
      <span className="tl-toolbar__spacer" />
      <Legend />
    </header>
  );
}

/**
 * The board's confirmations (one at a time, from the store's `dialog`):
 *  - dependents: a kind change that removes a `.holds` other proofs use (D-11 A->G, D->G), listing them; rewrite
 *    them to take it as a hypothesis (only with fresh Lean facts), keep them marked broken, or cancel;
 *  - rationale: the optional "Why do you hold it?" of a change to Assumption (D-14: Skip is fine);
 *  - delete: who declares it, which proofs use it, which statements mention it (D-18); delete the card with or
 *    without its Lean code;
 *  - revert: "Revert to this" in the history dropdown (D-33).
 */
import { useMemo, useState } from 'react';
import { InlineEdit } from '../common/OneLineInput';
import { Modal } from '../common/Modal';
import { KIND_GLYPH, KIND_NOUN } from '../labels';
import { deleteDependents } from '../model/cardData';
import { formatTime } from '../model/format';
import { useBoard, useBoardActions } from '../state/context';
import type { DialogState } from '../state/store';

/** A dependent: a node by its sentence, anything else (an untracked declaration) by its Lean name. */
function Dependent({ id }: { id: string }) {
  const node = useBoard((s) => s.nodes[id]);
  if (!node) {
    return (
      <li className="tl-dialog__item" data-dependent={id}>
        <code>{id}</code>
      </li>
    );
  }
  return (
    <li className="tl-dialog__item" data-dependent={id}>
      <span className="tl-glyph" data-kind={node.type} aria-hidden="true">
        {KIND_GLYPH[node.type]}
      </span>
      {node.naturalName}
    </li>
  );
}

function DependentsDialog({ dialog }: { dialog: Extract<DialogState, { kind: 'dependents' }> }) {
  const node = useBoard((s) => s.nodes[dialog.id]);
  const actions = useBoardActions();
  return (
    <Modal labelledBy="tl-dialog-title" testId="dialog-dependents" onCancel={() => actions.closeDialog()}>
      <h2 id="tl-dialog-title" className="tl-dialog__title">
        {dialog.summary}
      </h2>
      {node ? <p className="tl-dialog__subject">“{node.naturalName}”</p> : null}
      <p>
        A {KIND_NOUN[dialog.to].toLowerCase()} is not taken as given, so its <code>.holds</code> has to go. These use it:
      </p>
      <ul className="tl-dialog__list" data-testid="dependents">
        {dialog.dependents.map((id) => (
          <Dependent key={id} id={id} />
        ))}
      </ul>
      {!dialog.rewriteAvailable ? <p className="tl-dialog__note">Rewriting needs fresh Lean facts: refresh Lean first (the badge in the header).</p> : null}
      <div className="tl-dialog__buttons">
        <button type="button" className="tl-button" disabled={!dialog.rewriteAvailable} onClick={() => actions.confirmDependents('rewrite')}>
          Rewrite them to take it as a hypothesis
        </button>
        <button type="button" className="tl-button tl-button--secondary" onClick={() => actions.confirmDependents('mark-broken')}>
          Keep them, marked broken
        </button>
        <button type="button" className="tl-button tl-button--secondary" autoFocus onClick={() => actions.closeDialog()}>
          Cancel
        </button>
      </div>
    </Modal>
  );
}

function RationaleDialog({ dialog }: { dialog: Extract<DialogState, { kind: 'rationale' }> }) {
  const node = useBoard((s) => s.nodes[dialog.id]);
  const actions = useBoardActions();
  const [reason, setReason] = useState('');
  return (
    <Modal labelledBy="tl-dialog-title" testId="dialog-rationale" onCancel={() => actions.closeDialog()}>
      <h2 id="tl-dialog-title" className="tl-dialog__title">
        Make {KIND_NOUN[dialog.to]}
      </h2>
      {node ? <p className="tl-dialog__subject">“{node.naturalName}”</p> : null}
      <p className="tl-dialog__detail">{dialog.detail.replace(/`/g, '')}</p>
      <label className="tl-dialog__field">
        <span>Why do you hold it? (optional)</span>
        <InlineEdit
          initial=""
          aria-label="Why do you hold it?"
          placeholder="e.g. known from gaming news"
          onCommit={(value) => setReason(value)}
          onCancel={() => actions.closeDialog()}
          onInput={(event) => setReason(event.currentTarget.value)}
          onKeyDownCapture={(event) => {
            if (event.key === 'Enter') {
              event.preventDefault();
              actions.confirmRationale(event.currentTarget.value);
            }
          }}
        />
      </label>
      <div className="tl-dialog__buttons">
        <button type="button" className="tl-button" onClick={() => actions.confirmRationale(reason)}>
          Make {KIND_NOUN[dialog.to]}
        </button>
        <button type="button" className="tl-button tl-button--secondary" onClick={() => actions.confirmRationale(null)}>
          Skip
        </button>
        <button type="button" className="tl-button tl-button--secondary" onClick={() => actions.closeDialog()}>
          Cancel
        </button>
      </div>
    </Modal>
  );
}

function DeleteDialog({ dialog }: { dialog: Extract<DialogState, { kind: 'delete' }> }) {
  const node = useBoard((s) => s.nodes[dialog.id]);
  const nodes = useBoard((s) => s.nodes);
  const edges = useBoard((s) => s.edges);
  const order = useBoard((s) => s.order);
  const actions = useBoardActions();
  const affected = useMemo(() => deleteDependents(dialog.id, { nodes, edges, order }), [dialog.id, nodes, edges, order]);
  if (!node) return null;
  const hasLean = node.lean.statement !== undefined || node.lean.code !== undefined;
  const nothing = affected.declaredBy.length + affected.proofs.length + affected.mentions.length === 0;
  const section = (title: string, ids: string[], testId: string) =>
    ids.length > 0 ? (
      <div data-testid={testId}>
        <h3 className="tl-dialog__heading">{title}</h3>
        <ul className="tl-dialog__list">
          {ids.map((id) => (
            <Dependent key={id} id={id} />
          ))}
        </ul>
      </div>
    ) : null;
  return (
    <Modal labelledBy="tl-dialog-title" testId="dialog-delete" onCancel={() => actions.closeDialog()}>
      <h2 id="tl-dialog-title" className="tl-dialog__title">
        Delete this {KIND_NOUN[node.type].toLowerCase()}?
      </h2>
      <p className="tl-dialog__subject">“{node.naturalName}”</p>
      {nothing ? <p>Nothing else refers to it.</p> : null}
      {section('Declared as a premise by', affected.declaredBy, 'delete-declared')}
      {section('Used by the proofs of', affected.proofs, 'delete-proofs')}
      {section('Mentioned in the statements of', affected.mentions, 'delete-mentions')}
      {hasLean ? (
        <p className="tl-dialog__note">
          “Card only” keeps the Lean declarations: without the card, <code>axiom …holds</code> becomes an unmarked axiom, a hidden
          assumption Lean still takes as given, and the board flags it in the Vocabulary group.
        </p>
      ) : null}
      <div className="tl-dialog__buttons">
        <button type="button" className="tl-button tl-button--danger" autoFocus onClick={() => actions.deleteNode(node.id, false)}>
          {hasLean ? 'Delete card and its Lean code' : 'Delete card'}
        </button>
        {hasLean ? (
          <button type="button" className="tl-button tl-button--secondary" onClick={() => actions.deleteNode(node.id, true)}>
            Delete card only, keep Lean
          </button>
        ) : null}
        <button type="button" className="tl-button tl-button--secondary" onClick={() => actions.closeDialog()}>
          Cancel
        </button>
      </div>
    </Modal>
  );
}

function RevertDialog({ dialog }: { dialog: Extract<DialogState, { kind: 'revert' }> }) {
  const subject = useBoard((s) => s.subject);
  const actions = useBoardActions();
  return (
    <Modal labelledBy="tl-dialog-title" testId="dialog-revert" onCancel={() => actions.closeDialog()}>
      <h2 id="tl-dialog-title" className="tl-dialog__title">
        Revert {subject} to this state?
      </h2>
      <p className="tl-dialog__subject">
        {formatTime(dialog.entry.time)} · {dialog.entry.label}
      </p>
      <p>The subject's files are written back to how they were then. The current state is snapshotted first, so the revert can be undone.</p>
      <div className="tl-dialog__buttons">
        <button type="button" className="tl-button" onClick={() => actions.revertHistory(dialog.entry.id)}>
          Revert
        </button>
        <button type="button" className="tl-button tl-button--secondary" autoFocus onClick={() => actions.closeDialog()}>
          Cancel
        </button>
      </div>
    </Modal>
  );
}

export function Dialogs() {
  const dialog = useBoard((s) => s.dialog);
  if (!dialog) return null;
  switch (dialog.kind) {
    case 'dependents':
      return <DependentsDialog key={`${dialog.id}-${dialog.to}`} dialog={dialog} />;
    case 'rationale':
      return <RationaleDialog key={`${dialog.id}-${dialog.to}`} dialog={dialog} />;
    case 'delete':
      return <DeleteDialog key={dialog.id} dialog={dialog} />;
    case 'revert':
      return <RevertDialog key={dialog.entry.id} dialog={dialog} />;
  }
}

