/**
 * Toasts: the host's notices ("Deleted …" with Undo, "Copied") and the board's own refusals. A notice marked
 * undoable shows an Undo button that posts `undo`.
 */
import { useBoard, useBoardActions } from '../state/context';

const ICON = { info: 'info', warning: 'warning', error: 'error' } as const;

export function Toasts() {
  const toasts = useBoard((s) => s.toasts);
  const actions = useBoardActions();
  return (
    <div className="tl-toasts" role="status" aria-live="polite" data-testid="toasts">
      {toasts.map((toast) => (
        <div key={toast.key} className="tl-toast" data-level={toast.level} data-testid="toast">
          <span className={`codicon codicon-${ICON[toast.level]}`} aria-hidden="true" />
          <span className="tl-toast__text">{toast.text}</span>
          {toast.undoable ? (
            <button
              type="button"
              className="tl-button tl-button--small"
              onClick={() => {
                actions.dismissToast(toast.key);
                actions.undo();
              }}
            >
              Undo
            </button>
          ) : null}
          <button type="button" className="tl-icon-button" aria-label="Dismiss" onClick={() => actions.dismissToast(toast.key)}>
            <span className="codicon codicon-close" aria-hidden="true" />
          </button>
        </div>
      ))}
    </div>
  );
}

import type { TlNode } from '@telelean/core';
import { useMemo } from 'react';
import { KIND_GLYPH, KIND_NOUN } from '../labels';
import { presuppositionLabel, presuppositionsOf } from '../model/cardData';
import { useBoard, useBoardActions } from '../state/context';
import { trayModel } from '../state/store';

function Chip({ node, role, onRemove, onMakeTarget }: { node: TlNode; role: 'premise' | 'target'; onRemove: () => void; onMakeTarget?: () => void }) {
  return (
    <span className="tl-chipcard" data-kind={node.type} data-role={role} data-id={node.id}>
      <span className="tl-glyph" data-kind={node.type} title={KIND_NOUN[node.type]}>
        {KIND_GLYPH[node.type]}
      </span>
      <span className="tl-chipcard__text" title={node.naturalName}>
        {node.naturalName}
      </span>
      {onMakeTarget ? (
        <button type="button" className="tl-icon-button" title="Make this the target" aria-label={`Make "${node.naturalName}" the target`} onClick={onMakeTarget}>
          ⊢
        </button>
      ) : null}
      <button type="button" className="tl-icon-button" title="Remove from selection" aria-label={`Remove "${node.naturalName}" from the selection`} onClick={onRemove}>
        <span className="codicon codicon-close" aria-hidden="true" />
      </button>
    </span>
  );
}

/**
 * The selection, split into premises ⊢ target (D-5), with the presuppositions the selected statements carry
 * ("+ presupposes: assumes characters exist", D-3b) and "These suffice" (M1: declares the premises as the target's
 * support, D-13). With a target and no premises, "Self-evident?" is shown but is available only with Claude (M2).
 */
export function SelectionTray() {
  const selected = useBoard((s) => s.selected);
  const target = useBoard((s) => s.target);
  const nodes = useBoard((s) => s.nodes);
  const vocab = useBoard((s) => s.vocab);
  const subject = useBoard((s) => s.subject);
  const actions = useBoardActions();
  const tray = useMemo(() => trayModel({ selected, target, nodes }), [selected, target, nodes]);
  const presuppositions = useMemo(() => presuppositionsOf(selected, nodes), [selected, nodes]);

  if (selected.length === 0) {
    return (
      <section className="tl-tray tl-tray--empty" aria-label="Selection">
        <span className="tl-tray__hint">
          Click a card to select it, Ctrl/Cmd-click to select several. Select premises and one goal, then press “These suffice”.
        </span>
      </section>
    );
  }

  const targetNode = tray.target ? nodes[tray.target] : undefined;
  const selfEvident = tray.target !== null && tray.premises.length === 0;
  return (
    <section className="tl-tray" aria-label="Selection" data-testid="tray">
      <span className="tl-tray__count" data-testid="tray-count">
        {selected.length} selected
      </span>
      <div className="tl-tray__chips">
        {tray.premises.map((id) => {
          const node = nodes[id];
          return node ? (
            <Chip key={id} node={node} role="premise" onRemove={() => actions.deselect(id)} onMakeTarget={() => actions.setTarget(id)} />
          ) : null;
        })}
        <span className="tl-tray__turnstile" aria-hidden="true">
          ⊢
        </span>
        <span className="tl-tray__target" data-testid="tray-target" data-filled={targetNode ? true : undefined}>
          {targetNode ? (
            <Chip node={targetNode} role="target" onRemove={() => actions.deselect(targetNode.id)} />
          ) : (
            <span className="tl-tray__slot">target</span>
          )}
        </span>
        {presuppositions.length > 0 ? (
          <span className="tl-tray__presup" data-testid="tray-presuppositions" title="Existence presuppositions of the selected statements (D-3b)">
            <span className="tl-tray__presup-label">+ presupposes:</span>
            {presuppositions.map((name) => (
              <button key={name} type="button" className="tl-presup" data-presup={name} title={name} onClick={() => actions.highlightVocab(name)}>
                {presuppositionLabel(name, subject, vocab)}
              </button>
            ))}
          </span>
        ) : null}
      </div>
      <span className="tl-tray__spacer" />
      <button type="button" className="tl-button tl-button--secondary" onClick={() => actions.clearSelection()}>
        Clear
      </button>
      {selfEvident ? (
        <>
          <button type="button" className="tl-button tl-button--secondary" disabled title="Asking whether the target holds without premises needs Claude (M2)">
            Self-evident?
          </button>
          <span className="tl-tray__note">available with Claude in M2</span>
        </>
      ) : null}
      <button
        type="button"
        className="tl-button"
        disabled={tray.blocked !== null}
        title={tray.blocked ?? 'Declare these premises as the support of the target (proving it with Claude arrives in M2)'}
        onClick={() => actions.theseSuffice()}
      >
        These suffice ▶
      </button>
      {tray.blocked && !selfEvident ? <span className="tl-tray__blocked">{tray.blocked}</span> : null}
    </section>
  );
}

import { EVIDENTIALS, NODE_TYPES, STANCES, type Evidential, type NodeType, type Stance } from '@telelean/core';
import { useRef, useState, type KeyboardEvent } from 'react';
import { revealCardSoon } from '../board/reveal';
import { pasteOneLine } from '../common/OneLineInput';
import { KIND_GLYPH, KIND_NOUN, PROMPT_PLACEHOLDER, SOURCE_LABEL, STANCE_LABEL, whyPlaceholder } from '../labels';
import { useBoard, useBoardActions } from '../state/context';

/** Chips that act like radio buttons which can also be switched off again (all D-14 chips are optional). */
function ChipChoice<T extends string>({ label, values, value, text, onChange }: { label: string; values: readonly T[]; value: T | undefined; text: Readonly<Record<T, string>>; onChange: (next: T | undefined) => void }) {
  return (
    <span className="tl-prompt__chips" role="group" aria-label={label}>
      {values.map((v) => (
        <button key={v} type="button" className="tl-choice" aria-pressed={v === value} onClick={() => onChange(v === value ? undefined : v)}>
          {text[v]}
        </button>
      ))}
    </span>
  );
}

/**
 * The A|D|G prompt box (D-16): the switch marks the kind of the card the text creates. Enter adds a comment-only
 * card with the user's verbatim words (trimmed only; no LLM, no Lean). The second row is optional (D-14): stance
 * chips for an Assumption, a "why" field whose prompt follows the stance and kind, and source chips.
 */
export function PromptBox() {
  const kind = useBoard((s) => s.promptKind);
  const actions = useBoardActions();
  const [text, setText] = useState('');
  const [why, setWhy] = useState('');
  const [stance, setStance] = useState<Stance | undefined>(undefined);
  const [source, setSource] = useState<Evidential | undefined>(undefined);
  const radios = useRef<Partial<Record<NodeType, HTMLButtonElement | null>>>({});
  const showStance = kind === 'ASSUMPTION';
  const showSource = kind !== 'GOAL';

  const submit = () => {
    const id = actions.addNode(kind, text, {
      ...(why.trim() ? { rationale: why } : {}),
      ...(showStance && stance ? { stance } : {}),
      ...(showSource && source ? { source } : {}),
    });
    if (id) {
      setText('');
      setWhy('');
      setStance(undefined);
      setSource(undefined);
      revealCardSoon(id);
    }
  };

  const onSwitchKey = (event: KeyboardEvent) => {
    if (event.key !== 'ArrowRight' && event.key !== 'ArrowLeft') return;
    event.preventDefault();
    const index = NODE_TYPES.indexOf(kind);
    const next = NODE_TYPES[(index + (event.key === 'ArrowRight' ? 1 : NODE_TYPES.length - 1)) % NODE_TYPES.length] ?? kind;
    actions.setPromptKind(next);
    radios.current[next]?.focus();
  };

  return (
    <form
      className="tl-prompt"
      data-kind={kind}
      onSubmit={(event) => {
        event.preventDefault();
        submit();
      }}
    >
      <div className="tl-prompt__row">
        <div className="tl-seg" role="radiogroup" aria-label="Kind of the new card" onKeyDown={onSwitchKey}>
          {NODE_TYPES.map((k) => (
            <button
              key={k}
              ref={(element) => {
                radios.current[k] = element;
              }}
              type="button"
              role="radio"
              aria-checked={k === kind}
              tabIndex={k === kind ? 0 : -1}
              data-kind={k}
              onClick={() => actions.setPromptKind(k)}
            >
              <span className="tl-glyph" data-kind={k} aria-hidden="true">
                {KIND_GLYPH[k]}
              </span>
              {KIND_NOUN[k]}
            </button>
          ))}
        </div>
        <input
          className="tl-prompt__input"
          type="text"
          value={text}
          placeholder={PROMPT_PLACEHOLDER[kind]}
          aria-label={`New ${KIND_NOUN[kind].toLowerCase()}`}
          onChange={(event) => setText(event.target.value)}
          onPaste={(event) => pasteOneLine(event, setText)}
        />
        <button type="submit" className="tl-button" disabled={text.trim() === ''}>
          Add {KIND_NOUN[kind].toLowerCase()}
        </button>
      </div>
      <div className="tl-prompt__row tl-prompt__row--extra">
        {showStance ? <ChipChoice label="Stance" values={STANCES} value={stance} text={STANCE_LABEL} onChange={setStance} /> : null}
        <input
          className="tl-prompt__why"
          type="text"
          value={why}
          placeholder={whyPlaceholder(kind, stance)}
          aria-label="Why (optional)"
          onChange={(event) => setWhy(event.target.value)}
          onPaste={(event) => pasteOneLine(event, setWhy)}
        />
        {showSource ? <ChipChoice label="Source" values={EVIDENTIALS} value={source} text={SOURCE_LABEL} onChange={setSource} /> : null}
      </div>
    </form>
  );
}

import { Board } from './board/Board';
import { Dialogs } from './dialogs/Dialogs';
import { Header } from './header/Header';
import { LeanBanner } from './header/LeanStatus';
import { PromptBox } from './prompt/PromptBox';
import { Toasts } from './toasts/Toasts';
import { SelectionTray } from './tray/SelectionTray';

export function App() {
  return (
    <div className="tl-app">
      <Header />
      <LeanBanner />
      <Board />
      <SelectionTray />
      <PromptBox />
      <Toasts />
      <Dialogs />
    </div>
  );
}

