        posted.push(copy);
        if (copy && typeof copy.type === 'string') answer(copy);
      },
      getState: function () {
        var raw = sessionStorage.getItem(STATE_KEY);
        return raw === null ? undefined : JSON.parse(raw);
      },
      setState: function (next) {
        sessionStorage.setItem(STATE_KEY, JSON.stringify(next));
        return next;
      },
    });
  };
})();

/**
 * Global setup (and, through its return value, teardown) of the Playwright run: proves that Chrome left the real
 * home folder alone (docs/m1-plan.md section 10, AT6.15).
 *
 * Chrome runs with HOME and XDG_* pointing into the run's short temp dir (playwright.config.ts), so crash reports,
 * NSS databases and caches land there and are deleted with it. This guard lists the real locations Chrome would
 * otherwise write to before the run and again after it, and fails the run if anything changed. The listings
 * (names, sizes, modification times; never file contents) are written to test-results/home-guard.json.
 */
import { mkdirSync, readdirSync, statSync, writeFileSync } from 'node:fs';
import { homedir } from 'node:os';
import { join, relative } from 'node:path';
import { fileURLToPath } from 'node:url';

/** Where Chrome writes in a home folder (profile and crash reports, cache, NSS certificate database). */
const WATCHED = ['.config/google-chrome', '.cache/google-chrome', '.pki'];

type Listing = Record<string, string[] | null>;

function walk(root: string, dir: string, out: string[]): void {
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const path = join(dir, entry.name);
    const stat = statSync(path, { throwIfNoEntry: false });
    if (!stat) continue;
    out.push(`${relative(root, path)}\t${entry.isDirectory() ? 'dir' : stat.size}\t${Math.round(stat.mtimeMs)}`);
    if (entry.isDirectory() && !entry.isSymbolicLink()) walk(root, path, out);
  }
}

export function listHome(home: string = homedir()): Listing {
  const listing: Listing = {};
  for (const sub of WATCHED) {
    const root = join(home, sub);
    const stat = statSync(root, { throwIfNoEntry: false });
    if (!stat) {
      listing[sub] = null;
      continue;
    }
    const entries: string[] = [];
    walk(root, root, entries);
    listing[sub] = entries.sort();
  }
  return listing;
}

function differences(before: Listing, after: Listing): string[] {
  const out: string[] = [];
  for (const sub of WATCHED) {
    const a = before[sub] ?? null;
    const b = after[sub] ?? null;
    if (a === null && b === null) continue;
    if (a === null || b === null) {
      out.push(`${sub}: ${a === null ? 'appeared' : 'disappeared'}`);
      continue;
    }
    const setA = new Set(a);
    const setB = new Set(b);
    for (const line of b) if (!setA.has(line)) out.push(`${sub}: new or changed ${line.split('\t')[0]}`);
    for (const line of a) if (!setB.has(line)) out.push(`${sub}: removed or changed ${line.split('\t')[0]}`);
  }
  return out;
}

export default function homeGuard(): () => void {
  const before = listHome();
  return () => {
    const after = listHome();
    const changed = differences(before, after);
    const report = fileURLToPath(new URL('../../test-results/home-guard.json', import.meta.url));
    mkdirSync(fileURLToPath(new URL('../../test-results/', import.meta.url)), { recursive: true });
    writeFileSync(report, `${JSON.stringify({ home: homedir(), watched: WATCHED, before, after, changed }, null, 2)}\n`);
    if (changed.length > 0) throw new Error(`Chrome changed the real home folder:\n${changed.join('\n')}`);
    console.log(`home guard: ${WATCHED.map((sub) => `~/${sub} ${before[sub] === null ? 'absent' : `${before[sub]?.length} entries`}`).join(', ')}; unchanged`);
  };
}

import { defineConfig } from '@playwright/test';
import { mkdirSync } from 'node:fs';
import { join } from 'node:path';
import { chromeTmpDir } from './test/harness/chrome-tmp';

const PORT = 41739;

/**
 * Chrome's environment: ours, with TMPDIR, HOME and the XDG base directories all inside this run's short temp
 * directory (see test/harness/chrome-tmp.ts), so nothing Chrome writes (profile, crash reports, NSS database,
 * caches) lands in the real home folder; the global teardown deletes the directory. test/harness/home-guard.ts
 * checks the real home folder afterwards (docs/m1-plan.md section 10).
 */
function chromeEnv(): Record<string, string> {
  const tmp = chromeTmpDir();
  const dirs = { HOME: join(tmp, 'home'), XDG_CONFIG_HOME: join(tmp, 'xdg-config'), XDG_CACHE_HOME: join(tmp, 'xdg-cache'), XDG_DATA_HOME: join(tmp, 'xdg-data') };
  for (const dir of Object.values(dirs)) mkdirSync(dir, { recursive: true });
  return {
    ...Object.fromEntries(Object.entries(process.env).filter((entry): entry is [string, string] => entry[1] !== undefined)),
    TMPDIR: tmp,
    ...dirs,
  };
}

/**
 * Browser tests of the built bundle (packages/extension/dist/webview) in a static harness page with a mock
 * acquireVsCodeApi. Uses the installed Google Chrome (channel "chrome"); never downloads browsers.
 * One worker: one browser at a time (RAM rule). The npm script runs it under `ulimit -c 0` (no core dumps).
 */
export default defineConfig({
  testDir: 'test/e2e',
  // Screenshots are written to test-results/ directly; Playwright's own artifacts go one level down so the
  // start-of-run cleanup does not delete them.
  outputDir: 'test-results/playwright',
  workers: 1,
  fullyParallel: false,
  retries: 0,
  timeout: 30_000,
  expect: { timeout: 5_000 },
  reporter: [['list']],
  globalSetup: './test/harness/home-guard.ts',
  globalTeardown: './test/harness/chrome-tmp.ts',
  use: {
    baseURL: `http://127.0.0.1:${PORT}`,
    channel: 'chrome',
    headless: true,
    launchOptions: {
      env: chromeEnv(),
      args: ['--disable-crash-reporter', '--disable-breakpad', '--no-first-run'],
    },
    viewport: { width: 1280, height: 800 },
    deviceScaleFactor: 1,
    trace: 'off',
    screenshot: 'off',
    video: 'off',
  },
  webServer: {
    command: `node test/harness/serve.mjs ${PORT}`,
    url: `http://127.0.0.1:${PORT}/harness/index.html`,
    reuseExistingServer: false,
    timeout: 15_000,
    stdout: 'ignore',
  },
});

/**
 * Graph variants for the webview's tests, built from the frozen Spyro samples (core's samples carry the M1 card
 * data; other statuses are derived here).
 */
import {
  edgeId,
  spyroGraph,
  spyroProvedGraph,
  type BoardDiagnostic,
  type DerivedStatus,
  type HistoryListing,
  type SemanticSummary,
  type TlEdge,
  type TlGraph,
  type TlNode,
  type WorkspaceState,
} from '@telelean/core';

export function mapNode(graph: TlGraph, id: string, patch: (node: TlNode) => TlNode): TlGraph {
  return { ...graph, nodes: graph.nodes.map((n) => (n.id === id ? patch(n) : n)) };
}

export function withStatus(node: TlNode, status: Partial<DerivedStatus>): TlNode {
  return { ...node, status: { ...node.status, ...status } };
}

export function withSemantic(graph: TlGraph, semantic: SemanticSummary, version = graph.version): TlGraph {
  return { ...graph, semantic, version };
}

/** A minimal formalised node (statement abbrev) for status tests. */
export function makeNode(id: string, type: TlNode['type'], naturalName: string, status: Partial<DerivedStatus>, extra: Partial<TlNode> = {}): TlNode {
  const lean = id.replace(/-/g, '_');
  return {
    id,
    type,
    role: 'node',
    subject: 'Spyro',
    naturalName,
    premises: [],
    provenance: { wordedBy: 'user', endorsed: true, origin: 'user' },
    ext: {},
    lean: { binding: 'pinned', statement: `Spyro.${lean}`, code: `abbrev ${lean} : Prop := True` },
    status: { formal: 'formalized', proof: { kind: 'none' }, certificates: { consistency: 'none', nonVacuity: 'none' }, flags: [], ...status },
    ...extra,
  };
}

/**
 * Every ProofStatus kind and the M1 flags on one board (Spyro's vocabulary and four nodes, plus status nodes), with
 * diagnostics for the attention badge and an ASSUMPTION with declared premises (the D-13 hint).
 */
export function statusGallery(version = 5): TlGraph {
  const base = spyroProvedGraph(version);
  const extra: TlNode[] = [
    makeNode('d-pending', 'DERIVATION', 'Cynder is not PG material', { proof: { kind: 'pending-promotion' }, flags: ['claimed'] }, { lean: { binding: 'pinned', statement: 'Spyro.d_pending', justification: 'Spyro.d_pending.holds', justificationKind: 'axiom', code: 'abbrev d_pending : Prop := True\naxiom d_pending.holds : d_pending' } }),
    makeNode('d-conditional', 'DERIVATION', 'Spyro games avoid dark characters', { proof: { kind: 'conditional', on: ['d-pending'], footprint: ['cynder-dark-past'] } }),
    makeNode('g-sorry', 'GOAL', 'The sequel will be rated PG', { flags: ['uses-sorry'] }),
    makeNode('g-unchecked', 'GOAL', 'Fans will accept the change', { flags: ['not-checked'] }),
    makeNode('a-stale', 'ASSUMPTION', 'Critics notice ratings', { proof: { kind: 'assumed' }, flags: ['stale'] }),
    makeNode('a-missing', 'ASSUMPTION', 'Ratings are public', { flags: ['missing-holds'] }),
    makeNode('a-premised', 'ASSUMPTION', 'Ratings follow content', { proof: { kind: 'assumed' } }, { premises: ['cynder-dark-past'] }),
  ];
  const nodes = [...base.nodes, ...extra];
  const diagnostics: BoardDiagnostic[] = [
    { code: 'TL115', severity: 'warning', message: 'declaration uses sorry', nodeId: 'g-sorry', file: 'Model/Spyro/Main.lean', range: { start: { line: 60, character: 0 }, end: { line: 60, character: 0 } } },
    { code: 'LEAN', severity: 'error', message: 'unknown identifier', nodeId: 'g-sorry', file: 'Model/Spyro/Main.lean', range: { start: { line: 61, character: 2 }, end: { line: 61, character: 2 } } },
    { code: 'TL011', severity: 'info', message: 'ASSUMPTION without rationale', nodeId: 'a-missing' },
    { code: 'TL117', severity: 'warning', message: 'assumption without .holds', nodeId: 'a-missing' },
  ];
  const edges: TlEdge[] = [
    ...base.edges,
    { id: edgeId('premise', 'cynder-dark-past', 'a-premised'), type: 'premise', source: 'cynder-dark-past', target: 'a-premised', origin: 'declared' },
  ];
  return { ...base, nodes, edges, diagnostics };
}

/**
 * The proved Spyro board plus the M1 edge kinds the samples do not have: a conditional verified edge, a mismatch
 * on each side, and a lean-ref edge (the goal's statement mentions new-spyro-pg's).
 */
export function edgeKindsGraph(version = 6): TlGraph {
  const base = spyroProvedGraph(version);
  const extra = makeNode('d-hyp', 'DERIVATION', 'A PG game has no dark-past characters', { proof: { kind: 'conditional', on: ['pg-no-dark-past'] } });
  const edges: TlEdge[] = base.edges.map((e) =>
    e.type === 'premise' && e.source === 'pg-no-dark-past' ? { ...e, mismatch: 'declared-unused' } : e.type === 'verified' && e.source === 'new-spyro-pg' ? { ...e, mismatch: 'used-undeclared' } : e,
  );
  edges.push(
    { id: edgeId('verified', 'pg-no-dark-past', 'd-hyp'), type: 'verified', source: 'pg-no-dark-past', target: 'd-hyp', origin: 'lean', where: 'proof', conditional: true },
    { id: edgeId('lean-ref', 'cynder-dark-past', 'd-hyp'), type: 'lean-ref', source: 'cynder-dark-past', target: 'd-hyp', origin: 'lean', where: 'statement' },
  );
  return { ...base, nodes: [...base.nodes, extra], edges };
}

/** spyroGraph with a lean-ref edge: the goal's statement mentions cynder-dark-past's statement. */
export function mentionGraph(version = 7): TlGraph {
  const base = spyroGraph(version);
  return {
    ...base,
    edges: [...base.edges, { id: edgeId('lean-ref', 'cynder-dark-past', 'cynder-not-good'), type: 'lean-ref', source: 'cynder-dark-past', target: 'cynder-not-good', origin: 'lean', where: 'statement' }],
  };
}

export function workspaceState(patch: Partial<WorkspaceState> = {}): WorkspaceState {
  return {
    rootName: 'mental_model',
    subjects: [
      { name: 'Spyro', nodeCount: 4 },
      { name: 'Bayonetta', nodeCount: 2 },
    ],
    subject: 'Spyro',
    undo: 'Add assumption: Cynder is a character who has a dark past',
    redo: null,
    history: { state: 'ready' },
    ...patch,
  };
}

export function historyListing(subject = 'Spyro'): HistoryListing {
  return {
    subject,
    entries: [
      { id: 'c0ffee1', time: '2026-11-01T09:30:00.000Z', action: 'set-premises', label: 'These suffice: Cynder would not be a good addition… ← 3 premises', subject, nodes: ['cynder-not-good'] },
      { id: 'b0ffee2', time: '2026-11-01T09:20:00.000Z', action: 'add-node', label: 'Add assumption: The new Spyro game is PG', subject, nodes: ['new-spyro-pg'] },
      { id: 'a0ffee3', time: '2026-10-31T18:05:00.000Z', action: 'initial', label: 'Initial state', subject, nodes: [] },
    ],
    storage: { subjectBytes: 12 * 1024, totalBytes: 30 * 1024, perSubject: { Spyro: 12 * 1024, Bayonetta: 18 * 1024 } },
    more: false,
  };
}

