/**
 * Lean 4.35 identifier character classes (`Init/Meta/Defs.lean`: `isLetterLike`, `isSubScriptAlnum`, `isIdFirst`,
 * `isIdRest`), on Unicode code points. `Char.isAlpha` and `Char.isAlphanum` are ASCII-only in Lean.
 */

/** Greek (but λ, Π, Σ), Coptic, polytonic Greek, the letter-like block, script/double-struck/fraktur, Latin-1 and Latin Extended-A letters. */
export function isLetterLike(cp: number): boolean {
  return (
    (cp >= 0x3b1 && cp <= 0x3c9 && cp !== 0x3bb) ||
    (cp >= 0x391 && cp <= 0x3a9 && cp !== 0x3a0 && cp !== 0x3a3) ||
    (cp >= 0x3ca && cp <= 0x3fb) ||
    (cp >= 0x1f00 && cp <= 0x1ffe) ||
    (cp >= 0x2100 && cp <= 0x214f) ||
    (cp >= 0x1d49c && cp <= 0x1d59f) ||
    (cp >= 0x00c0 && cp <= 0x00ff && cp !== 0x00d7 && cp !== 0x00f7) ||
    (cp >= 0x0100 && cp <= 0x017f)
  );
}

/** Subscript digits, letters and the subscript j. */
export function isSubScriptAlnum(cp: number): boolean {
  return (cp >= 0x2080 && cp <= 0x2089) || (cp >= 0x2090 && cp <= 0x209c) || (cp >= 0x1d62 && cp <= 0x1d6a) || cp === 0x2c7c;
}

/** First character of an identifier part: ASCII letter, `_` or letter-like. */
export function isIdFirst(cp: number): boolean {
  return (cp >= 0x61 && cp <= 0x7a) || (cp >= 0x41 && cp <= 0x5a) || cp === 0x5f || isLetterLike(cp);
}

/** Later characters of an identifier part: also digits, `'`, `!`, `?` and subscripts. */
export function isIdRest(cp: number): boolean {
  return isIdFirst(cp) || (cp >= 0x30 && cp <= 0x39) || cp === 0x27 || cp === 0x21 || cp === 0x3f || isSubScriptAlnum(cp);
}

/** Lean's `Char.isWhitespace`: space, tab, carriage return, line feed (nothing else). */
export function isLeanWhitespace(code: number): boolean {
  return code === 0x20 || code === 0x09 || code === 0x0d || code === 0x0a;
}

/** The code point at `index` (a whole surrogate pair) or -1 past the end. */
export function codePointAt(text: string, index: number): number {
  return index < text.length ? (text.codePointAt(index) ?? -1) : -1;
}

/** Number of UTF-16 code units of the code point `cp`. */
export function cpWidth(cp: number): number {
  return cp > 0xffff ? 2 : 1;
}

/**
 * A Lean 4.35 lexer for comments, literals and identifiers: enough to find telelean blocks and declaration headers
 * without being fooled by comment delimiters inside strings, characters, raw strings or «escaped» names.
 *
 * Mirrors `Lean/Parser/Basic.lean` of the pinned toolchain:
 *  - `whitespace`: `--` starts a line comment; `/-` starts a block comment, `/--` a doc comment and `/-!` a module
 *    doc comment;
 *  - `finishCommentBlock`: block comments nest (`/-` opens, `-/` closes). For every kind the nesting scan starts
 *    after the third character: the doc tokens `/--` and `/-!` are three characters long, and for a plain comment
 *    `whitespace` skips the character after `/-` (verified with Lean 4.35: `/-/-/` is one complete comment and
 *    `/--/ doc -/` a valid docstring);
 *  - `tokenFnAux`: strings (`\` escapes the next character), character literals (`'a'`, `'\n'`, `'\x41'`,
 *    `'α'`; a `'` followed by `'` is not one), numbers (decimal with `_`, `0b`/`0o`/`0x`, scientific), raw
 *    strings `r#"…"#`, identifiers (dotted, with «escaped» parts; `isIdFirst`/`isIdRest`).
 * An unterminated comment or string runs to the end of the text, as in Lean. Interpolated strings (`s!"…"`, `m!"…"`,
 * `f!"…"`) skip their `{…}` parts as code, so a quote inside braces does not end them. Comments and tokens are
 * disjoint and sorted by offset; offsets are UTF-16 code units.
 */
import { codePointAt, cpWidth, isIdFirst, isIdRest, isLeanWhitespace } from './chars.js';
import type { CommentKind, LeanComment, LeanToken, LexResult } from './types.js';

const NL = 0x0a;
const CR = 0x0d;
const QUOTE = 0x22;
const HASH = 0x23;
const APOS = 0x27;
const DASH = 0x2d;
const DOT = 0x2e;
const SLASH = 0x2f;
const BACKSLASH = 0x5c;
const BANG = 0x21;
const LOWER_R = 0x72;
const LBRACE = 0x7b;
const RBRACE = 0x7d;
const GUILLEMET_OPEN = 0xab;
const GUILLEMET_CLOSE = '»';

/** Identifiers whose syntax takes an interpolated string right after them. */
const INTERPOLATING = new Set(['s!', 'm!', 'f!']);

const isDigit = (c: number) => c >= 0x30 && c <= 0x39;
const isHexDigit = (c: number) => isDigit(c) || (c >= 0x61 && c <= 0x66) || (c >= 0x41 && c <= 0x46);

/** Lexes Lean 4.35 source: comments (nesting), strings, chars, raw strings, «»-identifiers (research r4 lexer). */
export function lexLean(text: string): LexResult {
  const comments: LeanComment[] = [];
  const tokens: LeanToken[] = [];
  const n = text.length;
  const at = (i: number) => (i < n ? text.charCodeAt(i) : -1);

  /** End of the block comment whose opener `/-` starts at `i` (scan from `scanFrom`), or -1 when unterminated. */
  const finishCommentBlock = (scanFrom: number): number => {
    let depth = 1;
    let k = scanFrom;
    while (k < n) {
      const c = text.charCodeAt(k);
      if (c === DASH && at(k + 1) === SLASH) {
        k += 2;
        if (--depth === 0) return k;
      } else if (c === SLASH && at(k + 1) === DASH) {
        k += 2;
        depth++;
      } else {
        k++;
      }
    }
    return -1;
  };

  /** End of the string literal opening at `i` (`"`), or `n` when unterminated. */
  const scanString = (i: number, interpolated: boolean): number => {
    let j = i + 1;
    while (j < n) {
      const c = text.charCodeAt(j);
      if (c === BACKSLASH) j += 2;
      else if (c === QUOTE) return j + 1;
      else if (interpolated && c === LBRACE) j = skipCode(j + 1);
      else j++;
    }
    return n;
  };

  /** End of a character literal opening at `i` (`'`), or -1 when this `'` does not start one. */
  const scanChar = (i: number): number => {
    const c = codePointAt(text, i + 1);
    if (c < 0) return -1;
    let k: number;
    if (c === BACKSLASH) {
      const e = at(i + 2);
      if (e === BACKSLASH || e === QUOTE || e === APOS || e === 0x72 || e === 0x6e || e === 0x74) k = i + 3;
      else if (e === 0x78) k = isHexDigit(at(i + 3)) && isHexDigit(at(i + 4)) ? i + 5 : -1;
      else if (e === 0x75) k = [3, 4, 5, 6].every((d) => isHexDigit(at(i + d))) ? i + 7 : -1;
      else k = -1;
    } else {
      k = i + 1 + cpWidth(c);
    }
    return k > 0 && at(k) === APOS ? k + 1 : -1;
  };

  /** End of the raw string starting at `i` (`r`, then `#`s, then `"`), or -1 when this is not one. */
  const scanRawString = (i: number): number => {
    let j = i + 1;
    while (at(j) === HASH) j++;
    if (at(j) !== QUOTE) return -1;
    const close = `"${'#'.repeat(j - i - 1)}`;
    const k = text.indexOf(close, j + 1);
    return k < 0 ? n : k + close.length;
  };

  const scanDigits = (j: number, ok: (c: number) => boolean): number => {
    while (j < n && (ok(text.charCodeAt(j)) || text.charCodeAt(j) === 0x5f)) j++;
    return j;
  };

  /** End of the number starting at `i` (a digit). After a `.` only digits are read (`h.1.2` is a projection). */
  const scanNumber = (i: number): number => {
    const c1 = at(i + 1) | 0x20;
    if (at(i) === 0x30 && (c1 === 0x62 || c1 === 0x6f || c1 === 0x78)) {
      const ok = c1 === 0x62 ? (c: number) => c === 0x30 || c === 0x31 : c1 === 0x6f ? (c: number) => c >= 0x30 && c <= 0x37 : isHexDigit;
      return scanDigits(i + 2, ok);
    }
    let j = scanDigits(i, isDigit);
    if (i > 0 && text.charCodeAt(i - 1) === DOT) return j;
    if (at(j) === DOT && at(j + 1) !== DOT) {
      j = scanDigits(j + 1, isDigit);
    }
    if ((at(j) | 0x20) === 0x65) {
      let k = j + 1;
      if (at(k) === 0x2b || at(k) === DASH) k++;
      if (isDigit(at(k))) j = scanDigits(k, isDigit);
    }
    return j;
  };

  /** Whether an «escape» opening at `j` is closed. */
  const closedEscape = (j: number) => text.indexOf(GUILLEMET_CLOSE, j + 1) >= 0;

  /** End of the dotted identifier starting at `i`, or -1 when it starts with an unterminated «. */
  const scanIdent = (i: number): number => {
    let j = i;
    for (;;) {
      const cp = codePointAt(text, j);
      if (cp === GUILLEMET_OPEN) {
        const k = text.indexOf(GUILLEMET_CLOSE, j + 1);
        if (k < 0) return j === i ? -1 : j;
        j = k + 1;
      } else if (isIdFirst(cp)) {
        j += cpWidth(cp);
        for (let r = codePointAt(text, j); r >= 0 && isIdRest(r); r = codePointAt(text, j)) j += cpWidth(r);
      } else {
        return j;
      }
      if (at(j) !== DOT) return j;
      const next = codePointAt(text, j + 1);
      if (isIdFirst(next) || (next === GUILLEMET_OPEN && closedEscape(j + 1))) j++;
      else return j;
    }
  };

  /**
   * Skips code inside an interpolation `{…}` (starting after the `{`) up to and including its matching `}`;
   * nothing found there is recorded.
   */
  const skipCode = (start: number): number => {
    let i = start;
    let depth = 0;
    while (i < n) {
      const c = text.charCodeAt(i);
      const next = scanItem(i, false);
      if (next > i) {
        i = next;
        continue;
      }
      if (c === LBRACE) depth++;
      else if (c === RBRACE && depth-- === 0) return i + 1;
      i += cpWidth(codePointAt(text, i));
    }
    return n;
  };

  /**
   * Lexes one comment or literal/identifier starting at `i` (recorded when `record`), returning its end, or `i` when
   * the character there is whitespace or a symbol.
   */
  const scanItem = (i: number, record: boolean): number => {
    const c = text.charCodeAt(i);
    if (c === DASH && at(i + 1) === DASH) {
      let j = text.indexOf('\n', i);
      if (j < 0) j = n;
      const end = j > i + 2 && text.charCodeAt(j - 1) === CR && j < n ? j - 1 : j;
      if (record) comments.push({ kind: 'line', span: { start: i, end }, body: { start: i + 2, end: Math.max(i + 2, end) }, unterminated: false });
      return j;
    }
    if (c === SLASH && at(i + 1) === DASH) {
      const third = at(i + 2);
      const kind: CommentKind = third === DASH ? 'doc' : third === BANG ? 'moddoc' : 'block';
      const bodyStart = Math.min(kind === 'block' ? i + 2 : i + 3, n);
      const scanFrom = i + 2 < n ? i + 2 + cpWidth(codePointAt(text, i + 2)) : n;
      const end = finishCommentBlock(scanFrom);
      if (record) {
        comments.push(
          end < 0
            ? { kind, span: { start: i, end: n }, body: { start: bodyStart, end: n }, unterminated: true }
            : { kind, span: { start: i, end }, body: { start: bodyStart, end: Math.max(bodyStart, end - 2) }, unterminated: false },
        );
      }
      return end < 0 ? n : end;
    }
    let end = -1;
    let kind: LeanToken['kind'] = 'symbol';
    if (c === QUOTE) {
      kind = 'string';
      const previous = tokens.length > 0 ? tokens[tokens.length - 1] : undefined;
      end = scanString(i, record && previous !== undefined && previous.span.end === i && INTERPOLATING.has(previous.text));
    } else if (c === APOS && at(i + 1) !== APOS) {
      kind = 'char';
      end = scanChar(i);
    } else if (isDigit(c)) {
      kind = 'number';
      end = scanNumber(i);
    } else if (c === LOWER_R && at(i + 1) >= 0 && (at(i + 1) === HASH || at(i + 1) === QUOTE)) {
      kind = 'string';
      end = scanRawString(i);
    }
    if (end < 0 || (end === -1 && kind !== 'symbol')) end = -1;
    if (end < 0) {
      const cp = codePointAt(text, i);
      if (cp === GUILLEMET_OPEN || isIdFirst(cp)) {
        kind = 'ident';
        end = scanIdent(i);
      }
    }
    if (end > i) {
      if (record) tokens.push({ kind, span: { start: i, end }, text: text.slice(i, end) });
      return end;
    }
    return i;
  };

  let i = 0;
  while (i < n) {
    const c = text.charCodeAt(i);
    if (isLeanWhitespace(c)) {
      i++;
      continue;
    }
    const next = scanItem(i, true);
    if (next > i) {
      i = next;
      continue;
    }
    const width = cpWidth(codePointAt(text, i));
    tokens.push({ kind: 'symbol', span: { start: i, end: i + width }, text: text.slice(i, i + width) });
    i += width;
  }
  return { comments, tokens };
}

/** True when `name` is exactly one Lean identifier (dotted, «escaped» parts allowed), e.g. `Spyro.cynder_not_good`. */
export function isLeanName(name: string): boolean {
  if (name.length === 0) return false;
  const { comments, tokens } = lexLean(name);
  const only = tokens[0];
  return comments.length === 0 && tokens.length === 1 && only !== undefined && only.kind === 'ident' && only.span.start === 0 && only.span.end === name.length;
}

/** Splits a dotted name into its components, keeping «escaped» parts whole (`A.«b.c»` -> `A`, `«b.c»`). */
export function nameComponents(name: string): string[] {
  const parts: string[] = [];
  let current = '';
  let inEscape = false;
  for (const ch of name) {
    if (ch === '«') inEscape = true;
    else if (ch === '»') inEscape = false;
    if (ch === '.' && !inEscape) {
      parts.push(current);
      current = '';
    } else {
      current += ch;
    }
  }
  parts.push(current);
  return parts;
}

/** `«x»` -> `x` when `x` is a plain identifier part (Lean prints such names without the escape); other parts unchanged. */
export function canonicalNamePart(part: string): string {
  if (!part.startsWith('«') || !part.endsWith('»') || part.length < 3) return part;
  const inner = part.slice(1, -1);
  const cps = Array.from(inner, (ch) => ch.codePointAt(0) ?? -1);
  const first = cps[0];
  return first !== undefined && isIdFirst(first) && cps.every(isIdRest) ? inner : part;
}

/** A name as Lean prints it: unnecessary «» removed per component. */
export function canonicalName(name: string): string {
  return nameComponents(name).map(canonicalNamePart).join('.');
}

/**
 * A Lean 4.35 lexer for comments, literals and identifiers: enough to find telelean blocks and declaration headers
 * without being fooled by comment delimiters inside strings, characters, raw strings or «escaped» names.
 *
 * Mirrors `Lean/Parser/Basic.lean` of the pinned toolchain:
 *  - `whitespace`: `--` starts a line comment; `/-` starts a block comment, `/--` a doc comment and `/-!` a module
 *    doc comment;
 *  - `finishCommentBlock`: block comments nest (`/-` opens, `-/` closes). For every kind the nesting scan starts
 *    after the third character: the doc tokens `/--` and `/-!` are three characters long, and for a plain comment
 *    `whitespace` skips the character after `/-` (verified with Lean 4.35: `/-/-/` is one complete comment and
 *    `/--/ doc -/` a valid docstring);
 *  - `tokenFnAux`: strings (`\` escapes the next character), character literals (`'a'`, `'\n'`, `'\x41'`,
 *    `'α'`; a `'` followed by `'` starts none), numbers (decimal with `_`, `0b`/`0o`/`0x`, scientific), raw
 *    strings `r#"…"#`, identifiers (dotted, with «escaped» parts; `isIdFirst`/`isIdRest`).
 * An unterminated comment or string runs to the end of the text, as in Lean. Interpolated strings (`s!"…"`, `m!"…"`,
 * `f!"…"`) skip their `{…}` parts as code, so a quote inside the braces does not end them. Whitespace is Lean's
 * (space, tab, CR, LF); any other character outside the above is a one-code-point symbol. Comments and tokens are
 * disjoint and sorted by offset; offsets are UTF-16 code units.
 */
import { codePointAt, cpWidth, isIdFirst, isIdRest, isLeanWhitespace } from './chars.js';
import type { CommentKind, LeanComment, LeanToken, LexResult, TokenKind } from './types.js';

const CR = 0x0d;
const BANG = 0x21;
const QUOTE = 0x22;
const HASH = 0x23;
const APOS = 0x27;
const DASH = 0x2d;
const DOT = 0x2e;
const SLASH = 0x2f;
const BACKSLASH = 0x5c;
const UNDERSCORE = 0x5f;
const LOWER_R = 0x72;
const LBRACE = 0x7b;
const RBRACE = 0x7d;
const GUILLEMET_OPEN = 0xab;
const GUILLEMET_CLOSE = 0xbb;

/** Identifiers whose syntax takes an interpolated string right after them. */
const INTERPOLATING = new Set(['s!', 'm!', 'f!']);

const isDigit = (c: number) => c >= 0x30 && c <= 0x39;
const isHexDigit = (c: number) => isDigit(c) || (c >= 0x61 && c <= 0x66) || (c >= 0x41 && c <= 0x46);

/** The code point that ends just before `index`, or -1. */
function codePointBefore(text: string, index: number): number {
  if (index <= 0) return -1;
  const low = text.charCodeAt(index - 1);
  if (low >= 0xdc00 && low <= 0xdfff && index >= 2) {
    const high = text.charCodeAt(index - 2);
    if (high >= 0xd800 && high <= 0xdbff) return text.codePointAt(index - 2) ?? -1;
  }
  return low;
}

/** Lexes Lean 4.35 source: comments (nesting), strings, chars, raw strings, «»-identifiers (research r4 lexer). */
export function lexLean(text: string): LexResult {
  const comments: LeanComment[] = [];
  const tokens: LeanToken[] = [];
  const n = text.length;
  const at = (i: number) => (i >= 0 && i < n ? text.charCodeAt(i) : -1);

  /** Nesting scan of a block comment from `scanFrom`: the offset just after its closer, or -1 when unterminated. */
  const finishCommentBlock = (scanFrom: number): number => {
    let depth = 1;
    let k = scanFrom;
    while (k < n) {
      const c = text.charCodeAt(k);
      if (c === DASH && at(k + 1) === SLASH) {
        k += 2;
        if (--depth === 0) return k;
      } else if (c === SLASH && at(k + 1) === DASH) {
        k += 2;
        depth++;
      } else {
        k++;
      }
    }
    return -1;
  };

  /** Whether the `"` at `i` opens an interpolated string (`s!"`, `m!"`, `f!"` with nothing glued before the name). */
  const interpolationAt = (i: number): boolean => {
    if (i < 2 || at(i - 1) !== BANG || !INTERPOLATING.has(text.slice(i - 2, i))) return false;
    const before = codePointBefore(text, i - 2);
    return !(before >= 0 && (isIdRest(before) || before === DOT || before === GUILLEMET_CLOSE));
  };

  /** End of the string literal opening at `i`, or `n` when unterminated. */
  const scanString = (i: number): number => {
    const interpolated = interpolationAt(i);
    let j = i + 1;
    while (j < n) {
      const c = text.charCodeAt(j);
      if (c === BACKSLASH) j += 2;
      else if (c === QUOTE) return j + 1;
      else if (interpolated && c === LBRACE) j = skipInterpolation(j + 1);
      else j++;
    }
    return n;
  };

  /** End of a character literal opening at `i`, or -1 when this `'` starts none (Lean: "missing end of character literal"). */
  const scanChar = (i: number): number => {
    const c = codePointAt(text, i + 1);
    if (c < 0) return -1;
    let k = -1;
    if (c === BACKSLASH) {
      const e = at(i + 2);
      if (e === BACKSLASH || e === QUOTE || e === APOS || e === 0x72 || e === 0x6e || e === 0x74) k = i + 3;
      else if (e === 0x78 && isHexDigit(at(i + 3)) && isHexDigit(at(i + 4))) k = i + 5;
      else if (e === 0x75 && [3, 4, 5, 6].every((d) => isHexDigit(at(i + d)))) k = i + 7;
    } else {
      k = i + 1 + cpWidth(c);
    }
    return k > 0 && at(k) === APOS ? k + 1 : -1;
  };

  /** End of the raw string at `i` (`r`, `#`s, `"` … `"`, the same `#`s), or -1 when `r` does not start one. */
  const scanRawString = (i: number): number => {
    let j = i + 1;
    while (at(j) === HASH) j++;
    if (at(j) !== QUOTE) return -1;
    const close = `"${'#'.repeat(j - i - 1)}`;
    const k = text.indexOf(close, j + 1);
    return k < 0 ? n : k + close.length;
  };

  const scanDigits = (from: number, ok: (c: number) => boolean): number => {
    let j = from;
    while (j < n && (ok(text.charCodeAt(j)) || text.charCodeAt(j) === UNDERSCORE)) j++;
    return j;
  };

  /** End of the number at `i` (a digit). Right after a `.` only digits are read (`h.1.2` is two projections). */
  const scanNumber = (i: number): number => {
    const base = at(i + 1) | 0x20;
    if (at(i) === 0x30 && (base === 0x62 || base === 0x6f || base === 0x78)) {
      const ok = base === 0x62 ? (c: number) => c === 0x30 || c === 0x31 : base === 0x6f ? (c: number) => c >= 0x30 && c <= 0x37 : isHexDigit;
      return scanDigits(i + 2, ok);
    }
    let j = scanDigits(i, isDigit);
    if (at(i - 1) === DOT) return j;
    if (at(j) === DOT && at(j + 1) !== DOT) j = scanDigits(j + 1, isDigit);
    if ((at(j) | 0x20) === 0x65) {
      let k = j + 1;
      if (at(k) === 0x2b || at(k) === DASH) k++;
      if (isDigit(at(k))) j = scanDigits(k, isDigit);
    }
    return j;
  };

  /** End of the dotted identifier at `i`, or -1 when it starts with an unterminated «. */
  const scanIdent = (i: number): number => {
    let j = i;
    for (;;) {
      const cp = codePointAt(text, j);
      if (cp === GUILLEMET_OPEN) {
        const k = text.indexOf('»', j + 1);
        if (k < 0) return -1;
        j = k + 1;
      } else if (isIdFirst(cp)) {
        j += cpWidth(cp);
        for (let r = codePointAt(text, j); r >= 0 && isIdRest(r); r = codePointAt(text, j)) j += cpWidth(r);
      } else {
        return j;
      }
      if (at(j) !== DOT) return j;
      const next = codePointAt(text, j + 1);
      if (isIdFirst(next) || (next === GUILLEMET_OPEN && text.indexOf('»', j + 2) >= 0)) j++;
      else return j;
    }
  };

  /** Skips the code of an interpolation `{…}` (from just after the `{`) through its matching `}`; records nothing. */
  const skipInterpolation = (start: number): number => {
    let i = start;
    let depth = 0;
    while (i < n) {
      const end = scanItem(i, false);
      if (end > i) {
        i = end;
        continue;
      }
      const c = text.charCodeAt(i);
      if (c === LBRACE) depth++;
      else if (c === RBRACE && depth-- === 0) return i + 1;
      i += cpWidth(codePointAt(text, i));
    }
    return n;
  };

  /**
   * Lexes the comment, literal or identifier starting at `i` (recording it when `record`) and returns its end, or
   * returns `i` when the character there is whitespace or a symbol.
   */
  const scanItem = (i: number, record: boolean): number => {
    const c = text.charCodeAt(i);
    if (c === DASH && at(i + 1) === DASH) {
      const newline = text.indexOf('\n', i);
      const next = newline < 0 ? n : newline;
      const end = newline > i + 2 && text.charCodeAt(newline - 1) === CR ? newline - 1 : next;
      if (record) comments.push({ kind: 'line', span: { start: i, end }, body: { start: i + 2, end }, unterminated: false });
      return next;
    }
    if (c === SLASH && at(i + 1) === DASH) {
      const third = at(i + 2);
      const kind: CommentKind = third === DASH ? 'doc' : third === BANG ? 'moddoc' : 'block';
      const bodyStart = Math.min(kind === 'block' ? i + 2 : i + 3, n);
      const scanFrom = i + 2 < n ? i + 2 + cpWidth(codePointAt(text, i + 2)) : n;
      const end = finishCommentBlock(scanFrom);
      if (record) {
        comments.push(
          end < 0
            ? { kind, span: { start: i, end: n }, body: { start: bodyStart, end: n }, unterminated: true }
            : { kind, span: { start: i, end }, body: { start: bodyStart, end: Math.max(bodyStart, end - 2) }, unterminated: false },
        );
      }
      return end < 0 ? n : end;
    }
    let kind: TokenKind = 'symbol';
    let end = -1;
    if (c === QUOTE) {
      kind = 'string';
      end = scanString(i);
    } else if (c === APOS && at(i + 1) !== APOS) {
      kind = 'char';
      end = scanChar(i);
    } else if (isDigit(c)) {
      kind = 'number';
      end = scanNumber(i);
    } else if (c === LOWER_R) {
      kind = 'string';
      end = scanRawString(i);
    }
    if (end < 0) {
      const cp = codePointAt(text, i);
      if (cp === GUILLEMET_OPEN || isIdFirst(cp)) {
        kind = 'ident';
        end = scanIdent(i);
      }
    }
    if (end <= i) return i;
    if (record) tokens.push({ kind, span: { start: i, end }, text: text.slice(i, end) });
    return end;
  };

  let i = 0;
  while (i < n) {
    if (isLeanWhitespace(text.charCodeAt(i))) {
      i++;
      continue;
    }
    const end = scanItem(i, true);
    if (end > i) {
      i = end;
      continue;
    }
    const width = cpWidth(codePointAt(text, i));
    tokens.push({ kind: 'symbol', span: { start: i, end: i + width }, text: text.slice(i, i + width) });
    i += width;
  }
  return { comments, tokens };
}

/** True when `name` is exactly one Lean identifier (dotted, «escaped» parts allowed), e.g. `Spyro.cynder_not_good`. */
export function isLeanName(name: string): boolean {
  if (name.length === 0) return false;
  const { comments, tokens } = lexLean(name);
  const only = tokens[0];
  return comments.length === 0 && tokens.length === 1 && only !== undefined && only.kind === 'ident' && only.span.start === 0 && only.span.end === name.length;
}

/** Splits a dotted name into its components, keeping «escaped» parts whole (`A.«b.c»` -> `A`, `«b.c»`). */
export function nameComponents(name: string): string[] {
  const parts: string[] = [];
  let current = '';
  let inEscape = false;
  for (const ch of name) {
    if (ch === '«') inEscape = true;
    else if (ch === '»') inEscape = false;
    if (ch === '.' && !inEscape) {
      parts.push(current);
      current = '';
    } else {
      current += ch;
    }
  }
  parts.push(current);
  return parts;
}

/** `«x»` -> `x` when `x` is a plain identifier part (Lean prints such names without the escape); other parts unchanged. */
function canonicalNamePart(part: string): string {
  if (part.length < 3 || !part.startsWith('«') || !part.endsWith('»')) return part;
  const inner = part.slice(1, -1);
  const cps = Array.from(inner, (ch) => ch.codePointAt(0) ?? -1);
  const first = cps[0];
  return first !== undefined && isIdFirst(first) && cps.every(isIdRest) ? inner : part;
}

/** A name as Lean prints it: unnecessary «» removed per component (`«cynder»` -> `cynder`, `«a b»` kept). */
export function canonicalName(name: string): string {
  return nameComponents(name).map(canonicalNamePart).join('.');
}

/**
 * Line utilities shared by the parser and the text edits. Lines are separated by `\n`; a `\r` right before it
 * belongs to the line break (`\r\n`), so line contents never include it. Offsets are UTF-16 code units, which are
 * also LSP's default character unit, so a position's `character` is an offset difference.
 */
import type { LineIndex, Range, Span } from './types.js';

const NL = 0x0a;
const CR = 0x0d;

/** Offsets at which each line starts (the first is 0). */
export function lineStarts(text: string): number[] {
  const starts = [0];
  for (let i = text.indexOf('\n'); i >= 0; i = text.indexOf('\n', i + 1)) starts.push(i + 1);
  return starts;
}

/** The 0-based line containing `offset` (an offset at a line start belongs to that line). */
export function lineOfOffset(starts: readonly number[], offset: number): number {
  let lo = 0;
  let hi = starts.length - 1;
  while (lo < hi) {
    const mid = (lo + hi + 1) >> 1;
    if ((starts[mid] ?? 0) <= offset) lo = mid;
    else hi = mid - 1;
  }
  return lo;
}

/** Where line `line`'s content ends: before its `\n` or `\r\n`, or at the end of the text. */
export function lineContentEnd(text: string, starts: readonly number[], line: number): number {
  const next = starts[line + 1];
  if (next === undefined) return text.length;
  const newline = next - 1;
  return newline > (starts[line] ?? 0) && text.charCodeAt(newline - 1) === CR ? newline - 1 : newline;
}

/** Where line `line` ends including its line break (the next line's start, or the end of the text). */
export function lineFullEnd(text: string, starts: readonly number[], line: number): number {
  return starts[line + 1] ?? text.length;
}

/** True when `text[start, end)` holds only spaces and tabs. */
export function isHorizontalSpace(text: string, start: number, end: number): boolean {
  for (let i = start; i < end; i++) {
    const c = text.charCodeAt(i);
    if (c !== 0x20 && c !== 0x09) return false;
  }
  return true;
}

/** True when line `line` exists and holds only whitespace. */
export function isBlankLine(text: string, starts: readonly number[], line: number): boolean {
  const start = starts[line];
  if (start === undefined) return false;
  return text.slice(start, lineContentEnd(text, starts, line)).trim() === '';
}

/** The leading spaces and tabs of line `line`. */
export function lineIndent(text: string, starts: readonly number[], line: number): string {
  const start = starts[line] ?? 0;
  let i = start;
  const end = lineContentEnd(text, starts, line);
  while (i < end && (text.charCodeAt(i) === 0x20 || text.charCodeAt(i) === 0x09)) i++;
  return text.slice(start, i);
}

/** The file's line break: that of its first line, `\n` when it has none. */
export function detectEol(text: string): '\n' | '\r\n' {
  const i = text.indexOf('\n');
  return i > 0 && text.charCodeAt(i - 1) === CR ? '\r\n' : '\n';
}

/** True when the text ends with a line break. */
export function endsWithNewline(text: string): boolean {
  return text.length > 0 && text.charCodeAt(text.length - 1) === NL;
}

/** Offset <-> position conversion for one text (LSP convention: 0-based line, UTF-16 character). */
export function lineIndex(text: string): LineIndex {
  const starts = lineStarts(text);
  return {
    lineCount: starts.length,
    positionAt(offset: number) {
      const clamped = Math.max(0, Math.min(offset, text.length));
      const line = lineOfOffset(starts, clamped);
      return { line, character: clamped - (starts[line] ?? 0) };
    },
    offsetAt(position: { line: number; character: number }) {
      if (position.line < 0) return 0;
      const start = starts[position.line];
      if (start === undefined) return text.length;
      return Math.min(start + Math.max(0, position.character), lineContentEnd(text, starts, position.line));
    },
  };
}

/** A line table bundling the text, its line starts and range conversion (internal helper). */
export class Lines {
  readonly starts: number[];
  constructor(readonly text: string) {
    this.starts = lineStarts(text);
  }
  lineOf(offset: number): number {
    return lineOfOffset(this.starts, offset);
  }
  start(line: number): number {
    return this.starts[line] ?? this.text.length;
  }
  contentEnd(line: number): number {
    return lineContentEnd(this.text, this.starts, line);
  }
  fullEnd(line: number): number {
    return lineFullEnd(this.text, this.starts, line);
  }
  isBlank(line: number): boolean {
    return isBlankLine(this.text, this.starts, line);
  }
  indent(line: number): string {
    return lineIndent(this.text, this.starts, line);
  }
  get count(): number {
    return this.starts.length;
  }
  position(offset: number): { line: number; character: number } {
    const clamped = Math.max(0, Math.min(offset, this.text.length));
    const line = this.lineOf(clamped);
    return { line, character: clamped - this.start(line) };
  }
  range(span: Span): Range {
    return { start: this.position(span.start), end: this.position(span.end) };
  }
  /** True when only spaces/tabs precede `offset` on its line. */
  isLineInitial(offset: number): boolean {
    return isHorizontalSpace(this.text, this.start(this.lineOf(offset)), offset);
  }
}

/**
 * Field values of markup v1 (03 section 3.1; 02 D-8; docs/m1-plan.md section 6.7): never YAML. A value is the
 * trimmed raw text after `key:`, or a JSON string literal when it starts with `"`. The serializer writes a value
 * raw whenever that round-trips and is safe inside a Lean block comment, and as an escaped JSON string otherwise.
 */
import type { KnownFieldKey } from './types.js';

/** Line breaks, C0/C1 control characters and the Unicode line/paragraph separators. */
const CONTROL = /[\u0000-\u001f\u007f-\u009f  ]/;
/** Whitespace that `String.prototype.trim` would remove at either end. */
const EDGE_SPACE = /^\s|\s$/u;

/** Interprets a raw field value: a JSON string when it starts with `"`, else the trimmed raw text (never YAML). */
export function parseFieldValue(raw: string): { ok: true; value: string } | { ok: false; error: string } {
  const v = raw.trim();
  if (!v.startsWith('"')) return { ok: true, value: v };
  try {
    const parsed: unknown = JSON.parse(v);
    if (typeof parsed !== 'string') return { ok: false, error: 'a quoted value must be one JSON string' };
    return { ok: true, value: parsed };
  } catch (error) {
    const detail = error instanceof Error ? error.message : String(error);
    return { ok: false, error: `not a valid JSON string literal (${detail})` };
  }
}

/**
 * A JSON string literal for `value` that can sit inside a Lean block comment: every `/` followed by `-` is written
 * `/` (so `/-` becomes the 7 characters backslash u 0 0 2 f -), and every other `/` preceded by `-` is
 * written `\/` (so `-/` becomes `-\/`). Newlines and control characters use JSON escapes.
 */
export function escapeJsonValue(value: string): string {
  const json = JSON.stringify(value);
  let out = '';
  for (let i = 0; i < json.length; i++) {
    const ch = json.charAt(i);
    if (ch !== '/') out += ch;
    else if (json.charAt(i + 1) === '-') out += '\\u002f';
    else if (json.charAt(i - 1) === '-') out += '\\/';
    else out += ch;
  }
  return out;
}

/**
 * True when a scalar value cannot be written raw: empty, a comment delimiter, a leading `"`, a line break or
 * control character, or leading/trailing whitespace (the parser trims raw values).
 */
export function needsQuoting(value: string): boolean {
  return value === '' || value.includes('/-') || value.includes('-/') || value.startsWith('"') || CONTROL.test(value) || EDGE_SPACE.test(value);
}

/** One list item: raw when safe and unambiguous (no comma, no edge bracket), else a JSON string. */
export function formatListItem(item: string): string {
  const ambiguous = item.includes(',') || item.startsWith('[') || item.endsWith(']');
  return needsQuoting(item) || ambiguous ? escapeJsonValue(item) : item;
}

/**
 * The text written after `key: `. Raw when that round-trips (no comment delimiter, no leading quote, no line break,
 * no leading/trailing space); otherwise `escapeJsonValue`. Lists are written `a, b, c` (an item that is not safe
 * raw, e.g. one holding a comma, is written as a JSON string).
 */
export function formatFieldValue(key: KnownFieldKey | string, value: string | readonly string[]): string {
  void key;
  if (typeof value !== 'string') return value.map(formatListItem).join(', ');
  return needsQuoting(value) ? escapeJsonValue(value) : value;
}

/** Markdown body escapes: `-/` -> `-\/`, `/-` -> `/\-` (CommonMark backslash escapes). */
export function escapeBodyText(body: string): string {
  return body.replace(/-\//g, '-\\/').replace(/\/-/g, '/\\-');
}

/**
 * Splits a list value: optional surrounding brackets, items separated by commas, each item trimmed raw text or a
 * JSON string literal (which may hold commas). Empty items are skipped. Errors name the offending item.
 */
export function splitList(raw: string): { items: string[]; errors: string[] } {
  let v = raw.trim();
  if (v.startsWith('[') && v.endsWith(']')) v = v.slice(1, -1);
  const items: string[] = [];
  const errors: string[] = [];
  let i = 0;
  while (i <= v.length) {
    while (i < v.length && /\s/u.test(v.charAt(i))) i++;
    if (i >= v.length) break;
    if (v.charAt(i) === '"') {
      let j = i + 1;
      while (j < v.length && v.charAt(j) !== '"') j += v.charAt(j) === '\\' ? 2 : 1;
      const literal = v.slice(i, j + 1);
      const parsed = parseFieldValue(literal);
      if (parsed.ok) items.push(parsed.value);
      else errors.push(`${literal}: ${parsed.error}`);
      let k = j + 1;
      while (k < v.length && /\s/u.test(v.charAt(k))) k++;
      if (k < v.length && v.charAt(k) !== ',') {
        const comma = v.indexOf(',', k);
        errors.push(`unexpected text after ${literal}`);
        k = comma < 0 ? v.length : comma;
      }
      i = k + 1;
    } else {
      const comma = v.indexOf(',', i);
      const end = comma < 0 ? v.length : comma;
      const item = v.slice(i, end).trim();
      if (item !== '') items.push(item);
      i = end + 1;
    }
  }
  return { items, errors };
}

/**
 * Node ids (03 section 3.1 "Rules for id"; 02 D-8): a stable slug transliterated from the sentence, with
 * `n-<6 hex>` as the fallback for text with no Latin letters or digits. Ids are never changed implicitly; a derived
 * id is written back on the next edit.
 */

/** Node ids: lower-case letters and digits in groups joined by `-`, `_` or `.` (fallback ids look like `n-3fa2c1`). */
export const ID_PATTERN = /^[a-z0-9]+(?:[-_.][a-z0-9]+)*$/;

/** Most words kept in a slug. */
const MAX_WORDS = 6;

/** Latin letters that Unicode does not decompose (NFKD leaves them whole), spelled out. */
const TRANSLITERATIONS: Readonly<Record<string, string>> = {
  ß: 'ss',
  ẞ: 'ss',
  æ: 'ae',
  Æ: 'ae',
  œ: 'oe',
  Œ: 'oe',
  ø: 'o',
  Ø: 'o',
  đ: 'd',
  Đ: 'd',
  ð: 'd',
  Ð: 'd',
  þ: 'th',
  Þ: 'th',
  ł: 'l',
  Ł: 'l',
  ı: 'i',
  ħ: 'h',
  Ħ: 'h',
  ŋ: 'ng',
  Ŋ: 'ng',
};

/**
 * The slug of a sentence: transliterated (NFKD, combining marks removed, a few undecomposable Latin letters
 * spelled out), lower-cased, every run of other characters turned into `-`, at most 6 words. Empty when the
 * sentence has no Latin letters or digits.
 */
export function slugOf(sentence: string): string {
  const latin = Array.from(sentence, (ch) => TRANSLITERATIONS[ch] ?? ch).join('');
  return latin
    .normalize('NFKD')
    .replace(/\p{M}/gu, '')
    .toLowerCase()
    .split(/[^a-z0-9]+/)
    .filter((word) => word !== '')
    .slice(0, MAX_WORDS)
    .join('-');
}

/** UTF-8 bytes of a string (lone surrogates become U+FFFD, as `TextEncoder` does). */
export function utf8Bytes(text: string): number[] {
  const bytes: number[] = [];
  for (let i = 0; i < text.length; i++) {
    let cp = text.charCodeAt(i);
    if (cp >= 0xd800 && cp <= 0xdbff) {
      const low = text.charCodeAt(i + 1);
      if (low >= 0xdc00 && low <= 0xdfff) {
        cp = 0x10000 + ((cp - 0xd800) << 10) + (low - 0xdc00);
        i++;
      } else {
        cp = 0xfffd;
      }
    } else if (cp >= 0xdc00 && cp <= 0xdfff) {
      cp = 0xfffd;
    }
    if (cp < 0x80) bytes.push(cp);
    else if (cp < 0x800) bytes.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
    else if (cp < 0x10000) bytes.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
    else bytes.push(0xf0 | (cp >> 18), 0x80 | ((cp >> 12) & 0x3f), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
  }
  return bytes;
}

/** FNV-1a, 32 bits, over the UTF-8 bytes of `text` (core has no crypto). */
export function fnv1a32(text: string): number {
  let hash = 0x811c9dc5;
  for (const byte of utf8Bytes(text)) {
    hash ^= byte;
    hash = Math.imul(hash, 0x01000193) >>> 0;
  }
  return hash >>> 0;
}

/** The fallback id for a sentence without Latin letters or digits: `n-` + the first 6 hex digits of FNV-1a 32 of the trimmed sentence. */
export function fallbackId(sentence: string): string {
  return `n-${fnv1a32(sentence.trim()).toString(16).padStart(8, '0').slice(0, 6)}`;
}

/** A stable id from the sentence (transliterated slug, at most 6 words; `n-<6 hex>` for non-Latin text), unused per `taken`. */
export function deriveId(naturalName: string, taken: (id: string) => boolean): string {
  const base = slugOf(naturalName) || fallbackId(naturalName);
  if (!taken(base)) return base;
  for (let i = 2; i < 1_000_000; i++) {
    const candidate = `${base}-${i}`;
    if (!taken(candidate)) return candidate;
  }
  throw new Error(`deriveId: every suffix of "${base}" is taken`);
}

/** Name helpers of the markup API (moved verbatim from `api.ts`; behaviour unchanged). */
import type { ParsedFile } from './types.js';

/** The declaration with this fully-qualified name, if the file declares it. */
export function findDecl(file: ParsedFile, fullName: string): ParsedFile['decls'][number] | undefined {
  return file.decls.find((d) => d.fullName === fullName);
}

/** How to write `fullName` inside `namespace` (outermost first): the shortest suffix that resolves to it there. */
export function relativeName(fullName: string, namespace: readonly string[]): string {
  for (let i = namespace.length; i > 0; i--) {
    const prefix = `${namespace.slice(0, i).join('.')}.`;
    if (fullName.startsWith(prefix) && fullName.length > prefix.length) return fullName.slice(prefix.length);
  }
  return fullName;
}

/**
 * Syntactic declarations of one file (docs/m1-plan.md section 6.1): a header parser
 * (`[docComment] [@[attrs]]* modifiers* keyword [name]`), namespace/section/mutual scopes, declaration spans and
 * value starts, and the header's imports. The semantic layer confirms all of it; this only has to be right for
 * files written in the usual style (telelean writes every command at column 0).
 *
 * Command starts (where a declaration's span ends): a line whose first character, at column 0, begins a comment
 * (`--`, `/-`, `/--`, `/-!`), `@[`, a `#` command, or one of the command words below (declaration keywords,
 * modifiers, `end`, `namespace`, `section`, `open`, …, `import`); also every line where a declaration header starts,
 * at any indentation (so indented namespaces and `mutual` blocks split correctly). `deriving` counts only as
 * `deriving instance` (a bare `deriving Repr` line is a clause of the inductive above it).
 */
import { canonicalName, nameComponents } from './lexer.js';
import { Lines } from './text.js';
import type { DeclInfo, DeclKeyword, LeanComment, LeanToken, LexResult, Span } from './types.js';

/** Declaration keywords (`class inductive` and `class abbrev` are recognised from `class`). */
export const DECL_KEYWORDS: ReadonlySet<string> = new Set([
  'axiom',
  'theorem',
  'lemma',
  'def',
  'abbrev',
  'opaque',
  'instance',
  'example',
  'inductive',
  'coinductive',
  'structure',
  'class',
  'mutual',
]);

/** Declaration modifiers, in any order. */
export const MODIFIERS: ReadonlySet<string> = new Set([
  'private',
  'public',
  'protected',
  'noncomputable',
  'unsafe',
  'partial',
  'nonrec',
  'scoped',
  'local',
  'meta',
]);

/** Words that start a command when they begin a line at column 0 (plan 6.1, plus a few commands it omits). */
const COMMAND_WORDS: ReadonlySet<string> = new Set([
  ...DECL_KEYWORDS,
  ...MODIFIERS,
  'end',
  'namespace',
  'section',
  'open',
  'export',
  'variable',
  'universe',
  'set_option',
  'attribute',
  'notation',
  'infix',
  'infixl',
  'infixr',
  'prefix',
  'postfix',
  'macro',
  'macro_rules',
  'syntax',
  'elab',
  'elab_rules',
  'deriving',
  'initialize',
  'builtin_initialize',
  'import',
  'declare_syntax_cat',
  'add_decl_doc',
  'include',
  'omit',
  'module',
  'prelude',
]);

const OPENERS: ReadonlySet<string> = new Set(['(', '[', '{', '⦃', '⟨', '⟦']);
const CLOSERS: ReadonlySet<string> = new Set([')', ']', '}', '⦄', '⟩', '⟧']);

/** A comment or a token, in text order (comments and tokens never overlap). */
export interface Item {
  start: number;
  end: number;
  comment?: LeanComment;
  token?: LeanToken;
  /** Index into the lexer's tokens, for a token. */
  tokenIndex?: number;
}

/** A `namespace`/`section`/`mutual` opener or an `end`. */
export interface ScopeEvent {
  kind: 'open' | 'close';
  scope?: 'namespace' | 'section' | 'mutual';
  /** The name as written after the keyword, if any (may be dotted). */
  name?: string;
  /** Offset of the keyword. */
  offset: number;
  /** Offset where the keyword's line ends (content end). */
  lineEnd: number;
  /** Index of the matching event in `scopes` (opener <-> its `end`). */
  match?: number;
}

export interface DeclScan {
  decls: DeclInfo[];
  scopes: ScopeEvent[];
  imports: string[];
  /** All comments and tokens in order. */
  items: Item[];
  /** Line numbers that start a command (sorted). */
  commandStartLines: number[];
}

interface Header {
  start: number;
  doc?: LeanComment;
  attributes: Span[];
  modifiers: string[];
  keyword: DeclKeyword;
  keywordSpan: Span;
  name?: LeanToken;
  /** Offset where the header ends (after the name, the keyword, or an instance priority). */
  end: number;
  /** Index of the first token after the header. */
  nextToken: number;
}

/** Merges comments and tokens into one sorted list. */
export function mergeItems(lex: LexResult): Item[] {
  const items: Item[] = [];
  let c = 0;
  let t = 0;
  const { comments, tokens } = lex;
  while (c < comments.length || t < tokens.length) {
    const comment = comments[c];
    const token = tokens[t];
    if (comment !== undefined && (token === undefined || comment.span.start < token.span.start)) {
      items.push({ start: comment.span.start, end: comment.span.end, comment });
      c++;
    } else if (token !== undefined) {
      items.push({ start: token.span.start, end: token.span.end, token, tokenIndex: t });
      t++;
    }
  }
  return items;
}

/** Index of the first element whose `start` is at least `offset` (binary search over a sorted array). */
export function firstAtOrAfter<T extends { start: number }>(list: readonly T[], offset: number): number {
  let lo = 0;
  let hi = list.length;
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if ((list[mid]?.start ?? Infinity) < offset) lo = mid + 1;
    else hi = mid;
  }
  return lo;
}

/** Index of the first token whose start is at least `offset`. */
function firstTokenAtOrAfter(tokens: readonly LeanToken[], offset: number): number {
  let lo = 0;
  let hi = tokens.length;
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if ((tokens[mid]?.span.start ?? Infinity) < offset) lo = mid + 1;
    else hi = mid;
  }
  return lo;
}

const isWord = (token: LeanToken | undefined, word: string) => token !== undefined && token.kind === 'ident' && token.text === word;
const isSymbol = (token: LeanToken | undefined, symbol: string) => token !== undefined && token.kind === 'symbol' && token.text === symbol;
const glued = (a: LeanToken | undefined, b: LeanToken | undefined) => a !== undefined && b !== undefined && a.span.end === b.span.start;

/** Scans the declarations, scopes and imports of a lexed file. */
export function scanDecls(text: string, lex: LexResult, lines: Lines): DeclScan {
  const { tokens } = lex;
  const items = mergeItems(lex);
  const commandStart = new Set<number>();
  const headers: Array<{ header: Header; line: number }> = [];
  const scopes: ScopeEvent[] = [];
  const scopeAt = new Map<number, number>();
  let consumedUntil = -1;

  const skipAttribute = (t: number): number => {
    // tokens[t] is `@`, tokens[t + 1] is `[`: skip to just after the matching `]`.
    let depth = 0;
    let k = t + 1;
    for (; k < tokens.length; k++) {
      const tok = tokens[k];
      if (isSymbol(tok, '[')) depth++;
      else if (isSymbol(tok, ']') && --depth === 0) return k + 1;
    }
    return k;
  };

  /** Parses a declaration header starting at a doc comment or at token index `t`. */
  const parseHeader = (doc: LeanComment | undefined, firstToken: number): Header | undefined => {
    let t = firstToken;
    const first = tokens[t];
    if (first === undefined) return undefined;
    // A second docstring before the keyword is a Lean parse error: no declaration.
    if (doc !== undefined && lex.comments.some((c) => c.kind === 'doc' && c.span.start > doc.span.start && c.span.start < first.span.start)) return undefined;
    const attributes: Span[] = [];
    while (isSymbol(tokens[t], '@') && isSymbol(tokens[t + 1], '[') && glued(tokens[t], tokens[t + 1])) {
      const end = skipAttribute(t);
      const last = tokens[end - 1];
      attributes.push({ start: tokens[t]?.span.start ?? 0, end: last?.span.end ?? text.length });
      t = end;
    }
    const modifiers: string[] = [];
    while (tokens[t]?.kind === 'ident' && MODIFIERS.has(tokens[t]?.text ?? '')) {
      modifiers.push(tokens[t]?.text ?? '');
      t++;
    }
    const kw = tokens[t];
    if (kw === undefined || kw.kind !== 'ident' || !DECL_KEYWORDS.has(kw.text)) return undefined;
    let keyword = kw.text as DeclKeyword;
    let keywordSpan: Span = kw.span;
    t++;
    if (keyword === 'class' && (isWord(tokens[t], 'inductive') || isWord(tokens[t], 'abbrev'))) {
      keyword = `class ${tokens[t]?.text ?? ''}` as DeclKeyword;
      keywordSpan = { start: kw.span.start, end: tokens[t]?.span.end ?? kw.span.end };
      t++;
    }
    let end = keywordSpan.end;
    if (keyword === 'instance' && isSymbol(tokens[t], '(') && isWord(tokens[t + 1], 'priority') && isSymbol(tokens[t + 2], ':') && isSymbol(tokens[t + 3], '=')) {
      let depth = 0;
      for (; t < tokens.length; t++) {
        const tok = tokens[t];
        if (isSymbol(tok, '(')) depth++;
        else if (isSymbol(tok, ')') && --depth === 0) {
          end = tok?.span.end ?? end;
          t++;
          break;
        }
      }
    }
    let name: LeanToken | undefined;
    if (keyword !== 'example' && keyword !== 'mutual' && tokens[t]?.kind === 'ident') {
      name = tokens[t];
      end = name?.span.end ?? end;
      t++;
    }
    const start = doc?.span.start ?? first.span.start;
    return { start, ...(doc ? { doc } : {}), attributes, modifiers, keyword, keywordSpan, ...(name ? { name } : {}), end, nextToken: t };
  };

  for (let k = 0; k < items.length; k++) {
    const item = items[k];
    if (item === undefined || !lines.isLineInitial(item.start)) continue;
    const line = lines.lineOf(item.start);
    const lineEnd = lines.contentEnd(line);
    const column0 = item.start === lines.start(line);

    // The first code item of the line: skip plain comments that end on this line when more follows on it.
    let m = k;
    for (;;) {
      const here = items[m];
      const next = items[m + 1];
      if (here?.comment === undefined || here.comment.kind === 'doc' || here.end > lineEnd || next === undefined || next.start >= lineEnd) break;
      m++;
    }
    const code = items[m];

    if (column0) {
      if (item.comment !== undefined) commandStart.add(line);
      else if (item.token !== undefined && item.tokenIndex !== undefined) {
        const tok = item.token;
        const next = tokens[item.tokenIndex + 1];
        if (tok.kind === 'ident' && COMMAND_WORDS.has(tok.text) && (tok.text !== 'deriving' || isWord(next, 'instance'))) commandStart.add(line);
        else if (isSymbol(tok, '@') && isSymbol(next, '[') && glued(tok, next)) commandStart.add(line);
        else if (isSymbol(tok, '#') && next?.kind === 'ident' && glued(tok, next)) commandStart.add(line);
      }
    }
    if (code === undefined) continue;

    // Declarations.
    if (code.start >= consumedUntil && (code.comment?.kind === 'doc' || code.token !== undefined)) {
      const header =
        code.comment !== undefined ? parseHeader(code.comment, firstTokenAtOrAfter(tokens, code.end)) : parseHeader(undefined, code.tokenIndex ?? tokens.length);
      if (header !== undefined) {
        headers.push({ header, line });
        commandStart.add(line);
        consumedUntil = header.end;
      }
    }

    // Scopes.
    if (code.token !== undefined && code.tokenIndex !== undefined) {
      let t = code.tokenIndex;
      while (true) {
        const tok = tokens[t];
        if (isSymbol(tok, '@') && isSymbol(tokens[t + 1], '[') && glued(tok, tokens[t + 1])) t = skipAttribute(t);
        else if (tok?.kind === 'ident' && MODIFIERS.has(tok.text)) t++;
        else break;
      }
      const word = tokens[t];
      const sameLine = (tok: LeanToken | undefined) => tok !== undefined && tok.span.start < lineEnd;
      const nameToken = tokens[t + 1]?.kind === 'ident' && sameLine(tokens[t + 1]) ? tokens[t + 1] : undefined;
      const prefixed = t !== code.tokenIndex;
      if (word !== undefined && sameLine(word)) {
        const base = { offset: word.span.start, lineEnd: lines.contentEnd(lines.lineOf(word.span.start)), ...(nameToken ? { name: nameToken.text } : {}) };
        if (isWord(word, 'namespace') && !prefixed) scopes.push({ kind: 'open', scope: 'namespace', ...base });
        else if (isWord(word, 'section')) scopes.push({ kind: 'open', scope: 'section', ...base });
        else if (isWord(word, 'end') && !prefixed) scopes.push({ kind: 'close', ...base });
        else if (isWord(word, 'mutual') && !prefixed) scopes.push({ kind: 'open', scope: 'mutual', offset: word.span.start, lineEnd: base.lineEnd });
      }
    }
  }

  // Match scopes and record the namespace in force after each event.
  const stack: Array<{ event: number; component?: string; scope: 'namespace' | 'section' | 'mutual' }> = [];
  const namespaceAfter: string[][] = [];
  scopes.forEach((event, index) => {
    if (event.kind === 'open') {
      const components = event.scope === 'mutual' || event.name === undefined ? [undefined] : nameComponents(event.name);
      for (const component of components) stack.push({ event: index, scope: event.scope ?? 'section', ...(component !== undefined ? { component } : {}) });
    } else {
      const top = stack[stack.length - 1];
      const count = top?.scope === 'mutual' || event.name === undefined ? 1 : nameComponents(event.name).length;
      let opener: number | undefined;
      for (let i = 0; i < count && stack.length > 0; i++) opener = stack.pop()?.event;
      if (opener !== undefined) {
        event.match = opener;
        const open = scopes[opener];
        if (open !== undefined) open.match = index;
      }
    }
    namespaceAfter.push(stack.filter((f) => f.scope === 'namespace' && f.component !== undefined).map((f) => canonicalName(f.component ?? '')));
    scopeAt.set(event.offset, index);
  });
  const namespaceAt = (offset: number): string[] => {
    // The last event before `offset`.
    let lo = 0;
    let hi = scopes.length;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if ((scopes[mid]?.offset ?? Infinity) < offset) lo = mid + 1;
      else hi = mid;
    }
    return lo === 0 ? [] : [...(namespaceAfter[lo - 1] ?? [])];
  };

  const commandStartLines = [...commandStart].sort((a, b) => a - b);
  const nextCommandLine = (afterLine: number): number => {
    let lo = 0;
    let hi = commandStartLines.length;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if ((commandStartLines[mid] ?? Infinity) <= afterLine) lo = mid + 1;
      else hi = mid;
    }
    return commandStartLines[lo] ?? lines.count;
  };

  const decls: DeclInfo[] = headers.map(({ header }) => {
    const headerLine = lines.lineOf(header.end);
    let endLine: number;
    const mutualOpen = header.keyword === 'mutual' ? scopeAt.get(header.keywordSpan.start) : undefined;
    const mutualClose = mutualOpen !== undefined ? scopes[mutualOpen]?.match : undefined;
    if (mutualClose !== undefined) {
      endLine = lines.lineOf(scopes[mutualClose]?.offset ?? header.end);
    } else {
      endLine = nextCommandLine(headerLine) - 1;
      while (endLine > headerLine && lines.isBlank(endLine)) endLine--;
    }
    const span: Span = { start: header.start, end: Math.max(header.end, lines.contentEnd(endLine)) };
    const namespace = namespaceAt(header.start);
    const decl: DeclInfo = {
      keyword: header.keyword,
      namespace,
      modifiers: header.modifiers,
      span,
      range: lines.range(span),
      keywordSpan: header.keywordSpan,
    };
    if (header.name !== undefined) {
      decl.name = header.name.text;
      decl.nameSpan = header.name.span;
      decl.fullName = resolveName(header.name.text, namespace);
    }
    if (header.attributes.length > 0) decl.attributes = header.attributes.map((a) => text.slice(a.start, a.end));
    if (header.doc !== undefined) {
      decl.docstring = text.slice(header.doc.body.start, header.doc.body.end).trim();
      decl.docSpan = header.doc.span;
    }
    const valueStart = findValueStart(text, tokens, header, span, lines);
    if (valueStart !== undefined) decl.valueStart = valueStart;
    return decl;
  });

  return { decls, scopes, imports: scanImports(tokens), items, commandStartLines };
}

/** `name` resolved against the enclosing namespaces (`_root_.` honoured), as Lean prints it. */
export function resolveName(name: string, namespace: readonly string[]): string {
  const written = canonicalName(name);
  if (written.startsWith('_root_.')) return written.slice('_root_.'.length);
  return namespace.length > 0 ? `${namespace.join('.')}.${written}` : written;
}

/**
 * The first top-level `:=`, `where` or `|` after the header (skipping brackets; strings and comments are not
 * tokens). `|` counts when it begins a line or the declaration is an inductive type (elsewhere it is notation such
 * as `|x|`). Axioms and `mutual` blocks have none.
 */
function findValueStart(text: string, tokens: readonly LeanToken[], header: Header, span: Span, lines: Lines): number | undefined {
  if (header.keyword === 'axiom' || header.keyword === 'mutual') return undefined;
  const inductive = header.keyword === 'inductive' || header.keyword === 'coinductive' || header.keyword === 'class inductive';
  let depth = 0;
  for (let t = header.nextToken; t < tokens.length; t++) {
    const tok = tokens[t];
    if (tok === undefined || tok.span.start >= span.end) break;
    if (tok.kind === 'symbol') {
      if (OPENERS.has(tok.text)) depth++;
      else if (CLOSERS.has(tok.text)) depth = Math.max(0, depth - 1);
      else if (depth === 0 && tok.text === ':' && isSymbol(tokens[t + 1], '=') && glued(tok, tokens[t + 1])) return tok.span.start;
      else if (depth === 0 && tok.text === '|' && (inductive || lines.isLineInitial(tok.span.start))) return tok.span.start;
    } else if (depth === 0 && isWord(tok, 'where')) {
      return tok.span.start;
    }
  }
  void text;
  return undefined;
}

/** Module names of the header's `import` lines (`module`, `prelude`, `public`/`meta` and `import all` allowed). */
function scanImports(tokens: readonly LeanToken[]): string[] {
  const imports: string[] = [];
  let t = 0;
  if (isWord(tokens[t], 'module')) t++;
  if (isWord(tokens[t], 'prelude')) t++;
  for (;;) {
    let u = t;
    if (isWord(tokens[u], 'public')) u++;
    if (isWord(tokens[u], 'meta')) u++;
    if (!isWord(tokens[u], 'import')) break;
    u++;
    if (isWord(tokens[u], 'all')) u++;
    const module = tokens[u];
    if (module === undefined || module.kind !== 'ident') break;
    imports.push(module.text);
    t = u + 1;
  }
  return imports;
}

/**
 * Syntactic declarations of one file (docs/m1-plan.md section 6.1): a header parser
 * (`[docComment] [@[attrs]]* modifiers* keyword [name]`), namespace/section/mutual scopes, declaration spans and
 * value starts, and the header's imports. The semantic layer confirms all of it; this only has to be right for
 * files written in the usual style (telelean writes every command at column 0).
 *
 * Command starts (where a declaration's span ends): a line whose first character, at column 0, begins a comment
 * (`--`, `/-`, `/--`, `/-!`), `@[`, a `#` command, or one of the command words below (declaration keywords,
 * modifiers, `end`, `namespace`, `section`, `open`, …, `import`); also every line where a declaration header starts,
 * at any indentation (so indented namespaces and `mutual` blocks split correctly). `deriving` counts only as
 * `deriving instance` (a bare `deriving Repr` line is a clause of the inductive above it).
 */
import { canonicalName, nameComponents } from './lexer.js';
import type { Lines } from './text.js';
import type { DeclInfo, DeclKeyword, LeanComment, LeanToken, LexResult, Span } from './types.js';

/** Declaration keywords (`class inductive` and `class abbrev` are recognised from `class`). */
export const DECL_KEYWORDS: ReadonlySet<string> = new Set([
  'axiom',
  'theorem',
  'lemma',
  'def',
  'abbrev',
  'opaque',
  'instance',
  'example',
  'inductive',
  'coinductive',
  'structure',
  'class',
  'mutual',
]);

/** Declaration modifiers, in any order. */
export const MODIFIERS: ReadonlySet<string> = new Set([
  'private',
  'public',
  'protected',
  'noncomputable',
  'unsafe',
  'partial',
  'nonrec',
  'scoped',
  'local',
  'meta',
]);

/** Words that start a command when they begin a line at column 0 (plan 6.1, plus a few commands it omits). */
const COMMAND_WORDS: ReadonlySet<string> = new Set([
  ...DECL_KEYWORDS,
  ...MODIFIERS,
  'end',
  'namespace',
  'section',
  'open',
  'export',
  'variable',
  'universe',
  'set_option',
  'attribute',
  'notation',
  'infix',
  'infixl',
  'infixr',
  'prefix',
  'postfix',
  'macro',
  'macro_rules',
  'syntax',
  'elab',
  'elab_rules',
  'deriving',
  'initialize',
  'builtin_initialize',
  'import',
  'declare_syntax_cat',
  'add_decl_doc',
  'include',
  'omit',
  'module',
  'prelude',
]);

const OPENERS: ReadonlySet<string> = new Set(['(', '[', '{', '⦃', '⟨', '⟦']);
const CLOSERS: ReadonlySet<string> = new Set([')', ']', '}', '⦄', '⟩', '⟧']);

/** A comment or a token, in text order (comments and tokens never overlap). */
export interface Item {
  start: number;
  end: number;
  comment?: LeanComment;
  token?: LeanToken;
  /** Index into the lexer's tokens, for a token. */
  tokenIndex?: number;
}

/** A `namespace`/`section`/`mutual` opener or an `end`. */
export interface ScopeEvent {
  kind: 'open' | 'close';
  scope?: 'namespace' | 'section' | 'mutual';
  /** The name as written after the keyword, if any (may be dotted). */
  name?: string;
  /** Offset of the keyword. */
  offset: number;
  /** Index of the matching event in `scopes` (opener <-> its `end`). */
  match?: number;
}

export interface DeclScan {
  decls: DeclInfo[];
  scopes: ScopeEvent[];
  imports: string[];
  /** All comments and tokens in order. */
  items: Item[];
}

interface Header {
  start: number;
  doc?: LeanComment;
  attributes: Span[];
  modifiers: string[];
  keyword: DeclKeyword;
  keywordSpan: Span;
  name?: LeanToken;
  /** Offset where the header ends (after the name, the keyword, or an instance priority). */
  end: number;
  /** Index of the first token after the header. */
  nextToken: number;
}

/** The number of leading elements of a sorted sequence for which `before(i)` holds (binary search). */
export function lowerBound(length: number, before: (index: number) => boolean): number {
  let lo = 0;
  let hi = length;
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if (before(mid)) lo = mid + 1;
    else hi = mid;
  }
  return lo;
}

/** Merges comments and tokens into one sorted list. */
export function mergeItems(lex: LexResult): Item[] {
  const items: Item[] = [];
  const { comments, tokens } = lex;
  let c = 0;
  let t = 0;
  while (c < comments.length || t < tokens.length) {
    const comment = comments[c];
    const token = tokens[t];
    if (comment !== undefined && (token === undefined || comment.span.start < token.span.start)) {
      items.push({ start: comment.span.start, end: comment.span.end, comment });
      c++;
    } else if (token !== undefined) {
      items.push({ start: token.span.start, end: token.span.end, token, tokenIndex: t });
      t++;
    }
  }
  return items;
}

const isWord = (token: LeanToken | undefined, word: string) => token !== undefined && token.kind === 'ident' && token.text === word;
const isSymbol = (token: LeanToken | undefined, symbol: string) => token !== undefined && token.kind === 'symbol' && token.text === symbol;
const glued = (a: LeanToken | undefined, b: LeanToken | undefined) => a !== undefined && b !== undefined && a.span.end === b.span.start;

/** Scans the declarations, scopes and imports of a lexed file. */
export function scanDecls(text: string, lex: LexResult, lines: Lines): DeclScan {
  const { tokens, comments } = lex;
  const items = mergeItems(lex);
  const commandStart = new Set<number>();
  const headers: Header[] = [];
  const scopes: ScopeEvent[] = [];
  let consumedUntil = -1;

  const firstTokenAtOrAfter = (offset: number) => lowerBound(tokens.length, (i) => (tokens[i]?.span.start ?? Infinity) < offset);
  const isAttributeStart = (t: number) => isSymbol(tokens[t], '@') && isSymbol(tokens[t + 1], '[') && glued(tokens[t], tokens[t + 1]);
  /** From `@` at `t`: the index just after the matching `]`. */
  const skipAttribute = (t: number): number => {
    let depth = 0;
    let k = t + 1;
    for (; k < tokens.length; k++) {
      const tok = tokens[k];
      if (isSymbol(tok, '[')) depth++;
      else if (isSymbol(tok, ']') && --depth === 0) return k + 1;
    }
    return k;
  };

  /** Parses a declaration header made of an optional doc comment and the tokens from index `firstToken`. */
  const parseHeader = (doc: LeanComment | undefined, firstToken: number): Header | undefined => {
    let t = firstToken;
    const first = tokens[t];
    if (first === undefined) return undefined;
    if (doc !== undefined) {
      // A second docstring before the keyword is a Lean parse error: no declaration.
      const from = lowerBound(comments.length, (i) => (comments[i]?.span.start ?? Infinity) <= doc.span.start);
      for (let c = from; c < comments.length && (comments[c]?.span.start ?? Infinity) < first.span.start; c++) {
        if (comments[c]?.kind === 'doc') return undefined;
      }
    }
    const attributes: Span[] = [];
    while (isAttributeStart(t)) {
      const end = skipAttribute(t);
      attributes.push({ start: tokens[t]?.span.start ?? 0, end: tokens[end - 1]?.span.end ?? text.length });
      t = end;
    }
    const modifiers: string[] = [];
    for (let tok = tokens[t]; tok?.kind === 'ident' && MODIFIERS.has(tok.text); tok = tokens[++t]) modifiers.push(tok.text);
    const kw = tokens[t];
    if (kw === undefined || kw.kind !== 'ident' || !DECL_KEYWORDS.has(kw.text)) return undefined;
    let keyword = kw.text as DeclKeyword;
    let keywordSpan: Span = kw.span;
    t++;
    const second = tokens[t];
    if (keyword === 'class' && second !== undefined && (isWord(second, 'inductive') || isWord(second, 'abbrev'))) {
      keyword = `class ${second.text}` as DeclKeyword;
      keywordSpan = { start: kw.span.start, end: second.span.end };
      t++;
    }
    let end = keywordSpan.end;
    if (keyword === 'instance' && isSymbol(tokens[t], '(') && isWord(tokens[t + 1], 'priority') && isSymbol(tokens[t + 2], ':') && isSymbol(tokens[t + 3], '=')) {
      let depth = 0;
      for (; t < tokens.length; t++) {
        const tok = tokens[t];
        if (isSymbol(tok, '(')) depth++;
        else if (tok !== undefined && isSymbol(tok, ')') && --depth === 0) {
          end = tok.span.end;
          t++;
          break;
        }
      }
    }
    let name: LeanToken | undefined;
    const candidate = tokens[t];
    if (keyword !== 'example' && keyword !== 'mutual' && candidate?.kind === 'ident') {
      name = candidate;
      end = candidate.span.end;
      t++;
    }
    return {
      start: doc?.span.start ?? first.span.start,
      ...(doc ? { doc } : {}),
      attributes,
      modifiers,
      keyword,
      keywordSpan,
      ...(name ? { name } : {}),
      end,
      nextToken: t,
    };
  };

  let previousEndLine = -1;
  for (let k = 0; k < items.length; k++) {
    const item = items[k];
    if (item === undefined) continue;
    const line = lines.lineOf(item.start);
    const lineInitial = line !== previousEndLine;
    previousEndLine = lines.lineOf(item.end);
    if (!lineInitial) continue;
    const lineEnd = lines.contentEnd(line);

    // The line's first code item: skip plain comments that end on this line when more follows on it.
    let m = k;
    for (;;) {
      const here = items[m];
      const next = items[m + 1];
      if (here?.comment === undefined || here.comment.kind === 'doc' || here.end > lineEnd || next === undefined || next.start >= lineEnd) break;
      m++;
    }
    const code = items[m];

    if (item.start === lines.start(line)) {
      if (item.comment !== undefined) {
        commandStart.add(line);
      } else if (item.token !== undefined && item.tokenIndex !== undefined) {
        const tok = item.token;
        const next = tokens[item.tokenIndex + 1];
        const word = tok.kind === 'ident' && COMMAND_WORDS.has(tok.text) && (tok.text !== 'deriving' || isWord(next, 'instance'));
        const hashCommand = isSymbol(tok, '#') && next?.kind === 'ident' && glued(tok, next);
        if (word || hashCommand || isAttributeStart(item.tokenIndex)) commandStart.add(line);
      }
    }
    if (code === undefined) continue;

    if (code.start >= consumedUntil && (code.comment?.kind === 'doc' || code.tokenIndex !== undefined)) {
      const header =
        code.comment !== undefined ? parseHeader(code.comment, firstTokenAtOrAfter(code.end)) : parseHeader(undefined, code.tokenIndex ?? tokens.length);
      if (header !== undefined) {
        headers.push(header);
        commandStart.add(line);
        consumedUntil = header.end;
      }
    }

    if (code.tokenIndex !== undefined) {
      let t = code.tokenIndex;
      for (;;) {
        const tok = tokens[t];
        if (isAttributeStart(t)) t = skipAttribute(t);
        else if (tok?.kind === 'ident' && MODIFIERS.has(tok.text)) t++;
        else break;
      }
      const word = tokens[t];
      const after = tokens[t + 1];
      if (word !== undefined && word.span.start < lineEnd) {
        const prefixed = t !== code.tokenIndex;
        const name = after !== undefined && after.kind === 'ident' && after.span.start < lineEnd ? { name: after.text } : {};
        if (isWord(word, 'namespace') && !prefixed) scopes.push({ kind: 'open', scope: 'namespace', offset: word.span.start, ...name });
        else if (isWord(word, 'section')) scopes.push({ kind: 'open', scope: 'section', offset: word.span.start, ...name });
        else if (isWord(word, 'end') && !prefixed) scopes.push({ kind: 'close', offset: word.span.start, ...name });
        else if (isWord(word, 'mutual') && !prefixed) scopes.push({ kind: 'open', scope: 'mutual', offset: word.span.start });
      }
    }
  }

  // Match openers with their `end`s and record the namespace in force after each event.
  const stack: Array<{ event: number; scope: 'namespace' | 'section' | 'mutual'; component?: string }> = [];
  const namespaceAfter: string[][] = [];
  scopes.forEach((event, index) => {
    if (event.kind === 'open') {
      const scope = event.scope ?? 'section';
      const components = scope === 'mutual' || event.name === undefined ? [undefined] : nameComponents(event.name);
      for (const component of components) stack.push({ event: index, scope, ...(component !== undefined ? { component } : {}) });
    } else {
      const top = stack[stack.length - 1];
      const count = top?.scope === 'mutual' || event.name === undefined ? 1 : nameComponents(event.name).length;
      let opener: number | undefined;
      for (let i = 0; i < count && stack.length > 0; i++) opener = stack.pop()?.event;
      const open = opener !== undefined ? scopes[opener] : undefined;
      if (opener !== undefined && open !== undefined) {
        event.match = opener;
        open.match = index;
      }
    }
    namespaceAfter.push(stack.filter((f) => f.scope === 'namespace' && f.component !== undefined).map((f) => canonicalName(f.component ?? '')));
  });
  const namespaceAt = (offset: number): string[] => {
    const count = lowerBound(scopes.length, (i) => (scopes[i]?.offset ?? Infinity) < offset);
    return count === 0 ? [] : [...(namespaceAfter[count - 1] ?? [])];
  };

  const commandStartLines = [...commandStart].sort((a, b) => a - b);
  const nextCommandLine = (afterLine: number): number =>
    commandStartLines[lowerBound(commandStartLines.length, (i) => (commandStartLines[i] ?? Infinity) <= afterLine)] ?? lines.count;

  const decls = headers.map((header): DeclInfo => {
    const headerLine = lines.lineOf(header.end);
    const mutualOpen = header.keyword === 'mutual' ? scopes.findIndex((e) => e.offset === header.keywordSpan.start) : -1;
    const mutualClose = mutualOpen >= 0 ? scopes[mutualOpen]?.match : undefined;
    let endLine: number;
    if (mutualClose !== undefined) {
      endLine = lines.lineOf(scopes[mutualClose]?.offset ?? header.end);
    } else {
      endLine = nextCommandLine(headerLine) - 1;
      while (endLine > headerLine && lines.isBlank(endLine)) endLine--;
    }
    const span: Span = { start: header.start, end: Math.max(header.end, lines.contentEnd(endLine)) };
    const namespace = namespaceAt(header.start);
    const decl: DeclInfo = { keyword: header.keyword, namespace, modifiers: header.modifiers, span, range: lines.range(span), keywordSpan: header.keywordSpan };
    if (header.name !== undefined) {
      decl.name = header.name.text;
      decl.fullName = resolveName(header.name.text, namespace);
      decl.nameSpan = header.name.span;
    }
    if (header.attributes.length > 0) decl.attributes = header.attributes.map((a) => text.slice(a.start, a.end));
    if (header.doc !== undefined) {
      decl.docstring = text.slice(header.doc.body.start, header.doc.body.end).trim();
      decl.docSpan = header.doc.span;
    }
    const valueStart = findValueStart(tokens, header, span, lines);
    if (valueStart !== undefined) decl.valueStart = valueStart;
    return decl;
  });

  return { decls, scopes, imports: scanImports(tokens), items };
}

/** `name` resolved against the enclosing namespaces (`_root_.` honoured), as Lean prints it. */
export function resolveName(name: string, namespace: readonly string[]): string {
  const written = canonicalName(name);
  if (written.startsWith('_root_.')) return written.slice('_root_.'.length);
  return namespace.length > 0 ? `${namespace.join('.')}.${written}` : written;
}

/**
 * The first top-level `:=`, `where` or `|` after the header (skipping brackets; strings and comments are not
 * tokens). `|` counts when it begins a line or the declaration is an inductive type (elsewhere it may be notation
 * such as `|x|`). Axioms and `mutual` blocks have none.
 */
function findValueStart(tokens: readonly LeanToken[], header: Header, span: Span, lines: Lines): number | undefined {
  if (header.keyword === 'axiom' || header.keyword === 'mutual') return undefined;
  const inductive = header.keyword === 'inductive' || header.keyword === 'coinductive' || header.keyword === 'class inductive';
  let depth = 0;
  for (let t = header.nextToken; t < tokens.length; t++) {
    const tok = tokens[t];
    if (tok === undefined || tok.span.start >= span.end) break;
    if (tok.kind === 'symbol') {
      if (OPENERS.has(tok.text)) depth++;
      else if (CLOSERS.has(tok.text)) depth = Math.max(0, depth - 1);
      else if (depth === 0 && tok.text === ':' && isSymbol(tokens[t + 1], '=') && glued(tok, tokens[t + 1])) return tok.span.start;
      else if (depth === 0 && tok.text === '|' && (inductive || lines.isLineInitial(tok.span.start))) return tok.span.start;
    } else if (depth === 0 && isWord(tok, 'where')) {
      return tok.span.start;
    }
  }
  return undefined;
}

/** Module names of the header's `import` lines (`module`, `prelude`, `public`/`meta` and `import all` allowed). */
function scanImports(tokens: readonly LeanToken[]): string[] {
  const imports: string[] = [];
  let t = 0;
  if (isWord(tokens[t], 'module')) t++;
  if (isWord(tokens[t], 'prelude')) t++;
  for (;;) {
    let u = t;
    if (isWord(tokens[u], 'public')) u++;
    if (isWord(tokens[u], 'meta')) u++;
    if (!isWord(tokens[u], 'import')) break;
    u++;
    if (isWord(tokens[u], 'all')) u++;
    const module = tokens[u];
    if (module === undefined || module.kind !== 'ident') break;
    imports.push(module.text);
    t = u + 1;
  }
  return imports;
}

/**
 * `parseLeanFile`: telelean blocks (markup v1, 03 section 3) with their diagnostics, the file's declarations and
 * imports, and each block's binding. Rules of 02/03 that differ from the research prototype: `type:` is canonical
 * and `kind:` a silent alias; there is no DEFINITION kind; a missing version marker means v1 without a diagnostic;
 * `premises:` is allowed on every type; a block without `id:` gets a derived id (TL112).
 */
import type { Evidential, NodeType, Severity, Stance } from '../model.js';
import { EVIDENTIALS, STANCES } from '../model.js';
import { firstAtOrAfter, lowerBound, scanDecls, type DeclScan, type Item } from './decls.js';
import { deriveId, ID_PATTERN } from './ids.js';
import { isLeanName, lexLean } from './lexer.js';
import { detectEol, Lines } from './text.js';
import {
  FIELD_ORDER,
  SUPPORTED_MARKUP_VERSIONS,
  type BlockBinding,
  type BlockFields,
  type FieldLine,
  type KnownFieldKey,
  type LeanComment,
  type MarkupBlock,
  type MarkupDiagnostic,
  type ParsedFile,
  type Span,
} from './types.js';
import { parseFieldValue, splitList } from './values.js';

/** `@@ telelean` with an optional `vN` (the first non-blank line of a block). */
const MARKER = /^@@[ \t]*telelean(?:[ \t]+v(\d+))?[ \t]*$/;
/** `key: value`, where key = lcid { "." lcid } (dotted keys are extensions). */
const FIELD = /^([a-z][a-z0-9_]*(?:\.[a-z][a-z0-9_]*)*)[ \t]*:(.*)$/;
const TAG = /^[A-Za-z0-9][A-Za-z0-9_./-]*$/;
const TOKEN = /^[A-Za-z0-9][A-Za-z0-9_.:+-]*$/;
const DATE = /^(\d{4})-(\d{2})-(\d{2})$/;

const NODE_TYPES: readonly NodeType[] = ['ASSUMPTION', 'DERIVATION', 'GOAL'];
const LIST_KEYS: ReadonlySet<string> = new Set(['premises', 'lean', 'tags']);
const KNOWN_KEYS: ReadonlySet<string> = new Set(FIELD_ORDER);

/** Normalised key: `kind` is an alias of `type`. */
export function normaliseKey(key: string): string {
  return key === 'kind' ? 'type' : key;
}

/** True for keys with a meaning in v1. */
export function isKnownFieldKey(key: string): key is KnownFieldKey {
  return KNOWN_KEYS.has(key);
}

interface Segment {
  start: number;
  end: number;
}

/** The lines of `text[start, end)`, each without its line break (the last one ends at `end`). */
function segments(text: string, start: number, end: number): Segment[] {
  const out: Segment[] = [];
  let p = start;
  for (;;) {
    const nl = text.indexOf('\n', p);
    if (nl < 0 || nl >= end) {
      out.push({ start: p, end });
      return out;
    }
    out.push({ start: p, end: nl > p && text.charCodeAt(nl - 1) === 0x0d ? nl - 1 : nl });
    p = nl + 1;
  }
}

const indentWidth = (line: string) => line.length - line.trimStart().length;

/** One block before binding and id derivation. */
interface RawBlock {
  comment: LeanComment;
  version: number;
  fields: BlockFields;
  extensions: Record<string, string[]>;
  writtenId?: string;
  body?: string;
  bodySpan?: Span;
  markerSpan: Span;
  lines: FieldLine[];
}

class Diagnostics {
  readonly list: MarkupDiagnostic[] = [];
  constructor(private readonly lines: Lines) {}
  add(code: string, severity: Severity, message: string, span: Span, nodeId?: string): MarkupDiagnostic {
    const diagnostic: MarkupDiagnostic = { code, severity, message, span, range: this.lines.range(span), ...(nodeId !== undefined ? { nodeId } : {}) };
    this.list.push(diagnostic);
    return diagnostic;
  }
}

/**
 * Reads the block in `comment` if its first non-blank line is the marker. Doc and module-doc comments with a marker
 * get TL009 and are ignored. Field diagnostics are collected into `pending` (their node id is known only later).
 */
function readBlock(text: string, comment: LeanComment, diags: Diagnostics, pending: MarkupDiagnostic[]): RawBlock | undefined {
  const segs = segments(text, comment.body.start, comment.body.end);
  let s = 0;
  while (s < segs.length && text.slice(segs[s]?.start, segs[s]?.end).trim() === '') s++;
  const markerSeg = segs[s];
  if (markerSeg === undefined) return undefined;
  const markerLine = text.slice(markerSeg.start, markerSeg.end);
  const markerMatch = MARKER.exec(markerLine.trim());
  if (!markerMatch) return undefined;
  const markerStart = markerSeg.start + indentWidth(markerLine);
  const markerSpan: Span = { start: markerStart, end: markerStart + markerLine.trim().length };
  if (comment.kind === 'doc' || comment.kind === 'moddoc') {
    const opener = comment.kind === 'doc' ? '/--' : '/-!';
    diags.add('TL009', 'warning', `This telelean block is inside a doc comment (\`${opener}\`), so it is ignored: use a plain \`/- … -/\` comment.`, markerSpan);
    return undefined;
  }
  const version = markerMatch[1] !== undefined ? Number.parseInt(markerMatch[1], 10) : 1;
  const block: RawBlock = { comment, version, fields: {}, extensions: {}, markerSpan, lines: [] };
  const note = (code: string, severity: Severity, message: string, span: Span) => {
    const d: MarkupDiagnostic = { code, severity, message, span, range: { start: { line: 0, character: 0 }, end: { line: 0, character: 0 } } };
    pending.push(d);
  };
  if (comment.unterminated) note('TL010', 'error', 'Unterminated comment: this block swallows the rest of the file (Lean reports "unterminated comment"). Close it with `-/`.', { start: comment.span.start, end: Math.min(comment.span.start + 2, text.length) });
  if (!SUPPORTED_MARKUP_VERSIONS.includes(version)) {
    note('TL008', 'warning', `Markup v${version} is newer than this telelean understands (v${SUPPORTED_MARKUP_VERSIONS.join(', v')}); the block is shown, unknown fields are kept.`, markerSpan);
  }
  const seen = new Set<string>();
  for (let i = s + 1; i < segs.length; i++) {
    const seg = segs[i];
    if (seg === undefined) continue;
    const raw = text.slice(seg.start, seg.end);
    const content = raw.trim();
    if (content === '') continue;
    const contentStart = seg.start + indentWidth(raw);
    const lineSpan: Span = { start: seg.start, end: seg.end };
    if (content === '---') {
      const rest = segs.slice(i + 1);
      const restText = rest.map((r) => text.slice(r.start, r.end));
      let first = 0;
      let last = restText.length - 1;
      while (first <= last && (restText[first] ?? '').trim() === '') first++;
      while (last >= first && (restText[last] ?? '').trim() === '') last--;
      const kept = restText.slice(first, last + 1);
      const indent = Math.min(...kept.filter((l) => l.trim() !== '').map(indentWidth));
      const body = kept.map((l) => l.slice(Math.min(indent, indentWidth(l)))).join('\n');
      if (body !== '') block.body = body;
      const lastSeg = last >= first ? rest[last] : undefined;
      block.bodySpan = { start: seg.start, end: lastSeg !== undefined ? lastSeg.end : seg.end };
      break;
    }
    const match = FIELD.exec(content);
    if (!match || match[1] === undefined || match[2] === undefined) {
      note('TL001', 'error', `Malformed line (expected \`key: value\`): ${JSON.stringify(content.length > 60 ? `${content.slice(0, 60)}…` : content)}`, lineSpan);
      continue;
    }
    const writtenKey = match[1];
    const key = normaliseKey(writtenKey);
    const colon = content.indexOf(':', writtenKey.length);
    const afterColon = content.slice(colon + 1);
    const value = afterColon.trim();
    const valueStart = contentStart + colon + 1 + indentWidth(afterColon);
    const valueSpan: Span = { start: valueStart, end: valueStart + value.length };
    block.lines.push({ key, writtenKey, span: lineSpan, valueSpan, raw: value });
    if (key.includes('.') || !isKnownFieldKey(key)) {
      if (!key.includes('.')) note('TL002', 'warning', `Unknown field \`${key}\` (kept as written; use a dotted key such as \`mytool.${key}\` for tool data).`, lineSpan);
      (block.extensions[key] ??= []).push(value);
      continue;
    }
    if (seen.has(key) && !LIST_KEYS.has(key)) {
      note('TL005', 'error', `Duplicate field \`${key}\` (the first value is used).`, lineSpan);
      continue;
    }
    seen.add(key);
    interpretField(block, key, value, lineSpan, note);
  }
  return block;
}

/** Stores one known field's value in `block.fields`, reporting TL004/TL019 through `note`. */
function interpretField(
  block: RawBlock,
  key: KnownFieldKey,
  raw: string,
  span: Span,
  note: (code: string, severity: Severity, message: string, span: Span) => void,
): void {
  const fields = block.fields;
  if (LIST_KEYS.has(key)) {
    const { items, errors } = splitList(raw);
    for (const error of errors) note('TL004', 'error', `${key}: ${error}`, span);
    const valid = key === 'premises' ? (x: string) => ID_PATTERN.test(x) : key === 'lean' ? isLeanName : (x: string) => TAG.test(x);
    const what = key === 'premises' ? 'node id' : key === 'lean' ? 'Lean name' : 'tag';
    const good: string[] = [];
    for (const item of items) {
      if (valid(item)) good.push(item);
      else note('TL004', 'error', `${key}: ${JSON.stringify(item)} is not a valid ${what}.`, span);
    }
    if (key === 'premises') fields.premises = [...(fields.premises ?? []), ...good];
    else if (key === 'lean') fields.lean = [...(fields.lean ?? []), ...good];
    else fields.tags = [...(fields.tags ?? []), ...good];
    return;
  }
  const parsed = parseFieldValue(raw);
  if (!parsed.ok) {
    note('TL004', 'error', `${key}: ${parsed.error}.`, span);
    return;
  }
  const value = parsed.value;
  const invalid = (expected: string) => note('TL004', 'error', `Invalid ${key} ${JSON.stringify(value)} (expected ${expected}).`, span);
  switch (key) {
    case 'id':
      if (value === '') invalid('a node id');
      else {
        if (!ID_PATTERN.test(value)) invalid('lower-case letters and digits joined by "-", "_" or "."');
        block.writtenId = value;
      }
      return;
    case 'type': {
      const upper = value.toUpperCase();
      const type = NODE_TYPES.find((t) => t === upper);
      if (type === undefined) invalid(NODE_TYPES.join(', '));
      else {
        if (value !== upper) note('TL019', 'hint', `The type is written in upper case: ${upper}.`, span);
        fields.type = type;
      }
      return;
    }
    case 'natural_name':
      if (/[\r\n]/.test(value)) note('TL004', 'warning', 'natural_name should be a single line.', span);
      fields.naturalName = value;
      return;
    case 'rationale':
      fields.rationale = value;
      return;
    case 'stance':
      if ((STANCES as readonly string[]).includes(value)) fields.stance = value as Stance;
      else invalid(STANCES.join(', '));
      return;
    case 'source':
      if ((EVIDENTIALS as readonly string[]).includes(value)) fields.source = value as Evidential;
      else invalid(EVIDENTIALS.join(', '));
      return;
    case 'asserted': {
      const date = DATE.exec(value);
      const month = Number(date?.[2]);
      const day = Number(date?.[3]);
      if (date && month >= 1 && month <= 12 && day >= 1 && day <= 31) fields.asserted = value;
      else invalid('a date YYYY-MM-DD');
      return;
    }
    case 'supersedes':
    case 'refines':
      if (ID_PATTERN.test(value)) fields[key] = value;
      else invalid('a node id');
      return;
    case 'origin':
    case 'worded_by':
      if (value === 'user' || value === 'agent') {
        if (key === 'origin') fields.origin = value;
        else fields.wordedBy = value;
      } else invalid('user or agent');
      return;
    case 'session':
      if (TOKEN.test(value)) fields.session = value;
      else invalid('letters, digits and _ . : + -');
      return;
    default:
      return;
  }
}

/** What follows a block: the declaration it binds to by adjacency, or one after a blank line. */
function findFollowingDecl(text: string, end: number, scan: DeclScan, blockComments: ReadonlySet<LeanComment>): { adjacent?: number; gap?: number } {
  const { items, decls } = scan;
  let p = end;
  for (;;) {
    let q = p;
    let newlines = 0;
    for (; q < text.length; q++) {
      const c = text.charCodeAt(q);
      if (c === 0x0a) newlines++;
      else if (c !== 0x20 && c !== 0x09 && c !== 0x0d) break;
    }
    if (q >= text.length) return {};
    const blank = newlines >= 2;
    const item: Item | undefined = items[firstAtOrAfter(items, q)];
    if (item === undefined || item.start !== q) return {};
    if (item.comment !== undefined && blockComments.has(item.comment)) return {};
    if (item.comment !== undefined && (item.comment.kind === 'line' || item.comment.kind === 'block')) {
      if (blank) return {};
      p = item.end;
      continue;
    }
    // A doc comment or a token: is it inside a declaration's header (between its start and its keyword)?
    const index = lowerBound(decls.length, (i) => (decls[i]?.span.start ?? Infinity) <= q) - 1;
    const decl = decls[index];
    if (decl === undefined || q > decl.keywordSpan.start) return {};
    return blank ? { gap: index } : { adjacent: index };
  }
}

/**
 * Parses one model file: telelean blocks (with markup diagnostics TL001-TL019, TL112), syntactic declarations,
 * imports, and each block's binding (pinned `lean:` > adjacency; blank line, EOF or another block = code-less).
 * Never throws on bad input: problems become diagnostics.
 */
export function parseLeanFile(path: string, text: string): ParsedFile {
  const eol = detectEol(text);
  const lines = new Lines(text);
  try {
    return parse(path, text, eol, lines);
  } catch (error) {
    const detail = error instanceof Error ? error.message : String(error);
    const span: Span = { start: 0, end: 0 };
    return {
      path,
      text,
      eol,
      blocks: [],
      decls: [],
      imports: [],
      diagnostics: [{ code: 'TL001', severity: 'error', message: `telelean could not read this file (internal error: ${detail}).`, span, range: lines.range(span) }],
    };
  }
}

function parse(path: string, text: string, eol: '\n' | '\r\n', lines: Lines): ParsedFile {
  const lex = lexLean(text);
  const scan = scanDecls(text, lex, lines);
  const diags = new Diagnostics(lines);
  const raws: Array<{ raw: RawBlock; pending: MarkupDiagnostic[] }> = [];
  for (const comment of lex.comments) {
    if (comment.kind === 'line') continue;
    const pending: MarkupDiagnostic[] = [];
    const raw = readBlock(text, comment, diags, pending);
    if (raw !== undefined) raws.push({ raw, pending });
  }

  // Ids: written ids are kept; id-less blocks get a derived id, unique within the file.
  const taken = new Set(raws.map(({ raw }) => raw.writtenId).filter((id): id is string => id !== undefined));
  const blockComments = new Set(raws.map(({ raw }) => raw.comment));
  const blocks: MarkupBlock[] = raws.map(({ raw, pending }) => {
    const idWritten = raw.writtenId !== undefined;
    const id = raw.writtenId ?? deriveId(raw.fields.naturalName ?? '', (candidate) => taken.has(candidate));
    taken.add(id);
    for (const d of pending) diags.add(d.code, d.severity, d.message, d.span, id);
    if (!idWritten) {
      diags.add('TL112', 'info', `This block has no \`id:\`; telelean uses \`${id}\` and writes it into the block on its next edit.`, raw.markerSpan, id);
    }
    const missing = [raw.lines.some((l) => l.key === 'type') ? undefined : 'type', raw.lines.some((l) => l.key === 'natural_name') ? undefined : 'natural_name'].filter(
      (k): k is string => k !== undefined,
    );
    for (const key of missing) diags.add('TL003', 'error', `Missing required field \`${key}:\`.`, raw.markerSpan, id);
    if (raw.fields.type === 'ASSUMPTION' && raw.fields.rationale === undefined) {
      diags.add('TL011', 'info', 'This assumption has no `rationale:` yet (why do you hold it?).', raw.markerSpan, id);
    }
    const block: MarkupBlock = {
      id,
      idWritten,
      version: raw.version,
      fields: raw.fields,
      extensions: raw.extensions,
      span: raw.comment.span,
      range: lines.range(raw.comment.span),
      markerSpan: raw.markerSpan,
      lines: raw.lines,
      binding: { mode: 'none' },
    };
    if (raw.body !== undefined) block.body = raw.body;
    if (raw.bodySpan !== undefined) block.bodySpan = raw.bodySpan;
    block.binding = bindBlock(text, block, scan, blockComments, diags);
    return block;
  });

  diags.list.sort((a, b) => a.span.start - b.span.start);
  return { path, text, eol, blocks, decls: scan.decls, imports: scan.imports, diagnostics: diags.list };
}

/** A pinned `lean:` field wins; otherwise Go-style adjacency (03 section 3.1; docs/m1-plan.md 6.1). */
function bindBlock(text: string, block: MarkupBlock, scan: DeclScan, blockComments: ReadonlySet<LeanComment>, diags: Diagnostics): BlockBinding {
  const following = block.span.end < text.length ? findFollowingDecl(text, block.span.end, scan, blockComments) : {};
  const position: Pick<BlockBinding, 'adjacentDecl' | 'gapDecl'> = {
    ...(following.adjacent !== undefined ? { adjacentDecl: following.adjacent } : {}),
    ...(following.gap !== undefined ? { gapDecl: following.gap } : {}),
  };
  const pinned = block.fields.lean;
  if (pinned !== undefined && pinned.length > 0) {
    const names = pinned.map((name) => (name.startsWith('_root_.') ? name.slice('_root_.'.length) : name));
    return { mode: 'pinned', statement: names[0], pinned: names, ...position };
  }
  const adjacent = following.adjacent !== undefined ? scan.decls[following.adjacent] : undefined;
  if (adjacent !== undefined) {
    if (adjacent.fullName !== undefined && adjacent.keyword !== 'example' && adjacent.keyword !== 'mutual') {
      return { mode: 'adjacent', statement: adjacent.fullName, ...position };
    }
    const what =
      adjacent.keyword === 'example'
        ? '`example` declarations are not added to the environment'
        : adjacent.keyword === 'mutual'
          ? 'a `mutual` block holds several declarations: name one with `lean:`'
          : 'this declaration has no name: name it, or pin it with `lean:`';
    diags.add('TL014', 'warning', `The declaration after this block cannot be bound (${what}); the node stays code-less.`, block.markerSpan, block.id);
    return { mode: 'none', ...position };
  }
  const gap = following.gap !== undefined ? scan.decls[following.gap] : undefined;
  if (gap?.name !== undefined && gap.keyword !== 'example' && gap.keyword !== 'mutual') {
    diags.add(
      'TL013',
      'hint',
      `This node is code-less, but \`${gap.name}\` follows after a blank line: remove the blank line to attach it.`,
      block.markerSpan,
      block.id,
    );
  }
  return { mode: 'none', ...position };
}

