    const next = endLine + 1;
    const blankFollows = next < lines.count && lines.start(next) < text.length && lines.isBlank(next);
    if (previousBlank && blankFollows) end = lines.fullEnd(next);
    else if (end >= text.length && startLine > 0 && lines.isBlank(startLine - 1)) start = lines.start(startLine - 1);
  } else if (restBlank) {
    while (start > 0 && (text.charCodeAt(start - 1) === 0x20 || text.charCodeAt(start - 1) === 0x09)) start--;
    end = lines.contentEnd(endLine);
  } else {
    while (end < text.length && (text.charCodeAt(end) === 0x20 || text.charCodeAt(end) === 0x09)) end++;
  }
  return { span: { start, end }, newText: '' };
}

/** Removes a block comment and the line break after it (and one blank line, so spacing stays tidy). */
export function removeBlockEdits(file: ParsedFile, block: MarkupBlock): TextEdit[] {
  return [deletionEdit(file.text, block.span)];
}

/**
 * Inserts `blockText` (its line breaks converted to `eol`) at `offset` — a line start, or the end of the text —
 * with exactly one blank line between it and each non-blank neighbour (existing blank lines are reused).
 */
export function insertionEdit(text: string, eol: '\n' | '\r\n', offset: number, blockText: string, lines: Lines = new Lines(text)): TextEdit {
  const block = blockText.split(/\r?\n/).join(eol);
  let prefix: string;
  let suffix = eol;
  if (offset >= text.length && text.length > 0 && !endsWithNewline(text)) {
    prefix = eol + (lines.isBlank(lines.count - 1) ? '' : eol);
  } else {
    const line = lines.lineOf(offset);
    prefix = line === 0 || lines.isBlank(line - 1) ? '' : eol;
    if (lines.start(line) < text.length && !lines.isBlank(line)) suffix += eol;
  }
  return { span: { start: offset, end: offset }, newText: `${prefix}${block}${suffix}` };
}

/**
 * Inserts a rendered block (separated by one blank line from its neighbours) at `where`:
 *  - `end-of-namespace`: before the `end <ns>` line that closes the file's last `namespace <ns>`, else at the end;
 *  - `end-of-file`: at the end (a missing final line break is added first);
 *  - `after-block`: after the block and the declarations bound to it that follow it before the next block (its
 *    adjacent declaration, its pinned names and their `.holds`). Throws when no block has that id.
 */
export function insertBlockEdits(file: ParsedFile, blockText: string, where: InsertWhere): TextEdit[] {
  const text = file.text;
  const lines = new Lines(text);
  let offset = text.length;
  if (where.kind === 'end-of-namespace') {
    const scopes = scanDecls(text, lexLean(text), lines).scopes;
    const wanted = canonicalName(where.namespace);
    for (let i = scopes.length - 1; i >= 0; i--) {
      const event = scopes[i];
      if (event?.kind !== 'open' || event.scope !== 'namespace' || event.name === undefined || canonicalName(event.name) !== wanted) continue;
      const close = event.match !== undefined ? scopes[event.match] : undefined;
      if (close !== undefined) offset = lines.start(lines.lineOf(close.offset));
      break;
    }
  } else if (where.kind === 'after-block') {
    const index = file.blocks.findIndex((b) => b.id === where.blockId);
    const block = file.blocks[index];
    if (block === undefined) throw new Error(`insertBlockEdits: no block with id ${JSON.stringify(where.blockId)} in ${file.path}`);
    const limit = file.blocks[index + 1]?.span.start ?? text.length;
    const names = new Set<string>();
    for (const name of [block.binding.statement, ...(block.binding.pinned ?? [])]) {
      if (name !== undefined) names.add(name).add(holdsName(name));
    }
    let end = block.span.end;
    file.decls.forEach((decl, i) => {
      const bound = i === block.binding.adjacentDecl || (decl.fullName !== undefined && names.has(decl.fullName));
      if (bound && decl.span.start >= block.span.end && decl.span.start < limit) end = Math.max(end, decl.span.end);
    });
    offset = lines.fullEnd(lines.lineOf(end));
  }
  return [insertionEdit(text, file.eol, offset, blockText, lines)];
}

/**
 * Lean text operations (docs/m1-plan.md section 6.2): the D-11 kind-change rewrites and the D-9 docstring mirror,
 * planned by WP-model and applied here to one file. All or nothing: any problem means no edits.
 */
import { holdsName } from '../facts.js';
import { deletionEdit } from './edits.js';
import { isLeanName, lexLean } from './lexer.js';
import { findDecl, relativeName } from './names.js';
import { Lines } from './text.js';
import type { ArchivedDecl, DeclInfo, LeanOp, LeanOpsResult, LeanToken, ParsedFile, Span, TextEdit } from './types.js';
import { escapeBodyText } from './values.js';

/** Applies Lean text operations to one file (all or nothing: check `problems`). */
export function applyLeanOps(file: ParsedFile, ops: readonly LeanOp[]): LeanOpsResult {
  const { text, eol } = file;
  const lines = new Lines(text);
  const tokens = lexLean(text).tokens;
  const edits: TextEdit[] = [];
  const archived: ArchivedDecl[] = [];
  const problems: string[] = [];
  const where = (offset: number) => {
    const p = lines.position(offset);
    return `${file.path}:${p.line + 1}:${p.character + 1}`;
  };

  const need = (name: string, what: string): DeclInfo | undefined => {
    const decl = findDecl(file, name);
    if (decl === undefined) problems.push(`${what} \`${name}\` is not declared in ${file.path}.`);
    return decl;
  };
  /** A declaration about to be removed or replaced must not hold a telelean block (e.g. between its docstring and keyword). */
  const holdsNoBlock = (decl: DeclInfo, name: string): boolean => {
    const inside = file.blocks.find((b) => b.span.start >= decl.span.start && b.span.end <= decl.span.end);
    if (inside !== undefined) problems.push(`\`${name}\` contains the telelean block \`${inside.id}\` (${where(inside.span.start)}); edit it by hand.`);
    return inside === undefined;
  };
  const textOf = (decl: DeclInfo) => text.slice(decl.span.start, decl.span.end);
  /** The occurrence spans of an op: inside the declaration, after its name, each an identifier (or a dotted prefix of one). */
  const occurrences = (decl: DeclInfo, name: string, spans: readonly Span[]): boolean => {
    const after = decl.nameSpan?.end ?? decl.keywordSpan.end;
    let ok = true;
    for (const span of spans) {
      const token = tokenAt(tokens, span.start);
      const isIdentifier =
        token !== undefined &&
        token.kind === 'ident' &&
        span.end > span.start &&
        (span.end === token.span.end || (span.end < token.span.end && text.charAt(span.end) === '.'));
      if (!isIdentifier || span.start < after || span.end > decl.span.end) {
        problems.push(`The occurrence ${JSON.stringify(text.slice(span.start, span.end))} at ${where(span.start)} is not an identifier inside \`${name}\`.`);
        ok = false;
      }
    }
    return ok;
  };
  const validHypothesis = (hypName: string): boolean => {
    if (isLeanName(hypName) && !hypName.includes('.')) return true;
    problems.push(`\`${hypName}\` is not a valid hypothesis name.`);
    return false;
  };

  const addedHolds = new Set<string>();
  for (const op of ops) {
    switch (op.op) {
      case 'add-holds-axiom': {
        const statement = need(op.statement, 'The statement');
        if (statement === undefined) break;
        if (findDecl(file, holdsName(op.statement)) !== undefined || addedHolds.has(op.statement)) {
          problems.push(`\`${holdsName(op.statement)}\` already exists in ${file.path}.`);
          break;
        }
        addedHolds.add(op.statement);
        const short = relativeName(op.statement, statement.namespace);
        const indent = lines.indent(lines.lineOf(statement.span.start));
        edits.push({ span: { start: statement.span.end, end: statement.span.end }, newText: `${eol}${indent}axiom ${short}.holds : ${short}` });
        break;
      }
      case 'holds-theorem-to-axiom': {
        const name = holdsName(op.statement);
        const holds = need(name, 'The justification');
        if (holds === undefined) break;
        if (holds.keyword !== 'theorem' && holds.keyword !== 'lemma') {
          problems.push(`\`${name}\` is ${holds.keyword === 'axiom' ? 'already an axiom' : `a ${holds.keyword}, not a theorem`}.`);
          break;
        }
        if (!holdsNoBlock(holds, name)) break;
        const short = relativeName(op.statement, holds.namespace);
        archived.push({ name, text: textOf(holds) });
        edits.push({ span: holds.span, newText: `axiom ${short}.holds : ${short}` });
        break;
      }
      case 'remove-holds':
      case 'remove-decl': {
        const name = op.op === 'remove-holds' ? holdsName(op.statement) : op.name;
        const decl = need(name, op.op === 'remove-holds' ? 'The justification' : 'The declaration');
        if (decl === undefined || !holdsNoBlock(decl, name)) break;
        if (op.archive) archived.push({ name, text: textOf(decl) });
        edits.push(deletionEdit(text, decl.span, lines));
        break;
      }
      case 'add-hypothesis': {
        const decl = need(op.decl, 'The declaration');
        if (decl === undefined || !validHypothesis(op.hypName)) break;
        if (decl.nameSpan === undefined) {
          problems.push(`\`${op.decl}\` has no name to put a hypothesis after.`);
          break;
        }
        if (/[\r\n]/.test(op.hypType) || lexLean(op.hypType).comments.length > 0 || op.hypType.trim() === '') {
          problems.push(`The hypothesis type ${JSON.stringify(op.hypType)} is not a one-line Lean term.`);
          break;
        }
        if (!occurrences(decl, op.decl, op.replace)) break;
        // After the name and its universe parameters (`foo.{u}`), before every existing binder.
        let at = decl.nameSpan.end;
        if (text.startsWith('.{', at)) {
          const close = text.indexOf('}', at);
          if (close > 0) at = close + 1;
        }
        edits.push({ span: { start: at, end: at }, newText: ` (${op.hypName} : ${op.hypType.trim()})` });
        for (const span of op.replace) edits.push({ span, newText: op.hypName });
        break;
      }
      case 'apply-hypothesis': {
        const decl = need(op.decl, 'The declaration');
        if (decl === undefined || !validHypothesis(op.hypName) || !occurrences(decl, op.decl, op.replace)) break;
        for (const span of op.replace) {
          const start = text.charAt(span.start - 1) === '@' ? span.start - 1 : span.start;
          edits.push({ span: { start, end: span.end }, newText: `(${text.slice(start, span.end)} ${op.hypName})` });
        }
        break;
      }
      case 'set-docstring': {
        const decl = need(op.decl, 'The declaration');
        if (decl === undefined) break;
        const doc = `/-- ${escapeBodyText(op.text.split(/\r?\n/).join(eol))} -/`;
        if (decl.docSpan !== undefined) {
          edits.push({ span: decl.docSpan, newText: doc });
        } else {
          const separator = lines.isLineInitial(decl.span.start) ? `${eol}${lines.indent(lines.lineOf(decl.span.start))}` : ' ';
          edits.push({ span: { start: decl.span.start, end: decl.span.start }, newText: `${doc}${separator}` });
        }
        break;
      }
      default: {
        const unknown: never = op;
        problems.push(`Unknown Lean operation ${JSON.stringify(unknown)}.`);
      }
    }
  }

  if (problems.length === 0) {
    const sorted = [...edits].sort((a, b) => a.span.start - b.span.start || a.span.end - b.span.end);
    for (let i = 1; i < sorted.length; i++) {
      const previous = sorted[i - 1];
      const current = sorted[i];
      if (previous !== undefined && current !== undefined && current.span.start < previous.span.end) {
        problems.push(`Two operations change overlapping text at ${where(current.span.start)}.`);
        break;
      }
    }
  }
  return problems.length > 0 ? { edits: [], archived: [], problems } : { edits, archived, problems };
}

/** The token starting exactly at `offset`, if any. */
function tokenAt(tokens: readonly LeanToken[], offset: number): LeanToken | undefined {
  let lo = 0;
  let hi = tokens.length;
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if ((tokens[mid]?.span.start ?? Infinity) < offset) lo = mid + 1;
    else hi = mid;
  }
  const token = tokens[lo];
  return token !== undefined && token.span.start === offset ? token : undefined;
}

/**
