/**
 * AT1.8 — `deriveId`: transliterated slugs of at most 6 words, uniqueness suffixes, a deterministic `n-<6 hex>`
 * (FNV-1a 32 over the UTF-8 bytes of the trimmed sentence) for text without Latin letters, every result matching
 * ID_PATTERN; and id-less blocks in one file get distinct derived ids, each with TL112.
 */
import { describe, expect, it } from 'vitest';
import { deriveId, ID_PATTERN, parseLeanFile } from '../../src/index.js';

const none = () => false;

describe('AT1.8 deriveId', () => {
  it('slugs Latin text, at most 6 words', () => {
    expect(deriveId('Cynder is a character who has a dark past', none)).toBe('cynder-is-a-character-who-has');
    expect(deriveId('PG games cannot have characters with dark pasts', none)).toBe('pg-games-cannot-have-characters-with');
    expect(deriveId('The new Spyro game is PG', none)).toBe('the-new-spyro-game-is-pg');
    expect(deriveId('  42 is -- the answer!  ', none)).toBe('42-is-the-answer');
  });

  it('transliterates accents and undecomposable Latin letters', () => {
    expect(deriveId('Ça déjà vu: Ærø Straße', none)).toBe('ca-deja-vu-aero-strasse');
    expect(deriveId('Ｆｕｌｌ width İstanbul', none)).toBe('full-width-istanbul');
    expect(deriveId('Cynder 是 dragon', none)).toBe('cynder-dragon');
  });

  it('suffixes -2, -3, … until the id is free', () => {
    const taken = new Set(['dark-past', 'dark-past-2']);
    expect(deriveId('Dark past', (id) => taken.has(id))).toBe('dark-past-3');
    expect(deriveId('Dark past', (id) => id === 'dark-past')).toBe('dark-past-2');
  });

  it('falls back to n-<6 hex> of FNV-1a 32 for text with no Latin letters or digits (deterministic)', () => {
    // Reference values computed independently (Python, FNV-1a 32 over UTF-8): 猫は黒い -> 83afc8ea,
    // Ελληνικά -> 36ac4791, the empty string -> 811c9dc5.
    expect(deriveId('猫は黒い', none)).toBe('n-83afc8');
    expect(deriveId('  猫は黒い  ', none)).toBe('n-83afc8');
    expect(deriveId('Ελληνικά', none)).toBe('n-36ac47');
    expect(deriveId('', none)).toBe('n-811c9d');
    expect(deriveId('猫は黒い', (id) => id === 'n-83afc8')).toBe('n-83afc8-2');
    expect(deriveId('!!!', none)).toMatch(/^n-[0-9a-f]{6}$/);
  });

  it('always matches ID_PATTERN', () => {
    const pieces = ['a', 'Z', '9', ' ', '-', '_', '.', 'é', 'ß', '猫', 'λ', '!', '/', '\n', 'Æ', '𝓝', '  '];
    let seed = 99;
    const random = () => {
      seed = (seed * 1103515245 + 12345) % 2147483648;
      return seed / 2147483648;
    };
    for (let i = 0; i < 2000; i++) {
      let sentence = '';
      for (let j = Math.floor(random() * 12); j > 0; j--) sentence += pieces[Math.floor(random() * pieces.length)] ?? '';
      const id = deriveId(sentence, (candidate) => random() < 0.3 && candidate.length < 40);
      expect(id, JSON.stringify(sentence)).toMatch(ID_PATTERN);
    }
  });
});

describe('AT1.8 derived ids in a file', () => {
  const block = (sentence: string, id?: string) => `/-\n@@ telelean v1\n${id ? `id: ${id}\n` : ''}type: GOAL\nnatural_name: ${sentence}\n-/\n\n`;

  it('two id-less blocks with the same sentence get distinct derived ids, each with TL112', () => {
    const file = parseLeanFile('X.lean', block('Same sentence') + block('Same sentence'));
    expect(file.blocks.map((b) => [b.id, b.idWritten])).toEqual([
      ['same-sentence', false],
      ['same-sentence-2', false],
    ]);
    expect(file.diagnostics.map((d) => [d.code, d.severity, d.nodeId])).toEqual([
      ['TL112', 'info', 'same-sentence'],
      ['TL112', 'info', 'same-sentence-2'],
    ]);
  });

  it('a derived id avoids ids written anywhere in the file', () => {
    const file = parseLeanFile('X.lean', block('Same sentence') + block('Other', 'same-sentence') + block('Same sentence'));
    expect(file.blocks.map((b) => b.id)).toEqual(['same-sentence-2', 'same-sentence', 'same-sentence-3']);
  });
});

/**
 * AT1.9 — declaration spans end at plan 6.1's command starts (a column-0 `--` comment, `set_option`, `variable`,
 * `open`, `attribute` and `#check` lines end the preceding declaration; an indented continuation line does not; a
 * block comment after a theorem ends it) — and the rest of the header parser: names, namespaces, keywords,
 * modifiers, value starts, `mutual`, `deriving`, imports.
 */
import { describe, expect, it } from 'vitest';
import { parseLeanFile, type DeclInfo } from '../../src/index.js';

const decls = (text: string) => parseLeanFile('X.lean', text).decls;
const lines = (d: DeclInfo) => [d.range.start.line, d.range.end.line];
const summary = (text: string) => decls(text).map((d) => [d.fullName ?? d.keyword, ...lines(d)]);

describe('AT1.9 declaration spans end at command starts', () => {
  const text = [
    'namespace T',
    'theorem a : True := by',
    '  trivial',
    '-- column-0 comment',
    'theorem b : True := trivial',
    'set_option pp.all true',
    'theorem c : True :=',
    '  trivial',
    'variable (x : Nat)',
    'theorem d : True := trivial',
    'open Nat',
    'theorem e : True := trivial',
    'attribute [simp] e',
    'theorem f : True := trivial',
    '#check f',
    'theorem g : True := trivial',
    '/- a block comment -/',
    'theorem h : True :=',
    '  -- an indented comment stays in h',
    '  trivial',
    '',
    'end T',
    '',
  ].join('\n');

  it('ends each theorem before the next command start, keeping indented continuation lines', () => {
    expect(summary(text)).toEqual([
      ['T.a', 1, 2],
      ['T.b', 4, 4],
      ['T.c', 6, 7],
      ['T.d', 9, 9],
      ['T.e', 11, 11],
      ['T.f', 13, 13],
      ['T.g', 15, 15],
      ['T.h', 17, 19],
    ]);
  });

  it('a span ends at the end of its last non-blank line', () => {
    const h = decls(text).find((d) => d.name === 'h');
    expect(text.slice(h?.span.start, h?.span.end)).toBe('theorem h : True :=\n  -- an indented comment stays in h\n  trivial');
  });

  it('`deriving Repr` is a clause of the inductive above it; `deriving instance` is a command', () => {
    const src = 'inductive Color where\n  | red\n  | green\nderiving Repr\nderiving instance BEq for Color\nstructure P where\n  x : Nat\n  deriving DecidableEq\n';
    expect(summary(src)).toEqual([
      ['Color', 0, 3],
      ['P', 5, 7],
    ]);
  });

  it('`mutual … end` is one declaration (through its `end`), its members are found, and its `end` closes no namespace', () => {
    const src = [
      'namespace M',
      'mutual',
      '  def even : Nat → Bool',
      '    | 0 => true',
      '    | n+1 => odd n',
      '  def odd : Nat → Bool',
      '    | 0 => false',
      '    | n+1 => even n',
      'end',
      'theorem after : True := trivial',
      'end M',
    ].join('\n');
    const found = decls(src);
    expect(found.map((d) => [d.keyword, d.fullName, ...lines(d)])).toEqual([
      ['mutual', undefined, 1, 8],
      ['def', 'M.even', 2, 4],
      ['def', 'M.odd', 5, 7],
      ['theorem', 'M.after', 9, 9],
    ]);
    const even = found[1];
    expect(src.slice(even?.valueStart, (even?.valueStart ?? 0) + 5)).toBe('| 0 =');
  });

  it('indented declarations (an indented namespace body) are found and split', () => {
    const src = 'namespace I\n  /-- a doc -/\n  theorem a : True := trivial\n  theorem b : True :=\n    trivial\nend I\n';
    expect(decls(src).map((d) => [d.fullName, d.docstring, ...lines(d)])).toEqual([
      ['I.a', 'a doc', 1, 2],
      ['I.b', undefined, 3, 4],
    ]);
  });
});

describe('declaration headers', () => {
  it('resolves names against namespaces and sections (`_root_`, «escapes», dotted ends)', () => {
    const src = [
      'namespace A.B',
      'section S',
      'def x := 1',
      'end S',
      'noncomputable section',
      'def y := 2',
      'end',
      'def _root_.top := 3',
      'def «weird name» := 4',
      'def «plain» := 5',
      'end A.B',
      'def z := 6',
    ].join('\n');
    expect(decls(src).map((d) => [d.name, d.fullName, d.namespace.join('.')])).toEqual([
      ['x', 'A.B.x', 'A.B'],
      ['y', 'A.B.y', 'A.B'],
      ['_root_.top', 'top', 'A.B'],
      ['«weird name»', 'A.B.«weird name»', 'A.B'],
      ['«plain»', 'A.B.plain', 'A.B'],
      ['z', 'z', ''],
    ]);
  });

  it('reads keywords, modifiers, attributes, instance priorities and anonymous instances', () => {
    const src = [
      '@[simp, reducible] private noncomputable def m : Nat := 1',
      'instance (priority := low) instFoo : Inhabited Nat := ⟨0⟩',
      'instance (n : Nat) : Inhabited (Fin (n+1)) := ⟨0⟩',
      'class abbrev Both := Inhabited, Nonempty',
      'class inductive Foo',
      'protected theorem p : True := trivial',
      'example : True := trivial',
      'opaque o : Nat',
      'coinductive Stream',
    ].join('\n');
    const found = decls(src);
    expect(found.map((d) => [d.keyword, d.name])).toEqual([
      ['def', 'm'],
      ['instance', 'instFoo'],
      ['instance', undefined],
      ['class abbrev', 'Both'],
      ['class inductive', 'Foo'],
      ['theorem', 'p'],
      ['example', undefined],
      ['opaque', 'o'],
      ['coinductive', 'Stream'],
    ]);
    expect(found[0]).toMatchObject({ modifiers: ['private', 'noncomputable'], attributes: ['@[simp, reducible]'] });
    expect(found[5]?.modifiers).toEqual(['protected']);
    expect(src.slice(found[3]?.keywordSpan.start, found[3]?.keywordSpan.end)).toBe('class abbrev');
  });

  it('finds the value start: the first top-level `:=`, `where` or `|` (not inside brackets, not `|x|` notation)', () => {
    const at = (src: string) => {
      const d = decls(src)[0];
      return d?.valueStart === undefined ? undefined : src.slice(d.valueStart, d.valueStart + 5);
    };
    expect(at('def f (x : Nat := 1) : Nat := x')).toBe(':= x');
    expect(at('theorem t : 0 ≤ |a| := by simp')).toBe(':= by');
    expect(at('structure S where\n  x : Nat')).toBe('where');
    expect(at('instance : Inhabited Nat where default := 0')).toBe('where');
    expect(at('inductive C | a | b')).toBe('| a |');
    expect(at('def g : Nat → Nat\n  | 0 => 1\n  | n => n')).toBe('| 0 =');
    expect(at('def s : String := ":= not here"')).toBe(':= ":');
    expect(at('axiom ax : True')).toBeUndefined();
    expect(at('opaque o : Nat')).toBeUndefined();
  });

  it('a docstring attaches across a blank line and plain comments; a second docstring or a non-declaration does not attach', () => {
    expect(decls('/-- d -/\n\n-- note\n/- block -/\ndef x := 1\n').map((d) => [d.name, d.docstring, d.range.start.line])).toEqual([['x', 'd', 0]]);
    expect(decls('/-- first -/\n/-- second -/\ndef x := 1\n').map((d) => [d.name, d.docstring])).toEqual([['x', 'second']]);
    expect(decls('/-- doc before #check -/\n#check 1\ndef y := 2\n').map((d) => [d.name, d.docstring])).toEqual([['y', undefined]]);
  });

  it('reads the header imports only (module, public/meta, import all)', () => {
    const file = parseLeanFile('X.lean', 'module\n-- note\npublic import A.B\nimport all C\nmeta import D\nimport E\ndef x := 1\nimport F\n');
    expect(file.imports).toEqual(['A.B', 'C', 'D', 'E']);
  });
});

/**
 * Robustness: `parseLeanFile` never throws and keeps its invariants (sorted, in-bounds, consistent spans and
 * ranges) on random Lean-ish text full of half-written comments, strings and blocks; `lineIndex` converts both
 * ways; a large file parses quickly (research: 27k lines in ~145 ms in CPython).
 */
import { describe, expect, it } from 'vitest';
import { lexLean, lineIndex, parseLeanFile, renderBlock, type ParsedFile, type Span } from '../../src/index.js';

const PIECES = [
  'def',
  'theorem',
  'axiom',
  'abbrev',
  'instance',
  'mutual',
  'namespace',
  'section',
  'end',
  'private',
  'x',
  'A.B',
  ' ',
  ' ',
  '\n',
  '\n',
  '\r\n',
  '\t',
  '/-',
  '-/',
  '/--',
  '/-!',
  '--',
  '"',
  "'",
  "'a'",
  'r#"',
  '"#',
  '«',
  '»',
  '@[',
  ']',
  ':=',
  ':',
  '|',
  '(',
  ')',
  '{',
  '}',
  's!"',
  '@@ telelean v1',
  '@@ telelean v9',
  'id: x',
  'id: Bad Id',
  'kind: goal',
  'type: GOAL',
  'natural_name: y',
  'natural_name: "q\\"',
  'lean: A.b, «c d»',
  'premises: [a, b',
  'mytool.k: v',
  '---',
  '𝓝',
  'é',
  '0x1F',
  '1.5e3',
  '#check',
  'open',
  'where',
];

function prng(seed: number): () => number {
  let s = seed;
  return () => {
    s = (s + 0x6d2b79f5) | 0;
    let t = Math.imul(s ^ (s >>> 15), 1 | s);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const inside = (span: Span, outer: Span) => span.start >= outer.start && span.end <= outer.end && span.start <= span.end;

function checkInvariants(file: ParsedFile) {
  const { text } = file;
  const whole: Span = { start: 0, end: text.length };
  const index = lineIndex(text);
  const range = (span: Span) => ({ start: index.positionAt(span.start), end: index.positionAt(span.end) });
  const lex = lexLean(text);
  const commentSpans = new Set(lex.comments.map((c) => `${c.span.start}:${c.span.end}`));
  expect(file.diagnostics.filter((d) => d.message.includes('internal error'))).toEqual([]);
  let previous = -1;
  for (const block of file.blocks) {
    expect(commentSpans.has(`${block.span.start}:${block.span.end}`)).toBe(true);
    expect(block.span.start).toBeGreaterThan(previous);
    previous = block.span.end - 1;
    expect(block.range).toEqual(range(block.span));
    expect(inside(block.markerSpan, block.span)).toBe(true);
    for (const line of block.lines) {
      expect(inside(line.span, block.span)).toBe(true);
      expect(inside(line.valueSpan, line.span)).toBe(true);
      expect(text.slice(line.valueSpan.start, line.valueSpan.end)).toBe(line.raw);
    }
    if (block.bodySpan) expect(inside(block.bodySpan, block.span)).toBe(true);
    const { adjacentDecl, gapDecl } = block.binding;
    if (adjacentDecl !== undefined) expect(file.decls[adjacentDecl]).toBeDefined();
    if (gapDecl !== undefined) expect(file.decls[gapDecl]).toBeDefined();
    if (block.binding.mode !== 'none') expect(block.binding.statement).toBeTruthy();
  }
  previous = -1;
  for (const decl of file.decls) {
    expect(decl.span.start).toBeGreaterThanOrEqual(previous);
    previous = decl.span.start;
    expect(inside(decl.span, whole)).toBe(true);
    expect(inside(decl.keywordSpan, decl.span)).toBe(true);
    if (decl.nameSpan) expect(inside(decl.nameSpan, decl.span)).toBe(true);
    if (decl.docSpan) expect(inside(decl.docSpan, decl.span)).toBe(true);
    if (decl.valueStart !== undefined) expect(decl.valueStart >= decl.keywordSpan.end && decl.valueStart < decl.span.end).toBe(true);
    expect(decl.range).toEqual(range(decl.span));
  }
  for (const d of file.diagnostics) {
    expect(inside(d.span, whole)).toBe(true);
    expect(d.range).toEqual(range(d.span));
  }
}

describe('parseLeanFile never throws and keeps its invariants', () => {
  it('on 3000 random Lean-ish texts', () => {
    const random = prng(31337);
    for (let i = 0; i < 3000; i++) {
      let text = '';
      for (let j = Math.floor(random() * 60); j > 0; j--) text += PIECES[Math.floor(random() * PIECES.length)] ?? '';
      let file: ParsedFile | undefined;
      expect(() => (file = parseLeanFile('F.lean', text)), JSON.stringify(text)).not.toThrow();
      if (file !== undefined) checkInvariants(file);
    }
  });

  it('on every prefix of the Spyro-style text (as while typing)', () => {
    const text = `namespace S\n\n${renderBlock({ id: 'a', type: 'GOAL', naturalName: 'A -/ b', lean: ['S.a'] })}\n/-- A -/\nabbrev a : Prop := True\naxiom a.holds : a\n\nend S\n`;
    for (let n = 0; n <= text.length; n++) checkInvariants(parseLeanFile('S.lean', text.slice(0, n)));
  });
});

describe('lineIndex', () => {
  it('converts offsets and positions both ways (LF, CRLF, non-BMP), clamping out-of-range positions', () => {
    const text = 'ab\r\n𝓝c\n\nlast';
    const index = lineIndex(text);
    expect(index.lineCount).toBe(4);
    expect(index.positionAt(0)).toEqual({ line: 0, character: 0 });
    expect(index.positionAt(4)).toEqual({ line: 1, character: 0 });
    expect(index.positionAt(7)).toEqual({ line: 1, character: 3 });
    expect(index.positionAt(text.length)).toEqual({ line: 3, character: 4 });
    expect(index.positionAt(99)).toEqual({ line: 3, character: 4 });
    for (let offset = 0; offset <= text.length; offset++) {
      if (offset === 3) continue; // between \r and \n: not a position LSP can name
      expect(index.offsetAt(index.positionAt(offset))).toBe(offset);
    }
    expect(index.offsetAt({ line: 0, character: 99 })).toBe(2);
    expect(index.offsetAt({ line: 9, character: 0 })).toBe(text.length);
    expect(index.offsetAt({ line: -1, character: 5 })).toBe(0);
  });
});

describe('performance', () => {
  it('parses a 30 000-line model file well within a second or two', () => {
    const parts: string[] = ['import Model.Big.Vocabulary', '', 'namespace Big', ''];
    for (let i = 0; i < 2000; i++) {
      parts.push(renderBlock({ id: `node-${i}`, type: 'ASSUMPTION', naturalName: `Fact number ${i} holds`, rationale: 'r', lean: [`Big.f${i}`] }));
      parts.push(`/-- Fact number ${i} holds -/`, `abbrev f${i} : Prop := P${i % 7} c${i % 11}`, `axiom f${i}.holds : f${i}`, '');
    }
    parts.push('end Big', '');
    const text = parts.join('\n');
