/**
 * Git process helpers for telelean's private history refs (D-33, docs/m1-plan.md section 8).
 *
 * Every call runs `git` without a shell, with telelean's safe settings in front of the subcommand:
 *
 *   git -c commit.gpgsign=false -c core.hooksPath=/dev/null -c gc.auto=0 -c core.fsmonitor=false <subcommand> …
 *
 * so no signing prompt appears, none of the user's hooks run, no automatic gc starts and no fsmonitor daemon is
 * spawned. The environment has `GIT_TERMINAL_PROMPT=0` and `LC_ALL=C` (stable messages), and never carries
 * variables that would point git at another repository, index or object store (the caller's own temporary
 * `GIT_INDEX_FILE` aside). Only plumbing is used by the history store; nothing here touches the user's index,
 * HEAD, branches, remotes or hooks.
 */
import { spawn } from 'node:child_process';
import { createHash } from 'node:crypto';

/** `-c` settings put in front of every git subcommand telelean runs. */
export const SAFE_GIT_CONFIG: readonly string[] = [
  '-c',
  'commit.gpgsign=false',
  '-c',
  'core.hooksPath=/dev/null',
  '-c',
  'gc.auto=0',
  '-c',
  'core.fsmonitor=false',
];

/** Variables that would redirect git to another repository, index or object store; never inherited. */
const REDIRECTING_GIT_ENV: readonly string[] = [
  'GIT_DIR',
  'GIT_WORK_TREE',
  'GIT_INDEX_FILE',
  'GIT_OBJECT_DIRECTORY',
  'GIT_ALTERNATE_OBJECT_DIRECTORIES',
  'GIT_COMMON_DIR',
  'GIT_NAMESPACE',
  'GIT_PREFIX',
  'GIT_QUARANTINE_PATH',
];

/** Largest output read from one git call (blob contents, listings). */
const MAX_OUTPUT_BYTES = 256 * 1024 * 1024;

export type GitErrorKind = 'missing' | 'failed';

export class GitError extends Error {
  constructor(
    message: string,
    /** `missing`: the git executable could not be started; `failed`: it exited non-zero. */
    readonly kind: GitErrorKind,
    readonly exitCode: number | null = null,
    readonly stderr = '',
  ) {
    super(message);
    this.name = 'GitError';
  }
}

export interface GitRunOptions {
  /** Working directory (the model root). */
  cwd: string;
  /** Data for stdin (then closed); default: empty stdin. */
  input?: string | Buffer;
  /** Extra environment (author/committer identity, a temporary GIT_INDEX_FILE, dates). */
  env?: Readonly<Record<string, string>>;
  /** Exit codes that count as success (default `[0]`); the caller inspects `GitResult.code`. */
  okCodes?: readonly number[];
}

export interface GitResult {
  stdout: Buffer;
  stderr: string;
  code: number;
}

/** The environment for a git child: the host's, minus redirecting variables, plus telelean's fixed settings. */
export function gitEnvironment(extra: Readonly<Record<string, string>> = {}): NodeJS.ProcessEnv {
  const env: NodeJS.ProcessEnv = { ...process.env };
  for (const name of REDIRECTING_GIT_ENV) delete env[name];
  env['GIT_TERMINAL_PROMPT'] = '0';
  env['LC_ALL'] = 'C';
  return { ...env, ...extra };
}

/** Runs `git <SAFE_GIT_CONFIG> <args>`; rejects with GitError unless the exit code is in `okCodes`. */
export function runGit(gitPath: string, args: readonly string[], options: GitRunOptions): Promise<GitResult> {
  const argv = [...SAFE_GIT_CONFIG, ...args];
  const okCodes = options.okCodes ?? [0];
  return new Promise<GitResult>((resolve, reject) => {
    let child;
    try {
      child = spawn(gitPath, argv, { cwd: options.cwd, env: gitEnvironment(options.env), stdio: ['pipe', 'pipe', 'pipe'] });
    } catch (error) {
      reject(new GitError(`cannot start ${gitPath}: ${(error as Error).message}`, 'missing'));
      return;
    }
    const out: Buffer[] = [];
    const err: Buffer[] = [];
    let outBytes = 0;
    let settled = false;
    const fail = (error: GitError): void => {
      if (settled) return;
      settled = true;
      reject(error);
    };
    child.stdout.on('data', (chunk: Buffer) => {
      outBytes += chunk.length;
      if (outBytes > MAX_OUTPUT_BYTES) {
        child.kill('SIGKILL');
        fail(new GitError(`git ${args[0] ?? ''}: output exceeds ${MAX_OUTPUT_BYTES} bytes`, 'failed'));
        return;
      }
      out.push(chunk);
    });
    child.stderr.on('data', (chunk: Buffer) => err.push(chunk));
    child.stdin.on('error', () => undefined); // git may exit before reading all input; its exit code tells why
    child.on('error', (error: NodeJS.ErrnoException) => {
      fail(
        error.code === 'ENOENT' || error.code === 'EACCES'
          ? new GitError(`git executable not found (${gitPath})`, 'missing')
          : new GitError(`git ${args[0] ?? ''}: ${error.message}`, 'failed'),
      );
    });
    child.on('close', (code, signal) => {
      if (settled) return;
      const stderr = Buffer.concat(err).toString('utf8');
      const exit = code ?? -1;
      if (!okCodes.includes(exit)) {
        const why = stderr.trim().split('\n').slice(-3).join(' ') || (signal ? `killed by ${signal}` : `exit code ${exit}`);
        fail(new GitError(`git ${args[0] ?? ''} failed: ${why}`, 'failed', code, stderr));
        return;
      }
      settled = true;
      resolve({ stdout: Buffer.concat(out), stderr, code: exit });
    });
    child.stdin.end(options.input ?? '');
  });
}

/** `runGit`, returning stdout as UTF-8 text. */
export async function gitText(gitPath: string, args: readonly string[], options: GitRunOptions): Promise<string> {
  return (await runGit(gitPath, args, options)).stdout.toString('utf8');
}

/** Where a model root sits in its repository. */
export interface RepoInfo {
  /** Absolute path of the working tree's top level. */
  topLevel: string;
  /** The model root relative to the top level, POSIX, no trailing slash ('' at the top level). */
  prefix: string;
  /** Absolute path of the git directory. */
  gitDir: string;
  /** The ref namespace component for this root (docs/m1-plan.md section 8). */
  rootKey: string;
}

/**
 * Finds the repository holding `root`, or `'no-repo'` when it is in none. Throws GitError `missing` when git cannot
 * be started, and GitError `failed` for other git errors (e.g. a bare repository, unsafe ownership).
 */
export async function discoverRepository(gitPath: string, root: string): Promise<RepoInfo | 'no-repo'> {
  let lines: string[];
  try {
    lines = (await gitText(gitPath, ['rev-parse', '--show-toplevel', '--show-prefix', '--absolute-git-dir'], { cwd: root })).split('\n');
  } catch (error) {
    if (error instanceof GitError && error.kind === 'failed' && /not a git repository/i.test(error.stderr)) return 'no-repo';
    throw error;
  }
  const [topLevel = '', prefixLine = '', gitDir = ''] = lines;
  if (topLevel === '' || gitDir === '') throw new GitError(`unexpected git rev-parse output: ${JSON.stringify(lines.join('\n'))}`, 'failed');
  const prefix = prefixLine.replace(/\/+$/, '');
  return { topLevel, prefix, gitDir, rootKey: rootKeyOf(prefix) };
}

/**
 * The ref component naming one model root: `root` at the repository top level, else the relative path with `/`
 * turned into `.`, other characters outside `[A-Za-z0-9._-]` into `_` (runs of dots and a leading dot too, which
 * ref names forbid), plus `-` and the first 8 hex digits of sha1(relative path).
 */
export function rootKeyOf(prefix: string): string {
  if (prefix === '') return 'root';
  const hash = createHash('sha1').update(prefix, 'utf8').digest('hex').slice(0, 8);
  const readable = prefix
    .replaceAll('/', '.')
    .replace(/[^A-Za-z0-9._-]/g, '_')
    .replace(/\.{2,}/g, '_')
    .replace(/^\./, '_');
  return `${readable}-${hash}`;
}

/** `git check-ref-format <ref>`. */
export async function isValidRefName(gitPath: string, cwd: string, ref: string): Promise<boolean> {
  const result = await runGit(gitPath, ['check-ref-format', ref], { cwd, okCodes: [0, 1] });
  return result.code === 0;
}

/**
 * D-33 history: durable snapshots of a model root as commits on private git refs (docs/m1-plan.md section 8).
 *
 *   refs/telelean/<rootKey>/subjects/<S>   one chain per subject (its root file, module directory and sidecars)
 *   refs/telelean/<rootKey>/project        the project files (library root, lakefile, toolchain, manifest, …)
 *
 * A snapshot is a commit whose tree holds exactly the scope's files (paths relative to the model root, contents as
 * given by the caller, i.e. what the user sees, unsaved typing included), whose parent is the chain's tip, and
 * whose message is the label plus `Telelean-*` trailers. It is built with plumbing only:
 *
 *   hash-object -w --no-filters --stdin-paths   (blobs, from files in a fresh temporary directory)
 *   update-index -z --index-info                (into a temporary GIT_INDEX_FILE in that directory)
 *   write-tree                                  (same temporary index)
 *   commit-tree -F -                            (explicit author/committer and date, no signing)
 *   update-ref <ref> <new> <old>                (compare-and-swap; '' = must not exist yet)
 *
 * The user's index, HEAD, branches, remotes and hooks are never touched (see ./git.ts for the flags on every call).
 */
import { createHash } from 'node:crypto';
import { mkdtemp, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import path from 'node:path';

import type { HistoryActionKind, HistoryAvailability, HistoryEntry, StorageUsage } from '@telelean/core';

import { discoverRepository, GitError, gitText, isValidRefName, runGit, type RepoInfo } from './git.js';

/** Which chain a snapshot belongs to. */
export type SnapshotScope = { kind: 'subject'; subject: string } | { kind: 'project' };

export interface SnapshotFile {
  /** POSIX path relative to the model root. */
  path: string;
  text: string;
}

export interface SnapshotMeta {
  label: string;
  action: HistoryActionKind;
  /** Written as the `Telelean-Subject` trailer ('' for project-level changes). */
  subject: string;
  nodes: readonly string[];
}

export interface HistoryStoreOptions {
  root: string;
  gitPath: string;
  author: { name: string; email: string };
  now: () => Date;
}

/** A history entry with what revert and preview need. */
export interface EntryDetails extends HistoryEntry {
  tree: string;
  /** The parent commit, absent for the first entry of a chain. */
  parent?: string;
}

/** Thrown when history is unavailable (no repository, git missing); the workspace maps it to `no-history`. */
export class HistoryUnavailableError extends Error {
  constructor(readonly availability: Exclude<HistoryAvailability, { state: 'ready' }>) {
    super(
      availability.state === 'no-repo'
        ? 'History needs a git repository: initialize one from the board.'
        : availability.state === 'git-missing'
          ? 'History needs git, which was not found.'
          : availability.state === 'disabled'
            ? 'History is switched off (telelean.git.snapshotRefs).'
            : `History is unavailable: ${availability.detail}`,
    );
    this.name = 'HistoryUnavailableError';
  }
}

export const HISTORY_FORMAT = '1';
const STORAGE_CACHE_MS = 10_000;
const HISTORY_ACTIONS: ReadonlySet<string> = new Set<HistoryActionKind>([
  'add-node',
  'edit-node',
  'delete-node',
  'change-kind',
  'reorder',
  'set-premises',
  'create-subject',
  'initial',
  'manual',
  'undo',
  'redo',
  'revert',
  'initialize',
]);

/** One record of `ls-tree -r -z`. */
interface TreeEntry {
  mode: string;
  type: string;
  oid: string;
  path: string;
}

/** Parsed `git cat-file commit` output. */
interface RawCommit {
  tree: string;
  parents: string[];
  author: GitIdentity;
  committer: GitIdentity;
  message: string;
}

interface GitIdentity {
  name: string;
  email: string;
  /** Git's internal date, e.g. `1793000000 +0000`. */
  date: string;
}

export class HistoryStore {
  private repo: RepoInfo | undefined;
  /** Per ref: the commit telelean last wrote or saw there and the content digest of its files (skips needless git calls). */
  private readonly known = new Map<string, { commit: string; digest: string }>();
  private storageCache: { at: number; value: Omit<StorageUsage, 'subjectBytes'> } | undefined;

  constructor(private readonly options: HistoryStoreOptions) {}

  /** `ready`, `no-repo`, `git-missing` or `error` (the workspace adds `disabled`). Cached once ready. */
  async availability(): Promise<HistoryAvailability> {
    if (this.repo) return { state: 'ready' };
    try {
      const found = await discoverRepository(this.options.gitPath, this.options.root);
      if (found === 'no-repo') return { state: 'no-repo' };
      for (const ref of [this.refName(found, { kind: 'project' }), this.refName(found, { kind: 'subject', subject: 'Probe' })]) {
        if (!(await isValidRefName(this.options.gitPath, this.options.root, ref))) {
          return { state: 'error', detail: `"${ref}" is not a valid git ref name` };
        }
      }
      this.repo = found;
      return { state: 'ready' };
    } catch (error) {
      if (error instanceof GitError && error.kind === 'missing') return { state: 'git-missing' };
      return { state: 'error', detail: (error as Error).message };
    }
  }

  /** Forgets the cached repository (after `git init`, or when git reports that it is gone). */
  reset(): void {
    this.repo = undefined;
    this.known.clear();
    this.storageCache = undefined;
  }

  async repository(): Promise<RepoInfo> {
    const availability = await this.availability();
    if (availability.state !== 'ready' || !this.repo) throw new HistoryUnavailableError(availability.state === 'ready' ? { state: 'error', detail: 'no repository' } : availability);
    return this.repo;
  }

  refName(repo: RepoInfo, scope: SnapshotScope): string {
    const base = `refs/telelean/${repo.rootKey}`;
    return scope.kind === 'project' ? `${base}/project` : `${base}/subjects/${scope.subject}`;
  }

  /** The chain's tip commit, or undefined when the chain does not exist yet. */
  async tip(scope: SnapshotScope): Promise<string | undefined> {
    const repo = await this.repository();
    return this.resolveRef(this.refName(repo, scope));
  }

  /**
   * Commits `files` as the next snapshot of `scope`, unless the tree equals the tip's (returns undefined then).
   * A missing chain starts with this commit (a root commit); an empty file list with no chain records nothing.
   */
  async snapshot(scope: SnapshotScope, files: readonly SnapshotFile[], meta: SnapshotMeta): Promise<string | undefined> {
    const repo = await this.repository();
    const ref = this.refName(repo, scope);
    const digest = digestFiles(files);
    for (let attempt = 0; ; attempt++) {
      const tip = await this.resolveRef(ref);
      if (tip === undefined && files.length === 0) return undefined;
      const known = this.known.get(ref);
      if (tip !== undefined && known?.commit === tip && known.digest === digest) return undefined;
      const tree = await this.writeTree(files);
      if (tip !== undefined && (await this.treeOf(tip)) === tree) {
        this.known.set(ref, { commit: tip, digest });
        return undefined;
      }
      const commit = await this.commitTree(tree, tip === undefined ? [] : [tip], snapshotMessage(meta), this.identityNow(), this.identityNow());
      try {
        await this.git(['update-ref', ref, commit, tip ?? '']);
      } catch (error) {
        // Another telelean window moved the chain between our read and our write: rebuild on its new tip once.
        if (attempt === 0 && error instanceof GitError && error.kind === 'failed') continue;
        throw error;
      }
      this.known.set(ref, { commit, digest });
      this.storageCache = undefined;
      return commit;
    }
  }

  /** The subject's entries, newest first (at most `limit`), and whether older ones exist. */
  async list(subject: string, limit: number): Promise<{ entries: HistoryEntry[]; more: boolean }> {
    const repo = await this.repository();
    const ref = this.refName(repo, { kind: 'subject', subject });
    if ((await this.resolveRef(ref)) === undefined) return { entries: [], more: false };
    const out = await this.git([
      '-c',
      'i18n.logOutputEncoding=UTF-8',
      'log',
      '-z',
      '--no-show-signature',
      '--no-color',
      '--first-parent',
      `--max-count=${limit + 1}`,
      '--format=%H%x1f%aI%x1f%B',
      ref,
      '--',
    ]);
    const records = out.split('\0').filter((r) => r.trim() !== '');
    const entries = records.slice(0, limit).map((record) => {
      const [id = '', time = '', ...rest] = record.split('\x1f');
      return entryFromMessage(id.trim(), time.trim(), rest.join('\x1f'), subject);
    });
    return { entries, more: records.length > limit };
  }

  /** One entry of the subject's chain (abbreviated ids accepted). Throws `not-found`-style errors as plain Error. */
  async entry(subject: string, id: string): Promise<EntryDetails | undefined> {
    const repo = await this.repository();
    const ref = this.refName(repo, { kind: 'subject', subject });
    const tip = await this.resolveRef(ref);
    if (tip === undefined || !/^[0-9a-f]{4,64}$/.test(id)) return undefined;
    const full = (await runGit(this.options.gitPath, ['rev-parse', '--verify', '--quiet', `${id}^{commit}`], { cwd: this.options.root, okCodes: [0, 1] })).stdout
      .toString('utf8')
      .trim();
    if (full === '') return undefined;
    const ancestor = await runGit(this.options.gitPath, ['merge-base', '--is-ancestor', full, tip], { cwd: this.options.root, okCodes: [0, 1] });
    if (ancestor.code !== 0) return undefined;
    const raw = await this.readCommit(full);
    const base = entryFromMessage(full, isoOfGitDate(raw.author.date), raw.message, subject);
    return { ...base, tree: raw.tree, ...(raw.parents[0] !== undefined ? { parent: raw.parents[0] } : {}) };
  }

  /** The files of a tree (or commit): path -> text. */
  async treeFiles(treeish: string): Promise<Map<string, string>> {
    const listing = await this.git(['ls-tree', '--full-tree', '-r', '-z', treeish]);
    const entries: TreeEntry[] = [];
    for (const record of listing.split('\0')) {
      if (record === '') continue;
      const tab = record.indexOf('\t');
      const [mode = '', type = '', oid = ''] = record.slice(0, tab).split(' ');
      if (type === 'blob') entries.push({ mode, type, oid, path: record.slice(tab + 1) });
    }
    const blobs = await this.readBlobs(entries.map((e) => e.oid));
    const files = new Map<string, string>();
    for (const entry of entries) files.set(entry.path, blobs.get(entry.oid) ?? '');
    return files;
  }

  /**
   * Disk used by history (D-33 counter): objects reachable from each subject's chain and from all of this root's
   * refs, but from no branch, tag or remote-tracking ref. Cached for 10 s (cleared by snapshots and prunes).
   */
  async storage(subject: string): Promise<StorageUsage> {
    const repo = await this.repository();
    const now = Date.now();
    if (!this.storageCache || now - this.storageCache.at > STORAGE_CACHE_MS) {
      const refs = (await this.git(['for-each-ref', '--format=%(refname)', `refs/telelean/${repo.rootKey}/`])).split('\n').filter((r) => r !== '');
      const perSubject: Record<string, number> = {};
      const subjectPrefix = `refs/telelean/${repo.rootKey}/subjects/`;
      for (const ref of refs) {
        if (ref.startsWith(subjectPrefix)) perSubject[ref.slice(subjectPrefix.length)] = await this.diskUsage([ref]);
      }
      const totalBytes = refs.length === 0 ? 0 : await this.diskUsage(refs);
      this.storageCache = { at: now, value: { totalBytes, perSubject } };
    }
    const { totalBytes, perSubject } = this.storageCache.value;
    return { subjectBytes: perSubject[subject] ?? 0, totalBytes, perSubject: { ...perSubject } };
  }

  /**
   * Keeps the subject's last `keepLast` snapshots: recreates them with the same trees, messages, authors and dates
   * (the oldest kept one becomes a root commit) and moves the ref with a compare-and-swap. No gc.
   */
  async prune(subject: string, keepLast: number): Promise<number> {
    const repo = await this.repository();
    const ref = this.refName(repo, { kind: 'subject', subject });
    const tip = await this.resolveRef(ref);
    if (tip === undefined) return 0;
    const chain = (await this.git(['rev-list', '--first-parent', tip])).split('\n').filter((l) => l !== '');
    if (chain.length <= keepLast) return 0;
    let parent: string | undefined;
    for (const id of chain.slice(0, keepLast).reverse()) {
      const raw = await this.readCommit(id);
      parent = await this.commitTree(raw.tree, parent === undefined ? [] : [parent], raw.message, raw.author, raw.committer);
    }
    if (parent === undefined) return 0;
    await this.git(['update-ref', ref, parent, tip]);
    this.known.delete(ref);
    this.storageCache = undefined;
    return chain.length - keepLast;
  }

  // ------------------------------------------------------------------------------------------- plumbing

  private async git(args: readonly string[], env?: Readonly<Record<string, string>>, input?: string): Promise<string> {
    try {
      return await gitText(this.options.gitPath, args, { cwd: this.options.root, ...(env ? { env } : {}), ...(input !== undefined ? { input } : {}) });
    } catch (error) {
      if (error instanceof GitError && /not a git repository/i.test(error.stderr)) this.reset();
      throw error;
    }
  }

  private async resolveRef(ref: string): Promise<string | undefined> {
    const result = await runGit(this.options.gitPath, ['rev-parse', '--verify', '--quiet', `${ref}^{commit}`], { cwd: this.options.root, okCodes: [0, 1] });
    const id = result.stdout.toString('utf8').trim();
    return result.code === 0 && id !== '' ? id : undefined;
  }

  private async treeOf(commit: string): Promise<string> {
    return (await this.git(['rev-parse', '--verify', `${commit}^{tree}`])).trim();
  }

  /** Blobs + a temporary index + write-tree; nothing outside the object store and a fresh temp dir is written. */
  private async writeTree(files: readonly SnapshotFile[]): Promise<string> {
    if (files.length === 0) return (await this.git(['mktree', '-z'], undefined, '')).trim();
    const dir = await mkdtemp(path.join(tmpdir(), 'telelean-snapshot-'));
    try {
      const blobPaths: string[] = [];
      for (const [i, file] of files.entries()) {
        const blobPath = path.join(dir, `blob-${i}`);
        await writeFile(blobPath, file.text, { encoding: 'utf8', mode: 0o600 });
        blobPaths.push(blobPath);
      }
      const oids = (await this.git(['hash-object', '-w', '--no-filters', '--stdin-paths'], undefined, `${blobPaths.join('\n')}\n`)).trim().split('\n');
      if (oids.length !== files.length) throw new GitError(`git hash-object returned ${oids.length} ids for ${files.length} files`, 'failed');
      const index = { GIT_INDEX_FILE: path.join(dir, 'index') };
      const info = files.map((file, i) => `100644 ${oids[i] ?? ''}\t${file.path}\0`).join('');
      await this.git(['update-index', '-z', '--index-info'], index, info);
      return (await this.git(['write-tree'], index)).trim();
    } finally {
      await rm(dir, { recursive: true, force: true });
    }
  }

  private async commitTree(tree: string, parents: readonly string[], message: string, author: GitIdentity, committer: GitIdentity): Promise<string> {
    const args = ['-c', 'i18n.commitEncoding=UTF-8', 'commit-tree', tree];
    for (const parent of parents) args.push('-p', parent);
    args.push('-F', '-');
    const env = {
      GIT_AUTHOR_NAME: author.name,
      GIT_AUTHOR_EMAIL: author.email,
      GIT_AUTHOR_DATE: `@${author.date}`,
      GIT_COMMITTER_NAME: committer.name,
      GIT_COMMITTER_EMAIL: committer.email,
      GIT_COMMITTER_DATE: `@${committer.date}`,
    };
    return (await this.git(args, env, message)).trim();
  }

  private identityNow(): GitIdentity {
    const seconds = Math.floor(this.options.now().getTime() / 1000);
    return { name: this.options.author.name, email: this.options.author.email, date: `${seconds} +0000` };
  }

  private async readCommit(id: string): Promise<RawCommit> {
    const raw = await this.git(['cat-file', 'commit', id]);
    const split = raw.indexOf('\n\n');
    const headers = (split < 0 ? raw : raw.slice(0, split)).split('\n');
    const message = split < 0 ? '' : raw.slice(split + 2);
    let tree = '';
    const parents: string[] = [];
    let author: GitIdentity | undefined;
    let committer: GitIdentity | undefined;
    for (const line of headers) {
      if (line.startsWith('tree ')) tree = line.slice(5);
      else if (line.startsWith('parent ')) parents.push(line.slice(7));
      else if (line.startsWith('author ')) author = parseIdentity(line.slice(7));
      else if (line.startsWith('committer ')) committer = parseIdentity(line.slice(10));
    }
    if (tree === '' || !author || !committer) throw new GitError(`cannot parse commit ${id}`, 'failed');
    return { tree, parents, author, committer, message };
  }

  /** Reads many blobs with one `cat-file --batch`. */
  private async readBlobs(oids: readonly string[]): Promise<Map<string, string>> {
    const unique = [...new Set(oids)];
    const blobs = new Map<string, string>();
    if (unique.length === 0) return blobs;
    const { stdout } = await runGit(this.options.gitPath, ['cat-file', '--batch'], { cwd: this.options.root, input: `${unique.join('\n')}\n` });
    let offset = 0;
    for (const oid of unique) {
      const newline = stdout.indexOf(0x0a, offset);
      if (newline < 0) throw new GitError('truncated git cat-file --batch output', 'failed');
      const header = stdout.subarray(offset, newline).toString('utf8').split(' ');
      if (header[1] === 'missing') throw new GitError(`git object ${oid} is missing`, 'failed');
      const size = Number(header[2]);
      if (!Number.isInteger(size)) throw new GitError(`unexpected git cat-file header ${header.join(' ')}`, 'failed');
      blobs.set(oid, stdout.subarray(newline + 1, newline + 1 + size).toString('utf8'));
      offset = newline + 1 + size + 1;
    }
    return blobs;
  }

  private async diskUsage(refs: readonly string[]): Promise<number> {
    const out = await this.git(['rev-list', '--objects', '--disk-usage', ...refs, '--not', '--branches', '--tags', '--remotes']);
    const bytes = Number(out.trim());
    return Number.isFinite(bytes) ? bytes : 0;
  }
}

// ------------------------------------------------------------------------------------------- messages

/** The snapshot commit message: the label, a blank line, the `Telelean-*` trailers. */
export function snapshotMessage(meta: SnapshotMeta): string {
  const oneLine = (s: string): string => s.replace(/[\r\n]+/g, ' ').trim();
  const nodes = meta.nodes.map(oneLine).filter((n) => n !== '');
  return [
    oneLine(meta.label) || 'Snapshot',
    '',
    `Telelean-Action: ${meta.action}`,
    `Telelean-Subject:${meta.subject ? ` ${oneLine(meta.subject)}` : ''}`,
    `Telelean-Nodes:${nodes.length > 0 ? ` ${nodes.join(', ')}` : ''}`,
    `Telelean-Format: ${HISTORY_FORMAT}`,
    '',
  ].join('\n');
}

/** A HistoryEntry from a commit's message (label = first line; trailers parsed leniently). */
export function entryFromMessage(id: string, time: string, message: string, fallbackSubject: string): HistoryEntry {
  const lines = message.replace(/\r\n/g, '\n').split('\n');
  const label = (lines[0] ?? '').trim();
  const trailer = (key: string): string | undefined => {
    for (const line of lines) {
      const match = new RegExp(`^Telelean-${key}:[ \\t]*(.*)$`).exec(line);
      if (match) return (match[1] ?? '').trim();
    }
    return undefined;
  };
  const action = trailer('Action') ?? '';
  const nodes = (trailer('Nodes') ?? '')
    .split(',')
    .map((n) => n.trim())
    .filter((n) => n !== '');
  return {
    id,
    time,
    action: HISTORY_ACTIONS.has(action) ? (action as HistoryActionKind) : 'manual',
    label,
    subject: trailer('Subject') || fallbackSubject,
    nodes,
  };
}

function parseIdentity(text: string): GitIdentity {
  const match = /^(.*) <(.*)> (\d+) ([+-]\d{4})$/.exec(text);
  if (!match) throw new GitError(`cannot parse git identity "${text}"`, 'failed');
  return { name: match[1] ?? '', email: match[2] ?? '', date: `${match[3] ?? '0'} ${match[4] ?? '+0000'}` };
}

/** `1793000000 +0100` -> ISO 8601 in that offset. */
export function isoOfGitDate(date: string): string {
  const [seconds = '0', tz = '+0000'] = date.split(' ');
  const sign = tz.startsWith('-') ? -1 : 1;
  const offsetMinutes = sign * (Number(tz.slice(1, 3)) * 60 + Number(tz.slice(3, 5)));
  const local = new Date((Number(seconds) + offsetMinutes * 60) * 1000).toISOString().slice(0, 19);
  return `${local}${tz.slice(0, 3)}:${tz.slice(3, 5)}`;
}

/** Order-independent digest of a file set (paths and contents). */
export function digestFiles(files: readonly SnapshotFile[]): string {
  const hash = createHash('sha256');
  for (const file of [...files].sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : 0))) {
    hash.update(file.path, 'utf8');
    hash.update('\0');
    hash.update(createHash('sha256').update(file.text, 'utf8').digest('hex'));
    hash.update('\0');
  }
  return hash.digest('hex');
}

/**
 * In-board Undo/Redo (D-17; docs/m1-plan.md section 8): per subject, in memory, at most 100 entries.
 *
 * An entry is one applied operation as whole-file changes (`before` -> `after`, sidecars included). Both stacks hold
 * changes *as last applied*, and both Undo and Redo apply the top entry backwards (`after` -> `before`):
 *
 *   perform:  push the applied changes C on the undo stack, clear redo
 *   undo:     pop C, apply it backwards -> applied changes A; push A on the redo stack
 *   redo:     pop A, apply it backwards -> applied changes A'; push A' on the undo stack
 *
 * Applying a change backwards to a file's current text: exact when the file still equals `after`; a no-op when it
 * already equals `before`; otherwise the reverse patch (`diff` structuredPatch/applyPatch, no fuzz) when the hunks
 * still fit. A file the change created is deleted only while unchanged, a deleted file is re-created only while
 * absent. Anything else refuses the whole step (all or nothing).
 */
import { applyPatch, structuredPatch } from 'diff';

import type { FileChange } from '@telelean/core';

export const UNDO_LIMIT = 100;

export interface UndoEntry {
  /** The label of the original operation (Undo/Redo prefix their own). */
  label: string;
  subject: string;
  nodes: string[];
  /** The changes as last applied. */
  changes: FileChange[];
  /** Layout-only operations are not snapshotted on their own (docs/m1-plan.md section 8). */
  layoutOnly: boolean;
}

export type BackwardResult = { ok: true; changes: FileChange[] } | { ok: false; path: string };

const CONFLICT = Symbol('conflict');

/**
 * The text a file should get when `change` is applied backwards to `current`, or CONFLICT. `null` = the file must
 * not exist.
 */
export function backwardText(change: FileChange, current: string | null): string | null | typeof CONFLICT {
  if (current === change.after) return change.before;
  if (current === change.before) return current;
  if (current === null || change.before === null || change.after === null) return CONFLICT;
  const patch = structuredPatch(change.path, change.path, change.after, change.before);
  const result = applyPatch(current, patch, { fuzzFactor: 0 });
  return result === false ? CONFLICT : result;
}

/**
 * Applies `changes` backwards to the current files (read through `read`), all or nothing: the changes to write
 * (`before` = the current text), or the first file that no longer fits.
 */
export async function applyBackwards(changes: readonly FileChange[], read: (path: string) => Promise<string | null>): Promise<BackwardResult> {
  const out: FileChange[] = [];
  for (const change of changes) {
    const current = await read(change.path);
    const target = backwardText(change, current);
    if (target === CONFLICT) return { ok: false, path: change.path };
    if (target !== current) out.push({ path: change.path, before: current, after: target });
  }
  return { ok: true, changes: out };
}

/** Per-subject undo and redo stacks. */
export class UndoStacks {
  private readonly undo = new Map<string, UndoEntry[]>();
  private readonly redo = new Map<string, UndoEntry[]>();

  /** A new operation: push it and clear the subject's redo stack. */
  record(entry: UndoEntry): void {
    push(this.undo, entry);
    this.redo.delete(entry.subject);
  }

  peek(kind: 'undo' | 'redo', subject: string): UndoEntry | undefined {
    return (kind === 'undo' ? this.undo : this.redo).get(subject)?.at(-1);
  }

  /** After an undo (or redo) of the top entry: move it to the other stack with the changes as applied now. */
  move(kind: 'undo' | 'redo', subject: string, applied: FileChange[]): void {
    const from = kind === 'undo' ? this.undo : this.redo;
    const entry = from.get(subject)?.pop();
    if (!entry) return;
    push(kind === 'undo' ? this.redo : this.undo, { ...entry, changes: applied });
  }

  labels(subject: string): { undo: string | null; redo: string | null } {
    return { undo: this.peek('undo', subject)?.label ?? null, redo: this.peek('redo', subject)?.label ?? null };
  }
}

function push(stacks: Map<string, UndoEntry[]>, entry: UndoEntry): void {
  const stack = stacks.get(entry.subject) ?? [];
  stack.push(entry);
  if (stack.length > UNDO_LIMIT) stack.splice(0, stack.length - UNDO_LIMIT);
  stacks.set(entry.subject, stack);
}

/**
 * Which files of a model root the workspace reads, snapshots and reverts (docs/m1-plan.md sections 2, 7.1, 8).
 * Listings come from the file system (dot-directories, `.lake` and `node_modules` skipped, symlinks never followed);
 * contents always come from the TextSource (open buffers first).
 */
import type { Dirent } from 'node:fs';
import { readdir, stat } from 'node:fs/promises';
import path from 'node:path';

import { CONFIG_PATH, inScope, isSubjectName, libraryRootFile, projectSnapshotScope, subjectOfPath, subjectSidecarDir, TELELEAN_DIR } from '@telelean/core';

import type { SnapshotScope } from './history.js';

/** Directory names never walked inside a model root (besides every dot-directory). */
const SKIPPED_DIRS: ReadonlySet<string> = new Set(['node_modules', '.lake']);

const LAYOUT_PATH_PATTERN = /^\.telelean\/subjects\/([^/]+)\/layout\.json$/;
const SIDECAR_PATH_PATTERN = /^\.telelean\/subjects\/([^/]+)\//;

export async function isFile(absolute: string): Promise<boolean> {
  try {
    return (await stat(absolute)).isFile();
  } catch {
    return false;
  }
}

async function entriesOf(absolute: string): Promise<Dirent[]> {
  try {
    return await readdir(absolute, { withFileTypes: true });
  } catch {
    return [];
  }
}

/**
 * Regular files under `root/relDir` (POSIX paths relative to `root`), skipping dot-directories, `.lake`,
 * `node_modules` and symlinks; `accept` filters by file name.
 */
export async function walkFiles(root: string, relDir: string, accept: (name: string) => boolean = () => true): Promise<string[]> {
  const out: string[] = [];
  const stack = [relDir];
  while (stack.length > 0) {
    const rel = stack.pop() ?? '';
    for (const entry of await entriesOf(path.join(root, rel))) {
      const child = rel === '' ? entry.name : `${rel}/${entry.name}`;
      if (entry.isDirectory()) {
        if (!entry.name.startsWith('.') && !SKIPPED_DIRS.has(entry.name)) stack.push(child);
      } else if (entry.isFile() && accept(entry.name)) {
        out.push(child);
      }
    }
  }
  return out.sort();
}

/** `<library>.lean` and `<library>/**.lean`, sorted. */
export async function listModelFiles(root: string, library: string): Promise<string[]> {
  const files = await walkFiles(root, library, (name) => name.endsWith('.lean'));
  if (await isFile(path.join(root, libraryRootFile(library)))) files.unshift(libraryRootFile(library));
  return files.sort();
}

/** `.telelean/subjects/<S>/layout.json` for every subject name S that has one. */
export async function listLayoutFiles(root: string): Promise<string[]> {
  const out: string[] = [];
  for (const entry of await entriesOf(path.join(root, TELELEAN_DIR, 'subjects'))) {
    if (!entry.isDirectory() || !isSubjectName(entry.name)) continue;
    const rel = `${TELELEAN_DIR}/subjects/${entry.name}/layout.json`;
    if (await isFile(path.join(root, rel))) out.push(rel);
  }
  return out.sort();
}

/** True for `<library>.lean` and `<library>/**.lean`. */
export function isModelFile(rel: string, library: string): boolean {
  return rel === libraryRootFile(library) || (rel.startsWith(`${library}/`) && rel.endsWith('.lean'));
}

/** The subject whose layout file `rel` is, if it is one. */
export function layoutSubject(rel: string): string | undefined {
  const subject = LAYOUT_PATH_PATTERN.exec(rel)?.[1];
  return subject !== undefined && isSubjectName(subject) ? subject : undefined;
}

/** The subject whose snapshot scope holds `rel` (module files and sidecars), if any. */
export function scopeSubject(rel: string, library: string): string | undefined {
  const sidecar = SIDECAR_PATH_PATTERN.exec(rel)?.[1];
  if (sidecar !== undefined) return isSubjectName(sidecar) ? sidecar : undefined;
  if (!isModelFile(rel, library)) return undefined;
  const subject = subjectOfPath(rel, library);
  return subject !== undefined && isSubjectName(subject) ? subject : undefined;
}

/** Subject names from a list of model file paths (the core rule: `<library>/<S>.lean` or a `.lean` file under `<library>/<S>/`). */
export function subjectNamesOf(paths: Iterable<string>, library: string): string[] {
  const names = new Set<string>();
  for (const rel of paths) {
    if (!isModelFile(rel, library)) continue;
    const subject = subjectOfPath(rel, library);
    if (subject !== undefined && isSubjectName(subject)) names.add(subject);
  }
  return [...names].sort();
}

/** The snapshot scopes (subject chains, then the project chain) that a set of changed paths touches. */
export function scopesOf(paths: Iterable<string>, library: string): SnapshotScope[] {
  const subjects = new Set<string>();
  let project = false;
  for (const rel of paths) {
    const subject = scopeSubject(rel, library);
    if (subject !== undefined) subjects.add(subject);
    if (inScope(rel, projectSnapshotScope(library))) project = true;
  }
  const scopes: SnapshotScope[] = [...subjects].sort().map((subject) => ({ kind: 'subject', subject }));
  if (project) scopes.push({ kind: 'project' });
  return scopes;
}

/**
 * The files a snapshot of `scope` covers, as they exist now: for a subject its root file, the `.lean` files under
 * its module directory and every file under its sidecar directory; for the project the fixed project files.
 */
export async function listScopeFiles(root: string, scope: SnapshotScope, library: string): Promise<string[]> {
  if (scope.kind === 'project') {
    const out: string[] = [];
    for (const rel of projectSnapshotScope(library)) if (await isFile(path.join(root, rel))) out.push(rel);
    return out.sort();
  }
  const subject = scope.subject;
  const out = await walkFiles(root, `${library}/${subject}`, (name) => name.endsWith('.lean'));
  const rootFile = `${library}/${subject}.lean`;
  if (await isFile(path.join(root, rootFile))) out.push(rootFile);
  out.push(...(await walkFiles(root, subjectSidecarDir(subject))));
  return out.sort();
}

/** Converts a path the host passed (relative POSIX, or absolute inside the root) to the relative form, or undefined. */
export function toRelative(root: string, p: string): string | undefined {
  const rel = path.isAbsolute(p) ? path.relative(root, p).split(path.sep).join('/') : p.replace(/\\/g, '/');
  if (rel === '' || rel.startsWith('/') || rel.split('/').some((s) => s === '' || s === '.' || s === '..')) return undefined;
  return rel;
}

/** A path inside the root, for changes the workspace writes or materialises. Throws for anything else. */
export function assertRelativePath(rel: string): void {
  if (rel === '' || rel.startsWith('/') || /[\\\0]/.test(rel) || rel.split('/').some((s) => s === '' || s === '.' || s === '..')) {
    throw new TypeError(`not a relative POSIX path inside the model root: ${JSON.stringify(rel)}`);
  }
}

