/**
 * The board's SemanticSummary from the latest refresh and the facts in use (docs/m1-plan.md section 4, "Mapping to
 * the board's SemanticSummary"):
 *
 *   ok                          -> fresh (stale when files changed since)
 *   build-errors, check-errors  -> failed with errorCount (facts for fresh modules are still used)
 *   low-memory                  -> paused-low-memory
 *   unsupported-toolchain       -> unsupported-toolchain (syntactic mode, D-7)
 *   unsupported-project         -> disabled with the detail (+ diagnostic TL201)
 *   could-not-start             -> disabled ("sandbox unavailable: …")
 *   timeout, oom, cancelled     -> failed with the detail
 *
 * Refreshes that produce no facts keep the previous facts in use (marked stale where hashes differ).
 */
import type { BoardDiagnostic, FactsStatus, LeanFacts, SemanticSummary } from '@telelean/core';

/** Statuses whose LeanFacts carry no usable facts: the previous facts stay in use. */
export const NO_FACTS_STATUSES: ReadonlySet<FactsStatus> = new Set<FactsStatus>([
  'could-not-start',
  'timeout',
  'oom',
  'cancelled',
  'low-memory',
  'unsupported-toolchain',
  'unsupported-project',
]);

/** What the workspace remembers about its last refresh. */
export interface RefreshRecord {
  /** The facts' status, or `error` when the refresh itself threw. */
  status: FactsStatus | 'error';
  detail?: string;
  toolchain?: string;
  durationMs?: number;
}

export interface SummaryInput {
  enabled: boolean;
  running: boolean;
  phase?: 'build' | 'check';
  last?: RefreshRecord;
  /** The facts in use (possibly from an earlier refresh). */
  facts?: LeanFacts;
  /** sha256 of every current model file, by path. */
  fileHashes: Readonly<Record<string, string>>;
}

/** Model files whose current text is not the one the facts were computed from (changed, new, deleted or stale). */
export function staleFilesOf(facts: LeanFacts, fileHashes: Readonly<Record<string, string>>): string[] {
  const stale = new Set<string>();
  const covered = new Set<string>();
  for (const module of facts.modules) {
    covered.add(module.file);
    if (module.state === 'stale' || fileHashes[module.file] !== module.sourceSha256) stale.add(module.file);
  }
  for (const file of Object.keys(fileHashes)) if (!covered.has(file)) stale.add(file);
  return [...stale].sort();
}

/** Lean errors in the facts: build error messages plus declarations whose probe failed. */
export function errorCountOf(facts: LeanFacts): number {
  return facts.build.messages.filter((m) => m.severity === 'error').length + facts.decls.filter((d) => d.error !== undefined).length;
}

export function summarize(input: SummaryInput): SemanticSummary {
  if (!input.enabled) return { state: 'disabled', detail: 'Lean checking is switched off.' };
  const facts = input.facts;
  const common: Omit<SemanticSummary, 'state'> = {};
  const toolchain = facts?.toolchain || input.last?.toolchain;
  if (toolchain) common.toolchain = toolchain;
  if (facts) {
    common.checkedAt = facts.finishedAt;
    const stale = staleFilesOf(facts, input.fileHashes);
    if (stale.length > 0) common.staleFiles = stale;
    const errors = errorCountOf(facts);
    if (errors > 0) common.errorCount = errors;
  }
  if (input.last?.durationMs !== undefined) common.durationMs = input.last.durationMs;

  if (input.running) {
    const detail = input.phase === 'build' ? 'Lean: building the project…' : input.phase === 'check' ? 'Lean: checking declarations…' : 'Lean: starting…';
    return { ...common, state: 'checking', detail };
  }
  const last = input.last;
  if (!last) return facts ? { ...common, state: common.staleFiles ? 'stale' : 'fresh' } : { state: 'unavailable', ...common };
  const detail = last.detail?.trim() || undefined;
  const withDetail = (text: string | undefined): Partial<SemanticSummary> => (text ? { detail: text } : {});
  switch (last.status) {
    case 'ok':
      if (!facts) return { ...common, state: 'unavailable' };
      return { ...common, state: common.staleFiles ? 'stale' : 'fresh' };
    case 'build-errors':
      return { ...common, ...withDetail(detail ?? 'The Lean build reported errors.'), state: 'failed' };
    case 'check-errors':
      return { ...common, ...withDetail(detail ?? 'Lean reported errors while checking declarations.'), state: 'failed' };
    case 'low-memory':
      return { ...common, ...withDetail(detail ?? 'Lean paused: low memory.'), state: 'paused-low-memory' };
    case 'unsupported-toolchain':
      return { ...common, ...withDetail(detail), state: 'unsupported-toolchain' };
    case 'unsupported-project':
      return { ...common, ...withDetail(detail ?? 'This project cannot be checked as it is.'), state: 'disabled' };
    case 'could-not-start':
      return { ...common, ...withDetail(`sandbox unavailable: ${detail ?? 'unknown reason'}`), state: 'disabled' };
    case 'timeout':
      return { ...common, ...withDetail(detail ?? 'Lean timed out.'), state: 'failed' };
    case 'oom':
      return { ...common, ...withDetail(detail ?? 'Lean ran out of memory (memory cap reached).'), state: 'failed' };
    case 'cancelled':
      return { ...common, ...withDetail(detail ?? 'The Lean check was cancelled.'), state: 'failed' };
    case 'error':
      return { ...common, ...withDetail(`refresh failed: ${detail ?? 'unknown error'}`), state: 'failed' };
  }
}

/** Workspace diagnostics derived from the last refresh: TL201 when the project cannot be checked as it is. */
export function refreshDiagnostics(last: RefreshRecord | undefined): BoardDiagnostic[] {
  if (last?.status !== 'unsupported-project') return [];
  return [{ code: 'TL201', severity: 'warning', message: last.detail?.trim() || 'This project cannot be checked as it is (lake-manifest.json or Lake dependencies).' }];
}

/**
 * Turning an EditPlan's sidecars into whole-file FileChanges (docs/m1-plan.md sections 2 and 7.1):
 *
 *   plan.layout   -> `.telelean/subjects/<S>/layout.json` (serializeLayout)
 *   plan.archive  -> `.telelean/subjects/<S>/attic/<id>.lean`, each entry appended as
 *                      -- archived <ISO time> (<reason>): <declName>
 *                      <the declaration's text, verbatim>
 *                    with a blank line between entries.
 */
import { ActionError, atticPath, layoutPath, serializeLayout, type ArchiveEntry, type EditPlan, type FileChange } from '@telelean/core';

import { assertRelativePath } from './files.js';

/** The attic text after appending `entries` (archived at `nowIso`) to `before` (null: a new file). */
export function appendToAttic(before: string | null, entries: readonly ArchiveEntry[], nowIso: string): string {
  const oneLine = (s: string): string => s.replace(/[\r\n]+/g, ' ').trim();
  const blocks = entries.map((entry) => {
    const text = entry.text.endsWith('\n') ? entry.text : `${entry.text}\n`;
    return `-- archived ${nowIso} (${oneLine(entry.reason)}): ${oneLine(entry.declName)}\n${text}`;
  });
  const appendix = blocks.join('\n');
  if (before === null || before === '') return appendix;
  return `${before.endsWith('\n') ? before : `${before}\n`}\n${appendix}`;
}

/**
 * The plan's Lean changes followed by its sidecar changes, as whole files; unchanged files are dropped. Throws
 * ActionError `internal` when the plan changes one path twice or names a path outside the root.
 */
export async function materialisePlan(plan: EditPlan, read: (path: string) => Promise<string | null>, nowIso: string): Promise<FileChange[]> {
  const out: FileChange[] = [];
  const seen = new Set<string>();
  const add = (change: FileChange): void => {
    try {
      assertRelativePath(change.path);
    } catch (error) {
      throw new ActionError('internal', (error as Error).message);
    }
    if (seen.has(change.path)) throw new ActionError('internal', `the plan changes ${change.path} twice`);
    seen.add(change.path);
    if (change.before !== change.after) out.push({ path: change.path, before: change.before, after: change.after });
  };
  for (const change of plan.changes) add(change);
  if (plan.layout) {
    const rel = layoutPath(plan.layout.subject);
    add({ path: rel, before: await read(rel), after: serializeLayout(plan.layout.layout) });
  }
  const bySidecar = new Map<string, ArchiveEntry[]>();
  for (const entry of plan.archive ?? []) {
    const rel = atticPath(entry.subject, entry.nodeId);
    bySidecar.set(rel, [...(bySidecar.get(rel) ?? []), entry]);
  }
  for (const [rel, entries] of bySidecar) {
    const before = await read(rel);
    add({ path: rel, before, after: appendToAttic(before, entries, nowIso) });
  }
  return out;
}

/**
 * "telelean: Initialize Model Here" (D-28; docs/m1-plan.md sections 7.1 and 7.2): what a folder is, which files
 * opting it in creates, where model roots are, and `git init` for D-33 history.
 */
import type { Dirent } from 'node:fs';
import { readdir, readFile, stat } from 'node:fs/promises';
import path from 'node:path';

import {
  CONFIG_PATH,
  DEFAULT_LIBRARY,
  defaultProjectConfig,
  emptyLayout,
  isSubjectName,
  layoutPath,
  libraryRootFile,
  parseProjectConfig,
  PINNED_TOOLCHAIN_NAME,
  serializeLayout,
  serializeProjectConfig,
  subjectScaffold,
  type FileChange,
} from '@telelean/core';

import { discoverRepository, runGit } from './git.js';
import type { FolderInspection, InitializeOptions } from './types.js';

/** `lakefile.toml` of a new model folder: a byte copy of `test-fixtures/spyro/lakefile.toml` (tests compare them). */
export const SCAFFOLD_LAKEFILE_TOML =
  'name = "Model"\ndefaultTargets = ["Model"]\n\n[leanOptions]\nautoImplicit = false\nrelaxedAutoImplicit = false\n\n[[lean_lib]]\nname = "Model"\n';

/** `lake-manifest.json` of a new model folder: a byte copy of `test-fixtures/spyro/lake-manifest.json` (Lake 5.0 builds with it and never rewrites it). */
export const SCAFFOLD_LAKE_MANIFEST =
  '{"version": "1.3.0",\n "packagesDir": ".lake/packages",\n "packages": [],\n "name": "Model",\n "lakeDir": ".lake",\n "fixedToolchain": false}\n';

export const SCAFFOLD_LEAN_TOOLCHAIN = `${PINNED_TOOLCHAIN_NAME}\n`;

/** The `.gitignore` lines telelean needs (build output and the unshared sidecars). */
export const GITIGNORE_LINES: readonly string[] = ['/.lake/', '/.telelean/graph.json', '/.telelean/frozen/', '/.telelean/sessions/'];

const LIBRARY_NAME_PATTERN = /^[A-Za-z_][A-Za-z0-9_]*$/;

async function readText(absolute: string): Promise<string | undefined> {
  try {
    return await readFile(absolute, 'utf8');
  } catch {
    return undefined;
  }
}

async function isRegularFile(absolute: string): Promise<boolean> {
  try {
    return (await stat(absolute)).isFile();
  } catch {
    return false;
  }
}

/** The facts of a `lakefile.toml` that matter here (a deliberately small reader: tables, `name = "…"`, `require`). */
export interface LakefileSummary {
  /** `name` of each `[[lean_lib]]`, in order (undefined when a table has no plain string name). */
  leanLibs: Array<string | undefined>;
  /** Names of `[[require]]` entries (or `?` when unnamed), plus `?` for an inline `require = …`. */
  requires: string[];
}

/** Reads the parts of a Lake TOML configuration that Initialize needs. Unknown syntax is ignored. */
export function readLakefileToml(text: string): LakefileSummary {
  const summary: LakefileSummary = { leanLibs: [], requires: [] };
  let table: 'lean_lib' | 'require' | 'other' | 'root' = 'root';
  for (const rawLine of text.split(/\r?\n/)) {
    const line = stripTomlComment(rawLine).trim();
    if (line === '') continue;
    const arrayTable = /^\[\[\s*([^\]]+?)\s*\]\]$/.exec(line);
    if (arrayTable) {
      const name = unquoteKey(arrayTable[1] ?? '');
      table = name === 'lean_lib' ? 'lean_lib' : name === 'require' ? 'require' : 'other';
      if (table === 'lean_lib') summary.leanLibs.push(undefined);
      if (table === 'require') summary.requires.push('?');
      continue;
    }
    if (/^\[[^\]]*\]$/.test(line)) {
      table = 'other';
      continue;
    }
    const keyValue = /^([A-Za-z0-9_."'-]+)\s*=\s*(.*)$/.exec(line);
    if (!keyValue) continue;
    const key = unquoteKey(keyValue[1] ?? '');
    const value = keyValue[2] ?? '';
    if (table === 'root' && (key === 'require' || key.startsWith('require.'))) summary.requires.push('?');
    if (key !== 'name') continue;
    const name = tomlString(value);
    if (table === 'lean_lib' && name !== undefined) summary.leanLibs[summary.leanLibs.length - 1] = name;
    if (table === 'require' && name !== undefined) summary.requires[summary.requires.length - 1] = name;
  }
  return summary;
}

function stripTomlComment(line: string): string {
  let quote: string | undefined;
  for (let i = 0; i < line.length; i++) {
    const c = line[i];
    if (quote) {
      if (c === '\\' && quote === '"') i++;
      else if (c === quote) quote = undefined;
    } else if (c === '"' || c === "'") quote = c;
    else if (c === '#') return line.slice(0, i);
  }
  return line;
}

function unquoteKey(key: string): string {
  return key.trim().replace(/^"(.*)"$/, '$1').replace(/^'(.*)'$/, '$1');
}

function tomlString(value: string): string | undefined {
  const match = /^"((?:[^"\\]|\\.)*)"\s*$/.exec(value.trim()) ?? /^'([^']*)'\s*$/.exec(value.trim());
  return match ? (match[1] ?? '') : undefined;
}

/** Names of the packages a `lake-manifest.json` lists, or undefined when it is not a manifest. */
export function manifestPackages(text: string): string[] | undefined {
  try {
    const raw = JSON.parse(text) as { packages?: unknown };
    if (!Array.isArray(raw.packages)) return undefined;
    return raw.packages.map((p) => (typeof (p as { name?: unknown })?.name === 'string' ? (p as { name: string }).name : '?'));
  } catch {
    return undefined;
  }
}

function dependencyReason(names: readonly string[]): string {
  const listed = [...new Set(names.filter((n) => n !== '?'))];
  const which = listed.length > 0 ? ` (${listed.join(', ')})` : '';
  return `This project has Lake dependencies${which}: not supported in M1, which checks only dependency-free models. Mathlib needs an explicit opt-in (M4).`;
}

async function hasLeanFile(absoluteDir: string, depth = 0): Promise<boolean> {
  if (depth > 8) return false;
  let entries: Dirent[];
  try {
    entries = await readdir(absoluteDir, { withFileTypes: true });
  } catch {
    return false;
  }
  for (const entry of entries) {
    if (entry.isFile() && entry.name.endsWith('.lean')) return true;
  }
  for (const entry of entries) {
    if (entry.isDirectory() && !entry.name.startsWith('.') && (await hasLeanFile(path.join(absoluteDir, entry.name), depth + 1))) return true;
  }
  return false;
}

/** What "Initialize Model Here" would do in `root` (docs/m1-plan.md section 7.2). */
export async function inspectFolder(root: string): Promise<FolderInspection> {
  const abs = path.resolve(root);
  let entries: Dirent[];
  try {
    entries = await readdir(abs, { withFileTypes: true });
  } catch (error) {
    return { kind: 'unsupported', reason: `${abs} cannot be read: ${(error as Error).message}` };
  }
  const configText = await readText(path.join(abs, CONFIG_PATH));
  if (configText !== undefined) return { kind: 'model', config: parseProjectConfig(configText) };

  const gitignore = await readText(path.join(abs, '.gitignore'));
  const withGitignore = <T extends object>(value: T): T & { gitignore?: string } => (gitignore !== undefined ? { ...value, gitignore } : value);
  const visible = entries.filter((e) => !e.name.startsWith('.'));
  if (visible.length === 0) return withGitignore({ kind: 'empty' as const });

  const has = (name: string): boolean => entries.some((e) => e.name === name && e.isFile());
  if (has('lakefile.toml') && has('lakefile.lean')) {
    return {
      kind: 'unsupported',
      reason: 'This folder has both lakefile.lean and lakefile.toml; Lake uses lakefile.lean, and telelean M1 reads lakefile.toml only. Remove one of them.',
    };
  }
  if (!has('lakefile.toml')) {
    if (has('lakefile.lean')) {
      return {
        kind: 'unsupported',
        reason: 'This Lake project is configured by lakefile.lean; telelean M1 needs lakefile.toml (Lake can convert it: `lake translate-config toml`).',
      };
    }
    return {
      kind: 'unsupported',
      reason: 'This folder has files but no Lake project (lakefile.toml). Initialize telelean in an empty folder, or in a Lake project.',
    };
  }
  const lakefile = readLakefileToml((await readText(path.join(abs, 'lakefile.toml'))) ?? '');
  if (lakefile.requires.length > 0) return { kind: 'unsupported', reason: dependencyReason(lakefile.requires) };
  if (lakefile.leanLibs.length === 0) return { kind: 'unsupported', reason: 'lakefile.toml declares no [[lean_lib]]: telelean keeps the model in a Lake library.' };
  const library = lakefile.leanLibs[0];
  if (library === undefined || !LIBRARY_NAME_PATTERN.test(library)) {
    return { kind: 'unsupported', reason: `The first [[lean_lib]] of lakefile.toml needs a plain identifier as its name (found ${JSON.stringify(library ?? '')}).` };
  }
  const manifestText = await readText(path.join(abs, 'lake-manifest.json'));
  if (manifestText === undefined) {
    return { kind: 'unsupported', reason: 'lake-manifest.json is missing: telelean checks the project in a read-only sandbox, where Lake cannot create it.' };
  }
  const packages = manifestPackages(manifestText);
  if (packages === undefined) return { kind: 'unsupported', reason: 'lake-manifest.json is not a valid Lake manifest.' };
  if (packages.length > 0) return { kind: 'unsupported', reason: dependencyReason(packages) };

  const subjects: string[] = [];
  let libraryEntries: Dirent[] = [];
  try {
    libraryEntries = await readdir(path.join(abs, library), { withFileTypes: true });
  } catch {
    // no library directory yet: no subjects
  }
  for (const entry of libraryEntries) {
    if (entry.isDirectory() && isSubjectName(entry.name) && (await hasLeanFile(path.join(abs, library, entry.name)))) subjects.push(entry.name);
  }
  return withGitignore({ kind: 'lake-project' as const, library, subjects: subjects.sort() });
}

/** `.gitignore` after adding the lines telelean needs that are missing (equivalent spellings count as present). */
export function gitignoreWithTeleleanLines(before: string | undefined): string {
  const normalise = (line: string): string => line.trim().replace(/^\//, '').replace(/\/$/, '');
  const present = new Set((before ?? '').split(/\r?\n/).map(normalise));
  const missing = GITIGNORE_LINES.filter((line) => !present.has(normalise(line)));
  if (before === undefined) return `${GITIGNORE_LINES.join('\n')}\n`;
  if (missing.length === 0) return before;
  const eol = before.includes('\r\n') ? '\r\n' : '\n';
  const base = before === '' || before.endsWith('\n') ? before : `${before}${eol}`;
  return `${base}${missing.join(eol)}${eol}`;
}

/**
 * The files Initialize creates (docs/m1-plan.md section 7.2). Throws TypeError for a `model` or `unsupported`
 * inspection, and for an invalid subject name when scaffolding an empty folder (a Lake project keeps its own
 * subjects, so `subject` is not used there).
 */
export function planInitialize(options: InitializeOptions): FileChange[] {
  const { inspection } = options;
  if (inspection.kind === 'model' || inspection.kind === 'unsupported') {
    throw new TypeError(`cannot initialize a folder that is ${inspection.kind === 'model' ? 'already a telelean model' : 'not supported'}`);
  }
  const gitignoreChange = (): FileChange | undefined => {
    const before = inspection.gitignore;
    const after = gitignoreWithTeleleanLines(before);
    return before === after ? undefined : { path: '.gitignore', before: before ?? null, after };
  };
  const created = (rel: string, text: string): FileChange => ({ path: rel, before: null, after: text });

  if (inspection.kind === 'empty') {
    const subject = options.subject;
    if (!isSubjectName(subject)) throw new TypeError(`"${subject}" is not a subject name: use a capitalised Lean identifier (letters, digits, "_")`);
    const changes: FileChange[] = [
      created('lakefile.toml', SCAFFOLD_LAKEFILE_TOML),
      created('lean-toolchain', SCAFFOLD_LEAN_TOOLCHAIN),
      created('lake-manifest.json', SCAFFOLD_LAKE_MANIFEST),
    ];
    const gitignore = gitignoreChange();
    if (gitignore) changes.push(gitignore);
    changes.push(created(libraryRootFile(DEFAULT_LIBRARY), `import ${DEFAULT_LIBRARY}.${subject}\n`));
    for (const file of subjectScaffold(subject, DEFAULT_LIBRARY)) changes.push(created(file.path, file.text));
    changes.push(created(CONFIG_PATH, serializeProjectConfig(defaultProjectConfig())));
    changes.push(created(layoutPath(subject), serializeLayout(emptyLayout())));
    return changes;
  }

  const changes: FileChange[] = [created(CONFIG_PATH, serializeProjectConfig({ ...defaultProjectConfig(), library: inspection.library }))];
  const gitignore = gitignoreChange();
  if (gitignore) changes.push(gitignore);
  for (const subject of [...new Set(inspection.subjects)].filter(isSubjectName).sort()) changes.push(created(layoutPath(subject), serializeLayout(emptyLayout())));
  return changes;
}

/**
 * The default first-subject name for a folder: its name as a capitalised identifier (`mental_model` ->
 * `MentalModel`; characters outside `[A-Za-z0-9]` separate words and are dropped), else `Subject`.
 */
export function suggestSubjectName(folderName: string): string {
  const words = folderName.split(/[^A-Za-z0-9]+/).filter((w) => w !== '');
  const name = words
    .map((w) => `${w.charAt(0).toUpperCase()}${w.slice(1)}`)
    .join('')
    .slice(0, 64);
  return isSubjectName(name) ? name : 'Subject';
}

/** Model roots (directories holding `.telelean/config.json`) under `folder`, nested ones included, sorted. */
export async function findModelRoots(
  folder: string,
  excludedDirs: readonly string[],
  maxDepth: number,
): Promise<string[]> {
  const excluded = new Set(excludedDirs);
  const roots: string[] = [];
  const queue: Array<{ dir: string; depth: number }> = [{ dir: path.resolve(folder), depth: 0 }];
  while (queue.length > 0) {
    const { dir, depth } = queue.shift() ?? { dir: '', depth: 0 };
    if (await isRegularFile(path.join(dir, CONFIG_PATH))) roots.push(dir);
    if (depth >= maxDepth) continue;
    let entries: Dirent[];
    try {
      entries = await readdir(dir, { withFileTypes: true });
    } catch {
      continue;
    }
    for (const entry of entries) {
      if (entry.isDirectory() && !entry.name.startsWith('.') && !excluded.has(entry.name)) queue.push({ dir: path.join(dir, entry.name), depth: depth + 1 });
    }
  }
  return roots.sort();
}

/**
 * `git init` in `root` with telelean's safe settings, refusing when `root` is already inside a repository (or
 * when git cannot tell). Never adds remotes and never commits to a branch.
 */
export async function initGitRepository(root: string, gitPath = 'git'): Promise<void> {
  const abs = path.resolve(root);
  let st;
  try {
    st = await stat(abs);
  } catch {
    throw new Error(`${abs} does not exist`);
  }
  if (!st.isDirectory()) throw new Error(`${abs} is not a directory`);
  const repo = await discoverRepository(gitPath, abs);
  if (repo !== 'no-repo') throw new Error(`${abs} is already inside the git repository at ${repo.topLevel}`);
  await runGit(gitPath, ['init', '--quiet'], { cwd: abs });
}

/**
 * Disk-only TextSource and EditApplier for a model root. The extension uses its own (open editor buffers first,
 * WorkspaceEdit + save); these serve tests, the integrator's end-to-end test and later command-line use.
 */
import { mkdir, readFile, rename, rm, writeFile } from 'node:fs/promises';
import path from 'node:path';

import { ActionError, type FileChange } from '@telelean/core';

import { assertRelativePath } from './files.js';
import type { EditApplier, TextSource } from './types.js';

function resolveInside(root: string, rel: string): string {
  assertRelativePath(rel);
  const base = path.resolve(root);
  const absolute = path.resolve(base, rel);
  if (!absolute.startsWith(base + path.sep)) throw new TypeError(`${rel} is outside ${base}`);
  return absolute;
}

async function readOrNull(absolute: string): Promise<string | null> {
  try {
    return await readFile(absolute, 'utf8');
  } catch (error) {
    const code = (error as NodeJS.ErrnoException).code;
    if (code === 'ENOENT' || code === 'ENOTDIR') return null;
    throw error;
  }
}

async function writeOrDelete(absolute: string, text: string | null): Promise<void> {
  if (text === null) {
    await rm(absolute, { force: true });
    return;
  }
  await mkdir(path.dirname(absolute), { recursive: true });
  const temp = `${absolute}.telelean-${process.pid}.tmp`;
  await writeFile(temp, text, 'utf8');
  await rename(temp, absolute);
}

/** Reads files of `root` from disk (`null` when missing). */
export function fsTextSource(root: string): TextSource {
  return { read: (rel) => readOrNull(resolveInside(root, rel)) };
}

/**
 * Applies whole-file changes to disk: first checks every `before` (rejects with ActionError `conflict`, writing
 * nothing), then writes; if a write fails, the files already written are restored before rejecting.
 */
export function fsEditApplier(root: string): EditApplier {
  return {
    async apply(changes: readonly FileChange[]): Promise<void> {
      const targets = changes.map((change) => ({ change, absolute: resolveInside(root, change.path) }));
      for (const { change, absolute } of targets) {
        const current = await readOrNull(absolute);
        if (current !== change.before) {
          throw new ActionError('conflict', `${change.path} changed since the edit was planned; nothing was written.`);
        }
      }
      const done: Array<{ change: FileChange; absolute: string }> = [];
      try {
        for (const target of targets) {
          await writeOrDelete(target.absolute, target.change.after);
          done.push(target);
        }
      } catch (error) {
        for (const { change, absolute } of done.reverse()) {
          try {
            await writeOrDelete(absolute, change.before);
          } catch {
            // best effort: the original error below matters more
          }
        }
        throw error;
      }
    },
  };
}

/**
 * ModelWorkspace: one opted-in model root, without vscode (docs/m1-plan.md sections 2, 3, 4 and 8).
 *
 *   load()          config -> list `<library>.lean`, `<library>/**.lean`, `.telelean/subjects/<S>/layout.json`
 *                   -> read through the TextSource -> sha256 -> (lazily) core parseLeanFile, cached by path + hash;
 *                   then "Initial state" snapshots for chains that do not exist yet
 *   graph(S)        core.subjectGraph(core.buildProjectModel(files, hashes, facts, library), S, layout, semantic)
 *   invalidate      re-read changed files (latest read wins), drop deleted ones, fire onDidChange
 *   requestRefresh  debounce -> coalesce -> semantic.runExclusive(refreshLeanFacts) -> map the status
 *                   (./semanticSummary.ts) -> keep previous facts on failure -> rewrite .telelean/graph.json
 *   perform         planAction -> materialise sidecars -> "Manual edits" snapshots -> EditApplier.apply
 *                   -> action snapshots (not for layout-only) -> undo entry -> re-read -> graph.json -> refresh
 *   undo/redo       ./undo.ts, applied and snapshotted like actions ("Undo: …" / "Redo: …")
 *   history         ./history.ts (private refs; revert is snapshotted and undoable; prune; storage counter)
 *
 * perform, undo, redo, revert, prune, initGit and the initial snapshots run one at a time in one queue.
 */
