 * A small stand-in for the core functions a ModelWorkspace calls (ModelWorkspaceOptions.core), so the workspace's
 * own logic (scan, refresh, sidecars, undo, history, graph.json) is tested while WP1/WP2 are built in parallel.
 * It understands just enough of the markup (`id`, `type`, `natural_name` lines of `@@ telelean v1` blocks).
 */
import {
  ActionError,
  appendToLayout,
  createUserNode,
  emptyLayout,
  inboxPath,
  isSubjectName,
  libraryRootFile,
  moveInLayout,
