    expect(again.copiedBuild).toBe(true);
    expect(r2.status).toBe('ok');
    expect(rebuilt).toBe(0);
    expect(r.stdout.split('\n').filter((l) => /Built /.test(l)).length).toBeGreaterThan(0); // the regex does see real builds
  });

