/**
 * Text helpers for the semantic layer: line indexes, Lean (code point) to LSP (UTF-16) positions, and the few
 * pieces of Lean source scanning the facts need (docstrings, the `instance` keyword, import headers).
 *
 * Lean reports message positions as a 1-based line and a 0-based column counted in Unicode code points; the board
 * (and the `.ilean` files) use LSP positions: 0-based line and UTF-16 code units. A character outside the Basic
 * Multilingual Plane (e.g. `𝔸`) is one code point but two UTF-16 units, so columns after it differ.
 */
import type { Position } from '@telelean/core';

/** Start offsets (UTF-16 indexes into the string) of every line; lines end at `\n` (a preceding `\r` stays in the line). */
export function lineStarts(text: string): number[] {
  const starts = [0];
  for (let i = text.indexOf('\n'); i >= 0; i = text.indexOf('\n', i + 1)) starts.push(i + 1);
  return starts;
}

/** The text of a 0-based line (without its `\n`), or undefined past the end. */
export function lineText(text: string, starts: readonly number[], line: number): string | undefined {
  const start = starts[line];
  if (start === undefined) return undefined;
  const next = starts[line + 1];
  return text.slice(start, next === undefined ? text.length : next - 1);
}

/**
 * UTF-16 length of the first `codePoints` code points of `line`. Columns past the end of the line count one unit
 * each (Lean can point just past the last character).
 */
export function codePointsToUtf16(line: string, codePoints: number): number {
  let units = 0;
  let seen = 0;
  for (const ch of line) {
    if (seen >= codePoints) return units;
    units += ch.length;
    seen++;
  }
  return units + Math.max(0, codePoints - seen);
}

/**
 * Converts a Lean message position (1-based line, 0-based code-point column) to an LSP position (0-based line,
 * UTF-16 character) using the source text the build saw. Without the text the column is kept as is.
 */
export function leanToLspPosition(line1: number, column: number, text?: string, starts?: readonly number[]): Position {
  const line = Math.max(0, line1 - 1);
  if (text === undefined) return { line, character: column };
  const lineContent = lineText(text, starts ?? lineStarts(text), line);
  return { line, character: lineContent === undefined ? column : codePointsToUtf16(lineContent, column) };
}

/** UTF-16 offset of an LSP position, or undefined when the line does not exist. Characters are clamped to the line. */
export function offsetOf(text: string, starts: readonly number[], pos: Position): number | undefined {
  const start = starts[pos.line];
  if (start === undefined) return undefined;
  const next = starts[pos.line + 1];
  const end = next === undefined ? text.length : next - 1;
  return Math.min(start + Math.max(0, pos.character), end);
}

/** Every run of whitespace becomes one space; leading and trailing whitespace is removed. */
export function normalizeWhitespace(s: string): string {
  return s.replace(/\s+/gu, ' ').trim();
}

/**
 * The end offset (just past `-/`) of the block comment that starts at `start` (`/-`, `/--` or `/-!`), honouring
 * nesting as Lean does; undefined when it is not terminated.
 */
export function blockCommentEnd(text: string, start: number): number | undefined {
  if (!text.startsWith('/-', start)) return undefined;
  let depth = 1;
  let i = start + 2;
  while (i < text.length) {
    if (text.startsWith('/-', i)) {
      depth++;
      i += 2;
    } else if (text.startsWith('-/', i)) {
      depth--;
      i += 2;
      if (depth === 0) return i;
    } else {
      i++;
    }
  }
  return undefined;
}

/** The docstring (between `/--` and `-/`, trimmed) that starts exactly at `offset`, if any. */
export function docstringAt(text: string, offset: number): string | undefined {
  if (!text.startsWith('/--', offset) || text.startsWith('/--/', offset)) return undefined;
  const end = blockCommentEnd(text, offset);
  if (end === undefined) return undefined;
  return text.slice(offset + 3, end - 2).trim();
}

/**
 * The docstring that ends right before `offset` (only whitespace in between), with its start offset. Used for
 * auxiliary declarations such as structure fields, whose `.ilean` entry gives only the name's range.
 */
export function docstringBefore(text: string, offset: number): { start: number; text: string } | undefined {
  let i = offset;
  while (i > 0 && /\s/u.test(text.charAt(i - 1))) i--;
  if (!text.startsWith('-/', i - 2)) return undefined;
  // Walk back over candidate `/--` openings; the right one is the closest whose comment ends exactly at `i`.
  for (let open = text.lastIndexOf('/--', i - 2); open >= 0; open = open === 0 ? -1 : text.lastIndexOf('/--', open - 1)) {
    const end = blockCommentEnd(text, open);
    if (end === i) {
      const doc = docstringAt(text, open);
      return doc === undefined ? undefined : { start: open, text: doc };
    }
  }
  return undefined;
}

const IDENT_CHAR = /[\p{L}\p{N}_'!?₀-₉ₐ-ₜᵢ-ᵪ]/u;
/** Modifiers (and attribute kinds) that may precede a declaration keyword. */
const DECL_MODIFIERS = new Set(['private', 'protected', 'public', 'noncomputable', 'unsafe', 'partial', 'nonrec', 'meta', 'scoped', 'local']);

/** Skips whitespace, line comments and block comments (doc comments included) from `i`. */
function skipTrivia(text: string, i: number): number {
  for (;;) {
    while (i < text.length && /\s/u.test(text.charAt(i))) i++;
    if (text.startsWith('--', i)) {
      const nl = text.indexOf('\n', i);
      i = nl < 0 ? text.length : nl + 1;
    } else if (text.startsWith('/-', i)) {
      const end = blockCommentEnd(text, i);
      if (end === undefined) return text.length;
      i = end;
    } else {
      return i;
    }
  }
}

/** Skips a balanced `@[ … ]` attribute block at `i` (brackets inside strings are not special-cased). */
function skipAttributes(text: string, i: number): number {
  let depth = 0;
  for (let j = i + 1; j < text.length; j++) {
    const c = text.charAt(j);
    if (c === '[') depth++;
    else if (c === ']') {
      depth--;
      if (depth === 0) return j + 1;
    }
  }
  return text.length;
}

/**
 * The declaration keyword at `offset` (the start of a declaration's full range), after its docstring, attributes
 * and modifiers: e.g. `instance` for `/-- doc -/ @[simp] noncomputable instance foo : …`. Undefined when no word
 * follows.
 */
export function declKeywordAt(text: string, offset: number): string | undefined {
  let i = offset;
  for (let guard = 0; guard < 64; guard++) {
    i = skipTrivia(text, i);
    if (text.startsWith('@[', i)) {
      i = skipAttributes(text, i);
      continue;
    }
    let j = i;
    while (j < text.length && IDENT_CHAR.test(text.charAt(j))) j++;
    if (j === i) return undefined;
    const word = text.slice(i, j);
    if (!DECL_MODIFIERS.has(word)) return word;
    i = j;
  }
  return undefined;
}

/**
 * The modules a Lean file imports, from its header: an optional `module`/`prelude`, then `import` commands
 * (with the module-system forms `public import`, `meta import`, `import all`). Stops at the first other token.
 */
export function parseImports(text: string): string[] {
  const imports: string[] = [];
  let i = 0;
  const word = (): string | undefined => {
    i = skipTrivia(text, i);
    if (i >= text.length) return undefined;
    let j = i;
    if (text.charAt(j) === '«') {
      // Escaped module names: keep the guillemets as written; such names never match a project module path.
      while (j < text.length && !/\s/u.test(text.charAt(j))) {
        if (text.charAt(j) === '»') {
          j++;
          if (j >= text.length || /\s/u.test(text.charAt(j))) break;
        } else j++;
      }
    } else {
      while (j < text.length && !/\s/u.test(text.charAt(j))) j++;
    }
    return text.slice(i, j);
  };
  const advance = (w: string): void => {
    i += w.length;
  };
  for (let guard = 0; guard < 100_000; guard++) {
    const w = word();
    if (w === undefined) break;
    if (w === 'module' || w === 'prelude' || w === 'public' || w === 'private' || w === 'meta') {
      advance(w);
      continue;
    }
    if (w !== 'import') break;
    advance(w);
    let name = word();
    if (name === 'all' || name === 'runtime') {
      advance(name);
      name = word();
    }
    if (name === undefined) break;
    advance(name);
    imports.push(name);
  }
  return imports;
}

/**
 * The model project as the semantic layer sees it (docs/m1-plan.md section 4, steps 2, 3 and 5): the pinned
 * toolchain, the dependency-free Lake manifest, the library's modules (source text, sha256, imports) and the state
 * of each module after a build.
 */
import { createHash } from 'node:crypto';
import { lstatSync, readdirSync, readFileSync, type Dirent } from 'node:fs';
import path from 'node:path';

import type { ModuleFacts } from '@telelean/core';

import { isValidModuleName } from '../lean/leanNames.js';
import { PINNED_TOOLCHAIN } from '../lean/toolchain.js';
import { parseImports } from './text.js';

export type ModuleState = ModuleFacts['state'];

/** sha256 (hex) of a text's UTF-8 encoding: what core compares with `ModuleFacts.sourceSha256`. */
export function sha256Text(text: string): string {
  return createHash('sha256').update(text, 'utf8').digest('hex');
}

/** The project's `lean-toolchain`, trimmed (`''` when missing), and why it cannot be checked, if it cannot. */
export function readProjectToolchain(root: string): { toolchain: string; problem?: string } {
  let toolchain: string;
  try {
    toolchain = readFileSync(path.join(root, 'lean-toolchain'), 'utf8').trim();
  } catch (e) {
    const missing = (e as NodeJS.ErrnoException).code === 'ENOENT';
    return { toolchain: '', problem: missing ? 'lean-toolchain is missing' : `lean-toolchain cannot be read: ${(e as Error).message}` };
  }
  if (toolchain !== PINNED_TOOLCHAIN) {
    return {
      toolchain,
      problem: `lean-toolchain pins ${JSON.stringify(toolchain)}; telelean checks only ${PINNED_TOOLCHAIN} (D-7), so the board stays syntactic`,
    };
  }
  return { toolchain };
}

/**
 * Why M1 cannot check this project as it is, or undefined: a lakefile must exist, and `lake-manifest.json` must
 * exist (the sandbox keeps the root read-only, so Lake could not write one) and list no packages (Lake
 * dependencies such as Mathlib need an explicit opt-in, D-28/M4, and break the RAM rule).
 */
export function projectProblem(root: string): string | undefined {
  const hasLakefile = ['lakefile.toml', 'lakefile.lean'].some((f) => {
    try {
      return lstatSync(path.join(root, f)).isFile();
    } catch {
      return false;
    }
  });
  if (!hasLakefile) return 'the model folder has no lakefile.toml or lakefile.lean';
  let text: string;
  try {
    text = readFileSync(path.join(root, 'lake-manifest.json'), 'utf8');
  } catch (e) {
    if ((e as NodeJS.ErrnoException).code === 'ENOENT') {
      return 'lake-manifest.json is missing (the sandbox keeps the model folder read-only, so Lake cannot write one)';
    }
    return `lake-manifest.json cannot be read: ${(e as Error).message}`;
  }
  let manifest: unknown;
  try {
    manifest = JSON.parse(text);
  } catch (e) {
    return `lake-manifest.json is not valid JSON: ${(e as Error).message}`;
  }
  const packages = typeof manifest === 'object' && manifest !== null ? (manifest as { packages?: unknown }).packages : undefined;
  if (!Array.isArray(packages)) return 'lake-manifest.json has no "packages" list';
  if (packages.length > 0) {
    const names = packages.map((p: unknown) => {
      const name = typeof p === 'object' && p !== null ? (p as { name?: unknown }).name : undefined;
      return typeof name === 'string' ? name : '?';
    });
    return `this project has Lake dependencies (${names.join(', ')}): M1 checks only dependency-free models; Mathlib needs an explicit opt-in (M4)`;
  }
  return undefined;
}

export interface ModuleFile {
  /** e.g. `Model.Spyro.Main`. */
  readonly name: string;
  /** POSIX, relative to the root, e.g. `Model/Spyro/Main.lean`. */
  readonly file: string;
}

/**
 * The library's modules: `<library>.lean` and every `<library>/**.lean` (regular files only; symlinks, dot
 * directories and paths that are not plain module names are skipped). Sorted by file.
 */
export function listModuleFiles(root: string, library: string): ModuleFile[] {
  const out: ModuleFile[] = [];
  const consider = (rel: string): void => {
    const name = rel.slice(0, -'.lean'.length).split('/').join('.');
    if (isValidModuleName(name)) out.push({ name, file: rel });
  };
  try {
    if (lstatSync(path.join(root, `${library}.lean`)).isFile()) consider(`${library}.lean`);
  } catch {
    // no root module
  }
  const stack = [library];
  while (stack.length > 0) {
    const rel = stack.pop() ?? '';
    let entries: Dirent[];
    try {
      entries = readdirSync(path.join(root, rel), { withFileTypes: true });
    } catch {
      continue;
    }
    for (const entry of entries) {
      const childRel = `${rel}/${entry.name}`;
      if (entry.isDirectory()) {
        if (!entry.name.startsWith('.')) stack.push(childRel);
      } else if (entry.isFile() && entry.name.endsWith('.lean')) {
        consider(childRel);
      }
    }
  }
  return out.sort((a, b) => (a.file < b.file ? -1 : a.file > b.file ? 1 : 0));
}

export interface ModuleSource extends ModuleFile {
  /** The source text the build sees (UTF-8). */
  readonly text: string;
  readonly sha256: string;
  /** Every module named by the header's `import` commands. */
  readonly headerImports: readonly string[];
  /** The project-internal ones: the library itself or modules under it (as `ModuleFacts.imports`). */
  readonly imports: readonly string[];
}

/** Whether a module name belongs to the library (`Model` or `Model.…`). */
export function inLibrary(name: string, library: string): boolean {
  return name === library || name.startsWith(`${library}.`);
}

/** Reads, hashes and parses the header of every module; unreadable files are skipped. Topologically sorted. */
export function readModuleSources(root: string, library: string): ModuleSource[] {
  const sources: ModuleSource[] = [];
  for (const m of listModuleFiles(root, library)) {
    let text: string;
    try {
      text = readFileSync(path.join(root, m.file), 'utf8');
    } catch {
      continue; // vanished or unreadable: Lake will report it if it matters
    }
    const headerImports = parseImports(text);
    sources.push({ ...m, text, sha256: sha256Text(text), headerImports, imports: headerImports.filter((i) => inLibrary(i, library)) });
  }
  return topologicalOrder(sources);
}

/** Dependencies before dependents, ties by name; modules on an import cycle keep name order at the end. */
export function topologicalOrder<T extends { readonly name: string; readonly imports: readonly string[] }>(modules: readonly T[]): T[] {
  const byName = new Map(modules.map((m) => [m.name, m]));
  const pending = new Map(modules.map((m) => [m.name, new Set(m.imports.filter((i) => byName.has(i) && i !== m.name))]));
  const order: T[] = [];
  const ready = (): string[] => [...pending].filter(([, deps]) => deps.size === 0).map(([n]) => n).sort();
  for (let batch = ready(); batch.length > 0; batch = ready()) {
    const next = batch[0] ?? '';
    pending.delete(next);
    for (const deps of pending.values()) deps.delete(next);
    const m = byName.get(next);
    if (m !== undefined) order.push(m);
  }
  for (const name of [...pending.keys()].sort()) {
    const m = byName.get(name);
    if (m !== undefined) order.push(m);
  }
  return order;
}

export interface ModuleStateInput {
  readonly modules: readonly { readonly name: string; readonly headerImports: readonly string[] }[];
  readonly library: string;
  /** Targets Lake listed under "Some required targets logged failures:" (any caption). */
  readonly failedTargets: ReadonlySet<string>;
  /** `lake build` exited 0. */
  readonly buildOk: boolean;
  /** Modules with a successful progress line (`Built`, `Replayed`, …) in this build's log. */
  readonly reportedOk: ReadonlySet<string>;
}

/**
 * Module states after a build (plan section 4 step 5): `failed` = Lake said so; `not-built` = outside the import
 * closure of the library root `<library>`; `dependency-failed` = an import (transitively) failed, or names a
 * library module that does not exist; otherwise `fresh`. When the build failed without naming any project
 * module (e.g. a lakefile error), only modules this log reports as built count as fresh, the rest `not-built`:
 * their artifacts may predate the sources.
 */
export function computeModuleStates(input: ModuleStateInput): Map<string, ModuleState> {
  const byName = new Map(input.modules.map((m) => [m.name, m]));
  const closure = new Set<string>();
  const stack = byName.has(input.library) ? [input.library] : [];
  while (stack.length > 0) {
    const name = stack.pop() ?? '';
    if (closure.has(name)) continue;
    closure.add(name);
    for (const i of byName.get(name)?.headerImports ?? []) if (byName.has(i)) stack.push(i);
  }

  const memo = new Map<string, boolean>();
  const visiting = new Set<string>();
  const brokenImport = (name: string): boolean => {
    const known = memo.get(name);
    if (known !== undefined) return known;
    if (visiting.has(name)) return true; // an import cycle never builds
    visiting.add(name);
    let broken = false;
    for (const i of byName.get(name)?.headerImports ?? []) {
      const missing = !byName.has(i) && inLibrary(i, input.library);
      if (input.failedTargets.has(i) || missing || (byName.has(i) && brokenImport(i))) {
        broken = true;
        break;
      }
    }
    visiting.delete(name);
    memo.set(name, broken);
    return broken;
  };

  const anyProjectModuleFailed = input.modules.some((m) => input.failedTargets.has(m.name));
  const states = new Map<string, ModuleState>();
  for (const m of input.modules) {
    let state: ModuleState;
    if (input.failedTargets.has(m.name)) state = 'failed';
    else if (!closure.has(m.name)) state = 'not-built';
    else if (brokenImport(m.name)) state = 'dependency-failed';
    else if (!input.buildOk && !anyProjectModuleFailed) state = input.reportedOk.has(m.name) ? 'fresh' : 'not-built';
    else state = 'fresh';
    states.set(m.name, state);
  }
  return states;
}

/**
 * Parsing `lake build` output (Lake 5.0 / Lean 4.35; docs/m1-plan.md section 4 step 4, verified on real logs and
 * against `Lake/Build/Run.lean` and `Lake/Util/Log.lean` in the toolchain sources).
 *
 * Line shapes:
 * - progress: `<icon> [i/n] <verb> <caption>[ (<time>)]`, icon `✔` (ok), `⚠` (warnings), `ℹ` (infos), `✖`
 *   (failed), `⊘` (canceled); verbs `Built`/`Building`, `Replayed`/`Replaying`, `Ran`/`Running`, `Fetched`/…
 *   (the `-ing` form means the job failed). Lake replays the stored messages of up-to-date modules (`Replayed`),
 *   so warnings such as "declaration uses `sorry`" appear on every build;
 * - `trace: …`: the command line of a failed job (ignored, with any continuation);
 * - messages: `error|warning|info: <text>`, where a Lean message's text is `<file>:<line>:<col>: <first line>`
 *   (1-based line, 0-based code-point column; no end position); every following line up to the next recognised
 *   line is a continuation of the message (Lean's message text spans lines);
 * - `Some required targets logged failures:` followed by `- <caption>` lines (module names, or captions such as
 *   `job computation`); `error: build failed`; `Build completed successfully (n jobs).`
 */

export type LakeSeverity = 'error' | 'warning' | 'information';

export interface LakeProgress {
  readonly icon: string;
  readonly jobNo: number;
  readonly totalJobs: number;
  readonly verb: string;
  /** Usually a module name, e.g. `Model.Spyro.Main`; also captions such as `job computation`. */
  readonly caption: string;
  /** The job failed (icon `✖`). */
  readonly failed: boolean;
}

export interface LakeMessage {
  readonly severity: LakeSeverity;
  /** The file as Lake printed it (usually relative to the package root), when the message names one. */
  readonly file?: string;
  /** 1-based line, when the message has a position. */
  readonly line?: number;
  /** 0-based column in code points, when the message has a position. */
  readonly column?: number;
  /** The message without the `<severity>: <file>:<line>:<col>: ` prefix, continuation lines included. */
  readonly text: string;
}

export interface LakeLog {
  readonly progress: LakeProgress[];
  readonly messages: LakeMessage[];
  /** Captions listed under "Some required targets logged failures:". */
  readonly failedTargets: string[];
  /** `error: build failed` was printed. */
  readonly buildFailed: boolean;
  /** `Build completed successfully …`, `All targets up-to-date …` or `Nothing to build.` was printed. */
  readonly completed: boolean;
  /** Lines that matched nothing and continued no message (kept for error details). */
  readonly otherLines: string[];
}

const PROGRESS = /^([✔⚠✖ℹ⊘]) \[(\d+)\/(\d+)\](?: \(Optional\))? (\S+) (.+?)(?: \((?:\d+(?:\.\d+)?m?s)\))?$/u;
const MESSAGE = /^(error|warning|info): (.*)$/u;
const POSITIONED = /^(.+?):(\d+):(\d+): ([^]*)$/u;
const FILE_ONLY = /^(\S+\.lean): ([^]*)$/u;
const FAILURES_HEADER = 'Some required targets logged failures:';
const COMPLETED = /^(?:Build completed successfully \(\d+ jobs?\)\.|All targets up-to-date \(\d+ jobs?\)\.|Nothing to build\.)$/u;
// eslint-disable-next-line no-control-regex
const ANSI = /\x1B\[[0-9;?]*[A-Za-z]/gu;

const SEVERITY: Readonly<Record<string, LakeSeverity>> = { error: 'error', warning: 'warning', info: 'information' };

interface OpenMessage {
  severity: LakeSeverity;
  lines: string[];
}

function finishMessage(open: OpenMessage): LakeMessage {
  const lines = [...open.lines];
  while (lines.length > 1 && (lines.at(-1) ?? '').trim() === '') lines.pop();
  const body = lines.join('\n');
  const positioned = POSITIONED.exec(body);
  if (positioned !== null && !/\s/u.test(positioned[1] ?? '')) {
    return {
      severity: open.severity,
      file: positioned[1] ?? '',
      line: Number(positioned[2]),
      column: Number(positioned[3]),
      text: positioned[4] ?? '',
    };
  }
  const fileOnly = FILE_ONLY.exec(body);
  if (fileOnly !== null) return { severity: open.severity, file: fileOnly[1] ?? '', text: fileOnly[2] ?? '' };
  return { severity: open.severity, text: body };
}

/** Parses one output stream of `lake build` (parse stdout and stderr separately, then concatenate). */
export function parseLakeLog(output: string): LakeLog {
  const log = {
    progress: [] as LakeProgress[],
    messages: [] as LakeMessage[],
    failedTargets: [] as string[],
    buildFailed: false,
    completed: false,
    otherLines: [] as string[],
  };
  /** What unrecognised lines continue: a message, a trace entry (dropped), or nothing. */
  let open: OpenMessage | 'trace' | undefined;
  let inFailures = false;
  const close = (): void => {
    if (open !== undefined && open !== 'trace') log.messages.push(finishMessage(open));
    open = undefined;
  };

  for (const raw of output.replace(ANSI, '').split('\n')) {
    const line = raw.endsWith('\r') ? raw.slice(0, -1) : raw;
    if (inFailures) {
      if (line.startsWith('- ')) {
        log.failedTargets.push(line.slice(2).trim());
        continue;
      }
      inFailures = false;
    }
    const progress = PROGRESS.exec(line);
    if (progress !== null) {
      close();
      log.progress.push({
        icon: progress[1] ?? '',
        jobNo: Number(progress[2]),
        totalJobs: Number(progress[3]),
        verb: progress[4] ?? '',
        caption: progress[5] ?? '',
        failed: progress[1] === '✖',
      });
      continue;
    }
    if (line.startsWith('trace: ')) {
      close();
      open = 'trace';
      continue;
    }
    if (line === FAILURES_HEADER) {
      close();
      inFailures = true;
      continue;
    }
    if (line === 'error: build failed') {
      close();
      log.buildFailed = true;
      continue;
    }
    if (COMPLETED.test(line)) {
      close();
      log.completed = true;
      continue;
    }
    const message = MESSAGE.exec(line);
    if (message !== null) {
      close();
      open = { severity: SEVERITY[message[1] ?? ''] ?? 'error', lines: [message[2] ?? ''] };
      continue;
    }
    if (open === 'trace') continue;
    if (open !== undefined) {
      open.lines.push(line);
      continue;
    }
    if (line.trim() !== '') log.otherLines.push(line);
  }
  close();
  return log;
}

/** Concatenates the logs of stdout and stderr (each parsed on its own, so streams never mix inside a message). */
export function mergeLakeLogs(...logs: LakeLog[]): LakeLog {
  return {
    progress: logs.flatMap((l) => l.progress),
    messages: logs.flatMap((l) => l.messages),
    failedTargets: logs.flatMap((l) => l.failedTargets),
    buildFailed: logs.some((l) => l.buildFailed),
    completed: logs.some((l) => l.completed),
    otherLines: logs.flatMap((l) => l.otherLines),
  };
}

/** Captions of jobs that finished without failing (`Built`, `Replayed`, …). */
export function succeededCaptions(log: LakeLog): Set<string> {
  return new Set(log.progress.filter((p) => !p.failed && p.icon !== '⊘').map((p) => p.caption));
}

/**
 * Reading Lean's `.ilean` index (version 5 on Lean 4.35; docs/m1-plan.md section 4 step 6). Verified shape:
 *
 *   { "version": 5, "module": "Model.Spyro.Main", "directImports": [...],
 *     "decls": { "Spyro.cynder_dark_past": [23, 0, 24, 52, 24, 7, 24, 23], ... },
 *     "references": { "{\"c\":{\"m\":\"Model.Spyro.Vocabulary\",\"n\":\"Spyro.HasDarkPast\"}}":
 *                       { "definition": null, "usages": [[24, 34, 24, 45, "Spyro.cynder_dark_past"]] }, ... } }
 *
 * - `decls[name]` = the full range (from the docstring) then the selection range (the name), 0-based LSP
 *   positions with UTF-16 characters. JSON object order is alphabetical, not source order.
 * - `references` are keyed by a JSON-encoded `RefIdent` (`{"c":{"m":module,"n":name}}` for constants; other
 *   kinds are ignored). `definition` is null for constants of other modules, else `[l, c, l, c]` or
 *   `[l, c, l, c, parent]`; each usage is `[l, c, l, c, parent]`, `parent` being the declaration that contains it.
 * - Auxiliary names have no `decls` entry but a `definition` whose parent is another declaration: a structure's
 *   field `Spyro.Rec.past` has `definition: [101, 2, 101, 6, "Spyro.Rec"]`.
 * - Names starting with `_private.` (private declarations) are skipped.
 */
import type { Range } from '@telelean/core';

export const SUPPORTED_ILEAN_VERSION = 5;

export interface IleanDecl {
  readonly name: string;
  readonly range: Range;
  readonly selectionRange: Range;
  /** For auxiliary names (no `decls` entry): the declaration `.ilean` attributes the definition to. */
  readonly parent?: string;
  /** No `decls` entry: only the name's range is known (`range` = `selectionRange`). */
  readonly auxiliary: boolean;
}

export interface IleanUsage {
  /** The referenced constant. */
  readonly name: string;
  /** Module that defines it. */
  readonly module: string;
  readonly range: Range;
  /** The declaration containing the occurrence. */
  readonly parent: string;
}

export interface IleanData {
  readonly module: string;
  /** Source order (by full range start, then name), auxiliary names included. */
  readonly decls: IleanDecl[];
  /** Usages whose parent is one of `decls`, in source order. */
  readonly usages: IleanUsage[];
}

export type IleanResult = { readonly ok: true; readonly data: IleanData } | { readonly ok: false; readonly error: string };

const isPrivate = (name: string): boolean => name.startsWith('_private.');

function isNat(v: unknown): v is number {
  return typeof v === 'number' && Number.isInteger(v) && v >= 0;
}

function rangeOf(a: readonly unknown[], at: number): Range | undefined {
  const [l1, c1, l2, c2] = [a[at], a[at + 1], a[at + 2], a[at + 3]];
  if (!isNat(l1) || !isNat(c1) || !isNat(l2) || !isNat(c2)) return undefined;
  return { start: { line: l1, character: c1 }, end: { line: l2, character: c2 } };
}

export function comparePositions(a: Range['start'], b: Range['start']): number {
  return a.line - b.line || a.character - b.character;
}

/** Parses the JSON text of one `.ilean` file for module `expectedModule`. Never throws. */
export function parseIlean(text: string, expectedModule: string): IleanResult {
  let json: unknown;
  try {
    json = JSON.parse(text);
  } catch (e) {
    return { ok: false, error: `not valid JSON: ${(e as Error).message}` };
  }
  if (typeof json !== 'object' || json === null) return { ok: false, error: 'not a JSON object' };
  const root = json as { version?: unknown; module?: unknown; decls?: unknown; references?: unknown };
  if (root.version !== SUPPORTED_ILEAN_VERSION) {
    return { ok: false, error: `unsupported .ilean version ${JSON.stringify(root.version)} (expected ${SUPPORTED_ILEAN_VERSION})` };
  }
  if (root.module !== expectedModule) {
    return { ok: false, error: `.ilean is for module ${JSON.stringify(root.module)}, expected ${expectedModule}` };
  }
  if (typeof root.decls !== 'object' || root.decls === null || typeof root.references !== 'object' || root.references === null) {
    return { ok: false, error: '.ilean lacks "decls" or "references"' };
  }

  const decls = new Map<string, IleanDecl>();
  for (const [name, value] of Object.entries(root.decls as Record<string, unknown>)) {
    if (isPrivate(name) || !Array.isArray(value)) continue;
    const range = rangeOf(value, 0);
    const selectionRange = rangeOf(value, 4);
    if (range === undefined || selectionRange === undefined) continue;
    decls.set(name, { name, range, selectionRange, auxiliary: false });
  }

  const parents = new Map<string, string>();
  const auxiliary: IleanDecl[] = [];
  const usages: IleanUsage[] = [];
  const pendingUsages: Array<{ name: string; module: string; usage: readonly unknown[] }> = [];
  for (const [key, value] of Object.entries(root.references as Record<string, unknown>)) {
    let ident: unknown;
    try {
      ident = JSON.parse(key);
    } catch {
      continue;
    }
    const c = typeof ident === 'object' && ident !== null ? (ident as { c?: unknown }).c : undefined;
    if (typeof c !== 'object' || c === null) continue; // not a constant (e.g. a local variable)
    const { m, n } = c as { m?: unknown; n?: unknown };
    if (typeof m !== 'string' || typeof n !== 'string' || typeof value !== 'object' || value === null) continue;
    const info = value as { definition?: unknown; usages?: unknown };

    if (m === expectedModule && !isPrivate(n) && Array.isArray(info.definition) && info.definition.length >= 5) {
      const parent = info.definition[4];
      if (typeof parent === 'string' && parent !== n && !isPrivate(parent)) {
        if (decls.has(n)) parents.set(n, parent);
        else {
          const sel = rangeOf(info.definition, 0);
          if (sel !== undefined) auxiliary.push({ name: n, range: sel, selectionRange: sel, parent, auxiliary: true });
        }
      }
    }
    if (Array.isArray(info.usages)) {
      for (const usage of info.usages) if (Array.isArray(usage)) pendingUsages.push({ name: n, module: m, usage });
    }
  }

  for (const aux of auxiliary) {
    // Keep auxiliary names only when their parent is a declaration we report.
    if (decls.has(aux.parent ?? '') && !decls.has(aux.name)) decls.set(aux.name, aux);
  }
  for (const [name, parent] of parents) {
    const d = decls.get(name);
    if (d !== undefined && decls.has(parent)) decls.set(name, { ...d, parent });
  }
  for (const { name, module, usage } of pendingUsages) {
    const range = rangeOf(usage, 0);
    const parent = usage[4];
    if (range === undefined || typeof parent !== 'string' || !decls.has(parent)) continue;
    usages.push({ name, module, range, parent });
  }

  const sortedDecls = [...decls.values()].sort((a, b) => comparePositions(a.range.start, b.range.start) || (a.name < b.name ? -1 : a.name > b.name ? 1 : 0));
  usages.sort((a, b) => comparePositions(a.range.start, b.range.start) || comparePositions(a.range.end, b.range.end) || (a.name < b.name ? -1 : 1));
  return { ok: true, data: { module: expectedModule, decls: sortedDecls, usages } };
}

