/**
 * WP-semantic public functions (docs/m1-plan.md sections 4 and 9). The signatures and documented behaviour are
 * FROZEN. The internal helpers (Lake log parser, `.ilean` reader, check-file generator, text and project helpers)
 * are exported too, for tests and for the integrator.
 */
import { readFileSync } from 'node:fs';

import type { LeanFacts } from '@telelean/core';

import { refresh } from './refresh.js';
import type { RefreshRequest } from './types.js';

export * from './types.js';
export * from './text.js';
export * from './project.js';
export * from './lakeLog.js';
export * from './ilean.js';
export * from './checkFile.js';
export { buildRunOptions, declDrafts, gitMaskPaths, messageFacts, rootRelativeFile, toDeclFacts } from './refresh.js';

/**
 * Builds the project in place under runLean and checks it (see ./types.ts for the six steps). Never throws for
 * Lean or sandbox failures: they become `status` values with a `detail`. Throws TypeError for invalid arguments.
 * Does not serialise itself: callers wrap it in `runExclusive`.
 */
export async function refreshLeanFacts(request: RefreshRequest): Promise<LeanFacts> {
  return refresh(request, readMemAvailableBytes);
}

/** MemAvailable from /proc/meminfo in bytes, or undefined when it cannot be read. */
export function readMemAvailableBytes(): number | undefined {
  try {
    const match = /^MemAvailable:\s+(\d+)\s+kB$/m.exec(readFileSync('/proc/meminfo', 'utf8'));
    return match ? Number(match[1]) * 1024 : undefined;
  } catch {
    return undefined;
  }
}

let tail: Promise<unknown> = Promise.resolve();

/**
 * Runs Lean jobs one at a time in this process (03 principle 5: one Lean job at a time; M2's shadow builds will
 * queue here too). A job's failure does not block the queue.
 */
export function runExclusive<T>(job: () => Promise<T>): Promise<T> {
  const run = tail.then(job, job);
  tail = run.catch(() => undefined);
  return run;
}

/** Shared helpers for the semantic-layer tests (WP3). */
import { chmodSync, copyFileSync, existsSync, mkdirSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';

import { defaultHostTools, execCapture, type HostTools } from '../../src/lean/systemd.js';
import { REPO_ROOT, SPYRO } from '../lean/helpers.js';

export { cleanupTempRoot, knownProjectsLines, makeTempRoot, MiB, REPO_ROOT, SPYRO } from '../lean/helpers.js';

export const SEMANTIC_FIXTURES = path.join(REPO_ROOT, 'test-fixtures', 'semantic');
export const RECORDED = path.join(SEMANTIC_FIXTURES, 'recorded');

/** One run id per test process for the semantic tests, so leftover checks only ever see our own scopes. */
export const SEMANTIC_RUN_ID = `sem${process.pid}`;

/** A recorded fixture file as text. */
export function recorded(name: string): string {
  return readFileSync(path.join(RECORDED, name), 'utf8');
}

/** An overlay file's text, e.g. `overlayText('extras', 'Model/Spyro/Main.lean')`. */
export function overlayText(overlay: string, rel: string): string {
  return readFileSync(path.join(SEMANTIC_FIXTURES, 'overlays', overlay, rel), 'utf8');
}

function copyTree(src: string, dst: string): void {
  mkdirSync(dst, { recursive: true });
  for (const entry of readdirSync(src, { withFileTypes: true })) {
    const s = path.join(src, entry.name);
    const d = path.join(dst, entry.name);
    if (entry.isDirectory()) copyTree(s, d);
    else if (entry.isFile()) copyFileSync(s, d);
    else throw new Error(`unexpected non-regular fixture entry ${s}`);
  }
}

/**
 * A scratch copy of the Spyro fixture at `<tmp>/<name>`, with `test-fixtures/semantic/overlays/<overlay>/` copied
 * over it. Builds only ever happen in such copies.
 */
export function spyroCopy(tmp: string, name: string, overlay?: string): string {
  const dir = path.join(tmp, name);
  if (existsSync(dir)) throw new Error(`${dir} already exists`);
  copyTree(SPYRO, dir);
  if (overlay !== undefined) copyTree(path.join(SEMANTIC_FIXTURES, 'overlays', overlay), dir);
  return dir;
}

/** Loaded `telelean-<runId>-*` scope units (any state), from the systemd user manager. */
export async function unitsOfRun(runId: string): Promise<string[]> {
  const tools = defaultHostTools();
  const r = await execCapture(tools.systemctl, ['--user', 'list-units', '--all', '--no-legend', '--plain', `telelean-${runId}-*`], tools.env);
  return r.stdout
    .split('\n')
    .map((l) => l.trim())
    .filter((l) => l !== '');
}

export interface RecordingHost {
  /** HostTools overrides pointing at the recording fakes. */
  readonly host: Partial<HostTools>;
  /** Every recorded invocation: [tool, ...argv]. */
  calls(): string[][];
}

/**
 * Fake host tools that record each invocation (argv NUL-separated, one file per call) instead of doing anything.
 * `systemctl --user is-system-running` answers `running`, so runLean's preflight passes; `systemd-run` exits 1,
 * so a run that gets that far ends as `could-not-start` without any process of ours running Lean.
 */
export function recordingHost(dir: string): RecordingHost {
  mkdirSync(dir, { recursive: true });
  const logDir = path.join(dir, 'calls');
  mkdirSync(logDir, { recursive: true });
  const make = (tool: string, body: string): string => {
    const file = path.join(dir, tool);
    const record = `n=0; while [ -e '${logDir}/${tool}.'$n ]; do n=$((n+1)); done; printf '%s\\0' '${tool}' "$@" > '${logDir}/${tool}.'$n`;
    writeFileSync(file, `#!/bin/sh\n${record}\n${body}\n`);
    chmodSync(file, 0o755);
    return file;
  };
  const host: Partial<HostTools> = {
    systemdRun: make('systemd-run', 'echo "fake systemd-run: not starting anything" >&2; exit 1'),
    systemctl: make('systemctl', 'case "$2" in is-system-running) echo running ;; esac; exit 0'),
    bwrap: make('bwrap', 'exit 1'),
    setpriv: make('setpriv', 'exit 1'),
  };
  return {
    host,
    calls: () =>
      readdirSync(logDir)
        .sort()
        .map((f) => readFileSync(path.join(logDir, f), 'utf8').split('\0').slice(0, -1)),
  };
}

/** Text helpers: positions (code points vs UTF-16), docstrings, declaration keywords, import headers. */
import { describe, expect, it } from 'vitest';

import {
  codePointsToUtf16,
  declKeywordAt,
  docstringAt,
  docstringBefore,
  leanToLspPosition,
  lineStarts,
  lineText,
  normalizeWhitespace,
  offsetOf,
  parseImports,
  positionAt,
} from '../../src/semantic/index.js';
import { overlayText } from './helpers.js';

describe('positions', () => {
  it('converts a Lean column after a non-BMP character to UTF-16 (AT3.9, unit)', () => {
    const line = 'def nonBmp : String := "𝔸" ++ undefinedThing';
    // Lean reported 56:30 for `undefinedThing` (recorded/lake-nonbmp-error.stdout.txt): 30 code points.
    expect(line.indexOf('undefinedThing')).toBe(31); // UTF-16 index: 𝔸 is two code units
    expect(codePointsToUtf16(line, 30)).toBe(31);
    expect(codePointsToUtf16(line, 24)).toBe(24); // before the 𝔸: no difference
    expect(codePointsToUtf16(line, 25)).toBe(26); // just after it
    expect(codePointsToUtf16('ab', 5)).toBe(5); // past the end: one unit per column

    const text = overlayText('nonbmp-error', 'Model/Spyro/Main.lean');
    expect(leanToLspPosition(56, 30, text)).toEqual({ line: 55, character: 31 });
    expect(leanToLspPosition(56, 30)).toEqual({ line: 55, character: 30 }); // no text: column kept
    expect(leanToLspPosition(1, 0, text)).toEqual({ line: 0, character: 0 });
  });

  it('indexes lines, offsets and positions', () => {
    const text = 'ab\r\n𝔸c\n\nlast';
    const starts = lineStarts(text);
    expect(starts).toEqual([0, 4, 8, 9]);
    expect(lineText(text, starts, 0)).toBe('ab\r');
    expect(lineText(text, starts, 1)).toBe('𝔸c');
    expect(lineText(text, starts, 3)).toBe('last');
    expect(lineText(text, starts, 4)).toBeUndefined();
    expect(offsetOf(text, starts, { line: 1, character: 2 })).toBe(6);
    expect(offsetOf(text, starts, { line: 1, character: 99 })).toBe(7); // clamped to the line end
    expect(offsetOf(text, starts, { line: 9, character: 0 })).toBeUndefined();
    expect(positionAt(starts, 6)).toEqual({ line: 1, character: 2 });
    expect(positionAt(starts, 0)).toEqual({ line: 0, character: 0 });
    expect(positionAt(starts, 9)).toEqual({ line: 3, character: 0 });
  });

  it('normalises whitespace runs (wrapped #check output)', () => {
    expect(normalizeWhitespace('Spyro.a →\n  Spyro.b → Spyro.d3 ')).toBe('Spyro.a → Spyro.b → Spyro.d3');
  });
});

describe('docstrings and declaration keywords', () => {
  it('reads the docstring at a declaration start, honouring nested comments', () => {
    const text = '/-- Cynder /- nested -/ is a character -/\nabbrev x : Prop := True';
    expect(docstringAt(text, 0)).toBe('Cynder /- nested -/ is a character');
    expect(docstringAt('/- plain comment -/ def x', 0)).toBeUndefined();
    expect(docstringAt('abbrev x : Prop := True', 0)).toBeUndefined();
    expect(docstringAt('/-- unterminated', 0)).toBeUndefined();
  });

  it('finds the docstring right before a structure field', () => {
    const text = 'structure Rec where\n  /-- the past -/\n  past : Prop\n';
    const at = text.indexOf('past :');
    expect(docstringBefore(text, at)).toEqual({ start: text.indexOf('/--'), text: 'the past' });
    expect(docstringBefore('structure Rec where\n  past : Prop', 22)).toBeUndefined();
    const nested = 'x\n/-- a /-- inner -/ b -/\n  f : T';
    expect(docstringBefore(nested, nested.indexOf('f :'))).toEqual({ start: 2, text: 'a /-- inner -/ b' });
  });

  it('finds the keyword after docstring, attributes and modifiers (the instance rule)', () => {
    expect(declKeywordAt('instance : Nonempty Character := Character.exists', 0)).toBe('instance');
    expect(declKeywordAt('/-- A data instance -/\ninstance instInhabitedRec : Inhabited Rec := ⟨⟨True⟩⟩', 0)).toBe('instance');
    expect(declKeywordAt('@[simp, instance 100] noncomputable scoped instance foo : T := x', 0)).toBe('instance');
    expect(declKeywordAt('@[instance] def foo : T := x', 0)).toBe('def');
    expect(declKeywordAt('/-- doc -/ -- comment\nprivate theorem t : True := trivial', 0)).toBe('theorem');
    expect(declKeywordAt('instance_like_name', 0)).toBe('instance_like_name');
    expect(declKeywordAt('noncomputable opaque cynder : Character', 0)).toBe('opaque');
    expect(declKeywordAt('   ', 0)).toBeUndefined();
  });
});

describe('import headers', () => {
  it('reads the imports of a module header', () => {
    expect(parseImports('import Model.Spyro.Vocabulary\n\nnamespace Spyro\nimport Not.This\n')).toEqual(['Model.Spyro.Vocabulary']);
    expect(parseImports('/-! module doc -/\n-- comment\nimport A.B -- trailing\nimport C\n\ndef x := 1')).toEqual(['A.B', 'C']);
    expect(parseImports('module\n\npublic import A\nmeta import B\nimport all C\nprelude')).toEqual(['A', 'B', 'C']);
    expect(parseImports('namespace X\nend X\n')).toEqual([]);
    expect(parseImports('')).toEqual([]);
  });
});

/** The Lake log parser on recorded Lake 5.0 / Lean 4.35 logs (AT3.12), and what the refresh derives from it. */
import { describe, expect, it } from 'vitest';

import {
  computeModuleStates,
  lineStarts,
  mergeLakeLogs,
  messageFacts,
  parseLakeLog,
  rootRelativeFile,
  succeededCaptions,
  type ModuleSource,
} from '../../src/semantic/index.js';
import { overlayText, recorded } from './helpers.js';

const SPYRO_MODULES = [
  { name: 'Model.Spyro.Vocabulary', headerImports: [] },
  { name: 'Model.Spyro.Main', headerImports: ['Model.Spyro.Vocabulary'] },
  { name: 'Model', headerImports: ['Model.Spyro.Main'] },
];

function parseRecorded(base: string, streams: Array<'stdout' | 'stderr'>): ReturnType<typeof parseLakeLog> {
  return mergeLakeLogs(...streams.map((s) => parseLakeLog(recorded(`${base}.${s}.txt`))));
}

describe('parseLakeLog (recorded logs)', () => {
  it('reads a failed build: progress, trace ignored, a multi-line error, the failures list', () => {
    const log = parseRecorded('lake-build-error', ['stdout', 'stderr']);
    expect(log.progress.map((p) => [p.icon, p.verb, p.caption, p.failed, p.jobNo, p.totalJobs])).toEqual([
      ['✔', 'Built', 'Model.Spyro.Vocabulary', false, 2, 5],
      ['✖', 'Building', 'Model.Spyro.Main', true, 3, 5],
    ]);
    expect(log.messages).toEqual([
      {
        severity: 'error',
        file: 'Model/Spyro/Main.lean',
        line: 58,
        column: 51,
        text: 'Type mismatch\n  cynder_dark_past.holds\nhas type\n  cynder_dark_past\nbut is expected to have type\n  cynder_not_good',
      },
    ]);
    expect(log.failedTargets).toEqual(['Model.Spyro.Main']);
    expect(log.buildFailed).toBe(true);
    expect(log.completed).toBe(false);
    expect(log.otherLines).toEqual([]);
    expect([...succeededCaptions(log)]).toEqual(['Model.Spyro.Vocabulary']);
  });

  it('reads a successful build with a warning, first built and then replayed', () => {
    const built = parseLakeLog(recorded('lake-extras-built.stdout.txt'));
    expect(built.progress.map((p) => `${p.icon} ${p.verb} ${p.caption}`)).toEqual([
      '✔ Built Model.Spyro.Vocabulary',
      '⚠ Built Model.Spyro.Main',
      '✔ Built Model',
    ]);
    const replayed = parseLakeLog(recorded('lake-extras-replayed.stdout.txt'));
    expect(replayed.progress.map((p) => `${p.icon} ${p.verb} ${p.caption}`)).toEqual(['⚠ Replayed Model.Spyro.Main']);
    for (const log of [built, replayed]) {
      expect(log.messages).toEqual([{ severity: 'warning', file: 'Model/Spyro/Main.lean', line: 87, column: 8, text: 'declaration uses `sorry`' }]);
      expect(log.completed).toBe(true);
      expect(log.buildFailed).toBe(false);
      expect(log.failedTargets).toEqual([]);
    }
  });

  it('reads bad imports: job captions, file-only messages, continuation lines, four failures', () => {
    const log = parseRecorded('lake-missing-import', ['stdout', 'stderr']);
    expect(log.failedTargets).toEqual(['job computation', 'Model.Spyro.Missing', 'Model.Spyro.Main', 'Model']);
    expect(log.messages).toEqual([
      { severity: 'error', text: 'Model: some modules have bad imports or could not be read' },
      { severity: 'error', text: 'no such file or directory (error code: 2)\n  file: /work/model/Model/Spyro/Missing.lean' },
      { severity: 'error', file: 'Model/Spyro/Main.lean', text: "bad import 'Model.Spyro.Missing'" },
      { severity: 'error', file: 'Model.lean', text: "bad import 'Model.Spyro.Main'" },
    ]);
    expect(log.progress.filter((p) => p.failed).map((p) => p.caption)).toEqual(['job computation', 'Model.Spyro.Missing', 'Model.Spyro.Main', 'Model']);
    expect(log.buildFailed).toBe(true);
  });

  it('reads a lakefile error (stderr only)', () => {
    const log = parseRecorded('lake-lakefile-error', ['stderr']);
    expect(log.messages).toEqual([{ severity: 'error', file: 'lakefile.toml', line: 3, column: 0, text: "error: unexpected end of input; expected ']'" }]);
    expect(log.progress).toEqual([]);
    expect(log.failedTargets).toEqual([]);
  });

  it('strips ANSI colours and carriage returns, and keeps unknown lines aside', () => {
    const log = parseLakeLog(
      '\x1B[2K\r\x1B[32m✔ [1/2] Built A.B (1.2s)\x1B[0m\r\nsomething else\r\n\x1B[33mwarning:\x1B[0m A/B.lean:1:2: careful\r\n  more\r\nℹ [2/2] (Optional) Replayed A (12s)\n',
    );
    expect(log.progress.map((p) => `${p.icon} ${p.verb} ${p.caption}`)).toEqual(['✔ Built A.B', 'ℹ Replayed A']);
    expect(log.messages).toEqual([{ severity: 'warning', file: 'A/B.lean', line: 1, column: 2, text: 'careful\n  more' }]);
    expect(log.otherLines).toEqual(['something else']);
  });
});

describe('from the log to facts', () => {
  const sources = (overlay: string): Map<string, ModuleSource & { starts: number[] }> => {
    const text = overlayText(overlay, 'Model/Spyro/Main.lean');
    const main = { name: 'Model.Spyro.Main', file: 'Model/Spyro/Main.lean', text, sha256: '', headerImports: [], imports: [], starts: lineStarts(text) };
    return new Map([[main.file, main]]);
  };

  it('converts message positions to zero-width LSP ranges with modules (UTF-16 after a non-BMP character)', () => {
    const log = parseRecorded('lake-nonbmp-error', ['stdout', 'stderr']);
    const facts = messageFacts(log.messages, '/work/model', sources('nonbmp-error'));
    expect(facts).toEqual([
      {
        severity: 'error',
        file: 'Model/Spyro/Main.lean',
        module: 'Model.Spyro.Main',
        range: { start: { line: 55, character: 31 }, end: { line: 55, character: 31 } },
        text: 'Unknown identifier `undefinedThing`',
      },
    ]);
    const lakefile = messageFacts(parseLakeLog(recorded('lake-lakefile-error.stderr.txt')).messages, '/work/model', new Map());
    expect(lakefile).toEqual([
      { severity: 'error', file: 'lakefile.toml', range: { start: { line: 2, character: 0 }, end: { line: 2, character: 0 } }, text: "error: unexpected end of input; expected ']'" },
    ]);
  });

  it('makes printed paths root-relative', () => {
    expect(rootRelativeFile('Model/Spyro/Main.lean', '/work/model')).toBe('Model/Spyro/Main.lean');
    expect(rootRelativeFile('./././Model/Spyro/Main.lean', '/work/model')).toBe('Model/Spyro/Main.lean');
    expect(rootRelativeFile('/work/model/Model.lean', '/work/model')).toBe('Model.lean');
    expect(rootRelativeFile('/elsewhere/Init.lean', '/work/model')).toBeUndefined();
    expect(rootRelativeFile('../x.lean', '/work/model')).toBeUndefined();
  });

  it('derives module states from the recorded logs', () => {
    const states = (base: string, buildOk: boolean, streams: Array<'stdout' | 'stderr'>): Record<string, string> => {
      const log = parseRecorded(base, streams);
      return Object.fromEntries(
        computeModuleStates({ modules: SPYRO_MODULES, library: 'Model', failedTargets: new Set(log.failedTargets), buildOk, reportedOk: succeededCaptions(log) }),
      );
    };
    expect(states('lake-build-error', false, ['stdout', 'stderr'])).toEqual({ 'Model.Spyro.Vocabulary': 'fresh', 'Model.Spyro.Main': 'failed', Model: 'dependency-failed' });
    expect(states('lake-extras-replayed', true, ['stdout'])).toEqual({ 'Model.Spyro.Vocabulary': 'fresh', 'Model.Spyro.Main': 'fresh', Model: 'fresh' });
    expect(states('lake-missing-import', false, ['stdout', 'stderr'])).toEqual({ 'Model.Spyro.Vocabulary': 'fresh', 'Model.Spyro.Main': 'failed', Model: 'failed' });
    // Nothing named and nothing built: no module can be trusted to be fresh.
    expect(states('lake-lakefile-error', false, ['stderr'])).toEqual({ 'Model.Spyro.Vocabulary': 'not-built', 'Model.Spyro.Main': 'not-built', Model: 'not-built' });
  });

  it('computes not-built, missing imports and cycles', () => {
    const run = (modules: Array<{ name: string; headerImports: string[] }>, failed: string[] = []): Record<string, string> =>
      Object.fromEntries(computeModuleStates({ modules, library: 'Model', failedTargets: new Set(failed), buildOk: failed.length === 0, reportedOk: new Set() }));
    expect(
      run([
        { name: 'Model', headerImports: ['Model.A', 'Model.Cyc1'] },
        { name: 'Model.A', headerImports: ['Model.Missing'] },
        { name: 'Model.B', headerImports: [] },
        { name: 'Model.Cyc1', headerImports: ['Model.Cyc2'] },
        { name: 'Model.Cyc2', headerImports: ['Model.Cyc1', 'Init'] },
      ]),
    ).toEqual({ Model: 'dependency-failed', 'Model.A': 'dependency-failed', 'Model.B': 'not-built', 'Model.Cyc1': 'dependency-failed', 'Model.Cyc2': 'dependency-failed' });
    expect(run([{ name: 'Model.A', headerImports: [] }])).toEqual({ 'Model.A': 'not-built' }); // no root module
  });
});

