/**
 * The runner functions the extension calls (WP-workspace), gathered in one replaceable record: the in-VS-Code smoke
 * test swaps in a fake ModelWorkspace (extension mode Test only), so the panels, serializer, EditApplier, clipboard,
 * editor and diff paths are exercised before the real workspace exists.
 *
 * Only the runner's `workspace` subpath is imported (never the package root): `llm/` must stay out of the bundle.
 */
import {
  createModelWorkspace,
  findModelRoots,
  inspectFolder,
  planInitialize,
} from '@telelean/runner/workspace/index.js';

export interface RunnerFunctions {
  createModelWorkspace: typeof createModelWorkspace;
  findModelRoots: typeof findModelRoots;
  inspectFolder: typeof inspectFolder;
  planInitialize: typeof planInitialize;
}

export const DEFAULT_RUNNER: RunnerFunctions = { createModelWorkspace, findModelRoots, inspectFolder, planInitialize };
/**
 * telelean's VS Code extension (the thin host of docs/m1-plan.md section 2): commands, one board per model root,
 * the model workspaces behind them (runner), and the board serializer. Activation is cheap: nothing reads model
 * files or runs Lean until a board opens (D-28).
