/**
 * AT5.5: the smoke flow on the copied sample model with the REAL runner workspace (WP4), core model (WP1, WP2) and
 * Lean refresh (WP3). Until those are integrated their functions are stubs, and this suite marks itself pending.
 *
 *   4 cards -> refresh: semantic fresh, 9 vocabulary items -> addNode writes a block to Model/Spyro/Inbox.lean, undo
 *   removes it -> G->A on cynder-not-good adds the axiom, the refresh shows it assumed -> copyText -> initGit,
 *   historyList, historyPreview (diff editor), historyRevert (and its undo) -> openInEditor Main.lean ->
 *   .telelean/graph.json exists. Git runs only in the scratch copy (refs/telelean/* only, no branch commits).
 */
import * as assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { existsSync, mkdirSync, readFileSync } from 'node:fs';
import * as path from 'node:path';
import * as vscode from 'vscode';

import { buildProjectModel, isImplemented, NotImplementedError, parseLeanFile, planAction, toGraphJson, type TlGraph } from '@telelean/core';
import { refreshLeanFacts } from '@telelean/runner/semantic/index.js';
import { createModelWorkspace, findModelRoots, inspectFolder, planInitialize } from '@telelean/runner/workspace/index.js';

import type { OpenBoardResult, TeleleanApi } from '../../src/api';
import type { InitializeResult } from '../../src/logic/initialize';
import { closeAllEditors, closeTextEditors, getApi, isRendered, message, nextBoardMessage, nextPost, waitFor, workspacePaths } from './helpers';

const LEAN_TIMEOUT_MS = 240_000;

async function asyncImplemented(probe: () => Promise<unknown>): Promise<boolean> {
  try {
    await probe();
    return true;
  } catch (error) {
    return !(error instanceof NotImplementedError);
  }
}

/** Which pieces this suite needs are still stubs (each probe uses invalid input, so nothing real runs). */
async function missingImplementations(): Promise<string[]> {
  const missing: string[] = [];
  if (!isImplemented(() => parseLeanFile('X.lean', ''))) missing.push('WP1 parseLeanFile');
  if (!isImplemented(() => buildProjectModel({ files: [], fileHashes: {}, library: 'Model' }))) missing.push('WP2 buildProjectModel');
  if (!isImplemented(() => planAction(undefined as never, undefined as never, undefined as never))) missing.push('WP2 planAction');
  if (!isImplemented(() => toGraphJson(undefined as never, undefined as never))) missing.push('WP2 toGraphJson');
  // A missing root: an implemented refresh refuses it (TypeError) or stops at the toolchain check, before any spawn.
  if (!(await asyncImplemented(() => refreshLeanFacts({ root: '/nonexistent-telelean-probe', minAvailableBytes: Number.MAX_SAFE_INTEGER })))) {
    missing.push('WP3 refreshLeanFacts');
  }
  if (!isImplemented(() => createModelWorkspace(undefined as never))) missing.push('WP4 createModelWorkspace');
  if (!(await asyncImplemented(() => findModelRoots('/nonexistent-telelean-probe')))) missing.push('WP4 findModelRoots');
  if (!(await asyncImplemented(() => inspectFolder('/nonexistent-telelean-probe')))) missing.push('WP4 inspectFolder');
  if (!isImplemented(() => planInitialize(undefined as never))) missing.push('WP4 planInitialize');
  return missing;
}

function git(root: string, args: string[]): { status: number | null; stdout: string } {
  const result = spawnSync('git', ['-C', root, '-c', 'core.hooksPath=/dev/null', ...args], {
    encoding: 'utf8',
    env: { ...process.env, GIT_CONFIG_GLOBAL: '/dev/null', GIT_CONFIG_NOSYSTEM: '1', GIT_TERMINAL_PROMPT: '0' },
  });
  return { status: result.status, stdout: result.stdout ?? '' };
}

