/**
 * Drives the test instance's real board webview through the Chrome DevTools Protocol, for the end-to-end suite
 * (e2e.test.ts): clicks, typing and mouse drags are trusted input events, so native text selection and HTML5 drag
 * behave exactly as for the user (synthetic DOM events could not show that a drag in the code selects text).
 *
 * scripts/smoke.mjs picks a free local port and .vscode-test.mjs starts the isolated test instance with
 * `--remote-debugging-port=<port>` (Chromium binds it to 127.0.0.1); this module connects with the installed
 * playwright-core (`connectOverCDP` only attaches: it launches no browser and closing it only disconnects).
 */
import { chromium, type Browser, type Frame, type Page } from 'playwright-core';

import { sleep } from './helpers';

export interface Workbench {
  browser: Browser;
  page: Page;
}

/** Connects to the test instance's renderer and returns its workbench page. */
export async function connectWorkbench(port: string, timeoutMs = 30_000): Promise<Workbench> {
  const deadline = Date.now() + timeoutMs;
  let browser: Browser | undefined;
  for (;;) {
    try {
      browser = await chromium.connectOverCDP(`http://127.0.0.1:${port}`);
      break;
    } catch (error) {
      if (Date.now() > deadline) throw new Error(`cannot connect to the test instance on port ${port}: ${String(error)}`);
      await sleep(500);
    }
  }
  for (;;) {
    const page = browser.contexts().flatMap((context) => context.pages()).find((p) => p.url().includes('workbench.html'));
    if (page) return { browser, page };
    if (Date.now() > deadline) throw new Error('the workbench page did not appear');
    await sleep(250);
  }
}

/** The frame that holds a telelean board (`.tl-board`) whose root name is `rootName`, once it exists. */
export async function boardFrame(page: Page, rootName: string, timeoutMs = 30_000): Promise<Frame> {
  const deadline = Date.now() + timeoutMs;
  for (;;) {
    for (const frame of page.frames()) {
      if (frame.isDetached() || !frame.url().startsWith('vscode-webview://') || !frame.url().includes('fake.html')) continue;
      try {
        if ((await frame.locator('.tl-board').count()) === 0) continue;
        if (await frame.locator('[data-testid="subject-picker"]').count()) {
          const title = await frame.title().catch(() => '');
          // The panel title is "telelean: <folder>"; the webview document has no title of its own, so accept any
          // board when the title is empty (only one model board is open in this suite).
          if (title === '' || title.includes(rootName)) return frame;
        }
      } catch {
        // detached while probing: try the next one
      }
    }
    if (Date.now() > deadline) throw new Error(`no board webview for ${rootName} appeared`);
    await sleep(250);
  }
}

