11	/** Declarations whose facts refs name one of `targets`, closed under "uses a member" (BFS order). */
12	export function factUsers(model: ProjectModel, targets: readonly string[], exclude: ReadonlySet<string>): string[] {
13	  const users = new Map<string, string[]>();
14	  for (const [name, facts] of model.declFacts) {
15	    for (const ref of facts.refs) {
16	      const list = users.get(ref.name) ?? [];
17	      if (!list.includes(name)) list.push(name);
18	      users.set(ref.name, list);
19	    }
20	  }
21	  const out: string[] = [];
22	  const seen = new Set<string>([...targets, ...exclude]);
23	  const queue = [...targets];
24	  while (queue.length > 0) {
25	    const name = queue.shift() as string;
26	    for (const user of users.get(name) ?? []) {
27	      if (seen.has(user)) continue;
28	      seen.add(user);
29	      out.push(user);
30	      queue.push(user);
31	    }
32	  }
33	  return out;
34	}
