41	/** Declarations whose text mentions one of `targets` (resolved in their namespace), transitively. */
42	export function textUsers(model: ProjectModel, targets: readonly string[], exclude: ReadonlySet<string>): string[] {
43	  const decls: Array<{ name: string; file: ParsedFile; decl: DeclInfo }> = [];
44	  for (const file of model.files.values()) for (const decl of file.decls) if (decl.fullName) decls.push({ name: decl.fullName, file, decl });
45	  const out: string[] = [];
46	  const found = new Set<string>(targets);
47	  let grew = true;
48	  while (grew) {
49	    grew = false;
50	    for (const { name, file, decl } of decls) {
51	      if (found.has(name) || exclude.has(name)) continue;
52	      const mentions = identifierTokens(declBody(file, decl)).some((t) => {
53	        let text = t.text;
54	        for (;;) {
55	          if (resolveName(text, decl.namespace, (n) => found.has(n))) return true;
56	          const dot = text.lastIndexOf('.');
57	          if (dot < 0) return false;
58	          text = text.slice(0, dot);
59	        }
60	      });
61	      if (mentions) {
62	        found.add(name);
63	        out.push(name);
64	        grew = true;
65	      }
66	    }
67	  }
68	  return out;
69	}
