11	/** Start offsets (UTF-16 indexes into the string) of every line; lines end at `\n` (a preceding `\r` stays in the line). */
12	export function lineStarts(text: string): number[] {
13	  const starts = [0];
14	  for (let i = text.indexOf('\n'); i >= 0; i = text.indexOf('\n', i + 1)) starts.push(i + 1);
15	  return starts;
