18	/** The text of a 0-based line (without its `\n`), or undefined past the end. */
19	export function lineText(text: string, starts: readonly number[], line: number): string | undefined {
20	  const start = starts[line];
21	  if (start === undefined) return undefined;
22	  const next = starts[line + 1];
23	  return text.slice(start, next === undefined ? text.length : next - 1);
24	}
