  const fileHashes = hashes ?? Object.fromEntries(files.map((r) => [r, sha(read(root, r))]));
  return core.buildProjectModel({ files: files.map((r) => core.parseLeanFile(r, read(root, r))), fileHashes, ...(f ? { facts: f } : {}), library: 'Model',
    lakefile: existsSync(path.join(root, 'lakefile.toml')) ? { path: 'lakefile.toml', text: read(root, 'lakefile.toml') } : undefined });
}
export function graph(m, subject = 'Spyro', semanticState = 'fresh') {
  return core.subjectGraph(m, subject, { version: 1, semantic: { state: semanticState } });
}
export function brief(g) {
  return g.nodes.map((n) => ({ id: n.id, type: n.type, formal: n.status.formal, proof: n.status.proof, flags: n.status.flags, uses: n.lean.uses, presupposes: n.lean.presupposes, just: n.lean.justificationKind }));
}
export const J = (x) => JSON.stringify(x);
