 51	/** A stale file keeps a declaration's facts while its current keyword still says the same kind of declaration. */
 52	export function kindsAgree(keyword: DeclKeyword, kind: LeanDeclKind | undefined): boolean {
 53	  if (kind === undefined) return true;
