/**
 * The enclosing namespaces (outermost first) at `offset`, from `namespace X` / `section` / `end` commands at column 0
 * before it (comments ignored).
 */
export function namespaceAt(text: string, offset: number): string[] {
  const clean = blankComments(text.slice(0, offset));
  const stack: Array<{ kind: 'namespace' | 'section'; parts: string[] }> = [];
  for (const line of clean.split('\n')) {
    const ns = /^namespace\s+(\S+)/.exec(line);
    if (ns) {
      stack.push({ kind: 'namespace', parts: (ns[1] ?? '').split('.').filter(Boolean) });
      continue;
    }
    if (/^section(\s|$)/.test(line)) {
      stack.push({ kind: 'section', parts: [] });
      continue;
    }
    if (/^end(\s|$)/.test(line)) stack.pop();
  }
  return stack.flatMap((entry) => entry.parts);
}

