// Shared helpers for the verify-safety probes (scratch only; never touches the repo).
import { execFileSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { cpSync, existsSync, mkdirSync, readdirSync, readFileSync, statSync, writeFileSync } from 'node:fs';
import path from 'node:path';

export const REPO = '/home/zhengyew/telelean';
export const MENTAL_MODEL = path.join(REPO, 'mental_model');
export const SCRATCH = '/tmp/claude-1002/-home-zhengyew-telelean/03a29d54-7342-40e3-b5f0-2697a62c93ef/scratchpad/turn9/verify-safety';

export const GIT_ENV: NodeJS.ProcessEnv = {
  ...process.env,
  GIT_CONFIG_GLOBAL: '/dev/null',
  GIT_CONFIG_NOSYSTEM: '1',
  GIT_CEILING_DIRECTORIES: path.join(SCRATCH, 'runs'),
  GIT_AUTHOR_NAME: 'Probe User',
  GIT_AUTHOR_EMAIL: 'probe@example.invalid',
  GIT_COMMITTER_NAME: 'Probe User',
  GIT_COMMITTER_EMAIL: 'probe@example.invalid',
  GIT_OPTIONAL_LOCKS: '0',
};

/** git as the "user" runs it in the scratch repo (never runs hooks, never signs). */
export function ugit(cwd: string, ...args: string[]): string {
  return execFileSync('git', ['-c', 'commit.gpgsign=false', '-c', 'core.hooksPath=/dev/null', ...args], {
    cwd,
    env: GIT_ENV,
    encoding: 'utf8',
    stdio: ['ignore', 'pipe', 'pipe'],
  });
}

export function sha256(data: string | Buffer): string {
  return createHash('sha256').update(data).digest('hex');
}

export function copyModel(dest: string): string {
  mkdirSync(path.dirname(dest), { recursive: true });
  cpSync(MENTAL_MODEL, dest, { recursive: true });
  return dest;
}

export function read(root: string, rel: string): string {
  return readFileSync(path.join(root, rel), 'utf8');
}

export function write(root: string, rel: string, text: string | Buffer): void {
  mkdirSync(path.dirname(path.join(root, rel)), { recursive: true });
  writeFileSync(path.join(root, rel), text);
}

export function exists(root: string, rel: string): boolean {
  return existsSync(path.join(root, rel));
}

/** Every regular file under `root` (relative POSIX), skipping `.git` and `.lake`, with its sha256. */
export function treeHashes(root: string): Record<string, string> {
  const out: Record<string, string> = {};
  const walk = (rel: string): void => {
    for (const entry of readdirSync(path.join(root, rel), { withFileTypes: true })) {
      const child = rel ? `${rel}/${entry.name}` : entry.name;
      if (entry.isDirectory()) {
        if (entry.name !== '.git' && entry.name !== '.lake') walk(child);
      } else if (entry.isFile()) {
        out[child] = sha256(readFileSync(path.join(root, child)));
      }
    }
  };
  walk('');
  return out;
}

export function mtime(file: string): number {
  return statSync(file).mtimeMs;
}

export const results: Array<{ check: string; ok: boolean; detail?: string }> = [];

export function check(name: string, ok: boolean, detail?: unknown): void {
  results.push({ check: name, ok, ...(detail !== undefined ? { detail: typeof detail === 'string' ? detail : JSON.stringify(detail) } : {}) });
  console.log(`${ok ? 'PASS' : 'FAIL'}  ${name}${detail !== undefined ? `  -- ${typeof detail === 'string' ? detail : JSON.stringify(detail)}` : ''}`);
}

export function note(text: string): void {
  console.log(`NOTE  ${text}`);
}

// Probe 1: telelean history in a user repository that is in an awkward state:
// detached HEAD, a staged change AND further unstaged edits to a model file telelean edits, unstaged/untracked user
// files, repo-local core.hooksPath pointing at marker hooks (plus marker hooks in .git/hooks), commit.gpgsign=true
// with a failing gpg.program, gc.auto=1. Real core, real git, fs adapters, no Lean.
import { chmodSync, existsSync, mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import path from 'node:path';

import { createModelWorkspace, fsEditApplier, fsTextSource } from '/home/zhengyew/telelean/packages/runner/src/workspace/index.ts';

import { check, copyModel, note, read, results, SCRATCH, sha256, ugit, write } from './common.ts';

const HOOKS = ['pre-commit', 'prepare-commit-msg', 'commit-msg', 'post-commit', 'reference-transaction', 'post-index-change', 'post-checkout', 'post-rewrite', 'pre-auto-gc', 'post-merge', 'pre-push'];

async function main(): Promise<void> {
  const base = path.join(SCRATCH, 'runs', `p1-${process.pid}`);
  rmSync(base, { recursive: true, force: true });
  const repo = path.join(base, 'repo');
  const markers = path.join(base, 'markers');
  mkdirSync(markers, { recursive: true });
  mkdirSync(repo, { recursive: true });
  const root = copyModel(path.join(repo, 'model'));

  ugit(repo, 'init', '-q', '-b', 'main');
  write(repo, 'README.md', 'user readme\n');
  ugit(repo, 'add', '-A');
  ugit(repo, 'commit', '-q', '-m', 'user commit 1');
  write(repo, 'notes.txt', 'n1\n');
  ugit(repo, 'add', '-A');
  ugit(repo, 'commit', '-q', '-m', 'user commit 2');
  ugit(repo, 'tag', 'v1');
  ugit(repo, 'checkout', '-q', '--detach', 'HEAD~1'); // detached HEAD, one commit behind main
  // staged + unstaged changes to a model file telelean will edit
  const main = 'Model/Spyro/Main.lean';
  write(root, main, `${read(root, main)}-- staged by the user\n`);
  ugit(repo, 'add', `model/${main}`);
  write(root, main, `${read(root, main)}-- unstaged by the user\n`);
  write(repo, 'README.md', 'user readme, edited (unstaged)\n');
  write(repo, 'untracked.txt', 'u\n');
  ugit(repo, 'stash', 'list');
  // hooks that leave markers, in .git/hooks and in a repo-local core.hooksPath
  const custom = path.join(repo, '.customhooks');
  mkdirSync(custom);
  for (const dir of [path.join(repo, '.git', 'hooks'), custom]) {
    for (const hook of HOOKS) {
      const file = path.join(dir, hook);
      writeFileSync(file, `#!/bin/sh\necho "$0" >> "${markers}/${hook}"\nexit 0\n`);
      chmodSync(file, 0o755);
    }
  }
  ugit(repo, 'config', 'core.hooksPath', '.customhooks');
  ugit(repo, 'config', 'commit.gpgsign', 'true');
  ugit(repo, 'config', 'gpg.program', '/bin/false');
  ugit(repo, 'config', 'gc.auto', '1');
  ugit(repo, 'config', 'gc.autoDetach', 'false');
  ugit(repo, 'config', 'maintenance.auto', 'true');
  // positive control: a plain `git commit-tree` with the repo config (and no -c overrides) WOULD sign and fail
  let signFails = false;
  try {
    const tree = ugit(repo, 'write-tree').trim();
    // run without the -c overrides from ugit
    const { execFileSync } = await import('node:child_process');
    execFileSync('git', ['commit-tree', tree, '-m', 'x'], { cwd: repo, env: { ...process.env, GIT_CONFIG_GLOBAL: '/dev/null', GIT_CONFIG_NOSYSTEM: '1', GIT_AUTHOR_NAME: 'a', GIT_AUTHOR_EMAIL: 'a@b', GIT_COMMITTER_NAME: 'a', GIT_COMMITTER_EMAIL: 'a@b' }, stdio: 'pipe' });
  } catch {
    signFails = true;
  }
  check('positive control: repo config would make commit-tree sign (and fail with gpg.program=/bin/false)', signFails);

  const gitDir = path.join(repo, '.git');
  const state = (): Record<string, string> => ({
    headFile: readFileSync(path.join(gitDir, 'HEAD'), 'utf8'),
    head: ugit(repo, 'rev-parse', 'HEAD').trim(),
    refs: ugit(repo, 'for-each-ref', '--format=%(refname) %(objectname)').split('\n').filter((l) => l && !l.startsWith('refs/telelean/')).join('\n'),
    index: sha256(readFileSync(path.join(gitDir, 'index'))),
    config: sha256(readFileSync(path.join(gitDir, 'config'))),
    staged: ugit(repo, 'diff', '--cached', '--no-color'),
    statusOutsideModel: ugit(repo, 'status', '--porcelain=v1', '--untracked-files=all', '--', '.', ':(exclude)model'),
    stash: ugit(repo, 'stash', 'list'),
    gitTop: readdirSync(gitDir).filter((n) => n !== 'objects' && n !== 'refs' && n !== 'index').sort().join(','),
    packs: readdirSync(path.join(gitDir, 'objects', 'pack')).sort().join(','),
  });
  const before = state();
  const userMainBefore = read(root, main);

  const log: string[] = [];
  const ws = createModelWorkspace({
    root,
    text: fsTextSource(root),
    applier: fsEditApplier(root),
    semantic: { enabled: false },
    log: (level, message) => log.push(`${level}: ${message}`),
  });
  await ws.load();
  const status0 = await ws.historyStatus();
  check('history is ready in a detached-HEAD repo', status0.state === 'ready', status0);

  const outcomes: Array<[string, unknown]> = [];
  const add = await ws.perform({ kind: 'add-node', subject: 'Spyro', type: 'ASSUMPTION', naturalName: 'Probe assumption one', rationale: 'because' });
  outcomes.push(['add', add]);
  const edit = await ws.perform({ kind: 'edit-node', id: 'cynder-dark-past', field: 'naturalName', value: 'Cynder had a dark past (edited by the probe)' });
  outcomes.push(['edit', edit]);
  const graph = ws.graph('Spyro');
  const newId = (add as { nodeId?: string }).nodeId ?? '';
  const reorder = await ws.perform({ kind: 'reorder', id: newId, column: 'ASSUMPTION', beforeId: graph.nodes.find((n) => n.type === 'ASSUMPTION')?.id ?? null });
  outcomes.push(['reorder', reorder]);
  const premises = await ws.perform({ kind: 'set-premises', target: 'cynder-not-good', premises: ['cynder-dark-past', 'new-spyro-pg'] });
  outcomes.push(['premises', premises]);
  const subj = await ws.perform({ kind: 'create-subject', name: 'Other' });
  outcomes.push(['create-subject', subj]);
  const del = await ws.perform({ kind: 'delete-node', id: newId, keepLean: false });
  outcomes.push(['delete', del]);
  outcomes.push(['undo1', await ws.undo('Spyro')]);
  outcomes.push(['undo2', await ws.undo('Spyro')]);
  outcomes.push(['redo1', await ws.redo('Spyro')]);
  const listing = await ws.listHistory('Spyro', 100);
  note(`Spyro history: ${listing.entries.map((e) => e.label).join(' | ')}`);
  note(`storage: ${JSON.stringify(listing.storage)}`);
  const initial = listing.entries.find((e) => e.label === 'Initial state');
  const revert = initial ? await ws.revert('Spyro', initial.id) : { ok: false, error: 'no Initial state entry' };
  outcomes.push(['revert', revert]);
  const afterRevertMain = read(root, main);
  check('revert to "Initial state" restores the user-dirty Main.lean that was there when the history started', afterRevertMain === userMainBefore, { equal: afterRevertMain === userMainBefore });
  outcomes.push(['undo-revert', await ws.undo('Spyro')]);
  const pruned = await ws.prune('Spyro', 3);
  note(`after prune: ${pruned.entries.map((e) => e.label).join(' | ')}`);
  for (const [name, outcome] of outcomes) check(`outcome ${name} ok`, (outcome as { ok?: boolean }).ok === true, outcome);
  ws.dispose();

  const after = state();
  for (const key of Object.keys(before)) check(`user repo unchanged: ${key}`, before[key] === after[key], before[key] === after[key] ? undefined : { before: before[key], after: after[key] });
  const ran = readdirSync(markers);
  check('no hook ran (neither .git/hooks nor repo core.hooksPath)', ran.length === 0, ran);
  check('no reflog for telelean refs', !existsSync(path.join(gitDir, 'logs', 'refs', 'telelean')));
  check('no gc.log / auto gc', !existsSync(path.join(gitDir, 'gc.log')));
  const fsck = ugit(repo, 'fsck', '--no-dangling', '--no-progress');
  check('git fsck clean', fsck.trim() === '', fsck);
  const telelean = ugit(repo, 'for-each-ref', '--format=%(refname)', 'refs/telelean/').trim().split('\n');
  note(`telelean refs: ${telelean.join(', ')}`);
  const unsigned = ugit(repo, 'cat-file', 'commit', telelean.find((r) => r.endsWith('/subjects/Spyro')) ?? 'HEAD');
  check('snapshot commits are unsigned', !/gpgsig/.test(unsigned));
  // the staged content of Main.lean is still the user's staged version
  const stagedMain = ugit(repo, 'show', `:model/${main}`);
  check("the user's staged Main.lean is unchanged in the index", stagedMain.endsWith('-- staged by the user\n'));
  note(`log lines with warn/error: ${log.filter((l) => !l.startsWith('info')).join(' || ') || '(none)'}`);
  const failed = results.filter((r) => !r.ok);
  console.log(`\nprobe1: ${results.length - failed.length}/${results.length} checks passed`);
}

main().catch((error) => {
  console.error('probe1 crashed:', error);
  process.exit(2);
});

