// Probe 2: the M1 Lean refresh (refreshLeanFacts, in place under runLean) on scratch copies.
//  A. a module whose elaboration tries to write into the model's sources, .git and .lake, and looks at $HOME;
//  B. a large generated subject (RAM and time of the refresh, of the workspace pipeline, graph.json size).
import { existsSync, readFileSync, rmSync, statSync } from 'node:fs';
import path from 'node:path';

import type { LeanFacts } from '@telelean/core';
import { readMemAvailableBytes, refreshLeanFacts } from '/home/zhengyew/telelean/packages/runner/src/semantic/index.ts';
import { createModelWorkspace, fsEditApplier, fsTextSource } from '/home/zhengyew/telelean/packages/runner/src/workspace/index.ts';

import { check, copyModel, note, read, results, SCRATCH, ugit, write } from './common.ts';

const RUN = `vsp${process.pid}`;
const gib = (b: number | undefined): string => (b === undefined ? '?' : `${(b / 1024 ** 3).toFixed(2)} GiB`);
const mib = (b: number | undefined): string => (b === undefined ? '?' : `${(b / 1024 ** 2).toFixed(0)} MiB`);

async function partA(base: string): Promise<void> {
  const root = copyModel(path.join(base, 'evil'));
  ugit(root, 'init', '-q', '-b', 'main');
  ugit(root, 'add', '-A');
  ugit(root, 'commit', '-q', '-m', 'user commit');
  const lakefileBefore = read(root, 'lakefile.toml');
  write(
    root,
    'Model/Spyro/Evil.lean',
    [
      'import Model.Spyro.Vocabulary',
      '',
      '#eval show IO Unit from do',
      '  for p in ["Model/Spyro/pwned.txt", ".git/pwned.txt", ".lake/pwned.txt", "lakefile.toml"] do',
      '    try',
      '      IO.FS.writeFile p "pwned\\n"',
      '      IO.println s!"PROBE WROTE {p}"',
      '    catch e =>',
      '      IO.println s!"PROBE DENIED {p}: {e}"',
      '  let h ← IO.getEnv "HOME"',
      '  IO.println s!"PROBE HOME={h}"',
      '  for p in ["/home/zhengyew/.bashrc", "/home/zhengyew/.claude", "/home/zhengyew/.ssh", "/home/zhengyew/telelean/package.json"] do',
      '    let ex ← System.FilePath.pathExists p',
      '    IO.println s!"PROBE EXISTS {p}={ex}"',
      '  let gitFiles ← System.FilePath.readDir ".git"',
      '  IO.println s!"PROBE .git entries visible: {gitFiles.size}"',
      '',
    ].join('\n'),
  );
  write(root, 'Model/Spyro.lean', `${read(root, 'Model/Spyro.lean')}import Model.Spyro.Evil\n`);
  const facts = await refreshLeanFacts({ root, library: 'Model', runId: `${RUN}a` });
  const texts = facts.build.messages.map((m) => m.text).filter((t) => t.includes('PROBE'));
  note(`A: status ${facts.status}; build ${facts.build.status} ${facts.build.durationMs} ms peak ${mib(facts.build.peakMemoryBytes)}`);
  for (const t of texts) note(`A: lean says: ${t.replace(/\n/g, ' / ')}`);
  check('A: the sandboxed build could not write into the model sources', !existsSync(path.join(root, 'Model/Spyro/pwned.txt')));
  check('A: the sandboxed build could not write into the real .git (masked)', !existsSync(path.join(root, '.git/pwned.txt')));
  check('A: lakefile.toml unchanged', read(root, 'lakefile.toml') === lakefileBefore);
  check('A: the build could write .lake (expected)', existsSync(path.join(root, '.lake/pwned.txt')));
  check('A: $HOME files invisible inside the sandbox', texts.some((t) => t.includes('EXISTS /home/zhengyew/.bashrc=false')) && texts.some((t) => t.includes('EXISTS /home/zhengyew/.ssh=false')), texts);
  check('A: the repo outside the model is invisible', texts.some((t) => t.includes('EXISTS /home/zhengyew/telelean/package.json=false')), texts);
  check('A: git status still clean apart from Evil.lean / Model/Spyro.lean', ugit(root, 'status', '--porcelain').trim().split('\n').every((l) => /Evil\.lean|Model\/Spyro\.lean|\.lake/.test(l)), ugit(root, 'status', '--porcelain'));
}

function bigSubject(nA: number, nD: number, nG: number): Record<string, string> {
  const voc = [
    'namespace Big',
    '',
    '/-- things -/',
    'axiom Thing : Type',
    '/-- there is a thing -/',
    'axiom Thing.exists : Nonempty Thing',
    'instance : Nonempty Thing := Thing.exists',
  ];
  for (let j = 0; j < 20; j++) voc.push(`/-- property ${j} -/`, `axiom P${j} : Thing → Prop`, `/-- thing ${j} -/`, `noncomputable opaque c${j} : Thing`);
  voc.push('', 'end Big', '');
  const main = ['import Model.Big.Vocabulary', 'import Model.Big.Inbox', '', 'namespace Big', ''];
  const block = (id: string, type: string, sentence: string, lean: string, premises?: string): string[] => [
    '/-',
    '@@ telelean v1',
    `id: ${id}`,
    `type: ${type}`,
    `natural_name: ${sentence}`,
    ...(premises ? [`premises: ${premises}`] : []),
    'asserted: 2026-11-01',
    `lean: Big.${lean}`,
    '-/',
    `/-- ${sentence} -/`,
  ];
  for (let i = 0; i < nA; i++) {
    main.push(...block(`big-a-${i}`, 'ASSUMPTION', `Big assumption number ${i} about thing ${i % 20}`, `a${i}`));
    main.push(`abbrev a${i} : Prop := P${i % 20} c${(i * 7) % 20}`, `axiom a${i}.holds : a${i}`, '');
  }
  for (let i = 0; i < nD; i++) {
    const x = i % nA;
    const y = (i + 1) % nA;
    main.push(...block(`big-d-${i}`, 'DERIVATION', `Big derivation ${i} from two assumptions`, `d${i}`, `big-a-${x}, big-a-${y}`));
    main.push(`abbrev d${i} : Prop := a${x} ∧ a${y}`, `theorem d${i}.holds : d${i} := ⟨a${x}.holds, a${y}.holds⟩`, '');
  }
  for (let i = 0; i < nG; i++) {
    const d = i % nD;
    const a = (i * 3) % nA;
    main.push(...block(`big-g-${i}`, 'GOAL', `Big goal ${i} that follows from a derivation`, `g${i}`, `big-d-${d}, big-a-${a}`));
    main.push(`abbrev g${i} : Prop := d${d} ∧ a${a}`, `theorem g${i}.holds : g${i} := ⟨d${d}.holds, a${a}.holds⟩`, '');
  }
  main.push('end Big', '');
  return {
    'Model/Big.lean': 'import Model.Big.Vocabulary\nimport Model.Big.Inbox\nimport Model.Big.Main\n',
    'Model/Big/Vocabulary.lean': voc.join('\n'),
    'Model/Big/Inbox.lean': 'import Model.Big.Vocabulary\n\n-- New cards typed on the telelean board are added here.\nnamespace Big\n\nend Big\n',
    'Model/Big/Main.lean': main.join('\n'),
  };
}

async function partB(base: string, nA: number, nD: number, nG: number): Promise<void> {
  const root = copyModel(path.join(base, `big-${nA + nD + nG}`));
  for (const [rel, text] of Object.entries(bigSubject(nA, nD, nG))) write(root, rel, text);
  write(root, 'Model.lean', 'import Model.Spyro\nimport Model.Big\n');
  write(root, '.telelean/subjects/Big/layout.json', read(root, '.telelean/subjects/Spyro/layout.json'));
  const lines = read(root, 'Model/Big/Main.lean').split('\n').length;
  let captured: LeanFacts | undefined;
  const heap0 = process.memoryUsage();
  const t0 = performance.now();
  const ws = createModelWorkspace({
    root,
    text: fsTextSource(root),
    applier: fsEditApplier(root),
    git: { enabled: false },
    refreshFacts: async (req) => (captured = await refreshLeanFacts({ ...req, runId: `${RUN}b${nA}` })),
  });
  await ws.load();
  const g0 = ws.graph('Big');
  const t1 = performance.now();
  note(`B${nA + nD + nG}: Main.lean ${lines} lines; load+graph without facts ${(t1 - t0).toFixed(0)} ms, ${g0.nodes.length} nodes, ${g0.edges.length} edges`);
  const avail = readMemAvailableBytes();
  note(`B${nA + nD + nG}: MemAvailable before the refresh ${gib(avail)}`);
  const t2 = performance.now();
  const summary = await ws.refreshNow();
  const t3 = performance.now();
  note(`B${nA + nD + nG}: refresh ${summary.state} in ${(t3 - t2).toFixed(0)} ms; build ${captured?.build.status} ${captured?.build.durationMs} ms peak ${mib(captured?.build.peakMemoryBytes)}; check ${captured?.check.status} ${captured?.check.durationMs} ms peak ${mib(captured?.check.peakMemoryBytes)}; facts decls ${captured?.decls.length}`);
  const t4 = performance.now();
  const g1 = ws.graph('Big');
  const t5 = performance.now();
  const graphJson = path.join(root, '.telelean/graph.json');
  const gjSize = existsSync(graphJson) ? statSync(graphJson).size : -1;
  const payload = JSON.stringify({ type: 'graph', payload: { graph: g1 } }).length;
  const proved = g1.nodes.filter((n) => n.lean?.proof?.status === 'proved' || (n as unknown as { proof?: { status?: string } }).proof?.status === 'proved').length;
  note(`B${nA + nD + nG}: graph with facts ${(t5 - t4).toFixed(0)} ms; ${g1.edges.length} edges; board message ${(payload / 1024).toFixed(0)} KiB; graph.json ${(gjSize / 1024).toFixed(0)} KiB; proved-ish nodes ${proved}`);
  // typing simulation: invalidate after a one-character change (rebuild of the project model + graph)
  const main = path.join(root, 'Model/Big/Main.lean');
  const text = readFileSync(main, 'utf8');
  write(root, 'Model/Big/Main.lean', `${text}-- x\n`);
  const t6 = performance.now();
  await ws.invalidate(['Model/Big/Main.lean']);
  ws.graph('Big');
  const t7 = performance.now();
  note(`B${nA + nD + nG}: one keystroke-equivalent (invalidate + graph) ${(t7 - t6).toFixed(0)} ms`);
  // an edit action on the large model
  write(root, 'Model/Big/Main.lean', text);
  await ws.invalidate(['Model/Big/Main.lean']);
  const t8 = performance.now();
  const outcome = await ws.perform({ kind: 'edit-node', id: 'big-a-5', field: 'naturalName', value: 'Edited big assumption 5' });
  const t9 = performance.now();
  note(`B${nA + nD + nG}: edit-node on the large model ${outcome.ok ? 'ok' : JSON.stringify(outcome)} in ${(t9 - t8).toFixed(0)} ms`);
  const heap1 = process.memoryUsage();
  note(`B${nA + nD + nG}: probe process rss ${mib(heap1.rss)} (start ${mib(heap0.rss)}), heapUsed ${mib(heap1.heapUsed)}`);
  check(`B${nA + nD + nG}: refresh fresh`, summary.state === 'fresh', summary);
  ws.dispose();
  rmSync(path.join(root, '.lake'), { recursive: true, force: true });
}

async function main(): Promise<void> {
  const base = path.join(SCRATCH, 'runs', `p2-${process.pid}`);
  rmSync(base, { recursive: true, force: true });
  await partA(base);
  const sizes = (process.env['P2_SIZES'] ?? '200,100,100').split(';').map((s) => s.split(',').map(Number));
  for (const [a, d, g] of sizes) await partB(base, a ?? 0, d ?? 0, g ?? 0);
  const failed = results.filter((r) => !r.ok);
