// Probe 4: what the workspace does when the EditApplier applied the change but then rejects (the extension's
// CheckedEditApplier throws ActionError('internal', '"<label>" was applied, but X could not be saved: save it yourself,
// then Undo if needed.') when TextDocument.save() returns false). Simulated with an in-memory "editor": open buffers
// over the disk copy; the applier writes the buffers (like WorkspaceEdit) and then fails the save.
import { readFileSync, rmSync } from 'node:fs';
import path from 'node:path';

import { ActionError, type FileChange } from '@telelean/core';
import { createModelWorkspace, type EditApplier, type TextSource } from '/home/zhengyew/telelean/packages/runner/src/workspace/index.ts';

import { check, copyModel, note, results, SCRATCH, ugit } from './common.ts';

async function main(): Promise<void> {
  const base = path.join(SCRATCH, 'runs', `p4-${process.pid}`);
  rmSync(base, { recursive: true, force: true });
  const root = copyModel(path.join(base, 'model'));
  ugit(root, 'init', '-q', '-b', 'main');
  const buffers = new Map<string, string | null>(); // "open editors": unsaved text wins over the disk
  const disk = (rel: string): string | null => {
    try {
      return readFileSync(path.join(root, rel), 'utf8');
    } catch {
      return null;
    }
  };
  const text: TextSource = { read: async (rel) => (buffers.has(rel) ? (buffers.get(rel) ?? null) : disk(rel)) };
  let failSave = false;
  const { writeFileSync, mkdirSync, rmSync: rm } = await import('node:fs');
  const applier: EditApplier = {
    async apply(changes: readonly FileChange[], label: string) {
      for (const c of changes) if ((await text.read(c.path)) !== c.before) throw new ActionError('conflict', `${c.path} changed`);
      // WorkspaceEdit applied to the buffers
      for (const c of changes) buffers.set(c.path, c.after);
      if (failSave) throw new ActionError('internal', `"${label}" was applied, but ${changes.map((c) => c.path).join(', ')} could not be saved: save it yourself, then Undo if needed.`);
      // save: flush buffers to disk
      for (const c of changes) {
        const abs = path.join(root, c.path);
        if (c.after === null) rm(abs, { force: true });
        else {
          mkdirSync(path.dirname(abs), { recursive: true });
          writeFileSync(abs, c.after);
        }
        buffers.delete(c.path);
      }
    },
  };
  const ws = createModelWorkspace({ root, text, applier, semantic: { enabled: false } });
  await ws.load();
  const first = await ws.perform({ kind: 'edit-node', id: 'cynder-dark-past', field: 'naturalName', value: 'First edit (saved fine)' });
  check('first edit ok', first.ok, first);
  failSave = true;
  const second = await ws.perform({ kind: 'edit-node', id: 'new-spyro-pg', field: 'naturalName', value: 'Second edit (save fails)' });
  note(`second edit outcome: ${JSON.stringify(second)}`);
  const main = 'Model/Spyro/Main.lean';
  const bufferNow = await text.read(main);
  check('the failed-save edit IS in the buffer (applied)', (bufferNow ?? '').includes('Second edit (save fails)'));
  const state = await ws.workspaceState('Spyro');
  note(`undo label offered now: ${JSON.stringify(state.undo)}`);
  check('Undo now offers the failed-save edit (what the message promises)', (state.undo ?? '').includes('Second edit'), state.undo);
  const graphText = JSON.stringify(ws.graph('Spyro').nodes.find((n) => n.id === 'new-spyro-pg'));
  check('the board shows the applied text after the failed save', graphText.includes('Second edit (save fails)'), graphText.slice(0, 200));
  failSave = false;
  const undo = await ws.undo('Spyro');
  note(`undo outcome: ${JSON.stringify(undo)}`);
  const afterUndo = (await text.read(main)) ?? '';
  check('Undo removed the failed-save edit', !afterUndo.includes('Second edit (save fails)'), { stillThere: afterUndo.includes('Second edit (save fails)'), firstEditStillThere: afterUndo.includes('First edit (saved fine)') });
  const listing = await ws.listHistory('Spyro');
  note(`history: ${listing.entries.map((e) => e.label).join(' | ')}`);
  ws.dispose();
  const failed = results.filter((r) => !r.ok);
  console.log(`\nprobe4: ${results.length - failed.length}/${results.length} checks passed`);
}

main().catch((error) => {
  console.error('probe4 crashed:', error);
  process.exit(2);
});

