// Probe 5: a revert whose pre-revert "Manual edits" snapshot cannot be written (a stale ref lock left by a crashed git):
// does the revert go ahead and delete/overwrite hand edits that then exist only in the in-memory undo stack?
import { existsSync, rmSync, writeFileSync } from 'node:fs';
import path from 'node:path';

import { createModelWorkspace, fsEditApplier, fsTextSource } from '/home/zhengyew/telelean/packages/runner/src/workspace/index.ts';

import { check, copyModel, note, read, results, SCRATCH, ugit, write } from './common.ts';

async function main(): Promise<void> {
  const base = path.join(SCRATCH, 'runs', `p5-${process.pid}`);
  rmSync(base, { recursive: true, force: true });
  const root = copyModel(path.join(base, 'model'));
  ugit(root, 'init', '-q', '-b', 'main');
  const ws = createModelWorkspace({ root, text: fsTextSource(root), applier: fsEditApplier(root), semantic: { enabled: false } });
  await ws.load();
  await ws.perform({ kind: 'add-node', subject: 'Spyro', type: 'ASSUMPTION', naturalName: 'Something telelean wrote' });
  // hand work since the last snapshot
  write(root, 'Model/Spyro/Handmade.lean', '-- an hour of hand formalisation\ntheorem handmade : True := trivial\n');
  write(root, 'Model/Spyro/Main.lean', `${read(root, 'Model/Spyro/Main.lean')}-- hand edit\n`);
  const listing = await ws.listHistory('Spyro');
  const initial = listing.entries.find((e) => e.label === 'Initial state');
  const ref = ugit(root, 'for-each-ref', '--format=%(refname)', 'refs/telelean/').split('\n').find((r) => r.endsWith('/subjects/Spyro')) ?? '';
  writeFileSync(path.join(root, '.git', `${ref}.lock`), ''); // stale lock
  const outcome = initial ? await ws.revert('Spyro', initial.id) : { ok: false };
  note(`revert outcome with the stale lock: ${JSON.stringify(outcome)}`);
  const status = await ws.historyStatus();
  note(`history status: ${JSON.stringify(status)}`);
  check('revert refused because the current state could not be snapshotted first', !outcome.ok, outcome);
  check('hand-made file still on disk', existsSync(path.join(root, 'Model/Spyro/Handmade.lean')));
  rmSync(path.join(root, '.git', `${ref}.lock`));
  const after = await ws.listHistory('Spyro');
  note(`history after removing the lock: ${after.entries.map((e) => e.label).join(' | ')}`);
  const inHistory = after.entries.some((e) => e.label === 'Manual edits');
  check('the hand work is somewhere in the history', inHistory, after.entries.map((e) => e.label));
  ws.dispose();
  const failed = results.filter((r) => !r.ok);
  console.log(`\nprobe5: ${results.length - failed.length}/${results.length} checks passed`);
}

main().catch((error) => {
  console.error('probe5 crashed:', error);
  process.exit(2);
});

