// Probe 6: the model folder in a repository with a second git worktree (same relative path in both checkouts).
import { rmSync } from 'node:fs';
import path from 'node:path';

import { createModelWorkspace, fsEditApplier, fsTextSource } from '/home/zhengyew/telelean/packages/runner/src/workspace/index.ts';

import { check, copyModel, note, read, results, SCRATCH, ugit } from './common.ts';

async function main(): Promise<void> {
  const base = path.join(SCRATCH, 'runs', `p6-${process.pid}`);
  rmSync(base, { recursive: true, force: true });
  const repo = path.join(base, 'repo');
  copyModel(path.join(repo, 'model'));
  ugit(repo, 'init', '-q', '-b', 'main');
  ugit(repo, 'add', '-A');
  ugit(repo, 'commit', '-q', '-m', 'user commit');
  const wt = path.join(base, 'wt2');
  ugit(repo, 'worktree', 'add', '-q', '-b', 'feature', wt);
  const a = path.join(repo, 'model');
  const b = path.join(wt, 'model');
  const wsA = createModelWorkspace({ root: a, text: fsTextSource(a), applier: fsEditApplier(a), semantic: { enabled: false } });
  const wsB = createModelWorkspace({ root: b, text: fsTextSource(b), applier: fsEditApplier(b), semantic: { enabled: false } });
  await wsA.load();
  await wsB.load();
  await wsA.perform({ kind: 'add-node', subject: 'Spyro', type: 'ASSUMPTION', naturalName: 'Only in the main worktree' });
  await wsB.perform({ kind: 'add-node', subject: 'Spyro', type: 'GOAL', naturalName: 'Only in the feature worktree' });
  const listA = await wsA.listHistory('Spyro');
  note(`main worktree's history dropdown: ${listA.entries.map((e) => e.label).join(' | ')}`);
  const foreign = listA.entries.find((e) => e.label.includes('feature worktree'));
  check("the main worktree's history does not list the other worktree's changes", foreign === undefined, listA.entries.map((e) => e.label));
  if (foreign) {
    const r = await wsA.revert('Spyro', foreign.id);
    note(`reverting the main worktree to the other worktree's entry: ${JSON.stringify(r)}`);
    note(`main worktree Inbox now contains the feature-worktree card: ${read(a, 'Model/Spyro/Inbox.lean').includes('Only in the feature worktree')}`);
  }
  wsA.dispose();
  wsB.dispose();
  const failed = results.filter((r) => !r.ok);
  console.log(`\nprobe6: ${results.length - failed.length}/${results.length} checks passed`);
}

main().catch((error) => {
  console.error('probe6 crashed:', error);
  process.exit(2);
});

