// Shared helpers for the verify-safety probes (scratch only; never touches the repo).
import { execFileSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { cpSync, existsSync, mkdirSync, readdirSync, readFileSync, statSync, writeFileSync } from 'node:fs';
import path from 'node:path';

export const REPO = '/home/zhengyew/telelean';
export const MENTAL_MODEL = path.join(REPO, 'mental_model');
export const SCRATCH = '/tmp/claude-1002/-home-zhengyew-telelean/03a29d54-7342-40e3-b5f0-2697a62c93ef/scratchpad/turn9/verify-safety';

export const GIT_ENV: NodeJS.ProcessEnv = {
  ...process.env,
  GIT_CONFIG_GLOBAL: '/dev/null',
  GIT_CONFIG_NOSYSTEM: '1',
  GIT_CEILING_DIRECTORIES: path.join(SCRATCH, 'runs'),
  GIT_AUTHOR_NAME: 'Probe User',
  GIT_AUTHOR_EMAIL: 'probe@example.invalid',
  GIT_COMMITTER_NAME: 'Probe User',
  GIT_COMMITTER_EMAIL: 'probe@example.invalid',
  GIT_OPTIONAL_LOCKS: '0',
};

/** git as the "user" runs it in the scratch repo (never runs hooks, never signs). */
export function ugit(cwd: string, ...args: string[]): string {
  return execFileSync('git', ['-c', 'commit.gpgsign=false', '-c', 'core.hooksPath=/dev/null', ...args], {
    cwd,
    env: GIT_ENV,
    encoding: 'utf8',
    stdio: ['ignore', 'pipe', 'pipe'],
  });
}

export function sha256(data: string | Buffer): string {
  return createHash('sha256').update(data).digest('hex');
}

export function copyModel(dest: string): string {
  mkdirSync(path.dirname(dest), { recursive: true });
  cpSync(MENTAL_MODEL, dest, { recursive: true });
  return dest;
}

export function read(root: string, rel: string): string {
  return readFileSync(path.join(root, rel), 'utf8');
}

export function write(root: string, rel: string, text: string | Buffer): void {
  mkdirSync(path.dirname(path.join(root, rel)), { recursive: true });
  writeFileSync(path.join(root, rel), text);
}

export function exists(root: string, rel: string): boolean {
  return existsSync(path.join(root, rel));
}

/** Every regular file under `root` (relative POSIX), skipping `.git` and `.lake`, with its sha256. */
export function treeHashes(root: string): Record<string, string> {
  const out: Record<string, string> = {};
  const walk = (rel: string): void => {
    for (const entry of readdirSync(path.join(root, rel), { withFileTypes: true })) {
      const child = rel ? `${rel}/${entry.name}` : entry.name;
      if (entry.isDirectory()) {
        if (entry.name !== '.git' && entry.name !== '.lake') walk(child);
      } else if (entry.isFile()) {
        out[child] = sha256(readFileSync(path.join(root, child)));
      }
    }
  };
  walk('');
  return out;
}

export function mtime(file: string): number {
  return statSync(file).mtimeMs;
}

export const results: Array<{ check: string; ok: boolean; detail?: string }> = [];

export function check(name: string, ok: boolean, detail?: unknown): void {
  results.push({ check: name, ok, ...(detail !== undefined ? { detail: typeof detail === 'string' ? detail : JSON.stringify(detail) } : {}) });

