source /tmp/claude-1002/-home-zhengyew-telelean/03a29d54-7342-40e3-b5f0-2697a62c93ef/scratchpad/turn9/verify-final/env.sh; echo "DBUS=${DBUS_SESSION_BUS_ADDRESS:-unset} XDG_RUNTIME_DIR=${XDG_RUNTIME_DIR:-unset}"; cat > $V/vs/harness/vf-drive.mjs <<EOF
// Final verifier's real-VS-Code checks (isolated VS Code 1.140 test build over CDP on 127.0.0.1 only).
// phase A: open two boards, reload twice (restored boards must render), toast Undo, Open in editor, delete with deps, quit.
// phase B: after a restart with the same profile, the restored boards must render; quit.
import { chromium } from '$R/node_modules/playwright-core/index.mjs';
import { readFileSync } from 'node:fs';

const [port, phase, wsDir, shots] = process.argv.slice(2);
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const log = (...a) => console.log(new Date().toISOString().slice(11, 23), ...a);
const results = [];
const check = (name, ok, detail) => { results.push({ name, ok }); log(\`\${ok ? 'PASS' : 'FAIL'} \${name}\${detail !== undefined ? ' -- ' + (typeof detail === 'string' ? detail : JSON.stringify(detail)) : ''}\`); };

async function connect(timeoutMs = 90000) {
  const deadline = Date.now() + timeoutMs;
  for (;;) {
    try {
      const browser = await chromium.connectOverCDP(\`http://127.0.0.1:\${port}\`);
      for (;;) {
        const page = browser.contexts().flatMap((c) => c.pages()).find((p) => p.url().includes('workbench.html'));
        if (page) return { browser, page };
        if (Date.now() > deadline) throw new Error('no workbench page');
        await sleep(250);
      }
    } catch (e) {
      if (Date.now() > deadline) throw e;
      await sleep(500);
    }
  }
}
async function palette(page, command, pick) {
  await page.locator('.part.sidebar .composite.title').first().click({ timeout: 5000 }).catch(() => undefined);
  await page.keyboard.press('F1');
  const input = page.locator('.quick-input-widget:visible input');
  await input.waitFor({ timeout: 15000 });
  await input.fill(\`>\${command}\`);
  await sleep(600);
  await page.keyboard.press('Enter');
  if (pick) { await sleep(900); await input.fill(pick); await sleep(500); await page.keyboard.press('Enter'); }
}
async function boards(page) {
  const out = [];
  for (const frame of page.frames()) {
    if (frame.isDetached() || !frame.url().startsWith('vscode-webview://')) continue;
    try {
      const info = await frame.evaluate(() => {
        const app = document.querySelector('.tl-app');
        if (!app) return null;
        return { root: document.querySelector('.tl-toolbar__root')?.textContent ?? '?', cards: document.querySelectorAll('[data-node-id]').length };
      });
      if (info) out.push({ ...info, frame });
    } catch {}
  }
  return out;
}
async function boardFrame(page, root, timeoutMs = 60000) {
  const t0 = Date.now();
  for (;;) {
    const found = (await boards(page)).find((b) => b.root === root && b.cards >= 4);
    if (found) return found.frame;
    if (Date.now() - t0 > timeoutMs) return null;
    await sleep(250);
  }
}
async function waitBoard(page, root, label, timeoutMs = 60000) {
  const t0 = Date.now();
  const f = await boardFrame(page, root, timeoutMs);
  const iframes = await page.evaluate(() => document.querySelectorAll('iframe').length).catch(() => -1);
  check(\`\${label}: board "\${root}" renders its cards\`, !!f, f ? \`after \${Date.now() - t0} ms; iframes \${iframes}\` : \`NOT rendered after \${timeoutMs} ms; iframes \${iframes}\`);
  return f;
}
const tabs = (page) => page.locator('.tabs-container .tab').allInnerTexts().catch(() => []);
const clickTab = (page, text) => page.locator('.tabs-container .tab', { hasText: text }).first().click();
async function toastInfo(f) {
  return f.getByTestId('toast').evaluateAll((els) => els.map((e) => ({ text: (e.textContent ?? '').replace(/\\s+/g, ' ').trim(), undo: [...e.querySelectorAll('button')].some((b) => /^Undo$/.test((b.textContent ?? '').trim())) })));
}

let { browser, page } = await connect();
await page.locator('.monaco-workbench').waitFor({ timeout: 60000 });
await sleep(3000);
log('tabs at start:', JSON.stringify(await tabs(page)));

if (phase === 'A') {
  await palette(page, 'telelean: Open Board', 'mental_model');
  await waitBoard(page, 'mental_model', 'open #1');
  await palette(page, 'telelean: Open Board', 'second_model');
  await waitBoard(page, 'second_model', 'open #2');
  for (const round of [1, 2]) {
    await palette(page, 'Developer: Reload Window');
    await browser.close().catch(() => undefined);
    await sleep(4000);
    ({ browser, page } = await connect());
    await page.locator('.monaco-workbench').waitFor({ timeout: 60000 });
    log(\`reload #\${round}: tabs:\`, JSON.stringify(await tabs(page)));
    await waitBoard(page, 'second_model', \`reload #\${round} active tab\`);
    await clickTab(page, 'telelean: mental_model');
    await waitBoard(page, 'mental_model', \`reload #\${round} background tab, shown\`);
    await clickTab(page, 'telelean: second_model');
    await sleep(1000);
  }

  // Toast Undo (real host): two adds in a row; only the newest toast offers Undo; it undoes that add.
  let f = await boardFrame(page, 'second_model');
  const box = f.getByRole('textbox', { name: 'New assumption' });
  for (const text of ['VF toast one', 'VF toast two']) {
    await box.fill(text);
    await box.press('Enter');
    await f.locator('[data-node-id]', { hasText: text }).first().waitFor({ timeout: 15000 });
    await f.getByTestId('toast').filter({ hasText: \`Add assumption: \${text}\` }).first().waitFor({ timeout: 15000 });
  }
  await sleep(1500);
  const before = await toastInfo(f);
  log('toasts after two adds:', JSON.stringify(before));
  const one = before.find((t) => t.text.includes('VF toast one'));
  const two = before.find((t) => t.text.includes('VF toast two'));
  check('older toast ("VF toast one") offers no Undo', !!one && !one.undo, one);
  check('newest toast ("VF toast two") offers Undo', !!two && two.undo, two);
  if (two?.undo) {
    await f.getByTestId('toast').filter({ hasText: 'VF toast two' }).getByRole('button', { name: 'Undo' }).click();
    await sleep(2000);
    const hasOne = (await f.locator('[data-node-id]', { hasText: 'VF toast one' }).count()) > 0;
    const hasTwo = (await f.locator('[data-node-id]', { hasText: 'VF toast two' }).count()) > 0;
    check('toast Undo removed "VF toast two" and kept "VF toast one"', hasOne && !hasTwo, { hasOne, hasTwo });
    const after = await toastInfo(f);
    log('toasts after the Undo:', JSON.stringify(after));
    check('no toast offers Undo after an Undo', after.every((t) => !t.undo), after);
  }
  await page.screenshot({ path: \`\${shots}/vf-real-toasts.png\` });

  // Open in editor: the board stays readable.
  const cardEl = f.locator('[data-node-id="cynder-dark-past"]');
  await cardEl.locator('.tl-card__chevron').click();
  await cardEl.getByRole('button', { name: /Open in editor/ }).first().click();
  await sleep(2500);
  f = await boardFrame(page, 'second_model');
  const groups = await page.locator('.editor-group-container').count();
  const widths = await f.locator('.tl-col').evaluateAll((cols) => cols.map((c) => Math.round(c.getBoundingClientRect().width)));
  const scroll = await f.locator('.tl-board-scroll').evaluate((el) => [el.scrollWidth, el.clientWidth]).catch(() => null);
  const broken = await f.evaluate(() => {
    const out = [];
    for (const span of document.querySelectorAll('.tl-card__text')) {
      const text = span.firstChild;
      if (!text || text.nodeType !== 3) continue;
      for (const m of (text.textContent ?? '').matchAll(/\\S+/g)) {
        const r = document.createRange(); r.setStart(text, m.index); r.setEnd(text, m.index + m[0].length);
        if (new Set([...r.getClientRects()].map((x) => Math.round(x.top))).size > 1) out.push(m[0]);
      }
    }
    return out;
  });
  check('Open in editor: board columns stay >= 220 px, no word broken inside', widths.every((w) => w >= 220) && broken.length === 0, { groups, widths, scroll, broken });
  await page.screenshot({ path: \`\${shots}/vf-real-open-in-editor.png\` });

  // Delete with Lean when an untracked lemma uses the assumption (mental_model copy has helper_lemma).
  await clickTab(page, 'telelean: mental_model');
  let m = await boardFrame(page, 'mental_model');
  const badge = () => m.getByTestId('lean-badge').textContent().catch(() => '?');
  for (let i = 0; i < 240 && (await badge()) !== 'Lean: up to date'; i++) await sleep(500);
  log('mental_model badge:', await badge());
  const dark = m.locator('[data-node-id="cynder-dark-past"]');
  await dark.locator('.tl-card__chevron').click();
  await dark.getByRole('button', { name: 'Delete' }).click();
  const dialog = m.getByTestId('dialog-delete');
  await dialog.waitFor({ timeout: 10000 });
  log('delete dialog:', JSON.stringify((await dialog.innerText()).replace(/\\n+/g, ' | ')));
  await dialog.getByRole('button', { name: 'Delete card and its Lean code' }).click();
  await sleep(2500);
  const toastsDel = await toastInfo(m);
  const dialogsOpen = await m.locator('[data-testid^="dialog-"]').evaluateAll((els) => els.map((e) => e.getAttribute('data-testid')));
  const anyway = await m.getByRole('button', { name: /anyway/i }).count();
  const main = readFileSync(\`\${wsDir}/mental_model/Model/Spyro/Main.lean\`, 'utf8');
  log('after "Delete card and its Lean code":', JSON.stringify({ toasts: toastsDel, dialogsOpen, anywayButtons: anyway, cardStill: await dark.count(), fileKeepsAxiom: main.includes('axiom cynder_dark_past.holds'), fileKeepsLemma: main.includes('theorem helper_lemma') }));
  check('delete with Lean that would break helper_lemma is refused (file unchanged)', main.includes('axiom cynder_dark_past.holds') && main.includes('theorem helper_lemma'));
  check('the board offers a confirmation listing the dependents with "Delete anyway"', dialogsOpen.length > 0 && anyway > 0, { dialogsOpen, anyway });
  await page.screenshot({ path: \`\${shots}/vf-real-delete-refused.png\` });
  log('tabs before quit:', JSON.stringify(await tabs(page)));
  await clickTab(page, 'telelean: second_model');
  await sleep(1000);
} else {
  log('restart: tabs:', JSON.stringify(await tabs(page)));
  await waitBoard(page, 'second_model', 'restart active tab');
  await clickTab(page, 'telelean: mental_model');
  await waitBoard(page, 'mental_model', 'restart background tab, shown');
}
await palette(page, 'File: Exit');
await sleep(500);
await browser.close().catch(() => undefined);
const failed = results.filter((r) => !r.ok);
log(\`RESULT phase \${phase}: \${results.length - failed.length}/\${results.length} checks passed\${failed.length ? '; failed: ' + failed.map((r) => r.name).join(' ; ') : ''}\`);
process.exit(0);
EOF
