// Driver helpers for the UX verifier: attach to the isolated VS Code test instance over CDP (loopback only).
import { chromium } from '/home/zhengyew/telelean/node_modules/playwright-core/index.mjs';
import { writeFileSync, readFileSync } from 'node:fs';
import * as path from 'node:path';

export const SCRATCH = '/tmp/claude-1002/-home-zhengyew-telelean/03a29d54-7342-40e3-b5f0-2697a62c93ef/scratchpad/turn9/verify-ux';
export const SHOTS = path.join(SCRATCH, 'shots');
export const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

export async function connect(port, timeoutMs = 60000) {
  const deadline = Date.now() + timeoutMs;
  let browser;
  for (;;) {
    try {
      browser = await chromium.connectOverCDP(`http://127.0.0.1:${port}`);
      break;
    } catch (e) {
      if (Date.now() > deadline) throw e;
      await sleep(500);
    }
  }
  for (;;) {
    const page = browser.contexts().flatMap((c) => c.pages()).find((p) => p.url().includes('workbench.html'));
    if (page) return { browser, page };
    if (Date.now() > deadline) throw new Error('no workbench page');
    await sleep(250);
  }
}

export async function setWindow(page, width = 1600, height = 1000) {
  const cdp = await page.context().newCDPSession(page);
  const { windowId } = await cdp.send('Browser.getWindowForTarget');
  await cdp.send('Browser.setWindowBounds', { windowId, bounds: { left: 0, top: 0, width, height, windowState: 'normal' } });
  await cdp.detach();
}

export async function palette(page, command, { pick } = {}) {
  await page.keyboard.press('F1');
  const input = page.locator('.quick-input-widget input');
  await input.waitFor({ timeout: 10000 });
  await input.fill(`>${command}`);
  await sleep(400);
  await page.keyboard.press('Enter');
  if (pick) {
    await sleep(500);
  }
}

/** The board webview frame (the inner frame that holds .tl-app). */
export async function boardFrame(page, timeoutMs = 30000, predicate = '.tl-app') {
  const deadline = Date.now() + timeoutMs;
  for (;;) {
    for (const frame of page.frames()) {
      if (frame.isDetached() || !frame.url().startsWith('vscode-webview://')) continue;
      try {
        if ((await frame.locator(predicate).count()) > 0) return frame;
      } catch {}
    }
    if (Date.now() > deadline) throw new Error('no board frame');
    await sleep(250);
  }
}

export async function shot(page, name) {
  const file = path.join(SHOTS, `${name}.png`);
  await page.screenshot({ path: file });
  return file;
}

export function setTheme(profile, theme) {
  const file = path.join(profile, 'user-data', 'User', 'settings.json');
  const json = JSON.parse(readFileSync(file, 'utf8'));
  json['workbench.colorTheme'] = theme;
  writeFileSync(file, JSON.stringify(json, null, 2) + '\n');
}

export function setSetting(profile, key, value) {
  const file = path.join(profile, 'user-data', 'User', 'settings.json');
  const json = JSON.parse(readFileSync(file, 'utf8'));
  if (value === undefined) delete json[key];
  else json[key] = value;
  writeFileSync(file, JSON.stringify(json, null, 2) + '\n');
}

export async function waitFor(fn, timeoutMs, label, interval = 200) {
  const deadline = Date.now() + timeoutMs;
  for (;;) {
    try {
      if (await fn()) return;
    } catch {}
    if (Date.now() > deadline) throw new Error(`timeout: ${label}`);
    await sleep(interval);
  }
}

/** Runs a scenario module: node drive.mjs <port> <scenario.mjs> [args...] */
export async function main() {
  const [port, scenario, ...args] = process.argv.slice(2);
  const { browser, page } = await connect(port);
  const mod = await import(path.resolve(scenario));
  try {
    await mod.default({ browser, page, args });
  } finally {
    await browser.close().catch(() => undefined); // disconnect only
  }
}

