  const tag = args[0] ?? 'light';
  const f = await boardFrame(page);
  // collapse the vocabulary first, to see that a click expands it
  const vocab = f.getByTestId('vocabulary');
  if ((await vocab.getAttribute('data-collapsed')) !== 'true') {
    await f.locator('.tl-vocab__toggle').click();
    await sleep(300);
  }
  const card = f.locator('[data-node-id="cynder-dark-past"]');
  const ref = card.locator('.tl-lean .tl-ref[data-ref="Spyro.HasDarkPast"]');
  await ref.scrollIntoViewIfNeeded();
  await ref.click();
  await sleep(300);
  await shot(page, `12-ref-click-highlight-${tag}`);
  const item = f.locator('.tl-vocab__item[data-vocab="Spyro.HasDarkPast"]');
  console.log('highlight attr:', await item.getAttribute('data-highlight'), 'collapsed:', await vocab.getAttribute('data-collapsed'));
  const box = await item.boundingBox();
  console.log('item box', JSON.stringify(box));
  // Is the selection changed by the click? (it must not)
  console.log('selected cards:', await f.locator('[data-node-id][data-selected]').count());
  await sleep(2200);
  console.log('highlight after 2.2s:', await item.getAttribute('data-highlight'));

  // click on the card's own name ref (cynder_dark_past -> node)
  const own = card.locator('.tl-lean .tl-ref[data-ref="Spyro.cynder_dark_past"]');
  await own.scrollIntoViewIfNeeded();
  await own.hover();
  await sleep(400);
  const tip = f.getByTestId('ref-tooltip');
  console.log('own TIP:', (await tip.count()) ? (await tip.innerText()).replace(/\n/g, ' | ') : '(none)');
  await own.click();
  await sleep(300);
  console.log('card highlight:', await card.getAttribute('data-highlight'));

  // uses dropdown on the goal
  const goal = f.locator('[data-node-id="cynder-not-good"]');
  await goal.locator('.tl-uses__toggle').click();
  await sleep(400);
  await shot(page, `13-uses-dropdown-${tag}`);
  console.log('USES MENU:', (await f.getByTestId('uses-menu').innerText()).replace(/\n/g, ' | '));
  // keyboard: is the first menu item focused? try ArrowDown
  console.log('active el after open:', await f.evaluate(() => document.activeElement?.className + ' ' + document.activeElement?.textContent?.slice(0, 40)));
  await page.keyboard.press('ArrowDown');
  console.log('active el after ArrowDown:', await f.evaluate(() => document.activeElement?.className + ' ' + document.activeElement?.textContent?.slice(0, 40)));
  await f.getByTestId('uses-menu').locator('[data-vocab="Spyro.newSpyro"]').click();
  await sleep(300);
  await shot(page, `14-uses-pick-highlight-${tag}`);
  console.log('newSpyro highlight:', await f.locator('.tl-vocab__item[data-vocab="Spyro.newSpyro"]').getAttribute('data-highlight'));
}

import { boardFrame, shot, sleep } from './lib.mjs';

const describe = (f) =>
  f.evaluate(() => {
    const el = document.activeElement;
    if (!el || el === document.body) return '(body)';
    const label = el.getAttribute('aria-label') || el.getAttribute('data-testid') || '';
    const text = (el.textContent || '').trim().replace(/\s+/g, ' ').slice(0, 50);
    const inPortal = !!el.closest('.tl-popover');
    const outline = getComputedStyle(el).outlineStyle + ' ' + getComputedStyle(el).outlineWidth + ' ' + getComputedStyle(el).outlineColor;
    return `${el.tagName.toLowerCase()}.${(el.className || '').toString().split(' ')[0]} [${label}] "${text}"${inPortal ? ' (in popover)' : ''} outline=${outline}`;
  });

export default async function ({ page, args }) {
  const tag = args[0] ?? 'light';
  const f = await boardFrame(page);
  // collapse expanded cards, collapse vocab
  for (const chev of await f.locator('.tl-card__chevron[aria-expanded="true"]').all()) await chev.click();
  if ((await f.getByTestId('vocabulary').getAttribute('data-collapsed')) !== 'true') await f.locator('.tl-vocab__toggle').click();
  await sleep(300);
  // focus the board: click the title text
  await f.locator('.tl-toolbar__title').click();
  const seen = [];
  for (let i = 0; i < 45; i++) {
    await page.keyboard.press('Tab');
    await sleep(60);
    const d = await describe(f);
    seen.push(`${i + 1}: ${d}`);
    if (i === 6) await shot(page, `20-focus-ring-${tag}`);
  }
  console.log(seen.join('\n'));

  // subject picker via keyboard
  await f.getByTestId('subject-picker').focus();
  await page.keyboard.press('Enter');
  await sleep(300);
  console.log('after Enter on picker: menu open =', await f.getByTestId('subject-menu').count(), ' focus =', await describe(f));
  await page.keyboard.press('Tab');
  await sleep(100);
  console.log('Tab ->', await describe(f));
  await page.keyboard.press('ArrowDown');
  await sleep(100);
  console.log('ArrowDown ->', await describe(f));
  await shot(page, `21-subject-menu-kbd-${tag}`);
  await page.keyboard.press('Escape');
  await sleep(200);
  console.log('after Escape: menu open =', await f.getByTestId('subject-menu').count());

  // history via keyboard
  await f.getByTestId('history-button').focus();
  await page.keyboard.press('Enter');
  await sleep(500);
  console.log('after Enter on history: open =', await f.getByTestId('history-menu').count(), ' focus =', await describe(f));
  await page.keyboard.press('Tab');
  await sleep(100);
  console.log('Tab ->', await describe(f));
  await shot(page, `22-history-no-repo-${tag}`);
  await page.keyboard.press('Escape');
  await sleep(200);

  // card keyboard: focus first card, Enter expands, Space selects
  const card = f.locator('[data-node-id="new-spyro-pg"]');
  await card.focus();
  await page.keyboard.press('Enter');
  await sleep(300);
  console.log('Enter -> expanded:', await card.locator('.tl-details').count());
  await page.keyboard.press(' ');
  await sleep(200);
  console.log('Space -> selected:', await card.getAttribute('data-selected'));
  await shot(page, `23-card-kbd-selected-${tag}`);
  await page.keyboard.press('F2');
  await sleep(200);
  console.log('F2 -> focus:', await describe(f));
  await page.keyboard.press('Escape');
  await sleep(200);
  console.log('Esc -> focus:', await describe(f));
  await card.focus();
  await page.keyboard.press('Delete');
  await sleep(300);
  console.log('Delete -> dialog:', await f.getByTestId('dialog-delete').count(), ' focus:', await describe(f));
  await shot(page, `24-delete-dialog-${tag}`);
  await page.keyboard.press('Escape');
  await sleep(300);
  console.log('Esc -> dialog:', await f.getByTestId('dialog-delete').count(), ' focus:', await describe(f));
  // clear selection
  await page.keyboard.press(' ');
}

