import { boardFrame, shot, sleep, waitFor } from './lib.mjs';
import { readFileSync } from 'node:fs';

export default async function ({ page, args }) {
  const tag = args[0] ?? 'light';
  const root = args[1];
  const f = await boardFrame(page);
  // 1. Initialize git from the History dropdown
  await f.getByTestId('history-button').click();
  await sleep(300);
  await f.getByTestId('history-unavailable').getByRole('button', { name: 'Initialize git' }).click();
  // VS Code modal (custom dialog style)
  const dialog = page.locator('.monaco-dialog-box');
  await dialog.waitFor({ timeout: 10000 });
  await sleep(300);
  await shot(page, `30-initgit-modal-${tag}`);
  console.log('MODAL:', (await dialog.innerText()).replace(/\n+/g, ' | '));
  await dialog.getByRole('button', { name: 'Initialize git' }).click();
  await sleep(1500);
  // history dropdown again
  const menuOpen = await f.getByTestId('history-menu').count();
  console.log('history menu still open after init:', menuOpen);
  if (!menuOpen) await f.getByTestId('history-button').click();
  await sleep(1000);
  await shot(page, `31-history-after-init-${tag}`);
  console.log('HISTORY:', (await f.getByTestId('history-menu').innerText()).replace(/\n+/g, ' | '));
  await page.keyboard.press('Escape');
  await sleep(300);

  // 2. Add an assumption through the A|D|G box with stance + why + source
  await f.getByRole('radio', { name: 'Assumption' }).click();
  await f.getByLabel('New assumption').fill('Cynder can breathe fire');
  await f.getByRole('group', { name: 'Stance' }).getByRole('button', { name: 'I believe it' }).click();
  await f.getByLabel('Why (optional)').fill('seen in the games');
  await f.getByRole('group', { name: 'Source' }).getByRole('button', { name: 'observed' }).click();
  await shot(page, `32-box-filled-${tag}`);
  const t0 = Date.now();
  await f.getByLabel('New assumption').press('Enter');
  await sleep(150);
  await shot(page, `33-add-provisional-${tag}`);
  await waitFor(async () => (await f.locator('[data-node-id="cynder-can-breathe-fire"]').count()) > 0 && (await f.locator('[data-provisional]').count()) === 0, 15000, 'card confirmed');
  console.log('confirmed after', Date.now() - t0, 'ms');
  await sleep(500);
  await shot(page, `34-add-confirmed-${tag}`);
  console.log('TOASTS:', (await f.getByTestId('toasts').innerText()).replace(/\n+/g, ' | '));
  if (root) console.log('INBOX:\n' + readFileSync(`${root}/Model/Spyro/Inbox.lean`, 'utf8'));
}

import { boardFrame, shot, sleep, waitFor } from './lib.mjs';
import { readFileSync } from 'node:fs';

export default async function ({ page, args }) {
  const tag = args[0] ?? 'light';
  const root = args[1];
  const f = await boardFrame(page);
  // close the history menu if open, collapse expanded cards
  await page.keyboard.press('Escape');
  for (const chev of await f.locator('.tl-card__chevron[aria-expanded="true"]').all()) await chev.click();
  // reopen history to see the entries now
  await f.getByTestId('history-button').click();
  await sleep(1000);
  console.log('HISTORY (reopened):', (await f.getByTestId('history-menu').innerText()).replace(/\n+/g, ' | '));
  await shot(page, `35-history-reopened-${tag}`);
  await page.keyboard.press('Escape');
  await sleep(200);

  const form = f.locator('form.tl-prompt');
  await form.getByRole('radio', { name: 'Assumption' }).click();
  await form.getByLabel('New assumption').fill('Cynder can breathe fire');
  await form.getByRole('group', { name: 'Stance' }).getByRole('button', { name: 'I believe it' }).click();
  await form.getByLabel('Why (optional)').fill('seen in the games');
  await form.getByRole('group', { name: 'Source' }).getByRole('button', { name: 'observed' }).click();
  await shot(page, `32-box-filled-${tag}`);
  const t0 = Date.now();
  await form.getByLabel('New assumption').press('Enter');
  await sleep(120);
  await shot(page, `33-add-provisional-${tag}`);
  await waitFor(async () => (await f.locator('[data-node-id="cynder-can-breathe-fire"]').count()) > 0 && (await f.locator('[data-provisional]').count()) === 0, 15000, 'card confirmed');
  console.log('confirmed after', Date.now() - t0, 'ms');
  await sleep(600);
  await shot(page, `34-add-confirmed-${tag}`);
  console.log('TOASTS:', (await f.getByTestId('toasts').innerText()).replace(/\n+/g, ' | '));
  console.log('box after add: text=', JSON.stringify(await form.getByLabel('New assumption').inputValue()), ' why=', JSON.stringify(await form.getByLabel('Why (optional)').inputValue()));
  console.log('focus after add:', await f.evaluate(() => document.activeElement?.getAttribute('aria-label') ?? document.activeElement?.tagName));
  if (root) console.log('INBOX:\n' + readFileSync(`${root}/Model/Spyro/Inbox.lean`, 'utf8'));
  // Add a goal and a derivation too (comment-only)
  await form.getByRole('radio', { name: 'Goal' }).click();
  await form.getByLabel('New goal').fill('Cynder should be in a T-rated Spyro spin-off');
  await form.getByLabel('Why (optional)').fill('fans love her');
  await form.getByLabel('New goal').press('Enter');
  await waitFor(async () => (await f.locator('[data-provisional]').count()) === 0, 15000, 'goal confirmed');
  await form.getByRole('radio', { name: 'Derivation' }).click();
  await form.getByLabel('New derivation').fill('Cynder is not suitable for PG games');
  await form.getByLabel('New derivation').press('Enter');
  await waitFor(async () => (await f.locator('[data-provisional]').count()) === 0, 15000, 'derivation confirmed');
  await sleep(800);
  await shot(page, `36-after-adds-${tag}`);
  console.log('ORDER:', JSON.stringify(await f.locator('.tl-col').evaluateAll((cols) => cols.map((c) => [c.dataset.kind, [...c.querySelectorAll('[data-node-id]')].map((e) => e.dataset.nodeId)]))));
}

import { boardFrame, shot, sleep, waitFor } from './lib.mjs';

export default async function ({ page, args }) {
  const tag = args[0] ?? 'light';
  const f = await boardFrame(page);
  const form = f.locator('form.tl-prompt');
  await form.getByRole('radio', { name: 'Assumption' }).click();
  for (const text of ['Toast test one', 'Toast test two']) {
    await form.getByLabel('New assumption').fill(text);
    await form.getByLabel('New assumption').press('Enter');
    await waitFor(async () => (await f.locator('[data-provisional]').count()) === 0 && (await f.locator('[data-node-id]').filter({ hasText: text }).count()) > 0, 15000, `confirmed ${text}`);
  }
  await sleep(300);
  const toasts = f.getByTestId('toast');
  console.log('toasts:', await toasts.allInnerTexts());
  const first = toasts.filter({ hasText: 'Toast test one' });
  await shot(page, `40-two-toasts-${tag}`);
  await first.getByRole('button', { name: 'Undo' }).click();
  await sleep(1500);
  const cards = await f.locator('[data-node-id]').allInnerTexts();
  console.log('has one:', cards.some((t) => t.includes('Toast test one')), ' has two:', cards.some((t) => t.includes('Toast test two')));
  console.log('toasts after:', await toasts.allInnerTexts());
  await shot(page, `41-after-toast-undo-${tag}`);
}

import { boardFrame, shot, sleep, waitFor } from './lib.mjs';
import { readFileSync } from 'node:fs';

const order = (f) => f.locator('.tl-col').evaluateAll((cols) => cols.map((c) => [c.dataset.kind, [...c.querySelectorAll('[data-node-id]')].map((e) => e.dataset.nodeId)]));

async function drag(page, from, to, { steps = 20, midShot } = {}) {
  await page.mouse.move(from.x, from.y);
  await page.mouse.down();
  await page.mouse.move(from.x + 5, from.y + 5, { steps: 3 });
  const mid = { x: (from.x + to.x) / 2, y: (from.y + to.y) / 2 };
  await page.mouse.move(mid.x, mid.y, { steps });
  await page.mouse.move(to.x, to.y, { steps });
  await sleep(300);
  if (midShot) await midShot();
  await page.mouse.up();
}

export default async function ({ page, args }) {
  const tag = args[0] ?? 'light';
  const root = args[1];
  const f = await boardFrame(page);
  console.log('before:', JSON.stringify(await order(f)));
  // 1) re-order: drag "Toast test one" above the first assumption card
  const src = f.locator('[data-node-id]').filter({ hasText: 'Toast test one' });
  const target = f.locator('[data-node-id="pg-no-dark-past"]');
  const sb = await src.boundingBox();
  const tb = await target.boundingBox();
  await drag(page, { x: sb.x + 60, y: sb.y + 15 }, { x: tb.x + 60, y: tb.y + 8 }, { midShot: () => shot(page, `42-reorder-mid-${tag}`) });
  await sleep(1200);
  console.log('after reorder:', JSON.stringify(await order(f)));
  if (root) console.log('layout:', readFileSync(`${root}/.telelean/subjects/Spyro/layout.json`, 'utf8').replace(/\s+/g, ' '));
  await shot(page, `43-reorder-after-${tag}`);

  // 2) kind change by drag: "Cynder can breathe fire" -> Goals column
  const src2 = f.locator('[data-node-id="cynder-can-breathe-fire"]');
  const goals = f.locator('.tl-col__list[data-kind="GOAL"]');
  const s2 = await src2.boundingBox();
  const g = await goals.boundingBox();
  await drag(page, { x: s2.x + 60, y: s2.y + 15 }, { x: g.x + g.width / 2, y: g.y + g.height - 60 }, {
    midShot: async () => {
      await shot(page, `44-kind-drag-mid-${tag}`);
      console.log('dropzones:', JSON.stringify(await f.getByTestId('dropzone').evaluateAll((els) => els.map((e) => [e.dataset.kind, e.textContent]))));
    },
  });
  await sleep(1500);
  console.log('after kind drag:', JSON.stringify(await order(f)));
  await shot(page, `45-kind-drag-after-${tag}`);
