export async function boardFrame(page, timeoutMs = 30000, predicate = '.tl-app') {
  const deadline = Date.now() + timeoutMs;
  for (;;) {
    for (const frame of page.frames()) {
      if (frame.isDetached() || !frame.url().startsWith('vscode-webview://')) continue;
      try {
        if ((await frame.locator(predicate).count()) > 0) return frame;
      } catch {}
    }

