export async function boardFrame(page, timeoutMs = 30000, predicate = '.tl-app', rootName = undefined) {
  const deadline = Date.now() + timeoutMs;
  for (;;) {
    for (const frame of page.frames()) {
      if (frame.isDetached() || !frame.url().startsWith('vscode-webview://')) continue;
      try {
        if ((await frame.locator(predicate).count()) === 0) continue;
        if (rootName !== undefined) {
          const name = await frame.locator('.tl-toolbar__root').textContent({ timeout: 1000 }).catch(() => null);
          if (name !== rootName) continue;
        } else {
          const visible = await frame.evaluate(() => document.visibilityState).catch(() => 'hidden');
          if (visible !== 'visible') continue;
        }
        return frame;
      } catch {}
    }

