import { boardFrame, shot, sleep, waitFor, palette } from './lib.mjs';

export default async function ({ page, args }) {
  const tag = args[0] ?? 'light';
  for (const b of await page.locator('.notification-toast .codicon-notifications-clear, .notification-toast .codicon-close').all()) await b.click().catch(() => {});
  await page.keyboard.press('F1');
  const input = page.locator('.quick-input-widget input');
  await input.waitFor();
  await input.fill('>telelean: Open Board');
  await sleep(400);
  await page.keyboard.press('Enter');
  await sleep(800);
  console.log('QUICK PICK:', (await page.locator('.quick-input-widget').innerText()).replace(/\n+/g, ' | '));
  await shot(page, `80-root-pick-${tag}`);
  const t0 = Date.now();
  await page.locator('.quick-input-widget .monaco-list-row').filter({ hasText: 'big_model' }).first().click();
  const f = await boardFrame(page, 60000, '.tl-app', 'big_model');
  await waitFor(async () => (await f.locator('[data-node-id]').count()) > 100, 60000, 'cards');
  console.log('cards on screen after', Date.now() - t0, 'ms:', await f.locator('[data-node-id]').count());
  await shot(page, `81-big-initial-${tag}`);
  const badge = f.getByTestId('lean-badge');
  await waitFor(async () => ['fresh', 'failed'].includes(await badge.getAttribute('data-state')), 240000, 'lean', 500);
  console.log('lean settled after', Date.now() - t0, 'ms:', await badge.textContent());
  await sleep(1500);
  await shot(page, `82-big-fresh-${tag}`);
  const stats = await f.evaluate(() => ({
    cards: document.querySelectorAll('[data-node-id]').length,
    edges: document.querySelectorAll('path[data-edge-id]').length,
    stubs: document.querySelectorAll('path[data-edge-id][data-stub]').length,
    badges: [...document.querySelectorAll('.tl-col__badge-slot')].map((s) => s.textContent).join(' / '),
    counts: [...document.querySelectorAll('.tl-col__count')].map((s) => s.textContent).join(','),
  }));
  console.log('STATS:', JSON.stringify(stats));
  // scroll performance: scroll each column by steps and measure frame times
  const perf = await f.evaluate(async () => {
    const lists = [...document.querySelectorAll('.tl-col__list')];
    const results = [];
    for (const list of lists) {
      const frames = [];
      let last = performance.now();
      let running = true;
      const tick = (t) => {
        frames.push(t - last);
        last = t;
        if (running) requestAnimationFrame(tick);
      };
      requestAnimationFrame(tick);
      const max = list.scrollHeight - list.clientHeight;
      for (let i = 0; i <= 40; i++) {
        list.scrollTop = (max * i) / 40;
        await new Promise((r) => setTimeout(r, 25));
      }
      running = false;
      await new Promise((r) => setTimeout(r, 50));
      frames.sort((a, b) => a - b);
      const p = (q) => frames[Math.min(frames.length - 1, Math.floor(frames.length * q))];
      results.push({ kind: list.dataset.kind, scrollHeight: list.scrollHeight, frames: frames.length, median: p(0.5).toFixed(1), p95: p(0.95).toFixed(1), max: frames[frames.length - 1].toFixed(1) });
      list.scrollTop = max / 2;
    }
    return results;
  });
  console.log('SCROLL PERF:', JSON.stringify(perf));
  await sleep(500);
  await shot(page, `83-big-scrolled-${tag}`);
  // hover a derivation card
  const d = f.locator('[data-node-id="d-25"]');
  await d.scrollIntoViewIfNeeded();
  await d.hover();
  await sleep(500);
  await shot(page, `84-big-hover-${tag}`);
  // click rule-pq (hub with 50 outgoing arrows)
  const rule = f.locator('[data-node-id="rule-pq"]');
  await rule.scrollIntoViewIfNeeded();
  const tc = Date.now();
  await rule.click();
  await sleep(100);
  console.log('select hub took ~', Date.now() - tc, 'ms');
  await sleep(500);
  await shot(page, `85-big-hub-selected-${tag}`);
  console.log('badges now:', await f.evaluate(() => [...document.querySelectorAll('.tl-col__badge-slot')].map((s) => s.textContent).join(' / ')));
  await page.keyboard.press('Escape');
}

import { boardFrame, shot, sleep, waitFor } from './lib.mjs';

export default async function ({ page, args }) {
  const tag = args[0] ?? 'light';
  const f = await boardFrame(page, 30000, '.tl-app', 'big_model');
  const clear = f.getByRole('button', { name: 'Clear' });
  if (await clear.count()) await clear.click();
  const perf = await f.evaluate(async () => {
    const longTasks = [];
    let obs;
    try {
      obs = new PerformanceObserver((list) => list.getEntries().forEach((e) => longTasks.push(Math.round(e.duration))));
      obs.observe({ type: 'longtask', buffered: false });
    } catch {}
    const out = [];
    for (const list of document.querySelectorAll('.tl-col__list')) {
      list.scrollTop = 0;
      await new Promise((r) => requestAnimationFrame(() => requestAnimationFrame(r)));
      const max = list.scrollHeight - list.clientHeight;
      const steps = 90;
      const deltas = [];
      let last = performance.now();
      await new Promise((resolve) => {
        let i = 0;
        const step = (t) => {
          deltas.push(t - last);
          last = t;
          if (i > steps) return resolve();
          list.scrollTop = (max * i) / steps;
          i++;
          requestAnimationFrame(step);
        };
        requestAnimationFrame(step);
      });
      deltas.shift();
      const sorted = [...deltas].sort((a, b) => a - b);
      const p = (q) => sorted[Math.min(sorted.length - 1, Math.floor(sorted.length * q))];
      out.push({ kind: list.dataset.kind, steps: deltas.length, total: Math.round(deltas.reduce((a, b) => a + b, 0)), median: +p(0.5).toFixed(1), p95: +p(0.95).toFixed(1), max: +sorted[sorted.length - 1].toFixed(1) });
    }
    await new Promise((r) => setTimeout(r, 200));
    obs?.disconnect();
    return { out, longTasks };
  });
  console.log('RAF SCROLL:', JSON.stringify(perf));
  // vocabulary with 60 items
  await f.locator('.tl-vocab__toggle').click();
  await sleep(500);
  const list = f.locator('.tl-col__list[data-kind="ASSUMPTION"]');
  await list.evaluate((el) => (el.scrollTop = 0));
  await sleep(300);
  await shot(page, `86-big-vocab-${tag}`);
  const vocabHeight = await f.getByTestId('vocabulary').evaluate((el) => el.getBoundingClientRect().height);
  console.log('vocab height px:', Math.round(vocabHeight), 'column client height:', await list.evaluate((el) => el.clientHeight));
  await f.locator('.tl-vocab__toggle').click();
  await sleep(300);
  // drag in a big column: d-3 to the top of derivations
  const derivs = f.locator('.tl-col__list[data-kind="DERIVATION"]');
  await derivs.evaluate((el) => (el.scrollTop = 0));
  await sleep(300);
  const src = f.locator('[data-node-id="d-3"]');
  const dst = f.locator('[data-node-id="d-1"]');
  const sb = await src.boundingBox();
  const db = await dst.boundingBox();
  const t0 = Date.now();
  await page.mouse.move(sb.x + 60, sb.y + 12);
  await page.mouse.down();
  await page.mouse.move(sb.x + 65, sb.y + 17, { steps: 3 });
  await page.mouse.move(db.x + 60, db.y + 6, { steps: 20 });
  await sleep(200);
  await shot(page, `87-big-drag-mid-${tag}`);
  await page.mouse.up();
  await sleep(1500);
  console.log('drag took', Date.now() - t0, 'ms; order head:', JSON.stringify(await f.locator('.tl-col__list[data-kind="DERIVATION"] [data-node-id]').evaluateAll((els) => els.slice(0, 4).map((e) => e.dataset.nodeId))));
  // undo via the toolbar
  await f.locator('button[aria-label="Undo"].tl-icon-button--toolbar').click();
  await sleep(1500);
  console.log('after undo order head:', JSON.stringify(await f.locator('.tl-col__list[data-kind="DERIVATION"] [data-node-id]').evaluateAll((els) => els.slice(0, 4).map((e) => e.dataset.nodeId))));
}

