import { boardFrame, shot, sleep, waitFor } from './lib.mjs';
import { readFileSync } from 'node:fs';

export default async function ({ page, args }) {
  const root = args[0];
  let f = await boardFrame(page, 30000, '.tl-app', 'mental_model');
  for (const b of await f.locator('.tl-toast [aria-label="Dismiss"]').all()) await b.click().catch(() => {});
  const card = f.locator('[data-node-id="new-spyro-pg"]');
  if ((await card.locator('.tl-details').count()) === 0) await card.locator('.tl-card__chevron').click();
  await sleep(300);
  // 1) drag-select inside the code
  const code = card.locator('.tl-lean');
  await code.scrollIntoViewIfNeeded();
  const box = await code.boundingBox();
  await page.mouse.move(box.x + 8, box.y + 10);
  await page.mouse.down();
  await page.mouse.move(box.x + box.width * 0.6, box.y + box.height * 0.5, { steps: 10 });
  await page.mouse.move(box.x + box.width - 10, box.y + box.height - 8, { steps: 10 });
  console.log('card dragging during selection:', await card.getAttribute('data-dragging'));
  await page.mouse.up();
  await sleep(300);
  console.log('selected text:', JSON.stringify(await f.evaluate(() => window.getSelection()?.toString())));
  await shot(page, '93-code-selection-dark');
  // 2) Copy -> paste in an untitled editor
  const copyBtn = card.getByRole('button', { name: 'Copy the Lean code' });
  await copyBtn.click();
  await sleep(200);
  console.log('copy button text after click:', await copyBtn.innerText());
  await shot(page, '94-copied-dark');
  await page.keyboard.press('Control+n');
  await sleep(800);
  await page.keyboard.press('Control+v');
  await sleep(800);
  const pasted = await page.locator('.editor-instance .view-lines').first().innerText();
  console.log('pasted (from DOM):', JSON.stringify(pasted));
  await shot(page, '95-pasted-dark');
  // close the untitled editor without saving
  await page.keyboard.press('Control+w');
  await sleep(600);
  const dlg = page.locator('.monaco-dialog-box');
  if (await dlg.count()) {
    console.log('close dialog:', (await dlg.innerText()).replace(/\n+/g, ' | '));
    await dlg.getByRole('button', { name: /Don't Save/ }).click();
  }
  await sleep(500);
  await page.locator('.tabs-container .tab').filter({ hasText: 'telelean: mental_model' }).click();
  await sleep(800);
  f = await boardFrame(page, 30000, '.tl-app', 'mental_model');
  // 3) delete a comment-only card through the dialog
  const victim = f.locator('[data-node-id="cynder-can-breathe-fire"]');
  await victim.locator('.tl-card__chevron').click();
  await sleep(300);
  await victim.locator('.tl-details__actions').getByRole('button', { name: 'Delete' }).click();
  const d = f.getByTestId('dialog-delete');
  await d.waitFor();
  console.log('DELETE DIALOG:', (await d.innerText()).replace(/\n+/g, ' | '));
  await d.getByRole('button', { name: 'Delete card' }).click();
  await sleep(1500);
  console.log('victim present:', await victim.count());
  console.log('toasts:', await f.getByTestId('toast').allInnerTexts());
  console.log('inbox has block:', readFileSync(`${root}/Model/Spyro/Inbox.lean`, 'utf8').includes('id: cynder-can-breathe-fire'));
  await shot(page, '96-after-delete-dark');
}

