import { boardFrame, shot, sleep, waitFor, palette } from './lib.mjs';
import { writeFileSync, readFileSync } from 'node:fs';

export default async function ({ page, args }) {
  const folder = args[0];
  // close everything (blank restored boards included)
  await palette(page, 'View: Close All Editors');
  await sleep(1500);
  await palette(page, 'telelean: Open Board');
  await sleep(800);
  await page.locator('.quick-input-widget .monaco-list-row').filter({ hasText: 'empty_folder' }).first().click();
  let f = await boardFrame(page, 30000, '.tl-app', 'empty_folder');
  const badge = f.getByTestId('lean-badge');
  await waitFor(async () => (await badge.getAttribute('data-state')) === 'fresh', 120000, 'fresh', 500);
  console.log('badge:', await badge.textContent());
  // add one formalisable card first so the board has something
  const form = f.locator('form.tl-prompt');
  await form.getByLabel('New assumption').fill('Notes are useful');
  await form.getByLabel('New assumption').press('Enter');
  await sleep(1500);
  // toolchain change -> syntactic mode
  const tc = `${folder}/lean-toolchain`;
  const orig = readFileSync(tc, 'utf8');
  writeFileSync(tc, 'leanprover/lean4:v4.20.0\n');
  const t0 = Date.now();
  try {
    await waitFor(async () => (await badge.getAttribute('data-state')) === 'unsupported-toolchain', 30000, 'syntactic', 500);
    console.log('syntactic after', Date.now() - t0, 'ms; badge:', await badge.textContent());
  } catch (e) {
    console.log('no syntactic mode after 30 s; badge:', await badge.getAttribute('data-state'), await badge.textContent());
    await badge.click();
    await sleep(3000);
    console.log('after badge click:', await badge.getAttribute('data-state'), await badge.textContent());
  }
  await sleep(500);
  await shot(page, '103-syntactic-mode-dark');
  console.log('banner:', await f.getByTestId('lean-banner').innerText().catch(() => '(none)'));
  writeFileSync(tc, orig);
  await sleep(500);
  try {
    await waitFor(async () => (await badge.getAttribute('data-state')) === 'fresh', 60000, 'fresh again', 500);
    console.log('fresh again after toolchain restore');
  } catch {
    console.log('not fresh again automatically:', await badge.getAttribute('data-state'));
    await badge.click();
    await waitFor(async () => (await badge.getAttribute('data-state')) === 'fresh', 60000, 'fresh after click', 500);
    console.log('fresh after badge click');
  }
}

