import { boardFrame, shot, sleep, waitFor, palette } from './lib.mjs';

export default async function ({ page }) {
  await palette(page, 'telelean: Open Board');
  await sleep(800);
  await page.locator('.quick-input-widget .monaco-list-row').filter({ hasText: 'mental_model' }).first().click();
  const f = await boardFrame(page, 30000, '.tl-app', 'mental_model');
  await sleep(1500);
  console.log('subject:', await f.getByTestId('subject').textContent(), 'undo:', await f.locator('button[aria-label="Undo"].tl-icon-button--toolbar').getAttribute('title'));
  // Redo shortcuts: do an undoable edit (add a card), Ctrl+Z, then Ctrl+Shift+Z and Ctrl+Y
  const form = f.locator('form.tl-prompt');
  await form.getByLabel('New assumption').fill('Redo probe');
  await form.getByLabel('New assumption').press('Enter');
  await waitFor(async () => (await f.locator('[data-node-id]').filter({ hasText: 'Redo probe' }).count()) > 0 && (await f.locator('[data-provisional]').count()) === 0, 15000, 'added');
  await f.locator('[data-node-id]').filter({ hasText: 'Redo probe' }).focus();
  await page.keyboard.press('Control+z');
  await waitFor(async () => (await f.locator('[data-node-id]').filter({ hasText: 'Redo probe' }).count()) === 0, 15000, 'undone');
  console.log('Ctrl+Z: removed');
  await f.locator('.tl-toolbar__title').click();
  await page.keyboard.press('Control+Shift+z');
  await sleep(1500);
  console.log('Ctrl+Shift+Z: present =', (await f.locator('[data-node-id]').filter({ hasText: 'Redo probe' }).count()) > 0);
  await page.keyboard.press('Control+z');
  await sleep(1500);
  await page.keyboard.press('Control+y');
  await sleep(1500);
  console.log('Ctrl+Y: present =', (await f.locator('[data-node-id]').filter({ hasText: 'Redo probe' }).count()) > 0);
  // prune
  await f.getByTestId('history-button').click();
  const entries = f.getByTestId('history-entry');
  await waitFor(async () => (await entries.count()) > 0, 10000, 'entries');
  await sleep(600);
  const before = await f.getByTestId('history-storage').textContent();
  const n = await entries.count();
  await f.getByLabel('Keep the last N entries').fill('3');
  await f.getByRole('button', { name: 'Keep last' }).click();
  await sleep(2500);
  console.log('prune: entries', n, '->', await entries.count(), '| storage', before, '->', await f.getByTestId('history-storage').textContent());
  console.log('toasts:', await f.getByTestId('toast').allInnerTexts());
  await shot(page, '104-after-prune-dark');
  await page.keyboard.press('Escape');
}

