62	      vscode.workspace.onDidChangeTextDocument((event) => this.onTyping(event)),
63	      vscode.workspace.onDidSaveTextDocument((doc) => this.onSave(doc)),
64	    );
65	  }
66	
67	  /** The root's workspace, created and loaded on first use. Rejects when it cannot be created or loaded. */
68	  async get(root: string): Promise<ModelWorkspace> {
69	    const existing = this.entries.get(root);
70	    if (existing) return existing.workspace;
71	    let pending = this.loading.get(root);
72	    if (!pending) {
73	      pending = this.create(root).finally(() => this.loading.delete(root));
74	      this.loading.set(root, pending);
75	    }
76	    return (await pending).workspace;
77	  }
78	
79	  /** The root's workspace if it is already loaded. */
80	  peek(root: string): ModelWorkspace | undefined {
81	    return this.entries.get(root)?.workspace;
82	  }
83	
84	  roots(): string[] {
85	    return [...this.entries.keys()];
86	  }
87	
88	  /** Disposes one root's workspace (tests; a root that stopped being a model). */
89	  forget(root: string): void {
90	    const entry = this.entries.get(root);
91	    if (!entry) return;
92	    this.entries.delete(root);
93	    this.disposeEntry(entry);
94	  }
95	
96	  dispose(): void {
97	    for (const entry of this.entries.values()) this.disposeEntry(entry);
98	    this.entries.clear();
99	    for (const disposable of this.disposables.splice(0)) disposable.dispose();
100	  }
101	
102	  // ---------------------------------------------------------------------------------------------
103	
104	  private async create(root: string): Promise<Entry> {
105	    const name = path.basename(root);
106	    const log: Log = (level, message) => this.deps.log(level, `[${name}] ${message}`);
107	    const selfWrites = new SelfWrites();
108	    const settings = this.deps.settingsFor(root);
109	    const workspace = this.deps.runner().createModelWorkspace({
110	      root,
111	      text: vscodeTextSource(root),
112	      applier: vscodeEditApplier(root, log, (writes) => selfWrites.record(writes)),
113	      semantic: settings.semantic,
114	      git: settings.git,
115	      log,
116	      generatorVersion: this.deps.generatorVersion,
117	    });
118	    try {
119	      await workspace.load();
120	    } catch (error) {
121	      workspace.dispose();
122	      throw error;
123	    }
124	    const entry: Entry = {
125	      root,
126	      workspace,
127	      selfWrites,
128	      refreshPaths: new Set(),
129	      typing: new PathBatcher(TYPING_DEBOUNCE_MS, (paths) => this.invalidate(entry, paths, false)),
130	      files: new PathBatcher(FILE_EVENT_DEBOUNCE_MS, (paths) => {
131	        const refresh = paths.some((p) => entry.refreshPaths.delete(p));
132	        this.invalidate(entry, paths, refresh);
133	      }),
134	      disposables: [],
135	    };
136	    const watcher = vscode.workspace.createFileSystemWatcher(
137	      new vscode.RelativePattern(vscode.Uri.file(root), '{**/*.lean,.telelean/**,lakefile.toml,lean-toolchain,lake-manifest.json}'),
138	    );
