1	/**
2	 * Which model root and subject a board shows after a window reload (D-22: the board is an editor tab that restores).
3	 *
4	 * VS Code hands the WebviewPanelSerializer the panel (with its title) and whatever state the webview saved with
5	 * `setState`. The host cannot write that state itself, so it keeps its own record per window (the extension's
6	 * workspaceState): one entry per board with its title, root and subject, updated whenever the subject changes.
7	 * Restoring matches, in order: a root (and subject) the webview saved, if any; the recorded entry with the panel's
8	 * title; the only root whose folder name the title names; the only model root of the window.
9	 */
10	import * as path from 'node:path';
11	
12	/** What the host records for a board (and what a webview may save in its state). */
13	export interface BoardRecord {
14	  root: string;
15	  subject?: string;
16	  title: string;
17	}
18	
19	export const BOARD_TITLE_PREFIX = 'telelean: ';
20	
21	/** "telelean: <folder>", with the parent folder added when two model roots share a folder name. */
22	export function boardTitle(root: string, otherRoots: readonly string[] = []): string {
23	  const name = path.basename(root);
24	  const clash = otherRoots.some((other) => other !== root && path.basename(other) === name);
25	  return clash ? `${BOARD_TITLE_PREFIX}${name} (${path.basename(path.dirname(root))})` : `${BOARD_TITLE_PREFIX}${name}`;
26	}
27	
28	function stringField(value: unknown, key: string): string | undefined {
29	  if (typeof value !== 'object' || value === null) return undefined;
30	  const field = (value as Record<string, unknown>)[key];
31	  return typeof field === 'string' && field.length > 0 ? field : undefined;
32	}
33	
34	export interface RestoreInput {
35	  /** The webview's saved state (opaque; `root`/`subject` are used when present, also under a `telelean` key). */
36	  state: unknown;
37	  /** The restored panel's title. */
38	  title: string;
39	  /** Model roots known now (absolute paths). */
40	  roots: readonly string[];
41	  /** The host's records, newest first. */
42	  records: readonly BoardRecord[];
43	}
44	
45	export interface RestoreTarget {
46	  root: string;
47	  subject?: string;
48	}
49	
50	export function restoreTarget({ state, title, roots, records }: RestoreInput): RestoreTarget | undefined {
51	  const nested = typeof state === 'object' && state !== null ? (state as Record<string, unknown>)['telelean'] : undefined;
52	  for (const source of [state, nested]) {
53	    const root = stringField(source, 'root');
54	    if (root && (roots.includes(root) || records.some((r) => r.root === root))) {
55	      const subject = stringField(source, 'subject') ?? records.find((r) => r.root === root)?.subject;
56	      return subject ? { root, subject } : { root };
57	    }
58	  }
59	  const record = records.find((r) => r.title === title);
60	  if (record) return record.subject ? { root: record.root, subject: record.subject } : { root: record.root };
61	  if (title.startsWith(BOARD_TITLE_PREFIX)) {
62	    const named = roots.filter((root) => boardTitle(root, roots) === title || path.basename(root) === title.slice(BOARD_TITLE_PREFIX.length));
63	    if (named.length === 1 && named[0]) return withSubject(named[0], records);
64	  }
65	  if (roots.length === 1 && roots[0]) return withSubject(roots[0], records);
66	  return undefined;
67	}
68	
69	function withSubject(root: string, records: readonly BoardRecord[]): RestoreTarget {
70	  const subject = records.find((r) => r.root === root)?.subject;
71	  return subject ? { root, subject } : { root };
72	}
73	
74	/** The records after a board for `record.root` showed `record.subject` (newest first, one per root, at most 50). */
75	export function updateRecords(records: readonly BoardRecord[], record: BoardRecord): BoardRecord[] {
76	  return [record, ...records.filter((r) => r.root !== record.root)].slice(0, 50);
77	}
78	
79	/** Reads records saved by an older or newer extension leniently. */
80	export function parseRecords(value: unknown): BoardRecord[] {
81	  if (!Array.isArray(value)) return [];
82	  const out: BoardRecord[] = [];
83	  for (const entry of value) {
84	    const root = stringField(entry, 'root');
85	    const title = stringField(entry, 'title');
86	    if (!root || !title) continue;
87	    const subject = stringField(entry, 'subject');
88	    out.push(subject ? { root, title, subject } : { root, title });
89	  }
90	  return out;
91	}
