1	/**
2	 * The EditApplier behind every board write (docs/m1-plan.md section 2, "board to files"), without the vscode API:
3	 *
4	 *   1. check that each file's current text (open buffer first, via the TextSource) still equals the change's
5	 *      `before` (`null`: the file must not exist); otherwise refuse with ActionError `conflict`, applying nothing;
6	 *   2. turn the whole-file changes into one batch of operations: minimal line-based text edits for files that are
7	 *      changed (so open editors keep their cursors, folds and undo history outside the edited lines), create and
8	 *      delete for files that appear or disappear;
9	 *   3. apply the batch (the extension: one `vscode.WorkspaceEdit`) and refuse when VS Code refuses it;
10	 *   4. save every file that was edited in place, so the change is on disk when `apply` resolves (D-17 "edits are
11	 *      saved immediately"; this also saves unsaved typing in those files, risk R4).
12	 */
13	import { ActionError, type FileChange, type Position, type Range } from '@telelean/core';
14	import type { EditApplier, TextSource } from '@telelean/runner/workspace/index.js';
15	import { diffLines } from 'diff';
16	
17	import { OutsideRootError, resolveInsideRoot } from './modelPaths';
18	
19	/** Replace `before.slice(start, end)` with `text` (offsets into the text the edits were computed from). */
20	export interface TextReplacement {
21	  start: number;
22	  end: number;
23	  text: string;
24	}
25	
26	/** Beyond this, a whole-file replacement is cheaper than searching for a minimal diff. */
27	const DIFF_TIMEOUT_MS = 2000;
28	
29	/**
30	 * Line-granular edits that turn `before` into `after`: one replacement per changed run of lines, non-overlapping
31	 * and in order (what VS Code expects of the edits for one document). Empty when the texts are equal.
32	 */
33	export function minimalTextEdits(before: string, after: string): TextReplacement[] {
34	  if (before === after) return [];
35	  const parts = diffLines(before, after, { timeout: DIFF_TIMEOUT_MS });
36	  if (!parts) return [{ start: 0, end: before.length, text: after }];
37	  const edits: TextReplacement[] = [];
38	  let offset = 0;
39	  let open: TextReplacement | undefined; // the replacement being built at the current offset
40	  for (const part of parts) {
41	    if (part.added) {
42	      if (open && open.end === offset) open.text += part.value;
43	      else edits.push((open = { start: offset, end: offset, text: part.value }));
44	    } else if (part.removed) {
45	      if (open && open.end === offset) open.end += part.value.length;
46	      else edits.push((open = { start: offset, end: offset + part.value.length, text: '' }));
47	      offset += part.value.length;
48	    } else {
49	      offset += part.value.length;
50	      open = undefined;
51	    }
52	  }
53	  return edits;
54	}
55	
56	/** Applies replacements computed by `minimalTextEdits` (used by tests and to double-check a plan). */
57	export function applyTextReplacements(text: string, edits: readonly TextReplacement[]): string {
58	  let out = '';
59	  let cursor = 0;
60	  for (const edit of edits) {
61	    if (edit.start < cursor || edit.end < edit.start || edit.end > text.length) throw new RangeError('overlapping or out-of-range replacement');
62	    out += text.slice(cursor, edit.start) + edit.text;
63	    cursor = edit.end;
64	  }
65	  return out + text.slice(cursor);
66	}
67	
68	/** Offsets where lines start; `\r\n`, `\n` and a lone `\r` each end a line (as in VS Code's text model). */
69	export function lineStarts(text: string): number[] {
70	  const starts = [0];
71	  for (let i = 0; i < text.length; i++) {
72	    const c = text.charCodeAt(i);
73	    if (c === 13) {
74	      if (text.charCodeAt(i + 1) === 10) i++;
75	      starts.push(i + 1);
76	    } else if (c === 10) {
77	      starts.push(i + 1);
78	    }
79	  }
80	  return starts;
81	}
82	
83	/** The LSP position (0-based line, UTF-16 character) of an offset, given `lineStarts` of the same text. */
84	export function positionAt(starts: readonly number[], offset: number): Position {
85	  let low = 0;
86	  let high = starts.length - 1;
87	  while (low < high) {
88	    const mid = (low + high + 1) >> 1;
89	    if ((starts[mid] ?? 0) <= offset) low = mid;
90	    else high = mid - 1;
91	  }
92	  return { line: low, character: offset - (starts[low] ?? 0) };
93	}
94	
95	/** One step of the batch for one file. Paths: `path` relative POSIX (for messages), `absPath` for the editor. */
96	export type FileOperation =
97	  | { kind: 'create'; path: string; absPath: string; text: string }
98	  | { kind: 'delete'; path: string; absPath: string }
99	  | { kind: 'edit'; path: string; absPath: string; edits: Array<{ range: Range; text: string }> };
100	
101	/** The batch for `changes` (already checked); no-op changes produce nothing. */
102	export function planFileOperations(root: string, changes: readonly FileChange[]): FileOperation[] {
103	  const operations: FileOperation[] = [];
104	  for (const change of changes) {
105	    const absPath = resolveInsideRoot(root, change.path);
106	    if (change.before === change.after) continue;
107	    if (change.before === null && change.after !== null) {
108	      operations.push({ kind: 'create', path: change.path, absPath, text: change.after });
109	    } else if (change.before !== null && change.after === null) {
110	      operations.push({ kind: 'delete', path: change.path, absPath });
111	    } else if (change.before !== null && change.after !== null) {
112	      const starts = lineStarts(change.before);
113	      const edits = minimalTextEdits(change.before, change.after).map((edit) => ({
114	        range: { start: positionAt(starts, edit.start), end: positionAt(starts, edit.end) },
115	        text: edit.text,
116	      }));
117	      operations.push({ kind: 'edit', path: change.path, absPath, edits });
118	    }
119	  }
120	  return operations;
121	}
