1	/**
2	 * VS Code adapters for the runner's TextSource and EditApplier (the logic lives in ../logic/textSource.ts and
3	 * ../logic/editApplier.ts): open documents are read through `workspace.textDocuments`, writes go through one
4	 * `WorkspaceEdit` and `TextDocument.save`.
5	 */
6	import * as vscode from 'vscode';
7	
8	import type { TextSource } from '@telelean/runner/workspace/index.js';
9	
10	import { CheckedEditApplier, type FileOperation, type WorkspaceEditPort } from '../logic/editApplier';
11	import { createTextSource, readTextFile } from '../logic/textSource';
12	
13	/** The open (possibly unsaved) document for an absolute file path, if VS Code has one. */
14	export function openDocument(absPath: string): vscode.TextDocument | undefined {
15	  return vscode.workspace.textDocuments.find((doc) => doc.uri.scheme === 'file' && doc.uri.fsPath === absPath && !doc.isClosed);
16	}
17	
18	/** Reads model files the way the user sees them: an open editor buffer wins over the file on disk. */
19	export function vscodeTextSource(root: string): TextSource {
20	  return createTextSource(root, {
21	    openText: (absPath) => openDocument(absPath)?.getText(),
22	    readFile: readTextFile,
23	  });
24	}
25	
26	/** Applies a batch as one `WorkspaceEdit` (text edits for changed files, create/delete for the others). */
27	export class VscodeWorkspaceEditPort implements WorkspaceEditPort {
28	  async apply(operations: readonly FileOperation[], label: string): Promise<boolean> {
29	    const edit = new vscode.WorkspaceEdit();
30	    for (const operation of operations) {
31	      const uri = vscode.Uri.file(operation.absPath);
32	      switch (operation.kind) {
33	        case 'create':
34	          edit.createFile(uri, { overwrite: false, contents: new TextEncoder().encode(operation.text) });
35	          break;
36	        case 'delete':
37	          edit.deleteFile(uri, { ignoreIfNotExists: false });
38	          break;
39	        case 'edit':
40	          for (const { range, text } of operation.edits) {
41	            edit.replace(uri, new vscode.Range(range.start.line, range.start.character, range.end.line, range.end.character), text);
42	          }
43	          break;
44	      }
45	    }
46	    void label;
47	    return vscode.workspace.applyEdit(edit, { isRefactoring: false });
48	  }
49	
50	  async save(absPath: string): Promise<boolean> {
51	    const doc = openDocument(absPath) ?? (await vscode.workspace.openTextDocument(vscode.Uri.file(absPath)));
52	    if (!doc.isDirty) return true;
53	    return doc.save();
54	  }
55	}
56	
57	/** The EditApplier for one model root (Initialize uses it before the root has a workspace). */
58	export function vscodeEditApplier(
59	  root: string,
60	  log: (level: 'info' | 'warn' | 'error', message: string) => void,
61	  onWillWrite?: (writes: ReadonlyArray<{ absPath: string; text: string | null }>) => void,
62	): CheckedEditApplier {
63	  return new CheckedEditApplier({
64	    root,
65	    text: vscodeTextSource(root),
66	    port: new VscodeWorkspaceEditPort(),
67	    log,
68	    ...(onWillWrite ? { onWillWrite } : {}),
69	  });
70	}
