1	/**
2	 * The read-only `telelean-history:` documents behind a history preview, shown with VS Code's multi-file diff editor
3	 * (`vscode.changes`). Documents of a content provider cannot be edited or saved, so a preview never writes anything.
4	 */
5	import * as path from 'node:path';
6	import * as vscode from 'vscode';
7	
8	import type { HistoryDiff } from '@telelean/core';
9	
10	import { EXPIRED_PREVIEW_TEXT, HISTORY_SCHEME, previewRows, previewTitle, PreviewStore, type PreviewDocument } from '../logic/historyPreview';
11	
12	export class HistoryPreviews implements vscode.TextDocumentContentProvider, vscode.Disposable {
13	  private readonly store = new PreviewStore();
14	  private readonly registration: vscode.Disposable;
15	  private counter = 0;
16	
17	  constructor() {
18	    this.registration = vscode.workspace.registerTextDocumentContentProvider(HISTORY_SCHEME, this);
19	  }
20	
21	  provideTextDocumentContent(uri: vscode.Uri): string {
22	    return this.store.get(uri.path, uri.query) ?? EXPIRED_PREVIEW_TEXT;
23	  }
24	
25	  /** Opens the diff of one history entry; resolves with the title of the diff editor. */
26	  async show(diff: HistoryDiff, root: string): Promise<string> {
27	    const id = `${Date.now().toString(36)}${++this.counter}`;
28	    const rows = previewRows(diff, id);
29	    this.store.add(id, rows);
30	    const uri = (doc: PreviewDocument) => vscode.Uri.from({ scheme: HISTORY_SCHEME, path: `/${doc.path}`, query: doc.key });
31	    const resources = rows.map((row) => [
32	      vscode.Uri.file(path.join(root, ...row.path.split('/'))),
33	      row.left ? uri(row.left) : undefined,
34	      row.right ? uri(row.right) : undefined,
35	    ]);
36	    const title = previewTitle(diff);
37	    await vscode.commands.executeCommand('vscode.changes', title, resources);
38	    return title;
39	  }
40	
41	  dispose(): void {
42	    this.registration.dispose();
43	  }
44	}
