1	/**
2	 * The read-only preview of a history entry (D-33, docs/m1-plan.md section 8 "Preview"): the runner's HistoryDiff
3	 * becomes VS Code's multi-file diff (`vscode.changes`) over documents served by a `telelean-history:` content
4	 * provider. This module holds the vscode-free part: titles, the documents' identities and a bounded store.
5	 */
6	import type { HistoryDiff } from '@telelean/core';
