8	export const HISTORY_SCHEME = 'telelean-history';
9	
10	/** One side of one file in a preview: `key` identifies the document (its URI query), `path` names the file. */
11	export interface PreviewDocument {
12	  key: string;
13	  path: string;
14	  text: string;
