28	/** `2026-11-01 14:05` in local time (the ISO text itself when it does not parse). */
29	export function formatEntryTime(iso: string): string {
30	  const date = new Date(iso);
31	  if (Number.isNaN(date.getTime())) return iso;
32	  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())} ${pad(date.getHours())}:${pad(date.getMinutes())}`;
