40	/**
41	 * The rows of a preview. `compare: 'parent'` shows what the entry changed (parent on the left, entry on the right);
42	 * `compare: 'current'` shows how the files now differ from the entry (entry on the left, current on the right): the
43	 * runner's FileChange `before`/`after` already follow that order.
44	 */
45	export function previewRows(diff: HistoryDiff, previewId: string): PreviewRow[] {
46	  return diff.files.map((file) => {
47	    const side = (name: 'before' | 'after', text: string | null): PreviewDocument | undefined =>
48	      text === null ? undefined : { key: `preview=${previewId}&side=${name}&entry=${diff.entry.id}`, path: file.path, text };
49	    const left = side('before', file.before);
50	    const right = side('after', file.after);
51	    return { path: file.path, ...(left ? { left } : {}), ...(right ? { right } : {}) };
52	  });
53	}
