55	/** Documents of the last few previews (older ones are dropped; reopening shows a placeholder). */
56	export class PreviewStore {
57	  private readonly previews: Array<{ id: string; keys: string[] }> = [];
58	  private readonly texts = new Map<string, string>();
59	
60	  constructor(private readonly keepPreviews = 10) {}
61	
62	  add(id: string, rows: readonly PreviewRow[]): void {
63	    const keys: string[] = [];
64	    for (const row of rows) {
65	      for (const doc of [row.left, row.right]) {
66	        if (!doc) continue;
67	        this.texts.set(this.documentKey(doc.path, doc.key), doc.text);
68	        keys.push(this.documentKey(doc.path, doc.key));
69	      }
70	    }
71	    this.previews.push({ id, keys });
72	    while (this.previews.length > this.keepPreviews) {
73	      for (const key of this.previews.shift()?.keys ?? []) this.texts.delete(key);
74	    }
75	  }
76	
77	  /** The text of a preview document by its URI path (`/<file>`) and query. */
78	  get(uriPath: string, query: string): string | undefined {
79	    return this.texts.get(this.documentKey(uriPath.replace(/^\/+/, ''), query));
80	  }
81	
82	  private documentKey(path: string, query: string): string {
83	    return `${query}\u0000${path}`;
84	  }
85	}
