1	/**
2	 * Helpers for the extension's file watchers (docs/m1-plan.md section 2, "refresh triggers"): typing is batched per
3	 * model root (one `invalidate` after ~200 ms of quiet), and the echoes of telelean's own writes (the change, save and
4	 * file-system events its EditApplier causes) are recognised, since the workspace already knows those texts.
5	 */
6	
7	/** Collects paths and calls `flush` once, `delayMs` after the last `add` (a trailing debounce). */
8	export class PathBatcher {
9	  private readonly pending = new Set<string>();
10	  private timer: ReturnType<typeof setTimeout> | undefined;
11	
12	  constructor(
13	    private readonly delayMs: number,
14	    private readonly onFlush: (paths: string[]) => void,
15	  ) {}
16	
17	  add(paths: Iterable<string>): void {
18	    for (const path of paths) this.pending.add(path);
19	    if (this.pending.size === 0) return;
20	    if (this.timer !== undefined) clearTimeout(this.timer);
21	    this.timer = setTimeout(() => this.flush(), this.delayMs);
22	  }
23	
24	  /** Delivers what is pending now (e.g. before a save is handled, so the order of events is kept). */
25	  flush(): void {
26	    if (this.timer !== undefined) clearTimeout(this.timer);
27	    this.timer = undefined;
28	    if (this.pending.size === 0) return;
29	    const paths = [...this.pending].sort();
30	    this.pending.clear();
31	    this.onFlush(paths);
32	  }
33	
34	  /** Drops `paths` from the pending set (they are being handled another way). */
35	  drop(paths: Iterable<string>): void {
36	    for (const path of paths) this.pending.delete(path);
37	  }
38	
39	  get size(): number {
40	    return this.pending.size;
41	  }
42	
43	  dispose(): void {
44	    if (this.timer !== undefined) clearTimeout(this.timer);
45	    this.timer = undefined;
46	    this.pending.clear();
47	  }
48	}
49	
50	/**
51	 * The files telelean just wrote, with their new text (null = deleted), for a few seconds. An event whose text equals
52	 * the recorded one is an echo of telelean's own write. The first event with any other text (the user typed) forgets
53	 * the record, so a later return to the same text is not mistaken for an echo.
54	 */
55	export class SelfWrites {
56	  private readonly entries = new Map<string, { text: string | null; until: number }>();
57	
58	  constructor(
59	    private readonly ttlMs = 5000,
60	    private readonly now: () => number = Date.now,
61	  ) {}
62	
63	  record(writes: ReadonlyArray<{ absPath: string; text: string | null }>): void {
64	    const until = this.now() + this.ttlMs;
65	    for (const write of writes) this.entries.set(write.absPath, { text: write.text, until });
66	  }
67	
68	  isEcho(absPath: string, text: string | null): boolean {
69	    const entry = this.entries.get(absPath);
70	    if (!entry) return false;
71	    if (entry.until < this.now() || entry.text !== text) {
72	      this.entries.delete(absPath);
73	      return false;
74	    }
75	    return true;
76	  }
77	
78	  /** Whether a write to `absPath` is recorded and fresh (for events that carry no text). */
79	  has(absPath: string): boolean {
80	    const entry = this.entries.get(absPath);
81	    if (entry && entry.until < this.now()) this.entries.delete(absPath);
82	    return this.entries.has(absPath);
83	  }
84	}
