1	/**
2	 * Paths inside a model root: the checks behind "Open in editor" (the webview's path is untrusted), the TextSource and
3	 * the EditApplier (the runner's paths are relative POSIX), and which file events matter to a workspace.
4	 * Pure apart from the optional `realpath` probe.
5	 */
6	import { realpath as fsRealpath } from 'node:fs/promises';
7	import * as path from 'node:path';
8	
9	/** Thrown when a path would leave the model root (or is not a plain relative POSIX path). */
10	export class OutsideRootError extends Error {
11	  constructor(
12	    readonly file: string,
13	    reason: string,
14	  ) {
15	    super(`refused "${file}": ${reason}`);
16	    this.name = 'OutsideRootError';
17	  }
18	}
19	
20	/** True when `absPath` lies strictly inside `root` (the root itself is not inside). */
21	export function isInside(root: string, absPath: string): boolean {
22	  const rel = path.relative(root, absPath);
23	  return rel !== '' && rel !== '..' && !rel.startsWith(`..${path.sep}`) && !path.isAbsolute(rel);
24	}
25	
26	/** `absPath` relative to `root` as a POSIX path, or undefined when it is not inside the root. */
27	export function relativeModelPath(root: string, absPath: string): string | undefined {
28	  if (!isInside(root, absPath)) return undefined;
29	  return path.relative(root, absPath).split(path.sep).join('/');
30	}
31	
32	/**
33	 * The absolute path of a model file given as a POSIX path relative to the root. Refuses absolute paths, backslashes,
34	 * NUL, and empty, `.` or `..` segments (the protocol already refuses them; the host checks again), and anything that
35	 * would resolve outside the root.
36	 */
37	export function resolveInsideRoot(root: string, file: string): string {
38	  if (file.length === 0) throw new OutsideRootError(file, 'empty path');
39	  if (file.startsWith('/') || /[\\\0]/.test(file)) throw new OutsideRootError(file, 'not a relative POSIX path');
40	  const segments = file.split('/');
41	  if (segments.some((s) => s === '' || s === '.' || s === '..')) throw new OutsideRootError(file, 'empty, "." or ".." segment');
42	  const absPath = path.join(root, ...segments);
43	  if (!isInside(root, absPath)) throw new OutsideRootError(file, 'outside the model root');
44	  return absPath;
45	}
46	
47	/**
48	 * Like `resolveInsideRoot`, and when the file exists also checks its real path (symbolic links resolved) against the
49	 * root's real path, so a link inside the model folder cannot open a file elsewhere.
50	 */
51	export async function resolveModelFile(root: string, file: string, realpath: (p: string) => Promise<string> = fsRealpath): Promise<string> {
52	  const absPath = resolveInsideRoot(root, file);
53	  let real: string;
54	  try {
55	    real = await realpath(absPath);
56	  } catch {
57	    return absPath; // does not exist (yet): nothing to follow
58	  }
59	  const realRoot = await realpath(root).catch(() => root);
60	  if (!isInside(realRoot, real)) throw new OutsideRootError(file, 'links outside the model root');
61	  return absPath;
62	}
63	
64	/** The innermost root that contains `absPath`, if any. */
65	export function rootOfPath(roots: Iterable<string>, absPath: string): string | undefined {
66	  let best: string | undefined;
67	  for (const root of roots) {
68	    if (isInside(root, absPath) && (best === undefined || root.length > best.length)) best = root;
69	  }
70	  return best;
71	}
72	
73	/** What a changed file means for a model workspace. */
74	export interface ModelPathEvent {
75	  /** POSIX path relative to the root. */
76	  path: string;
77	  /** `model`: a Lean file; `sidecar`: under `.telelean/`; `project`: lakefile.toml/.lean, lean-toolchain, lake-manifest.json. */
78	  kind: 'model' | 'sidecar' | 'project';
79	  /** A Lean refresh is due even without a save (the project's build setup changed). */
80	  refresh: boolean;
81	}
82	
83	/** Directories inside a root whose files never concern the board. */
84	const IGNORED_DIRS = new Set(['.lake', '.git', 'node_modules']);
85	/**
86	 * Gitignored telelean outputs: writing them must not trigger anything (graph.json is rewritten after each refresh;
87	 * `.telelean/*.tmp` are the temp files of atomic writes).
88	 */
89	const IGNORED_SIDECARS = ['.telelean/graph.json', '.telelean/frozen/', '.telelean/sessions/'];
90	const PROJECT_FILES = new Set(['lakefile.toml', 'lakefile.lean', 'lean-toolchain', 'lake-manifest.json']);
91	
92	/**
93	 * Classifies a file event under `root`: undefined for files outside the root and for files that never concern the
94	 * board (`.lake/`, `.git/`, `.telelean/graph.json`, non-Lean files, ...).
95	 */
96	export function classifyModelPath(root: string, absPath: string): ModelPathEvent | undefined {
97	  const rel = relativeModelPath(root, absPath);
98	  if (rel === undefined) return undefined;
99	  const segments = rel.split('/');
100	  if (segments.some((s) => IGNORED_DIRS.has(s))) return undefined;
101	  if (rel.startsWith('.telelean/')) {
102	    if (IGNORED_SIDECARS.some((ignored) => (ignored.endsWith('/') ? rel.startsWith(ignored) : rel === ignored))) return undefined;
103	    if (segments.length === 2 && rel.endsWith('.tmp')) return undefined;
104	    return { path: rel, kind: 'sidecar', refresh: false };
105	  }
106	  if (PROJECT_FILES.has(rel)) return { path: rel, kind: 'project', refresh: true };
107	  if (rel.endsWith('.lean')) return { path: rel, kind: 'model', refresh: false };
108	  return undefined;
109	}
