  }

  setEdges(edges: readonly EdgeSpec[]): void {
    this.edges = edges;
    this.schedule();
  }

  setFocus(ids: ReadonlySet<string>): void {
    this.focus = ids;
    this.schedule();
  }

  invalidateLayout(): void {
    this.layoutDirty = true;
    this.schedule();
  }

  /** Called after each frame (diagnostics and tests). */
