/** A text source over a map, and an editor port that applies operations to the same map. */
function fakeEditor(files: Record<string, string>) {
  const texts = new Map(Object.entries(files));
  const text: TextSource = { read: async (path) => texts.get(path) ?? null };
  const applied: FileOperation[][] = [];
  const saved: string[] = [];
  let refuse = false;
  let failSave = false;
  const port: WorkspaceEditPort = {
    async apply(operations) {
      if (refuse) return false;
      applied.push([...operations]);
      for (const op of operations) {
        if (op.kind === 'create') texts.set(op.path, op.text);
        else if (op.kind === 'delete') texts.delete(op.path);
        else texts.set(op.path, applyRanges(texts.get(op.path) ?? '', op.edits));
      }
      return true;
    },
    async save(absPath) {
      saved.push(absPath);
      return !failSave;
    },
  };
  return {
    texts,
    text,
    port,
    applied,
    saved,
    refuseNext: () => {
      refuse = true;
    },
    failSaves: () => {
      failSave = true;
    },
  };
}

