async show(diff: HistoryDiff, root: string): Promise<string> {
  const id = `${Date.now().toString(36)}${++this.counter}`;
  const rows = previewRows(diff, id);
  this.store.add(id, rows);
  const uri = (doc: PreviewDocument) => vscode.Uri.from({ scheme: HISTORY_SCHEME, path: `/${doc.path}`, query: doc.key });
  const resources = rows.map((row) => [
    vscode.Uri.file(path.join(root, ...row.path.split('/'))),
    row.left ? uri(row.left) : undefined,
    row.right ? uri(row.right) : undefined,
  ]);
  const title = previewTitle(diff);
  await vscode.commands.executeCommand('vscode.changes', title, resources);
  return title;
}

