export function semanticBadge(summary: SemanticSummary): { text: string; title: string; tone: BadgeTone } {
  const detail = summary.detail ? ` ${summary.detail}` : '';
  const refresh = ' Click to check again.';
  switch (summary.state) {
    case 'unavailable':
      return { text: 'Lean: not checked yet', title: `Lean has not checked these files yet.${detail}${refresh}`, tone: 'off' };
    case 'checking':
      return { text: 'Lean: checking…', title: `Building and checking the model with Lean.${detail}`, tone: 'busy' };
    case 'fresh':
      return { text: 'Lean: up to date', title: `Lean checked every file on this board${summary.checkedAt ? ` (${summary.checkedAt})` : ''}.${refresh}`, tone: 'ok' };
    case 'stale': {
      const files = summary.staleFiles?.length ? ` Changed: ${summary.staleFiles.join(', ')}.` : '';
      return { text: 'Lean: files changed', title: `Some files changed since Lean last checked them; their cards show the last known status.${files}${refresh}`, tone: 'warn' };
    }
    case 'failed': {
      const n = summary.errorCount ?? 0;
      const text = n > 0 ? `Lean: ${n} error${n === 1 ? '' : 's'}` : 'Lean: check failed';
      return { text, title: `${n > 0 ? 'The build reported errors (see Problems).' : 'The last Lean check did not complete.'}${detail}${refresh}`, tone: 'error' };
    }
    case 'paused-low-memory':
      return { text: 'Lean paused: low memory', title: `Lean checks are paused while little memory is available.${detail}${refresh}`, tone: 'warn' };
    case 'unsupported-toolchain':
      return { text: 'Lean: syntactic mode', title: `This project is not on the toolchain telelean checks with, so cards are read from the files only.${detail}`, tone: 'off' };
    case 'disabled':
      return { text: 'Lean: off', title: `Lean checking is off.${detail}${refresh}`, tone: 'off' };
  }
}

