// Independent check of SelfWrites (closing verifier): the real classes, old (pre-fix copy) and new.
import { SelfWrites as NewSW } from './newChangeBatcher';
import { SelfWrites as OldSW } from './oldChangeBatcher';

type SW = { record(w: { absPath: string; text: string | null }[]): void; isEcho(p: string, t: string | null, s?: 'editor' | 'disk'): boolean; has(p: string, s?: 'editor' | 'disk'): boolean };
const P = '/m/Model/Spyro/Inbox.lean';
let clock = 1000;
const now = () => clock;
function run(name: string, make: () => SW) {
  const out: Record<string, unknown> = {};
  // 1. The verifier's race: telelean writes T1 (action) then T0 (its Undo) before the first disk event is handled.
  {
    const sw = make();
    sw.record([{ absPath: P, text: 'T1' }]);
    sw.record([{ absPath: P, text: 'T0' }]);
    out.race_lateDiskT1 = sw.has(P, 'disk') && sw.isEcho(P, 'T1', 'disk');
    out.race_nextDiskT0 = sw.has(P, 'disk') && sw.isEcho(P, 'T0', 'disk');
  }
  // 2. Editor Undo protection: telelean writes T1, then T0; the editor saw both; the user's Ctrl+Z goes back to T1.
  {
    const sw = make();
    sw.record([{ absPath: P, text: 'T1' }]);
    const e1 = sw.isEcho(P, 'T1', 'editor');
    sw.record([{ absPath: P, text: 'T0' }]);
    const e2 = sw.isEcho(P, 'T0', 'editor');
    out.undoProtect_echoes = [e1, e2];
    out.undoProtect_userCtrlZ_isEcho = sw.isEcho(P, 'T1', 'editor'); // must be false
  }
  // 3. Duplicate events for one write (change + save, or two watcher events): both echoes.
  {
    const sw = make();
    sw.record([{ absPath: P, text: 'T1' }]);
    out.dup = [sw.isEcho(P, 'T1', 'editor'), sw.isEcho(P, 'T1', 'editor'), sw.isEcho(P, 'T1', 'disk'), sw.isEcho(P, 'T1', 'disk')];
  }
  // 4. Another program writes X after telelean's T1 was seen on disk: X is not an echo; a later T1 is not either.
  {
    const sw = make();
    sw.record([{ absPath: P, text: 'T1' }]);
    const a = sw.isEcho(P, 'T1', 'disk');
    const b = sw.isEcho(P, 'X', 'disk');
    const c = sw.isEcho(P, 'T1', 'disk');
    out.outside = [a, b, c]; // expect [true,false,false]
  }
  // 5. Streams are independent: the disk lags behind the editor (editor saw T1,T0; disk then reads T1,T0).
  {
    const sw = make();
    sw.record([{ absPath: P, text: 'T1' }]);
    sw.record([{ absPath: P, text: 'T0' }]);
    out.streams = [sw.isEcho(P, 'T1', 'editor'), sw.isEcho(P, 'T0', 'editor'), sw.isEcho(P, 'T1', 'disk'), sw.isEcho(P, 'T0', 'disk')];
  }
  // 6. TTL: an event 5.1 s later is not an echo.
  {
    clock = 1000;
    const sw = make();
    sw.record([{ absPath: P, text: 'T1' }]);
    clock = 6100;
    out.ttlExpired_isEcho = sw.isEcho(P, 'T1', 'disk');
    out.ttlExpired_has = sw.has(P, 'disk');
    clock = 1000;
  }
  // 7. Deletion (null text) then re-creation.
  {
    const sw = make();
    sw.record([{ absPath: P, text: null }]);
    sw.record([{ absPath: P, text: 'T0' }]);
    out.deleteRecreate = [sw.isEcho(P, null, 'disk'), sw.isEcho(P, 'T0', 'disk')];
  }
  // 8. Action, Undo, Redo (A, B, A): events in order are all echoes; an out-of-order late A after B is also accepted.
  {
    const sw = make();
    sw.record([{ absPath: P, text: 'A' }]);
    sw.record([{ absPath: P, text: 'B' }]);
    sw.record([{ absPath: P, text: 'A' }]);
    out.aba = [sw.isEcho(P, 'A', 'disk'), sw.isEcho(P, 'B', 'disk'), sw.isEcho(P, 'A', 'disk')];
  }
  console.log(name, JSON.stringify(out));
}
run('NEW', () => new NewSW(5000, now) as unknown as SW);
run('OLD', () => new OldSW(5000, now) as unknown as SW);
