// Closing verifier's real-VS-Code checks (isolated VS Code 1.140 test build over CDP on 127.0.0.1 only).
// Workspace: a copy of mental_model plus d-cond / g-cond / d-cond2 / cynder-popular cards (Main.lean) and two
// untracked lemmas in Model/Spyro/Extra.lean (helper_lemma uses cynder_dark_past.holds; helper_cond passes
// arguments to d_cond2.holds).
// Scenarios: B Cancel in the second delete form; B2 Enter on the focused Cancel; C "Delete card only, keep Lean"
// from the second form + Undo; A "Delete anyway" + Undo; D D->A on d-cond (board-impact dialog) + Undo;
// E D->A on d-cond2 (only the host asks) + Undo.
import { chromium } from '/tmp/claude-1002/-home-zhengyew-telelean/03a29d54-7342-40e3-b5f0-2697a62c93ef/scratchpad/turn9/closing-verifier-r1/repo/node_modules/playwright-core/index.mjs';
import { readFileSync, readdirSync, statSync, existsSync, writeFileSync } from 'node:fs';
import { join, relative } from 'node:path';

const [port, model, shots, outJson] = process.argv.slice(2);
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const t0 = Date.now();
const log = (...a) => console.log(`${((Date.now() - t0) / 1000).toFixed(1).padStart(6)}s`, ...a);
const results = [];
const record = {};
const check = (name, ok, detail) => {
  results.push({ name, ok: !!ok, detail });
  log(`${ok ? 'PASS' : 'FAIL'} ${name}${detail !== undefined ? ' -- ' + (typeof detail === 'string' ? detail : JSON.stringify(detail)) : ''}`);
};

// ---------------------------------------------------------------------------------------------- files
function walk(dir, out = []) {
  for (const e of readdirSync(dir, { withFileTypes: true })) {
    const p = join(dir, e.name);
    if (e.isDirectory()) {
      if (['.lake', '.git'].includes(e.name)) continue;
      walk(p, out);
    } else out.push(p);
  }
  return out;
}
function snapshot() {
  const snap = {};
  for (const p of walk(model)) {
    const rel = relative(model, p);
    if (rel === '.telelean/graph.json' || rel.endsWith('.tmp')) continue;
    snap[rel] = readFileSync(p, 'utf8');
  }
  return snap;
}
function diffSnap(a, b) {
  const keys = new Set([...Object.keys(a), ...Object.keys(b)]);
  return [...keys].filter((k) => a[k] !== b[k]).sort();
}
const readRel = (rel) => readFileSync(join(model, rel), 'utf8');
async function waitFor(cond, ms, label, every = 200) {
  const end = Date.now() + ms;
  for (;;) {
    try { if (await cond()) return true; } catch {}
    if (Date.now() > end) { log(`timeout: ${label}`); return false; }
    await sleep(every);
  }
}
/** Waits until the snapshot stops changing for `quietMs`. */
async function settledSnapshot(quietMs = 1500, maxMs = 20000) {
  let last = JSON.stringify(snapshot());
  let since = Date.now();
  const end = Date.now() + maxMs;
  while (Date.now() < end) {
    await sleep(250);
    const now = JSON.stringify(snapshot());
    if (now !== last) { last = now; since = Date.now(); }
    else if (Date.now() - since >= quietMs) break;
  }
  return JSON.parse(last);
}

// ---------------------------------------------------------------------------------------------- VS Code
async function connect(timeoutMs = 90000) {
  const deadline = Date.now() + timeoutMs;
  for (;;) {
    try {
      const browser = await chromium.connectOverCDP(`http://127.0.0.1:${port}`);
      for (;;) {
        const page = browser.contexts().flatMap((c) => c.pages()).find((p) => p.url().includes('workbench.html'));
        if (page) return { browser, page };
        if (Date.now() > deadline) throw new Error('no workbench page');
        await sleep(250);
      }
    } catch (e) {
      if (Date.now() > deadline) throw e;
      await sleep(500);
    }
  }
}
const { browser, page } = await connect();
await page.locator('.monaco-workbench').waitFor({ timeout: 60000 });
async function clearNotifications() {
  const n = await page.evaluate(() => {
    let k = 0;
    for (const b of document.querySelectorAll('.notifications-toasts .notification-toast .action-label')) {
      if (/Clear/i.test((b.getAttribute('aria-label') || '') + (b.title || ''))) { b.click(); k++; }
    }
    return k;
  }).catch(() => -1);
  if (n > 0) log(`cleared ${n} VS Code notification(s)`);
}
async function palette(command) {
  await page.keyboard.press('F1');
  const input = page.locator('.quick-input-widget:visible input');
  await input.waitFor({ timeout: 15000 });
  await input.fill(`>${command}`);
  await sleep(700);
  await page.keyboard.press('Enter');
}
async function boardFrame(timeoutMs = 60000) {
  const end = Date.now() + timeoutMs;
  for (;;) {
    for (const frame of page.frames()) {
      if (frame.isDetached() || !frame.url().startsWith('vscode-webview://')) continue;
      try {
        const ok = await frame.evaluate(() => !!document.querySelector('.tl-app') && document.querySelectorAll('[data-node-id]').length >= 4);
        if (ok) return frame;
      } catch {}
    }
    if (Date.now() > end) return null;
    await sleep(250);
  }
}

await sleep(6000); // VS Code raises its sticky "extensions are temporarily disabled" toast a few seconds after start
await clearNotifications();
await palette('telelean: Open Board');
let f = await boardFrame();
check('board renders', !!f);
if (!f) process.exit(1);

const badge = () => f.getByTestId('lean-badge').textContent().catch(() => '?');
async function waitUpToDate(label, ms = 180000) {
  const ok = await waitFor(async () => (await badge()) === 'Lean: up to date', ms, label, 500);
  log(`badge (${label}): ${await badge()}`);
  return ok;
}
const card = (id) => f.locator(`[data-node-id="${id}"]`);
async function expand(id) {
  const chev = card(id).locator('.tl-card__chevron');
  if ((await chev.getAttribute('aria-expanded')) !== 'true') await chev.click();
  await card(id).locator('.tl-details').waitFor({ timeout: 10000 });
}
async function toastTexts() {
  return f.getByTestId('toast').evaluateAll((els) => els.map((e) => (e.textContent ?? '').replace(/\s+/g, ' ').trim()));
}
async function openDialogs() {
  return f.locator('[data-testid^="dialog-"]').evaluateAll((els) => els.map((e) => e.getAttribute('data-testid')));
}
async function dismissToasts() {
  // Board toasts time out by themselves; wait until none is left so each scenario starts clean.
  await waitFor(async () => (await f.getByTestId('toast').count()) === 0, 20000, 'board toasts gone', 500);
}
const undoBtn = () => f.locator('button.tl-icon-button--toolbar[aria-label="Undo"]');
async function cardInfo(id) {
  const c = card(id);
  if ((await c.count()) === 0) return null;
  return (await c.first().innerText()).replace(/\s+/g, ' ').trim().slice(0, 240);
}

const upToDate0 = await waitUpToDate('initial build');
check('initial Lean build of the scenario model is up to date', upToDate0);
const S0 = snapshot();
record.initialCards = {};
for (const id of ['cynder-dark-past', 'd-cond', 'g-cond', 'd-cond2', 'cynder-popular', 'cynder-not-good']) record.initialCards[id] = await cardInfo(id);
log('initial cards:', JSON.stringify(record.initialCards));
check('d-cond, g-cond and d-cond2 are conditional proofs', ['d-cond', 'g-cond', 'd-cond2'].every((id) => /conditional on/i.test(record.initialCards[id] ?? '')), record.initialCards);

async function openSecondForm(label) {
  await expand('cynder-dark-past');
  await card('cynder-dark-past').locator('.tl-details__actions').getByRole('button', { name: 'Delete', exact: true }).click();
  const dialog = f.getByTestId('dialog-delete');
  await dialog.waitFor({ timeout: 10000 });
  const first = (await dialog.innerText()).replace(/\n+/g, ' | ');
  await dialog.getByRole('button', { name: 'Delete card and its Lean code' }).click();
  const ok = await waitFor(async () => (await f.getByTestId('delete-breaks-explanation').count()) > 0, 15000, `${label}: second form`);
  const info = ok
    ? await f.evaluate(() => {
        const d = document.querySelector('[data-testid="dialog-delete"]');
        return {
          title: d?.querySelector('h2')?.textContent ?? null,
          explanation: d?.querySelector('[data-testid="delete-breaks-explanation"]')?.textContent ?? null,
          items: [...(d?.querySelectorAll('[data-testid="delete-breaks"] li') ?? [])].map((li) => li.textContent),
          code: [...(d?.querySelectorAll('[data-testid="delete-breaks"] code') ?? [])].map((c) => c.textContent),
          buttons: [...(d?.querySelectorAll('button') ?? [])].map((b) => b.textContent),
          focused: document.activeElement?.textContent ?? null,
          notes: [...(d?.querySelectorAll('.tl-dialog__note') ?? [])].map((n) => n.textContent),
        };
      })
    : null;
  return { first, ok, info, dialog };
}

// ---------------------------------------------------------------------------------------------- B: Cancel
try {
  log('--- B: second form, Cancel');
  await dismissToasts();
  const { first, ok, info, dialog } = await openSecondForm('B');
  record.B = { first, info };
  log('B first form:', JSON.stringify(first));
  log('B second form:', JSON.stringify(info));
