 91	  record(writes: ReadonlyArray<{ absPath: string; text: string | null }>): void {
 92	    for (const path of [...this.entries.keys()]) this.fresh(path); // drop expired texts of other files too
 93	    const until = this.now() + this.ttlMs;
 94	    for (const write of writes) {
 95	      const entry = this.fresh(write.absPath) ?? { texts: [], floor: { editor: 0, disk: 0 } };
