 99	  }
100	
101	  isEcho(absPath: string, text: string | null, stream: EchoStream = 'editor'): boolean {
102	    const entry = this.fresh(absPath);
103	    if (!entry) return false;
104	    const match = entry.texts.find((t) => t.seq >= entry.floor[stream] && t.text === text);
105	    if (match) {
106	      entry.floor[stream] = match.seq;
107	      return true;
108	    }
109	    entry.floor[stream] = this.seq + 1;
110	    return false;
111	  }
112	
113	  /** Whether a fresh write to `absPath` is recorded that `stream` could still echo (before reading the file). */
114	  has(absPath: string, stream: EchoStream = 'disk'): boolean {
115	    const entry = this.fresh(absPath);
116	    return entry !== undefined && entry.texts.some((t) => t.seq >= entry.floor[stream]);
117	  }
118	
119	  /** The path's record without its expired texts (removed when none is left). */
120	  private fresh(absPath: string): PathRecord | undefined {
121	    const entry = this.entries.get(absPath);
122	    if (!entry) return undefined;
123	    const now = this.now();
124	    entry.texts = entry.texts.filter((t) => t.until >= now);
125	    if (entry.texts.length > 0) return entry;
126	    this.entries.delete(absPath);
127	    return undefined;
128	  }
